pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are small but nonzero are "dead"
    // (unlikely to fit future items, whose sizes are >= 1 but often large).
    if post_residual > 0 && post_residual < 20 {
        score += 30.0 * (20.0 - post_residual as f64);
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness;

    // Open-bin pressure: discourage spreading into many bins unless the fit is good.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to mean residual of open bins (i.e., poor fits everywhere).
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size as f64 > mean_residual {
            score -= 55.0;
        }
        // Late in the stream, opening new bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: dead space confirmed.
        score += 15.0;
    }

    // Deviation from mean residual: prefer bins with less residual than average
    // (consolidate fullness) but avoid near-empty bins.
    score += 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that cannot fit the average upcoming item.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 18.0 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving space the lookahead item could use later.
            score -= 6.0 * ((post_residual - next_item_size) as f64).min(30.0);
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * (1.0 - progress);
    }

    // New-bin candidate handling: penalize opening a new bin, more so early in
    // the stream and when many open bins still have room.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 40.0 + 25.0 * (1.0 - progress) + 10.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 12.0; // keep fresh bins for bigger upcoming items
        }
    } else {
        // Mildly reward using bins that are already fragmented.
        let frag = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * frag;
    }

    // Prefer balancing residuals toward the mean across open bins.
    score += 0.03 * (post_residual as f64 - mean_residual).abs();

    // Encourage consolidation when many bins are open.
    score += 0.2 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    // Base: prefer small post-residual, with smooth non-linear polynomial coupling
    let mut score = post_norm * (1.0 + 2.0 * post_norm * post_norm);

    // Tight-fit reward: smooth bell around exact fit, scaled by stream progress
    let tightness = 1.0 - post_norm;
    score -= tightness * tightness * (1.0 + progress);

    // Penalize leaving residuals that are too small to be useful later
    // (smooth penalty via cubic in post_norm, stronger late in stream)
    let dead = (0.3 - post_norm).max(0.0) / 0.3;
    score += dead * dead * (1.0 + 2.0 * progress) * 5.0;

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let pair_waste = (post_residual - next_item_size) as f64 / cap;
            score -= (1.0 - pair_waste) * 3.0;
        } else {
            // penalize residuals that block the next item proportionally to overlap
            let overlap = (nxt - post) / cap;
            score += overlap * overlap * 4.0;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0 * (0.5 + progress);
    }

    // Mild penalty for spreading across many open bins vs consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 0.15 * post_norm;

    // Prefer bins whose residual deviates from the mean in a useful (smaller) direction
    let mean_norm = mean_residual / cap;
    score += (mean_norm - post_norm) * 1.5;

    // Slight bias toward opening a new bin early (when many bins fit) vs late
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 1.0 - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let post = post_residual as f64;
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post) * 12.0; // dead space of 1..10 is worse than large leftovers
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit strongly rewarded
    } else {
        // fractional fill quality: prefer bins where item fills a large share of residual
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 10.0;
    }

    // Open-bins pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (item large relative to mean residual) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 25.0 + mean_residual * 0.3 - progress * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity && next_item_size as f64 > mean_residual {
            score -= 10.0; // new bin can host the next item too
        }
        if item_size as f64 >= mean_residual {
            score -= 15.0; // open bins are too full for this item anyway
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit: perfect closure, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity fractions.
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Dead-space penalty: residuals that are tiny but nonzero are wasted.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - pr) / 10.0;
    }

    // Residuals in (10, 25] are semi-usable for small items; mild penalty.
    if post_residual > 10 && post_residual <= 25 {
        score += 15.0;
    }

    // Integer-division thresholds: how many "eighth-slots" remain.
    let slots = post_residual / 12; // ~eighth of capacity
    score -= (slots as f64) * 4.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Reward tight packing with lookahead; penalize if gap is dead space.
            if gap <= 10.0 {
                score -= 120.0 - gap * 4.0;
            } else {
                score += gap * 0.3;
            }
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: make empty bin attractive only when open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64;
        let mean_fit_gap = (mean_residual - item_size as f64).abs();
        // Prefer new bin when open-bin residuals are poorly matched to item.
        score = cap - 40.0 + mean_fit_gap * 0.5 - congestion * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 50.0; // new bin can host item + next item comfortably
        }
    }

    // Mild progression term: later in stream, prefer tighter closures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0;

    // Coupling with mean residual: bins far below mean residual are "dusty" — deprioritize slightly.
    score += (mean_residual - pr).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small dead space (unusable slivers) non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual (chained packing).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if nx <= pr {
            // Chain bonus proportional to how snugly the next item fits.
            let slack_after_next = pr - nx;
            score -= 40.0 - slack_after_next.min(40.0);
            if slack_after_next == 0.0 {
                score -= 200.0; // exact 2-item chain completion
            }
        } else {
            // Dead-end residual: penalize proportionally to how much the next item overflows.
            let overflow = nx - pr;
            score += overflow.min(80.0) * 0.8;
        }
    }

    // Compare residual against mean residual: prefer bins that become tighter than average.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when it creates a clean large residual
    // for a large next item, or when open bins are numerous/fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        let fragmentation = mean_residual / bin_capacity as f64;
        let new_bin_bonus = 30.0
            + (next_item_size as f64) * 0.6
            + fragmentation * 50.0
            + progress * 20.0
            + (open_bins_count as f64) * 2.0;
        score = 100.0 - new_bin_bonus + post_residual as f64 * 0.3;
        // Discard new bin if current placement would be a perfect fit elsewhere.
        if post_residual == bin_capacity - item_size && item_size > 0 && bin_residual - item_size == 0 {
            score += 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit even the smallest
    // future item (assume min size ~10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 12.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // and penalize opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 + progress) * 0.8;

    // Prefer bins whose residual is already below mean (consolidate waste).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // next item cannot use the leftover gap -> dead space penalty
            score += 6.0;
        }
    }

    // New-bin candidate: only attractive when current bin fit is poor
    // (large post_residual) or item nearly fills a fresh bin.
    if bin_residual == bin_capacity {
        // baseline for fresh bin: small, so it loses only against bad fits
        score = 5.0 + (100 - item_size.min(100)) as f64 * 0.5;
        if fitting_bins_count <= 1 {
            score -= 20.0; // nothing else fits well -> new bin is fine
        }
        if item_size >= 90 {
            score -= 25.0; // big item: fresh bin is excellent
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;
    let mean = mean_residual.max(0.0);

    let denom = if total_items == 0 { 1.0 } else { total_items as f64 };
    let progress = (step_index as f64 / denom).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;
    let max_post = (cap - item).max(0.0);

    let mut score = post;

    if post <= 0.0 {
        score -= 5.0 + 0.05 * open + 2.5 * progress;
    }

    if next > 0.0 && post > 0.0 && post < next {
        let gap_ratio = ((next - post) / next).clamp(0.0, 1.0);
        let open_fragmentation = 1.0 + open / (2.0 + fitting);
        let mut dead_penalty = gap_ratio * gap_ratio
            * (0.85 * cap + 0.15 * item)
            * open_fragmentation
            * (0.55 + 0.75 * progress);

        if next > max_post {
            dead_penalty *= 0.35;
        }

        score += dead_penalty;
    } else if next > 0.0 && post >= next {
        let inv_cap = if cap > 0.0 { 1.0 / cap } else { 0.0 };
        let slack_after_next = post - next;
        let tightness = (1.0 - slack_after_next * inv_cap).clamp(0.0, 1.0);
        score -= (1.0 + 2.5 * tightness) * (0.5 + 0.5 * progress);
    }

    if is_new_bin {
        let mut new_bin_penalty = 2.5 + 0.22 * open + 0.05 * mean + 3.0 * progress;

        if fitting > 0.0 {
            new_bin_penalty += 1.5 + 0.08 * open;
            if fitting <= 1.0 {
                new_bin_penalty += 2.5;
            }
        }

        score += new_bin_penalty;
    } else {
        score -= 0.015 * open * (0.5 + 0.5 * progress);

        if fitting <= 1.0 {
            score -= 1.5 + 0.05 * open + 1.5 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: post_residual that cannot fit typical small items (1..=10).
        if post_residual < 10 {
            score += 60.0;
        }
        // Harmonic classes: quantize post_residual into eighths of capacity.
        let class = (post_residual * 8 / bin_capacity) as f64;
        score += class * 3.0;

        // Integer division thresholds: prefer post_residual divisible by small harmonics
        // (post_residual % 5 == 0 or % 10 == 0 leaves friendly gaps).
        if post_residual % 10 == 0 {
            score -= 6.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 400.0;
        } else {
            score -= (next_item_size as f64) * 1.5;
            if next_post < 10 {
                score += 25.0;
            }
        }
    } else if next_item_size > 0 {
        // Next item cannot use the gap: penalize large leftover gaps more.
        score += post * 0.4;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: keep it neutral-ish unless open bins are fragmented.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when mean residual of open bins is small
        // (existing bins nearly full) or few bins can fit.
        score -= (fitting_bins_count as f64) * 8.0;
        score += (mean_residual / cap) * 40.0;
        // Slight preference for reusing bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 20.0;
    }

    // Mild preference to fill bins with larger residuals when many bins open.
    score -= (bin_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 11.0);
    }
    // Medium gaps (11..=30) are also poor: few future items fit them.
    if post_residual > 10 && post_residual <= 30 {
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 21.0);
    }

    // Reward tight fits strongly (post_residual near zero but not dead-space zone).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual >= 31 && post_residual <= 60 {
        score -= 20.0; // flexible gap, good placement
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 50.0;
        } else if slack <= 10 {
            score += 15.0; // next item creates dead space, discourage
        } else {
            score -= 10.0;
        }
    }

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but reward using the last fitting bin (avoid opening a new bin).
    score += (open_bins_count as f64) * 0.8;
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: neutralize base residual so an empty bin scores
    // as a modest constant, only winning when all open bins are bad fits.
    if bin_residual == bin_capacity {
        score = 20.0 + (open_bins_count as f64) * 0.5
            - if fitting_bins_count == 0 { 40.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits snugly in the post residual.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit here: penalize proportionally to wasted lookahead.
    else if next_item_size > post_residual && next_item_size > 0 {
        score += 15.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Penalize unusable dead space (small residuals likely wasted).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits relative to current bin residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Relative to mean residual: bins with less residual than average are scarcer;
    // using them for a loose fit is worse.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if existing bins give a poor fit
    // (large post_residual means bad packing) or many bins are already open.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = (post_residual as f64 / bin_capacity as f64) * 40.0;
        score += 10.0 + poor_fit_penalty - 1.5 * open_bins_count as f64;
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // last-chance bin with good lookahead match beats a new bin
        }
    }

    // Early in stream: keep things flexible, mildly discourage fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // in [0, 1]

    // Class the post residual into harmonic bins (modulo-style classes of 10 units).
    let class = post_residual / 10; // 0..10 integer class
    let class_center = (class * 10 + 5) as f64;

    // Penalize residuals that fall into "unusable" classes: small but nonzero dead space.
    // Dead space in (0, 10) is nearly unusable for items >= 1..100 unknown distribution.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Harmonic penalty: distance from class center, scaled by class.
        let dist = (post_f - class_center).abs();
        score += 0.15 * dist;
        // Quadratic coupling on fraction of capacity wasted.
        score += 30.0 * frac * frac;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain placement possible. Reward proportionally to tightness of chain fit.
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / cap_f;
            score -= 20.0 * chain_tightness;
        } else {
            // Next item won't fit here; penalize more if the leftover is small dead space.
            let waste = post_residual as f64;
            score += 0.1 * waste;
        }
    } else {
        // Last item: prefer zero residual.
        score -= 10.0 * (1.0 - frac);
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // offers a good fit. Give the empty bin a baseline near its residual (capacity),
    // adjusted by stream progression and congestion.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: capacity minus item fills a bit.
        score = cap_f * 0.9;
        // Early in stream or many open bins: opening is cheaper (spread load).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // If existing bins are congested (low mean residual), opening is better.
        score -= 0.5 * (cap_f - mean_residual).max(0.0);
        // If item is large relative to capacity, opening a fresh bin is natural.
        score -= 0.2 * item_size as f64;
        // If next item is large too, a fresh bin can host the pair.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
    } else {
        // Existing bin: reward tightness relative to current residual.
        let fit_tightness = 1.0 - (post_f / (bin_residual as f64).max(1.0));
        score -= 10.0 * fit_tightness;
        // Slight penalty for spreading across too many bins.
        score += 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0,10) is nearly unusable
    // (items >= 10), so penalize small positive residuals heavily.
    if post_residual > 0 {
        let cls = post_residual % 10; // harmonic sub-class within each decade
        if cls > 0 && post_residual < 10 {
            score += 60.0; // tiny dead space, worst outcome
        } else if post_residual < 10 {
            score += 40.0;
        } else if post_residual < 20 {
            score += 12.0;
        } else if post_residual < 30 {
            score += 4.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            // partial usability of the leftover
            let usable = post_residual - next_item_size;
            score -= (usable as f64).min(30.0);
        } else {
            // next item cannot use the residual: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, mild penalty for wasting a large residual.
        score += (post_residual as f64) * 0.1;
    }

    // New-bin candidate: only attractive when open bins are nearly full
    // (mean residual low) or the item fits nothing well.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 0.15 {
            score -= 30.0; // open bins nearly exhausted, fresh bin is fine
        } else {
            score += 55.0 + pressure * 40.0; // discourage wasting fresh capacity
        }
    }

    // Progress factor: late in the stream, prefer closing bins tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Tie-break: prefer bins with residual close to a multiple of 10
    // (harmonic alignment leaves reusable chunks).
    let align = (post_residual % 10) as f64;
    score -= (5.0 - (align - 5.0).abs()) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "dead space": small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 2.0; // tiny gaps are worst
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Pressure from number of open bins: prefer filling existing bins
    // when many are open; allow opening new bins when few are open.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += pressure;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        score += 8.0; // dead space relative to lookahead
    }

    // Mean residual coupling: bins far below mean residual are less attractive
    // (keeps residual distribution tight for future items).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // New-bin candidate handling: empty bin gets a moderate default score,
    // beaten by good fits but beating poor fits into nearly-full bins.
    if bin_residual == bin_capacity {
        score = 35.0 + pressure - (item_size as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let pre = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let item = item_size as f64;
    let open = open_bins_count as f64;
    let fit = fitting_bins_count as f64;

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = open.min(80.0);
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post + 0.03 * (post - mean_residual).max(0.0);

    // Perfect closure is the best possible dead-space outcome.
    if post == 0.0 {
        score -= 3.0 + 3.0 * progress;
    }

    // Penalize a nonzero leftover that is already known to be too small
    // for the lookahead item.
    let dead_gap = if next > 0.0 && post > 0.0 && post < next {
        next - post
    } else {
        0.0
    };

    if dead_gap > 0.0 {
        score += 5.0 + dead_gap * (1.2 + 1.6 * progress + 0.025 * open_pressure);

        // If this existing bin could have served the next item before insertion,
        // using it for the current item destroys that opportunity.
        if !is_new_bin && pre >= next {
            score += 3.0 + 5.0 * progress;
        }
    }

    if is_new_bin {
        // Opening a new bin is costly, especially late in the stream and when
        // many bins are already open.
        score += 4.0 + 4.0 * progress + 0.075 * open_pressure;

        // Do not bypass the last existing fitting bin unless the dead-space
        // penalty is truly severe.
        if fit <= 1.0 {
            score += 6.0 + 4.0 * progress;
        }

        if next > 0.0 {
            if post >= next {
                // A new bin that can also absorb the lookahead item is mildly attractive.
                score -= 1.0 + 2.0 * (next / cap);
            } else if mean_residual < next {
                // The new bin cannot take the next item, and the average open pool
                // probably cannot either.
                score += 2.0;
            }
        }
    } else {
        // Mild pressure toward consolidating into existing bins.
        score -= 0.01 * open_pressure;

        // Strongly favor the last existing bin that can fit the item.
        if fit <= 1.0 {
            score -= 7.0 + 5.0 * progress + 0.02 * open_pressure;
        }

        // Reward leaving enough room for the lookahead item.
        if next > 0.0 && post >= next {
            score -= 0.8 + 1.5 * (next / cap);
        }

        // Crumb guard: very small leftovers are treated as risky dead space.
        let crumb_floor = 0.08 * item;
        if post > 0.0 && post < crumb_floor {
            score += 0.8 + 0.05 * (crumb_floor - post);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible future item are "dead space" -> heavy penalty.
    if post_residual > 0 {
        let dead = (post_residual < 10) || (next_item_size > 0 && post_residual < next_item_size);
        if dead {
            score += 40.0 + 0.6 * post_residual as f64;
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward residuals that exactly accommodate the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    score += 0.15 * open_bins_count as f64;

    // Penalize bins whose residual is far from the mean residual (fragmentation).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Early in the stream, be more willing to open fresh bins (score new bin better);
    // late in the stream, squeeze existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 8.0;

    // New-bin candidate: empty bin has residual == capacity. Make it moderately
    // attractive only when the item is large relative to capacity or when no
    // existing bin fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score = 50.0 - 30.0 * large_item;
        if fitting_bins_count == 0 {
            score -= 45.0; // must open a new bin anyway
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // new bin can also host the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly fit the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // chain fit possible, mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize dead space below next item size
            score += 60.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual across open bins
    score -= 0.5 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New empty bin candidate: penalize unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 200.0 * (1.0 - tightness);
    }

    // Late in the stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 40.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 10) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with
    // few open bins, opening a new one is cheap so a poor fit is avoided.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + 8.0 * progress);
    score += 2.5 * pressure;

    // If this bin's residual is far above the mean, it is roomy; mildly
    // prefer saving roomy bins for big future items.
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Lookahead: if the next item fits exactly in the post-residual, keep
    // this bin attractive; if next item would not fit, residual is dead.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // New-bin candidate: baseline attractiveness so it wins only when all
    // open bins are poor fits.
    if bin_residual == bin_capacity {
        score = 45.0 + 2.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..100 range,
    // but typical min ~10) can use are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 15 {
        score -= 8.0; // small-but-recoverable gap is actually useful
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 25.0 * (1.0 - tightness.min(1.0));

    // Exact fit: perfect packing.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize waste proportional to bin capacity usage imbalance.
    score += 0.15 * (bin_capacity as f64 - bin_residual as f64);

    // Open bins pressure: discourage proliferation of many open bins
    // unless the fit is excellent.
    score += 0.5 * open_bins_count as f64 * (1.0 + tightness);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate logic: an empty bin is only attractive when the
    // current item would leave a large dead gap in any existing bin,
    // or when open bins are numerous and fragmented.
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual > 0 && post_residual < 10 { 0.0 } else { 30.0 };
        score = 45.0 + 0.4 * open_bins_count as f64 - gap_penalty
            - 10.0 * (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        if next_item_size > 0 && next_item_size as f64 >= post_residual as f64 {
            // lookahead item would not fit in the fresh bin either; less useful
            score += 15.0;
        }
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            // fresh bin pairs perfectly with the next item
            score -= 35.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this placement (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 0.3 * (next_item_size as f64 / post_residual.max(1) as f64);
    }

    // Mild stream-progress adaptation: later in the stream, be more conservative
    // about opening bins (consolidation phase).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (-gap / 20.0).exp();
        // Exact match for the next item is excellent
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual too small for next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (post_residual as f64);
        }
    }

    // Compare against mean residual: prefer bins that are already below-average filled
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 45.0;
        // Opening fresh is good if the item is huge and lookahead is large
        if item_size > 70 && next_item_size > 60 {
            score -= 55.0;
        }
        // Fewer open bins -> cheaper to open new
        score -= 2.0 * open_bins_count as f64;
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // granularity (e.g. 10) are more reusable than prime-like leftovers.
    let r = post_residual;
    if r > 0 {
        let harmony = if r % 10 == 0 {
            -14.0
        } else if r % 5 == 0 {
            -7.0
        } else if r % 2 == 0 {
            -3.0
        } else {
            4.0
        };
        score += harmony;
    }

    // Dead-space penalty: tiny residuals are nearly unusable.
    if r < 10 && r > 0 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if r == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // Prefer residuals that can host the next item, especially near-exact.
            let slack = (r - next_item_size) as f64;
            score -= 12.0 - slack * 0.08;
            if (r - next_item_size) % 10 == 0 {
                score -= 5.0; // harmonic chaining
            }
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Capacity-fraction thresholds on the item's class.
    let item_frac = item_size as f64 / bin_capacity as f64;
    if item_frac > 0.5 {
        // Big items: prefer fresher bins (large residual) to avoid fragmentation.
        score += (bin_residual as f64 - item_size as f64) * 0.05;
    } else if item_frac < 0.2 {
        // Tiny items: prefer bins with small residuals to consolidate.
        score += (post_residual as f64) * 0.15;
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline: opening a new bin should cost roughly the wasted capacity
        // it incurs relative to packing into an existing bin.
        score = bin_capacity as f64 * 0.62;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        } else if next_item_size > 0 && next_item_size > mean_residual {
            // Next item is large: a fresh bin may serve it better.
            score -= 10.0;
        }
        // Fewer open bins early in the stream -> cheaper to open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0 - open_bins_count as f64 * 0.5;
    }

    // Mild tie-break toward bins below the mean residual (consolidation).
    if !is_new_bin {
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<10) are almost unusable later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bin would leave bad dead space
    // or open bins are numerous (pressure to consolidate).
    if bin_residual == bin_capacity {
        let dead_space_penalty = if post_residual > 0 && post_residual < 10 { 30.0 } else { 0.0 };
        score += 15.0 + dead_space_penalty - 0.5 * open_bins_count as f64;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones.
    score += 0.3 * open_bins_count as f64 * (1.0 - tightness);

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 { score -= 20.0; } else { score -= 5.0; }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.2 * (mean_residual - post_residual as f64);

    // Late in stream: be more conservative, avoid creating small gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: a leftover gap that cannot hold the next
    // item is wasted capacity. Penalize it quadratically, scaled by how
    // "close" it is to being useful (small unusable gaps are worst).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 4.0 + waste * waste * 0.15;
    }

    // Perfect fit reward: nothing left over at all.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: with many bins open, discourage spreading items
    // across bins; consolidate into already-open bins.
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate handling: an empty bin gets a base penalty so we
    // only open a new bin when the current fit is genuinely poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, new bins are even less attractive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 6.0;
    }

    // Mild best-fit refinement: prefer bins whose residual is tight
    // relative to the mean residual across open bins.
    score += (bin_residual as f64 - mean_residual) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: punish gaps that are too small to hold
    // any plausible future item (below the minimum item size of 1, but
    // practically below a useful threshold ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    } else if post_residual < 25 {
        // Moderate dead-space penalty with quadratic coupling.
        score += (25.0 - post_residual as f64) * (25.0 - post_residual as f64) * 0.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Exact fit for the lookahead item: very desirable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    }
    // Lookahead fits comfortably: mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead won't fit here: penalize to prefer bins where it can.
        score += 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // open_bins_count is high, encouraging consolidation.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make it unattractive unless residual is very tight
    // elsewhere; slight bonus early in the stream.
    if bin_residual == bin_capacity {
        score += 120.0 - (step_index as f64 / total_items.max(1) as f64) * 60.0;
    }

    // Prefer bins below mean residual (tighter bins) mildly.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Prefer bins whose residual was already small (tight packing).
    score += 0.4 * (bin_residual as f64 - item_size as f64 - post_residual as f64);

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item would leave a large gap elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 - item_size as f64 + 30.0 + 0.5 * open_bins_count as f64;
        // If no existing bin fits, new bin is the only option: make it cheap.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Lookahead: if next item is large, a fresh bin is more valuable.
        if next_item_size > 60 {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that cannot host the next item: extra penalty.
        score += 15.0;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: quadratic penalty on post residual (favor tight fits)
    let mut score = norm_post * norm_post * cap;

    // Non-linear coupling: post residual weighted by stream progress
    score += norm_post * (0.5 + progress * (1.0 - progress) * 4.0) * 10.0;

    // Smooth interaction: post residual vs mean residual (avoid bins far from mean)
    let dev = (post - mean_residual) / cap;
    score += dev * dev * cap * (0.3 + 0.7 * progress);

    // Last-chance bonus: strong smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_post * norm_post);
    }

    // Lookahead coupling: penalize post residual that wastes space needed by next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (nx - post).max(0.0) / cap;
        score += waste * waste * cap * 8.0;
        // reward leaving post residual close to next item size (smooth kernel)
        let gap = (post - nx) / cap;
        score -= (-gap * gap * 40.0).exp() * 12.0;
    }

    // New-bin candidate: prefer opening new bin when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        score -= 6.0 + 30.0 * (1.0 - crowding) * progress;
        score -= 10.0 * (norm_post * 0.0 + 1.0); // constant advantage baseline
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored: reward small post_residual non-linearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score -= (1.0 - pr / cap).powi(3) * 30.0;

    // Penalize dead space that no plausible future item can use.
    if pr > 0.0 && pr < 10.0 {
        score += 25.0; // tiny unusable sliver
    }
    if next_item_size > 0 && (next_item_size as f64) > pr {
        // Post-residual cannot host the next item: penalize proportionally.
        score += ((next_item_size as f64 - pr) / cap) * 20.0;
    } else if next_item_size > 0 {
        // Perfect or near-perfect lookahead fit: strong reward.
        let gap = (pr - next_item_size as f64) / cap;
        score -= (1.0 - gap).powi(2) * 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins relative to the average residual of open bins.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += dev * 15.0; // below-mean residual (fuller bin) lowers score
    }

    // New-bin candidate handling: only attractive early in the stream or
    // when the item fits badly everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = pr > 40.0; // large hole left behind
        let many_open = open_bins_count as f64;
        score += 10.0 + progress * 30.0 - many_open * 0.5;
        if bad_fit { score -= 5.0; } // opening a bin beats wrecking an open one
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 8.0; // fresh bin can also serve the next item
        }
    }

    // Mild preference to consolidate into bins that are already partially full
    // as the stream matures (reduce open-bin sprawl).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / cap) * (5.0 + 10.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in the post residual,
    // this placement is highly desirable
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits: penalize proportional to wasted space after both items
            let two_step_waste = post_residual - next_item_size;
            score -= 200.0 - 2.0 * two_step_waste as f64;
        } else {
            // Next item does NOT fit after this placement: penalize
            let overshoot = (next_item_size - post_residual) as f64;
            score += 50.0 + overshoot * 0.5;
        }

        // Bonus if the pair (item, next) nearly fills the bin
        let pair_fill = (item_size + next_item_size) as f64;
        if pair_fill >= bin_capacity as f64 * 0.95 && item_size + next_item_size <= bin_capacity {
            score -= 400.0;
        }
    }

    // Compare against mean residual: bins with less residual than average are
    // "tighter" and better candidates for closing out
    let res_diff = post_residual as f64 - mean_residual;
    score += res_diff * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize creating large dead space relative to typical small item sizes
    if post_residual > 0 && post_residual < 10 {
        score -= 80.0; // tiny unusable slivers are actually good (bin nearly closed)
    }
    if post_residual > 50 {
        // leaving a large residual is fine only for a fresh bin
        if bin_residual == bin_capacity {
            score -= 20.0; // slight encouragement to open new bin when fits are poor
        } else {
            score += 30.0;
        }
    }

    // Late in the stream, prefer consolidating (fewer open bins)
    if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 150.0 / (post_residual as f64).sqrt();
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining: next item fits exactly into the leftover.
            if post_residual == next_item_size {
                score -= 400.0;
            } else {
                // Partial reward scaled by how well the next item fills the residual.
                let fill_ratio = next_item_size as f64 / post_residual as f64;
                score -= 200.0 * fill_ratio;
            }
        } else {
            // Penalize leftovers that the next item cannot use (potential dead space),
            // unless the leftover is tiny (still a good fit for the current item).
            let waste = next_item_size - post_residual;
            score += 0.35 * waste as f64;
        }
    }

    // Relative to mean residual: prefer bins that are already more loaded than average
    // (tight packing) when they still fit well.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 30.0 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Slight preference for consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate (empty bin): penalize mildly so it is only chosen when
    // no open bin offers a decent fit or a strong lookahead chain.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Allow new bin if the lookahead chain is perfect from a fresh bin.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps that no future item (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < next_item_size as f64 * 1.0 && next_item_size > 0 {
        // Gap unusable by the lookahead item: penalize proportionally.
        score += 50.0 + (next_item_size as f64 - post_residual as f64) * 2.0;
    }

    // Reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Last-chance bonus: only one bin fits the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Lookahead synergy: if next item fits exactly in the post-residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but ease off near the end of the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 - mean_residual / 10.0) * (1.0 - 0.5 * progress);

    // New-bin candidate: neutral-ish baseline so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 40.0 - mean_residual * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let tightness = (post_residual - next_item_size) as f64;
            score -= 300.0 - 2.0 * tightness;
        } else {
            // penalize dead space relative to next item
            score += 50.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer tighter fits relative to mean residual
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize opening new bins when open bins exist, unless residual is small
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0 - 80.0 * progress;
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 60.0; // fresh bin good for pairing
        }
    }

    // Mild penalty for leaving awkward small residuals (unusable gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are "dead".
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Unusable for the lookahead item: harsh penalty scaled by how close
            // the dead gap is to being useful (wasting a nearly-fitting gap is worse).
            let gap_deficit = (next_item_size - post_residual) as f64;
            score += 40.0 + 2.0 * gap_deficit;
        } else {
            // Usable gap for the next item: reward proportionally.
            score -= 6.0 + 0.05 * next_item_size as f64;
        }
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Zero residual is perfect: extra reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading onto new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 8.0 + pressure;
    } else {
        // Slight reward for reusing existing bins, scaled by open-bin count.
        score -= 1.0 + 0.2 * pressure;
