    // Mild preference for bins whose residual is close to the mean (balance residuals),
    // keeping many medium gaps rather than one huge gap.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.3;

    // Early in the stream, be more tolerant of opening bins; later, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 10.0 * (bin_residual == bin_capacity) as i32 as f64;
    score += progress * 15.0 * (post_residual > 50) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain: bin becomes exactly full next step
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how snugly it fits
            score -= 40.0 * (nxt / (post + 1.0));
        } else {
            // next item does NOT fit: penalize dead space that blocks the lookahead
            score += 25.0 * (1.0 - post / (nxt + 1.0));
        }
        // extra bonus when the chain leaves a tiny unusable gap vs a useful one
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0; // tiny dead space below min item size is worthless
        }
    }

    // Prefer bins whose residual is below mean (consolidate waste), penalize above-mean residuals
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64;
        score += 10.0 + 2.0 * crowded; // default penalty for opening a new bin
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 20.0; // open a fresh bin when open residuals can't host the next item
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits: new bin is mandatory
        }
    }

    // Mild pressure to fill bins tightly as the stream progresses
    score -= 0.05 * (bin_capacity - post_residual) as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 40.0;
    }

    // Penalize large dead space left behind relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * dead * dead;

    // Lookahead: reward if next item fits into post_residual (good chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a gap the next item cannot use.
            score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a decent fit, or the stream is early and bins are scarce.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_cost = 35.0;
        // Early in the stream with few bins: cheaper to open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_cost -= 25.0 * (1.0 - progress) * (1.0 - (open_bins_count as f64 / 20.0).min(1.0));
        // If many bins fit the item, opening a new bin is wasteful.
        new_bin_cost += 8.0 * fitting_bins_count as f64;
        // If the item is large and fits nowhere well, new bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count == 0 {
            new_bin_cost -= 30.0;
        }
        // If mean residual is high, prefer reusing existing bins.
        new_bin_cost += 0.3 * mean_residual;
        score += new_bin_cost;
    }

    // Mild global pressure: when many open bins exist, discourage sloppy fits
    // that fragment space; reward using bins with above-average residual.
    if bin_residual < bin_capacity {
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
        score += 0.02 * open_bins_count as f64 * dead;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post-residual (dead space), slightly convex
    let mut score = norm_pr * norm_pr * 60.0 + norm_pr * 40.0;

    // Smooth non-linear coupling with stream progress:
    // early on, prefer tight fits mildly; later, dead space matters more (waste compounds)
    let progress_coupling = (norm_pr * norm_pr) * (progress * progress * 80.0 + 20.0);
    score += progress_coupling;

    // Reward filling bins nearly exactly, scaled smoothly by progress
    let fill_ratio = item_size as f64 / cap;
    score -= fill_ratio * fill_ratio * (30.0 + 40.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 35.0 * progress;
    }

    // Many open bins: slight penalty to discourage proliferation, smooth in count
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += open_norm * norm_pr * 30.0;

    // Lookahead: penalize leaving residual too small for the next item,
    // reward residuals that can still host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            // next item fits: reward proportionally to how well residual matches next size
            let slack = (pr - nxt) / cap;
            score -= 20.0 * (1.0 - slack * slack) * (0.5 + progress);
        } else {
            // next item won't fit: penalize proportionally to the shortfall
            let shortfall = (nxt - pr) / cap;
            score += 25.0 * shortfall * (0.5 + progress);
        }
    }

    // Deviation from mean residual: prefer bins whose residual differs from average
    // (keeps a diverse residual portfolio, smooth interaction)
    let dev = (pr - mean_residual) / cap;
    score -= 8.0 * dev * dev.abs();

    // Brand-new bin candidate: neutral-ish baseline; only attractive when
    // no open bin offers a tight fit (post_residual small)
    if bin_residual == bin_capacity {
        score = 55.0 + 45.0 * (1.0 - progress) + 10.0 * fill_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: classify leftover space into
    // capacity-fraction buckets. Leftovers in "nice" classes (fitting common
    // item sizes) are cheap; odd tiny leftovers are dead space.
    let c = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Class by integer division thresholds on post_residual.
    let class = pr / 10; // 0..10 harmonic classes
    match class {
        0 => score += 60.0,                 // 0-9: near-perfect fill, but tiny residue is dead space
        1 => score -= 25.0,                 // 10-19: fits smallest items, very reusable
        2 => score -= 20.0,                 // 20-29
        3 => score -= 15.0,                 // 30-39
        4 => score -= 10.0,                 // 40-49
        5 => score -= 5.0,                  // 50-59
        6 => score += 5.0,                  // 60-69: awkward class
        7 => score += 10.0,                 // 70-79
        8 => score += 15.0,                 // 80-89
        9 => score += 20.0,                 // 90-99: nearly empty bin
        _ => {}                             // full bin
    }

    // Modulo coupling: residues that are multiples of common item sizes are
    // more likely to be exactly filled later -> reward them.
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        else { score += 3.0; }
    }

    // Perfect fit: zero residual is ideal.
    if pr == 0 { score -= 100.0; }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            // prefer bins where next item leaves a "harmonic" residue again
            let nxt_class = (pr - next_item_size) / 10;
            let class_bonus = match nxt_class {
                0 => -20.0,
                1 => -14.0,
                2 => -10.0,
                3 => -6.0,
                4 => -3.0,
                _ => 0.0,
            };
            score += class_bonus + slack * 0.3;
        } else {
            // next item cannot follow into this bin -> mild penalty
            score += 10.0;
        }
        // reward when next item would also fit (chaining placements)
        let _ = nxt;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a mediocre reason.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins are mostly full or the item is huge and fits nowhere well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fullness = 1.0 - (mean_residual / c);
        // Penalize opening new bins early; relax later or when item is large.
        let item_frac = item_size as f64 / c;
        score += 55.0 - 40.0 * progress - 30.0 * fullness - 20.0 * item_frac;
    }

    // Tie-break toward consolidating: fewer open bins is better.
    score += open_bins_count as f64 * 0.5;

    // Mild pull toward mean residual: avoid extreme outliers.
    score += (prf - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual can still host the next item after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap just barely below the next item (wasted dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Open-bin pressure: discourage scattering across many bins unless the fit is tight.
    let pressure = (open_bins_count as f64).powf(1.2) * 0.15;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make a fresh bin attractive only when no open bin
    // offers a tight fit (large post_residual relative to capacity on open bins).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are already open
        // (item likely belongs in a fresh bin anyway).
        score = bin_capacity as f64 * 0.55 + 5.0 * (open_bins_count as f64).sqrt();
        if mean_residual < 15.0 {
            score -= 10.0; // existing bins are nearly full; new bin is fine
        }
        if next_item_size > 0 && bin_capacity >= next_item_size + item_size {
            score -= 5.0; // fresh bin has room for lookahead
        }
    }

    // Mild preference for filling fuller bins early vs late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff);
        // Penalize leaving space that is too small for the next item (dead space),
        // unless the bin is nearly full (post_residual very small).
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0;
        }
        // Small bonus if post_residual can still fit the next item comfortably.
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Reward bins with residuals near the mean (balanced usage), penalize outliers.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * mean_gap;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline; only attractive when existing bins
    // would create large dead space. Make empty-bin score track its full residual
    // with a mild penalty so tight fits in existing bins win.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in the stream, discourage proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Tight fit reward: small post_residual is good (already in base score),
        // add extra non-linear reward for very tight fits.
        score -= 10.0 * (-post_residual as f64 / 15.0).exp();
    }

    // Mild penalty for very tight fits when next item is large and would not fit
    // anywhere else afterwards (avoid stranding).
    if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    // Squared penalty for leaving awkward dead space.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    } else if fitting_bins_count >= 2 {
        // With multiple options, mildly prefer bins that are already committed.
        score -= 3.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item
    // (chain-friendly packing), penalize bins that waste space the next item needs.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else if post_residual > 0 {
            // Dead space that the next item cannot use.
            score += 0.10 * post_residual as f64;
        }
    }

    // Global state: when many bins are open relative to progress, discourage
    // opening new bins; the new-bin candidate has residual == capacity and high
    // post_residual, so extra weighting here pushes toward consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.02 * bin_pressure * (1.0 + progress);

    // Prefer bins already below mean residual (consolidating small leftovers)
    // vs. leaving large residuals scattered.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // New-bin candidate handling: empty bin should only win when all open bins
    // would leave large unusable residuals.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.15 * item_size as f64;
    }

    // Late-stream consolidation: as the stream ends, favor filling existing bins.
    score -= 8.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let t = progress;
    // quadratic-quadratic interaction: tight fits matter more early, waste matters more late
    let coupling = (prn * prn - prn) * (1.0 + t) + (prn * prn * prn) * t;
    score += 20.0 * coupling;

    // Reward near-perfect fits smoothly (low post residual), stronger as stream progresses
    let fit_quality = (1.0 - prn).powi(3);
    score -= 15.0 * fit_quality * (0.5 + t);

    // Lookahead: penalize residual that cannot hold the next item, smoothly
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 8.0 * (1.0 - slack * slack);
        } else {
            let miss = ((ni - pr) / cap).powi(2);
            score += 12.0 * miss;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.6 + 0.4 * t);
    }

    // Mild penalty when many bins are open and this bin is far from mean residual
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * (open_bins_count as f64).sqrt() / (1.0 + t);

    // New-bin candidate: baseline cost that rises slightly over the stream
    if bin_residual == bin_capacity {
        score += cap * (1.0 + 0.5 * t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual buckets of size 10 define
    // "usable slots" — a residual that is a multiple of common item sizes
    // is more likely to be filled later.
    let pr = post_residual;
    let bucket = pr / 10;
    // Reward residuals that fall on harmonic class boundaries (multiples of 10)
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    } else {
        score += (10 - (pr % 10)) as f64 * 0.4;
    }

    // Integer-division threshold: tiny residuals (< 10) are dead space.
    if pr < 10 {
        score += 15.0;
    } else if pr <= 20 {
        score += 4.0;
    }

    // Perfect fit is ideal.
    if pr == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: does the residual after placement match the next
    // item via harmonic classes (modulo 10 / integer division)?
    if next_item_size > 0 {
        let diff = pr as i64 - next_item_size as i64;
        if diff == 0 {
            score -= 30.0; // next item fills this bin exactly
        } else if diff > 0 && (diff as u32) % 10 == 0 {
            score -= 12.0; // next item leaves a harmonic residual
        } else if diff < 0 && (next_item_size as u32) <= bin_residual {
            score += 3.0; // next item won't fit here anyway; mild penalty
        }
        // Reward if residual bucket matches next item's size bucket
        if next_item_size / 10 == bucket && pr >= next_item_size {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit
    // here is poor (large post residual relative to capacity) or when many
    // bins are open and mean residual suggests fragmentation.
    if bin_residual == bin_capacity {
        let poor_fit = (pr as f64 / bin_capacity as f64) > 0.55;
        let fragmented = open_bins_count > 3 && mean_residual < 25.0;
        if poor_fit || fragmented {
            score -= 25.0;
        } else {
            score += 40.0; // prefer existing bins when fit is decent
        }
    }

    // Progress-based tie-breaking: late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - pr as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
