    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate (bin_residual == bin_capacity) gets a natural
    // high post_residual, so add extra penalty proportional to open bins.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    }

    // Mild coupling with mean residual: prefer bins whose residual is below
    // average (i.e., tighter bins) to consolidate packing.
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0);

    // Late in the stream, be more aggressive at filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits snugly in the post residual.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit here: penalize proportionally to wasted lookahead.
    else if next_item_size > post_residual && next_item_size > 0 {
        score += 15.0 + 0.25 * (next_item_size - post_residual) as f64;
    }

    // Penalize unusable dead space (small residuals likely wasted).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits relative to current bin residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fill_ratio;

    // Relative to mean residual: bins with less residual than average are scarcer;
    // using them for a loose fit is worse.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if existing bins give a poor fit
    // (large post_residual means bad packing) or many bins are already open.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = (post_residual as f64 / bin_capacity as f64) * 40.0;
        score += 10.0 + poor_fit_penalty - 1.5 * open_bins_count as f64;
        if fitting_bins_count == 1 && next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0; // last-chance bin with good lookahead match beats a new bin
        }
    }

    // Early in stream: keep things flexible, mildly discourage fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 45.0 * fit_ratio * fit_ratio;

    // Penalize large dead space left behind, weighted by how "wasted" it is.
    let waste = post_residual as f64;
    if waste > 0.0 {
        let small_leftover = (waste / bin_capacity as f64).powi(3);
        score += 30.0 * small_leftover;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 20.0 + 25.0 * chain_fit;
        } else {
            // Next item cannot follow here; slight penalty proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(40.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 40.0;
        // Cheaper to open new bins early in the stream (long horizon ahead).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        // More open bins with high mean residual -> prefer consolidating into existing bins.
        score += 0.8 * open_bins_count as f64;
        score += 0.5 * mean_residual;
        // If next item is small, a fresh bin gives it a clean home.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 12.0;
        }
        // If no existing bin fits well, opening a new bin is fine.
        if fit_ratio < 0.6 && bin_residual != bin_capacity {
            score -= 0.0; // unreachable guard, keeps structure clear
        }
        if fitting_bins_count > 0 && fit_ratio < 0.55 {
            score -= 18.0;
        }
    } else {
        // Existing bin: reward using bins that are already partially filled.
        let used = (bin_capacity - bin_residual) as f64;
        score -= 0.05 * used;
        // Slight preference to keep the number of open bins low.
        score += 0.3 * open_bins_count as f64;
    }

    // Mild exploration term: small deterministic perturbation from state variables.
    let phase = ((step_index as f64 * 0.37).sin() + (open_bins_count as f64 * 0.61).cos()) * 0.5;
    score += 1.5 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with quadratic penalty on waste.
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth non-linear coupling: waste matters more as the stream progresses.
    let coupling = norm_pr * (1.0 - norm_pr);
    score += 60.0 * coupling * progress * norm_pr;

    // Lookahead: reward bins whose residual can host the next item (smooth kernel).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = (pr - nx).abs();
        let kernel = (-fit_next / 25.0).exp();
        score -= 25.0 * kernel;
        // Penalize exact-tight fits that strand the next item slightly.
        if pr < nx {
            score += 15.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0 + 30.0 * (1.0 - norm_pr);
    }

    // Mild preference for bins below mean residual (consolidating space).
    score += 0.15 * (mean_residual - pr);

    // New-bin candidate: make it slightly unattractive unless residuals are all poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 40.0 * progress;
    }

    // Tie-break: fewer open bins favored slightly (encourages filling existing bins).
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let cap_quarter = bin_capacity / 4; // 25
    let cap_eighth = bin_capacity / 8;  // 12

    // Dead space penalty: post_residual in awkward "harmonic dead zones"
    // Residuals that are small but nonzero are hard to fill later.
    if post_residual > 0 && post_residual <= cap_eighth {
        score += 45.0 - 4.0 * post_residual as f64; // tiny slivers penalized
    }

    // Reward residuals that are harmonic multiples (divisible by 10 or 25):
    // these match typical item sizes and are reusable.
    if post_residual % 10 == 0 {
        score -= 12.0;
    }
    if post_residual % cap_quarter == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = post_residual - next_item_size;
        if next_fit_gap == 0 {
            score -= 200.0;
        } else if next_fit_gap % 10 == 0 {
            score -= 40.0;
        } else if next_fit_gap <= cap_eighth {
            score += 10.0; // would leave a sliver
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // post_residual can't host the next item: mild penalty scaled by sliver size
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a fresh bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no tight fit exists elsewhere. Baseline anchor so open bins win
    // when they provide decent fits.
    if bin_residual == bin_capacity {
        score += 70.0;
        if item_size >= 3 * bin_capacity / 4 {
            score -= 65.0; // big items justify a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Tight-fit reward: small post_residual relative to item is efficient packing.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 30.0;

    // Stream progression: early on, be pickier about dead space; later, prioritize closure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.15;
    score -= progress * 15.0 * fill_ratio;

    // Dispersion from mean residual: prefer bins below-average residual (tighter bins).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Treat gaps that can't fit even the smallest plausible item as dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Moderate dead space (small but potentially usable) gets a soft penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit bonus: strongly reward leaving exactly zero residual.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading items across new bins.
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure,
        // but relax the penalty when no open bin is a decent fit.
        score += 15.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else {
        // Existing bin: reward using it, more so under high pressure.
        score -= 6.0 * pressure;
        // Last-chance bonus: if this is the only fitting bin, avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Lookahead coupling: if the next item fits in the post-residual,
    // reward this placement for enabling a follow-up fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize if post-residual is large enough to be tempting but the
    // next item won't fit, creating likely stranded space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Mean-residual coupling: placing into a bin with residual far below
    // the mean helps balance residuals and reduce fragmentation.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Early-stream tiebreak: slightly prefer tighter fits early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for an exact two-step match: this bin absorbs the current
    // item AND the next item perfectly (post_residual == next_item_size).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Mild reward if the next item fits in the post-residual (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Penalize dead space: residuals too small for any plausible future item.
    if post_residual < 10 {
        score += 15.0;
    } else if post_residual < 25 {
        score += 5.0;
    }

    // Prefer bins that are tighter than the fleet average (good fits first).
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.3 * mean_gap;

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin; reward it strongly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a brand-new empty bin unless the fit in open bins is bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if the new bin would serve the next item exactly, allow it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Early in the stream, be slightly more willing to open bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward small relative post-residual (good fit).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post-residual too small to ever be useful.
    if post_residual > 0 && post_residual < 10 {
