    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Global state coupling: many open bins with slack -> prefer filling existing ones.
    if open_bins_count > 0 {
        score -= (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0) * 5.0;
    }

    // Time horizon: early in stream, prefer keeping residuals large (flexibility);
    // late in stream, squeeze tight fits harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.25 * progress;

    // New-bin candidate: make empty bin attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.55 || (next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10);
        if poor_fit {
            score -= 22.0;
        } else {
            score += 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = prn * (1.0 + 0.8 * progress + 1.2 * p2 + 0.5 * p3);
    score += 12.0 * coupling;

    // Penalize large dead space more aggressively as stream progresses
    score += 6.0 * prn * prn * (0.5 + progress);

    // Perfect fit reward (smooth)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio * fit_ratio * (1.0 - 0.3 * progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: reward residual that can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
