        }
    }

    // Mild pressure to prefer filling existing bins over opening new ones
    if bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mean residual deviation penalty
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction classes (eighths).
    let item_class = (item_size * 8 + bin_capacity - 1) / bin_capacity; // ceil(item/C*8), 1..8
    let next_class = if next_item_size == 0 {
        0
    } else {
        (next_item_size * 8 + bin_capacity - 1) / bin_capacity
    };

    // Reward tight fits: post_residual in a small harmonic class is good.
    let post_class = (post_residual * 8 + bin_capacity - 1) / bin_capacity;
    score -= (bin_capacity as f64 / (post_residual as f64 + 1.0)) * 2.0;

