    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Next item fits exactly into post_residual class (integer division threshold).
    if next_item_size > 0 && next_item_size <= post_residual {
        // slack after placing next item; reward small slack
        let next_slack = post_residual - next_item_size;
        score -= 15.0 * (1.0 - next_slack as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; penalize proportionally to wasted potential
        score += 5.0;
    }

    // Coupling of item class with post class: avoid pairing large classes with large leftovers.
    score += 0.5 * (item_class as f64 * post_class as f64) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless current bin would leave tiny unusable residue.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Opening new bin is attractive when item is large-class and mean residual is fragmented.
        if item_class >= 6 && mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Progress modulation: later in the stream, be more aggressive about tight packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // Prefer bins with below-mean residual (keeps a spread of usable gaps).
    score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
