        // Big item with no good fit: opening new bin is fine
        if next_item_size > 0 && item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Early stream: be slightly conservative with open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic decay of residual waste.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Penalize residuals that no plausible item (1..100) can use efficiently:
    // tiny dead space is fine, but mid-size leftovers are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 3.0; // small but unusable for min-size items
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 0.25 * (post_residual - next_item_size) as f64;
    }
    // If next item would leave the bin nearly empty anyway, slight penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make opening a new bin attractive only
    // when current bins have little usable space relative to the item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 20.0;
        // Cheaper to open new bins early in the stream (more future items to fill it).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 18.0 * (1.0 - progress);
        // If open bins are crowded on average, new bin is more justified.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 10.0;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64).min(4.0);
        }
    } else {
        // Prefer bins with less residual when fitting_bins_count is large
        // (best-fit tie-breaking via residual coupling).
        score += 0.05 * (bin_residual as f64 - mean_residual);
        // Mild penalty for spreading across many open bins.
        score += 0.3 * open_bins_count as f64;
    }

    // Global slack pressure: when total open residual is large, discourage
    // placements that leave large post_residuals.
    let slack = mean_residual * open_bins_count as f64;
    if slack > 2.0 * bin_capacity as f64 {
        score += 0.08 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr + 40.0 * pr_norm * pr_norm;

    // Polynomial coupling of residual with stream progress
    let coupling = pr_norm * (1.0 + progress * progress * 3.0 - progress * 2.0);
    score += 30.0 * coupling;

    // Tight fits rewarded more as stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual
    score += 15.0 * (pr - mean_residual) / cap;

    // Last chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * progress;
    }

    // Lookahead: prefer leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        if gap < 0.0 {
            score += 10.0 * (-gap) * (1.0 + progress);
        } else {
            score -= 8.0 * gap * gap;
        }
    }

    // New-bin candidate: penalize mildly, more when many bins open
    if bin_residual == bin_capacity {
        score += 12.0 + 2.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: which "slot band" does the leftover fall in? ---
    // Class 0: post_residual == 0 (perfect fit) — strongly reward.
    // Class 1: post_residual in small dead zone (1..=10) — mild reward.
    // Class 2: post_residual in mid band — neutral.
    // Class 3: post_residual large — penalize (wasted capacity).
    let post = post_residual;
    if post == 0 {
        score -= 60.0;
    } else if post <= 10 {
        score -= 25.0;
    } else if post >= 50 {
        score += 20.0;
    }

    // Integer-division thresholds: post_residual divisible by common item sizes
    // (10,20,25,50) suggests the leftover may be reusable by typical future items.
    if post > 0 {
        let reusable = (post % 10 == 0) || (post % 20 == 0) || (post % 25 == 0) || (post % 50 == 0);
        if reusable {
            score -= 12.0;
        }
        // Odd, non-round dead space is less likely to be filled later.
        if post % 10 != 0 && post < 10 {
            score += 8.0;
        }
    }

    // --- Lookahead coupling: does the next item fit the post residual? ---
    if next_item_size > 0 {
        if next_item_size <= post {
            // Chain-friendly: reward proportionally to how snugly next item fits.
            let snug = (post - next_item_size) as f64;
            score -= 18.0 - snug.min(18.0);
        } else {
            // Next item cannot use the leftover: penalize wasted space.
            score += 10.0;
        }
        // If next item exactly consumes post residual, big bonus.
        if next_item_size == post && post > 0 {
            score -= 30.0;
        }
    }

    // --- Last-chance logic: if this is the only fitting bin, prefer using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling: opening a new bin is wasteful unless
    //     current bin would be left with unusable tiny residual. ---
    if bin_residual == bin_capacity {
        // New bin baseline: penalize relative to stream progress (early on,
        // keep bins open; late, allow more bins since order matters less).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 + 40.0 * (1.0 - progress);
        // If no open bin can fit at all, opening is inevitable; soften penalty.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // --- Mean residual coupling: prefer bins whose residual deviates from mean
    //     toward tighter packing (below-mean residual bins are "well used"). ---
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let dev = (res - mean_residual) / mean_residual;
        score += 8.0 * dev;
    }

    // --- Capacity fraction harmonic: reward placements landing on nice fractions ---
    let frac = post as f64 / bin_capacity as f64;
    if (frac * 4.0).round() == frac * 4.0 {
        score -= 5.0; // post lands on quarter-capacity grid
    }

    // --- Open bins pressure: many open bins -> prefer filling existing ones ---
    score += 2.0 * open_bins_count as f64;

    // --- Tight fit bonus: item fills most of the bin ---
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for the smallest plausible item) are heavily penalized,
    // quadratically, scaled by how far the stream has progressed.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64).powf(2.0) * (2.0 + 3.0 * progress);
    }

    // Reward tight fits strongly (post_residual near zero is ideal).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize waste relative to capacity: a large fraction of the bin left
    // unused when the bin was already mostly full is worse than spreading.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when
        // existing bins would leave large dead space.
        score += 20.0 + pressure * 8.0;
        // A new bin is acceptable if the item is large and would fit well.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 30.0;
        }
    } else {
        score -= pressure * 2.0;
    }

    // Lookahead: if the next item fits exactly into the resulting residual,
    // reward this placement; if it cannot fit, penalize leaving a big gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += (post_residual as f64) * 0.5;
        }
    }

    // Mild preference for bins with residuals close to the item size
    // (best-fit flavor) relative to the mean.
    score += (mean_residual - bin_residual as f64).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of post_residual
    // with the next item's size (perfect chain placement).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff < 0.5 {
            score -= 60.0; // exact 2-step match: place here almost surely
        } else if post >= nxt {
            // next item still fits here afterwards -> mildly reward tight chains
            let tight = 1.0 - (post - nxt) / bin_capacity as f64;
            score -= 12.0 * tight;
        } else {
            // next item won't fit in leftover -> penalize proportionally
            score += 10.0 * (1.0 - post / nxt);
        }
        // extra penalty if post_residual becomes dead space (below min plausible item)
        if post > 0.0 && post < 10.0 {
            score += 25.0;
        }
    }

    // Relative-to-mean residual coupling: prefer bins whose post_residual
    // stays below the current mean residual (consolidating space).
    score += 0.35 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (1.0 + step_index as f64 / total_items.max(1) as f64);
        score += 45.0 + 5.0 * pressure; // penalize new bin unless forced
        if next_item_size > 0 && next_item_size > bin_capacity - item_size.min(bin_capacity) {
            score += 5.0;
        }
    }

    // Early stream: be slightly greedy toward tight fits to build dense bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward near-full packing (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect or near-perfect fit gets a big bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible future item
    if post_residual < 10 && post_residual > 0 {
        score += 18.0 * (10.0 - post_residual as f64);
    }

    // Lookahead: reward if the next item fits exactly into the post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // next item fits: mild reward proportional to how much it consumes
            let consumed = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * consumed;
        } else {
            // next item won't fit here: penalize more as post residual shrinks
            let gap = (next_item_size - post_residual) as f64;
            score += 0.05 * gap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global state: when many bins are open, prefer consolidating into existing bins
    // (penalize opening new bins when open_bins_count is high)
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, modulated by state
        let mut new_bin_cost = 20.0;
        // More open bins -> higher cost of yet another bin
        new_bin_cost += 1.5 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (exploration)
        new_bin_cost *= (1.0 - 0.6 * progress);
        // If mean residual across open bins is high, we're wasting space -> new bin less bad
        new_bin_cost -= 0.3 * mean_residual;
        // If no existing bin fits well (post_residual large), new bin is more attractive
        score += new_bin_cost;
    } else {
        // Reward using existing bins, especially ones below the mean residual
        // (i.e., emptier-than-average bins get filled first)
        let rel = bin_residual as f64 - mean_residual;
        score -= 0.2 * rel;
        // Slight bonus for using existing bins late in the stream
        score -= 3.0 * progress;
    }

    // Coupling: large items early should prefer roomier bins
    if item_size > 60 {
        score -= 0.1 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: quadratic in post-residual (dead space penalized super-linearly)
    let mut score = pr + 0.008 * pr * pr;

    // Non-linear coupling of residual with stream progress:
    // late in the stream, small residuals matter more (tight packing)
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * progress;

    // Reward near-perfect fits: subtract smooth bump centered at post_residual ~ 0
    let fit_bump = (-pr_norm * pr_norm / 0.02).exp();
    score -= 15.0 * fit_bump;

    // Lookahead: reward residuals that can host the next item (smooth sigmoid-like)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr - nx).max(0.0) / cap;
        score += 4.0 * fits_next * fits_next;
        score -= 3.0 / (1.0 + (pr - nx).abs());
    }

    // Last-chance bin: strong reward, smoothly scaled by progress
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Penalize bins far from mean residual (prefer homogeneous fill levels), smooth quadratic
    let dev = bin_residual as f64 - mean_residual;
    score += 0.02 * dev * dev / (1.0 + open_bins_count as f64);

    // Slight preference to fill existing bins over opening new ones, growing with progress
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction bands (0..10%, 10..20%, ...). Leftovers in the lowest
    // band are nearly dead space -> penalize heavily; mid bands are reusable.
    let band = (post_residual * 10 / bin_capacity.max(1)) as i32; // 0..=10
    let band_penalty = match band {
        0 => 60.0,                       // dead space (<10% of capacity)
        1 => 20.0,
        2 => 5.0,
        3 | 4 => -10.0,                  // sweet spot: fits small/medium items
        5 | 6 => -5.0,
        _ => 0.0,
    };
    score += band_penalty;

    // Exact-fit reward: post_residual zero is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Modulo-arithmetic harmony: reward when post_residual is a multiple of
    // common small item classes (4, 5, 10, 20) so future items tile it exactly.
    let harmony = if post_residual > 0 {
        let pr = post_residual;
        let mut h = 0.0;
        if pr % 10 == 0 { h -= 8.0; }
        else if pr % 5 == 0 { h -= 4.0; }
        if pr % 20 == 0 { h -= 4.0; }
        if pr % 4 == 0 { h -= 2.0; }
        h
    } else { 0.0 };
    score += harmony;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is excellent; if next item cannot fit, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: neutral-ish baseline; opening a new bin is only
    // attractive when current placement would create dead space.
    if bin_residual == bin_capacity {
        score = 55.0 + post_residual as f64 * 0.1;
        if band == 0 || post_residual < 10 {
            score -= 40.0; // existing bin would leave dead space -> prefer new bin
        }
        if fitting_bins_count <= 1 && next_item_size > 0 && next_item_size <= bin_residual {
            score += 10.0;
        }
    }

    // Slight preference to fill bins below the mean residual (balance load).
    score -= (mean_residual - post_residual as f64) * 0.05;

    // Late-stream tightening: near the end, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual is dead space relative to the next item.
        score += 8.0 * (next_item_size as f64 / 100.0);
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score -= 15.0 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // Early in the stream, keep residuals flexible (avoid committing to near-full bins too early).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is close to the item need.
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let poor_fits = fitting_bins_count == 0
            || (post_residual > 0 && post_residual < 10);
        if poor_fits {
            score -= 20.0;
        } else {
            score += 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically: wasted capacity hurts.
        let waste = post_residual as f64;
        score += waste * waste / (bin_capacity as f64);
    }

    // Aggressive 2-step lookahead: if the next item fits into the post-residual,
    // this is a great chain placement; reward it proportionally to tightness.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover2 = post_residual - next_item_size;
            score -= 60.0 - (leftover2 as f64) * 0.3;
        } else {
            // Next item won't fit here: penalize leaving awkward residuals
            // that are slightly too small for typical future items.
            score += 15.0;
        }
    }

    // Compare against mean residual: placing into a bin whose residual is far
    // below average tightens the packing; placing into an already-large residual
    // is less valuable.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin early in the stream when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 60.0 * (1.0 - progress) + (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.98;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / c;

    // Base: post-residual (waste minimization), smoothly warped by progress.
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Non-linear coupling: residual tightness interacts with stream progress.
    let tight = (1.0 - norm_pr).powi(3);
    score -= 12.0 * tight * (0.5 + progress);

    // Lookahead: reward residuals that can host the next item (smoothly).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let slack = (pr - ns) / c;
            score -= 6.0 * (1.0 - slack * slack) * (1.0 - progress);
        } else {
            let gap = (ns - pr) / c;
            score += 8.0 * gap * (1.0 + progress);
        }
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + 0.5 * progress);
    }

    // Penalize bins deviating from mean residual (smooth quadratic dispersion term).
    let dev = (pr - mean_residual) / c;
    score += 5.0 * dev * dev * open_bins_count as f64;

    // Mild penalty for opening new bins late in the stream.
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions (C/8 classes)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let eighth = cap / 8.0;
    let class = (pr / eighth).floor(); // 0..=8

    // Penalize residuals in "dead" classes: too small for typical items but nonzero.
    // Class 0 (perfect fit) heavily rewarded; classes 1 (tiny) heavily penalized.
    match class as i32 {
        0 => score -= 40.0,
        1 => score += 25.0,
        2 => score += 12.0,
        3 => score -= 5.0,
        4 => score -= 3.0,
        5 => score -= 8.0,
        6 => score -= 4.0,
        _ => {}
    }

    // Lookahead coupling: does next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: reward proportionally to how snugly
            let snug = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - snug / cap);
        } else {
            // Next item won't fit: penalize more if the wasted gap is small
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 * (1.0 - gap / cap).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Modulo-3 arithmetic on post_residual: certain residue classes pair well
    // with common item sizes (multiples of 10-ish) in modular streams.
    let m3 = post_residual % 3;
    if m3 == 0 {
        score -= 3.0;
    } else if m3 == 1 {
        score += 2.0;
    }

    // Integer-division threshold: residual <= 20 is nearly dead space
    if post_residual > 0 && post_residual <= 20 {
        score += 15.0;
    }

    // New-bin candidate handling: an empty bin has high raw residual; make it
    // attractive only when open bins are fragmented or the fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        // Prefer new bin early, or when existing residuals are small/fragmented,
        // or when this item would leave a bad residual elsewhere.
        let poor_fit = if bin_residual >= item_size {
            let pr_alt = (bin_residual - item_size) as f64;
            (pr_alt > 0.0 && pr_alt < 20.0) as f64 * 20.0
        } else { 0.0 };
        score = 60.0 - 25.0 * (1.0 - progress) - 20.0 * fragmentation.max(0.0) - poor_fit;
        if fitting_bins_count == 1 {
            score += 45.0; // don't abandon the last usable bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Medium dead space (10..20) is moderately penalized since few items fit.
    else if post_residual >= 10 && post_residual < 20 {
        score += 8.0 + 0.5 * (20.0 - post_residual as f64);
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 6.0 * progress);

    // If this is the empty new-bin candidate, apply a mild barrier so it only
    // wins when existing bins are genuinely bad fits (large dead space).
    if bin_residual == bin_capacity {
        score += 25.0 + 0.3 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    }
    // If next item fits into post-residual at all, mild reward.
    else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }
    // If next item is large and this bin would leave a gap next item can't use,
    // slightly discourage creating awkward residuals.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Prefer bins whose residual is close to the item (tight fit relative to mean).
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item chains nicely into this bin: reward proportional to tightness of chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.5;
        } else {
            // Post residual too small for the next item: penalize dead space,
            // worse the smaller the unusable remainder relative to mean residual.
            let dead = post_residual as f64;
            let rel = if mean_residual > 0.0 { dead / mean_residual } else { 1.0 };
            score += 40.0 * rel;
        }
    }

    // Penalize creating awkward small residuals (1..=10) that rarely fit anything.
    if post_residual > 0 && post_residual <= 10 {
        score += 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the new-bin residual would be perfectly clean).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Prefer filling bins that are already relatively full (small residual vs mean).
    if mean_residual > 0.0 {
        score -= (mean_residual - post_residual as f64) * 0.3;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.1;

    // Early in the stream, be slightly more willing to open fresh bins for large items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline near capacity, bonus early, penalty late.
        score = 100.0 - progress * 20.0 + item_size as f64 * 0.2;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 200.0; // next item needs a fresh bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1), used as a dynamic time horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Lookahead coupling: reward residuals that can host the next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // The next item can also fit here: strong chaining bonus.
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 8.0 + 10.0 * chain_tightness;
        } else if post_residual > 0 {
            // Dead space the next item cannot use: penalize, scaled by how
            // unusable it is relative to the smallest plausible item.
            let waste = post_residual as f64;
            score += 0.5 * waste * (0.5 + progress);
        }
    }

    // --- Perfect / near-perfect fit rewards ---
    if post_residual == 0 {
        score -= 30.0; // exact fill, always ideal
    } else if post_residual <= 5 {
        score -= 15.0; // nearly perfect fill
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // --- Last-chance dynamics ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // This is the only open bin that fits; using it avoids opening a bin.
        score -= 12.0;
        // Extra pressure late in the stream when consolidation matters most.
        score -= 6.0 * progress;
    } else if fitting_bins_count > 1 {
        // Competition exists: mildly prefer bins with less residual (best-fit
        // already encoded via post_residual), but discourage hoarding many bins.
        score += 1.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // --- Global state coupling ---
    let mean_gap = mean_residual - post_residual as f64;
    // Favor bins whose resulting residual is below the current mean
    // (pushes toward compacting low-residual bins and closing them out).
    score += 0.15 * mean_gap;

    // Many open bins: encourage closing them by filling small residuals.
    if open_bins_count > 4 {
        score -= 0.05 * (post_residual as f64) * (open_bins_count as f64).sqrt();
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Baseline cost of opening a fresh bin.
        score = bin_capacity as f64 * 0.75;
        // Early in the stream or when no good option exists, opening is cheap.
        let desperate = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual < next_item_size && post_residual > 20);
        if desperate {
            score -= 40.0;
        }
        // Late in the stream, prefer squeezing into existing bins.
        score += 25.0 * progress;
        // If many bins are open and none fit tightly, a new bin is fine.
        if open_bins_count > 6 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual
    let it = item_size as f64;
    let ni = next_item_size as f64;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - t) + x * x * x * t;
    score += 12.0 * poly;

    // Tight fit reward, stronger late in stream
    let tight = (1.0 - x).powi(3);
    score -= 25.0 * tight * (0.5 + 0.5 * t);

    // Reward leaving room exactly for the lookahead item
    if ni > 0.0 && ni <= pr as f64 {
        let gap = (pr - ni as u32) as f64;
        score -= 15.0 * (1.0 - gap / cap) * (0.4 + 0.6 * t);
    }

    // Penalize when this is the last fitting bin yet fit is poor
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - x);
    }

    // Mild penalty for excessive open bins relative to progress
    let open_pressure = open_bins_count as f64 / (1.0 + t * 10.0);
    score += 0.05 * open_pressure * x;

    // Deviation from mean residual: prefer bins near mean to keep balance
    score += 0.1 * (pr as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity divided into octaves.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let octave = (pr / cap * 8.0).floor(); // 0..7 harmonic class of leftover space

    // Reward tight fits: post_residual in the lowest octave (0-12% waste) is great.
    match octave as u32 {
        0 => score -= 30.0,
        1 => score -= 12.0,
        2 => score -= 3.0,
        3 => score += 2.0,
        4 => score += 6.0,
        5 => score += 12.0,
        6 => score += 20.0,
        _ => score += 28.0,
    }

    // Exact-fill bonus: post_residual divisible by common harmonic denominators.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 25 == 0 { score -= 5.0; }
    } else {
        score -= 40.0; // perfect fill
    }

    // Modulo coupling with next item: if next item can exactly fill the leftover,
    // strongly favor this bin (chain of harmonic complements).
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % next_item_size.max(1) == 0 {
            score -= 18.0;
        } else if next_item_size >= post_residual * 3 / 4 {
            score -= 10.0; // next item nearly fills the remainder
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // leftover too small for the next item: dead space penalty scaled by class
        score += octave * 2.5;
    }

    // Last-chance bin: this is the only open bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; stronger when many bins are open
        // (consolidation preferred) or when a tight fit exists elsewhere.
        score += 15.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0; // fresh bin can host future harmonic pairs
        }
    }

    // Stream progression: late in the stream, be greedier about consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - pr / cap);

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.15 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold typical
    // future items are wasted. Penalize gaps in (0, 10] heavily and
    // gaps that no plausible next item (>= next_item_size) can use.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 12.0 + 0.5 * post_residual as f64;
        }
    } else {
        // Perfect fill is excellent.
        score -= 40.0;
    }

    // Reward tight fits (high fill ratio).
    let fill = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill * fill;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, consolidate into them;
    // when few are open, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (0.6 + 0.8 * progress);
    score -= pressure * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: empty bin should win only when open bins are poor fits.
    if bin_residual == bin_capacity {
        score = 55.0 - 8.0 * mean_residual.min(100.0) / 100.0
            - pressure
            + if next_item_size > 0 && next_item_size >= item_size { 10.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match bonus: next item would fit with minimal waste left after that.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack_after_next / bin_capacity as f64);
    }

    // Penalize residuals too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.8 * unusable;
    }

    // Compare post_residual against mean residual: leaving more than average
    // open space is fine (bin stays usable), less than average is wasteful.
    score -= 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current bin would leave
    // a very tight, unusable residue and many bins are already open.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 15.0;
        }
        score += open_bins_count as f64 * 2.0;
    }

    // Early in the stream: be pickier (prefer tight fits), later: consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual is just above item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for the smallest plausible item (1..100 interface).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate logic: only attractive when existing fits are bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = fit_ratio < 0.5;
        if bad_fit || open_bins_count == 0 {
            score -= 30.0 + 40.0 * (1.0 - fit_ratio);
        } else {
            score += 20.0 + 50.0 * progress;
        }
        // Early stream: opening fresh bins is cheap and useful.
        if progress < 0.2 {
            score -= 15.0;
        }
    }

    // Global balance: prefer bins with residual near the mean (keep bin family homogeneous).
    score -= 5.0 * (1.0 - ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64));

    // Slight preference for filling fuller bins (smaller residual) as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize leftover space, but less so late in the stream
    let mut score = pr * (0.5 + 0.5 * (1.0 - progress));

    // Non-linear coupling: squared normalized post-residual, damped by progress
    score += 20.0 * pr_norm * pr_norm * (1.0 - 0.5 * progress);

    // Interaction with mean residual: prefer bins near the mean (tight packing)
    let mean_norm = mean_residual / cap;
    let deviation = pr_norm - mean_norm;
    score += 15.0 * deviation * deviation;

    // Smooth cubic term: strongly penalize large dead space that can't fit typical items
    score += 10.0 * pr_norm * pr_norm * pr_norm;

    // Last-chance bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead coupling: reward if next item fits well in post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_quality = 1.0 - ((pr - nxt) / cap);
            score -= 12.0 * fit_quality * fit_quality;
        } else {
            // post-residual too small for next item: penalize smoothly
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap;
        }
    }

    // Encourage closing bins when many are open (fragmentation control)
    score += (open_bins_count as f64).ln().max(0.0) * pr_norm * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual bands via capacity fractions.
    // Bands: 0 (perfect), (0,10] tiny dead space, (10,25] small, (25,50] medium, (50,100] large.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let dead_zone = 10.0; // residuals <= 10 are nearly unusable for items >= 10

    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if pr <= dead_zone {
        score += 30.0; // dead space penalty
    } else if pr <= c * 0.25 {
        score += 5.0;
    } else if pr <= c * 0.5 {
        score -= 5.0;
    } else {
        score -= 12.0; // large residual left is fine
    }

    // Harmonic pairing: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            let new_pr = post_residual - next_item_size;
            if new_pr <= dead_zone {
                score += 15.0; // chain creates dead space
            } else {
                score -= 8.0;
            }
        } else {
            score += 10.0; // next item won't chain here
        }
    }

    // Last-chance bin bonus: only bin that fits item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when fit elsewhere is bad.
    if bin_residual == bin_capacity {
        // Neutral-ish base; penalize when open bins exist and mean residual is healthy.
        score += 60.0;
        if open_bins_count > 0 {
            score += (mean_residual / c) * 40.0;
            // prefer new bin late in stream when residuals are fragmented
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score -= progress * 10.0;
        }
        // big items favor a fresh bin
        if item_size > 60 {
            score -= 25.0;
        }
    }

    // Modulo harmonic classes on post_residual (quarter classes)
    let q = post_residual / 25; // integer division threshold class
    score -= q as f64 * 2.0;

    // Slight preference for tighter fits (smaller post_residual) beyond base
    score += (item_size as f64 / c) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (min size 1, but
    // typical items are >= 10) are almost unusable -> strong nonlinear penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Moderately awkward gaps also get a soft penalty
        score += 8.0;
    }

    // Lookahead reward: if the next item can fit into the post residual,
    // this placement chains nicely -> subtract to favor it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; this bin will likely become dead space
        score += 6.0;
    }

    // New-bin candidate: penalize opening a fresh bin, with pressure growing
    // as more bins are already open (prefer filling existing bins).
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64
            + 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Last-chance bin: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: bins tighter than the mean residual are better
    // targets; penalize bins looser than the mean.
    score += 0.08 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Post residual can still fit the next item: reward tight fits
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot fit here: penalize proportionally to wasted capacity
    else if next_item_size > 0 {
        score += 20.0 + 0.3 * post_residual as f64;
    }

    // Reward filling bins tighter than the current mean residual
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Late in the stream, prefer closing out bins (less residual waste)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.1 * post_residual as f64;

    // Mild penalty when many bins are open: encourage consolidation
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, with mild non-linear scaling.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste * waste;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize if post residual can't fit the next item but could
    // have fit it with slack; reward if next item fits exactly in leftover.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
        } else if (bin_residual as u32) >= next_item_size && post_residual > 0 {
            score += 6.0;
        }
        // Chain fit: this placement + next item leaves nothing.
        if (post_residual as u32) == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowding: many open bins -> favor filling existing ones, discourage new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.15 * pressure * (1.0 - progress);

    // New-bin candidate: only attractive when mean residual is too small for the item
    // or no open bin is a good home.
    if bin_residual == bin_capacity {
        let mean_fits = mean_residual >= item_size as f64;
        if mean_fits && fitting_bins_count > 0 {
            score += 60.0 + 10.0 * (open_bins_count as f64).sqrt();
        } else {
            score += 5.0; // weak preference for fresh space when nothing fits well
        }
        // Late in the stream, opening new bins is more acceptable.
        score -= 20.0 * progress;
    }

    // Dead-space penalty: small unusable leftovers (1..10) are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Slight preference toward bins whose residual is close to item size (tight fit).
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64).abs() / bin_capacity as f64;
    score -= 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;
    // quadratic coupling of post_residual with stream progress
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);
    // reward tight fits more strongly as stream advances
    let tight = 1.0 - norm_pr;
    score -= 6.0 * tight * tight * (0.3 + 0.7 * progress);
    // dead-space penalty: very small post-residuals that can't fit typical items
    if pr > 0.0 && pr < 10.0 {
        score += 5.0 * (1.0 - pr / 10.0);
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 4.0;
    }
    // lookahead: favor bins whose post-residual fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
        } else if post_residual > 0 {
            score += 2.0;
        }
    }
    // mean residual coupling: penalize bins far from the mean
    score += 0.05 * (pr - mean_residual).abs();
    // mild penalty for opening new bins late in the stream
    if bin_residual == bin_capacity {
        score += 2.0 + 6.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Harmonic class of post_residual: mod-10 buckets reward small residuals
    let pr = post_residual as i64;
    let class = pr % 10;
    if class == 0 {
        score -= 8.0; // perfect decade residual
    } else if class <= 3 {
        score -= 3.0;
    } else if class >= 7 {
        score += 3.0; // awkward sliver
    }

    // Dead-space penalty: residual too small for the smallest possible item
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Lookahead: does post_residual still fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
            // harmonic coupling: next item's mod class
            let ncls = (next_item_size as i64) % 10;
            if ncls == 0 {
                score -= 2.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening unless item is huge relative to capacity
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        if frac < 0.5 {
            score += 20.0;
        } else if frac >= 0.8 {
            score -= 5.0;
        }
        // fewer open bins -> slightly prefer reusing structure anyway
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Progress-scaled tightening: late in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (10.0 - post_residual as f64).max(0.0) * (0.5 + progress);

    // Mean-residual coupling: if this bin is far below mean residual, it's a good dump target
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Heavy penalty for small unusable dead space: gaps below the minimum item size (1..10)
    // are worthless. Penalize post_residual in the "dead zone" (1..=10) very strongly.
    if post_residual >= 1 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        // Slightly-above-minimum gaps are hard to fill too
        score += 8.0;
    }

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 15.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use this gap -> dead space for next step
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && post_residual <= 10 {
        score -= 12.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin (high post_residual) is fine.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += pressure * (0.5 + 0.5 * progress) * 0.8;

    // Make new-bin candidate less attractive when decent fits exist:
    // a new bin has post_residual = capacity - item (large), so base score already
    // high; add mild extra cost scaled by how many bins could fit.
    if bin_residual == bin_capacity {
        score += 5.0 + (fitting_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual).
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin becomes exactly full after next item
        } else if next_item_size <= post_residual {
            // next item fits too: reward proportionally to how much it fills the remainder
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item does NOT fit here: penalize leaving gaps the next item can't use
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    }

    // Compare post_residual against mean residual: leaving more than average waste is bad.
    score += 0.4 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.2 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit.
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; escalate with number of open bins
        // and when the current item is small relative to capacity.
        score += 45.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= post_residual {
            // fresh bin promises good fit for the upcoming item
            score -= 20.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Penalize creating very small dead space that no item (min size 1..100) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: strongly favor small post_residual (non-linear).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Penalize placing small items into large-residual bins (preserve big space).
    let size_frac = item_size as f64 / bin_capacity as f64;
    let waste = (1.0 - size_frac) * (bin_residual as f64 / bin_capacity as f64);
    score += 25.0 * waste;

    // Lookahead: reward if next item fits exactly into post_residual (perfect chaining).
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Next item won't fit here; penalize leaving awkward small residue.
            let leftover = post_residual as f64;
            if leftover > 0.0 && leftover < next_item_size as f64 {
                score += 8.0 * (1.0 - leftover / (next_item_size as f64));
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global pressure: when many bins are open, discourage new bins implicitly by
    // rewarding reuse proportional to open_bins_count.
    if bin_residual < bin_capacity {
        score -= 3.0 * (open_bins_count as f64).sqrt();
    }

    // Mean-residual coupling: if this bin's residual is far below the mean, it is
    // a "crumb" bin; prefer to fill it off and keep larger residuals around.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 6.0 * (mean_residual - res) / bin_capacity as f64;
    } else {
        score += 4.0 * (res - mean_residual) / bin_capacity as f64;
    }

    // Time horizon: late in the stream, consolidation matters more (penalize
    // opening new bins), early on exploration is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, increasingly penalized later,
        // and only attractive if it enables a near-perfect pack for this item.
        let base = 55.0 + 45.0 * progress;
        let perfect = (item_size == bin_capacity) as i32 as f64 * 200.0;
        score = score.min(base - perfect);
        // If an open bin fits and this is late, make new bin clearly worse.
        if fitting_bins_count > 0 {
            score += 20.0 * progress;
        }
    } else {
        // Reuse reward grows with progress.
        score -= 10.0 * progress;
    }

    // Exact fit is always excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with a non-linear polynomial shaping of residual.
    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 - norm_pr));

    // Smooth progress coupling: later in the stream, penalize large residuals more strongly.
    let progress_term = 0.5 * progress * (pr * pr) / cap;
    score += progress_term;

    // Coupling with mean residual: bins far from the mean get a smooth polynomial nudge.
    let diff = pr - mean_residual;
    score += 0.3 * diff * diff / cap;

    // Last-chance bonus: strongly reward using the only fitting bin (smoothly scaled by fill).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward leaving room for the next item with a smooth quadratic overlap term.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = pr - ns;
        if gap >= 0.0 {
            score -= 4.0 * (1.0 - (gap / cap).abs());
        } else {
            score += 2.0 * (gap.abs() / cap) * (gap.abs() / cap) * cap;
        }
    }

    // Mild penalty for opening new bins when many bins are open late in the stream.
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * progress + (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by 10 are more reusable
    let cls = (post_residual % 10) as f64;
    score += cls * 1.5;

    // Very small dead space is excellent (near-perfect fit)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Penalize mid-range residuals that few item sizes can use
    if post_residual >= 20 && post_residual < 40 {
        score += 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot use this bin's remainder: mild penalty
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalize new bins slightly more as stream progresses
        score += 12.0 + 20.0 * progress;
        // but if the item is large relative to capacity, new bin is fine
        if item_size * 2 >= bin_capacity {
            score -= 15.0;
        }
    }

    // Prefer filling bins with large residuals when many bins are open
    score -= mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual <= 30 {
        score += 4.0;
    }

    // Last-chance pressure: if this is the only fitting bin, reward using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new (empty) bin is relatively fine.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 8.0 * open_pressure;
        // But if the item would leave a bad gap in existing bins, ease this.
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0;
        }
    } else {
        // Reusing an existing bin: small bonus proportional to open pressure.
        score -= 3.0 * open_pressure;
    }

    // Lookahead: if next item could exactly fill the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 18.0;
    }
    // If next item cannot fit into post residual anyway, a large gap is less useful.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (tighter than average => better consolidation).
    if bin_residual < bin_capacity {
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Progression: later in the stream, be slightly more conservative
    // about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how snugly the next item fits.
            let slack_after_next = post_residual - next_item_size;
            score -= 120.0 - (slack_after_next as f64).min(120.0);
            // Extra bonus if the bin would then be nearly full.
            if slack_after_next <= 5 {
                score -= 80.0;
            }
        } else {
            // Penalize leaving a gap that the next item cannot use (dead space).
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(60.0);
        }
    }

    // Penalize bins whose residual deviates upward from the mean (fragmented space).
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Early in the stream, be more willing to pack tightly into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 20.0;

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * fit_ratio * fit_ratio;

    // Penalize large leftover dead space that few future items can use (items >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0; // awkward gap
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward residual that can still host the next item; penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > bin_capacity {
            score += 0.0;
        } else {
            score += 3.0;
        }
        // Perfect pairing: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the item
    // is large relative to capacity or open bins are very fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
        // Penalize new bins generally, less so when item is big or bins are fragmented.
        score += 20.0 - 12.0 * (item_size as f64 / bin_capacity as f64) - 10.0 * fragmentation;
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
        // Late in stream, prefer consolidating into existing bins.
        score += 8.0 * progress;
    }

    // Mild preference for bins below mean residual (keeps a spread of gap sizes).
    if bin_residual < bin_capacity {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear polynomial coupling of post_residual with progress.
    // Early in the stream: favor tight fits (small post_residual) strongly.
    // Late in the stream: tolerate larger post_residual slightly, since
    // residual fragmentation matters less when the stream is ending.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    let time_warp = 0.5 + 0.5 * progress; // smooth in [0.5, 1.0]
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * 30.0; // hump-shaped penalty for mid-size waste
    score += poly * time_warp;

    // Reward nearly-full placements with a smooth quadratic bonus
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * 12.0;

    // Last-chance bonus: strongly prefer using the only bin that fits,
    // avoiding a fresh bin opening; smooth ramp via fitting count.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        score -= (fitting_bins_count as f64).recip() * 6.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let fit_quality = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 10.0 * (1.0 - fit_quality * fit_quality);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that is useless for the next item,
        // scaled by how close the residual is to being wasted.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 8.0 * waste * (1.0 - progress);
    }

    // Deviation from mean residual: prefer bins whose post-residual is
    // harmonized with the fleet mean (smooth quadratic coupling).
    score += 0.15 * (pr - mean_residual) * (pr - mean_residual) / (bin_capacity as f64);

    // Mild penalty for spreading across many open bins late in the stream
    score += 0.02 * (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);

    // New-bin candidate handling: an empty bin should only win when the
    // placement would otherwise create severe dead space.
    if bin_residual == bin_capacity {
        let dead_space_risk = pr_norm * pr_norm;
        score += 18.0 - 20.0 * dead_space_risk * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (buckets of 10) ---
    let post_class = post_residual / 10;
    let post_mod = post_residual % 10;

    // Dead-space penalty: residuals that no typical item can use.
    // Class 0 (perfect fit) heavily rewarded; tiny unusable slivers penalized.
    match post_class {
        0 => score -= 45.0,                       // exact fit, ideal
        1 => score -= 12.0,                       // 10..19 usable by small items
        2 => score -= 6.0,                        // 20..29
        3 => score -= 2.0,                        // 30..39
        4 | 5 => score -= 0.0,                    // mid range, neutral
        6 | 7 => score += 3.0,                    // getting loose
        _ => score += 6.0,                        // very loose, likely wasteful
    }

    // Fine-grained modulo penalty: odd tails (mod 10 in 1..=4) are hard to fill.
    if post_mod >= 1 && post_mod <= 4 {
        score += 4.0 - post_mod as f64;
    } else if post_mod >= 5 {
        score -= 1.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward; if next item cannot fit, penalize (bin becomes dead).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // harmonic class match: next item leaves a "clean" class again
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            }
            score -= (next_item_size as f64) / 20.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Many open bins: prefer tightening the most crowded bins (below-mean residual).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate: empty bin should only win when open bins are fragmented
    // or the item is huge and would leave a bad class in an open bin.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (step_index as f64 + 1.0);
        score += 25.0
            + 20.0 * fragmentation
            - 15.0 * pressure
            - (item_size as f64) / 4.0;
        // large items open fresh bins more willingly
        if item_size >= 60 {
            score -= 12.0;
        }
        // early stream: opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference to fill nearly-full bins first (best-fit flavor).
    score -= (bin_capacity - bin_residual) as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps: if post_residual is smaller than the
    // minimum plausible item size (1..100 stream => treat <=10 as dead space),
    // a perfect fit is great, but a tiny leftover that nothing can use is waste.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 1000.0;
    } else if post_residual <= 10 {
        // Dead space: bin becomes useless for future items.
        score += 500.0;
    } else {
        // Usable residual: mild reward for larger leftovers, but check lookahead.
        score -= (post_residual as f64).sqrt() * 5.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin; if next item cannot fit, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size > post_residual {
            score += 40.0;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes more expensive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 + 8.0 * progress);

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (tighter bins get filled first, keeping loose bins flexible).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize moderately so it is only chosen when all
    // open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 150.0 + open_bins_count as f64 * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward post_residual close to next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (-gap / 25.0).exp();
        // Perfect 2-step chain bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving dead space too small for the next item
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (post_residual as f64).max(1.0);
        }
    } else {
        // Last item: minimize waste directly
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting a nearly-empty fresh bin's flexibility on a small item
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score += 30.0 * (1.0 - fill_frac) * (1.0 - fill_frac);
        // But allow new bin if nothing fits well elsewhere
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Early stream: be conservative, keep bins open for flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    // Slight preference for tighter bins when many bins are open
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Reward near-exact fills.
    if post_residual <= 2 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bonus: only one bin fits the item.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count >= 3 {
        // Many alternatives: be pickier about wasted space.
        score += 8.0 * tightness;
    }

    // Lookahead coupling: prefer leaving post_residual that can host next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 18.0; // leaves a slot the next item nearly fills
        } else if post_residual > 0 && post_residual < next_item_size.min(100) {
            score += 10.0; // dead space relative to lookahead
        }
    } else {
        // Last item: strongly prefer zero residual.
        score += 0.5 * post_residual as f64;
    }

    // Global state: with many open bins, consolidate (favor fuller bins).
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.15 * mean_gap; // prefer bins with residual below the mean (fuller)

    // Time horizon: late in stream, consolidation matters more; early, allow new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - tightness);
    if bin_residual == bin_capacity {
        // New-bin candidate: cheap early, expensive late.
        score += 20.0 * progress + 5.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear waste coupling: quadratic in normalized post-residual
    let pr_norm = post_residual as f64 / cap;
    score += 8.0 * pr_norm * pr_norm * (1.0 + progress);

    // Lookahead: penalize residual too small for next item, reward exact re-use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) < nx {
            score += 6.0 * (nx - post_residual as f64) / cap;
        } else {
            score -= 3.0 * (nx / cap) * (1.0 - ((post_residual as f64 - nx) / cap));
        }
    }

    // Tight fit reward: smooth sigmoid-like bonus for small post_residual
    let tight = (-pr_norm * 10.0).exp();
    score -= 5.0 * tight;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    // New-bin candidate: prefer opening new bins early, penalize late
    if bin_residual == bin_capacity {
        score = cap * (1.0 - progress) + 10.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Mild attraction toward bins with residuals near the item size (smooth)
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 2.0 * fit_gap * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: post_residual divisible by 10 -> aligns with 10-multiples, highly reusable.
    // Class 1: post_residual % 10 == 5 -> half-slot, medium reuse.
    // Else: ragged residue, penalize.
    let post = post_residual;
    let class = post % 10;
    match class {
        0 => { score -= 8.0; }
        5 => { score -= 3.0; }
        _ => { score += 5.0 + (class as f64) * 0.4; }
    }

    // Dead-space penalty: post_residual too small for the minimum item (1..100 interface, use 10 as soft floor)
    if post > 0 && post < 10 {
        score += 20.0; // unusable sliver
    }

    // Perfect fit reward
    if post == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: can next_item_size land exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 15.0; // chained perfect fit
        } else if next_item_size < post {
            let slack = post - next_item_size;
            // harmonic class of the slack after the lookahead placement
            match slack % 10 {
                0 => score -= 6.0,
                5 => score -= 2.0,
                _ => score += 3.0,
            }
        } else {
            // next item cannot fit here; slightly penalize wasting a good residual
            score += 4.0;
        }
    }

    // Integer-division thresholds on post_residual (capacity fractions)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post >= half {
        score -= 4.0; // large residual is valuable
    } else if post >= quarter {
        score -= 1.0;
    } else if post > 0 {
        score += 3.0; // cramped bin
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let crowded = mean_residual < (bin_capacity as f64) * 0.2;
        let poor_fit = item_size > bin_capacity * 3 / 4;
        if crowded || poor_fit {
            score -= 10.0;
        } else {
            score += 15.0; // prefer existing bins early on
        }
    }

    // Late-stream consolidation: as stream progresses, favor filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (post as f64 / bin_capacity as f64);

    // Mild bonus for keeping open-bin count low
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: residuals too small for any item (1..10)
    // are unusable dead space -> heavy penalty scaled by how dead they are.
    if post_residual < 10 {
        score += 200.0 + (10 - post_residual) as f64 * 20.0;
    } else if post_residual <= 20 {
        // Small but potentially usable gap: mild penalty to prefer larger residuals.
        score += 10.0;
    }

    // Lookahead: reward residuals that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // This bin becomes dead after placement; penalize proportionally.
            score += 30.0;
        }
    }

    // Last chance: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only prefer it if current bin would leave large dead space
    // or residual is already tight for future items.
    if bin_residual == bin_capacity {
        // Neutral-ish base; open_bins_count pressure decides.
        score += 5.0;
    }

    // Open bins pressure: many open bins -> favor filling existing ones
    // (new-bin candidate gets penalized more when many bins are open).
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 8.0;
        // Late in the stream, avoid spawning bins aggressively.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    } else {
        // Filling an existing bin is favored slightly more when many bins are open.
        score -= open_bins_count as f64 * 1.5;
    }

    // Mean residual coupling: if mean residual across open bins is high,
    // there's slack elsewhere; be pickier about wasting this bin's space.
    if post_residual as f64 > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: residual after placement exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the post residual: strong bonus, scaled by tightness.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit: penalize proportionally to wasted dead space.
    else if next_item_size > 0 {
        let waste = post_residual as f64;
        score += 0.5 * waste;
        // Extra penalty if next item would have fit better elsewhere.
        if next_item_size > post_residual {
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: bins with residual far below mean are tight;
    // placing there is good (small post_residual already captured), but a bin
    // whose residual greatly exceeds mean_residual is "loose" — prefer using it.
    let diff = bin_residual as f64 - mean_residual;
    score -= 0.1 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when few bins fit the item
    // or the item is huge (poor fit anywhere).
    if bin_residual == bin_capacity {
        let huge = item_size as f64 > 0.6 * bin_capacity as f64;
        if fitting_bins_count <= 1 || huge {
            score -= 15.0;
        } else {
            // Discourage opening new bins when existing bins fit fine.
            score += 20.0 + 0.2 * post_residual as f64;
        }
    }

    // Late in the stream, tighten up: prefer minimizing bins, so reward reuse.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (open_bins_count as f64).recip().max(0.0) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
