pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - 0.5 * norm_pr * progress;
    score += 20.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Lookahead: reward residual that can fit next item, penalize otherwise
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - progress);
        } else {
            score += 6.0 + 10.0 * progress;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty coupling with mean residual to prefer balanced bins
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: penalize moderately so it's chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residues near multiples of small
    // denominators (2,3,4) are more "usable" by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Perfect fit: zero waste is ideal.
    if pr == 0 {
        score -= 1000.0;
    }

    // Class penalty: dead space that is too small for the minimum item (1..100
    // interface, min plausible ~10) is worthless.
    if pr > 0 && pr < 10 {
        score += 60.0; // tiny sliver = dead space
    }

    // Harmonic goodness: post_residual divisible by 4, 3, or 2 tends to be
    // reusable by common item sizes.
    let div_bonus = if pr % 4 == 0 {
        18.0
    } else if pr % 3 == 0 {
        12.0
    } else if pr % 2 == 0 {
        6.0
    } else {
        0.0
    };
    score -= div_bonus;

    // Lookahead: reward if next item fits exactly in post_residual,
    // penalize if next item can't fit at all.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 250.0;
        } else if next_item_size < pr {
            let waste_after_next = pr - next_item_size;
            if waste_after_next < 10 {
                score -= 120.0; // near-exact two-item packing
            } else {
                score -= (pr as f64 - next_item_size as f64) * 0.3;
            }
        } else {
            score += 15.0; // next item won't fit here anyway; keep flexibility
        }
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when this bin's fit is terrible.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly; it competes via raw score.
        // Penalize more when many bins are open (fragmentation risk).
        score += 40.0 + 5.0 * open_bins_count as f64;
        // But if current placement would leave huge waste elsewhere, the
        // baseline already reflects that.
        if fitting_bins_count > 0 {
            let best_alt_waste = post_residual; // same as new bin residual
            let _ = best_alt_waste;
        }
    }

    // Waste relative to capacity fraction: quadratic penalty on large
    // post_residual (harmonic fraction > 1/2 of capacity is wasteful).
    let frac = post_residual as f64 / cap;
    if frac > 0.5 {
        score += (frac - 0.5) * 80.0;
    }

    // Tight fits (small post_residual that is still usable) are great.
    if pr >= 10 && pr <= 25 {
        score -= 40.0;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * 20.0 * progress;

    // Prefer bins with residuals below mean (balance preservation).
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are wasted.
