        score -= 8.0;
        // Bonus proportional to how tightly the next item fits afterwards.
        let next_leftover = (post_residual - next_item_size) as f64;
        score -= (10.0 / (1.0 + next_leftover)).min(5.0);
    }
    // Next item cannot fit here: penalize creating dead space, worse for small post_residual.
    else if next_item_size > 0 {
        score += 6.0;
        score += 12.0 / (1.0 + post_residual as f64);
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize tiny unusable dead space (waste), scaled against capacity.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 0.8;
    }

    // Reward closing residual gap relative to mean residual (balance open bins).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Slight preference for filling fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;

    // Mildly discourage opening new bins when several bins are already open.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    score
