pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= 40.0 * fill_ratio;
    } else if fill_ratio < 0.4 {
        // Penalize wasteful placements into large-residual bins.
        score += 15.0 * (0.4 - fill_ratio);
    }

    // Dead-space penalty: small post_residual that can't fit typical items is fine;
    // mid-range dead space (e.g. 10..30) is the worst outcome.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 0.0 } else if post_residual <= 30 { (post_residual as f64) * 0.8 } else { 0.0 };
        score += dead;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here anyway; slight penalty if we nearly filled bin.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global pressure: many open bins with low mean residual -> prefer consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln();
        score += consolidation * (2.0 + 6.0 * progress);
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced late in the stream or when many bins open.
        score = bin_capacity as f64 - 20.0 * progress - 3.0 * (open_bins_count as f64).min(10.0);
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin gives room for a possibly larger follower
        }
    }

    // Mild time-horizon modulation: early stream, be conservative with big residuals.
    score += 10.0 * (1.0 - progress) * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        - 18.0 * norm_pr * (1.0 - norm_pr)
        + 10.0 * norm_pr * norm_pr * (1.0 + progress);

    // Smooth coupling of residual tightness with stream progress:
    // late in stream, tight fits matter more
    let tightness = 1.0 - norm_pr;
    score -= 14.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space: small post residual that likely can't fit future items
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let unusable = ((nx - pr) / cap).max(0.0);
        score += 22.0 * unusable * (0.4 + progress);
        // Reward leaving room for the lookahead item
        let fit_next = (pr - nx).max(0.0) / cap;
        score -= 12.0 * fit_next.sqrt();
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 9.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins
    score += 0.35 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins below mean residual (tighter)
    score += 0.5 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo common item sizes
    // Small residues that no item can use are dead space -> penalize.
    let r = post_residual;
    if r > 0 {
        // dead-space penalty: residue below smallest item (1..10) is unusable
        if r < 10 {
            score += 40.0 - 4.0 * r as f64;
        }
        // harmonic classes: residues divisible by common sizes are reusable
        let reusable = (r % 10 == 0) || (r % 20 == 0) || (r % 25 == 0) || (r % 50 == 0);
        if reusable {
            score -= 6.0;
        } else if r % 5 == 0 {
            score -= 3.0;
        } else {
            score += 4.0;
        }
    } else {
        // perfect fit is ideal
        score -= 100.0;
    }

    // Integer-division threshold classes on post_residual
    let q = r / 20; // coarse class 0..5
    score -= q as f64 * 2.5; // larger usable chunks preferred

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size <= r {
        if next_item_size == r {
            score -= 50.0;
        } else {
            let next_post = r - next_item_size;
            score -= 8.0 + (next_post as f64).min(20.0) * 0.5;
            // harmonic match: next_post reusable?
            if next_post % 10 == 0 { score -= 5.0; }
        }
    } else if next_item_size > r && next_item_size > 0 {
        // next item won't fit here: this bin becomes dead-end sooner
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): prefer it only when this placement is bad
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: its post_residual equals capacity - item
        score += 12.0;
        // but if current bin would leave tiny dead space, new bin is attractive
        if r > 0 && r < 15 {
            score -= 20.0;
        }
        if open_bins_count > 12 {
            score -= 5.0; // consolidate when many bins open
        }
    }

    // Phase-aware: late in stream, waste matters more
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - phase) * 0.0 + phase * (r as f64) * 0.05;

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
