        score += 20.0 + 15.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin helps chain the next item
        }
    }

    // Prefer bins whose post-residual can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    score
