    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) + norm_pr * (0.5 + 2.0 * progress * (1.0 - progress));
    score += 20.0 * poly;

    // Tight fits are valuable; reward smooth in residual
    let tight = ((bin_residual - item_size) as f64 / cap).powi(3);
    score -= 15.0 * tight;

    // Last-chance bonus: avoid opening a new bin when only this bin fits
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    }

    // Lookahead: favor bins whose post residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            score += 5.0 * ((nxt - pr) / cap);
        }
    }

    // Prefer filling bins with large residuals when many bins are open
    let open_f = open_bins_count as f64;
    score -= 2.0 * (mean_residual / cap) * (1.0 - norm_pr) * (open_f / (open_f + 5.0));

    // Mild new-bin penalty grows with stream progress
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo small divisors: residues that
    // commonly reoccur in item streams are "usable" dead space, others are dead.
    let r = post_residual;
    let mod5 = (r % 5) as f64;
    let mod10 = (r % 10) as f64;
    let mod20 = (r % 20) as f64;

    // Penalize awkward residues (non-representable by common item sizes 1..100
    // drawn from arbitrary distributions: multiples of 5/10 are safer targets).
    if r > 0 {
        if mod5 > 0.0 { score += 6.0; }
        if mod10 > 0.0 { score += 3.0; }
        if r < 10 { score += 14.0; } // unusable sliver for most items
        else if r < 20 { score += 5.0; }
    }

    // Integer-division threshold: post_residual exactly matching a harmonic
    // fraction of capacity is a great landing spot.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if r == 0 { score -= 25.0; }             // perfect fill
    else if r == quarter { score -= 8.0; }
    else if r == half { score -= 4.0; }

    // Lookahead coupling: if next item fits into post_residual, reward strongly.
    if next_item_size > 0 && next_item_size <= r {
        let slack_ratio = (r - next_item_size) as f64 / bin_capacity as f64;
        score -= 12.0 * (1.0 - slack_ratio);
    } else if next_item_size > r {
        score += 4.0; // next item won't reuse this bin's leftover
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only attractive when all open bins fit badly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // base cost of a fresh bin, discounted when no open bin can fit
        score += 30.0 * (1.0 - pressure);
        if pressure > 0.0 { score -= 20.0; }
    }

    // Late-stream tightening: waste matters more as the stream nears its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins tighter than the mean residual (best-fit bias).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    // (items are >= 10 in the canonical setting; small gaps are dead space).
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits (small positive residual) super-linearly.
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 12.0 * tightness * tightness;
    }

    // Penalize blocking a bin that could fit the next item with this placement.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && (bin_residual as u32) >= next_item_size {
        score += 8.0;
    }
    // Reward placements that still leave room for the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // allow consolidation into emptier bins.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += 0.5 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when this bin would be a terrible fit
    // (i.e. we bias against opening new bins unless nothing else works).
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If the item is large relative to mean residual, opening fresh is fine.
        if (item_size as f64) > mean_residual + 10.0 {
            score -= 35.0;
        }
    }

    // Mild stream-progression term: later in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect chain fit: next item exactly fills the post residual.
        if (post_residual as u64) == (next_item_size as u64) {
            score -= 40.0;
        } else if post >= nxt {
            // Next item still fits: reward closeness of the match.
            let gap = post - nxt;
            score -= 12.0 - (gap / 20.0).min(10.0);
        } else {
            // Next item will NOT fit here: penalize dead space relative to gap.
            score += (nxt - post) * 0.35;
        }

        // Coupling with mean residual: a bin whose post residual deviates
        // far below the mean is creating fragmented space.
        let dev = (post - mean_residual).abs();
        score += dev * 0.08;
    }

    // Reward exact fill.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize tiny unusable dead space (waste pockets).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when post_residual is large
    // (i.e., item is small relative to a fresh bin) or current bin leaves
    // very fragmented space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer reusing bins early; allow new bins more later in the stream.
        score += 30.0 - 15.0 * progress;
        // If the item leaves a huge residual in a fresh bin AND the next item
        // is large enough to pair with it, a new bin may be reasonable.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 10.0;
        }
    }

    // Mild pressure against hoarding many open bins with large residuals.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored: reward small post_residual non-linearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score -= (1.0 - pr / cap).powi(3) * 30.0;

    // Penalize dead space that no plausible future item can use.
    if pr > 0.0 && pr < 10.0 {
        score += 25.0; // tiny unusable sliver
    }
    if next_item_size > 0 && (next_item_size as f64) > pr {
        // Post-residual cannot host the next item: penalize proportionally.
        score += ((next_item_size as f64 - pr) / cap) * 20.0;
    } else if next_item_size > 0 {
        // Perfect or near-perfect lookahead fit: strong reward.
        let gap = (pr - next_item_size as f64) / cap;
        score -= (1.0 - gap).powi(2) * 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins relative to the average residual of open bins.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += dev * 15.0; // below-mean residual (fuller bin) lowers score
    }

    // New-bin candidate handling: only attractive early in the stream or
    // when the item fits badly everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = pr > 40.0; // large hole left behind
        let many_open = open_bins_count as f64;
        score += 10.0 + progress * 30.0 - many_open * 0.5;
        if bad_fit { score -= 5.0; } // opening a bin beats wrecking an open one
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 8.0; // fresh bin can also serve the next item
        }
    }

    // Mild preference to consolidate into bins that are already partially full
    // as the stream matures (reduce open-bin sprawl).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / cap) * (5.0 + 10.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling: post_residual normalized, squared/cubic shaping
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;

    // Quadratic penalty on dead space (convex: large residuals hurt super-linearly)
    score += 40.0 * pr_norm * pr_norm;

    // Cubic term coupling with stream progress: dead space matters more late in stream
    score += 60.0 * pr_norm * pr_norm * pr_norm * (0.5 + progress);

    // Perfect fit reward (smooth, near-zero residual strongly favored)
    let fit_quality = 1.0 - pr_norm;
    score -= 25.0 * fit_quality * fit_quality * fit_quality * fit_quality;

    // Lookahead coupling: reward if next item fits smoothly in post_residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            let slack = (pr - ns) / bin_capacity as f64;
            score -= 15.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // next item can't fit here: mild penalty scaled by overflow amount
            score += 8.0 * ((ns - pr) / bin_capacity as f64);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening bins when good fits exist
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 35.0 + 40.0 * scarcity * (1.0 - progress);
        // late in stream, opening bins is cheaper than wasting space
        score -= 25.0 * progress * progress;
    }

    // Mean-residual coupling: prefer bins below mean residual (denser bins)
    score += 0.3 * (mean_residual - pr);

    // Tie-break toward fewer open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact "perfect" fills and small dead zones
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward near-tight packing heavily
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Dead-space penalty: residual that is hard to reuse (small odd slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Modulo arithmetic on post_residual: classes of 10 (capacity fractions)
    let class = post_residual / 10;
    score += (class as f64) * 2.0;

    // Harmonic bonus: residual exactly divisible by common item sizes (10,20,25,50)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    } else if post_residual % 25 == 0 {
        score -= 15.0;
    } else if post_residual % 20 == 0 {
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: prefer leaving divisible-friendly residual
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 60.0;
            } else {
                score -= (20.0 - gap as f64 * 0.5).max(0.0);
            }
        } else {
            // next item will NOT fit here: penalize leaving large unusable residual
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Prefer bins tighter than the mean residual
    score += (mean_residual - pr) * 0.5;

    // Mild pressure to keep number of open bins low
    score += (open_bins_count as f64) * 0.5;

    // Progress-based tuning: later in stream, prioritize tightness more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: neutral baseline, only chosen if all open bins look bad
    if bin_residual == bin_capacity {
        score = 250.0 + pr * 0.1 - (next_item_size as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item are "dead". Penalize them quadratically.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) > 0.0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 40.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // If next item cannot fit in post residual but could fit elsewhere,
    // slightly penalize leaving a residual that blocks the lookahead.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new bins
    // (make the empty-bin candidate expensive) and encourage consolidation.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure proportional to open bins.
        score = bin_capacity as f64 + (open_bins_count as f64) * 8.0;
        // But if no existing bin fits well and residual would be tiny dead space,
        // opening a bin becomes attractive: relax the cost.
        let worst_case_dead = (bin_residual >= item_size) && (post_residual as f64) < dead_threshold;
        if worst_case_dead && open_bins_count > 0 {
            score -= 30.0;
        }
        // Late in the stream, avoid sprawling new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    } else {
        // Existing-bin consolidation bonus scaled by open-bin pressure.
        score -= (open_bins_count as f64).min(10.0) * 1.5;
        // Prefer bins with below-mean residual (fill the emptier ones first).
        if (bin_residual as f64) > mean_residual {
            score += 4.0;
        } else {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear urgency
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // 2-step lookahead: perfect match between post_residual and next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Chain fit: this bin will be exactly filled by the next item
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item also fits here: good, but less attractive than perfect match
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.35;
        } else {
            // Next item won't fit in the leftover: penalize dead space proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative-to-mean coupling: bins below mean residual are already well used;
    // dumping an item there may create unusable residue elsewhere.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 {
            (next_item_size as f64 / bin_capacity as f64).powf(2.0)
        } else {
            0.0
        };
        score += 20.0 + open_bins_count as f64 * 0.5 - pressure * 10.0;
    }

    // Late-stream consolidation: toward the end, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional tightness of fit: how well the item fills the bin's residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    // Reward near-perfect fits (fit_ratio close to 1)
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to ever hold another item (min item = 1)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how much of the post-residual next item uses
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the leftover: penalize wasted space scaled by waste
            score += 8.0 * (next_item_size as f64 - post_residual as f64).min(40.0) / 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly or are fragmented
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted when many items remain
        score = bin_capacity as f64 * 0.9;
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // if no open bin truly fits well (all fits are loose), opening is fine
        let loose_fits = (fitting_bins_count as f64) * 20.0;
        score -= pressure * 80.0;
        score -= t * 20.0; // late in stream, keep bins closed less
        score += loose_fits.min(80.0);
        // if mean residual is small, existing bins are nearly full -> new bin attractive
        score -= (100.0 - mean_residual).max(0.0) * 0.3;
        // many open bins: discourage spreading
        score += open_bins_count as f64 * 2.0;
    }

    // Prefer bins whose residual is close to the mean (balanced usage) slightly
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild penalty on very loose fits late in the stream (fragmentation control)
    if fit_ratio < 0.5 && t > 0.5 {
        score += 15.0 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Smooth non-linear tightness reward: strongly favor small post_residual.
    let tightness = 1.0 - (pr / cap);
    score -= 25.0 * tightness * tightness * tightness;

    // Coupling with stream progress: as stream advances, prioritize tight fits more.
    score -= 15.0 * progress * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Penalize opening a new bin when other bins fit reasonably well.
    if bin_residual == bin_capacity {
        let mean_fit_gap = if mean_residual > 0.0 { (mean_residual - item_size as f64).max(0.0) } else { 0.0 };
        let waste_penalty = (mean_fit_gap / cap).powf(2.0) * 40.0;
        score += 20.0 + waste_penalty + 10.0 * (1.0 - progress);

        // Lookahead: if next item fits the new-bin residual, soften the penalty.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let pair_fill = 1.0 - ((pr - nxt) / cap);
                score -= 25.0 * pair_fill * pair_fill;
            } else {
                score += 15.0;
            }
        }
    } else {
        // Lookahead synergy: reward leaving a residual that fits the next item.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if pr >= nxt {
                let synergy = 1.0 - ((pr - nxt) / cap);
                score -= 12.0 * synergy * synergy;
            } else {
                // Dead space penalty: residual too small for the next item.
                let dead = (pr / nxt).min(1.0);
                score += 8.0 * dead * dead;
            }
        }
    }

    // Mild penalty for residual far from common small item sizes (fragmentation risk).
    let frag = (pr / cap - 0.5).abs();
    score += 6.0 * frag * frag * (1.0 - progress);

    // Slight preference for consolidating into fewer bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 5, and small residues) get rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual divisible by 10 -> perfect harmonic slot
    if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 6.0;
    }

    // Dead-space penalty: leftover too small for the smallest plausible item
    if post_residual < 5 && post_residual > 0 {
        score += 25.0;
    }

    // Fractional fill: reward tight fits (item occupies most of the residual)
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // harmonic compatibility: next divides post_residual or near match
            let diff = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - diff / cap);
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: leftover is dead for the lookahead
            score += 6.0 + 0.1 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): only attractive when open bins are crowded
    // or mean residual is too small to hold future items well.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).max(0.0);
        // open new bin when existing residuals are mostly consumed or few bins
        score = 40.0 - 30.0 * pressure;
        if open_bins_count == 0 {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
    }

    // Stream progression: later in stream, consolidate more aggressively
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - pr / cap);

    // Prefer bins below mean residual (balancing harmonic spread)
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    } else if post_residual <= 20 {
        // Moderately small gaps: penalize proportionally harder near zero.
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward bins whose residual tightly matches the item (good fit quality).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let pressure = open_bins_count as f64 * 3.0;
        score += 15.0 + pressure;
        // Late in the stream, strongly prefer closing out existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    } else {
        // Slight reward for using existing bins, stronger when it's the last chance.
        if fitting_bins_count == 1 {
            score -= 18.0;
        } else {
            score -= 4.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is very attractive (chains two items).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; mildly penalize leaving large-but-unusable-for-next gaps.
        score += 3.0;
    }

    // Prefer bins with below-mean residual (consolidate space elsewhere).
    score += 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if current open bins are too full
        // to offer good future packing. Base cost of a fresh bin.
        let mut new_bin_score = bin_capacity as f64 * 0.75;
        // If few bins can fit the item, opening fresh is more defensible.
        if fitting_bins_count <= 1 {
            new_bin_score -= 30.0;
        }
        // If mean residual across open bins is large, prefer reusing them.
        new_bin_score += mean_residual * 0.4;
        // Later in the stream, avoid opening extra bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += progress * 20.0;
        // A fresh bin has perfect room for the next item too.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            new_bin_score -= 5.0;
        }
        return new_bin_score;
    }

    // --- Aggressive 2-step lookahead matching on open bins ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step match: consume residual exactly with next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement: good.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0;
            // Mild penalty proportional to leftover slack beyond next item.
            score += slack * 0.15;
        } else {
            // Dead space: next item cannot use what remains.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.5;
        }
    } else {
        // Last item: just minimize waste.
        score += (bin_capacity as f64 - post_residual as f64) * 0.1;
    }

    // Relative-to-mean coupling: bins tighter than the mean are precious,
    // fill them; bins looser than the mean can absorb awkward items.
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.2;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 3.0;
    }

    // Slight preference to keep many open bins from accumulating.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (low post residual), with a non-linear bonus.
    let tightness = 1.0 - post / cap;
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post >= 10.0 && post <= 20.0 {
        score -= 8.0; // usable mid-range leftover is fine
    }

    // Lookahead coupling: reward leaving a gap that the next item can fill.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 * (next_item_size as f64) / cap;
    } else if next_item_size > 0 && post_residual > 0 {
        // leftover can't host next item: mild penalty scaled by wasted fraction
        score += 5.0 * (post / cap);
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && post_residual < item_size {
        score -= 30.0;
    }
    if fitting_bins_count == 0 && bin_residual == bin_capacity {
        // new-bin candidate: neutral baseline; slight penalty so real bins win when decent
        score += 12.0;
    }

    // Time horizon: late in the stream, consolidate harder (favor existing bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 6.0 * progress;
    }

    // Bin-count pressure: many open bins -> favor filling existing ones.
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Global residual state: if mean residual is high, prefer bins below average
    // (drain the small ones first to close them out).
    let mean = mean_residual;
    let post_dev = post - mean;
    score += 0.05 * post_dev;

    // Prefer bins whose residual is close to item size (perfect fit).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial coupling to progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Non-linear penalty for awkward residuals (dead space near mid-range)
    let mid = norm_pr - 0.5;
    score += 30.0 * mid * mid * (1.0 - progress);

    // Reward tight fits more strongly as stream progresses
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 15.0 * (nx / cap);
        } else {
            score += 8.0 * (nx / cap);
        }
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening new bins unless residuals are poor
    if bin_residual == bin_capacity {
        let avg_tight = (mean_residual / cap).max(0.0);
        score = cap * (1.0 + 0.3 * progress) - 15.0 * avg_tight;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    // Smooth dispersion penalty relative to mean residual
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fit classes are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect closure
    } else if pr <= 10 {
        score -= 60.0; // near-perfect fit, dead space negligible
    } else {
        // Modulo classes: residuals divisible by common small item sizes
        // (e.g. multiples of 20/25/50) are re-usable "harmonic" slots.
        if pr % 50 == 0 { score -= 45.0; }
        else if pr % 25 == 0 { score -= 35.0; }
        else if pr % 20 == 0 { score -= 30.0; }
        else if pr % 10 == 0 { score -= 20.0; }
        else { score += 8.0; } // inharmonic residual: likely dead space
    }

    // Penalize large unusable leftovers via quadratic term on capacity fraction.
    let frac = pr as f64 / cap;
    score += 40.0 * frac * frac;

    // Lookahead coupling: reward leaving a residual that the next item can fill
    if next_item_size > 0 && pr >= next_item_size {
        let slack = (pr - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / cap);
        if slack as u32 % 10 == 0 { score -= 10.0; }
    } else if next_item_size > pr && pr > 0 {
        // next item won't fit here; residual becomes a waiting dead slot
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or
    // open bins are crowded; otherwise discourage proliferation.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a bin
        } else if pressure < 0.25 && open_bins_count < 8 {
            score -= 30.0; // cheap to open early when bins are fresh
        } else {
            score += 60.0 + 10.0 * open_bins_count as f64;
        }
    }

    // Mild late-stream tightening: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize residual gaps that are
    // likely unusable (too small for typical minimum items).
    let dead_zone: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 40.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Penalize bins whose residual deviates far from the mean residual
    // (prefer keeping the bin pool homogeneous).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.5;

    // Open-bin pressure: penalize opening new bins when many bins are open.
    let new_bin_candidate = bin_residual == bin_capacity;
    if new_bin_candidate {
        score += open_bins_count as f64 * 8.0;
        score += 15.0; // base bias against opening a new bin
    } else if fitting_bins_count == 1 {
        // Last chance: strongly favor using this bin.
        score -= 50.0;
    }

    // Lookahead coupling: if the next item can use the post_residual,
    // reward leaving exactly that much space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 20.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // residual smaller than next item: dead space for lookahead
            score += 10.0;
        }
    }

    // Late in the stream, consolidate: slightly stronger new-bin penalty.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Exact match: chain the two items perfectly -> strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits too, but leaves a new residual: reward proportionally
            // to how tight the two-step chain is.
            let two_step_final = post - nxt;
            score -= 25.0 * (1.0 - two_step_final / bin_capacity as f64);
            // Extra reward if the two-step final residual is small (near-perfect chain).
            if two_step_final < 10.0 {
                score -= 15.0;
            }
        } else {
            // Next item will NOT fit here: post_residual becomes dead space.
            // Penalize dead space relative to next item size (wasted gap).
            let gap = nxt - post;
            score += 0.8 * gap.min(60.0);
        }

        // Coupling with mean residual: a post_residual far below mean means this bin
        // is being closed out well; far above mean means it stays a loose bin.
        let dev = post - mean_residual;
        score += 0.3 * dev.abs().min(50.0) * if dev > 0.0 { 1.0 } else { -0.5 };
    } else {
        // No lookahead available: just prefer tight fits.
        score += 0.1 * (post_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else (post_residual here is large) or when the
    // lookahead chains perfectly from a fresh bin.
    if bin_residual == bin_capacity {
        let fresh_chain = next_item_size > 0 && post_residual == next_item_size;
        if fresh_chain {
            score -= 55.0; // fresh bin enables a perfect 2-item chain
        } else {
            // Keep new bins slightly unattractive by default; scale with open count
            // to discourage bin proliferation when existing bins suffice.
            score += 10.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Mild stream-progression adaptation: later in the stream, tighten packing
    // (penalize residual more) since fewer chances remain to consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer bins leaving small post-residual, but only if the gap is "useful"
    // (a future item could still fit) or exactly zero (perfect fit).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize post_residual that cannot accommodate the lookahead item:
        // that dead space is likely wasted.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 0.6 * post_residual as f64;
        } else if next_item_size > 0 {
            // Residual that exactly hosts the next item is excellent.
            if post_residual == next_item_size {
                score -= 40.0;
            } else {
                score -= 0.25 * post_residual as f64;
            }
        }
    }

    // Tightness relative to the current bin: prefer filling a bin deeply.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * (1.0 - progress);
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // bins fit poorly (large post_residual relative to capacity) or few bins are open.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: keeps full residual, mildly penalized.
        score = bin_capacity as f64 * 0.55;
        // Early in the stream or with few open bins, a new bin is cheap.
        score -= 15.0 * (1.0 - progress);
        if open_bins_count <= 2 {
            score -= 10.0;
        }
        // If the item fits snugly in a fresh bin and the lookahead also fits, favor it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        // Many open bins with slack: discourage proliferation.
        if open_bins_count as f64 > 4.0 + 6.0 * progress {
            score += 18.0;
        }
    } else {
        // Existing bin: reward when its residual is below the mean (it is "tighter"
        // than average), encouraging consolidation of slack.
        let dev = mean_residual - bin_residual as f64;
        score -= 0.35 * dev;
    }

    // Late-stream urgency: as the stream ends, avoid creating tiny useless gaps.
    if next_item_size == 0 {
        score += 0.8 * post_residual as f64;
    }

    // Mild global pressure: more open bins -> prefer consolidating into existing ones.
    score += 0.15 * open_bins_count as f64 * (bin_residual != bin_capacity) as i32 as f64;

    // Non-linear coupling: penalize medium-sized dead space (hard to fill later)
    // using a bump function around half-capacity residuals.
    let pr = post_residual as f64;
    let bump = (-((pr - 45.0).powi(2)) / 400.0).exp();
    score += 10.0 * bump;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fits; late in the stream, tolerate larger residuals less.
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * (0.5 + 0.5 * progress);
    score += 30.0 * poly;

    // Reward near-perfect fills (small post residual) with a smooth quadratic bonus.
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.4 + 0.6 * progress);

    // Lookahead: penalize if the residual cannot fit the next item (dead space),
    // reward if it can (smooth interaction with post_residual size).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 12.0 * (1.0 - pr / nxt) * (0.5 + 0.5 * progress);
        } else {
            score -= 8.0 * (nxt / pr.max(1.0)) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - pr_norm);
    }

    // Penalize opening a brand-new bin unless existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let frag = mean_residual / cap;
        score += 45.0 - 25.0 * frag * frag;
    } else {
        // Slight bonus for placing into bins with residual near the mean (balance).
        let dev = (pr - mean_residual).abs() / cap;
        score += 6.0 * dev;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // small classes (0, or divisible by common item sizes) are favored.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        let pr = post_residual;
        // dead-space penalty grows superlinearly for mid-range residuals
        score += (pr as f64 / bin_capacity as f64).powf(1.7) * 40.0;

        // reward residuals that are reusable by small/medium items (mod classes)
        if pr % 10 == 0 {
            score -= 8.0;
        }
        if pr >= 10 && pr <= 20 {
            score -= 6.0; // small but potentially usable
        }
        if pr > 60 && pr < 90 {
            score += 5.0; // awkward mid gap: neither small nor reusable
        }

        // lookahead coupling: can next item fit exactly-ish into post_residual?
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 45.0;
            } else if next_item_size <= pr {
                let slack = (pr - next_item_size) as f64;
                score -= 20.0 - slack * 0.15;
                // harmonic bonus if next item divides nicely into the slack chain
                if pr % next_item_size.max(1) == 0 {
                    score -= 10.0;
                }
            } else {
                score += 10.0; // next item cannot use this bin's leftover
            }
        }
    }

    // last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }
    if fitting_bins_count > 1 {
        score += 3.0; // mild penalty to spread competition
    }

    // new-bin candidate handling
    if bin_residual == bin_capacity {
        // opening a new bin is only attractive when the item is large and
        // current open bins have small mean residual (poor fits)
        let large_item = item_size > bin_capacity / 2;
        let poor_open = mean_residual < item_size as f64 * 1.2;
        if large_item && poor_open {
            score -= 25.0;
        } else {
            score += 50.0 + open_bins_count as f64 * 0.0; // default: prefer existing bins
        }
    }

    // stream progression: late in stream, tighten up (avoid many tiny leftovers)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (mean_residual - post_residual as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 2.0 * post_residual as f64;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // Gap too small for the next item: penalize proportionally to how
            // close it is to being useless.
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Tightness reward: fraction of the bin consumed by this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Open-bin pressure: with many open bins, discourage spreading across
    // bins unless the fit is excellent; favor filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.15 + 0.35 * progress);
    score += pressure * (1.0 - tightness);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: an empty bin is only attractive when the item
    // would leave a large residual in an existing bin or no bin fits well.
    if bin_residual == bin_capacity {
        let existing_waste = (mean_residual - post_residual as f64).max(0.0);
        // Base cost of opening a new bin, discounted as stream progresses
        // (fewer future items to amortize).
        score += 18.0 + 20.0 * (1.0 - progress);
        // Discount new-bin cost if existing bins would be badly fragmented.
        score -= 0.4 * existing_waste;
        // If the item fits almost perfectly in an open bin, don't open new.
        if post_residual < 15 && fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is near
    // the mean (keeps bins balanced, avoids extreme fragmentation).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (minimal dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly or closely matches the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 500.0;
        } else if diff <= 5 {
            score -= 150.0;
        } else if diff <= 15 {
            score -= 50.0;
        } else {
            // Penalize post_residual that is just barely unusable
            // for the next item (dead space trap).
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
        // If next item won't fit anywhere else after this placement,
        // strongly prefer a bin leaving enough room.
        if post_residual >= next_item_size && fitting_bins_count <= 2 {
            score -= 60.0;
        }
    }

    // Compare post_residual to mean residual: prefer bins whose leftover
    // is close to the average (keeps bin portfolio balanced), but avoid
    // leaving tiny unusable slivers below the minimum item size (1).
    let pr = post_residual as f64;
    if pr < 1.0 {
        score += 300.0; // impossible, guard
    }
    let dev = (pr - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strongly prefer using the only fitting bin
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize placing into a new empty bin unless current open bins
    // are all poor fits (post_residual very large relative to capacity).
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty so open bins with decent
        // fit win; relax when few bins open or fit is terrible elsewhere.
        let mut new_bin_penalty = 250.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // Opening a fresh bin keeps a clean 100 residual for the
            // next (possibly larger) item.
            new_bin_penalty -= 100.0;
        }
        if open_bins_count == 0 {
            new_bin_penalty = 0.0;
        }
        score += new_bin_penalty;
    } else {
        // Mild preference for fuller bins (waste-minimization).
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Early in stream: be slightly more willing to open bins (spread risk).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }
    // Small residual is risky dead space unless a known next item fits it
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += dead * 40.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0; // lookahead: next item can use the leftover
        }
        if next_item_size > post_residual {
            score += dead * 30.0; // leftover unusable by next item
        }
    }

    // Tightness of current fit: reward snug placements
    let snug = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= snug * 10.0;

    // Last-chance bin: strongly prefer using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin, more when fits exist or few items remain
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 80.0 + 60.0 * (1.0 - progress);
        if fitting_bins_count > 1 {
            score += 50.0;
        }
        // opening a bin is fine if open bins are cluttered with big residuals
        if mean_residual > 40.0 && open_bins_count > 2 {
            score -= 40.0;
        }
    }

    // Global state coupling: many open bins with small mean residual -> consolidate
    let open_f = open_bins_count as f64;
    let mr = mean_residual.max(0.0);
    let consolidation = (mr / bin_capacity as f64) * (open_f / (open_f + 5.0));
    score -= consolidation * 20.0;

    // Time horizon: early stream, be flexible; late stream, fill bins tightly
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 12.0 * snug;
    score += (1.0 - progress) * 5.0 * (1.0 - snug);

    // Prefer bins whose residual is close to item (avoid wasting large residual on small item)
    if bin_residual > item_size {
        let waste_ratio = item_size as f64 / bin_residual as f64;
        score += (1.0 - waste_ratio) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with progress
    let tightness = 1.0 - norm_pr; // fraction of bin filled after placement
    let coupling = (tightness * tightness) * (1.0 + 2.0 * progress) - (norm_pr * norm_pr) * (0.5 + progress);
    score -= 40.0 * coupling;

    // Penalize large dead space, more so later in the stream
    score += 25.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward near-perfect fits smoothly
    let fit_quality = 1.0 - (norm_pr * 4.0 - 1.0) * (norm_pr * 4.0 - 1.0);
    score -= 15.0 * fit_quality.max(0.0);

    // Lookahead: reward residual that can fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = norm_pr - nxt;
        if gap >= 0.0 {
            score -= 12.0 * (1.0 - gap) * (1.0 + progress);
        } else {
            score += 8.0 * (-gap) * (1.0 + progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 6.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into a
    // "usable" class (large enough for typical small items) are rewarded.
    let post = post_residual;
    let class = match post {
        0 => 0u32,                 // perfect fit
        1..=10 => 1,               // dead space
        11..=25 => 2,              // small-item slot
        26..=50 => 3,              // medium slot
        _ => 4,                    // large slot
    };
    score -= match class {
        0 => 60.0,
        1 => -25.0, // penalize: dead space is worse than base residual suggests
        2 => 8.0,
        3 => 15.0,
        _ => 22.0,
    };

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post {
        let slack = (post - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / cap);
        if post == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > post {
        // next item cannot use this bin's leftover: leftover is likelier dead
        score += 12.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else {
        // More competing bins: slight penalty for wasting alternatives.
        score += 2.0 * (fitting_bins_count as f64).min(5.0);
    }

    // Prefer bins tighter than average (good fit relative to fleet).
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Progress modulation: early on, keep bins flexible (favor larger post residual);
    // late in stream, squeeze hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.15 * post_residual as f64;
    score -= progress * 10.0;

    // Modulo-based harmonic preference: residuals that are multiples of common
    // item sizes (10/20/25/50) are more reusable.
    if post > 0 && (post % 10 == 0 || post % 25 == 0) {
        score -= 6.0;
    }

    // New-bin candidate: only open a new bin when existing fits are terrible
    // (item barely fits nowhere well or all fits leave dead space).
    if bin_residual == bin_capacity {
        let poor_existing = fitting_bins_count == 0
            || (post_residual == 0 && item_size >= 1);
        // New empty bin base score: residual is full capacity, so make it
        // competitive only if existing fits would waste a lot.
        score = cap * 0.55 + if poor_existing { -30.0 } else { 15.0 };
        if next_item_size > 0 && next_item_size > item_size && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // room for a bigger follower
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity_f = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that are too small for any item
    // (items are >= 1, but tiny gaps < ~10 are statistically near-unusable)
    // are heavily penalized.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 6.0; // up to +60 dead-space penalty
    }

    // Reward tight fits: the smaller post_residual relative to item size,
    // the better the packing density.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Perfect-fit bonus: item exactly fills the bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into this bin's post_residual,
    // reward; if it nearly fits (within 5), mild reward; otherwise mild penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0;
        } else if nxt - post <= 5.0 {
            score -= 4.0;
        } else {
            score += (nxt - post).min(20.0) * 0.3;
        }
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // (applies to the new-bin candidate where residual == capacity).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 3.0
            + (mean_residual / capacity_f) * 20.0;
        score += pressure.max(0.0);
    } else {
        // Using an existing bin slightly relieves open-bin count pressure.
        score -= 2.0;
    }

    // Late-stream tightening: as the stream progresses, prefer tighter fits
    // to consolidate residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * fit_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
