}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let waste_after_pair = post_residual - next_item_size;
            score -= 10.0 * (1.0 - waste_after_pair as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slightly penalize leaving medium dead space.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 && dead > 0.0 {
                score += 3.0 * (1.0 - dead / (next_item_size as f64));
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when many bins have generous residuals already.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_gap = mean_residual - post_residual as f64; // mean residual of open bins vs fresh residual
        let mut new_bin_score = 20.0;
        new_bin_score += mean_gap * 0.3;
        new_bin_score += open_bins_count as f64 * 0.8;
        new_bin_score *= 0.5 + 0.5 * progress;
        score += new_bin_score;
    }

    // Mild penalty when this bin's residual deviates far above the mean (fragmenting outlier).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling bins that are already quite full (keep many partially empty bins flexible).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear waste term: quadratic in post_residual, amplified as stream progresses.
    let norm_post = post / cap;
    score += norm_post * norm_post * cap * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth saturating bonus.
    score -= (1.0 - norm_post).exp() * 8.0 * (0.5 + 0.5 * progress);

    // Penalize bins whose residual is far from mean residual (fragmentation avoidance).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev.abs() * 5.0 * (0.3 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let gap = (post - nx) / cap;
            score -= 10.0 * (1.0 - gap * gap);
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            score += ((nx - post) / cap) * 4.0;
        }
    }

    // Mild penalty for spreading across too many open bins early on.
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    // New-bin candidate: keep it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 8.0 * (1.0 - norm_post);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that land in "usable" buckets
    // (multiples of 10 and 5 are easier to fill for integer item sizes).
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else if pr % 10 == 0 {
        score -= 12.0;
    } else if pr % 5 == 0 {
        score -= 6.0;
    } else if pr < 10 {
        score += 25.0; // dead space: too small for any item (min size 1..100 unknown, penalize tiny slivers)
    } else {
        score += 4.0; // awkward non-harmonic residual
    }

    // Integer-division threshold: can the lookahead item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0; // chainable bin: keeps next item here
            // Harmonic bonus if next item also lands on a nice class
            let nxt = pr - next_item_size;
            if nxt % 10 == 0 { score -= 5.0; } else if nxt % 5 == 0 { score -= 2.5; }
        } else {
            score += 8.0; // next item will need another bin anyway
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer open bins unless this bin is nearly full
    // and the new bin offers a clean harmonic start.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, modulated by stream progress and congestion.
        score = bin_capacity as f64 + 15.0
            + (step_index as f64 / total_items.max(1) as f64) * 20.0
            + open_bins_count as f64 * 2.0;
        // Open a fresh bin if existing fits are all poor (high mean residual waste vs item)
        if fitting_bins_count > 0 {
            let tight = (bin_residual as f64 - item_size as f64).abs();
            if tight > 30.0 && mean_residual < item_size as f64 {
                score -= 35.0; // allow opening when fits are wasteful
            }
        } else {
            score -= 60.0; // no alternative
        }
    } else {
        // Prefer tighter fits among open bins: penalize large pre-fit slack
        score += (bin_residual - item_size) as f64 * 0.15;
        // Congestion-aware: if many bins open and this one is slack-heavy, discourage
        if open_bins_count > 4 && (bin_residual as f64) > mean_residual + 20.0 {
            score += 6.0;
        }
    }

    // Small deterministic tie-breaker via modulo class of item_size
    score += (item_size % 7) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (small post_residual) more aggressively.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_frac * 30.0;

    // Lookahead: if the next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Leaves a gap the next item cannot use; mild penalty.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score -= pressure * 2.0;

    // New-bin candidate handling: an empty bin should only win when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.55 + open_bins_count as f64 * 3.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        } else if next_item_size > 0 && bin_residual >= next_item_size && post_residual == 0 {
            score -= 20.0; // perfect fit for next item in a fresh bin
        }
        // If mean residual across open bins is large, opening new bins is less attractive.
        score += mean_residual * 0.35;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u64 >= next_item_size as u64 {
            // Next item fits exactly into this bin afterwards -> strong reward.
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 25.0; // perfect 2-chain
            }
        } else {
            // Next item would NOT fit after placing here: penalize proportionally.
            score += 8.0 + 0.1 * (nxt - post_residual as f64);
        }
    }

    // Tight fit reward: small post residual is good, but avoid tiny unusable slivers
    // unless they are zero.
    let pr = post_residual as f64;
    if pr == 0.0 {
        score -= 20.0; // perfect closure
    } else if pr < 10.0 {
        score += 6.0; // dead space sliver (below min item size)
    }

    // Compare residual against mean residual across open bins:
    // prefer bins whose residual is close to item size (good fill).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Late in stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score += 18.0 - 25.0 * crowding;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin can host the chain of large items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here: slight penalty proportional to overflow
            score += 3.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Time horizon: early in the stream, be pickier (prefer tight fits, allow new bins);
    // late in the stream, consolidate into open bins to cap total count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (fitting_bins_count as f64).max(1.0).ln();

    // Global state: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 4.0 * (mean_residual - item_size as f64) / bin_capacity as f64;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual == capacity means empty bin) or item is large.
    if bin_residual == bin_capacity {
        let escape = if fitting_bins_count == 0 { 0.0 } else {
            // competing open bins exist: new bin must look worse unless fit is poor
            let best_possible = (bin_capacity - item_size) as f64;
            (post_residual as f64 - best_possible).abs() // = 0, so use penalty below
        };
        let _ = escape;
        score += if fitting_bins_count <= 1 { 5.0 } else { 15.0 + 10.0 * (item_size as f64 / bin_capacity as f64) };
        // Late stream: opening new bins is expensive.
        score += progress * 10.0;
    }

    // Mild preference for filling larger residuals with large items.
    score -= 2.0 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling: penalize large post-residual more as stream progresses
    let pr_norm = pr / cap;
    let t = progress;
    score += (pr_norm * pr_norm) * cap * (0.5 + t);

    // Tight fits rewarded with smooth coupling to progress
    let fit = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= fit * fit * cap * (0.3 + 0.7 * t);

    // Last chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - pr_norm) * (0.5 + t);
    }

    // Lookahead coupling: reward if next item fits post-residual (smooth term)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let nx = next_item_size as f64 / cap;
        score -= 8.0 * nx * (1.0 - pr_norm) * (0.5 + 0.5 * t);
    } else if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr) / cap;
        score += 6.0 * gap * gap * cap * (0.5 + 0.5 * t);
    }

    // Discourage many open bins with large mean residual (smooth interaction)
    let open_norm = (open_bins_count as f64) / ((open_bins_count as f64) + 5.0);
    score += open_norm * (mean_residual / cap) * (pr_norm) * 10.0;

    // New-bin candidate: mildly penalize early, allow late when progress high
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - t) * (1.0 - t) - 3.0 * t * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: which quarter of the bin does the leftover live in?
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter.max(1);

    // Reward tight fits (small post_residual classes) with a strong subtractive term.
    let class_reward = match class {
        0 => 45.0,
        1 => 18.0,
        2 => 4.0,
        _ => -10.0, // penalize big leftovers (bin mostly empty after placement)
    };
    score -= class_reward;

    // Exact-fill bonus: harmonic class zero with zero remainder.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % 10 == 0 {
        // Residuals that are round multiples of 10 are reusable by typical items.
        score -= 8.0;
    }

    // Lookahead coupling: does the leftover harmonically match the next item?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chord with next item
        } else if post_residual >= next_item_size {
            // leftover can host next item: mild reward scaled by slack
            score -= 6.0 + (post_residual - next_item_size).min(20) as f64 * 0.3;
        } else {
            // next item cannot use this leftover: penalize proportionally to waste
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // current item is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score = bin_capacity as f64 * 1.5;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        } else if item_size > bin_capacity * 3 / 4 {
            // Large item in a fresh bin keeps a big residual — acceptable only if
            // existing fits are very loose.
            score -= 20.0;
        }
        // Fewer open bins relative to stream length: slightly cheaper to open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate waste).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Modulo harmonic tiebreak: residuals in [10,30) are prime reuse zones.
    if post_residual >= 10 && post_residual < 30 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: residuals that are too small for the smallest
    // possible item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // If this bin is the only one that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: if next item would fit the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap that just barely fails to hold the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; but for
    // the new-bin candidate, add pressure so new bins open only when needed.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 8.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    } else {
        score += 2.0 * open_bins_count as f64 * (1.0 - fill);
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    // (using a bin with more residual than average keeps tight bins tight).
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) relative to bin size.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly matches the next item size (perfect chained fit).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 30.0; // perfect 2-step chain: place here
        } else {
            score += gap * 0.6; // penalize mismatched leftover vs next item
        }
        // If next item fits exactly in the residual BEFORE placement, also mild bonus.
        if bin_residual == next_item_size {
            score -= 5.0;
        }
    }

    // Compare against mean residual: prefer bins with residual close to item
    // (dense packing), penalize bins that are much emptier than average.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening new bins when good fits exist, especially late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress;
        // But allow new bin if this bin would leave large dead space next step can't use.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
            score -= 15.0;
        }
    }

    // Discourage creating tiny unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste ratio non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize small unusable post-residual dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many fitting bins: mild penalty to prefer scarcer fits elsewhere.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: reward if next item fits well into post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect follow-up
        } else if next_item_size < post_residual {
            let nl = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * nl * nl;
        } else {
            // next item can't fit here: slight penalty for wasting space
            score += 0.05 * (post_residual as f64);
        }
    }

    // New-bin candidate logic: only attractive when current fit is poor
    // or no real bins fit well.
    if bin_residual == bin_capacity {
        let is_new_bin = bin_residual == bin_capacity && item_size <= bin_capacity;
        if is_new_bin {
            let poor_fit = fit_ratio < 0.5;
            let early = (step_index as f64) / (total_items.max(1) as f64);
            if poor_fit || fitting_bins_count == 0 {
                score -= 25.0 + 10.0 * early;
            } else {
                score += 20.0 + 15.0 * (1.0 - early);
            }
            // If next item is large, opening fresh bin may be wise.
            if next_item_size > item_size && next_item_size > 60 {
                score -= 12.0;
            }
        }
    }

    // Global state coupling: when mean residual is high, prefer reusing
    // bins with residuals near the mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Prefer filling bins with smaller residuals first (compactness).
    score += 0.05 * bin_residual as f64;

    // Late in stream: tighten packing more aggressively.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score -= 5.0 * progress * fit_ratio;

    // Mild penalty for too many open bins.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // base: prefer tight fits, mildly scaled by progress
    let mut score = pr * (0.5 + 0.5 * t);
    // non-linear penalty for awkward residuals that couple with progress
    let awkward = norm_pr * (1.0 - norm_pr); // peaks at half-full residual
    score += 20.0 * awkward * (0.3 + 0.7 * t);
    // reward very small residuals (near-perfect packing)
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    // lookahead: penalize if post_residual cannot host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 6.0 * (nx - pr) / cap * (1.0 + t);
        } else {
            score -= 4.0 * (1.0 - (nx / pr)) * (1.0 - t);
        }
    }
    // last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + t);
    }
    // many open bins: discourage spreading; prefer new bin when residual large
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 10.0 * crowd * norm_pr * (1.0 - norm_pr) * 4.0;
    // new-bin candidate: keep it slightly unattractive unless residual gap is huge
    if bin_residual == bin_capacity {
        score += 3.0 - 2.0 * t;
        score += 2.0 * (mean_residual / cap).min(1.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Residuals that are "harmonically compatible" with common item sizes (multiples of 10)
    // are less wasteful than awkward residuals.
    let pr = post_residual;
    let harmonic_class = (pr % 10) as f64;
    // Penalize residuals that are not multiples of 10 (dead space that rarely fits items).
    if harmonic_class != 0.0 {
        score += harmonic_class * 1.5; // awkward remainder -> dead space penalty
    }

    // Integer-division thresholds: how many "typical small items" (size ~10) fit afterwards.
    let slots = pr / 10;
    if slots == 0 {
        // Bin becomes nearly useless after placement; strong penalty unless it was a near-perfect fit.
        if pr == 0 {
            score -= 60.0; // perfect fit is ideal
        } else {
            score += 25.0;
        }
    } else {
        // Reward keeping usable capacity, with diminishing returns (harmonic-like decay).
        score -= 8.0 * (1.0 + 1.0 / (slots as f64));
    }

    // Lookahead: if next item fits the post residual exactly or well, reward this placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0; // chains a perfect fit
        } else if next_item_size <= pr {
            let waste = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - waste / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty if we leave a tempting-but-insufficient residual.
            if pr >= next_item_size / 2 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: residual == capacity means empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing fits are poor:
        // i.e., post_residual here would be large (bad packing into open bins).
        let pressure = (post_residual as f64 / bin_capacity as f64) * 40.0;
        score += 15.0 - pressure; // base cost of a fresh bin, offset by avoiding bad fits
        // If many bins are open and mean residual is high, prefer consolidating into open bins.
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            score += 12.0;
        }
    }

    // Progress term: late in the stream, be more conservative with opening bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Mild preference for tighter bins (best-fit baseline already via post_residual).
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest possible item (1) are fine (perfect fit), but "wasted" gaps
    // that nothing can tightly use get extra penalties.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 1000.0;
    } else {
        let pr = post_residual as f64;
        // Non-linear dead-space penalty: small-but-nonzero residuals are
        // the worst kind of waste, penalize quadratically below a threshold.
        let dead_threshold = 20.0;
        if pr < dead_threshold {
            score += (dead_threshold - pr) * (dead_threshold - pr) * 2.0;
        }
        // Bonus if the leftover can still fit the next item (lookahead k=2).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0 + 0.5 * next_item_size as f64;
        } else if next_item_size > 0 {
            // Next item won't fit here; mild penalty if gap is awkward.
            score += 0.1 * (next_item_size as f64 - pr).min(50.0);
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction
    // of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 50.0 * fill_ratio * fill_ratio;

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few are open, allow consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (0.5 + progress);

    // Discourage bins whose residual deviates wildly from the mean residual
    // (avoid stranding outliers).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a fresh bin is only attractive when no
    // decent fit exists. Make the empty bin moderately expensive so it is
    // chosen only when open bins would create heavy dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with number of open bins.
        score = 60.0 + 1.5 * open_bins_count as f64;
        // If the item is small relative to capacity, a new bin is wasteful.
        score += 0.5 * (bin_capacity - item_size) as f64;
        // Late in the stream, prefer reusing open bins even more.
        score += 40.0 * progress;
        // But if this is the last item and nothing fits well, allow it.
        if next_item_size == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to leftover size
            let excess = (next_item_size - post_residual) as f64;
            score += 40.0 * (excess / 100.0).min(1.0);
        }
    }

    // Penalize dead space (small unusable residuals)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Late in stream: consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for many open bins to encourage packing density
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let base = 120.0;
        let fit_quality = if post_residual as f64 <= mean_residual { 0.0 } else { 1.0 };
        score += base + 100.0 * fit_quality;
        if fitting_bins_count == 0 {
            score -= 250.0; // no alternative, new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual is already the base; amplify near-perfect fits.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(6);

    // Penalize dead space that cannot host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Complementary fit: this bin can still host the next item.
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 20.0; // perfect chain fill
            }
        } else {
            // Dead space for the lookahead: penalize proportionally to waste.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.4 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + progress);
    } else {
        // With many alternatives, prefer bins where this item wastes least.
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0) * fit_ratio;
    }

    // Prefer bins below mean residual (tighter bins) early; spread load late.
    let dev = mean_residual - bin_residual as f64;
    score += if progress < 0.6 { 0.25 * dev } else { -0.15 * dev };

    // Mild penalty for opening new bins when many bins are open and fits exist.
    if bin_residual == bin_capacity {
        let base = 18.0 + 10.0 * (1.0 - progress);
        score += if fitting_bins_count > 0 { base } else { -5.0 };
        // New bin attractive if residuals everywhere are fragmented.
        if mean_residual < item_size as f64 * 0.5 && open_bins_count > 2 {
            score -= 15.0;
        }
    }

    // Encourage consolidating into few bins as stream ends.
    score += 2.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;
    let fit_ratio = item_size as f64 / cap;
    let nxs = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };

    let mut score = pr;

    // Non-linear coupling of post-residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them super-linearly.
    let late = progress * progress;
    score += 20.0 * late * pr_norm * (1.0 - pr_norm) * 4.0;

    // Smooth quadratic term favoring tight fits (small post_residual).
    score += 15.0 * pr_norm * pr_norm * (0.5 + 0.5 * progress);

    // Reward bins whose residual closely matches the item (smooth Gaussian-like).
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score -= 12.0 * (-gap * gap * 40.0).exp();

    // Lookahead coupling: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let diff = (pr - nxs * cap) / cap;
        score -= 10.0 * (-diff * diff * 50.0).exp();
        // penalize wasting residual larger than next item, smoothly
        score += 6.0 * (pr_norm - nxs).max(0.0) * (1.0 + progress);
    }

    // Last-chance bonus: smooth ramp when few fitting bins remain.
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 8.0 * scarcity * fit_ratio;

    // Penalize spreading across many open bins late in the stream.
    score += 0.5 * open_bins_count as f64 * progress * pr_norm;

    // Mild alignment with mean residual (smooth deviation penalty).
    score += 0.3 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled.
    score += 0.5 * (post_residual as f64 / cap);

    // Harmonic class of post_residual: residues mod 10, 20, 25.
    let r10 = post_residual % 10;
    let r20 = post_residual % 20;
    let r25 = post_residual % 25;
    // Small residues mean the leftover aligns with common item-size classes.
    score -= 2.0 * ((10 - r10) % 10) as f64 * 0.05;
    score -= ((20 - r20) % 20) as f64 * 0.03;
    score -= ((25 - r25) % 25) as f64 * 0.02;

    // Perfect / near-perfect closure rewards.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        // Dead space below the minimum item size is unusable.
        score += 15.0;
    }

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward leftovers that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack as f64 / cap);
            // Harmonic bonus if slack is a small residue again.
            score -= ((10 - slack % 10) % 10) as f64 * 0.08;
        } else {
            score += 4.0;
        }
        // If next item is large, prefer conserving big-residual bins.
        if next_item_size > 60 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Many open bins: discourage spreading into fresh-ish bins.
    if open_bins_count > 4 {
        score += 0.6 * (open_bins_count as f64).ln();
        // But reward consolidation into bins below mean residual (poorly filled).
        if (post_residual as f64) < mean_residual {
            score -= 1.5;
        }
    }

    // Stream progression: early on be picky about tight fits; later, close bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / cap);

    // New-bin candidate: only open a new bin when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline score; beats open bins only if their scores are worse than this.
        score = cap * 0.9;
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 10.0; // large next item: keep empty bin pristine
        }
        if fitting_bins_count == 0 {
            score -= cap; // no alternative, must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize gaps that cannot fit the known next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }
    // Reward gaps that can fit the next item (good staging).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit here is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fits).
    score += (bin_residual - item_size) as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in the post residual,
    // this placement is highly desirable
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits: penalize proportional to wasted space after both items
            let two_step_waste = post_residual - next_item_size;
            score -= 200.0 - 2.0 * two_step_waste as f64;
        } else {
            // Next item does NOT fit after this placement: penalize
            let overshoot = (next_item_size - post_residual) as f64;
            score += 50.0 + overshoot * 0.5;
        }

        // Bonus if the pair (item, next) nearly fills the bin
        let pair_fill = (item_size + next_item_size) as f64;
        if pair_fill >= bin_capacity as f64 * 0.95 && item_size + next_item_size <= bin_capacity {
            score -= 400.0;
        }
    }

    // Compare against mean residual: bins with less residual than average are
    // "tighter" and better candidates for closing out
    let res_diff = post_residual as f64 - mean_residual;
    score += res_diff * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize creating large dead space relative to typical small item sizes
    if post_residual > 0 && post_residual < 10 {
        score -= 80.0; // tiny unusable slivers are actually good (bin nearly closed)
    }
    if post_residual > 50 {
        // leaving a large residual is fine only for a fresh bin
        if bin_residual == bin_capacity {
            score -= 20.0; // slight encouragement to open new bin when fits are poor
        } else {
            score += 30.0;
        }
    }

    // Late in the stream, prefer consolidating (fewer open bins)
    if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tight_fit * tight_fit * (item_size as f64);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < next_item_size as u32 && next_item_size > 0 {
        // This bin can't host the lookahead item: mild penalty scaled by lookahead size.
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the lookahead item.
        score -= 4.0 + 0.1 * (next_item_size as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 + 0.25 * (item_size as f64);
    }

    // Compare against global mean residual: prefer bins below mean (more fragmented,
    // harder to fill later) when the item is large; prefer above-mean when small.
    let diff = bin_residual as f64 - mean_residual;
    if item_size >= 50 {
        score += 0.15 * diff;
    } else {
        score -= 0.10 * diff;
    }

    // Time horizon: early in the stream, be conservative (favor filling existing bins);
    // later, allow opening new bins more freely since future compensation is limited.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, discount penalty as stream progresses
        // and when the current fit would waste a lot of space.
        let waste_penalty = (bin_residual - item_size) as f64;
        let mut new_bin_score = waste_penalty + 20.0 * (1.0 - progress);
        if post_residual > 40 { new_bin_score -= 10.0; } // big item, plenty of room anyway
        if open_bins_count == 0 { new_bin_score -= 30.0; } // must open
        score += new_bin_score;
    } else {
        // Existing bin: slight reward late in the stream for consolidation.
        score -= 2.0 * progress;
        // Congestion: many open bins -> prefer consolidating into existing bins.
        score += 0.3 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fits), with non-linear shaping.
    let mut score = post * (1.0 + 0.8 * post / cap) - 20.0 * (-(post / cap) * 3.0).exp();

    // Reward near-perfect fits via smooth bump around post_residual ~ 0..5.
    let tight = (-post / 6.0).exp();
    score -= 35.0 * tight;

    // Penalize large dead space quadratically.
    score += 0.15 * (post / cap).powi(3) * cap;

    // Stream-progress coupling: late in the stream, be greedier about tight fits.
    let progress_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score -= 12.0 * progress_term * tight;
    score += 10.0 * progress * (post / cap);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0 * (1.0 - (post - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // leaves an attractive residual or no good fit exists.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln().max(1.0) };
        score += 40.0 + 12.0 * scarcity - 20.0 * (-(post / cap) * 4.0).exp();
        // Early in the stream, opening bins is cheaper.
        score -= 15.0 * (1.0 - progress);
    }

    // Mild pressure against accumulating many open bins with idle space.
    score += 0.4 * open_bins_count as f64 * (mean_residual / cap - post / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 residue classes
    let r = post_residual % 10;
    // Penalize residues that are "dead" (small nonzero leftovers are hard to fill)
    if post_residual > 0 {
        score += match r {
            0 => -6.0,                    // perfectly divisible class: excellent
            1 | 2 | 3 => 4.0,             // tiny slivers: dead space
            4 | 5 | 6 => -1.5,            // medium: fillable by small items
            _ => 1.0,                     // 7..9: awkward
        };
    } else {
        score -= 10.0; // perfect fill
    }

    // Integer-division thresholds on post_residual
    let q = post_residual / 25; // quarters of capacity
    score -= q as f64 * 2.0;    // reward larger usable chunks

    // Capacity fraction coupling
    let frac = post_residual as f64 / bin_capacity as f64;
    score += (frac - 0.5).abs() * 8.0; // prefer residuals near half capacity? no: prefer SMALL residual
    score -= frac * 4.0;               // net: smaller residual favored

    // Lookahead harmonic class: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact harmonic match check
            if post_residual % next_item_size.max(1) == 0 {
                score -= 7.0;
            } else {
                score -= 3.0;
            }
            // next item leaves a good residue after hypothetical placement
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 { score -= 3.0; }
            if nr > 0 && nr < 5 { score += 3.0; }
        } else {
            score += 5.0; // next item cannot use this bin's remainder anyway
        }
    } else {
        // last item: minimize residual hard
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: only open a new bin if all open fits are bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin ~ its full residual
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        } else if post_residual + item_size <= bin_capacity {
            // competing against poor fits: open new bin if existing best residual is small
            if mean_residual < 15.0 {
                score -= 100.0;
            }
        }
        // late in stream, fewer open bins: prefer consolidation
        if open_bins_count > 0 && (step_index as f64) / (total_items.max(1) as f64) > 0.7 {
            score += 10.0;
        }
    }

    // Mild pressure to keep number of open bins low
    score += open_bins_count as f64 * 0.15;

    // Mean residual alignment: placing into a bin far from mean residual smooths load
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // accept a future item (below the minimum plausible item footprint)
    // are pure waste — penalize them sharply.
    let min_item = 1u32;
    if post_residual < min_item.max(1) {
        score += 1000.0;
    }

    // Dead-space band: post_residual small but nonzero is a near-loss.
    // The tighter the fit (small post_residual), the better — but a
    // residual that no future item can use is worse than a moderate gap.
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 10.0 {
        // tiny sliver: nearly dead space
        score += 60.0 * (10.0 - pr + 1.0);
    } else if pr <= 30.0 {
        // moderate gap: mildly good (tight fit)
        score -= 25.0 * (1.0 - pr / 30.0);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward leaving a gap exactly matching the lookahead item (k=2 lookahead)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // gap can host the next item: mild reward proportional to usability
        score -= 15.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // gap cannot host the lookahead: dead-space risk
        score += 30.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly
    // prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: many open bins -> favor consolidation into
    // existing bins; few open bins -> new bins are cheaper.
    let obp = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open count.
        // Only attractive when existing fits are poor (handled implicitly
        // by comparisons) and bin count is low.
        score += 40.0 + 8.0 * obp;
        // If the next item is huge, a fresh bin keeps large capacity free.
        if next_item_size > 60 {
            score -= 30.0;
        }
    } else {
        // Placing into an existing bin reduces open-bin pressure.
        score -= 4.0 * obp;
    }

    // Mean-residual coupling: if this bin's residual deviates favorably
    // from the mean (i.e., we are consuming a large residual), reward it.
    let resid = bin_residual as f64;
    if resid > mean_residual {
        score -= 0.3 * (resid - mean_residual);
    } else {
        score += 0.3 * (mean_residual - resid);
    }

    // Stream progression: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 50.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact or near match between
    // post_residual and next_item_size (item fills the bin perfectly next step).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match is a jackpot: bin becomes perfectly full after two items.
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score -= 40.0 / (1.0 + diff);
        }
        // Penalize leaving residual that neither fits next item nor is small.
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * post_residual as f64;
        }
    } else {
        // Last item: prefer tightest fit, no lookahead to help.
        score += 0.1 * post_residual as f64;
    }

    // Prefer bins whose residual is already below average (well-packed bins).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    score -= 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless
    // the fit into existing bins is truly poor (large post_residual).
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if lookahead suggests a fresh bin pairs well with next item,
        // soften the penalty.
        if next_item_size > 0 && bin_capacity as i64 - next_item_size as i64 == item_size as i64 {
            score -= 45.0;
        }
    }

    // Late in the stream, waste hurts more: escalate dead-space penalty.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    // Slight preference for fewer open bins (consolidation pressure).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed post-residual dominates.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to next item.
            score += (post_residual as f64 - next_item_size as f64).min(0.0).abs() * 0.1;
        }
    } else {
        // Last item: strongly prefer filling existing bins.
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Less penalty late in the stream? Actually keep opening bins cheap early.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        // If mean residual of open bins is small, opening new bin is fine.
        score -= (mean_residual / bin_capacity as f64) * 20.0;
    }

    // Prefer fuller bins when many bins are open (bin consolidation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Mild penalty proportional to open bins count to encourage reuse.
    score += open_bins_count as f64 * 0.5;

    // Discourage leaving residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling: residual quality weighted by stream progress
    let tightness = (pr_norm - 0.5) * 2.0; // in [-1, 1]
    let progress_curve = 0.5 + 0.5 * (progress * std::f64::consts::PI).sin();
    score += 40.0 * tightness * tightness * progress_curve;

    // Reward filling bin tightly relative to its residual
    score -= 25.0 * fit_ratio * (br / cap);

    // Penalize near-full dead space that nothing else can use
    if next_item_size > 0 {
        let waste = (pr as i64 - next_item_size as i64).max(0) as f64;
        score += 0.35 * waste * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - pr_norm);
    }

    // Mild pressure to consolidate when many bins are open
    score -= 3.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - pr_norm);

    // New-bin candidate: keep it attractive early, penalize late
    if bin_residual == bin_capacity {
        score += 15.0 * progress - 5.0 * (1.0 - progress);
    }

    // Mean-residual drift term
    score += 0.1 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: residual mod capacity fractions ---
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Small post-residuals are excellent (tight fits): reward heavily.
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Integer-division thresholds: post_residual in harmonic bands.
    // Bins whose leftover falls in a "usable small item" class are favored.
    let band = post_residual / 10; // 0..=10 harmonic class
    match band {
        0 => score -= 20.0,             // 0..9  : nearly full, great
        1 => score -= 10.0,             // 10..19: fits a small item
        2 => score -= 5.0,              // 20..29: fits a medium item
        3 => score -= 2.0,              // 30..39
        4 | 5 => score += 3.0,          // 40..59: awkward mid gap
        6 | 7 => score += 6.0,          // 60..79: large dead space
        _ => score += 10.0,             // 80..99: nearly empty bin
    }

    // Modulo arithmetic on post_residual: values near multiples of common
    // item sizes (10, 20, 25, 50) are reusable classes.
    let pr_u = post_residual;
    if pr_u % 10 == 0 && pr_u > 0 {
        score -= 8.0;
    }
    if pr_u % 25 == 0 && pr_u > 0 {
        score -= 6.0;
    }
    if pr_u % 50 == 0 && pr_u > 0 {
        score -= 6.0;
    }

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // perfect chained fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this gap: penalize proportionally to gap size
            score += 0.10 * pr;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a decent fit and the item is large.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // Base penalty for opening a new bin.
        score = cap * 0.75 + 25.0 * item_frac;
        // Early in the stream, more freedom to open bins; later, avoid it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If many bins are open, prefer reusing one of them.
        score += 2.0 * open_bins_count as f64;
        // If the item is huge (harmonic class > half capacity), a fresh bin
        // is often the only sane choice for future pairings.
        if item_size > bin_capacity / 2 {
            score -= 45.0;
        }
        // If next item is large too, a fresh bin can host the pair.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    } else {
        // Prefer bins that are already relatively full (waste-aware).
        let fill = (bin_capacity - bin_residual) as f64 / cap;
        score -= 12.0 * fill;
        // Slight penalty for spreading across many half-empty bins.
        if mean_residual > cap * 0.45 {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harsh penalty for small unusable gaps (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward perfect fits strongly
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving gaps that could fit the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Open bins pressure: discourage spreading across many bins
    score += (open_bins_count as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high unless current fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + (open_bins_count as f64) * 0.5;
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Mild waste penalty relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: minimize residual directly (already base score).

    // 2-step lookahead: strongly reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Exact chain: item + next item fills bin completely.
        if item_size + next_item_size == bin_residual {
            score -= 60.0;
        }
        // Next item fits snugly after placement (post_residual >= next_item_size).
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0;
        }
        // Penalize leaving residual too small for next item (dead space).
        if post_residual < next_item_size && post_residual < 10 {
            score += 20.0 * (10.0 - post_residual as f64);
        }
    } else {
        // Last item: only exact fits matter.
        if post_residual == 0 {
            score -= 100.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average (good fits),
    // penalize bins looser than average unless they enable a lookahead chain.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 10.0 * rel;

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep new bins attractive only when current bin fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; offset by large residual (post_residual == capacity).
        score += 15.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host a clean 2-item chain
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let resid = bin_residual as f64;

    // Base: prefer leaving small residuals, but avoid residuals too small to ever be reused.
    let mut score = post;

    // Dead-space penalty: residuals below the smallest plausible item are wasted.
    if post_residual < 10 {
        score += 60.0 * (10.0 - post) / 10.0;
    }

    // Tightness reward: fraction of bin filled by this item.
    let fill = item / cap;
    score -= 35.0 * fill * fill;

    // Lookahead coupling: if next item fits the post residual, big bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 45.0 * (1.0 - post / cap) * (nxt / post.max(1.0));
        } else {
            // Penalize creating a residual just barely too small for the next item.
            let gap = post - nxt;
            if gap.abs() < 8.0 {
                score += 12.0 * (1.0 - gap.abs() / 8.0);
            }
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Global load balancing: prefer bins whose residual is below the mean (pack fuller bins first).
    score += 0.6 * (resid - mean_residual);

    // Time horizon: as stream completes, be more conservative; early on, allow more exploration.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress);
    score -= 8.0 * progress;

    // Many open bins: discourage opening more (applies to empty-bin candidate naturally via post=cap).
    score += 2.5 * (open_bins_count as f64).ln().max(0.0) * (resid / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with smooth polynomial coupling to stream progress.
    // Early on, prefer filling bins tightly (penalize large residuals strongly);
    // later, residual matters slightly less but dead-space curvature grows.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear penalty on unusable residual space: residual too small for
    // typical future items is dead weight. Smooth interaction with progress.
    let dead = (norm_pr - 0.15).max(0.0);
    score += 40.0 * dead * dead * (1.0 + 2.0 * progress);

    // Reward tight fits: near-zero post residual gets a smooth bonus.
    score -= 12.0 * (-norm_pr * 8.0).exp();

    // Lookahead coupling: if next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        let fits_next = if next_item_size <= post_residual { 1.0 } else { 0.0 };
        score -= 10.0 * fits_next * (1.0 - progress);
        // If next item is large, mildly prefer keeping big-residual bins free.
        let big_next = (next_item_size as f64 / cap).max(0.0);
        score += 6.0 * big_next * norm_pr;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual is above the mean (consolidate space).
    score += 0.3 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" classes are preferred (dead space minimization).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: excellent
    } else if pr <= 10 {
        score -= 40.0;
    } else if pr <= 20 {
        score -= 18.0;
    } else if pr <= 30 {
        score -= 6.0;
    } else if pr <= 50 {
        score += 4.0;
    } else {
        score += 12.0; // large dead space penalty
    }

    // Modulo-10 harmonic class: leftover that is a multiple of 10 tends to
    // accept typical item sizes exactly.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr && pr - next_item_size <= 10 {
            score -= 20.0;
        } else if next_item_size > pr {
            // next item won't fit here: mild penalty, wasted capacity slot
            score += 6.0;
        }
    } else {
        // last item: prefer closing bins as tightly as possible
        score -= 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; penalize it
    // unless the fit into open bins is poor.
    if bin_residual == bin_capacity {
        score += 55.0;
        // but if the item is large relative to capacity, a fresh bin is fine
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
        // late in the stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Prefer filling bins whose residual is already below the mean (tight bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item are pure waste.
    let next = if next_item_size == 0 { 1 } else { next_item_size };
    if next_item_size > 0 && post_residual < next && post_residual > 0 {
        // Unusable gap for the lookahead: strong penalty, worse the smaller the gap.
        score += 40.0 + (next - post_residual) as f64 * 2.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Reward tight relative fit.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Opening a brand-new bin: penalize unless the current bin would leave a bad gap.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if no open bin fits well (item nearly fills empty bin), allow it.
        if item_size >= 70 {
            score -= 45.0;
        }
    }

    // Mild bonus for bins with below-average residual (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Early in stream, be slightly more willing to open bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (item_size as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect pairing
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64); // tight fit reward
        } else {
            // next item cannot use leftover space: penalize dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.4 * waste.min(80.0);
        }
    }

    // Relative to mean residual: prefer bins whose residual deviates favorably
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins overall
    score -= 0.3 * (bin_capacity - bin_residual) as f64;

    // Penalize opening a new bin when reasonable fits exist
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * open_bins_count as f64;
    }

    // Late in the stream: consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the waste relative to capacity, the better.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving small unusable gaps (dead space) after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect closure is excellent.
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post residual, reward it;
    // if the next item would NOT fit, penalize creating a residual that strands it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Crowding pressure: when many bins are open with scattered residuals,
    // prefer filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score -= 3.0 * (open_bins_count as f64).ln() * (0.5 + 0.5 * progress);
    }

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (a "small" leftover bin), favor consolidating items into it.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 4.0 * diff / bin_capacity as f64;
    } else {
        score += 2.0 * (-diff) / bin_capacity as f64;
    }

    // New-bin candidate: opening a fresh bin should only win when the item
    // is large relative to the empty capacity and late in the stream where
    // leftovers are less valuable.
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - item_size as f64 / bin_capacity as f64) - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual (dead-space fraction)
    let pr = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling: dead space becomes more costly as the stream progresses
    let coupling = pr * pr * (0.5 + 2.0 * progress) + pr * (1.0 - progress) * 0.5;
    score += 40.0 * coupling;

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= 20.0 * (1.0 - pr) * (1.0 - pr) * progress;

    // Lookahead: penalize if post_residual cannot serve the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 8.0 + 12.0 * progress;
        } else {
            // reward residual that still accommodates the next item
            score -= 6.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty for proliferating open bins late in the stream
    score += 0.3 * open_bins_count as f64 * progress;

    // Deviation from mean residual: prefer bins whose residual is near the mean (balanced usage)
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 10.0 * dev * dev;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction classes. Residuals in low classes (small leftovers)
    // are desirable -> subtract; large dead space -> penalize extra.
    let class = post_residual / 10; // 0..=10 harmonic bins
    score += match class {
        0 => -12.0,
        1 => -6.0,
        2 => -2.0,
        3 => 0.0,
        4 => 2.0,
        5 => 5.0,
        6 => 8.0,
        7 => 12.0,
        8 => 16.0,
        9 => 20.0,
        _ => 0.0,
    };

    // Modulo coupling: exact-fit residue classes (post_residual % 10 == 0)
    // create clean packing structures; reward them.
    if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 1.5;
    }

    // Lookahead: if next item fits the post residual, this is a chained fit.
    if next_item_size > 0 && next_item_size <= post_residual {
        let tight = (post_residual - next_item_size) as f64;
        score -= 8.0 - 0.05 * tight;
    } else if next_item_size > 0 {
        // Next item won't chain; penalize more if we waste a scarce fitting bin.
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 2 {
        score += 1.0 * (fitting_bins_count as f64 - 2.0).min(4.0);
    }

    // Empty new-bin candidate: only attractive when nothing fits well.
    // Penalize opening a new bin unless the item is large relative to capacity
    // or the stream is early and mean residual is high (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        let penalty = 14.0 - 6.0 * item_frac - 4.0 * (1.0 - progress);
        score += penalty + 0.05 * open_bins_count as f64;
        // If mean residual across open bins is small, opening fresh is fine.
        if mean_residual < 15.0 {
            score -= 8.0;
        }
    }

    // Slight preference for tighter existing bins (smaller residual before place).
    score += 0.02 * bin_residual as f64;

    // Mean-residual deviation: placing into bins far below mean residual
    // (very full bins) is good; bins far above mean are wasteful.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.03 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: a leftover gap that cannot hold the next
    // item is wasted capacity. Penalize it quadratically, scaled by how
    // "close" it is to being useful (small unusable gaps are worst).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 4.0 + waste * waste * 0.15;
    }

    // Perfect fit reward: nothing left over at all.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: with many bins open, discourage spreading items
    // across bins; consolidate into already-open bins.
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate handling: an empty bin gets a base penalty so we
    // only open a new bin when the current fit is genuinely poor.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Late in the stream, new bins are even less attractive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 6.0;
    }

    // Mild best-fit refinement: prefer bins whose residual is tight
    // relative to the mean residual across open bins.
    score += (bin_residual as f64 - mean_residual) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (dead-space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // Next item fits perfectly here -> great chaining.
            if diff < 1.0 {
                score -= 400.0;
            } else if diff <= 10.0 {
                score -= 150.0 / diff.sqrt();
            } else {
                score -= 40.0 / diff;
            }
        } else {
            // Next item won't fit here; penalize leaving a residual that is
            // neither usable by the next item nor by typical items.
            let unusable = (nxt - post_residual as f64).min(60.0);
            score += 0.8 * unusable;
        }
    }

    // Compare post_residual against mean residual: prefer bins that end up
    // closer to (or below) the mean, avoiding outlier dead space.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Mild penalty for spreading across too many open bins when plenty remain.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64) * (1.0 - progress);
    }

    // Penalize very large leftover space in an old bin only mildly (it stays reusable).
    if post_residual > 50 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear boost.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 20.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    // relative to the item, or late in the stream with few open bins.
    if bin_residual == bin_capacity {
        let avg_fit_gap = (mean_residual - item_size as f64).max(0.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 30.0
            + 10.0 * (1.0 - progress)
            + 2.0 * open_bins_count as f64
            - 0.5 * avg_fit_gap;
        score += penalty.max(5.0);
    }

    // Mild preference for filling more-loaded bins (larger item relative to residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * fill_ratio;

    // Slight time-horizon modulation: early stream, be conservative with near-full bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 && post_residual > 0 && post_residual < 5 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let fit = (item_size as f64) / cap;

    // Tight-fit reward: strong smooth penalty on post_residual relative to item size
    let tightness = fit * fit;
    score -= tightness * 40.0 * (1.0 - progress * 0.3);

    // Non-linear coupling of post_residual with progress: waste matters more later
    let pr = post_residual as f64 / cap;
    score += pr * pr * 30.0 * (0.4 + 0.6 * progress);

    // Penalize bins whose residual deviates from the mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 15.0;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits into the post-residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= post_residual as f64 {
            score -= 20.0 * (ni / cap) * (0.5 + 0.5 * progress);
        } else {
            score += 8.0 * (1.0 - ni / cap);
        }
    }

    // New-bin candidate: prefer it only when existing bins would be badly fragmented
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        score += 25.0 + openness * 2.0 * (1.0 - progress);
        score -= fit * 30.0 * progress;
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band it lands in.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals too small to be useful (below 1/8 capacity).
    if post_residual < eighth {
        score += (eighth - post_residual) as f64 * 3.0;
    }

    // Reward residuals that are harmonic multiples of capacity fractions (usable slots).
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % eighth == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Extra reward if next item leaves another harmonic residual.
        let next_post = post_residual - next_item_size;
        if next_post % eighth == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // Next item cannot use this residual: penalize proportional to wasted potential.
        score += (next_item_size as f64 - pr).min(pr) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current bins are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs();
        score += 40.0 + fragmentation * 0.2;
        // But open a new bin if the item is large and would leave a bad residual elsewhere.
        if item_size > bin_capacity / 2 && fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Early in stream, opening fresh bins is fine.
        if step_index < total_items / 10 {
            score -= 10.0;
        }
    }

    // Mild preference for tighter bins (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Penalize spreading across too many open bins when residuals are large.
    if open_bins_count > 4 && mean_residual > (bin_capacity as f64) * 0.5 && bin_residual < bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (min item size 1, but practically small gaps < ~15 are near-useless)
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver -> strong penalty
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        } else {
            score -= 10.0; // large residual stays reusable
        }
    } else {
        // perfect fit: reward strongly
        score -= 50.0;
    }

    // Reward tight fits relative to bin capacity
    score += 0.5 * (item_size as f64 / bin_capacity as f64) * (post_residual as f64 - mean_residual);

    // Lookahead: if the next item fits exactly into the post residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0; // next item cannot use this gap
        }
    }

    // Open-bin pressure: discourage scattering across many bins
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only allow opening a new bin when current bin fit is terrible
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        if post_residual == 0 { score -= 60.0; } // item fills fresh bin exactly
    }

    // Stream progression: late in the stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 * 0.3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead: reward exact/near-exact match with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // Next item fits after this placement: reward tight chain.
            score -= (bin_capacity as f64 - diff) * 0.5;
        } else {
            // Next item would NOT fit: penalize dead space, worse when gap small.
            score += diff * 0.3 + 5.0;
        }
    }

    // Reward tight fits relative to mean residual.
    let mean = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if (post_residual as f64) < mean {
        score -= (mean - post_residual as f64) * 0.4;
    } else {
        score += (post_residual as f64 - mean) * 0.2;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 3.0 + open_bins_count as f64 * 0.5;
    }

    // Perfect closure reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let residual = bin_residual as f64;
    let fill_ratio = 1.0 - (post_residual as f64) / residual.max(1.0);
    score -= 40.0 * fill_ratio * fill_ratio;

    // Perfect-fit bonus: leaving nothing usable behind.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Dead space penalty: small leftovers are hard to reuse.
        score += 12.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Lookahead: reward if the next item fits into the post-residual (chain packing),
    // penalize if post-residual is just barely too small for the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            let slack = post - next;
            score -= 15.0 * (1.0 - slack / 100.0);
        } else if post > 0.0 && next - post <= 20.0 {
            // Post-residual just misses the next item: mild penalty.
            score += 8.0 * ((next - post) / 20.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize opening a new bin generally, more when many
    // bins are open or mean residual is large.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 20.0 + 3.0 * open_bins_count as f64;
        new_bin_penalty += 0.3 * mean_residual;
        // Late in the stream, opening new bins is more wasteful.
        new_bin_penalty *= 1.0 + 0.5 * progress;
        score += new_bin_penalty;
    } else {
        // Slight preference for bins with residuals near the item (best-fit flavor)
        // already captured by fill_ratio; add mild preference for larger residuals
        // among open bins to keep flexibility early.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let flexibility = (post_residual as f64 / bin_capacity as f64) * (1.0 - progress);
        score -= 5.0 * flexibility;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = progress.clamp(0.0, 1.0);
    let norm_pr = pr / cap;

    // Base: reward tight fits via smooth polynomial decay of post-residual
    let mut score = pr;
    score += 40.0 * norm_pr * norm_pr * (1.0 + x);

    // Dead-space penalty: residuals too small for typical items are wasteful
    let dead = if norm_pr > 0.0 && norm_pr < 0.1 { (0.1 - norm_pr) * 300.0 } else { 0.0 };
    score += dead * (1.0 + x);

    // Reward filling bins as stream progresses (smooth coupling with progress)
    score -= item_size as f64 * (0.5 + 0.5 * x);

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 25.0 * x;
    }

    // Lookahead coupling: if next item fits in the post-residual, reward it
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 10.0 * (1.0 - (nx / cap)) * (0.5 + x);
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Prefer bins with residual close to the mean (balance load) - smooth quadratic
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Slight penalty when many bins are open and this one is nearly empty
    let openf = open_bins_count as f64;
    score += 0.05 * openf * norm_pr * (1.0 - x);

    // New-bin candidate: penalize mildly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 30.0 + 40.0 * x - item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of small
    // divisors of capacity are more "reusable" by typical items.
    let pr = post_residual;
    let class_penalty = match pr % 10 {
        0 => -14.0,                       // perfectly reusable slots
        1 | 9 => 3.0,
        2 | 8 => 2.0,
        3 | 7 => 1.0,
        4 | 6 => 0.5,
        _ => 0.0,                          // residue 5: half-slot class
    };
    score += class_penalty;

    // Dead-space threshold: residuals below the minimum item size are wasted.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit: huge reward.
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;                 // exact chain fit
        } else if next_item_size <= pr {
            score -= 12.0 * (next_item_size as f64 / pr as f64);
        } else {
            // next item cannot fit here; penalize proportional to leftover waste
            score += 4.0 * (pr as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when mean residual of open bins is low
    // (open bins nearly full) — otherwise penalize opening fresh capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 60.0 + mean_residual * 0.5 - 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity - 5 {
            score -= 40.0;                 // reserve fresh bins for huge items
        }
    }

    // Slight preference for filling fuller bins (smaller residual) via mild scaling.
    score *= 1.0 + (pr as f64 / bin_capacity as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Tightness ratio: favor bins where the item fills a large share of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Lookahead: if the next item fits in the post residual, this placement
    // sets up a chain; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * next_item_size as f64;
    }
    // If next item almost fits (small shortfall), mildly penalize creating a trap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 10 {
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += 2.0 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already tight — finishing it off is good.
    let res_gap = mean_residual - bin_residual as f64;
    if res_gap > 0.0 {
        score -= 0.3 * res_gap;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless the item is
    // large relative to capacity or no good alternative exists.
    if bin_residual == bin_capacity {
        score += 90.0 + 0.5 * open_bins_count as f64;
        if item_size >= 60 {
            score -= 40.0; // big items start fresh bins acceptably
        }
    }

    // Mild stream-progression bias: late in the stream, avoid opening bins
    // that will end up mostly empty.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when post_residual matches the next item size exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for exact match; decays as mismatch grows.
        score -= 60.0 * (-gap / 12.0).exp();
        // Penalize leaving residual that is too small for the next item (dead space).
        if (post_residual as u64) < next_item_size as u64 {
            score += 25.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    }

    // Penalize tiny unusable residuals (dead space) relative to minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 3.0 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: penalize opening a new bin, unless current bin
    // would leave a very poor fit and the item is large.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_residual - item_size) < 15 && item_size > 50;
        if poor_fit && fitting_bins_count > 0 {
            score -= 10.0; // allow opening a fresh bin for large items with poor fits
        } else {
            score += 30.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Mild preference for tighter bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64 - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 20.0;

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline high unless item is large relative to capacity
        // or the item would leave awkward dead space in any open bin.
        let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
        let mut open_bonus = 0.0;
        if !large_item {
            open_bonus += 12.0;
        }
        // If many open bins fit, prefer one of them over a new bin.
        if fitting_bins_count > 1 {
            open_bonus += 10.0;
        }
        // Late in the stream, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        open_bonus += progress * 8.0;
        score += open_bonus;
        // If next item is large, opening a fresh bin can be good (reserve space).
        if next_item_size > 0 && next_item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 6.0;
        }
    } else {
        // Open bin: reward keeping residual compatible with the lookahead item.
        if next_item_size > 0 {
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score += gap * 0.15;
            // Perfect lookahead fit bonus.
            if post_residual == next_item_size {
                score -= 8.0;
            }
        }
        // Slight preference for bins tighter than average (concentrate waste).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        } else {
            score += 2.0;
        }
        // Penalize leaving very small unusable residuals.
        if post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
    }

    // Mild preference for using fewer bins overall.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Quadratic penalty on wasted residual, scaled by progress (late stream => waste matters more)
    let waste = pr / cap;
    score += 2.0 * waste * waste * (0.5 + progress);

    // Reward tight fits: smooth non-linear coupling of item size with residual
    let fill = item_size as f64 / cap;
    score -= 1.5 * fill * fill * (1.0 - waste);

    // If next item fits in post_residual, reward this bin (chaining)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 1.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Penalize leaving residual that cannot host the next item, weighted by progress
        score += 0.8 * progress * (pr / cap);
    }

    // Last-chance bonus: only one bin fits; strongly favor using it
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - waste);
    }

    // Mild pressure from many open bins: prefer consolidation, smoothly coupled to mean residual
    let obs = open_bins_count as f64;
    let mr = mean_residual / cap;
    score += 0.3 * (obs / (obs + 5.0)) * (1.0 - mr);

    // New-bin candidate handling: empty bin has high base residual; add smooth barrier
    if bin_residual == bin_capacity {
        score += 2.5 * (1.0 - progress) + 1.0 * (1.0 - fill);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: multiples of 10 are "usable" by
    // future items (sizes drawn on a 1..100 grid), so reward them.
    let harmonic = post_residual % 10;
    if harmonic == 0 {
        score -= 12.0 * (post_residual as f64 / bin_capacity as f64);
    } else if harmonic <= 3 {
        // Tiny dead space: nearly wasted capacity, penalize hard.
        score += 18.0 + 2.0 * harmonic as f64;
    } else if harmonic >= 7 {
        // Large-ish chunk still potentially usable by small items.
        score -= 4.0;
    } else {
        score += 6.0;
    }

    // Integer-division thresholds: post_residual in [1,9] is dead space;
    // post_residual >= 50 keeps a half-bin of usable room.
    if post_residual >= 1 && post_residual <= 9 {
        score += 25.0;
    }
    if post_residual >= 50 {
        score -= 8.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: reward if the next item fits exactly into the
    // post_residual (harmonic chaining), penalize if next item is close
    // but doesn't fit (we destroyed its home).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= 3.0 * (post_residual - next_item_size) as f64 / 10.0;
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            score += 15.0; // we broke a fit for the next item
        }
    }

    // New-bin candidate: make it unattractive unless the current item is
    // huge relative to capacity (poor fit anywhere else) or few bins open.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 15.0 * big_item;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A post_residual that cannot fit even the smallest plausible item (or the
    // lookahead item) is dead space -> hard penalty proportional to its waste.
    let min_item = 1u32;
    if post_residual < min_item.max(next_item_size.min(post_residual)) {
        // gap smaller than the next item: likely wasted
        if post_residual < next_item_size && next_item_size > 0 {
            score += 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }
    // Very small gaps (< 10) are almost certainly unusable dead space.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // Penalize leaving a gap just barely below the lookahead item (near-miss waste).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 0.1 * (next_item_size - post_residual) as f64;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across too many bins when mean
    // residual is already large (consolidation effect).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);
    score -= 0.3 * mean_residual * (mean_residual / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well; make the empty
    // bin moderately costly so it is chosen only for poor fits / last-chance misses.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
        // If no existing bin fits at all, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect lookahead match (within a small tolerance)
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 10.0 {
            score -= 30.0 * (1.0 - gap / 10.0);
        } else {
            // Dead space that next item cannot use: penalize proportionally
            score += gap * 0.35;
        }
    }

    // Penalize creating residual smaller than the minimum plausible item (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual well below the mean suggests wasted capacity
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.5 * (mean_residual - pr);
    } else {
        score -= 0.15 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late in the stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Slight penalty for using a nearly-full bin when many bins are open (balance load)
    if open_bins_count > 1 && post_residual < 20 {
        score += 8.0;
    }

    // New-bin candidate: neutral-ish baseline, only chosen when fits are bad
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize larger post-residual, with extra penalty for awkward small leftovers
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // dead space: too small for anything
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward filling bins deeply relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make fresh bins moderately attractive only when
    // current item is large relative to typical residuals or fits are scarce
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / mean_residual.max(1.0);
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        score = 60.0 - pressure * 20.0 - scarcity * 15.0 - horizon * 10.0;
        if fitting_bins_count == 1 {
            score += 50.0; // discourage opening a bin when a last-chance bin exists
        }
        return score;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement destroys room for next item; penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // exact pairing bonus
        if post_residual == next_item_size {
            score -= 18.0;
        }
    }

    // Prefer bins with residual close to item size (best-fit style) with non-linear coupling
    let waste = (bin_residual - item_size) as f64;
    score += (waste / bin_capacity as f64).powi(2) * 20.0;

    // Many open bins: encourage consolidation into emptier bins to close others
    let mean_gap = mean_residual - (bin_residual as f64);
    score += mean_gap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Core: quadratic penalty on leftover space (smooth non-linear coupling).
    let mut score = post * post / cap;

    // Reward tight fits: subtract proportional to fill fraction, amplified by progress.
    let fill = (bin_residual as f64 - post) / cap;
    score -= fill * fill * (1.0 + 2.0 * progress) * cap * 0.5;

    // Cubic dead-space term: residuals that are hard to reuse are extra bad.
    let unusable = (post / cap).powi(3);
    score += unusable * cap * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 2.0;
    }

    // Lookahead coupling: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= nxt * (1.0 + progress);
        } else {
            // Penalize leaving a residual that barely fails to fit the next item.
            let gap = post - nxt;
            score += (nxt - gap.abs()).max(0.0) * 0.3;
        }
    }

    // Mean residual coupling: prefer bins with residual near the mean (balanced packing),
    // smoothly penalized deviation.
    let dev = (post - mean_residual) / cap;
    score += dev * dev * cap * 0.8;

    // New-bin candidate: make it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        // Cost of a new bin grows with progress (late bins are more wasteful).
        let new_bin_cost = cap * (0.6 + 1.5 * progress);
        // But if existing fit is terrible (huge post residual), new bin becomes attractive.
        score = new_bin_cost - post * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact fill (0) heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modulo-10 harmonic classes: small post_residuals in low classes are dead space.
    let cls = (post_residual % 10) as f64;
    score -= (10.0 - cls) * 0.5;

    // Integer-division thresholds on post_residual.
    if post_residual <= 10 {
        score -= 40.0; // nearly perfect fit
    } else if post_residual <= 20 {
        score -= 15.0;
    } else if post_residual > 50 {
        score += 10.0; // leaving half a bin unused is bad
    }

    // Lookahead coupling: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual; penalize large residuals more
            score += (post_residual as f64) * 0.1;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist that fit,
    // unless it's the only option or residuals are all poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base_penalty = 120.0 + 80.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 500.0; // no open bin fits: must open new bin
        } else if mean_residual > 0.0 && (mean_residual - item_size as f64) < 10.0 {
            score -= 100.0; // existing fits are all near-exact anyway
        } else {
            score += base_penalty;
        }
    }

    // Prefer bins with residual close to item size (tight fits) via capacity fractions.
    let frac = (item_size as f64) / (bin_capacity as f64);
    let tightness = 1.0 - ((bin_residual as f64 - item_size as f64) / bin_capacity as f64);
    score -= frac * tightness * 30.0;

    // Spread load: if many bins open, slightly discourage adding to bins with large residual.
    if open_bins_count > 4 && post_residual > 40 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item are pure loss.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Small gaps are only usable by tiny items; penalize proportionally.
        score += 25.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += (open_bins_count as f64) * 0.8;

    // If a lookahead item can use the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If the lookahead item would be stranded by this placement, mild penalty.
    if next_item_size > post_residual && post_residual > 0 && next_item_size > bin_residual {
        score += 8.0;
    }

    // Prefer bins whose residual is close to the mean (balanced packing) early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (post_residual as f64 - mean_residual).abs() * 0.15 * (1.0 - progress);

    // New-bin candidate: only attractive when no decent fit exists among open bins.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 1 || (fitting_bins_count == 1 && post_residual >= 10);
        if decent_fit_exists {
            score += 50.0;
        } else {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits perfectly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin becomes exactly full after next item
        } else if next_item_size <= post_residual {
            // partial fit: reward proportional to how much of post_residual gets consumed
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill;
        } else {
            // next item cannot fit here: penalize leftover dead space
            score += 0.5 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    } else {
        // last item: prefer tightest packing
        score += 0.3 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins that end up below average residual
    // (tighter than the fleet average), penalize wasteful outliers
    score += 0.25 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly reward using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it attractive only when existing bins would leave bad residue
    if bin_residual == bin_capacity {
        // neutral baseline slightly above a good fit score
        score = 55.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // fewer open bins relative to stream progress -> opening fresh bin is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Slight penalty for accumulating many open bins with large residuals
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit a plausible future item
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.35 {
        score += 4.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item would leave an even tighter residual, mild reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 5.0 * chain_tight;
    }
    // Penalize if placing here blocks the next item while other bins could take it
    if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Time horizon: early in stream, prefer consolidating into few bins;
    // later, be more tolerant of spreading
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 2.0 * (bin_residual as f64 / bin_capacity as f64);

    // Many open bins with high mean residual: discourage adding to fragmentation
    if open_bins_count > 4 && (bin_residual as f64) > mean_residual * 1.4 {
        score += 3.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so an existing decent fit wins
        score += 20.0;
        // If the item fits poorly everywhere (high mean residual vs item), opening new bin is fine
        if (item_size as f64) > mean_residual - 5.0 {
            score -= 18.0;
        }
        // Late in the stream, opening a fresh bin is less costly
        score -= 10.0 * progress;
        // Lookahead synergy: fresh bin guarantees room for the next item
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fit_norm = (bin_residual as f64 - item_size as f64) / cap;

    // Base: post-residual cost, with non-linear penalty on mid-range waste
    let mut score = pr * (1.0 + 0.5 * pr_norm * (1.0 - pr_norm));

    // Smooth polynomial coupling of tight-fit reward with stream progress
    let tightness = (1.0 - fit_norm).clamp(0.0, 1.0);
    score -= tightness * tightness * (2.0 + 3.0 * progress) * 10.0;

    // Penalize residuals that no plausible future item fits: smooth interaction
    let next_fit = if next_item_size > 0 {
        let nf = (next_item_size as f64) / cap;
        let gap = pr_norm - nf;
        1.0 / (1.0 + (-8.0 * gap).exp()) // probability next item fits exactly-ish
    } else { 0.5 };
    score += 8.0 * (1.0 - next_fit) * pr_norm * (1.0 + progress);

    // Last-chance bin bonus (smoothly weighted)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_norm * pr_norm);
    }

    // Scarcity pressure: fewer fitting bins -> prefer this bin more
    let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
    score -= 5.0 * scarcity * tightness;

    // Mean residual alignment: favor bins near mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: penalize mildly so it's chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions
    let pr = post_residual as f64;
    let frac = pr / cap; // residual fraction

    // Penalize residuals that fall into "useless" harmonic bands:
    // residual classes (0,10] are near-perfect; (10,30] are awkward; >30 wasteful
    let class = (post_residual / 10).min(10); // integer division harmonic class 0..10
    match class {
        0 => { score -= 25.0; }              // near-perfect fit
        1 => { score -= 12.0; }              // still good (residual 10..20)
        2 => { score += 3.0; }               // 20..30 awkward zone
        3 => { score += 8.0; }               // 30..40
        4 => { score += 14.0; }              // 40..50 half-empty
        _ => { score += 18.0 + 2.0 * (class as f64 - 5.0); } // large dead space
    }

    // Lookahead coupling: reward if next item fits into post_residual (chained fit)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly-ish: strong reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / cap).min(1.0);
        }
        // Harmonic modulo: if next_item_size divides nicely into residual classes
        let nmod = next_item_size % 10;
        if nmod == 0 && next_item_size <= post_residual {
            score -= 5.0; // round-size next item chains well
        }
    } else {
        // last item: prefer zero residual strongly
        score -= 15.0 * (1.0 - frac);
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin has residual == capacity
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin fits well
        // (fitting_bins_count == 0 among open bins) or stream is early
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a bin
        } else {
            // penalize opening new bin when alternatives exist,
            // more strongly later in the stream (consolidation pressure)
            score += 25.0 + 30.0 * progress;
        }
        // new bin baseline: its "post_residual" is cap - item, treat neutrally
        score -= 5.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean
    // (concentrate filling into tighter bins)
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Mild preference for filling bins when many are open
    score += 0.5 * open_bins_count as f64 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for the smallest plausible item) are heavily penalized.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect / near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if (post_residual as f64) < 6.0 {
        score -= 15.0;
    }

    // Reward snug fits relative to the item size (waste ratio penalty).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 30.0;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when the stream is early
        // (room to fill it later) and few bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + progress * 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item could still use the leftover
    // space, this placement is more attractive.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 10.0;
    } else if next_item_size > 0 && (post_residual as f64) > 0.0 && (next_item_size as f64) > post_residual as f64 && (post_residual as f64) < dead_threshold {
        score += 10.0; // leftover can't host next item and is dead space
    }

    // Prefer bins whose residual is already below the mean (consolidation).
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
