pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize large dead space after placement, especially small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver is almost dead space
    } else if post_residual >= 10 {
        score -= 2.0 * (post_residual as f64).sqrt();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // partial reward, scaled by how well next item uses the leftover
            let next_fit = (next_item_size as f64) / (post_residual.max(1) as f64);
            score -= 15.0 * next_fit;
        } else {
            // next item cannot use leftover: mild penalty proportional to leftover size
            score += 0.05 * (post_residual as f64);
        }
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 0.3 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Time horizon: early on, be more willing to open new bins (spread items);
    // late in the stream, consolidate aggressively.
    if bin_residual == bin_capacity {
        // New-bin candidate score: baseline = capacity minus item, adjusted.
        score = (bin_capacity - item_size) as f64;
        // Discourage opening new bins late in the stream or when many bins are open.
        score += 10.0 * progress + 0.5 * open_bins_count as f64;
        // Encourage new bin early if current bin fits are all loose.
        score -= 5.0 * (1.0 - progress);
        // If next item is large and no bin would fit both, opening a fresh bin is fine.
        if next_item_size >= item_size {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Non-linear coupling: residual quality weighted by stream progress
    let progress_weight = t * t * (3.0 - 2.0 * t); // smoothstep
    score -= progress_weight * (norm_pr * norm_pr) * 20.0;

    // Penalize dead space that cannot fit next item, smoothly
    let dead = (pr - norm_next * cap).max(0.0) / cap;
    score += dead * dead * 15.0 * (1.0 - t);

    // Reward tight fits via non-linear coupling of item and post-residual
    let tightness = norm_item * (1.0 - norm_pr);
    score -= tightness * tightness * 12.0;

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - t * 0.5);
    }

    // Mild penalty for spreading across many bins late in stream
    score += (open_bins_count as f64).sqrt() * t * 2.0;

    // Prefer bins with residual below mean (compactness), smooth term
    let mean_gap = (mean_residual - pr) / cap;
    score += mean_gap * mean_gap * 5.0 - mean_gap * 3.0;

    // New-bin candidate: make it less attractive unless residual is large
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with gentle non-linearity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Harmonic class: post_residual modulo buckets. Residuals that are
    // "classically reusable" (multiples of 10, or large enough for common
    // item classes) are rewarded; awkward odd remainders penalized.
    let pr = post_residual;
    let cls = pr % 10;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if cls == 0 {
        score -= 18.0; // decile-aligned residual, highly reusable
    } else if cls <= 2 {
        score += 10.0; // sliver dead space
    } else if cls >= 8 {
        score += 6.0;  // nearly aligned but not quite
    }

    // Integer-division thresholds: can the residual host a future item?
    // Item sizes 1..100; treat residual >= 50 as "half-bin class".
    if pr >= 50 {
        score -= 12.0;
    } else if pr >= 25 {
        score -= 5.0;
    } else if pr > 0 {
        score += 14.0 * (1.0 - pr as f64 / 25.0); // small unusable pocket
    }

    // Lookahead coupling: reward if next item fits in post_residual exactly
    // or with tiny waste; penalize if next item almost fits (near-miss).
    if next_item_size > 0 {
        if next_item_size <= pr {
            let waste = pr - next_item_size;
            if waste == 0 {
                score -= 45.0; // chain exact fit
            } else if waste <= 3 {
                score -= 25.0;
            } else {
                score -= 10.0 * (1.0 - waste as f64 / pr.max(1) as f64);
            }
        } else {
            let miss = (next_item_size - pr) as f64;
            score += 8.0 * (1.0 - miss / 100.0).max(0.0); // near-miss penalty
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when open bins are fragmented or the item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Opening a new bin is cheap early or when open bins are full-ish.
        score = 55.0 + 30.0 * (1.0 - fragmentation) - 25.0 * progress;
        if item_size >= 70 {
            score -= 15.0; // big items prefer fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host a pair
        }
    }

    // Mild pressure against proliferating bins when mean residual is healthy.
    score += 0.6 * (open_bins_count as f64).ln().max(0.0) * (1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that no future item can use are heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fit, huge reward
    } else if post_residual > 0 && post_residual < next_item_size.max(min_item) {
        // Gap cannot fit the lookahead item -> likely dead space
        score += 25.0 + (next_item_size - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to bin capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact-fit bonus
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead synergy: reward residuals that exactly fit the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Deviation from mean residual: prefer bins whose residual is close to the item need
    let residual_gap = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.15 * residual_gap.abs();

    // Mild preference for keeping large residuals available for large future items
    if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny sliver is nearly dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: zero dead space strongly favored
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + next_item_size as f64;
        // exact chain: post_residual == next_item_size leaves another perfect fit
        if post_residual == next_item_size {
            score -= 100.0;
        }
    } else if next_item_size > 0 {
        // penalize dead space that cannot host the next item
        score += (next_item_size as f64 - post_residual as f64).abs() * 0.5;
    }

    // Penalize small unusable residuals (dead space) relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Relative to mean residual: prefer bins tighter (less residual) than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate: make it less attractive than good fits,
    // but attractive when no open bin fits well (post_residual would be large)
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fits win
        score += 150.0;
        // but if item is large and would leave big residual in any bin,
        // new bin becomes competitive: reduce penalty as item grows
        score -= (item_size as f64 / bin_capacity as f64) * 100.0;
        // late in the stream, prefer packing into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 80.0;
    }

    // Slight preference for tighter bins overall
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: exact fits are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward tight fits proportionally to how small the dead space is.
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += tightness * 60.0;

        // Lookahead: if the next item fits into the post-residual, reward this placement.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
            // Extra reward when next item nearly fills the leftover space.
            let next_leftover = post_residual - next_item_size;
            score -= (bin_capacity as f64 - next_leftover as f64) * 0.05;
        }
        // Penalize if next item would fit better in a fresh bin than in this leftover.
        if next_item_size > post_residual && post_residual < 10 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize wasting space in bins with large residuals when many bins can fit the item.
    if fitting_bins_count > 1 && bin_residual > item_size + 20 {
        score += 10.0;
    }

    // Global state coupling: when mean residual is low, conserve open-bin space more aggressively.
    let mean_gap = mean_residual - post_residual as f64;
    score += mean_gap * 0.3;

    // Prefer filling already-open bins as the stream matures (avoid bin proliferation late).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    // New-bin candidate handling: opening a new bin should only win when it creates
    // a genuinely better long-term home (e.g., large item, poor fits elsewhere).
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (post_residual as f64 >= item_size as f64 && mean_residual < item_size as f64);
        if poor_fit_elsewhere {
            // Fresh bin is attractive when the item is large or nothing fits well.
            score -= 40.0 + 0.5 * item_size as f64;
        } else {
            // Discourage opening new bins when decent fits exist.
            score += 50.0 + 0.4 * (open_bins_count as f64);
        }
    }

    // Mild penalty for very large leftover dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable slivers are dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post-residual, with a smooth non-linear penalty
    let mut score = pr * (1.0 + 0.35 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, tolerate larger residuals; late, tighten aggressively
    let tight = 0.5 + 1.5 * progress * progress;
    score += 20.0 * tight * norm_pr * norm_pr;

    // Reward filling bins tightly relative to the mean residual of open bins
    let mean_gap = (mean_residual - pr) / cap;
    score -= 8.0 * mean_gap * (1.0 + progress);

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * norm_pr);
    } else if fitting_bins_count > 1 {
        // mild crowding penalty scaled by number of alternatives
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: penalize leaving a residual that barely fails to fit the next item,
    // reward residuals that can accommodate it
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let slack = pr - ni;
        if slack >= 0.0 {
            score -= 6.0 * (slack / cap) * (1.0 - progress);
        } else {
            score += 4.0 * ((ni - pr) / cap) * (1.0 + progress);
        }
    }

    // New-bin candidate: penalize opening a new bin unless current residual is large dead space
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.6 * progress) - 5.0 * (open_bins_count as f64).ln();
        // allow opening early when item is large and would leave little residual anyway
        score -= 10.0 * norm_item * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are "perfect" leftovers
    // (zero) or large enough to plausibly host another item, penalize awkward middles.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect closure
    } else {
        // class by integer division thresholds (harmonic buckets of capacity)
        let class = pr / 10; // 0..=10
        let awkward = (class >= 1 && class <= 3) || class == 5 || class == 7;
        if awkward { score += 12.0; }
        if class >= 8 { score -= 6.0; } // roomy leftover, likely reusable
        // modulo arithmetic: residuals divisible by common item classes are reusable
        if pr % 10 == 0 { score -= 5.0; }
        if pr % 20 == 0 { score -= 4.0; }
    }

    // Lookahead: reward if next item fits the resulting residual (chaining)
    if next_item_size > 0 && next_item_size <= pr {
        score -= 18.0 + 0.15 * (pr - next_item_size) as f64;
    } else if next_item_size > 0 {
        // next item cannot fit here after placement: slight penalty proportional to waste
        score += 0.05 * (next_item_size.saturating_sub(pr)) as f64;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Tight fit reward: minimal slack relative to capacity
    let tightness = (item_size as f64) / cap;
    score -= 10.0 * tightness;

    // Penalize opening a new bin when open bins already exist and item fits one of them
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of a fresh bin
        score = cap - 20.0;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 15.0;
        }
        // if stream near end, opening new bins is cheap-ish
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
        // if next item is large and current bin nearly full, new bin is attractive
        if next_item_size > 0 && next_item_size as f64 > 0.8 * cap {
            score -= 10.0;
        }
    } else {
        // mild preference to balance residuals across bins
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.02 * dev;
    }

    // Early stream: be slightly conservative about closing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100 range,
    // but small gaps < 10 are almost always unusable) are heavily penalized.
    if post_residual < 10 {
        score += 500.0;
    } else {
        // Non-linear penalty growing as the gap approaches the unusable zone.
        let gap = post_residual as f64;
        score += 40.0 / gap;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            // gap that cannot host next item: mild penalty proportional to dead-ness
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Pressure from number of open bins: discourage spreading across many bins,
    // but relax pressure when this bin is the last chance before a new bin.
    let pressure = open_bins_count as f64 * 2.0;
    if fitting_bins_count == 1 {
        // Last chance: strongly favor using this bin over opening a new one.
        score -= 120.0;
    } else {
        score += pressure;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 100.0 + 30.0 * fitting_bins_count as f64;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * progress;
    } else {
        // Slight reward for using existing bins as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that waste large residuals on small items.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Mild preference for tighter fits overall.
    score -= (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item -> strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: mild reward, scaled by tightness.
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted-looking residual, worse if gap is small.
            score += 10.0 + 20.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize residual.
        score -= 5.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving residual well below mean means we consumed a "fat" bin efficiently.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Penalize large dead space (unusable chunks).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // tiny residual = nearly perfect fill
    } else if post_residual > bin_capacity / 2 {
        score += 6.0; // leaving half-empty bin is wasteful
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-ish, only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * item_size as f64;
        // Late in the stream, opening new bins is less costly than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Slight preference for bins that are already well-filled.
    score -= 0.2 * (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual)
    score -= (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Penalize dead space that next item could have used
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Reward leaving room exactly for the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins with large mean residual: prefer consolidating into fuller bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - post_residual as f64) * 0.15 * (0.5 + progress);
    }

    // Penalize opening new bins when many bins are already open and sparse
    if bin_residual == bin_capacity {
        let sparsity = mean_residual / bin_capacity as f64;
        score += 20.0 + sparsity * 30.0 + open_bins_count as f64 * 0.5;
        // Late in stream, new bins are extra costly
        score += progress * 25.0;
        // But a big item in a new bin is fine early
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
    }

    // Prefer filling bins with larger items when residuals are large
    score -= (item_size as f64 / bin_capacity as f64) * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: waste after placement, non-linearly scaled (waste hurts more when small).
    let mut score = pr + 12.0 * (pr / cap).powi(4) * cap;

    // Reward tight fits (small post_residual relative to item) with smooth coupling.
    score -= 8.0 * (it / cap) * (1.0 - pr / cap).powi(3) * cap * 0.1;

    // New-bin candidate: penalize opening new bins, more strongly later in stream
    // and when existing bins fit, unless post_residual would be very tight.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let scarcity = (fitting_bins_count as f64).recip().min(1.0);
        let tight_bonus = (1.0 - pr / cap).powi(2);
        score += 18.0 * (1.0 - progress) + 10.0 * (1.0 - scarcity) - 14.0 * tight_bonus;
    } else {
        // Existing bin: mild reward when it is a rare fitting option (last chance).
        if fitting_bins_count <= 1 {
            score -= 6.0;
        }
    }

    // Lookahead coupling: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            score -= 5.0 * (ni / cap) * (1.0 - progress);
        } else {
            score += 4.0 * ((ni - pr) / cap) * (0.5 + 0.5 * progress);
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // (use large residual bins when mean residual is high).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 3.0 * dev * (0.5 + progress);

    // Stream progress: later in the stream, waste matters more (fewer chances to fill).
    score += 6.0 * (pr / cap) * progress;

    // Slight open-bin pressure to consolidate.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fractions
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Reward residuals that belong to "useful" harmonic classes
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= quarter / 2 {
        score -= 30.0; // near-perfect, small dead space
    } else if pr <= quarter {
        score -= 12.0;
    } else if pr <= half {
        // mid-band: check modulo arithmetic — residual divisible by small integers
        // suggests it can host common item sizes later
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        }
    } else {
        score += 5.0; // large residual left = item was small, mild penalty
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize more if this bin was the only option
            score += 6.0;
        }
    }

    // Last-chance bin: avoid opening a new bin if fit is reasonable
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing bins with decent fits,
    // but allow opening a new bin when all open bins leave bad residuals
    if bin_residual == bin_capacity {
        score += 10.0 + 0.05 * open_bins_count as f64;
        // If mean residual is small (open bins are nearly full), new bin is fine
        score -= (mean_residual / cap) * 12.0;
    }

    // Progress coupling: later in stream, be slightly more conservative with new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (open_bins_count as f64).sqrt();

    // Tie-break: prefer bins whose residual is close to mean (keep balance)
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for typical future items
    // are effectively wasted capacity. Penalize unusable gaps extra hard.
    if post_residual > 0 {
        let min_useful = 10u32;
        if post_residual < min_useful {
            score += 60.0 * (min_useful as f64 - post_residual as f64);
        }
        // Smooth dead-space curve: gaps just below typical item sizes are bad.
        let gap = post_residual as f64;
        score += 15.0 * (-(gap / 20.0)).exp();
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin; if it nearly fits, slightly favor.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // Next item cannot use this residual -> dead space risk
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, slightly encourage filling them rather than opening new ones.
    let pressure = open_bins_count as f64;
    score += 0.5 * pressure;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin, more so when many
        // bins are already open, but relax when this bin would end up
        // nearly full (efficient bulk fill).
        let fill = item_size as f64 / bin_capacity as f64;
        score += 25.0 + 2.0 * pressure - 30.0 * fill;
    }

    // Mean residual context: if this bin's residual is far below the mean,
    // it is a laggard bin; filling it consolidates state.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= 0.3 * (mean_residual - resid);
    } else {
        score += 0.15 * (resid - mean_residual);
    }

    // Stream progression: early on, be a bit more liberal about opening bins;
    // later, consolidate harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post residual, with mild superlinearity to punish dead space.
    let mut score = post + 0.35 * (post * post) / cap;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: strongly reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // Chain fit: reward proportionally to how well next item fills the leftover.
            let chain_fill = nxt / post;
            score -= 25.0 * chain_fill;
            // Extra bonus for a perfect 2-chain (post_residual == next_item_size).
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // Penalize leftovers that are too small for the next item (dead space risk).
            let waste = nxt - post;
            score += 0.25 * waste;
        }
    }

    // Relative-to-mean coupling: prefer bins that are tighter than average when they fit well.
    let tightness = (mean_residual - bin_residual as f64) / cap;
    score += 8.0 * tightness;

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin unless fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate logic: empty bin gets a moderate default score;
    // open bins with decent fits beat it, but terrible fits (large post residual waste
    // with no chain) lose to a fresh bin.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 6.0;
        }
    }

    // Late-stream pressure: consolidate more aggressively as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness: reward near-exact fills.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;
    if post_residual == 0 { score -= 60.0; }

    // Penalize small dead space (< 10 unusable for future items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward; else penalize larger leftover.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 20.0;
        } else {
            score += 0.08 * post_residual as f64;
        }
    } else {
        // Last item: maximize fill.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: prefer reusing existing bins, penalize new-bin candidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        score -= 5.0 * open_bins_count.min(20) as f64 * progress;
    }

    // Global residual pressure: if mean residual is high, prefer filling fuller bins.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: penalize wasted space quadratically (dead space grows costly)
    let mut score = norm_post * norm_post * cap;

    // Smooth non-linear coupling of waste with stream progress:
    // later in the stream, residual waste is more harmful (fewer chances to fill)
    let progress_coupling = norm_post * (1.0 - progress) * (progress * 2.0);
    score += progress_coupling * cap * 0.5;

    // Reward tight fits: subtract when post_residual is small relative to item size
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * item_size as f64 * 0.3;

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + norm_post * 10.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let fit_quality = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= 5.0 + 10.0 * fit_quality * (1.0 - progress);
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize proportionally to leftover
        score += norm_post * next_item_size as f64 * 0.2;
    }

    // Prefer bins below mean residual (consolidate space)
    score += (post - mean_residual) * 0.05;

    // New-bin candidate: neutral-ish baseline, slightly penalized so it is
    // chosen only when existing bins have poor fits
    if bin_residual == bin_capacity {
        score = cap * 0.55 + open_bins_count as f64 * 0.3 + norm_post * cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity fractions and reward residues that form "nice" classes
    // (divisible into common item sizes), penalize awkward leftovers.
    let pr = post_residual as u32;
    let pr_class = pr / 10; // integer-division harmonic class (0..10)
    match pr_class {
        0 => score -= 40.0,                       // near-perfect fit
        1 => score -= 18.0,                       // small but useful
        2 | 3 => score -= 6.0,                    // mid-small leftovers
        4 | 5 | 6 => { /* neutral zone */ }
        7 => score += 5.0,                        // awkward ~70-79 gap
        8 => score += 10.0,                       // ~80-89 gap hard to fill
        _ => score += 3.0,                        // large residual, bin barely used
    }

    // Reward exact harmonic alignment: post_residual divisible by common sizes
    if pr > 0 {
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 {
                score -= 8.0;
                break;
            }
        }
    }

    // Tightness ratio: fraction of bin consumed by this placement
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill; // quadratic fill reward

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let pair_waste = pr - next_item_size;
            score -= 20.0 * (1.0 - pair_waste as f64 / cap);
        } else {
            // next item won't fit here; penalize large dead space more
            score += (pr as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when current item is huge and existing residuals are small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (mean_residual / cap - item_size as f64 / cap).max(0.0);
        score = cap - item_size as f64 // baseline: residual after fill = cap - item
              + 12.0 * open_bins_count as f64 * (0.5 + progress)
              + 60.0 * pressure;
        if item_size > 60 {
            score -= 15.0; // big items justify fresh bins
        }
    }

    // Mild global balancing: prefer bins whose residual is below mean
    // (fill the fullest-fitting bins first).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: gaps too small for the smallest plausible item are wasted.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0;
    } else if (post_residual as f64) < dead_threshold * 2.0 {
        score += 25.0 * (dead_threshold * 2.0 - post_residual as f64) / dead_threshold;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (post_residual as f64 + 1.0);
    score -= 8.0 * tightness.min(3.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space relative to capacity: fraction of the bin that becomes unusable.
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * dead_frac * dead_frac;

    // Lookahead: if next item fits exactly in the post residual, reward; if it
    // nearly fits but not quite, penalize creating a near-miss gap.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let overshoot = (next_item_size - post_residual) as f64;
            score += 10.0 * overshoot / bin_capacity as f64;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 1.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate: penalize opening a new bin for a small item, allow it
    // for large items when the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        let base = 45.0 + 0.6 * item_size as f64;
        score += base + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: if the next item fits the post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 120.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use.
        score += 0.3 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 50.0 + mean_residual * 0.2;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.06;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits, scaled non-linearly by stream progress.
    let mut score = post * (1.0 + 0.5 * progress * progress);

    // Smooth polynomial coupling: dead space penalty grows quadratically with
    // normalized post_residual and accelerates as the stream progresses.
    score += cap * 0.8 * norm_post * norm_post * (0.5 + progress);

    // Reward near-perfect fits with a smooth bump around small post_residual.
    let tight = (-norm_post * 8.0).exp();
    score -= 12.0 * tight * (1.0 + progress);

    // Last-chance bonus: smooth reward when few fitting bins exist.
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= 6.0 * last_chance * (1.0 + 0.5 * progress);

    // Lookahead: smooth reward if the next item fits into post_residual.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let ratio = next_item_size as f64 / cap;
        score -= 5.0 * (1.0 - ratio) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Penalize when next item cannot follow, scaled by how close it was.
        let gap = (next_item_size as f64 - post) / cap;
        score += 3.0 * gap * gap * cap * 0.05;
    }

    // New-bin candidate: keep it mildly unattractive unless residual is tiny,
    // with attractiveness decaying smoothly as stream progresses.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 4.0;
    }

    // Mild penalty for proliferating open bins relative to stream length.
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins near the mean (smooth quadratic).
    let dev = post - mean_residual;
    score += 0.02 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: small leftovers are "dead".
    // Class 0: post_residual < 10  -> perfect packing, big reward.
    // Class 1: 10..20              -> still usable by any item, mild reward.
    // Class 2: 20..50              -> medium.
    // Class 3: >= 50               -> large, keep flexible.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0;
    } else if pr < 10 {
        score -= 45.0;
    } else if pr < 20 {
        score -= 15.0;
    } else if pr < 50 {
        score -= 4.0;
    } else {
        score += 6.0;
    }

    // Integer-division threshold: does the leftover fit a "harmonic" class
    // of typical item sizes (multiples of 10 / halves)?
    if pr >= 10 && (pr % 10 == 0 || pr % 20 == 0) {
        score -= 8.0; // leftover aligns with common size granularity
    }
    if pr > 0 && pr < 10 {
        // tiny dead space: penalize unless it exactly fills the bin
        score += 5.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0 + 0.1 * next_item_size as f64;
            // extra reward if next item would nearly fill it
            if pr - next_item_size < 10 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this bin's leftover: slight penalty
            score += 3.0;
            // modulo harmonic: leftover in awkward band that no small item uses
            if pr >= 10 && pr < next_item_size {
                score += 2.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate logic: opening a new bin is expensive; only allow
    // it when current bins are badly fragmented (high mean residual spread
    // vs item size) or this is a fresh stream start.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // penalize new bins generally
        score += 40.0;
        // but if open bins have huge residuals (poorly packed) and many bins
        // exist, opening a fresh one can be better for large items
        if item_size > 60 && fragmentation > 0.7 && open_bins_count > 3 {
            score -= 55.0;
        }
        // early stream: seeding bins is cheap
        if progress < 0.05 && open_bins_count < 4 {
            score -= 20.0;
        }
    }

    // Prefer tighter bins when several fit: reward small bin_residual usage.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    // Mild pressure against bin proliferation.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are unusable
    if post_residual > 0 && post_residual < 10 {
        score += 200.0; // creating a dead gap is very bad
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fit reward
    }

    // Penalize moderately small leftovers that few items can use
    if post_residual > 0 && post_residual < 20 {
        score += 40.0 * (20 - post_residual) as f64 / 20.0;
    }

    // Open bins pressure: discourage proliferation of bins
    score += open_bins_count as f64 * 3.0;

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New empty bin candidate: penalize so it's only chosen when fits are poor
    if bin_residual == bin_capacity {
        score += 150.0 + mean_residual * 0.5;
    }

    // Lookahead: prefer bins whose leftover can still host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if post_residual > 0 {
            score += 15.0;
        }
    }

    // Slight preference for tighter fits relative to mean residual
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Penalize leftover that exceeds next item: dead space remains after 2 steps.
        score += 0.5 * (post_residual as f64 - next_item_size as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Small post_residual that can't fit next item is acceptable if tiny.
        score += 0.2 * post_residual as f64;
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could absorb the item reasonably.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64).min(1.0);
        score += 15.0 + 20.0 * (1.0 - tightness);
    }

    // Prefer bins tighter than the mean residual (relative fit).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 20.0;

    // Penalize dead space: post_residual too small to matter later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize leaving mid-size gap
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; offset when open bins are mostly full.
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        score = 40.0 - avg_fullness * 35.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Global pressure: many open bins with high mean residual -> reward using this bin.
    let pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    score -= pressure * 0.5;

    // Time horizon: early on, tolerate imperfect fits (keep bins flexible);
    // late in the stream, prioritize immediate tight packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.3;
    score -= progress * fit_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear shaping
    let mut score = pr as f64 * (1.0 + 0.8 * progress);

    // Polynomial coupling: dead space penalty grows super-linearly for small residuals
    score += cap * (1.0 - x).powi(3) * (0.5 + 0.5 * progress);

    // Reward tight fits more strongly late in the stream
    score -= (item_size as f64 / cap) * (20.0 + 30.0 * progress);

    // Penalize residuals that cannot fit typical future items (non-linear in x)
    score += 15.0 * (-(x * 8.0)).exp();

    // Last-chance bonus: strongly favor the only fitting bin to avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - progress);
    }

    // Lookahead: reward leaving space for the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_next = (pr >= nx) as i32 as f64;
        score -= fit_next * 10.0 * (0.5 + 0.5 * progress);
        score += (nx / cap) * (1.0 - x).powi(2) * 12.0;
    }

    // New-bin candidate: prefer opening a new bin only when existing bins are crowded
    if bin_residual == bin_capacity {
        let crowdedness = (mean_residual / cap).max(0.0).min(1.0);
        score = 45.0 + 60.0 * crowdedness * (0.5 + 0.5 * progress) + 10.0 * (1.0 - progress);
        // discourage accumulating many open bins early
        score += (open_bins_count as f64).powf(0.7) * 2.0;
    }

    // Mild penalty for many open bins relative to stream progress
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: post_residual bucketed by capacity fractions
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f;

    // Penalize residuals in "dead zones": small but not zero (unusable by mid items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward exact fit
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo-10 harmonic classes of post_residual: align with item granularity
    let class = post_residual % 10;
    score += class as f64 * 0.6;

    // Integer-division thresholds: residuals divisible by 5 or 10 are more reusable
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // reward if next item leaves another harmonic residual
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            }
            score -= (next_item_size as f64) * 0.1;
        } else {
            // next item can't use this residual: penalize proportionally
            score += (next_item_size as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: neutral baseline, only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap_f;
        // open new bin when mean residual is small (bins nearly full)
        score = 15.0 - pressure * 10.0;
        if next_item_size > item_size {
            score -= 5.0;
        }
    }

    // Mild tie-breaking by fullness ratio
    score -= (1.0 - frac) * 2.0;

    // Progression: slightly prefer consolidation early, freshness later
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals too small for any future item are "dead".
    // Dead zone threshold calibrated to the minimum plausible item size.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= 2.5 * (1.0 - (post_residual as f64) / bin_capacity as f64).powi(3);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another bin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // If the next item fits snugly into the post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 * (next_item_size as f64 / (post_residual as f64).max(1.0));
    }

    // Penalize leaving post_residual that matches mean residual poorly (fragmentation).
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect match: post_residual exactly equals next item size -> big reward.
        if post == next {
            score -= 60.0;
        }
        // Next item still fits in this bin after placement -> reward proportionally.
        else if post >= next {
            let slack = post - next;
            // Reward tight fits (small slack) more than loose ones.
            score -= 40.0 - slack.min(40.0);
        }
        // Next item would NOT fit here after placement: penalize wasted dead space,
        // scaled by how close the next item is to fitting (near-miss hurts most).
        else {
            let miss = next - post;
            score += miss * 0.8;
        }
    }

    // Relative-to-mean-residual coupling: bins with residual far above the mean
    // are "large" bins; prefer keeping them flexible unless lookahead matched.
    let post_f = post_residual as f64;
    let dev = post_f - mean_residual;
    score += dev.abs() * 0.25;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Slight preference for tighter fits overall.
    score += (item_size as f64 / bin_residual.max(1) as f64) * 5.0;

    // Early in the stream, allow more exploration of new bins; late in the stream,
    // consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize it more as the stream progresses,
        // unless lookahead suggests a poor fit in existing bins.
        score += 10.0 + 25.0 * progress;
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            // Existing bins would leave a near-miss; a fresh bin may be better.
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that
    // can never fit a typical item is worse than the raw number suggests.
    if post_residual > 0 {
        // penalize residuals too small to be reusable (dead space)
        let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
        if (post_residual as f64) < dead_threshold {
            score += 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
        }
    } else {
        // perfect fit: strong reward
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement sets up a chain — reward it.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let pr = post_residual as f64;
        if ni <= pr {
            // next item fits here: reward proportional to how snugly
            let slack = (pr - ni) / bin_capacity as f64;
            score -= 15.0 * (1.0 - slack);
        } else {
            // next item won't fit after this placement: mild penalty scaled
            // by how much we fragment this bin
            let frag = (ni - pr) / bin_capacity as f64;
            score += 8.0 * frag;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity.
    // Only allow opening a new bin when existing fits are poor or scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base handicap so open bins are preferred unless their scores are bad
        let mut handicap = 12.0;
        // more open bins with slack -> discourage new bins
        handicap += 2.0 * (open_bins_count as f64).ln().max(0.0);
        // high mean residual -> plenty of room around, discourage new bins
        handicap += 6.0 * (mean_residual / bin_capacity as f64);
        // late in the stream, closing bins out tightly matters more
        handicap += 10.0 * progress;
        // if item is huge, a fresh bin is actually attractive (clean fit)
        handicap -= 0.15 * item_size as f64;
        score += handicap.max(-20.0);
    }

    // Mild preference for fuller bins overall (best-fit flavor) modulated
    // by stream progress: early on keep bins flexible, later consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * (0.5 + progress);

    // Slight penalty for spreading across many bins when residuals are large
    if open_bins_count > 0 && mean_residual > bin_capacity as f64 * 0.5 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize large post residual, with non-linear (quadratic) coupling to progress.
    let mut score = pr * (1.0 + 0.8 * progress) - 0.6 * cap * norm_pr * norm_pr * (1.0 - progress);

    // Reward tight fits: smooth exponential term favoring small post_residual.
    score -= 12.0 * (-(pr / 20.0)).exp();

    // Dead-space penalty: residuals too small for typical future items are wasteful.
    let dead_threshold = 0.15 * cap;
    if pr > 0.0 && pr < dead_threshold {
        score += 8.0 * (1.0 - pr / dead_threshold) * (1.0 + progress);
    }

    // Lookahead: reward bins whose post_residual accommodates next_item_size.
    if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= 6.0 * (1.0 - pr / cap) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + 0.5 * progress);
    }

    // Prefer bins with residual below mean (better fill balance), smooth coupling.
    score += 0.05 * (pr - mean_residual);

    // New-bin candidate: mild penalty so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - progress) * (open_bins_count as f64 / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post-residual: residuals divisible into common
    // small-item sizes are more valuable than "dead" remainders.
    let post = post_residual as u32;
    let mut harmony_bonus = 0.0;
    if post > 0 {
        if post % 10 == 0 { harmony_bonus += 6.0; }        // divisible by 10
        if post % 20 == 0 { harmony_bonus += 4.0; }         // divisible by 20
        if post % 50 == 0 { harmony_bonus += 3.0; }         // divisible by 50
        if post % 25 == 0 { harmony_bonus += 2.0; }
        // dead-space penalty: residual not expressible by small items
        if post < 10 { harmony_bonus -= 12.0; }             // unusable sliver
        else if post < 20 { harmony_bonus -= 5.0; }
    } else {
        harmony_bonus += 15.0; // perfect fill
    }

    // Lookahead coupling: does post_residual exactly accommodate next item?
    if next_item_size > 0 {
        if post == next_item_size {
            harmony_bonus += 20.0; // perfect chain
        } else if post > next_item_size && (post - next_item_size) % 10 == 0 {
            harmony_bonus += 8.0;
        } else if post < next_item_size && post >= 10 {
            harmony_bonus += 2.0; // still usable for others
        } else if post < next_item_size && post < 10 {
            harmony_bonus -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        harmony_bonus -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a bin costs more early (want consolidation) but is fine
        // when mean residual across open bins is already fragmented.
        let fragmentation = (mean_residual / cap - post_residual as f64 / cap).abs();
        let mut penalty = 18.0 + 30.0 * (1.0 - progress);
        if open_bins_count > 0 && mean_residual < 15.0 {
            penalty -= 20.0; // open bins nearly full, new bin justified
        }
        if next_item_size > 0 && next_item_size > post_residual {
            penalty -= 5.0; // next item won't fit here anyway
        }
        score += penalty;
        let _ = fragmentation;
    }

    // Prefer filling fuller bins: residual fraction penalty (quadratic).
    let residual_frac = post_residual as f64 / cap;
    score += 10.0 * residual_frac * residual_frac;

    // Slight preference for bins whose residual is above mean (keep small ones tight).
    if post_residual as f64 > mean_residual && !is_new_bin {
        score += 3.0;
    }

    score -= harmony_bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize unusable small gaps: post_residual below the minimum item size
    // is dead space. Harsher the smaller (and more useless) it is.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0 + (10 - post_residual) as f64 * 20.0;
    } else if post_residual >= 10 && post_residual < 30 {
        // Small-but-usable gaps are risky: they may never be filled.
        score += 30.0 + (30.0 - post) * 1.5;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 40.0 - slack * 2.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Gap cannot host the next item: mild penalty for blocking lookahead.
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // encourage consolidating into existing bins.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 8.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open-bin pressure
        // and stream progression, but relieve pressure if mean residual is high.
        score += 25.0 + pressure + (step_index as f64 / total_items.max(1) as f64) * 20.0
                 - (mean_residual / cap) * 10.0;
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins whose residual is close to the item (tight fit) generally.
    let tightness = 1.0 - ((bin_residual - item_size) as f64 / cap);
    score -= tightness * 5.0;

    // Mild preference for fuller bins as the stream progresses.
    score -= (1.0 - (bin_residual as f64 / cap)) * (10.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near match: next item fits with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 / (1.0 + slack);
    }
    // Penalize dead space that no plausible small item can use
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }
    // Penalize small unusable post residuals relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Favor bins tighter than the mean (best-fit style)
    score -= (bin_residual as f64 - mean_residual).signum() * -1.0 * (bin_residual as f64 - mean_residual).abs() * 0.5;
    score -= (bin_residual as f64 - mean_residual) * 0.5;

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Mild preference for filling existing bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Slight penalty for opening new bins when many are already open
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that likely cannot be reused.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: bonus if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            score += 5.0;
        }
        // Discard bins whose residual is just below the next item (near-miss waste).
        if post_residual > 0 && post_residual < next_item_size {
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 5.0 * fit_ratio;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here would be poor.
    if bin_residual == bin_capacity {
        let avg_open = if open_bins_count > 0 { mean_residual } else { 0.0 };
        let pressure = avg_open / bin_capacity as f64;
        // Opening a new bin is good if existing bins are tight or fit is bad.
        let open_bonus = if fit_ratio < 0.55 || pressure < 0.25 {
            -18.0 + 20.0 * fit_ratio
        } else {
            22.0
        };
        score += open_bonus;
        // Slight preference to consolidate when many bins are open late in stream.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * t * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        return score;
    }

    // Prefer bins whose residual deviates beneficially from the mean residual
    // (pack into bins already committed to being full).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time-horizon modulation: early in the stream, be conservative with
    // near-full bins (keep flexibility); late, exploit them fully.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > item_size as u32 {
        score -= 4.0 * t; // late: fine to leave room for more items
    } else {
        score += 4.0 * (1.0 - t); // early: avoid near-exact fills
    }

    // Mild penalty for spreading across too many open bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: minimize wasted space, with a smooth non-linear (quadratic-ish) coupling
    // to stream progress: waste tolerance shrinks as the stream matures.
    let mut score = pr * (1.0 + 0.9 * progress * progress);

    // Smooth tightness reward: strongly favor small post_residual via inverse coupling.
    score -= 120.0 / (1.0 + pr * pr / 400.0);

    // Exact-fit bonus (smooth, peaked at pr == 0).
    score -= 60.0 * (-pr as f64 / 12.0).exp();

    // Lookahead coupling: reward if next item can use the post_residual,
    // penalize if it cannot (dead space risk), smoothly scaled.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 25.0 * (pr - nxt) / cap;
        } else {
            score += 15.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the waste is egregious (smooth threshold via sigmoid).
    if fitting_bins_count == 1 {
        let waste_sigmoid = 1.0 / (1.0 + (-(pr - 40.0) / 15.0).exp());
        score -= 40.0 * (1.0 - waste_sigmoid);
    }

    // New-bin candidate handling: an empty bin has pr == cap. Penalize it early
    // (prefer filling open bins), reward it late or when mean residual is fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).powi(2);
        score += 30.0 * (1.0 - progress) + 10.0;
        score -= 45.0 * progress * fragmentation;
    }

    // Mild penalty when many bins are open and this placement leaves a lonely fragment.
    score += 0.02 * open_bins_count as f64 * (pr / cap).powi(3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space classes via integer division.
    // Residuals that are multiples of small quantum sizes are "reusable" classes.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // Class by divisibility: highly composite residuals are more reusable.
        let class: f64 = if pr % 50 == 0 {
            0.0
        } else if pr % 25 == 0 {
            2.0
        } else if pr % 20 == 0 {
            3.0
        } else if pr % 10 == 0 {
            5.0
        } else if pr % 5 == 0 {
            8.0
        } else {
            12.0
        };
        score += class;

        // Lookahead coupling: does the next item fit in the post residual?
        if next_item_size > 0 {
            if next_item_size <= pr {
                // Reward proportionally to how well next item fills leftover.
                let fill = next_item_size as f64 / pr as f64;
                score -= 20.0 * fill;
            } else {
                // Dead space until next item's class: penalize if next item
                // leaves a "bad" residue class here.
                score += 6.0;
                if pr < 10 {
                    score += 10.0; // tiny unusable sliver
                }
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin for a poor reason.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large (large items deserve fresh space).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        // Base penalty so open bins with decent fits win; reduced for big items.
        let mut penalty = 35.0 - 25.0 * item_frac;
        // If no open bin fits, opening is inevitable: soften penalty.
        if fitting_bins_count == 0 {
            penalty -= 40.0;
        }
        // Early in the stream, having fresh bins is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty -= 10.0 * (1.0 - progress);
        score += penalty.max(-50.0);
    }

    // Mild pressure toward consolidating bins when many are open.
    score += 0.05 * open_bins_count as f64;

    // Slight nudge using mean residual: prefer bins below mean residual
    // (tighter bins) to keep large residuals available for large items.
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny nonzero leftovers are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Mid-range dead space (unusable for typical small items) is also penalized.
    if post_residual >= 10 && post_residual < 30 {
        score += 18.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 45.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins; reward dense packing.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: only attractive when the item is large and would leave
    // a huge unusable gap in any existing bin, or no bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base mild penalty so existing decent fits win.
        score += 30.0;
        // Large items relative to residual get a fresh-bin discount.
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.6 {
            score -= 20.0;
        }
        // If next item is large too, a fresh bin preserves flexibility.
        if next_item_size > 50 {
            score -= 8.0;
        }
    }

    // Coupling with mean residual: if this bin's residual is far below average,
    // it is a tight bin — favor filling it further.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.3;
    } else {
        score += (res_f - mean_residual) * 0.15;
    }

    // Lookahead: if next item exactly fits the post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize if next item cannot fit into post_residual (dead space confirmed).
    if next_item_size > post_residual && post_residual > 0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when the next item exactly matches post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        // Penalize post_residual that is slightly larger than next item (dead space after next placement).
        if post_residual > next_item_size && post_residual - next_item_size < 10 {
