        }
        // Bonus: next item fills this bin completely after placement.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Compare against mean residual: prefer bins whose residual deviates usefully.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev; // prefer below-average residual (tighter bins)

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when an open bin could fit decently.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 10.0 * (1.0 - progress);
        // New bin is attractive only if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild penalty for leaving residuals that no typical small item (>=1) can use.
    if post_residual > 0 && post_residual < 5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good; amplify near-zero waste.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * waste_frac * waste_frac;

    // Reward filling bins deeply (high fill ratio before placement).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Penalize large post_residual relative to the smallest plausible future item (1..100 interface).
    // Dead space below next item size is likely unusable.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 6.0 + 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Bonus when this bin can still host the lookahead item.
            score -= 3.0;
        }
    } else {
        // Last item: strongly prefer the fullest possible placement.
        score -= 8.0 * (1.0 - waste_frac);
    }

    // Last-chance bin: if this is the only fitting bin, opening a new bin wastes its residual.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 7.0 + 0.1 * bin_residual as f64;
    }

    // New-bin candidate handling: empty bin gets a base cost that shrinks over time
    // and when existing residuals are poor.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 14.0 - 6.0 * progress;
        // If mean residual across open bins is small, opening fresh is more attractive.
        score -= (mean_residual / 10.0).min(6.0);
        // If many bins fit, prefer reusing an existing one.
        score += 2.0 * (fitting_bins_count as f64).min(5.0);
    } else {
        // Mild penalty for spreading across too many bins early.
        score += 0.05 * open_bins_count as f64 * (1.0 - progress);
        // Reward matching bin residual closeness to item (good global packing).
        let tightness = 1.0 - (bin_residual - item_size).abs() as f64 / bin_capacity as f64;
        score -= 5.0 * tightness;
    }

    // Encourage leaving residuals that are multiples of common small sizes (modular harmony).
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with polynomial shaping
    let mut score = norm_pr.powf(1.5 + 1.5 * progress) * cap;

    // Smooth coupling: leftover is more costly as stream progresses (less time to fill it)
    score += 8.0 * norm_pr * (progress * progress);

    // Reward tight fits (small post_residual) with mild non-linearity
    score -= 12.0 * (1.0 - norm_pr).powi(3);

    // Lookahead: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            score -= 15.0 * (1.0 - gap / cap).powi(2);
        } else {
            score += 5.0 * (gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Slight preference for consolidating into fewer bins when many are open
    score += (open_bins_count as f64).ln() * 2.0 * norm_pr;

    // Mean-residual coupling: prefer bins near the mean (balanced filling)
    score += 4.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: neutral-ish baseline, slightly worse than good fits
    if bin_residual == bin_capacity {
        score += 6.0 + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post-residual: residues that are "dead space"
    // (small, unusable for typical items) are heavily penalized.
    // Class items into residue buckets via modulo arithmetic on capacity.
    let r = post_residual % 10;
    let dead = (1..=3).contains(&post_residual) || (post_residual > 0 && post_residual < 10 && r <= 3);
    if dead {
        score += 60.0;
    }

    // Harmonic quarter classes of capacity: prefer leaving quarters (25/50/75)
    // which combine well with future item sizes.
    let q = post_residual % 25;
    if post_residual > 0 && q == 0 {
        score -= 15.0;
    } else if q <= 5 {
        score += 5.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual,
    // penalize if next item cannot fit (wasted capacity for lookahead).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += 8.0;
        }
    }

    // Last chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // mean residual of open bins is small (bins nearly full) or many bins exist.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // If open bins are nearly full, new bin is more acceptable.
        let fullness = 1.0 - mean_residual / bin_capacity as f64;
        score -= fullness * 50.0;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If this item is large, a fresh bin is relatively better.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        // Mild preference for tighter existing bins as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
        // Penalize spreading across too many open bins.
        if open_bins_count > 8 {
            score += 2.0;
        }
    }

    // Integer-division threshold: post_residual in the "awkward middle"
    // (just above half of a quarter class) is less reusable.
    if post_residual > 12 && post_residual < 25 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

