    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if next item is large and this item is small, a fresh bin may be good.
        if next_item_size > item_size * 2 && post_residual < 40 {
            score -= 18.0;
        }
    }

    // Late in the stream, close out bins aggressively (avoid many tiny residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    // Avoid leaving residuals that no plausible item (min size ~1) can use anyway.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
