    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 0.8 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving room exactly usable by the next item.
            let gap = (post_residual - next_item_size) as f64;
            score -= 3.0 * (-gap / 15.0).exp();
        }
    }

    // Last-chance bonus: only bin that fits; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Mild penalty when many bins are open and this placement leaves a very fragmented residual.
    let frag = post_residual as f64 / 100.0;
    if frag > 0.0 && frag < 0.10 {
        score += (0.10 - frag) * 40.0 * (open_bins_count as f64).sqrt();
    }

    // Time horizon: late in the stream, prefer consolidating (avoid opening new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when open bins fit fine.
        let base = 6.0 + 14.0 * progress;
        score += base;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 4.0; // fresh bin can host the next item too
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean (fill below-average space).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Small global-load coupling: with few fitting bins, discourage spreading.
    if fitting_bins_count > 0 {
        score -= 1.5 / fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, tolerate large residuals less (prefer tight fits to save bins);
    // later, penalize large residuals more strongly to consolidate waste.
    let coupling = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * 2.0;
    score += 30.0 * coupling;

    // Reward near-perfect fits smoothly (quadratic trough at pr=0).
    score -= 8.0 * (-pr_norm * 6.0).exp();

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1e-9 {
        score -= 12.0;
    } else if next_item_size > 0 {
        // Penalize if next item can't fit here (this bin becomes dead for next step).
        let next_fits = (next_item_size as u32) <= post_residual;
        if !next_fits {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Mild penalty when this bin is much worse than the mean residual (outlier waste).
    score += 0.5 * (pr - mean_residual).max(0.0);

    // New-bin candidate: make it attractive only when open bins would leave bad residuals.
    if bin_residual == bin_capacity {
        score = pr + 20.0 * (1.0 - progress) + 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo 10 buckets
    let harm = post_residual % 10;
    // Perfect fits (post_residual == 0) are ideal
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Penalize residuals that are hard to fill later (dead space classes)
        // Residuals in [1..9] are near-useless; residuals divisible by 10 are reusable
        if harm != 0 {
            score += (10 - harm) as f64 * 1.5;
        } else {
            score -= 5.0;
        }
        // Small residuals (< 10) are dead space for items >= 10
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // Fraction-of-capacity classes: reward post_residual that is a "clean" fraction
    let frac = post_residual as f64 / cap;
    if (frac * 4.0).round() as u32 * 25 == post_residual {
        score -= 4.0; // quarter-capacity aligned residuals
    }

    // Integer division threshold: post_residual / 20 class
    let div20 = post_residual / 20;
    score += div20 as f64 * 2.0; // prefer bins with larger leftover class

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // harmonic bonus: next_item_size exactly consumes a harmonic class
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else if next_item_size <= bin_residual && next_item_size > post_residual {
            // next item fits bin but not after this placement -> wasteful
            score += 6.0;
        }
    } else {
        // last item: just minimize residual
        score += 0.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing decent fits
    if bin_residual == bin_capacity {
        let base_penalty = 30.0
            + open_bins_count as f64 * 1.5
            + (mean_residual - item_size as f64).max(0.0) * 0.3;
        // If next item is huge and current residual classes are poor, new bin less bad
        let relief = if next_item_size >= 60 { 10.0 } else { 0.0 };
        score += base_penalty - relief;
    }

    // Stream progression: late in stream, tighten packing (avoid many small residuals)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * mean_residual * 0.05;

    // Prefer bins whose residual is close to item size (tight fit) via quadratic term
    let tight = (bin_residual - item_size) as f64;
    score += tight * tight * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (items >= 1, but small gaps < 8 are almost never reusable) are heavily penalized.
    if post_residual > 0 && post_residual < 8 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit is highly desirable.
        score -= 40.0;
    }

    // Reward tight fits relative to item size.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Penalize leaving a gap just below the next item's size (near-miss dead space).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0; // can host the next item: good
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: mild incentive to fill existing bins rather than
    // proliferating bins, scaled by stream progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins whose residual is already low
    // (concentrate packing into nearly-full bins).
    score += 0.2 * ((bin_residual as f64 - mean_residual).abs());

    // New-bin candidate: empty bin has huge residual; make it unattractive
    // unless the item genuinely cannot fit anywhere well. Its raw post_residual
    // already dominates; add a fixed opening cost.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is great.
    score -= 12.0 * (-post_residual as f64 / 12.0).exp() * 10.0;

    // Penalize large dead space quadratically.
    score += 0.012 * (post_residual as f64).powi(2);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item would fit in the post-residual, reward;
    // if post_residual is small but nonzero and useless for the next item, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 0.5 * (nxt - post_residual as f64);
        }
        // Perfect chain: next item fills post-residual exactly.
        if post_residual as i64 == next_item_size as i64 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // existing fits are poor (large post_residual) or no bins fit well.
    if bin_residual == bin_capacity {
        // Mild penalty so we prefer reusing decently-fitting open bins.
        score += 10.0;
        // But if many open bins are nearly full (mean residual small),
        // opening a fresh bin early is fine (pre-staging).
        if mean_residual < 25.0 {
            score -= 12.0;
        }
        // Late in the stream, avoid opening bins that will be mostly wasted.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If item is large relative to capacity, a fresh bin guarantees a good fit.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
    }

    // Prefer filling bins with low residual relative to the fleet average
    // (consolidate scarce space).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Slight preference to keep the number of open bins from exploding early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Reward exact fills.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * (1.0 + 0.8 * progress + 0.6 * progress * progress);
    score += 20.0 * coupling;

    // Penalize dead space more sharply as stream progresses (quartic smooth term)
    score += 30.0 * norm_pr * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth exponential-like discount
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * tightness;

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            let gap = (nxt - pr) / cap;
            score += 8.0 * gap * gap * (1.0 + progress);
        }
    }

    // Last-chance bin: smooth bonus scaled by scarcity of fitting bins
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    } else {
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean residual context: prefer bins near (or below) the mean residual
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev.abs();

    // Mild penalty for spreading across many bins early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover belongs to a
    // "reusable" residue class (small, common sizes) should be rewarded.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Class A: post_residual divisible by 10 (common item sizes 10..80)
    // -> leftover likely reusable by future items. Reward.
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    // Class B: post_residual divisible by 20 -> even better (fits 20/40/60/80)
    if post_residual % 20 == 0 {
        score -= 6.0;
    }
    // Class C: post_residual divisible by 25 -> fits 25/50/75
    if post_residual % 25 == 0 {
        score -= 4.0;
    }

    // Dead-space penalty: tiny unusable leftovers (1..9) are near-wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Nonlinear coupling: penalize leaving large residual when many bins
    // are already open (fragmentation risk grows with open_bins_count).
    let open_pressure = (open_bins_count as f64).sqrt() * 2.0;
    score += frac * open_pressure;

    // Lookahead: if next item exactly fits post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves another residual: mild reward scaled
            // by how well it subdivides the leftover.
            let nfrac = (post_residual - next_item_size) as f64 / cap;
            score -= 5.0 * (1.0 - nfrac);
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += 4.0 * frac;
        }
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using
    // it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: make empty bins attractive only when the current
    // item is large relative to capacity (fresh bin gives best packing
    // potential for big items) or when mean residual across open bins is low.
    let empty = (bin_residual as f64 - bin_capacity as f64).abs() < 0.5;
    if empty {
        // baseline cost of opening a new bin
        score = 0.5 * cap;
        // discount for large items that would fragment an existing bin
        let big_item = item_size as f64 / cap;
        score -= 30.0 * big_item;
        // if existing bins are nearly full on average, new bin is cheap
        score -= 20.0 * (1.0 - mean_residual / cap);
        // early in stream, opening bins is fine (build a portfolio)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins close to the mean residual
    // (balanced packing keeps options open).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Integer-division threshold: bins whose residual floor(cap/4) bucket
    // matches item's quarter-class get a small alignment bonus.
    let q_bin = bin_residual / (bin_capacity / 4).max(1);
    let q_item = item_size / (bin_capacity / 4).max(1);
    if q_bin == q_item {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual gap is "dead" if it is smaller than the smallest plausible item.
    let dead_threshold = 10.0_f64.min(next_item_size.max(1.0) as f64);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Perfect or near-perfect fill: strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Open bins pressure: discourage spreading across many bins when not needed,
    // but allow opening a new bin when this is the only fitting bin (avoid wasting).
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else {
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }
    // If next item would NOT fit in post_residual, penalize (dead space for lookahead).
    else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when this placement
    // would create large dead space or the bin is nearly full already.
    if bin_residual == bin_capacity {
        // Empty bin: neutral-ish baseline; make it slightly unattractive so
        // existing bins with decent fits are preferred.
        score += 12.0;
        // But if the item is huge relative to mean residual, opening fresh is fine.
        if (item_size as f64) > mean_residual {
            score -= 20.0;
        }
    }

    // Stream progression: later in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect chain fit (post_residual == next_item_size) is highly desirable.
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize residuals too small for the next item (dead space risk).
        let miss = (next_item_size - post_residual) as f64;
        score += 6.0 * (miss / bin_capacity as f64);
    }

    // Reward tight fits of the current item (small post_residual relative to capacity).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 15.0 * tightness * tightness;

    // Penalize creating residual far below the smallest plausible item (dead space),
    // scaled by how much slack other bins have (mean_residual).
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.35 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild preference for consolidating into more-populated bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    // Slight penalty for leaving residual that matches neither current nor next needs.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // residual too small for next item: penalize proportionally
            let miss = (next_item_size - post_residual) as f64;
            score += 6.0 * (miss / 100.0);
        }
    } else {
        // last item: just minimize waste
        score -= 15.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many fitting bins: mild penalty to conserve tight bins for harder items
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap when many items remain and open bins are crowded,
        // expensive when stream is ending or few bins fit the item
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 * (1.0 - progress);
        score += 5.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 4.0;
        }
        if fitting_bins_count == 1 {
            score += 30.0; // don't abandon the only fitting bin for a fresh one
        }
    }

    // Global state coupling: prefer bins deviating favorably from mean residual
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Slight preference for filling larger-residual bins late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    // Base: prefer small post-residual, with smooth non-linear polynomial coupling
    let mut score = post_norm * (1.0 + 2.0 * post_norm * post_norm);

    // Tight-fit reward: smooth bell around exact fit, scaled by stream progress
    let tightness = 1.0 - post_norm;
    score -= tightness * tightness * (1.0 + progress);

    // Penalize leaving residuals that are too small to be useful later
    // (smooth penalty via cubic in post_norm, stronger late in stream)
    let dead = (0.3 - post_norm).max(0.0) / 0.3;
    score += dead * dead * (1.0 + 2.0 * progress) * 5.0;

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let pair_waste = (post_residual - next_item_size) as f64 / cap;
            score -= (1.0 - pair_waste) * 3.0;
        } else {
            // penalize residuals that block the next item proportionally to overlap
            let overlap = (nxt - post) / cap;
            score += overlap * overlap * 4.0;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0 * (0.5 + progress);
    }

    // Mild penalty for spreading across many open bins vs consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 0.15 * post_norm;

    // Prefer bins whose residual deviates from the mean in a useful (smaller) direction
    let mean_norm = mean_residual / cap;
    score += (mean_norm - post_norm) * 1.5;

    // Slight bias toward opening a new bin early (when many bins fit) vs late
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 1.0 - 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: post_residual that cannot fit typical small items (1..=10).
        if post_residual < 10 {
            score += 60.0;
        }
        // Harmonic classes: quantize post_residual into eighths of capacity.
        let class = (post_residual * 8 / bin_capacity) as f64;
        score += class * 3.0;

        // Integer division thresholds: prefer post_residual divisible by small harmonics
        // (post_residual % 5 == 0 or % 10 == 0 leaves friendly gaps).
        if post_residual % 10 == 0 {
            score -= 6.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_post = post_residual - next_item_size;
        if next_post == 0 {
            score -= 400.0;
        } else {
            score -= (next_item_size as f64) * 1.5;
            if next_post < 10 {
                score += 25.0;
            }
        }
    } else if next_item_size > 0 {
        // Next item cannot use the gap: penalize large leftover gaps more.
        score += post * 0.4;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: keep it neutral-ish unless open bins are fragmented.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when mean residual of open bins is small
        // (existing bins nearly full) or few bins can fit.
        score -= (fitting_bins_count as f64) * 8.0;
        score += (mean_residual / cap) * 40.0;
        // Slight preference for reusing bins early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 20.0;
    }

    // Mild preference to fill bins with larger residuals when many bins open.
    score -= (bin_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // Gap threshold: smallest plausible item is 1, but gaps below ~20 are hard to fill.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 20.0 {
        score += (20.0 - gap) * 2.5; // dead-space penalty ramps as gap shrinks
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward leaving a gap that the lookahead item can exactly fill (k=2 lookahead)
    if next_item_size > 0 && post_residual > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual <= next_item_size + 10 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when fits are bad
        score += 55.0;
        // Pressure grows with number of open bins (avoid bin sprawl)
        score += open_bins_count as f64 * 1.5;
        // Early in stream, opening bins is cheaper (more room to consolidate later)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
        // If mean residual across open bins is large, fits are wasteful -> new bin ok
        score -= (mean_residual - 40.0).max(0.0) * 0.8;
        // Large items fit cleanly in fresh bins
        if item_size >= 50 {
            score -= 20.0;
        }
    } else {
        // Mild pressure against scattering across many bins
        score += open_bins_count as f64 * 0.3;
    }

    // Prefer bins whose residual is already small (tight packing direction)
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual that still accommodates the next item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + (post_residual as f64 - next_item_size as f64) * 0.3;
    } else if next_item_size > 0 {
        // Dead space relative to what the next item needs.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Penalize very small unusable remnants (fragmentation).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward filling bins tightly relative to the average residual landscape.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-ish, but discourage when any open bin
    // gives a reasonable fit; encourage when current bin would leave heavy waste.
    if bin_residual == bin_capacity {
        let waste_if_placed_here = bin_residual - item_size;
        if next_item_size > 0 && waste_if_placed_here < next_item_size && waste_if_placed_here > 0 {
            score -= 20.0; // open a fresh bin rather than fragment this one
        } else {
            score += 30.0; // prefer existing bins when fit is decent
        }
    }

    // Late in the stream, prioritize compactness (fewer wasted opens).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalize progress through the stream (0..1).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core tightness preference: strongly reward small post_residual (best-fit),
    // with a superlinear push so near-perfect fits dominate.
    let pr = post_residual as f64;
    score += 0.35 * (pr / cap).powi(2) * cap;

    // Penalize wasteful dead space relative to what the item needed,
    // but only when the bin is not the new-bin candidate.
    let is_new_bin = bin_residual == bin_capacity;
    if !is_new_bin {
        // Exact fit is gold.
        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual < 10 {
            score -= 25.0;
        }
        // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
        // unless the fit is terrible.
        if fitting_bins_count == 1 {
            score -= 18.0 + 0.2 * item_size as f64;
        }
        // Coupling with lookahead: if next item fits into the post-residual,
        // reward keeping this bin chainable; otherwise penalize blocking.
        if next_item_size > 0 {
            if (post_residual as u64) >= (next_item_size as u64) {
                score -= 8.0 + 0.1 * next_item_size as f64;
            } else {
                // Post residual too small for next item: penalize proportionally
                // to how "stranded" that space is (dead space).
                let stranded = pr / cap;
                score += 12.0 * stranded;
            }
        }
        // Global state: if mean residual is high and this bin is far above mean,
        // slightly favor consolidating into fuller bins (reduce bin count pressure).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 5.0 * dev;
        // Early in the stream, be more willing to spread items (keep flexibility);
        // later, consolidate aggressively.
        score -= (1.0 - progress) * 6.0 * (1.0 - pr / cap);
        score += progress * 4.0 * (pr / cap);
    } else {
        // New-bin candidate: baseline cost of opening a fresh bin.
        // Attractive when item barely fits anywhere (fitting_bins_count small)
        // or when item is large (would leave awkward remainder in existing bins).
        score += 30.0;
        score -= 0.15 * item_size as f64;
        if fitting_bins_count <= 1 {
            score -= 22.0;
        }
        if fitting_bins_count >= 3 {
            score += 20.0;
        }
        // If the next item is large and current open bins have big residuals,
        // opening a fresh bin preserves those bins for the next item.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 10.0;
        }
        // Late in the stream, opening new bins is more costly (fewer chances to fill).
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_post = post / cap; // in [0, 1]
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Base: quadratic in normalized post-residual, modulated by progress
    let mut score = post * (1.0 + 0.8 * p2 + 0.6 * p3);

    // Smooth interaction: large dead space penalized more as stream progresses
    let dead = norm_post * norm_post;
    score += 30.0 * dead * (0.5 + progress);

    // Reward tight fits smoothly (small post residual)
    score -= 12.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 + 0.5 * p2);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 4.0 * (post / (next_item_size as f64 + 1.0)) * progress;
    }

    // Mild preference to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * norm_post;

    // New-bin candidate: keep it neutral-to-slightly-attractive early, worse late
    if bin_residual == bin_capacity {
        score += 6.0 * progress - 4.0 * (1.0 - progress) * norm_post;
    }

    // Deviation from mean residual: prefer bins near the mean (balanced usage)
    score += 0.3 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: bucket post_residual into capacity-fraction classes.
    // Small post_residual classes are "dead space" -> penalize less (already small).
    // Mid-range residuals (30..60) are the most valuable for future items -> reward.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let class: f64 = if post_residual == 0 {
        0.0 // perfect fit, strongly favored
    } else if post_residual < 10 {
        5.0 // tiny dead space, nearly useless
    } else if post_residual < quarter {
        2.0
    } else if post_residual < half {
        -4.0 // sweet spot: fits mid-size future items
    } else {
        0.0
    };
    score += class;

    // Integer-division harmonic class on post_residual (mod 10): residuals that
    // align with common item-size granularities are more reusable.
    let gran = (post_residual % 10) as f64;
    score -= 0.3 * (5.0 - (gran - 5.0).abs()) * (post_residual as f64 / bin_capacity as f64);

    // Perfect fit bonus scaled by how tight the placement is.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item uses the leftover
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * usage;
        } else {
            // next item too big for this residual: mild penalty for wasting
            score += 3.0;
        }
    }

    // New-bin candidate handling: prefer opening a fresh bin when all open bins
    // would leave very poor fits (item barely squeezes in).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Opening new bin is attractive if the item is large (would leave crumbs elsewhere)
        score -= 8.0 * tightness;
        // But discourage hoarding bins early in the stream
        score += 12.0 * (step_index as f64 / total_items.max(1) as f64);
        // If many bins already open and mean residual is large, prefer reusing
        score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    } else {
        // Penalize placements that leave a residual just below the smallest item class
        if post_residual > 0 && post_residual < 10 {
            score += 6.0;
        }
        // Mild preference for bins with lower residual among equally fitting bins
        score += 0.02 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Medium gaps that likely can't fit future items (items >= 10).
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(10)) {
        score += 12.0;
    }

    // Reward tight fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: prefer already-open bins over proliferating bins.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit = (bin_residual - item_size) as f64 <= mean_residual;
        if decent_fit {
            score += 45.0; // penalize new bin when an open bin fits reasonably
        } else {
            score -= 15.0; // encourage fresh bin when fits are all poor
        }
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Slight preference for fuller bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - bin_residual) as f64 * (0.3 + 0.4 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.04;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits proportional to item size consumed.
    let tightness = 1.0 - post_residual as f64 / cap;
    score -= tightness * item_size as f64 * 0.6;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual < 10 {
        // Tiny dead space is nearly useless later: penalize.
        score += 9.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 28.0;
    }

    // Lookahead (k=2): reward bins whose post-residual will accommodate the
    // next item snugly; penalize if next item cannot fit afterwards.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 16.0 * (1.0 - gap as f64 / cap);
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Brand-new empty bin candidate: penalize mildly so it only wins when
    // existing fits are genuinely poor (large post_residual, no lookahead fit).
    if bin_residual == bin_capacity {
        score += 22.0 + mean_residual * 0.15;
    }

    // Global state: with many open bins and large mean residual, push toward
    // consolidation into existing bins.
    score += open_bins_count as f64 * 0.6;
    score -= mean_residual * 0.06;

    // Dynamic time horizon: early in the stream, be slightly more selective
    // (keep bins flexible); late in the stream, accept good-enough fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to progress.
    // Late in the stream, tight fits (small post_residual) matter more.
    let mut score = pr * (1.0 + progress * norm_pr * (1.0 - norm_pr) * 4.0);

    // Penalize large dead space super-linearly as the stream matures.
    score += (norm_pr * norm_pr) * cap * (0.5 + progress);

    // Reward perfect-ish fits smoothly via (1 - norm_pr) coupling.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * item_size as f64 * (0.3 + 0.7 * progress);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - progress);
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild pressure to prefer filling bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 3.0;

    // Deviation from mean residual: prefer bins whose outcome is near/above mean fill.
    score += (pr - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes over small divisors.
    // Residuals that are "harmonically useful" (divisible by common item sizes)
    // are rewarded, since future items more likely to fit exactly.
    let r = post_residual;
    let mut harmony: f64 = 0.0;
    for d in [10u32, 20, 25, 50] {
        if r % d == 0 && r > 0 {
            harmony += 4.0;
        }
    }
    score -= harmony;

    // Dead-space penalty: residuals too small to hold the minimum item (1..100 range,
    // but conservative small-item threshold) are nearly useless.
    if r > 0 && r < 10 {
        score += 30.0;
    }

    // Perfect fit reward.
    if r == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain of perfect fits).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0;
        } else if next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot class.
            let over = (next_item_size - r) % 100;
            score += 2.0 + over as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer filling bins whose residual deviates below the mean (tighter bins first),
    // keeping loose bins available for larger future items.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for using existing bins vs opening new ones as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as the stream matures and bins accumulate.
        score += 8.0 + 12.0 * progress + open_bins_count as f64 * 0.5;
        // But if no open bin fits well (post residual here is large and clean), allow it.
        if item_size >= 50 {
            score -= 6.0;
        }
    }

    // Integer-division threshold: bins whose residual is at least half capacity are
    // flexible; penalize leaving a half-full bin untouched.
    if bin_residual as f64 > bin_capacity as f64 * 0.5 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead-space gaps heavily (strict dead-space avoidance).
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (1.0 - (post_residual as f64) / 12.0);
    } else if post_residual > 12 && post_residual < 25 {
        score += 12.0 * (1.0 - (post_residual as f64 - 12.0) / 13.0);
    }

    // Perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward bins whose residual can still fit the next item (lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: mildly discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.3;

    // Mean-residual coupling: if this bin's residual is far below mean, it is a laggard bin; prefer filling it.
    let diff = mean_residual - bin_residual as f64;
    score -= 0.15 * diff;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: strongly reward, scaled by how snug the chain fit is
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leftover dead space
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize post_residual (already base term)
        score -= 4.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge or fit is bad
    if bin_residual == bin_capacity {
        // Opening new bin keeps perfect residual 100-item_size; only attractive for big items
        let keep = (bin_capacity - item_size) as f64;
        score += 5.0 - 0.05 * item_size as f64;
        if next_item_size > 0 && keep >= next_item_size as f64 {
            score -= 3.0; // new bin can chain next item
        }
    }

    // Late in stream: consolidate, discourage spreading across many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (open_bins_count as f64).ln().max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact fits strongly
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: penalize dead space that the next item cannot use
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }
    // Lookahead: reward residual that exactly accommodates the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 4.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Time horizon: early in the stream, be more willing to fragment
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    // Global state: many open bins with slack -> prefer consolidating into low-residual bins
    if open_bins_count > 2 {
        score -= (mean_residual - post_residual as f64).abs() * 0.05;
    }

    // New-bin candidate: baseline between a mediocre fit and a good fit
    if bin_residual == bin_capacity {
        score = 18.0 + item_size as f64 * 0.08 - (post_residual as f64 * 0.05);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: residual value decays with stream progress
    score -= 30.0 * norm_pr * (1.0 - progress) * (1.0 - norm_pr * 0.5);

    // Penalize large dead space quadratically, more so early (waste compounds)
    score += 40.0 * norm_pr * norm_pr * (1.0 - progress);

    // Reward tight fits: post_residual near zero
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_item;

    // Lookahead coupling: smooth interaction between post residual and next item
    if next_item_size > 0 {
        let fit_next = (norm_pr - norm_next).max(0.0);
        score -= 15.0 * (1.0 - fit_next) * norm_next * (1.0 - progress);
        score += 10.0 * fit_next * fit_next;
    }

    // Last-chance bonus (smoothly): only fitting bin -> strong reward
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * (1.0 - progress);
    }

    // Penalize opening new bins when many open bins have slack (smooth in open count)
    let open_f = open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += 8.0 + 3.0 * open_f * (1.0 - progress);
    } else {
        score -= 5.0 * (1.0 - 1.0 / (1.0 + open_f));
    }

    // Mean residual coupling: prefer bins deviating favorably from mean
    let mean_norm = mean_residual / cap;
    score += 10.0 * (mean_norm - norm_pr) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover space: capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap;

    // Penalize dead space that is too small to be useful later.
    // Items are 1..=100; leftover below ~10 is nearly dead.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Modulo classes on post_residual: leftovers that match common item
    // size bands (multiples of 10, 25, 50) are more reusable.
    let reusable = (post_residual % 10 == 0)
        || (post_residual % 25 == 0)
        || (post_residual % 50 == 0);
    if reusable {
        score -= 12.0;
    }

    // Lookahead coupling: reward leftovers that can host the next item exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect chaining
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score -= 60.0;
            } else if gap < 25 {
                score -= 25.0;
            } else {
                score -= gap as f64 * 0.3;
            }
        } else {
            // next item cannot fit here: leftover value depends on future reusability
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it attractive only when the item fits poorly
    // everywhere else. Base new-bin score near capacity fraction 1.0.
    if bin_residual == bin_capacity {
        // New bin starts fresh; its post_residual = cap - item.
        // Prefer opening a new bin when the current item leaves a large,
        // clean residual (good for future items) AND alternatives are bad.
        score -= 30.0;
        if item_size >= 50 {
            score -= 20.0; // big items deserve fresh bins
        }
        if post_residual % 10 == 0 {
            score -= 10.0;
        }
    }

    // Mean residual context: when open bins are on average spacious,
    // favor filling them rather than opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_gap = (mean_residual - post).abs();
    score += mean_gap * 0.05 * (1.0 - progress);

    // Mild preference to keep number of open bins stable early on
    score += open_bins_count as f64 * 0.02 * progress;

    // Small tie-break: tighter fit (smaller post_residual) still preferred overall
    score += post_frac * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: smaller post_residual is already favored by base term.

    // Dead-space penalty: post_residual in a small unusable gap (< next item or < min item 1..10)
    let min_item = 1u32;
    if post_residual > 0 {
        let unusable = post_residual < next_item_size.max(min_item) && next_item_size > 0;
        if unusable {
            score += 12.0 * (1.0 - post_residual as f64 / 10.0).max(0.0);
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: with many open bins, discourage opening new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New bin candidate: penalize relative to open bins count and mean residual
        score += 8.0 + open_bins_count as f64 * 2.0 + mean_residual * 0.3 + progress * 10.0;
        // But if current bin would leave a bad dead space, new bin becomes attractive
        if post_residual > 0 && post_residual < next_item_size.max(min_item) && next_item_size > 0 {
            score -= 10.0;
        }
    } else {
        // Mild reward for using already-open bins when they fit well
        score -= 2.0;
        // Penalize wasting a large residual on a small item when other bins exist
        if post_residual as f64 > mean_residual * 1.5 {
            score += 4.0;
        }
        // If next item fits exactly in post_residual, big bonus
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit (dead space eliminated)
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // 2-step lookahead: reward when the next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            score -= 40.0 - slack.min(60) as f64 * 0.5;
        } else {
            // next item cannot follow in this bin: mild penalty if we strand space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Compare residual against mean residual across open bins
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a brand-new bin when a decent fit exists elsewhere
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if item fits poorly everywhere else
        score += 25.0;
        if next_item_size > 0 && next_item_size <= bin_residual - item_size {
            score -= 20.0; // fresh bin can also host the next item
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Dead-space penalty for tiny post-residuals that are likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead coupling: reward leaving room for the next item when it's large.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            score -= 4.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Penalize placements that leave a residual too small for the next item.
            score += 3.0 * (-gap / bin_capacity as f64);
        }
    }

    // Global state: when many bins are open with high mean residual, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    score -= 2.0 * (mean_residual / bin_capacity as f64 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: allow opening a fresh bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // A new bin is attractive if the item is large and current fits are loose.
        let tight_best = fill_ratio < 0.55 && fitting_bins_count > 0;
        if tight_best || fitting_bins_count == 0 {
            score -= 10.0 + 8.0 * (item_size as f64 / bin_capacity as f64);
        } else {
            score += 15.0; // discourage wasteful new bins when a good fit exists
        }
    }

    // Mild preference for near-exact fills.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_n = pr / cap; // normalized post residual in [0,1]
    let t = progress;
    // smooth interaction: polynomial in pr_n modulated by progress
    score += 20.0 * (pr_n * pr_n) * (0.5 + t) - 10.0 * pr_n * (1.0 - t);

    // Penalize very small dead space (unusable slivers) smoothly
    let sliver = (1.0 - pr_n).powi(6);
    score += 15.0 * sliver * (1.0 - t);

    // Lookahead coupling: reward post residual matching next item smoothly
    if next_item_size > 0 {
        let nxt = (next_item_size as f64 / cap).clamp(0.0, 1.0);
        let diff = pr_n - nxt;
        score -= 12.0 * (-diff * diff * 40.0).exp();
    }

    // Last-chance bin bonus (smooth)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - pr_n);
    }

    // Mild penalty tied to mean residual deviation
    score += 0.05 * (mean_residual - pr).abs();

    // Encourage tighter fits overall
    score -= 5.0 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: quantize post_residual into capacity fractions.
    let post_f = post_residual as f64;
    let frac = post_f / cap; // 0..1 fraction of capacity left
    let harmonic_class = (frac * 10.0).floor(); // 0..9 decile of residual

    // Reward small residuals (tight fits), but with harmonic (quantized) structure.
    score -= (10.0 - harmonic_class) * 1.5;

    // Strong bonus for near-perfect fills (post_residual in lowest decile).
    if post_residual <= bin_capacity / 10 {
        score -= 6.0;
    }

    // Penalize dead space that no small item (min size 1) could plausibly waste:
    // leftovers in awkward mid ranges (e.g. 30..50) are hard to fill.
    if post_residual > bin_capacity / 4 && post_residual < bin_capacity / 2 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward heavily; if next item is much larger than post residual, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size <= post_residual {
            score -= 2.0;
        } else {
            // next item won't fit here; penalize proportionally to mismatch
            score += ((next_item_size - post_residual) as f64) / cap * 4.0;
        }
    }

    // Modulo threshold logic on item size: large items (>50% cap) prefer fresh bins
    // to avoid fragmenting partially-filled bins needed for small items.
    let item_class = (item_size as f64 / cap * 4.0).floor(); // 0..3
    if item_class >= 2 && bin_residual < bin_capacity {
        score += 2.0;
    }

    // Early in stream: encourage consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    // Pull toward mean residual: prefer bins whose residual is near average
    // (balanced packing), unless it's a last-chance fit.
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 2.0;

    // New-bin candidate: give it a moderate default so it wins only when
    // existing bins are poor fits.
    if bin_residual == bin_capacity {
        score = cap * 0.35 + item_size as f64 * 0.2;
        if fitting_bins_count <= 1 {
            score -= 5.0; // nothing else fits well; new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small
    // to be usable by future items (typical item range 1..=100).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10.0 - post_residual as f64) * 4.0;
    } else if post_residual == 0 {
        // Perfect fit is highly rewarded.
        score -= 25.0;
    } else {
        // Moderate reward for tight fits relative to bin capacity.
        let tightness = post_residual as f64 / bin_capacity as f64;
        score -= 15.0 * (1.0 - tightness);
    }

    // Penalize leaving residuals just below common item sizes (unusable gaps).
    let gap_thresholds: [u32; 5] = [10, 20, 30, 50, 80];
    for t in gap_thresholds.iter() {
        if post_residual > 0 && post_residual < *t && (bin_residual as u64) >= (*t as u64) {
            score += 6.0;
        }
    }

    // Open bins pressure: discourage spreading when many bins are open.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 20.0);
    score += 2.5 * open_pressure;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_fit = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - lookahead_fit / bin_capacity as f64);
    } else if next_item_size > post_residual as u32 && next_item_size > 0 {
        // Next item won't fit here; slight penalty if this creates dead space.
        if post_residual > 0 && post_residual < 15 {
            score += 12.0;
        }
    }

    // New-bin candidate: neutral baseline, only chosen when open bins are bad.
    if bin_residual == bin_capacity {
        score += 5.0 + 1.5 * open_pressure;
        // Prefer new bin if all open bins would leave tiny dead space.
        if post_residual > 0 && post_residual < 10 {
            score -= 30.0;
        }
    }

    // Mean residual coupling: penalize bins far below mean (fragmented).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item fills this bin exactly
        } else {
            score += gap * 0.6;
        }
        // penalize post_residual that is unusable (smaller than smallest plausible item)
        if post_residual < next_item_size.min(10) {
            score += 15.0;
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // Prefer bins whose residual is small relative to mean (compact packing)
    score += (mean_residual - bin_residual as f64) * 0.25;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize creating very small dead space that likely becomes waste
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: make it unattractive unless all open bins would leave big waste
    if bin_residual == bin_capacity {
        // waste if we open a new bin while a decent fit exists
        score += 25.0 + open_bins_count as f64 * 2.0;
        // but if the item leaves a huge hole in every open bin, opening is fine
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Slight preference for tighter fits overall
    score += (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits nonlinearly.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness * tightness;

    // Dead-space penalty: leftover that cannot fit the next item is wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 2.5 * dead;
    }

    // Lookahead synergy: bonus if the next item fits exactly in the post-residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more when open bins exist
    // and the stream is early (many future items to fill existing space).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 30.0 * (1.0 - 0.5 * progress);
        if fitting_bins_count > 0 {
            new_bin_penalty += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Late in the stream, waste matters less; ease the penalty.
        new_bin_penalty *= 1.0 - 0.3 * progress;
        score += new_bin_penalty;
    }

    // Global fragmentation pressure: if mean residual is large relative to
    // capacity, encourage consolidating into existing bins.
    let frag = mean_residual / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= 5.0 * frag;
    }

    // Mild preference for bins with residual close to the item (avoid
    // dumping small items into large residuals).
    if bin_residual > bin_capacity {
        score += 100.0; // safety guard, should not occur
    }
    let waste = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 4.0 * waste * waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = (pr / cap).clamp(0.0, 1.0);

    // Base: prefer small post_residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * fit_norm * fit_norm);

    // Tight-fit reward: smooth polynomial coupling of post_residual with capacity
    let tightness = 1.0 - (pr / cap).powi(2);
    score -= 12.0 * tightness * (item_size as f64 / cap);

    // Stream progress: later in stream, penalize wasted residual more (quadratic in progress)
    score += pr * 0.8 * progress * progress;

    // Last-chance bonus: smooth sigmoid-like coupling with fitting_bins_count
    if fitting_bins_count <= 1 {
        score -= 15.0;
    } else {
        score -= 15.0 / (fitting_bins_count as f64).powi(2);
    }

    // Lookahead: if next item fits the post residual, reward; smooth interaction
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = 1.0 - ((pr - nxt) / cap).powi(2);
            score -= 10.0 * slack * (nxt / cap);
        } else {
            // penalize leaving residual that next item cannot use
            score += 5.0 * (1.0 - progress) * (pr / cap);
        }
    }

    // Open-bin pressure: many open bins -> discourage adding to them mildly
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + progress) * 2.0;

    // Mean residual coupling: prefer bins deviating smoothly from mean (balance residuals)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate: neutral baseline with slight progress-dependent bias
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) - 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Small post_residual = tight fit, reward strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else {
        // Dead-space penalty grows for residuals in the "awkward" class
        // (too small for typical items 10..80 but wasteful).
        if post_residual < 20 {
            score += 15.0; // unusable sliver
        }
        // Modulo-10 harmonic class: residuals divisible by 10 align with
        // common item sizes, making them more reusable.
        let m10 = post_residual % 10;
        score -= (10 - m10) as f64 * 0.8; // exact multiples of 10 favored
        // Modulo-5 secondary class
        let m5 = post_residual % 5;
        if m5 == 0 {
            score -= 3.0;
        }
        // Integer-division threshold: residual >= half capacity is a
        // "rich" bin; keep it available for large future items.
        if post_residual * 2 >= bin_capacity {
            score += 8.0;
        }
    }

    // Capacity-fraction coupling: how well does the item fill the bin?
    let fill = item_size as f64 / cap;
    score -= fill * 12.0;

    // Lookahead: does next item fit into post_residual? Harmonic check
    // via integer division.
    if next_item_size > 0 {
        let nx = next_item_size;
        if nx <= post_residual {
            // next item fits exactly-ish: reward if it nearly empties bin
            let after2 = post_residual - nx;
            if after2 <= 10 {
                score -= 20.0;
            } else {
                score -= 8.0;
            }
            // exact pairing (post_residual == nx) is a perfect chain
            if nx == post_residual {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: penalize leaving mid-range gaps
            // that neither fit the next item nor are near-zero.
            if post_residual >= 10 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when open bins are congested
    // (low mean residual) or late in the stream with many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = mean_residual / cap; // small = congested bins
        let penalty = 30.0 + 40.0 * congestion + 15.0 * (1.0 - progress);
        // Exception: very large items deserve a fresh bin.
        if item_size >= 70 && congestion < 0.35 {
            score = penalty - 10.0;
        } else {
            score = penalty;
        }
    }

    // Mild preference to fill emptier bins when many are open.
    if open_bins_count > 4 {
        score -= (bin_residual as f64 - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

