    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness.powf(2.2);

    // Reward fullness of the bin (item_size relative to capacity)
    score -= 8.0 * (item / cap).powf(1.5);

    // Last-chance bonus: if this is the only bin that can fit, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
