    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev.powf(2.0) * (0.5 + progress);

    // New-bin candidate handling: empty bin gets a mild penalty that shrinks as stream progresses
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress) + 5.0 * (1.0 - item / cap);
    }

    // Slight preference for consolidating into fewer bins early on
    score += 0.5 * (open_bins_count as f64).powf(0.7) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
