    // Last-chance bonus: if this is the only bin that fits, prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize spreading across many open bins when residuals are similar
    let progress = step_index as f64 / total_items.max(1) as f64;
    let closeness = 1.0 - ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64);
    score -= 15.0 * closeness * (1.0 - progress);

    // New-bin candidate handling: empty bin is a fallback; make it costly
    // unless the item is huge relative to typical residuals
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 80.0 };
        score += desperation + 20.0 * (1.0 - fill);
        // late in the stream, prefer consolidating into open bins
        score += 30.0 * progress;
    }

    // Mild preference for bins with larger residuals early (first-fit flavor)
    score -= 0.05 * bin_residual as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // smooth non-linear coupling: post_residual penalized more heavily as stream progresses
    score += 20.0 * norm_pr * norm_pr * progress;

    // reward tight fits (small post_residual) more strongly late in the stream
    score -= 15.0 * (1.0 - norm_pr).powi(3) * (0.5 + 0.5 * progress);

    // lookahead: reward if next item fits the post residual (smooth sigmoid-like)
    let fits_next = (norm_next - norm_pr) / 0.15;
    let sig = 1.0 / (1.0 + fits_next * fits_next);
    score -= 8.0 * sig * (1.0 - progress);

    // last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // penalize opening new bins early; mildly favor consolidation late
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (30.0 - 20.0 * progress);

    // mean residual coupling: prefer bins deviating from mean residual (balance)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // reward large item fraction placement (fills bins densely)
    score -= 10.0 * norm_item * (1.0 - norm_item) * 4.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group into capacity-fraction bands.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit bonus: post_residual in {0} gets strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals that no plausible item (1..100) can use well.
    // Harmonic classes via integer division: post_residual / 10 -> class 0..10
    let post_class = post_residual / 10;
    // Class 0 (0..9) is dead space; class 9 (90..99) is nearly-full bin (fine).
    if post_class == 0 && post_residual > 0 {
        score += 60.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 40.0 + 0.5 * (next_item_size as f64);
        } else {
            // Next item won't fit here; penalize proportionally to wasted lookahead potential.
            score += 0.3 * (next_item_size as f64 - post) * (post / cap);
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin, scaled by how full it already is.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let fill_ratio = 1.0 - (bin_residual as f64) / cap;
        score -= 50.0 + 80.0 * fill_ratio;
    }

    // New-bin candidate: neutral-ish baseline; prefer it only when mean residual
    // across open bins is small (open bins nearly full anyway).
    if bin_residual == bin_capacity {
        score -= 10.0;
        score += 0.2 * (mean_residual / cap) * (open_bins_count as f64).sqrt();
    }

    // Stream progression: early on, be more willing to open bins (spread items);
    // late, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.05 * post;

    // Harmonic modulo coupling: post_residual mod 25 classes — residuals near
    // common item sizes (multiples of 10/25) are more reusable.
    let m = post_residual % 25;
    if m >= 10 && m <= 20 {
        score -= 15.0;
    }

    // Prefer bins whose residual is close to mean residual (balanced packing).
    score += 0.1 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small unusable gaps are the worst outcome. Penalize post_residual
    // quadratically when it falls into the "dead zone" (small gaps that few
    // future items can fill).
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr <= 20.0 {
            // tiny leftover: likely unusable dead space -> heavy penalty
            score += (21.0 - pr) * (21.0 - pr) * 0.8;
        } else if pr <= 45.0 {
            // medium gap: moderately risky
            score += (46.0 - pr) * 0.35;
        } else {
            // large gap: still usable by many item sizes -> mild bonus
            score -= 3.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 60.0;
    }

    // --- Reward tight fit relative to the item placed ---
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // --- Last-chance bin pressure ---
    // If this is the only bin that can fit the item, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + 0.5 * item_size as f64;
    }

    // --- Open-bin pressure (archetype coupling) ---
    // When many bins are open, discourage opening new ones and encourage
    // consolidating into existing residual space.
    let ob = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // brand-new bin candidate: penalize more when many bins are open
        score += ob * 4.0 + 10.0;
        // but if the current item is huge and next item won't fit anywhere
        // typical, still allow occasional new bin when fit is hopeless
        if post_residual > 0 && post_residual <= 10 {
            score -= 15.0; // near-perfect fill of a fresh bin is fine
        }
    } else {
        // placing into an existing bin reduces pressure when bins are many
        score -= ob.min(20.0) * 0.6;
    }

    // --- Mean-residual coupling ---
    // If mean residual across open bins is high, we have slack; prefer bins
    // whose post_residual stays close to (above) the mean so we don't create
    // outliers of tiny useless gaps.
    if bin_residual < bin_capacity {
        let dev = (pr - mean_residual).abs();
        score += dev * 0.15;
    }

    // --- Lookahead: prefer bins whose leftover can still host next item ---
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 12.0; // leftover remains useful
        } else if post_residual > 0 {
            score += (next_item_size as f64 - pr).max(0.0) * 0.25;
        }
    }

    // --- Stream progression: early on, be more conservative with new bins ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // If the next item can also fit here, reward it proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 20.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space for the lookahead item: penalize unusable leftovers,
        // worse when the leftover is tiny (wasted) or large.
        let dead = post_residual as f64;
        score += 8.0 + 0.15 * dead;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving residual far below the mean residual (fragmenting).
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // Slight preference against opening a new bin when decent options exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        // But if no open bin fits well (post_residual large waste elsewhere),
        // new bin becomes relatively attractive for big items.
        if item_size > 70 {
            score -= 20.0;
        }
    }

    // Late-stream consolidation: prefer tighter fills as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual as fraction of capacity, superlinear penalty
    let post_frac = post_residual as f64 / cap;
    score += 40.0 * post_frac * post_frac;

    // Penalize placing small items into large-residual bins (waste of good space)
    let item_frac = item_size as f64 / cap;
    let resid_frac = bin_residual as f64 / cap;
    score += 25.0 * item_frac * (resid_frac - item_frac).max(0.0);

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 * (next_item_size as f64 / post_residual as f64);
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        // next item would need another bin anyway; slight penalty if we leave awkward gap
        score += 8.0 * post_frac;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Global pressure: many open bins relative to progress -> prefer filling existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 0 {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score -= 20.0 * pressure * (1.0 - post_frac);
    }

    // Compare against mean residual: bins with residual far below mean are precious, avoid them
    let dev = resid_frac - mean_residual / cap;
    score += 10.0 * dev;

    // New-bin candidate logic: opening a new bin is attractive early or when fit is poor
    if bin_residual == bin_capacity {
        // base score is cap (100); adjust so new bins compete with bad fits only
        let bad_fit = post_frac; // == 1 - item_frac
        let open_bonus = -15.0 * (1.0 - progress) - 30.0 * bad_fit;
        score += open_bonus;
        // if item is large, a fresh bin is often best (perfect pairing potential)
        if item_frac > 0.5 { score -= 20.0; }
    }

    // Small dead-space reward: exact or near-exact fills
    if post_residual == 0 { score -= 50.0; }
    else if post_residual < 10 { score -= 25.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early (t small): tolerate larger residuals slightly (bins stay flexible).
    // Late (t large): strongly prefer tight fits (small post_residual).
    let mut score = pr * (1.0 + 2.0 * t * t);

    // Smooth non-linear penalty for dead space: cubic in normalized residual,
    // scaled by progress so waste matters more as the stream advances.
    score += 40.0 * norm_pr * norm_pr * norm_pr * (0.5 + t);

    // Reward exact/near-exact fills with a smooth saturating term.
    score -= 25.0 * (1.0 - (-norm_pr * 12.0).exp());

    // Penalize bins whose residual deviates below the mean (fragmentation risk),
    // coupled smoothly with progress.
    let dev = (mean_residual - pr) / cap;
    score += 8.0 * dev * dev * (0.3 + t);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (smooth exponential reward).
    if fitting_bins_count <= 1 {
        score -= 30.0 * (1.0 - t * 0.5);
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 12.0 * fits_next * (0.5 + t);
        // Smooth penalty if post_residual is just barely below next item (dead space).
        let gap = (next_item_size as f64 - pr) / cap;
        if gap > 0.0 {
            score += 15.0 * gap * gap * t;
        }
    }

    // New-bin candidate: empty bin has post_residual == capacity. Penalize it
    // smoothly unless residuals across open bins are very tight (little room left).
    let is_new = (bin_residual == bin_capacity) as f64;
    let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
    score += is_new * (20.0 + 60.0 * (1.0 - tightness)) * (0.4 + 0.6 * t);

    // Mild penalty for proliferating open bins, decaying as stream ends.
    score += open_bins_count as f64 * 0.05 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for small post_residual (tight fit), non-linear.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / cap;

    // Harmonic class of the post-residual: residues divisible into large
    // chunks (e.g. multiples of 25 or 50) remain reusable for big items.
    let pr_u = post_residual;
    if pr_u == 0 {
        score -= 40.0; // perfect fit is ideal
    } else {
        let usable = if pr_u >= 50 { 2 } else if pr_u >= 25 { 1 } else { 0 };
        score -= 6.0 * usable as f64;
        // Penalize dead space that no item (min size 1..10 typical) can use
        if pr_u < 10 {
            score += 12.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
        } else {
            // next item won't fit here; slight penalty for stranding capacity
            score += 2.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with number of open bins.
        score = cap * 0.9 + open_bins_count as f64;
        // If nothing fits well (many fitting bins means good alternatives exist),
        // opening is fine when current bin would leave large awkward residual.
        if fitting_bins_count == 0 && post_residual < cap * 0.5 {
            score -= cap * 0.5;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large items in fresh bins
        }
    }

    // Mild preference for filling more-emptied bins first (best-fit flavor)
    score += (bin_residual as f64) * 0.05;

    // Progress-based tie-break: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (mean_residual - pr).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
