pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Dead-space penalty: quadratic in leftover.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 150.0 / (1.0 + gap);
        } else {
            // Next item cannot fit here; leftover is likely dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.8;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 50.0;
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin should only win when current fits are poor.
    if bin_residual == bin_capacity {
        score += 250.0;
        // Late in the stream, opening new bins is less costly than hoarding.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 200.0 * progress;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 60 {
            score -= 80.0;
        }
