pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize dead space: post_residual too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.3;
    }

    // Exact or near-exact fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Penalize leaving a gap that just barely fails the next item.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score += gap * 0.6;
            }
        }
    }

    // New-bin candidate logic: opening a new bin is only attractive when the item
    // is large and current bins are relatively full (high mean utilization pressure).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let pressure = mean_residual / (bin_capacity as f64);
        // High pressure (low mean residual) => new bin less attractive.
        score += 12.0 + 25.0 * (1.0 - pressure);
        // Late in the stream, discourage proliferation of bins.
        score += 10.0 * progress;
        // If many bins are already open, discourage another one.
        score += (open_bins_count as f64).ln().max(0.0) * 4.0;
        // Exception: large items with no good fit anywhere deserve a fresh bin.
        if item_size >= 60 && fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild global coupling: prefer bins below mean residual (balancing waste).
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score += 0.15 * (residual_f - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - residual_f);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer tight fits (small post_residual), smoothed quadratically.
    let mut score = pr * pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, waste matters more; early, flexibility matters.
    let tightness = 1.0 - pr / cap;
    score -= 40.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize very small residuals that become dead space, weighted by progress.
    let dead = if pr < it { pr / it.max(1.0) } else { 0.0 };
    score += 25.0 * dead * (0.5 + 0.5 * progress);

    // Interaction: post_residual vs mean residual — avoid making bin much tighter than average.
    score += 0.15 * (pr - mean_residual).abs() * (1.0 + progress);

    // Lookahead: reward bins whose post-residual can still fit the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 12.0 * (1.0 - (pr - nx) / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (1.0 - pr / nx.max(1.0)) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Many open bins: mild pressure to consolidate into existing bins.
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    // New-bin candidate: penalize unless the item is large relative to capacity
    // and no good fit exists (post_residual would be small in a fresh bin anyway).
    if bin_residual == bin_capacity {
        let fill = it / cap;
        score += 20.0 * (1.0 - fill) * (1.0 - progress) + 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit class: harmonic reward when post_residual lands on useful residue classes.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual modulo small divisors: residues that
        // commonly admit future items (multiples of 5, 10) are valuable.
        let pr = post_residual as f64;
        if post_residual % 10 == 0 {
            score -= 12.0;
        } else if post_residual % 5 == 0 {
            score -= 6.0;
        } else {
            // penalize awkward residues proportionally
            score += (post_residual % 5) as f64 * 1.5;
        }

        // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 500.0;
            } else if next_item_size <= post_residual {
                // reward proportionally to tightness of the lookahead fit
                let tight = (post_residual - next_item_size) as f64;
                score -= 20.0 * (1.0 - tight / bin_capacity as f64);
            } else {
                // next item cannot fit here: penalize dead space mildly
                score += 5.0;
            }
        }

        // Last-chance bin: if this is the only bin that fits, strongly prefer using it
        // over opening a new bin (unless the fit is terrible).
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // New-bin candidate handling: an empty bin gets a base penalty so we prefer
        // existing bins with decent fits; relax it late in the stream.
        if bin_residual == bin_capacity {
            score += 25.0;
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= 10.0 * progress;
            // but if the item is large relative to capacity and fits badly elsewhere,
            // opening fresh is attractive
            if item_size * 2 >= bin_capacity {
                score -= 15.0;
            }
        }

        // Prefer bins whose residual is below mean (tighter bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }

        // Integer-division threshold: post_residual <= capacity/10 is nearly dead space.
        if post_residual <= bin_capacity / 10 {
            score += 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones,
    // but a fresh bin candidate gets a penalty proportional to bin count.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 0.5 * open_bins_count as f64;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size as f64 > post_residual as f64 && post_residual > 0 {
        score += 8.0;
    }

    // Deviation from mean residual: prefer bins whose residual differs
    // favorably (tight bins get priority when mean is loose).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits with small leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= 25.0 - (leftover as f64).min(25.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here: penalize proportional shortfall (dead space risk).
        let shortfall = next_item_size - post_residual;
        score += (shortfall as f64) * 0.35;
    }

    // Penalize post_residual relative to mean residual (avoid creating outliers of dead space).
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual <= bin_capacity {
        score -= 18.0;
    }

    // Small post residuals are good (tight packing); non-linear reward.
    score -= (1.0 - (post_residual as f64 / bin_capacity as f64).powi(2)) * 8.0;

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for having many open bins already (encourage consolidation).
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) especially when they nearly fill the bin.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        // Mild penalty for awkward mid-range residuals, scaled by progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item cannot follow here; penalize proportionally to wasted capacity.
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin over opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // Discourage opening new bins when many bins are already open and mean residual is large.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin.
        score = 55.0;
        // Opening is more attractive early in the stream (more future to amortize).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // Attractive if open bins are crowded on average.
        score -= 0.25 * mean_residual;
        // Unattractive if the current item leaves a very tight fit elsewhere.
        if post_residual == 0 { score += 0.0; }
    } else {
        // Prefer bins below mean residual (consolidating space).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 3.0;
        }
        // Slight preference for bins that are relatively full already.
        score -= 0.15 * (bin_capacity - bin_residual) as f64;
    }

    // Global pressure: when many open bins exist, favor filling existing ones harder.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: quadratic in post-residual (dead-space penalty grows super-linearly)
    let mut score = pr * pr_norm * 2.0 + pr * 0.5;

    // Smooth non-linear coupling of post-residual with stream progress:
    // later in the stream, tight fills matter more; early, waste is cheaper.
    let prog_coupling = (1.0 + progress * progress) * (1.0 - pr_norm).powi(2);
    score -= 8.0 * prog_coupling * pr_norm;

    // Reward near-perfect fits via smooth bell-like term
    let tightness = 1.0 - (pr_norm - 0.05).abs() * 10.0;
    let bell = (-tightness * tightness).exp();
    score -= 6.0 * bell;

    // Last-chance bin: strongly favor using it (smoothly scaled by progress)
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + 0.5 * progress);
    }

    // If next item fits in the post-residual, reward leaving room for it
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let nxt = next_item_size as f64 / cap;
        score -= 5.0 * (1.0 - (pr_norm - nxt).abs() * 4.0).max(0.0);
    } else if next_item_size > 0 {
        // next item won't fit: penalize blocking future pairing
        score += 2.0 * (pr_norm / (1.0 + next_item_size as f64 / cap));
    }

    // Crowding effect: many open bins with large mean residual -> prefer filling existing bins
    let crowd = (open_bins_count as f64).ln() * (mean_residual / cap).max(0.0);
    score -= 3.0 * crowd * pr_norm;

    // New-bin candidate: penalize opening a bin unless current residuals are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0) * (1.0 - progress);
        score += 10.0 - 8.0 * fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space in [1,9] is nearly unusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else if pr <= 5 {
        score += 25.0; // tiny dead space: penalize hard
    } else if pr <= 9 {
        score += 12.0;
    } else if pr <= 19 {
        score += 4.0;
    } else if pr <= 29 {
        score -= 3.0;
    } else {
        // large residual keeps future options open
        score -= 8.0;
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly or leaves tiny residue
            let nr = pr - next_item_size;
            if nr == 0 {
                score -= 35.0;
            } else if nr <= 9 {
                score -= 18.0;
            } else {
                score -= 8.0;
            }
        } else {
            // next item cannot follow here; penalize proportionally
            score += (next_item_size - pr) as f64 * 0.25;
        }
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + (item_size as f64 / bin_capacity as f64) * 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to the residual gap of existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // prefer reusing open bins when mean residual is healthy
        score += 30.0 - mean_residual * 0.3 - progress * 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin can host the larger next item too
        }
    }

    // Harmonic modulo class on item size: awkward sizes (creating 1..9 gaps with
    // common capacities) get a mild placement penalty.
    let gap_class = (bin_capacity as i64 - item_size as i64) % 10;
    if gap_class > 0 && gap_class < 10 && item_size > bin_capacity / 2 {
        score += gap_class as f64 * 0.5;
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 9] are essentially unusable
    // for items >= 10, so penalize them heavily (non-linearly).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving a gap that the lookahead item could exactly fill.
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 25.0 - slack * 2.0;
        }
    }
    // Penalize leaving a gap that is too small for the next item (dead space trap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing
    // bins; make the fresh-bin candidate less attractive.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 3.0 + mean_residual * 0.5;
    } else {
        score -= open_bins_count as f64 * 0.3;
    }

    // Mild progression term: late in the stream, tighten packing (favor tight fits).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - post_residual) as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post_residual, but strongly reward perfect or near-perfect fits.
    let tight_fit_bonus = if post_residual == 0 {
        50.0
    } else if post_residual <= 5 {
        30.0
    } else if post_residual <= 15 {
        12.0
    } else {
        0.0
    };
    score -= tight_fit_bonus;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Exact chain: this bin will be perfectly filled by the next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here afterwards; reward proportionally to tightness of chain.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin; penalize dead space relative to next item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious; using them is good.
    let dev = mean_residual - bin_residual as f64;
    score += 0.25 * dev;

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current item is large
    // relative to capacity and no tight option exists.
    if bin_residual == bin_capacity {
        score += 55.0;
        if item_size >= 70 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Late in the stream, consolidate aggressively: prefer fullest bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 0.3 * (bin_capacity as f64 - bin_residual as f64);

    // Mild penalty for spreading across many open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero gets strong bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // small slivers are fine
    }
    if post_residual >= 10 && post_residual < item_size.min(20) {
        score += 8.0; // awkward mid-range residual
    }

    // Lookahead: if the next item fits into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
            // extra reward if next item fills the bin almost exactly after placement
            let chain_post = post_residual - next_item_size;
            if chain_post < 10 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += 0.2 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: prefer filling any bin as fully as possible
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: keep it competitive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 12.0; // base cost of opening a new bin
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else if fit_ratio < 0.5 {
            // existing bins fit poorly; new bin attractive
            score -= 18.0;
        }
        // late in the stream, avoid opening bins with big remaining capacity
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Global state coupling: when mean residual is high, prefer consuming bins
    // with large residuals; when mean residual is low, prefer tight fits even more.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Many open bins: encourage consolidation by rewarding placement into bins
    // (implicitly, since new-bin branch already penalized).
    if open_bins_count > 8 {
        score += 3.0;
        if bin_residual == bin_capacity {
            score += 10.0;
        }
    }

    // Time horizon: early in stream, be slightly exploratory toward new bins;
    // late in stream, squeeze everything into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * (1.0 - progress) * fit_ratio;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear tight-fit reward: strongly prefer small post-residuals
    let tight = 1.0 - (pr / cap);
    score -= 40.0 * tight * tight * tight;

    // Penalize dead space relative to mean residual of open bins
    score += 0.5 * (pr - mean_residual).abs();

    // Lookahead: reward if next item fits into post-residual (chaining)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 25.0 * (nxt / cap) * (1.0 - progress);
        } else {
            // penalize leaving a gap that wastes space relative to next item
            score += 10.0 * ((pr - nxt).abs() / cap) * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: mildly penalize opening new bins early, more later
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64).sqrt();
    }

    // Late-stream: encourage filling existing bins tighter
    score += 15.0 * progress * (pr / cap);

    // Slight preference to spread load when many bins open
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4; // 25 for C=100
    let class = post_residual % quarter;
    // Residuals just above a harmonic class boundary are "dead space" prone
    if class > 0 && class <= 10 {
        score += (11.0 - class as f64) * 1.5;
    } else {
        score -= class as f64 * 0.3;
    }

    // Exact-fill bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: does next item fit into post_residual? Reward potential chaining
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 + (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // leftover unusable for the known next item
            score += (post_residual as f64) * 0.25;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so new bins are chosen only for poor fits / tiny residuals
        let mut new_score = 45.0 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            new_score -= 15.0; // fresh bin can host a perfect pair with lookahead
        }
        if post_residual < quarter {
            new_score += 10.0; // fresh bin would still leave a sliver after pairing? unlikely; mild
        }
        if progress > 0.8 {
            new_score += 8.0; // late stream: prefer filling existing bins
        }
        // If item leaves a large residual in every bin (big item), new bin neutral
        if item_size > bin_capacity * 3 / 4 {
            new_score -= 20.0;
        }
        score = new_score;
    } else {
        // Tightness reward: prefer bins whose residual is closest to item size
        let tightness = (bin_residual - item_size) as f64;
        score -= (bin_capacity as f64 - tightness) * 0.1;
        // Prefer bins below mean residual (filling emptier-but-usable bins)
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward fits that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead won't fit in the leftover gap: penalize proportionally.
        score += 0.3 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.6 * (0.5 + progress);

    // Relative tightness: prefer bins where the item consumes a large share.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Prefer bins with residuals close to the item (best-fit flavor).
    score += 0.4 * (bin_residual as f64 - item_size as f64);

    // New-bin candidate: choose it only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && mean_residual >= item_size as f64 * 1.05;
        if decent_fit_exists {
            score += 30.0 + mean_residual * 0.2;
        } else {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // next item cannot follow here; penalize leaving awkward residue
        score += 15.0 + (post_residual as f64) * 0.2;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(1.0);
        score += 40.0 * openness + 0.5 * (post_residual as f64);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 50.0;
        }
        if fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    // Late-stream consolidation: tighten packing as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual penalty by how full the bin already is.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * (bin_capacity as f64) * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // or when many bins are open (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 12.0 * (1.0 - progress) + (open_bins_count as f64).ln().max(0.0) * 4.0;
    } else {
        // Lookahead synergy: if next item fits exactly in post_residual, big reward.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 20.0;
            } else if post_residual >= next_item_size {
                score -= 6.0;
            } else {
                // Next item won't fit here: penalize dead space left behind.
                score += (next_item_size - post_residual) as f64 * 0.25;
            }
        }

        // Penalize bins whose residual is far from the mean residual (fragmentation).
        score += (post_residual as f64 - mean_residual).abs() * 0.15;

        // Small residual bonus: nearly-closed bins are valuable to finish off.
        if post_residual < 10 {
            score -= 10.0;
        }
    }

    // Mild penalty when few fitting bins remain (competition among candidates).
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fit_ratio = pr / cap;

    // Base: post residual (waste), scaled non-linearly
    let mut score = pr;

    // Non-linear polynomial coupling: small residuals are fine (tight fit),
    // medium residuals are dead space; penalize quadratically.
    let dead = fit_ratio * (1.0 - fit_ratio);
    score += 18.0 * dead * (0.5 + progress);

    // Reward tight fits (small post_residual) increasingly late in the stream
    score -= 30.0 * (1.0 - fit_ratio).powi(3) * (0.3 + 0.7 * progress);

    // Lookahead coupling: bonus if next item fits in post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (next_item_size as f64) / cap) * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        score += 4.0 * ((next_item_size as f64) - pr) / cap;
    }

    // Last chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Prefer bins with residual below mean (consolidating fuller bins)
    score += 0.35 * (pr - mean_residual);

    // Penalize spreading across many open bins early; encourage it late
    score += 0.6 * (open_bins_count as f64) * (1.0 - progress) * fit_ratio;

    // New empty bin: mild penalty unless residual space is hopeless
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
        if pr as u32 == 0 {
            score -= 100.0;
        }
        if item_size as f64 > 0.6 * cap {
            score -= 5.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: quarter bands of capacity
    let quarter = (bin_capacity / 4).max(1) as f64;
    let post_f = post_residual as f64;

    // Dead-space penalty: leftover in the awkward middle band (just above half)
    if post_residual > bin_capacity / 2 && post_residual <= (3 * bin_capacity) / 4 {
        score += 12.0;
    }
    // Perfect or near-perfect fits are rewarded
    if post_residual <= bin_capacity / 10 {
        score -= 15.0 + post_f * 0.5;
    }

    // Modulo-10 harmonic class: leftovers divisible by 10 pair well with
    // typical item sizes; odd leftovers tend to become dead space.
    if post_residual % 10 != 0 {
        score += 3.0;
    }
    if post_residual % 20 == 0 {
        score -= 4.0;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item's class complements the leftover
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - slack * 0.15;
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 5.0; // exact harmonic subdivision
            }
        } else {
            // Next item cannot follow here; leftover risks being stranded
            score += 6.0 + (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: neutral baseline, slightly above good fits,
    // but attractive when open bins are very fragmented.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + open_bins_count as f64 * 0.3 + mean_residual * 0.4;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 8.0; // big next item: keep capacity fresh
        }
        if fitting_bins_count == 1 {
            score += 25.0; // avoid abandoning the last usable bin
        }
    }

    // Progress modulation: tighten packing as the stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    // Nudge toward bins below mean residual (consolidate fullness)
    score += (mean_residual - bin_residual as f64) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly worthless.
    let min_item = 1u32; // items can be as small as 1, but treat small gaps harshly anyway
    let dead_threshold = 12u32; // gaps below this rarely absorb future items usefully
    if post_residual < dead_threshold {
        // quadratic dead-space penalty
        score += (dead_threshold - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (waste-aware): waste ratio penalty
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * waste_ratio * 30.0;

    // Perfect / near-perfect fit gets a strong discount
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 3 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // have poor residuals or there is open-bin pressure.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, modulated by stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 20.0 * progress;
        // if open bins are already crowded, new bin is more acceptable
        score -= open_bins_count as f64 * 0.8;
        // if mean residual across open bins is small, new bin looks better
        score -= (mean_residual / bin_capacity as f64) * 30.0;
    } else {
        // Favor bins whose residual is close to the item (best-fit core)
        score -= (bin_residual - item_size) as f64 * 0.1;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement (chains well).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 15.0;
        } else {
            score -= 5.0 * (1.0 - slack / post_residual as f64);
        }
    }

    // Open-bin pressure: mildly discourage scattering across many bins
    score += open_bins_count as f64 * 0.3;

    // Prefer bins below mean residual (consolidate emptier space usage)
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: item + next item exactly fills the bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Residual after next item: prefer small leftover but avoid tiny slivers
            let after_next = post_residual - next_item_size;
            score -= 25.0;
            if after_next < 10 {
                score += (10 - after_next) as f64 * 1.5;
            }
        } else {
            // Next item won't fit here: dead space relative to lookahead
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Penalize tiny unusable residuals
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean (better packing); avoid wasteful bins
    score += (mean_residual - post_residual as f64) * 0.3;

    // Late in the stream, prefer closing bins out (favor high fill)
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    // Many open bins: reward consolidation into existing bins
    if open_bins_count > 4 {
        score -= 2.0;
    }

    // Make new-bin candidate (empty) less attractive unless current fit is bad
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; mildly penalize wasting large residual.
            score += 5.0 * (post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).max(1.0);
        let poor_fits = (mean_residual - item_size as f64).max(0.0);
        score += 20.0 - 8.0 * poor_fits / cap - 4.0 / scarcity;
        // Late in stream, prefer packing into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer filling bins with larger residuals when many bins are open.
    if open_bins_count > 3 {
        score += 0.05 * (mean_residual - post_residual as f64).abs();
    }

    // Slight preference for bins whose residual is close to item size.
    let gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 6.0 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear coupling: post-residual weighted by stream progress
    score += 6.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (low post_residual) more strongly as stream advances
    score -= 4.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;

    // Penalize residuals too small for the lookahead item (dead space)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 3.0 * (nx - pr) / cap * (1.0 + progress);
        } else {
            // Reward leaving room for the next item, smoothly
            score -= 1.5 * (1.0 - (pr - nx) / cap) * progress;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0 * (1.0 - norm_item);
    }

    // Mild penalty when this bin's residual deviates from mean residual
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // Prefer filling already-open bins when many are open
    score += 0.3 * (open_bins_count as f64).ln() * norm_pr;

    // Smooth interaction: item size vs post residual
    score += 2.0 * norm_item * norm_pr * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes group residual space
    // into "usable bands". Residuals that are multiples of 10 are highly reusable
    // since items are integers 1..100; small odd residuals are near-dead space.
    let post_class = post_residual % 10;
    match post_class {
        0 => score -= 12.0,                       // perfectly reusable band
        1 | 2 | 3 => score += 8.0,                // near-dead sliver
        4 | 5 | 6 => score += 3.0,                // marginal band
        _ => {}                                   // 7..9: mildly awkward
    }

    // Integer-division thresholds on post_residual: which harmonic size classes
    // (10-wide buckets) can still be served by the leftover?
    let usable_buckets = (post_residual / 10) as f64;
    score -= 2.5 * usable_buckets;

    // Lookahead: reward if the next item fits exactly into the post residual
    // (perfect chaining), penalize if it cannot fit at all.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * fit_ratio;            // tighter chain = better
        } else {
            score += 6.0;                         // next item stranded elsewhere
        }
        // Harmonic class of next item vs post residual bucket
        if post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 8.0;                          // chain leaves aligned residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when open bins are very full
    // or this bin would leave an awkward residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - (mean_residual / bin_capacity as f64);
        let pressure = avg_fill * (open_bins_count as f64).sqrt();
        score = 100.0 - 30.0 * pressure - 10.0 * progress;
        // If item is large, a fresh bin wastes little; small items should reuse.
        score += (item_size as f64) * 0.15;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;                          // new bin can also chain next item
        }
    }

    // Penalize wasting a large residual on a small item unless it's the last chance.
    let waste = post_residual as f64 - if next_item_size > 0 { (bin_residual - post_residual) as f64 } else { 0.0 };
    if post_residual > 40 && item_size < 30 && fitting_bins_count > 1 {
        score += 5.0;
    }
    let _ = waste;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // Anything below the minimum item size (1..100 range, use conservative 10)
    // is likely dead space; the smaller the gap, the harsher the penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Gaps too small for the next item are also dead weight.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size as f64 {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation into
    // existing bins; opening new bins is penalized via the empty-bin call
    // naturally scoring high residual, but add pressure when bins are many.
    let pressure = open_bins_count as f64 / 8.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Early in the stream, be slightly more willing to spread out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near match: next item fits with small leftover.
    if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 120.0 * (1.0 - slack / cap);
    }
    // Next item does NOT fit: penalize proportionally to wasted residual.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 40.0 * (post_residual as f64 / cap);
    }

    // Favor bins with residuals below the mean (tighter bins absorb items first).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when open bins are quite full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fullness = 1.0 - mean_residual / cap;
        score = cap + 100.0 - 80.0 * avg_fullness - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 30.0; // new bin always fits next item comfortably
        }
    }

    // Slight preference for keeping many open bins consolidated.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
