pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial coupling to stream progress.
    // Early on, prefer tight fits (minimize post_residual); later, tolerate larger
    // residuals to keep bins flexible for future items.
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Non-linear penalty on tiny residuals (dead space), smoothed polynomial:
    let tiny = (1.0 - norm_pr).powi(8); // peaks when post_residual ~ cap (i.e., empty-ish? no: norm_pr near 1 means big residual)
    // Penalize very small post_residual only mildly when it perfectly closes a bin
    if pr == 0.0 {
        score -= 25.0; // perfect closure is excellent
    } else {
        // smooth penalty for small-but-nonzero dead space, coupled with progress
        let small = (1.0 - norm_pr).powi(3);
        score += 8.0 * small * (1.0 - progress);
    }

    // Reward fitting into a bin when few bins can fit (last-chance bonus)
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth polynomial match)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - (gap / cap).min(1.0)).powi(2);
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual - pr).abs() / cap;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the residual after placement: which capacity fraction band
    // the leftover space falls into. Small leftovers = tight fit = reward.
    let frac = post_residual as f64 / cap;
    let class = (frac * 10.0).floor(); // 0..10 harmonic band

    // Reward tight fits (low post_residual classes) with a strong subtraction.
    let class_bonus = match class as u32 {
        0 => 40.0,                 // near-perfect fit
        1 => 25.0,
        2 => 15.0,
        3 => 6.0,
        4 => 0.0,
        5 => -4.0,                 // half-empty: mildly penalize
        6 => -8.0,
        7 => -12.0,
        8 => -16.0,
        9 => -20.0,
        _ => -24.0,                // nearly empty bin used wastefully
    };
    score -= class_bonus;

    // Modulo-arithmetic coupling: does the leftover residual pair well with the
    // lookahead item? If next item fits exactly or snugly into post_residual,
    // this placement chains nicely.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        // exact chain (slack 0) is golden; small slack also good
        let chain_reward = if slack == 0 {
            30.0
        } else if slack <= 5 {
            18.0
        } else if slack <= 15 {
            8.0
        } else {
            0.0
        };
        score -= chain_reward;
    } else if next_item_size > post_residual && post_residual > 0 {
        // leftover cannot host the next item: dead space unless tiny
        if post_residual < 10 {
            score -= 5.0; // negligible dead space
        } else {
            score += (post_residual as f64).sqrt() * 1.5; // unusable chunk penalty
        }
    }

    // Integer-division threshold on post_residual: classify leftover by /10 bucket
    // and give a harmonic staircase reward for lower buckets.
    let bucket = post_residual / 10;
    score -= match bucket {
        0 => 12.0,
        1 => 8.0,
        2 => 4.0,
        _ => 0.0,
    };

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // bins give poor fits. Penalize the empty bin moderately so tight fits
    // still win, but allow it when all alternatives are loose.
    if bin_residual == bin_capacity {
        score += 18.0;
        // late in the stream, prefer consolidating into open bins even more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mean-residual coupling: if this bin is much emptier than average, using it
    // balances residuals; if much fuller than average, it's a good tight target.
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }

    // Perfect fit: heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Reward tight fits proportionally.
        let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= 40.0 * tightness * tightness;

        // Penalize gaps that cannot fit the lookahead item (k=2 lookahead).
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0;
        }
        // Bonus if the residual can exactly host the next item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // and encourage consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 20.0 + 15.0 * pressure;
        // But if no existing bin fits well (large post_residual elsewhere),
        // a fresh bin is fine: reduce penalty via mean residual comparison.
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward slightly when bin pressure is high.
        score -= 3.0 * pressure;
        // Prefer bins with below-average residual (keeps some bins tight,
        // others free for large future items).
        if (bin_residual as f64) > mean_residual {
            score += 8.0;
        } else {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly favored
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits: reward proportional to tightness of the chain
            let chain_tightness = (next_item_size + item_size) as f64 / bin_capacity as f64;
            score -= 50.0 + 100.0 * chain_tightness;
            // Extra reward for exact 2-item fill
            if next_item_size == post_residual {
                score -= 500.0;
            }
        } else {
            // Next item won't fit here: penalize leaving dead space that is
            // small enough to be unusable (worse than a large residual)
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 40.0 + (next_item_size as f64 - dead) * 2.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are tight
    if bin_residual == bin_capacity {
        score += 30.0;
        // If mean residual across open bins is small, opening new bin is wasteful
        if mean_residual < item_size as f64 * 0.5 {
            score += 200.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 50.0 * progress;
        // If next item is large, a fresh bin is more attractive
        if next_item_size > item_size {
            score -= 60.0;
        }
    }

    // Prefer bins whose residual is already below average (tighter bins first)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strong bonus when post_residual is small.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space relative to item size (wasted capacity).
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / (item_size.max(1) as f64);
        score += 4.0 * waste_ratio.min(3.0);
    }

    // Lookahead (k=2): if the next item fits exactly or well in post_residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chaining
        } else if next_item_size < post_residual {
            let chain_fit = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 8.0 * chain_fit;
        } else {
            // Next item won't fit here; mildly penalize leaving a large unusable gap.
            let gap = next_item_size - post_residual;
            if gap <= item_size {
                score += 2.0;
            } else {
                score += 4.0 * (gap as f64 / 100.0);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bin fit is poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early on, opening bins is fine; later, prefer consolidating.
        score += 10.0 + 10.0 * progress;
        // If many open bins already, discourage another new bin.
        score += 1.5 * open_bins_count as f64;
        // If mean residual is high, existing bins have room — discourage new bin.
        score += 0.3 * mean_residual;
        // If next item is large, a fresh bin may be valuable.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    } else {
        // Fitting into an existing bin: small bonus scaled by how full the bin already is.
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 5.0 * fill;
    }

    // Mild global pressure: when few bins fit the item, prefer any fitting existing bin.
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Time-horizon coupling: late in the stream, tighten up — avoid spreading across bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, waste matters less; late, tight packing dominates.
    let w = 0.5 + 1.5 * progress * progress;
    score += w * (post / cap) * post * 0.02;

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio * (0.5 + progress);

    // Penalize creating residual that no plausible next item can use.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score += 0.15 * gap * gap / cap;
        // Bonus if next item fits exactly into the post residual.
        if (next_item_size as f64 - post).abs() < 1.0 {
            score -= 8.0;
        }
    } else if post > 0.0 {
        // Last item: any residual is pure waste.
        score += post * 0.5;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0 + 8.0 * progress;
    }

    // New empty bin candidate: neutral baseline, mildly penalized so open bins
    // with decent fits win; only wins when all fits are terrible.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * open_bins_count as f64;
        score += 0.05 * mean_residual;
    } else {
        // Prefer bins whose residual deviates favorably from the mean.
        let dev = bin_residual as f64 - mean_residual;
        score -= 0.1 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common
    // item sizes (10, 20, 25, 50) are "reusable" classes; odd/prime-like
    // residues are dead space. Reward reusable classes.
    let reusable = |r: u32| -> f64 {
        let mut bonus = 0.0;
        for &m in &[10u32, 20, 25, 50, 100] {
            if r % m == 0 {
                bonus += (m as f64) * 0.35;
            }
        }
        bonus
    };

    score -= reusable(post_residual);

    // Penalize tiny non-zero dead space strongly (harmonic penalty on residue).
    if post_residual > 0 {
        score += 60.0 / (post_residual as f64).powf(0.75);
    } else {
        score -= 120.0; // perfect fit
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward when post-residual sits in the same harmonic class as next item
            if post_residual % next_item_size == 0 {
                score -= 45.0;
            } else {
                score -= 18.0;
            }
        } else {
            // Next item won't fit: penalize proportionally to wasted lookahead
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when open bins are nearly exhausted / fragmented.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Early in stream or few bins: opening fresh bins is fine.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 40.0 + 60.0 * pressure - 30.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild penalty for spreading across many open bins when mean residual is high.
    if open_bins_count > 3 {
        score += (open_bins_count as f64).ln() * 3.0 * (1.0 - mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10.0 - post_residual as f64) * 5.0;
    }

    // Reward tight fits: residual close to item size
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (1.0 - tightness) * 15.0;

    // Penalize large post_residual that likely becomes dead space
    if post_residual >= 10 {
        score += post_residual as f64 * 0.3;
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open bins pressure: discourage new bins when many are open
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 3.0;
        // But allow new bin if item is large and no good fit exists
        if item_size > 50 && fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Lookahead: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size <= 10 && post_residual < next_item_size {
        score += 15.0; // next item won't fit here; wasted gap
    }

    // Mean residual coupling: prefer bins below mean residual (fill emptier ones first)
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // 2-step lookahead: reward if next item fits in post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 80.0 + next_item_size as f64;
        } else {
            // dead space penalty scaled by how badly next item misses
            let miss = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score += miss * 1.5;
        }
        // chain fit: next item exactly fills post_residual
        if post_residual == next_item_size {
            score -= 150.0;
        }
    }

    // Relative to mean residual: prefer bins that are tighter than average
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin early in the stream unless it's a great fit
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
    }

    // Progress-based tightening: late in stream, waste is more costly
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * (0.5 + 0.5 * progress);

    // Large residual bins get slight preference to consolidate
    score -= bin_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

