    // Lookahead: penalize if next item could have used this residual better
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size <= post_residual {
            // residual remains useful for next item: mild bonus
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // residual too small for next item: dead-space penalty
            score += post_residual as f64 * 0.2;
        }
    }

    // Compare against mean residual: prefer bins with residuals close to item size
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Many open bins: encourage consolidation (favor filling existing bins over new ones)
    let progress = step_index as f64 / (total_items.max(1) as f64);
