        score -= progress * 10.0;
    }

    // Large items: prefer bins with residual near item size
    if item_size >= bin_capacity / 2 {
        score -= (bin_residual - item_size) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: quadratic penalty on wasted space (post residual)
    let mut score = post * (1.0 + 1.5 * norm_post * norm_post);

    // Smooth stream-progress coupling: waste penalized more as stream advances
    score += 20.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post residual) with smooth exponential-style shaping
    score -= 15.0 * (-norm_post * 6.0).exp() * (1.0 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_post) * (1.0 - norm_post);
    }

    // Penalize bins that leave a residual just below the next item (smooth coupling)
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let gap_norm = gap / cap;
        score += 10.0 * gap_norm * gap_norm;
        // Reward leaving room exactly for the next item
        score -= 12.0 * (-(gap_norm * 8.0)).exp();
    }

    // Mild preference for bins below mean residual (consolidating emptier bins)
    score += 0.05 * (bin_residual as f64 - mean_residual) * (0.5 + progress);

    // New-bin candidate: penalize opening a bin unless current waste would be severe
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * progress - 8.0 * (1.0 - norm_post);
    }

    // Slight load-balancing: fewer open bins favored via smooth term
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: partition capacity into 8 classes.
    let class = post_residual / (bin_capacity / 8).max(1);
    let class_bonus: f64 = match class {
        0 => 0.0,                       // near-perfect fit
        1 => 2.0,                       // small waste, still fine
        2 => 5.0,
        3 => 9.0,
        4 => 14.0,
        5 => 20.0,
        6 => 27.0,
        _ => 35.0,                      // huge dead space class
    };
    score += class_bonus;

    // Modulo harmonic coupling: residuals that are multiples of 4/8 pair well
    // with typical item sizes drawn from coarse grids.
    if post_residual % 8 == 0 { score -= 4.0; }
    else if post_residual % 4 == 0 { score -= 2.0; }
    if post_residual % 3 == 0 { score -= 1.0; }

    // Lookahead: reward residuals that exactly or nearly fit the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0; // perfect chain
        } else if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - gap / cap).max(0.0);
        } else {
            // next item cannot fit here; penalize more the tighter we filled
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin is good.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: prefer reusing open bins by default.
        score += 18.0 + open_bins_count as f64;
        // But if this is a big item and residual capacity everywhere is low,
        // opening fresh space is better.
        let frac = item_size as f64 / cap;
        if frac > 0.6 && mean_residual < item_size as f64 * 1.2 {
            score -= 30.0;
        }
        // Early in the stream, having many open bins is costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.15 { score += 10.0; }
    } else {
        // Reward closing the gap toward mean residual (keep bins homogeneous).
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.5 * dev;
        // Favor tighter bins when many bins are open.
        score -= (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64 / cap);
    }

    // Exact fill is always excellent.
    if post_residual == 0 { score -= 25.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, the classic
    // smallest item size) are the worst outcome; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 3.0 * (10 - post_residual) as f64;
    }

    // Perfect fit is the ideal outcome: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual >= 10 {
        // Reward residual gaps that are likely reusable: closeness to a
        // "friendly" gap (>= next item, or large enough to be flexible).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0 + 0.3 * post_residual as f64;
        } else if next_item_size > 0 {
            // Residual too small for the next item: mild dead-space penalty.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Tight-fit reward: item fills a large fraction of the bin's residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Open-bin pressure: discourage scattering across many bins; prefer
    // filling existing bins as open_bins_count grows.
    score += 0.15 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, avoid forcing a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin is a fallback. It should win
    // only when no open bin offers a decent fit. Make the empty bin
    // moderately attractive (residual = capacity) but penalized by open-bin
    // pressure so tight fits in existing bins win.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Room for the lookahead item in a fresh bin: slight bonus.
            score -= 4.0;
        }
    }

    // Mean-residual coupling: when average residual is high, prefer bins
    // that reduce dispersion (place into bins far below the mean residual).
    score += 0.2 * (bin_residual as f64 - mean_residual).max(0.0);

    // Late-stream urgency: as the stream ends, waste matters less than
    // bin count; tighten preference for full bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0; // next item fits perfectly here
        } else if post_residual >= next_item_size {
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit; penalize more the closer we came to a near-waste
            score += 10.0 + 0.2 * gap;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let badness = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs()
        } else {
            0.0
        };
        score = bin_capacity as f64 + 5.0 + badness * 0.1;
        // Allow new bin late in stream or when open bins are already tight
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if post_residual as f64 > mean_residual + 30.0 && fitting_bins_count > 0 {
            score += 50.0;
        }
        let _ = progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: penalize large post_residual super-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Dead-space penalty: residuals too small for the smallest possible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 8.0;
        }
        // Perfect chaining: post residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate logic: an empty bin is only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fit_ratio < 0.5;
        if poor_fit && open_bins_count > 0 {
            score -= 30.0; // allow opening a fresh bin for a loose item
        } else {
            score += 50.0; // discourage spreading across many bins
        }
        // Late in the stream, consolidate more aggressively.
        score += 30.0 * progress;
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation.
    let spread = (mean_residual - bin_residual as f64).abs();
    score += 0.15 * spread;

    // Mild time-decay: earlier steps tolerate more exploration (new bins).
    score -= 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: post residual (waste), with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Reward tight fits: low post residual relative to item size
    score -= 30.0 * (1.0 - norm_pr).powi(3) * fit_norm;

    // Lookahead coupling: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let usable = if next_norm <= norm_pr { 1.0 } else { 0.0 };
        let smooth = (norm_pr - next_norm).clamp(0.0, 1.0);
        score += 15.0 * (1.0 - smooth) * norm_pr;
        score -= 10.0 * smooth * (1.0 - progress);
        let _ = usable;
    }

    // Stream progress: later in stream, prefer filling existing bins more aggressively
    score *= 1.0 + 0.4 * progress * (1.0 - norm_pr);

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening new bins unless residuals are large
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual / cap;
        score += 20.0 + 40.0 * (1.0 - avg_waste).powi(2);
        score -= 15.0 * progress * avg_waste;
    }

    // Penalize many open bins mildly to encourage consolidation
    score += 0.5 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    // Smooth interaction: residual vs mean residual
    score += 5.0 * (norm_pr - mean_residual / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into bands.
    let class = post_residual / 10; // 0..=10
    match class {
        0 => score -= 60.0,                 // near-perfect fit, tiny dead space
        1 => score -= 40.0,                 // excellent
        2 => score -= 25.0,                 // good
        3 => score -= 10.0,                 // moderate
        4 => score -= 0.0,
        5 => score += 5.0,                  // half-empty: risky dead space
        6 => score += 10.0,
        7 => score += 18.0,
        8 => score += 28.0,
        9 => score += 40.0,
        _ => score += 55.0,                 // large residual left behind
    }

    // Modulo harmony: does post_residual align with common item granules (10,20,25)?
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0; // divisible by 10: future items can tile it exactly
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead harmony: can next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chaining
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 { score -= 20.0; }
            if slack <= 10 { score -= 25.0; }
            score += slack as f64 * 0.3; // mild penalty for leftover after chain
        } else {
            // next item cannot use this residual: dead space likely
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bonus: only bin that fits the item -> strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 100.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 45.0; // default: prefer reusing open bins
        if fitting_bins_count <= 1 {
            score -= 30.0; // few alternatives -> new bin acceptable
        }
        if post_residual as f64 > 0.4 * bin_capacity as f64 && next_item_size > post_residual {
            score -= 15.0;
        }
    }

    // Progression pressure: late in stream, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0;

    // Prefer filling bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.4;

    // Many open bins -> favor reuse to avoid proliferation.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible future item are "dead space" -> heavy penalty.
    if post_residual > 0 {
        let dead = (post_residual < 10) || (next_item_size > 0 && post_residual < next_item_size);
        if dead {
            score += 40.0 + 0.6 * post_residual as f64;
        }
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward residuals that exactly accommodate the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    score += 0.15 * open_bins_count as f64;

    // Penalize bins whose residual is far from the mean residual (fragmentation).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    // Early in the stream, be more willing to open fresh bins (score new bin better);
    // late in the stream, squeeze existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 8.0;

    // New-bin candidate: empty bin has residual == capacity. Make it moderately
    // attractive only when the item is large relative to capacity or when no
    // existing bin fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score = 50.0 - 30.0 * large_item;
        if fitting_bins_count == 0 {
            score -= 45.0; // must open a new bin anyway
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // new bin can also host the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness;

    // Perfect fit bonus: post_residual zero is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits after this one: excellent chaining.
            score -= 15.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // Next item won't fit here: penalize wasted residual, scaled by how much it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.6 * miss.min(next_item_size as f64);
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    // Placing to leave residual far below mean reduces fragmentation.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when good existing options exist,
    // especially early/mid stream when bins can still be filled.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable when stream is late or many bins are open.
        score += 20.0 - 15.0 * progress - (open_bins_count as f64).min(10.0);
    } else if open_bins_count > 0 {
        score -= 3.0;
    }

    // Mild penalty for very large dead space that nothing (min size 1) can use later.
    if post_residual > 50 {
        score += 0.2 * (post_residual - 50) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Tight fit reward: quadratic bonus for small post_residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Lookahead: penalize residuals too small for the next item (dead space),
    // reward residuals that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 + 0.05 * next_item_size as f64;
        } else if post_residual > 0 {
            let waste_ratio = post_residual as f64 / bin_capacity as f64;
            score += 6.0 * waste_ratio;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps the fleet balanced); penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate: baseline penalty so it only wins when open fits are bad.
    if is_new_bin {
        score += 10.0 + 8.0 * (1.0 - progress);
        // If nothing else fits well, allow opening: post_residual already large.
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
    }

    // Early stream: be slightly more conservative with existing bins.
    score += 2.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64 / cap;

    let mut score = post;

    // Reward tight fits: quadratic coupling of fill ratio with progress.
    score -= (fit * fit) * cap * (0.6 + 0.4 * progress);

    // Penalize large dead space more strongly as the stream progresses.
    let dead = post / cap;
    score += dead * dead * cap * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly early, more when many open bins exist,
    // but allow opening when no open bin fits well (post_residual == cap case
    // already scores post = cap; add pressure so it's chosen only when fits are bad).
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        let mean_fit = mean_residual / cap;
        // New bin is attractive if mean residual of open bins is small (poor fits).
        score += 10.0 + 2.0 * openness - 25.0 * (1.0 - mean_fit) * (1.0 - mean_fit);
    } else {
        // Prefer bins whose residual matches the lookahead item (k=2 lookahead).
        if next_item_size > 0 && next_item_size <= post_residual {
            let look_fit = next_item_size as f64 / post.max(1.0);
            score -= 12.0 * look_fit * (1.0 - look_fit) * 4.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // Lookahead won't fit here: slight penalty for wasting future capacity.
            score += 5.0 * (next_item_size as f64 / cap);
        }
        // Slight preference for fuller bins among open bins.
        score += (mean_residual - post) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic classes on post_residual (integer division thresholds) ---
    // Class 0: post_residual == 0  -> perfect fit, reward heavily.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Class the residual into harmonic bands of capacity/10.
        let band = post_residual / (bin_capacity / 10).max(1); // 0..10
        // Smaller bands are better; penalize proportionally with a superlinear kick.
        score += band as f64 * 3.0;
        // Dead-space class: residual too small for ANY plausible item (min size 1,
        // but typical small items >= 10): treat residuals < 10 as near-wasted.
        if post_residual < 10 {
            score += 8.0; // wasted sliver, worse than a clean fit but bin is used anyway
        }
        // Harmonic modulo classes: residuals that are multiples of 5 pair well
        // with many item sizes drawn from modular grids.
        if post_residual % 5 == 0 {
            score -= 4.0;
        }
        if post_residual % 10 == 0 {
            score -= 4.0;
        }
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual can host the next item: reward the match.
            let slack = post_residual - next_item_size;
            score -= 12.0 + (slack as f64).min(20.0) * 0.3;
        } else {
            // Next item won't fit here; penalize by how close we came (near-miss dead space).
            let miss = next_item_size - post_residual;
            score += (miss as f64) * 0.5;
        }
        // Harmonic class of next item: large items (>= 50) favor tight fits now.
        if next_item_size >= 50 && post_residual > 0 && post_residual < 15 {
            score += 6.0; // keep big bins free for big items
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0; // strongly prefer using the only bin that fits
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost of +capacity worth of "fresh" space.
        // Only attractive when existing bins fit poorly (mean residual low utility)
        // or few bins fit the item.
        score += 55.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Late in the stream, consolidation matters more: new bins cost more.
        score += progress * 20.0;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += (fitting_bins_count as f64) * 5.0;
        }
        // If mean residual across open bins comfortably exceeds item, use open bins.
        if mean_residual > item_size as f64 + 10.0 {
            score += 15.0;
        }
    }

    // --- Global state modulation ---
    // Many open bins: encourage filling existing ones tightly.
    score += (open_bins_count as f64) * 0.4;
    // Prefer bins whose residual is below the mean (use up the emptier-tail bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward closing the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are worthless; residuals below ~15 are near-dead.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 + (15 - post_residual) as f64 * 4.0;
    } else if post_residual >= 15 && post_residual < 30 {
        score += 12.0;
    }

    // Reward residuals that can still host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 10.0; // dead space relative to lookahead
        }
    }

    // Last-chance bin: strongly prefer filling the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Open-bin pressure: with many bins open, discourage opening new ones
    // and prefer packing into existing residual mass.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // New-bin candidate (empty bin): penalize so it's chosen only when
    // open bins offer genuinely bad fits (their dead-space penalties above
    // make them worse than this threshold).
    if bin_residual == bin_capacity {
        score += 90.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin likely useful for the next item too
        }
    }

    // Mild alignment bonus: residual close to mean residual keeps the
    // bin profile balanced.
    score -= (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 60.0; // next item can still be placed here
        } else {
            // dead space: penalize unusable leftover, worse when small leftover
            let dead = post_residual as f64;
            score += dead * dead / (bin_capacity as f64 * 0.25);
        }
    } else {
        // last item: only care about closing bins now
        score -= 100.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual is genuinely large.
    if bin_residual == bin_capacity {
        score += 120.0;
        // opening a new bin is fine if it will fit the next item too
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead: reward if next item fits the post-residual (chaining), penalize otherwise
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.25 * (post_residual as f64 - next_item_size as f64).min(20.0);
        } else {
            // dead space relative to next item
            score += 0.15 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64)).max(0.0);
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin if residuals of open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalize new bins early / when mean residual is still usable
        score += 30.0 + 40.0 * (1.0 - progress) - fragmentation.min(50.0) * 0.3;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer filling bins whose residual deviates strongly from mean (normalize spread)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Mild preference to use more-opened bins rather than proliferate
    score += 0.05 * open_bins_count as f64;

    // Time-horizon term: later in stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress);
    score += 40.0 * norm_pr * norm_pr * (1.0 - progress);
    score -= 60.0 * norm_pr * progress * progress;

    // Dead-space penalty: residuals too small to fit typical items
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (10.0 - pr) as f64 / 10.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 20.0 * (1.0 - gap / cap).max(0.0);
        if pr >= next_item_size as f64 {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Mild pressure toward consolidating into fewer bins
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual is near the mean (balanced packing)
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are gold
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward near-exact fits (post_residual in small harmonic bands)
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    } else {
        // penalize dead space that cannot hold the smallest plausible item (1..100)
        if post_residual < 10 {
            score += 5.0; // tiny sliver: mostly dead
        }
        // modulo classes: residuals divisible by common item sizes are reusable
        let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0);
        if reusable {
            score -= 10.0;
        } else {
            score += 6.0;
        }
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= (next_item_size as f64) * 0.3;
        } else {
            score += (next_item_size as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin would leave large waste
    if bin_residual == bin_capacity {
        // opening new bin competes with post_residual of existing placement
        let waste_penalty = (bin_capacity as f64) - (item_size as f64);
        score = waste_penalty * 0.9;
        // open new bin early in stream or when many bins open (spread load)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        if open_bins_count == 0 {
            score -= 1000.0;
        }
    }

    // Prefer bins below mean residual (tighter bins get filled first)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (items are >= 1, but gaps < ~15 rarely absorb future items).
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // hard penalty: pure dead space
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 100.0;
    }

    // Reward tight fits: fraction of bin used by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last chance: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (post_residual would be dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // (favor bins with low residual) rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - fill_ratio);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "small" bin — using it up is good (reduces fragmentation).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 45.0; // chains a near-perfect follow-up placement
            } else if slack <= 25.0 {
                score -= 15.0;
            }
        } else {
            // post_residual cannot host next item: slight penalty proportional
            // to how close it is to being wasted.
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 10.0;
            }
        }
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when this placement would create dead space or no
    // open bin fits well.
    if bin_residual == bin_capacity {
        // Neutral-ish base: new bin residual = capacity - item_size,
        // already captured by post_residual. Add mild preference when
        // open bins are fragmented.
        score += 5.0;
        if open_bins_count > 0 && post_residual as f64 > mean_residual {
            score -= 10.0; // spreading when existing bins are tight
        }
    }

    // Late-stream tightening: as the stream ends, waste matters more.
    score -= 10.0 * progress * (1.0 - fill_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits perfectly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-step chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow: penalize proportionally to wasted residual
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Reward tight fits relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize residual far below mean residual (fragmented bin).
    score += 0.5 * (mean_residual - post_residual as f64).abs();

    // Last chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Penalize opening a new bin when many bins are open and mean residual is large.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size as f64 <= mean_residual {
            score += 20.0; // existing bins likely serve the next item too
        }
    }

    // Late-stream consolidation: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear in post_residual).
    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Penalize large dead space quadratically: unusable slivers are costly.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fill bonus
    }
    if post_residual > bin_capacity / 2 {
        score += 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if the next item exactly fills the post-residual, strongly prefer this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item could also fit here after this placement, mild bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 3.0;
    }
    // If next item is large and would not fit here, penalize leaving big gaps unused elsewhere?
    if next_item_size > post_residual && post_residual > 0 {
        score += 1.5;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base new-bin cost, reduced late in the stream or when bins are scarce.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 - 8.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 6.0; // large upcoming item benefits from a fresh bin
        }
    }

    // Prefer filling bins below the mean residual (balance toward consolidation).
    score -= 0.5 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Mild pressure when many bins are open: encourage consolidation.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post-residual with stream progress
    let p = progress;
    let poly = 1.0 + p * (0.8 - 1.6 * p * (1.0 - p));

    let mut score = pr * poly;

    // Reward tight fits: penalize high post-residual quadratically, scaled by progress
    score += 40.0 * norm_pr * norm_pr * (0.5 + p);

    // Dead-space penalty when residual becomes too small to be useful later
    let small_threshold = 20.0;
    if pr < small_threshold {
        score += (small_threshold - pr) * (1.0 + 2.0 * p);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        if diff >= 0.0 {
            score -= 12.0 * (diff / cap);
        } else {
            score += 6.0 * (-diff / cap);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + p);
    }

    // New-bin candidate: penalize mildly, more so late in the stream
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * p;
    }

    // Mean residual coupling: prefer bins whose residual deviates from the mean (consolidation)
    score += 4.0 * (pr - mean_residual).abs() / cap;

    // Slight preference for fuller bins overall
    score -= 5.0 * (1.0 - norm_pr) * (0.5 + p);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod small integers
    let r = post_residual;
    let class = (r % 10) as f64;

    // Reward post-residuals that are "friendly" sizes for future items (10..100)
    if r == 0 {
        score -= 25.0; // perfect closure
    } else if r <= 10 {
        score -= 8.0 - class * 0.4; // small residue still usable by tiny items
    } else if r % 20 == 0 {
        score -= 6.0;
    } else if r % 10 == 0 {
        score -= 3.0;
    } else {
        score += class * 0.6; // penalize awkward residues
    }

    // Lookahead coupling: does the next item fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0;
        } else if next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            score += slack * 0.15;
            if (r - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer filling bins when many are open
    score += mean_residual * 0.05;
    score -= (open_bins_count as f64).ln() * 2.0;

    // Late-stream consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 12.0 - (fitting_bins_count as f64) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // plausible future item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // "Awkward gap" zone: residuals 10..30 are hard to fill with items in
    // 10..80 range unless an exact-ish match arrives; penalize mildly.
    if post_residual >= 10 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 0.8;
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 25.0 * tightness * tightness;

    // Perfect / near-perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead (k=2): if the next item fits the post-residual exactly or
    // nearly, this placement sets up a great follow-up; reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 18.0;
            }
        }
        // If next item cannot use the leftover space at all, mild penalty
        // when the leftover is small (dead space for the next step too).
        if next_item_size > post_residual && post_residual < 10 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, encourage consolidation into
    // existing bins rather than fragmenting capacity.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= 4.0 * pressure;
    }

    // New-bin candidate handling: an empty bin has large post_residual, so it
    // already scores high. Add a fixed surcharge so a new bin is opened only
    // when no open bin offers a decent fit; relax the surcharge late in the
    // stream when leftover items are few.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 55.0 - 15.0 * progress;
        // If the item exactly halves or nearly fills a fresh bin, opening is
        // more attractive.
        if item_size * 2 == bin_capacity {
            score -= 12.0;
        }
    }

    // Mean-residual coupling: if this bin's post-residual deviates upward
    // from the mean residual of open bins, it creates heterogeneous waste.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs().sqrt() * dev.signum();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: exact match of next item into post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size {
            score -= 20.0; // next item still fits here
        } else {
            // dead space relative to next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && post_residual <= bin_capacity {
        score -= 80.0;
    }

    // Penalize leaving large unusable slivers (below min item size 1..10 range)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Late in stream: prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 0 {
        score += progress * 5.0;
    }

    // Avoid opening new bins when a decent fit exists
    if bin_residual == bin_capacity {
        score += 25.0;
        if post_residual > 0 && next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0; // fresh bin perfectly preps next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item).
    let fit_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score += fit_ratio * 12.0;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        if next_item_size == 0 || next_item_size > post_residual {
            score += post_residual as f64 * 0.8;
        } else {
            // Lookahead bonus: next item fits exactly or nearly.
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= (post_residual as f64 - gap) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with larger residuals when many bins are open (consolidation).
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Deviation from mean residual: prefer atypical bins to balance state.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.05;

    // Time horizon: early in stream, be picky (penalize waste more); late, pack greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * post_residual as f64 * 0.3;

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let open_waste = mean_residual * open_bins_count.max(1) as f64;
        // Prefer new bin if existing residuals are large and fragmented.
        score = 100.0 + open_waste * 0.1 - progress * 20.0;
        if fitting_bins_count == 1 {
            score += 60.0; // never open new bin when a last-chance bin exists
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // fresh bin can host lookahead chain
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with smooth non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * (1.0 - norm_pr));

    // Stream-progress coupling: penalize residual more as stream advances
    let prog_poly = progress * progress * (3.0 - 2.0 * progress);
    score += 12.0 * prog_poly * norm_pr * norm_pr;

    // Perfect fit reward (subtract)
    if post_residual == 0 {
        score -= 40.0 * (1.0 + prog_poly);
    }

    // Lookahead coupling: reward leaving space the next item can use
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let tight = 1.0 - (pr - ni) / cap;
            score -= 15.0 * tight * (1.0 - prog_poly);
        } else {
            score += 8.0 * (ni - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly early, more when open bins are loose
    if bin_residual == bin_capacity {
        score += 6.0 + 0.3 * open_bins_count as f64 + 0.5 * mean_residual / cap;
    }

    // Mean residual divergence penalty
    score += 0.2 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual), with harmonic class weighting
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // Harmonic classes: classify dead space by divisibility / magnitude classes
        let class_bonus: f64 = if pr <= 10 {
            -25.0 // small dead space, very usable
        } else if pr % 10 == 0 {
            -18.0 // round residual likely reusable by common item sizes
        } else if pr % 5 == 0 {
            -12.0
        } else if pr <= 30 {
            -6.0
        } else {
            0.0
        };
        score += class_bonus;

        // Harmonic fraction penalty: dead space as fraction of capacity
        let frac = pr as f64 / cap;
        score += 30.0 * frac * frac;
    }

    // If the next item fits exactly in the post residual, strongly reward
    if next_item_size > 0 && next_item_size <= pr {
        let slack = pr - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else if slack <= 10 {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        // next item cannot use leftover: penalize proportionally
        score += (next_item_size - pr) as f64 * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when existing fit is bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins generally; scaled by how many bins already open
        score += 45.0 + 3.0 * open_bins_count as f64;
        // But if this is a large item and few bins, new bin is fine
        if item_size >= 50 {
            score -= 15.0;
        }
        // Late in stream, discourage proliferation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Reward using existing bins, more so when many are open
        score -= 8.0;
    }

    // Mild preference to balance: avoid dumping into bins far from mean residual
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 40.0 * (1.0 - gap / 10.0); // tiny gaps are dead space
        }
    } else {
        score -= 25.0; // perfect fit strongly rewarded
    }

    // Reward tight fits relative to bin residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
    score -= 15.0 * tightness;

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / 100.0);
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 8.0; // post residual won't hold next item
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer existing bins over new bins.
    let new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if new_bin {
        score += 10.0 + 3.0 * open_bins_count as f64;
        // Early in stream, new bins are cheaper; late, avoid fragmentation.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 15.0 * progress;
        // If mean residual is large, existing bins have room; discourage new bin.
        score += mean_residual * 0.3;
    }

    // Prefer bins with residuals close to item size (waste minimization).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a nonlinear boost.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward exact matching of post_residual with next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect 2-chain: bin becomes exactly full after next item
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // penalize leftover gap after hypothetical next placement
            score += 0.25 * gap;
            if gap <= 10.0 {
                score -= 8.0; // near-perfect chain still valuable
            }
        } else {
            // next item won't fit after this placement; penalize proportionally
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.15 * overflow;
        }
    } else {
        // Last item: any residual is pure waste; favor the fullest bin.
        score += 20.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (denser bins),
    // which concentrates waste into fewer bins.
    let rel = (bin_residual as f64) - mean_residual;
    score += 0.08 * rel;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is huge relative to capacity
    // or no good fit exists elsewhere; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let fill_ratio = (item_size as f64) / (bin_capacity as f64);
        if fill_ratio > 0.85 {
            score -= 15.0; // large item deserves a fresh bin
        } else {
            score += 18.0 + 10.0 * (1.0 - fill_ratio);
        }
        // fewer open bins -> slightly cheaper to open one
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mild late-stream pressure to consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness;

    // Penalize creating dead space that no typical future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score -= 1.0; // medium residual still useful
    } else if post_residual >= 30 {
        score += 0.5 * (post_residual as f64 - 30.0) / 70.0; // large leftover mild penalty
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead: reward leaving space exactly fitting the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual > next_item_size {
            // residual can host next item: mild reward proportional to snugness
            let slack = (post_residual - next_item_size) as f64;
            score -= 2.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit in leftover: small penalty scaled by gap
            score += 0.03 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate handling: make empty bin attractive only when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset when few bins open or stream is early.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 40.0;
        new_bin_score -= 10.0 * (1.0 - progress);          // cheaper early in stream
        new_bin_score -= 1.5 * open_bins_count as f64;      // more open bins -> reuse them
        new_bin_score -= 0.2 * mean_residual;               // high mean residual -> reuse
        if next_item_size > 0 && next_item_size >= item_size {
            new_bin_score -= 3.0; // new bin helps fit next big item too
        }
        score = score.min(new_bin_score + 25.0);
        // Keep new bin strictly worse than a perfect fit but competitive with bad fits.
        score = score.max(20.0);
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer bins with residual close to the item (reduce fragmentation).
    if open_bins_count > 0 {
        let frag = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * frag;
    }

    // Dynamic time horizon: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post residual (dead space), softened by progress
    let mut score = pr * (1.0 + 1.5 * norm_pr * (1.0 - progress));

    // Smooth non-linear coupling: post_residual interacts with stream progress
    let coupling = (pr / (cap * 0.5)).powi(2) * (0.5 + progress);
    score += 12.0 * coupling;

    // Reward tight fits: item filling most of residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill * fill * (0.5 + 0.5 * progress);

    // Penalize leaving residual that is too small for typical future items
    let small_gap = (norm_pr * (1.0 - norm_pr)).max(0.0); // peaks near mid residual
    score -= 6.0 * small_gap * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 15.0 * (-diff / 20.0).exp();
        // Penalize post residual slightly smaller than next item (dead space)
        if pr < next_item_size as f64 && pr > 0.0 {
            score += 5.0 * (1.0 - pr / next_item_size as f64);
        }
    }

    // Mild penalty for opening new bins late when many bins already open
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0)) * (0.5 + progress);
    }

    // Tie-break with mean residual alignment
    score += 0.05 * (mean_residual - pr).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: mod-10 buckets penalize "awkward" leftovers
    let post = post_residual as u32;
    let awkward = post % 10; // leftover mod 10
    if post > 0 {
        score += 6.0 * (1.0 - awkward as f64 / 9.0) * (post as f64 / cap).powf(0.5);
    } else {
        // Perfect fit: strong reward
        score -= 40.0;
    }

    // Small dead space (<= 10) is nearly unusable: heavy penalty
    if post > 0 && post <= 10 {
        score += 25.0;
    }

    // Reward tight fits (residual close to item size before placement)
    let tightness = (bin_residual - item_size) as f64 / cap;
    score -= 10.0 * (1.0 - tightness);

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 35.0;
        } else if next_item_size < post {
            // harmonic compatibility: next item leaves another small residual
            let combo = post - next_item_size;
            if combo % 10 == 0 {
                score -= 12.0;
            }
            score += 0.3 * (post - next_item_size) as f64;
        } else {
            // next item won't fit here: mild penalty proportional to overflow
            score += 0.2 * (next_item_size - post) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current bins are nearly full / crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * 0.5 + mean_residual / cap * 2.0;
        score = 120.0 + progress * 30.0 - pressure;
        if next_item_size > item_size && next_item_size > 0 {
            score += 15.0; // keep fresh bin for bigger next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

