        if post_residual == next_item_size {
            score -= 50.0; // lookahead perfect fit
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space relative to lookahead: penalize gap the next item cannot use
        score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.8;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 70.0;
    }

    // Open bins pressure: many open bins -> favor consolidation into existing bins
    let pressure = (open_bins_count as f64).ln().max(1.0) * 4.0;
    score += pressure;

    // New-bin candidate handling: empty bin has residual == capacity.
    // Only attractive when no good existing fit exists; make it moderately costly by default.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if existing bins are fragmented (high mean residual spread) and many bins open,
        // a fresh bin is fine — reduce penalty.
        if open_bins_count > 3 && mean_residual < (bin_capacity as f64) * 0.35 {
            score -= 30.0;
        }
        // If the item is large relative to typical residuals, new bin is reasonable
        if item_size as f64 > mean_residual {
            score -= 15.0;
        }
    } else {
        // Reusing an existing bin is generally good: reward proportional to how much
        // of the residual the item consumes (tightness of fit).
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 30.0;
    }

    // Late in the stream, prefer closing bins out (avoid leaving many partially-filled bins)
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if progress > 0.8 && post_residual > 0 {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect 2-chain: fill bin completely over two items
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 80.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize more if post_residual is a small dead zone
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 0.0; // tiny waste is fine
            } else {
                score += dead * (dead / bin_capacity as f64) * 1.5;
            }
        }
    }

    // Compare against mean residual: bins with residual near mean are "normal";
    // penalize placing into bins already below mean residual (preserving big spaces)
    let res = post_residual as f64;
    if res < mean_residual {
        score += (mean_residual - res) * 0.8;
    } else {
        score -= (res - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 40.0;
        }
        if fitting_bins_count > 0 {
            score += 50.0;
        }
    }

    // Early in stream: be slightly more willing to open bins / keep space
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual is already good; amplify it).
    score *= 1.0 + (item_size as f64 / bin_capacity as f64);

    // Penalize leaving residuals that no plausible future item can use well:
    // dead space is residual that is small but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can exactly host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here; slight penalty scaled by wasted potential
            score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // If many bins fit the item, prefer the tightest; add mild dispersion penalty
    // proportional to how far this bin's residual is above the mean residual.
    if fitting_bins_count > 1 {
        score += (bin_residual as f64 - mean_residual).max(0.0) * 0.3;
    }

    // Time horizon: early in the stream, be conservative (keep bins flexible);
    // late in the stream, aggressively fill bins since few items remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin is flexible but costs a bin.
    // Prefer it only when the item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let flexibility_bonus = if next_item_size > 0 {
            10.0 * (1.0 - item_size as f64 / bin_capacity as f64)
        } else {
            0.0
        };
        score += 20.0 + flexibility_bonus;
    }

    // Mild penalty for proliferating open bins early on (fragmentation control).
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tightness: reward low post_residual non-linearly
    let tight = 1.0 - (pr / cap);
    score -= 12.0 * tight * tight;

    // Dead-space penalty: residual too small for typical future items (non-linear bump)
    let dead = ((18.0 - pr).max(0.0) / 18.0);
    score += 15.0 * dead * dead;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).abs();
        score -= 10.0 * (-gap / 10.0).exp() * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress * 0.3);
    }

    // New-bin candidate handling: penalize opening a bin unless current fit is bad
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        score += 8.0 + 6.0 * (1.0 - tight);
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // more open bins -> less eager to open new ones
        score += open_bins_count as f64 * 0.8;
    }

    // Mean residual coupling: avoid bins deviating from mean (balance residuals)
    let dev = (pr - mean_residual).abs() / cap;
    score += 4.0 * dev * dev;

    // Late stream: prefer filling existing bins tighter
    score -= 6.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot" of capacity it falls into.
    let class = (post_residual / 10).min(9) as f64;
    let frac = (post_residual % 10) as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead space penalty grows super-linearly in the lowest harmonic class
        // (tiny unusable slivers are the worst outcome).
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 8.0;
        }
        // Mid classes: mild shaping so we prefer residuals that are "round"
        // multiples of common item sizes (harmonic slots).
        score += class * 1.5 - frac * 0.3;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let next_slack = post_residual - next_item_size;
            if next_slack < 10 {
                score -= 150.0 - next_slack as f64 * 5.0;
            } else {
                score -= 20.0;
            }
        }
        // If next item cannot fit here anyway, this bin's residual is final;
        // penalize leaving large but unusable residue.
        if next_item_size > post_residual && post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate (empty bin): penalize so we only open new bins when no
    // open bin offers a decent fit. The penalty decays as the stream progresses
    // and when many bins are already open (consolidation phase).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let base = 320.0 - 120.0 * progress;
        let crowd = (open_bins_count as f64).min(20.0) * 4.0;
        score += base + crowd;
        // Opening a new bin is more attractive for large items that would leave
        // a huge residual anywhere (item near capacity).
        if item_size >= 70 {
            score -= 100.0;
        }
    }

    // Mild preference for bins whose residual deviates from the mean:
    // place items into below-average-residual bins to consolidate.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (dead space threshold).
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // If the lookahead item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 8.0 + slack as f64 * 0.3;
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // Next item cannot follow into this bin: mild penalty unless bin is nearly full anyway.
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * (post_residual as f64) * 0.05;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized when good fitting bins exist.
        score += 15.0 + fitting_bins_count as f64 * 5.0;
        // But attractive if the item is huge relative to mean residual (poor fits elsewhere).
        if mean_residual > 0.0 && (item_size as f64) > mean_residual + 20.0 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Small global tie-breaker toward compactness.
    score += (bin_residual as f64 - post_residual as f64) * -0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strong reward
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // slight bonus when post_residual slightly exceeds next item
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0;
        }
        // penalize wasting a large residual on a small item
        if post_residual > next_item_size + 30 {
            score += 12.0;
        }
    } else {
        // last item: just minimize wasted residual
        score -= 20.0;
    }

    // Dead-space penalty: residuals too small for typical items
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Mild preference for keeping a few open bins when stream is early
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if open_bins_count > 2 && progress < 0.5 {
        score += 2.0;
    }

    // New-bin candidate: only attractive when item barely fits anywhere else
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 || item_size > 70 {
            score -= 40.0;
        } else {
            score += 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is already the base).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Lookahead bonus: residual can host the next item.
            score -= 6.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            // Dead space: waste that likely can't be recovered.
            let waste = post_residual as f64;
            score += 2.5 * waste * (1.0 - step_index as f64 / total_items.max(1) as f64);
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // the item is large relative to capacity or open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let big_item = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for large items late in stream or when bins are fragmented.
        score += 10.0 - 14.0 * big_item - 5.0 * crowding - 4.0 * progress;
        // If no open bin fits at all, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mild preference for bins with residuals near multiples that pack well.
    let r = post_residual as f64;
    if r > 0.0 && r < 10.0 {
        score += 3.0; // tiny useless slivers
    }

    // Global balance: prefer bins whose residual is close to mean residual.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap; // 0..1
    let prog_sq = progress * progress;
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * prog_sq * 2.0;
    score += 12.0 * coupling;

    // Penalize waste relative to mean residual (smooth quadratic term).
    let diff = pr - mean_residual;
    score += 0.05 * diff * diff / cap;

    // Reward tight fits: small post residual gets a smooth bonus.
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bonus: avoid opening a new bin when only one fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: favor bins leaving room for the next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score -= 6.0 * slack * (1.0 - slack);
        } else {
            score += 5.0 * (ni - pr) / cap;
        }
    }

    // Mild penalty for proliferation of open bins early in the stream.
    score += 0.5 * (open_bins_count as f64) * (1.0 - progress) / (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on residual space.
    // Residuals that are "harmonically friendly" (small, or divisible into
    // common item classes like 10/20/25/50) are less penalized.
    let pr = post_residual;
    if pr > 0 {
        // Dead-space penalty grows super-linearly for awkward residuals.
        let frac = pr as f64 / cap;
        score += 20.0 * frac * frac;

        // Harmonic bonus: residual divisible by common item sizes is reusable.
        if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 5.0; }
        if pr % 50 == 0 { score -= 6.0; }

        // Very small leftover (< 10, minimum item size) is pure dead space
        // unless exactly 0; penalize hard via a threshold on integer division.
        if pr < 10 && pr > 0 {
            score += 15.0;
        }
    } else {
        // Perfect fill: strong reward.
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if pr >= next_item_size {
            // Next item fits: residual class reuse reward, scaled by tightness.
            let tight = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - tight / cap);
            if pr % next_item_size == 0 {
                score -= 6.0; // harmonic divisibility of residual by next item
            }
        } else {
            // Next item won't fit here: penalize leaving a bin that strands it.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening new bins unless current bin is bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; relax late in the stream or when open bins
        // are already fragmented (high mean residual).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 55.0 - 15.0 * progress;
        if mean_residual > 40.0 {
            new_bin_cost -= (mean_residual - 40.0).min(30.0) * 0.4;
        }
        if open_bins_count == 0 {
            new_bin_cost = 0.0;
        }
        score += new_bin_cost;
        // Harmonic check: an empty bin is maximally harmonic; slight discount.
        score -= 5.0;
    }

    // Mild preference for tighter fits among similar residuals: tie-break on
    // item size relative to bin residual (larger item = less wasted ratio).
    score -= 3.0 * (item_size as f64 / cap);

    // Small noise-free deterministic tie-breaker via residual class hash.
    let class = (pr % 7) as f64;
    score += 0.5 * class;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: convex penalty on leftover space,
    // extra harsh on tiny unusable slivers (gaps that likely waste capacity).
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead sliver: residual too small for typical items
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead (k=2): reward if the next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover can't host the next item -> mild penalty
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins slightly,
    // but keep new-bin option viable only for genuinely bad fits.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer a new bin only if the best existing fit would leave a big mess.
        // Base cost of opening a bin, offset by its pristine full residual.
        score += 30.0;
        if item_size >= 80 {
            score -= 20.0; // big item: fresh bin is often good
        }
    }

    // Mild progression coupling: late in the stream, be more conservative
    // about opening bins (favor consolidation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // Coupling with mean residual: if open bins are already loose,
    // penalize adding more slack elsewhere.
    if bin_residual < bin_capacity {
        score += 0.05 * (mean_residual - pr).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: after placing this item,
    // the residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Partial lookahead credit: next item fits with little slack left over.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item does NOT fit here: penalize proportionally to how
        // badly the residual is stranded relative to mean residual.
        let stranded = (post_residual as f64 - mean_residual).max(0.0);
        score += 0.5 * stranded;
        score += 10.0;
    }

    // Penalize tiny dead space (unusable slivers) more than large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward filling bins tightly when many bins compete (waste-avoidance).
    if fitting_bins_count > 1 {
        score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when this bin's fit is poor
    // (large post_residual compared to mean residual of open bins).
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64 - mean_residual).max(0.0);
        score += 20.0 + 0.3 * poor_fit;
        // Late in the stream, avoid opening new bins unless necessary.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for bins already below-average residual (compact them).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Penalize creating dead space that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny residual is excellent (near-perfect fill)
    } else if post_residual >= 10 && post_residual < 20 {
        score += 5.0; // moderately wasteful
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; slight penalty for leaving large gap unusable by next
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin, unless open bins are tight
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        // opening new bin is attractive when existing bins are nearly full
        score += 60.0 - avg_pressure * 50.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // late in stream, prefer filling existing bins harder
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Prefer bins below mean residual (keeps balance, avoids fragmentation)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Mild penalty for many open bins (consolidation pressure)
    score += open_bins_count as f64 * 0.5;

    // Reward using larger residuals when item is large
    score -= (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // base: prefer small post residual
    let mut score = pr as f64;

    // smooth non-linear polynomial coupling with stream progress
    let poly = x * x * (1.0 - progress) + x * x * x * progress;
    score += 60.0 * poly;

    // dead-space penalty: very small residuals are wasteful, penalize smoothly
    let dead = (1.0 - x).powi(3);
    score += 25.0 * dead * (0.5 + progress);

    // last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // lookahead: reward residual that fits next item exactly or well
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        score -= 20.0 * (1.0 - gap / cap).max(0.0);
        if ns <= pr {
            score -= 10.0;
        }
    }

    // penalize spreading across too many open bins mildly
    score += 0.5 * open_bins_count as f64 * (x - mean_residual / cap).abs();

    // reward tight fits with smooth term
    score -= 15.0 * (1.0 - x).max(0.0) * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "small residue" classes are rewarded (tight fits leave dead space that
    // is hard to reuse).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Class A: post_residual < 10 -> nearly perfect fit, strong reward.
    if post_residual < 10 {
        score -= 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Class B: post_residual in [10, 30) -> moderately reusable residue.
    else if post_residual < 30 {
        score -= 20.0 + (30 - post_residual) as f64 * 0.8;
    }
    // Class C: post_residual in [30, 60) -> awkward middle zone, penalize.
    else if post_residual < 60 {
        score += 15.0 * (1.0 - (pr - 30.0) / 30.0);
    }
    // Class D: post_residual >= 60 -> large residue, still valuable.
    else {
        score -= 10.0;
    }

    // Modulo-10 harmonic structure: residues that are multiples of 10 pair
    // well with typical item sizes (which cluster on decade boundaries).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }

    // Lookahead coupling (k=2): reward if the next item exactly fits the
    // post-residual (harmonic pairing), penalize if next item is slightly
    // larger than the residue (near-miss creates frustration).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni == pr && pr > 0.0 {
            score -= 70.0;
        } else if ni < pr {
            // next item also fits: bonus scaled by how much room remains
            // for a third item afterwards.
            let rem = pr - ni;
            score -= 25.0 - rem * 0.3;
            if (rem as u32) % 10 == 0 && rem > 0.0 {
                score -= 6.0;
            }
        } else if ni - pr <= 10.0 && pr > 0.0 {
            score += 12.0; // near-miss: this residue likely becomes dead
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
        if post_residual < 10 {
            score -= 25.0;
        }
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Give the empty bin a moderate baseline so
    // tight fits in existing bins beat it, but awful fits (large post
    // residual relative to capacity) do not.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score += 40.0;
        // early in the stream, opening bins is cheaper (fewer open bins to
        // manage later); late in the stream, consolidation matters more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * (1.0 - progress);
        // if many bins are open, discourage opening yet another one
        score += open_bins_count as f64 * 2.0;
    } else {
        // Existing-bin preference: mild reward for consolidation.
        score -= 5.0;
        // Prefer bins that are already somewhat full (below-mean residual
        // means this bin is a leader; filling leaders keeps the bin count
        // down).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Small global tie-breaker proportional to fill ratio for determinism.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100 range)
    // are pure waste. Penalize sharply when post_residual falls in an unusable gap.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 500.0; // cannot happen with min 1, but guard anyway
    }
    // Unusable if smaller than the smallest plausible next need: next item size
    // or a conservative floor of the stream's small-item scale.
    let floor_need = if next_item_size > 0 { next_item_size } else { 1 };
    if post_residual > 0 && post_residual < floor_need {
        score += 120.0 + (floor_need - post_residual) as f64 * 4.0;
    }
    // Dead-space gradient: small nonzero residuals are worse than large ones
    // (non-linear quadratic penalty on tiny gaps).
    if post_residual > 0 && post_residual <= 20 {
        score += (20 - post_residual) as f64 * (20 - post_residual) as f64 * 0.35;
    }

    // Reward tight fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        score -= 25.0 * (item_size as f64 / bin_residual as f64);
    }

    // Lookahead: if next item fits exactly in the post residual, strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling with open bins count.
        score += 30.0 + 6.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    } else {
        score -= (open_bins_count as f64).ln().max(0.0) * 3.0;
    }

    // Mean-residual coupling: prefer bins near the mean residual (balanced usage).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small dead space relative to capacity: reward tight fits.
        let tightness = (post_residual as f64) / (bin_capacity as f64);
        score += tightness * 50.0;

        // 2-step lookahead: if next item fits exactly in the post residual, reward heavily.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 500.0;
            } else if post_residual >= next_item_size {
                // Next item fits: mild reward proportional to how snugly.
                score -= 30.0 * (next_item_size as f64 / post_residual as f64);
            } else {
                // Next item cannot fit: penalize wasted residual, worse for medium dead space.
                let waste = (next_item_size - post_residual) as f64;
                score += waste * 0.5;
            }
        }

        // Penalize post residual far from mean residual (fragmentation vs. fleet state).
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.3;

        // Reward keeping residuals above the smallest possible item threshold (1..100 unknown),
        // but penalize large unusable gaps.
        if post_residual < 10 {
            score -= 20.0; // tiny residual is effectively closed; fine to finish it
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Late in stream: prefer compacting into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 25.0;

    // Many open bins: encourage filling existing ones rather than opening more.
    score += (open_bins_count as f64) * 2.0;

    // New-bin candidate: make it unattractive unless residual situation is bad.
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if nothing else fits well (large item, few fitting bins), allow new bin.
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
        if next_item_size > 0 && item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space: post_residual too small to ever hold a min-size item.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 50.0;
    } else if post_residual < 10 {
        // Small awkward gap: penalize proportionally to how useless it is.
        score += 3.0 * (10.0 - post_residual as f64);
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            // Reward leaving room for the next item, scaled by how much slack remains.
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Post-residual can't hold next item: mild penalty, worse for large overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 0.08 * overshoot;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // Cheaper to open a new bin early in the stream (long horizon ahead).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // Cheaper when few bins are open (keeps bin count growth controlled but allows early spread).
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        // If mean residual across open bins is large, open bins are roomy -> new bin less needed.
        score += 0.05 * mean_residual;
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 60 {
            score -= 8.0;
        }
    } else {
        // Existing bin: slight bonus when many bins are open (consolidate).
        score -= 0.3 * (open_bins_count as f64).ln().max(0.0);
        // Favor bins whose residual is above mean (use the roomier ones less, keep roomy bins flexible):
        // i.e. penalize placing into bins that are much roomier than average.
        let diff = (bin_residual as f64) - mean_residual;
        if diff > 0.0 {
            score += 0.04 * diff;
        }
        // Time-dependent aggression: late in stream, pack tighter (favor small post_residual more).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 5.0 * progress * tightness;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;
    let mut score = pr as f64;
    // smooth non-linear coupling of post_residual with stream progress
    let poly = x * x * (1.0 - progress) + x * x * x * progress;
    score += 20.0 * poly;
    // penalize residual that cannot fit lookahead item
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 8.0 * fits_next * (1.0 - progress) + 4.0 * fits_next * progress;
        let tight = (next_item_size as f64 - pr).abs() / cap;
        score += 3.0 * tight * tight;
    }
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress) + 5.0 * progress;
    }
    // mean residual deviation penalty, scaled by progress
    let dev = (mean_residual - pr) / cap;
    score += 5.0 * dev * dev * (0.5 + progress);
    // new-bin candidate: mildly discouraged unless residuals are fragmented
    if bin_residual == bin_capacity {
        score += 6.0 - 6.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: perfect fits and tiny remnants are golden.
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 3.0;
    } else {
        // Large dead space penalty, scaled by fraction of capacity
        score += (post / cap) * 25.0;
    }

    // Modulo-10 harmonic classes: remnants that align with typical item granularity
    let rem_class = post_residual % 10;
    if rem_class == 0 {
        score -= 6.0;
    } else if rem_class >= 8 {
        score += 4.0; // awkward 8/9 slivers
    }

    // Lookahead: reward if next item fits into the resulting residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly-ish: strong reward
            let tight = (post_residual - next_item_size) as f64;
            score -= 25.0 - tight.min(20.0) * 0.5;
        } else {
            // next item won't fit here: penalize wasted potential
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins when many bins are open (encourage consolidation)
    let fill_frac = 1.0 - post / cap;
    score -= fill_frac * 10.0;

    // Mild bias toward open bins vs new bin early in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless stream is late and open bins are crowded
        score += 18.0 - progress * 10.0 + (open_bins_count as f64).min(20.0) * 0.5;
    } else {
        score -= 2.0;
    }

    // Mean-residual coupling: if this bin is much emptier than average, slight penalty
    let dev = post - mean_residual;
    score += dev.clamp(-30.0, 30.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small to hold even the smallest plausible item.
    let min_item = 1.0f64.min(bin_capacity as f64);
    if post_residual > 0 && (post_residual as f64) < 10.0 {
        // Unusable sliver: penalize proportionally to how close it is to zero.
        score += (10.0 - post_residual as f64) * 12.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Small gap: only usable by tiny items; moderate penalty.
        score += 15.0;
    }

    // Perfect fit reward: exact fill leaves nothing behind.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Reward residual that still accommodates the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creating a gap that blocks the next item: penalize dead space creation.
        score += 20.0 + 0.3 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize new-bin candidate implicitly by keeping open-bin scores lower).
    score += open_bins_count as f64 * 2.0;

    // Tight-fit preference: reward placements that consume a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Early in stream: be slightly more willing to open bins / keep flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0;

    // Mean-residual coupling: bins far below mean residual are better targets
    // for large items (balances residual spread).
    score -= (mean_residual - post_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead-space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // perfect chain: bin becomes exactly full after next item
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 10.0 {
                score -= 120.0 - gap * 6.0; // tight chain fit
            } else {
                score -= (30.0 / gap).max(0.0); // mild reward for usable leftover
            }
        } else {
            // Next item can't fit here; penalize proportionally to wasted potential.
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.8;
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 40.0 * (0.5 - rel); // leaving less than average waste is good
        } else if rel > 1.5 {
            score += 25.0 * (rel - 1.5); // leaving much more waste than average is bad
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = if open_bins_count == 0 {
            -500.0 // first bin always fine
        } else {
            let avg_free = mean_residual;
            if avg_free < item_size as f64 * 1.1 {
                -50.0 // open bins nearly exhausted, opening is reasonable
            } else {
                150.0 + avg_free * 2.0 // plenty of space left: discourage new bin
            }
        };
        score += pressure;
        // Slight progression bias: later in stream, consolidation matters more.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 20.0;
        }
    }

    // Mild penalty for very large leftovers that likely become dead space.
    if post_residual > 40 && post_residual < item_size.min(60) {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 20.0 + (10 - post_residual) as f64;
    }

    // Penalize dead space that no future item can plausibly fill.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress); // small unusable gap early on is bad
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item can't fit here; mild penalty proportional to overshoot
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // and there are few open bins relative to progress.
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        let poor_fit = post_residual as f64 > 30.0;
        let many_open = open_bins_count as f64 > 3.0 + 5.0 * progress;
        if poor_fit && many_open {
            score -= 10.0; // allow fresh bin when current fits are all bad
        } else {
            score += 35.0 - 20.0 * fit_quality; // discourage new bins otherwise
        }
    }

    // Global state: prefer filling bins below mean residual (larger residuals)
    // to consolidate space.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Mild preference for bins with less residual overall (best-fit bias),
    // scaled down as stream progresses.
    score += 0.2 * (1.0 - progress) * post_residual as f64;

    // Coupling: when many bins are open, encourage tightening (reduce fragmentation).
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

