    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    let tightness = (1.0 - fit_ratio).powi(3);
    score -= 12.0 * tightness * (0.5 + progress);

    // Reward near-perfect fills strongly (smooth exponential coupling).
    score -= 20.0 * (-fit_ratio * 8.0).exp();

    // Penalize dead space that no plausible item can fill: quadratic in wasted gap.
    let gap = post_residual as f64 - 1.0;
    score += 0.02 * gap * gap * (1.0 - progress);

    // Lookahead: bonus if the next item fits the post-residual (smooth reward).
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let coupling = (next_item_size as f64 / post_residual as f64).powi(2);
