        let miss = post_residual as f64 - next_item_size as f64;
        if miss < 10.0 {
            score += 0.5 * (10.0 - miss);
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate (empty bin): penalize mildly, more early when consolidation matters.
    if bin_residual == bin_capacity {
        score += 6.0 + 8.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    } else {
        // Favor bins with residuals below mean (consolidate large gaps).
        let dev = mean_residual - post_residual as f64;
        score -= 0.3 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class: post_residual bucketed by integer division thresholds.
    let pr = post_residual as f64;
    let cls = (post_residual / 10).min(10) as f64; // 0..10 harmonic class
    // Reward small post_residual strongly (tight fit), superlinear.
    score -= 40.0 * (1.0 - cls / 10.0).powi(3);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo coupling: post_residual divisible by common item sizes (10/20/25/50)
    // leaves reusable residue classes -> reward.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 8.0;
    }

    // Penalize dead space: residual too small for minimum item (1) but awkward
    // relative to capacity fractions.
    let frac = pr / cap;
    if frac > 0.0 && frac < 0.10 {
        score += 25.0 * (0.10 - frac) / 0.10; // unusable sliver
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            // reward if next item leaves a harmonic residual class again
            let nn = post_residual - next_item_size;
            if nn % 10 == 0 || nn % 25 == 0 {
                score -= 12.0;
            }
            score -= 6.0 * (nn as f64 / cap);
        } else {
            // next item won't fit here: mild penalty proportional to gap
            score += 5.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bin attractive only when open bins
    // are mostly full or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / cap;
        // Penalize new bin when existing bins have room (high mean residual).
        score += 45.0 * pressure;
        // Early stream: slightly discourage hoarding bins; late: allow.
        score += 10.0 * (1.0 - progress);
        // Large items start fresh bins more willingly.
        score -= (item_size as f64 / cap) * 15.0;
    }

    // Mild dispersion penalty: avoid spreading load across many bins.
    score += 0.5 * open_bins_count as f64;

    // Tie-break: prefer bins whose residual is close to item (best-fit flavor).
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

