    // plausible item are pure waste -> heavy penalty.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // exact fill is perfect, but guard anyway
    }
    if post_residual == 0 {
        score -= 500.0; // perfect fit: strong reward
    } else if post_residual < 10 {
        // dead space: unusable gap below typical minimum item size
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual < 25 {
        // awkward small gap: likely dead space under unknown distributions
        score += (25 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits relative to item size (relative waste minimization).
    let waste_ratio = post_residual as f64 / (bin_residual.max(1) as f64);
    score += waste_ratio * 30.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins,
    // but allow new bins when existing residuals are large (poor fits).
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are used only when open bins are bad.
        score += 60.0 + open_bins_count as f64 * 2.0;
        // If mean residual across open bins is small, open bins are fragmented;
        // a fresh bin is more reasonable.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 80.0;
        // If the next item is large, a fresh empty bin is valuable.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
    } else {
        // Prefer bins whose residual can still host the lookahead item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size > 0 && post_residual > 0 {
            score += 10.0; // residual won't fit next item: dead-space risk
        }
    }

    // Slight late-stream consolidation: near the end, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
