        if (post_residual as f64 - nxt).abs() < 0.5 {
            // next item exactly fills this bin afterwards: huge reward
            score -= 200.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportional to how snugly it nests
            score -= 40.0 * (nxt / post_residual as f64);
        } else {
