    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize leaving dead space that nothing in [1,100] could reasonably pair with:
    // small-but-nonzero residuals are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }

    // Lookahead coupling: reward residual that can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global state: many open bins -> prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 6.0 * pressure * (item_size as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual is below mean, it is a
    // "dying" bin; filling it is good. If above mean, slight penalty.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 5.0 * (res - mean_residual) / (bin_capacity as f64);
    }

    // Time horizon: early in stream, keep bins flexible (penalize very low
    // post-residual slightly less relevant); late in stream, pack tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * t * tight;

    // New-bin candidate handling: an empty bin has neutral appeal; discourage
    // opening a new bin when decent fits exist, encourage it when the fit here
    // would be terrible (large dead space).
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size >= 50 {
            score -= 10.0; // large items start fresh bins happily
        }
    }

    // Slight preference for bins whose residual is close to item size (perfect-ish fit)
    let diff = (res - item_size as f64).abs();
    score += 0.15 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
