    // Prefer bins whose residual deviates favorably from the mean:
    // placing into a bin with residual close to the item keeps the
    // remaining pool of large residuals intact.
    let fit_tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * fit_tightness;

    // New-bin candidate handling: an empty bin is a fallback. Make it
    // moderately attractive when open-bin pressure is high or the fit
    // elsewhere is terrible, but not when a decent existing fit exists.
    if bin_residual == bin_capacity {
        score += 150.0 * (1.0 - progress);
        score += 2.0 * open_bins_count as f64;
        // If mean residual is large, existing bins have room: discourage new bin.
        score += 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Strong reward for perfect fit.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // 2-step lookahead: if next item exactly matches post_residual, huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            // Next item still fits: mild reward, scaled by how well it fits after.
            let rem2 = post_residual - next_item_size;
            score -= 18.0 * (1.0 - rem2 as f64 / (bin_capacity as f64));
        } else {
            // Next item won't fit here: penalize bins that leave almost-but-not-quite
            // enough space (wasted near-fit).
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 20.0 {
                score += 14.0 * (1.0 - gap / 20.0);
            }
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.35 * ((bin_residual as f64) - mean_residual);

    // Early in stream, be more conservative about filling bins tightly; later,
    // pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * tightness;

    // New-bin candidate: prefer keeping it closed unless open bins are very full
    // or this is a poor fit situation.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // But if open bins are nearly full on average, opening is fine.
        score -= 0.25 * mean_residual;
        // If many bins can fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
        }
        // If only this (new) bin fits, allow opening.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powi(3);

    // Penalize leaving small unusable dead space (post residual < 10 and not zero).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward perfect closure.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 6.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only
    // when no open bin fits well or many bins are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0;
        score -= 10.0 * (open_bins_count as f64 / (mean_residual / 10.0 + 1.0)).min(5.0);
        score -= 20.0 * progress;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0; // new bin can host a pair
        }
    }

    // Prefer filling bins with larger residuals when mean residual is high (waste reduction).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Mild preference for bins with low residual overall (compact packing).
    score += 0.03 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted residual, non-linearly (quadratic dead-space growth)
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: tighter packing matters more later
    let tightness = 1.0 + 1.5 * progress * progress;
    score *= tightness;

    // Reward filling bins nearly exactly (small post_residual bonus)
    let fill_bonus = (1.0 - norm_pr).powi(3);
    score -= 12.0 * fill_bonus;

    // Penalize leaving residuals that cannot fit the lookahead item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 6.0 * (ns - pr) / cap;
        } else {
            // reward leaving room for the next item, smoothly decaying
            score -= 4.0 * (1.0 - (pr - ns) / cap).max(0.0);
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.15 * open_bins_count as f64;

    // Mean-residual coupling: prefer bins near mean residual (keeps balance)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: prefer opening a fresh bin only when existing fit is bad
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals that are "harmonically clean"
    // (small, or exact multiples of common item classes) are less dead.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize large-but-unusable residuals (dead space in the awkward zone)
    if post_residual > 0 {
        // Awkward zone: residual too small for typical items (1..10) but nonzero
        if post_residual < 10 {
            score += 25.0; // tiny dead space is worst-case waste
        }
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Harmonic class via integer division on post_residual:
    // class = post_residual / 10 gives decade buckets; odd classes (residuals
    // like 15, 25, 35) pair poorly with even-typical items, penalize mildly.
    let decade = post_residual / 10;
    if decade % 2 == 1 && post_residual % 10 != 0 {
        score += 6.0;
    }
    // Residuals that are clean multiples of 10 or 20 pair well with many items
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            if next_post < 10 {
                score -= 20.0; // two-step perfect chain
            } else {
                score -= (next_post as f64).min(15.0) * 0.5;
            }
        } else {
            // next item won't fit here; residual becomes final waste
            score += (post_residual as f64 - frac * 10.0).max(0.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer filling bins when many bins are open (consolidation pressure)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= mean_residual.min(50.0) * 0.1 * progress;

    // New-bin candidate: make empty bins moderately attractive only when
    // no open bin offers a good fit; penalize slightly by default so we
    // reuse bins unless the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        // Harmonic class of the item itself: items that are exact capacity
        // fractions (25, 33, 50, 100...) deserve fresh bins more often
        let harmonic_item = item_size % 25 == 0 || item_size % 50 == 0;
        if harmonic_item {
            score -= 5.0;
        } else {
            score += 10.0 + 20.0 * (1.0 - progress);
        }
    }

    // Mild tie-break: prefer bins with residuals harmonically related to item
    if bin_residual % item_size.max(1) == 0 && bin_residual > item_size {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fill is ideal.
        score -= 40.0;
    }

    // Penalize gaps too small for the next item if it would otherwise fit here.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as u32 {
        score += 8.0 + (next_item_size as f64 - post_residual as f64) * 0.3;
    }
    // Reward gaps that can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size as u32 {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading; with few, mild spread is fine.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.0 * (0.5 + progress);

    // Prefer bins with residuals below the mean (tighter bins get filled first).
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.25;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual < 10;
        if poor_fit || (fitting_bins_count == 0) {
            score -= 20.0;
        } else if fitting_bins_count == 1 {
            score += 35.0; // don't open new bin when a last-chance bin exists
        } else {
            score += 10.0 + mean_residual * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fill (small post_residual), with non-linear penalty
    // on dead space that is too small for any plausible future item.
    let pr = post_residual as f64;
    if pr > 0.0 {
        // dead-space penalty grows super-linearly for small, unusable gaps
        if pr < 10.0 {
            score += (10.0 - pr) * 3.0;
        }
    }

    // 2-step lookahead: reward when the next item exactly fills the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx).abs();
        if diff <= 1.0 {
            // perfect chaining: next item exactly fits this bin
            score -= 60.0;
        } else if diff <= 5.0 {
            score -= 40.0 - diff * 4.0;
        } else if nx <= pr {
            // next item fits but imperfectly: partial reward scaled by fit quality
            score -= 15.0 * (nx / pr);
        } else {
            // next item won't fit here: post residual likely becomes dead space
            score += 10.0 + (nx - pr).min(50.0) * 0.5;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are the
    // "small leftover" bins; filling them is good (consolidate waste).
    if mean_residual > 0.0 {
        let rel = pr / mean_residual;
        if rel < 0.5 {
            score -= 8.0 * (0.5 - rel);
        } else if rel > 1.5 {
            score += 4.0 * (rel - 1.5).min(2.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has pr == capacity. Opening a new
    // bin is only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; make it slightly worse than a good fit but
        // better than leaving large dead space in an existing bin
        score += 5.0;
        if next_item_size > 0 && (next_item_size as f64) >= bin_capacity as f64 * 0.9 {
            score -= 20.0; // big item coming, fresh bin is useful
        }
    }

    // Late-stream pressure: as the stream progresses, avoid opening new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    }

    // Mild preference to use bins when many are open (limit open-bin count)
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by base term,
    // but amplify non-linearly for very tight placements.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that is too small to hold the next item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Residual becomes unusable for the lookahead item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        } else {
            // Residual can still host the next item: reward.
            let snug = (post_residual - next_item_size) as f64;
            score -= 0.35 * snug.max(0.0).min(20.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // When many bins are open, prefer consolidating into existing bins;
    // when few bins are open, opening a new bin is cheaper.
    let crowding = (open_bins_count as f64).ln1p();
    if bin_residual == bin_capacity {
        // New-bin candidate: base attractiveness, penalized when many bins open
        // (we would rather fill existing ones), relaxed early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 8.0 * crowding - 10.0 * (1.0 - progress);
        // If no open bin fits well (this call context: compare via mean residual),
        // opening a new bin is more attractive when mean residual is small.
        score -= 0.3 * mean_residual;
    } else {
        // Existing bin: slight reward for placing into bins with larger residuals
        // (drain the fullest-first effect via residual comparison).
        if (bin_residual as f64) > mean_residual {
            score -= 2.0;
        } else {
            score += 2.0;
        }
    }

    // Prefer filling bins that are already heavily loaded (small residual relative to capacity).
    score += 0.15 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let fit_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: post residual (lower waste preferred)
    let mut score = pr;

    // Smooth polynomial coupling of residual waste with stream progress:
    // late in the stream, tight fits (small post_residual) are rewarded more strongly.
    let tight = 1.0 - pr_norm * pr_norm; // quadratic in residual, ~1 for tight fits
    score -= 12.0 * tight * (progress * progress) * fit_norm;

    // Penalize large dead space non-linearly, amplified by progress
    score += 8.0 * pr_norm * pr_norm * (1.0 + progress);

    // Lookahead coupling: reward bins whose post_residual can host the next item,
    // smoothly weighted by progress
    if next_item_size > 0 {
        let can_fit_next = (pr >= next_item_size as u32) as f64;
        let match_quality = 1.0 - (pr_norm - next_norm).abs();
        score -= 6.0 * can_fit_next * match_quality.max(0.0) * (0.5 + progress);
    }

    // Last-chance bin: strong smooth reward when few fitting bins exist
    let scarcity = 1.0 / fitting_bins_count as f64;
    score -= 10.0 * scarcity * (1.0 - progress * 0.5);

    // Mild penalty for spreading across many open bins, scaled by mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo capacity/4 quarter classes
    let quarter = (bin_capacity / 4).max(1);
    let q_class = (post_residual % quarter) as f64;
    score += 0.35 * q_class; // prefer residuals that sit low in their quarter class

    // Integer-division thresholds: reward near-perfect fills
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= bin_capacity / 20 {
        score -= 25.0;
    } else if post_residual <= bin_capacity / 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward strongly
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > post_residual {
        score += 6.0;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mean residual alignment: prefer bins whose residual is below mean (tighter bins first)
    score += 0.15 * ((post_residual as f64) - mean_residual);

    // Progress coupling: as stream advances, tighten packing (punish waste more)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: only attractive when open bins are all crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / cap;
        score = cap as f64 * (0.55 - 0.5 * crowding.min(1.0));
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small waste ratio), scaled by how much of the bin is consumed.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual - next_item_size < 10 {
            score += 8.0; // next item would create dead space here
        } else {
            score -= 5.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer consolidation.
    score += (open_bins_count as f64) * 0.4;

    // Prefer bins with below-mean residual (tighter bins) to consolidate fragments.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: make it moderately attractive only when open bins would be badly fragmented.
    if bin_residual == bin_capacity {
        score -= 6.0;
        if open_bins_count > 3 {
            score += (open_bins_count as f64) * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core archetype: aggressive 2-step lookahead matching.
    // Reward bins whose post_residual exactly (or nearly) matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect 2-step match: strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportionally to tightness of the follow-up fit.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item does NOT fit: penalize leftover dead space harder.
            score += 0.5 * gap;
        }
    } else {
        // Last item: purely minimize post_residual.
        score -= 10.0;
    }

    // Tight fit reward relative to current item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Penalize post_residual relative to the mean residual of open bins:
    // leaving much more space than average means wasted capacity elsewhere.
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoiding bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would create large dead space. Make the empty bin moderately attractive
    // by default, but beatable by good fits.
    if bin_residual == bin_capacity {
        let new_bin_base = 45.0
            - 0.2 * open_bins_count as f64
            - (post_residual as f64); // post_residual == capacity here
        // If next item is huge and current item small, a fresh bin is fine.
        if next_item_size > 0 && post_residual >= next_item_size {
            score = new_bin_base + 10.0;
        } else {
            score = new_bin_base + 25.0;
        }
    }

    // Slight late-stream conservatism: near the end, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residuals.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize unusable dead space: residual below the minimum item size (1)
    // is fine, but small-but-nonzero residuals (1..=10) are wasted potential.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 && next_item_size <= bin_residual && post_residual < next_item_size {
        // This placement destroys room for the next item; penalize.
        score += 10.0;
    }

    // Prefer bins with residual already below mean (consolidating small leftovers),
    // keep larger-capacity bins flexible for big future items.
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Early in the stream: keep bins open loosely; late: pack greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * (1.0 - progress);

    // Many open bins: encourage closing them out (favor filling existing bins).
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * tight;

    // New-bin candidate: only attractive when nothing fits well or bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fits = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let big_next = if next_item_size > post_residual && next_item_size > 60 { 1.0 } else { 0.0 };
        score = 35.0 + 30.0 * poor_fits + 20.0 * big_next - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: post residual, with non-linear shrinkage of large residuals over time
    let mut score = post * (1.0 + 0.5 * progress * (post / cap).powi(2));

    // Reward near-perfect fits: strong polynomial discount as post_residual -> 0
    score -= 60.0 * (1.0 - post / cap).powi(4);

    // Penalize residuals that are awkwardly large relative to mean residual
    score += 0.3 * (post - mean_residual).abs() * (1.0 + progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: reward if next item fits into post_residual (smooth coupling)
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 {
            score -= 25.0 * (1.0 - gap / cap).powi(3);
        } else {
            score += 0.15 * (-gap) * (0.5 + 0.5 * progress);
        }
    }

    // New-bin candidate: penalize opening a new bin, more so as stream progresses
    if bin_residual == bin_capacity {
        score += 20.0 + 60.0 * progress + 5.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post-residual: classify leftover by capacity fractions
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = c / 4.0;
    let eighth = c / 8.0;

    // Leftovers that can still hold common item classes are valuable; tiny slivers are dead space
    if pr >= quarter {
        score -= 40.0; // roomy leftover, still flexible
    } else if pr >= eighth {
        score -= 15.0;
    } else if pr > 0.0 {
        score += 25.0; // small dead space penalty
    }

    // Dead space relative to next item: leftover below next_item_size is likely wasted
    if next_item_size > 0 {
        if (post_residual as u64) < (next_item_size as u64) && post_residual > 0 {
            score += 35.0;
        } else if (post_residual as u64) >= (next_item_size as u64) {
            score -= 20.0; // this bin can also serve the next item
        }
        // Exact chain: leftover exactly matches next item size
        if post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening new bins when decent open bins exist
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost of a fresh bin
        score = c - item_size as f64; // equivalent to post_residual of empty bin
        score += 30.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count >= 1 {
            score += 50.0; // extra penalty when an open bin could fit
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 40.0; // big items pair well in a fresh bin
        }
    }

    // Progress-based mild pressure: late in stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - pr / c);

    // Mean residual coupling: if open bins are already roomy, discourage more slack
    score += 0.15 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 {
        let unusable = post_residual < min_item.max(next_item_size.min(100));
        if unusable {
            score += post_residual as f64 * 3.0 + 10.0; // dead space penalty
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Lookahead coupling: penalize leaving a gap that exactly fails the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }
    // Reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (0.5 + progress);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 15.0 + pressure * 20.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is fine
        }
        if post_residual == 0 {
            score -= 100.0; // perfect fit into fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + diff);
        // Bonus if next item fits exactly after this placement.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual too small for the next item (dead space).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 10.0;
    }

    // Penalize dead space relative to mean residual of open bins.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals elsewhere are hopeless.
    if bin_residual == bin_capacity {
        score += 60.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    }

    // Mild preference for compacting bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fits snugly.
    let tight = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 12.0 * (-tight * 18.0).exp();

    // Exact fill gets a huge reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the leftover exactly matches the next item, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Lookahead: leftover can still hold the next item -> mild bonus.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 8.0;
    }
    // Penalize leaving dead space smaller than the smallest possible item,
    // scaled by how much of the stream remains (waste matters more early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (1.0 - progress) * 25.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a bin is expensive.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0;
        // More open bins with slack -> less reason to open another.
        score += open_bins_count as f64 * 4.0;
        // If mean residual is large, existing bins have room; penalize new bin more.
        score += mean_residual * 0.6;
        // If no other bin can fit, opening a new bin is necessary: cancel the penalty.
        if fitting_bins_count == 0 {
            score -= 120.0;
        }
        // If next item is large and this item is small, saving residual space is bad;
        // a fresh bin is fine. Slight discount.
        if next_item_size > 0 && next_item_size > item_size * 2 {
            score -= 10.0;
        }
    } else {
        // Prefer filling more-opened (older) bins slightly to consolidate.
        score += mean_residual * 0.05;
        // Penalize bins whose residual is far above item size (poor fit) mildly.
        score += 0.1 * (bin_residual as f64 - item_size as f64);
    }

    // Late in the stream, waste tolerance increases: slightly flatten scores.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: post_residual normalized, shaped by progress
    let prn = pr / cap; // in [0,1]
    let shape = 1.0 + 2.0 * progress * progress; // later in stream => more penalty on waste
    score += 60.0 * prn * prn * shape;

    // Reward near-perfect fits (small post_residual) more aggressively as stream progresses
    score -= 40.0 * (1.0 - prn) * (1.0 - prn) * (0.5 + progress);

    // Dead-space penalty: residual too small for any plausible future item (min size 1)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - prn * 10.0) * (0.5 + progress);
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0 * (1.0 - progress * 0.5);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // penalize blocking next item when waste is large
        score += 10.0 * prn;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild penalty for keeping many open bins with high mean residual
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // New-bin candidate handling: empty bin gets neutral-ish baseline
    if bin_residual == bin_capacity {
        score = 35.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: classify post_residual by capacity fraction buckets (dead-space classes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Penalize awkward residual classes: residuals that are hard to fill later.
    // Perfect-fit class (very small residual) is excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Modulo-style harmonic penalty: residuals near multiples of small item sizes
        // (10, 20, 25, 50) are easier to fill; others are penalized.
        let harmonic_bonus = if post_residual % 10 == 0 { 12.0 }
            else if post_residual % 25 == 0 { 9.0 }
            else if post_residual % 20 == 0 { 7.0 }
            else if post_residual % 5 == 0 { 3.0 }
            else { -6.0 };
        score -= harmonic_bonus;

        // Dead-space zone: residuals in (0, 10) are nearly unusable (min item 10).
        if post_residual < 10 {
            score += 25.0;
        }
        // Mid dead zone: residual slightly above common small sizes wastes capacity.
        if post_residual > 60 {
            score -= 5.0; // roomy bin still flexible
        } else if frac < 0.25 && post_residual >= 10 {
            score += 8.0; // tight awkward remainder
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current fit is poor and lookahead is large.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = (post_residual as i32) < 15 || (post_residual as i32) > 55;
        let big_next = next_item_size >= 40;
        if poor_fit && big_next {
            score -= 30.0;
        } else {
            score += 15.0;
        }
    }

    // Lookahead coupling: if next item exactly matches a harmonic class of post_residual,
    // reward heavily (perfect chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual % next_item_size.max(1) == 0 {
        score -= 10.0;
    }

    // Progress-based nudge: late in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0;

    // Slightly prefer bins below mean residual (balance load across open bins).
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty scaled by how "wasted" the residual is relative to typical item sizes.
    if post_residual > 0 && post_residual < item_size {
        score += 0.5 * (10.0 - post_residual as f64).max(0.0);
    }

    // Open bins pressure: discourage spreading across many bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Last-chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Prefer bins with lower residual among fitting bins (tight packing).
    score += 0.1 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (small post residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score += (post_residual as f64).powi(2) * 0.05;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item can also fit here afterwards: chain-friendly.
            let gap = (post_residual - next_item_size) as f64;
            score -= (50.0 - gap.min(50.0)) * 2.0;
        } else {
            // Next item cannot fit in the remainder: penalize dead space.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Reward filling bins that are relatively empty vs mean residual (avoid fragmentation).
    if (bin_residual as f64) > mean_residual {
        score -= 20.0;
    } else {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 250.0;
        if post_residual as f64 > mean_residual * 1.2 && next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 200.0;
        }
    }

    // Late in stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Perfect or near-perfect fill is highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item can fit into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_tightness = next_item_size as f64 / post_residual as f64;
        score -= 14.0 * chain_tightness;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Penalize leaving dead space that the next item cannot use.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 10.0 * (10.0 - dead) / 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty for hogging a bin when alternatives exist, scaled by slack.
        score += 2.0 * (post_residual as f64) / bin_capacity as f64;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing bins fit poorly (large post_residual) or few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let open_penalty = 8.0 * (1.0 - progress) + 20.0 * progress;
        score += open_penalty + 3.0 * (open_bins_count as f64).ln().max(0.0);
        // If the current item is large and mean residual is small, a new bin is reasonable.
        if item_size as f64 > 0.6 * bin_capacity as f64 && mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Global state coupling: when mean residual is low, conserve space aggressively.
    let residual_pressure = mean_residual / bin_capacity as f64;
    score += 6.0 * (1.0 - residual_pressure) * (post_residual as f64 / bin_capacity as f64);

    // Late in the stream, avoid fragmenting residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimal post residual, with non-linear (quadratic) dead-space penalty
    let mut score = post + 1.5 * (post / cap) * (post / cap) * cap;

    // Smooth coupling: as stream progresses, tighter fits matter more
    score *= 1.0 + 0.6 * progress * (1.0 - post / cap);

    // Penalize near-full bins slightly less as mean residual across bins grows
    score -= 0.3 * mean_residual * (post / cap);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a bin unless the item is large
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln_1p();
        score += 10.0 + 15.0 * openness + 0.2 * (cap - item);
        // If next item is small, a fresh bin is more attractive (smooth lookahead coupling)
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            score -= 0.15 * (cap - nxt) * (0.5 + 0.5 * progress);
        }
    } else {
        // Reward lookahead synergy: residual left should ideally fit next item
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let gap = (post - nxt).abs();
            score += 0.1 * gap;
            if post >= nxt {
                score -= 4.0;
            }
        }
        // Mild reward for using bins that are already quite full
        score -= 0.1 * (cap - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base waste scaling: dead space below the smallest plausible item is nearly worthless.
    if post_residual < 10 {
        score -= 40.0; // near-perfect fit reward
    } else {
        // Harmonic decay: residual value drops as it shrinks toward unusability
        let frac = post_residual as f64 / cap;
        score -= 30.0 * (1.0 - frac) * (1.0 - frac);
    }

    // Modulo class of post_residual relative to typical item granularity
    let res_mod = post_residual % 10;
    if res_mod == 0 {
        score -= 6.0; // residual divisible by 10 likely reusable
    } else if res_mod >= 7 {
        score += 4.0; // awkward sliver class
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 10.0 + 0.3 * slack_after_next as f64;
    } else if next_item_size > post_residual {
        score += 0.15 * next_item_size as f64 * (post_residual as f64 / cap);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is attractive only for large items or when few bins fit the item
        let large_item = (item_size as f64 / cap) > 0.6;
        let mut new_bin_score = cap * 0.55;
        if large_item { new_bin_score -= 15.0; }
        if fitting_bins_count == 0 { new_bin_score -= 60.0; }
        new_bin_score += 10.0 * progress;
        if open_bins_count == 0 { new_bin_score -= 50.0; }
        // compare against mean residual: if open bins are nearly full, new bin is fine
        if mean_residual < 20.0 { new_bin_score -= 8.0; }
        score = new_bin_score;
    }

    // Mild penalty for proliferating bins late in the stream
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that is too small to ever hold a typical item is pure waste.
    let min_item = 1.0f64;
    let dead = if post_residual > 0 && (post_residual as f64) < min_item.max(10.0) {
        1000.0
    } else {
        0.0
    };
    score += dead;

    // Non-linear dead-space curve: small post-residuals below ~15 are risky,
    // mid residuals are fine, large residuals mean the bin was underfilled.
    let pr = post_residual as f64;
    if pr > 0.0 && pr <= 15.0 {
        score += (15.0 - pr) * 8.0; // the tighter the leftover, the worse
    }
    if pr > 70.0 {
        score += (pr - 70.0) * 2.0; // discourage leaving a big empty bin half used
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening yet another one.
    let pressure = (open_bins_count as f64).ln() * 15.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins pressure,
        // but relax pressure late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += pressure * (1.0 - 0.3 * progress) + 40.0;
    } else {
        score -= pressure * 0.5;
    }

    // Lookahead coupling: if next item fits in the post-residual, reward;
    // if next item almost fits (small miss), penalize slightly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 25.0;
        } else if nx <= pr + 5.0 {
            score += 15.0;
        }
    }

    // Slight preference for bins tighter than the mean residual (best-fit flavor)
    score += (pr - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact chain fits (item + next item fill bin)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect 2-item chain: item + next item exactly fill bin
        } else if next_item_size < post_residual {
            // next item fits too: reward tightness of the two-item combo
            let combo_leftover = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - combo_leftover / bin_capacity as f64);
            // extra bonus if the combo leftover is very small (near-perfect double fit)
            if combo_leftover <= 5.0 {
                score -= 15.0;
            }
        } else {
            // next item does NOT fit after this placement: penalize proportionally
            // to how much dead space this creates relative to the next item
            let waste = (post_residual as f64) / (next_item_size as f64);
            score += 8.0 * waste.min(3.0);
        }
    }

    // Relative-to-mean-residual coupling: prefer bins whose post_residual is close to
    // the mean residual (keeps open bins homogeneous, easier to pack later items)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Tight fit reward: penalize large post_residual after placement (dead space)
    score += 0.3 * post_residual as f64 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing bins would leave large unusable residue
    if bin_residual == bin_capacity {
        // neutral baseline slightly above a good fit so it's used only when fits are bad
        score += 12.0;
        // if next item is large relative to a fresh bin, opening new bin preserves room
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 6.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer bins with smaller residual before placement (best-fit flavor)
    score += 0.05 * bin_residual as f64;

    // Slight penalty when many bins are open (encourage consolidation)
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin: attractive only when fits are scarce or item is huge.
        let scarcity = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let tight = (item_size as f64 / bin_capacity as f64) > 0.8;
        let open_pressure = (open_bins_count as f64 / 20.0).min(1.0);
        // Reward new bin when it's scarce or item is tight; penalize otherwise.
        score -= 60.0 * (scarcity + if tight { 0.6 } else { 0.0 }) - 25.0 * open_pressure;
        // Late in stream, prefer filling existing bins.
        score += 40.0 * progress;
        // If lookahead also fits nicely in a fresh bin, mild bonus.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 8.0;
        }
        return score;
    }

    // Reward near-perfect fits (small post_residual is already low score; amplify).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * frac * frac; // quadratic penalty on wasted space

    // Exact or near-exact closure bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post-residual, this is a great bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            score += 5.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer closing bins.
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Prefer bins with residuals below the mean (consolidate small holes).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Early in the stream, be picky about wasted space; later, just pack.
    score *= 1.0 - 0.25 * progress;

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: waste left after placement, softly compressed
    let mut score = post.powf(1.3);

    // Non-linear coupling: waste is more tolerable early, penalized later
    let tightness = 1.0 + 1.2 * progress * progress;
    score *= tightness;

    // Reward near-perfect fits via smooth saturating term
    let fit_quality = 1.0 - (post / cap).powf(2.0);
    score -= 8.0 * fit_quality * fit_quality;

    // Penalize residuals that cannot fit the lookahead item (smooth valley)
    if nxt > 0.0 && post >= nxt {
        let slack = (post - nxt) / cap;
        score -= 4.0 * (-slack * slack * 20.0).exp();
    } else if nxt > 0.0 {
        score += 3.0 * (1.0 - (post / nxt.max(1.0)).min(1.0));
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: prefer it when open bins are already tight/fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - post / cap).abs();
        score += 6.0 - 3.0 * (open_bins_count as f64).ln().max(0.0) / 3.0;
        score += 4.0 * fragmentation;
    } else {
        // Mild penalty for spreading across many bins when residuals are high
        score += 0.5 * (mean_residual / cap) * progress;
    }

    // Smooth polynomial interaction of item size with progress
    let x = item / cap;
    score -= 3.0 * x * (1.0 - x) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Integer-division thresholds on post_residual (harmonic bands).
    let band = post_residual / 10; // 0..=10 bands
    let band_f = band as f64;

    // Reward tight fits: post_residual near 0 or exactly reusable sizes.
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 25.0; // near-perfect, small dead space
    } else {
        // Penalize dead space that falls in "unusable" harmonic classes.
        // Modulo arithmetic: residuals of the form C mod k for small k are reusable.
        let reusable = (post_residual % 25 == 0) || (post_residual % 20 == 0) || (post_residual % 10 == 0);
        if reusable {
            score -= 8.0 + band_f;
        } else {
            score += 10.0 + (10.0 - band_f).abs() * 0.5;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            if next_post <= 10 {
                score -= 15.0;
            } else if next_post % 10 == 0 {
                score -= 6.0;
            } else {
                score += next_post as f64 * 0.15;
            }
        } else {
            // next item cannot use this residual: penalize proportionally to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        score += 35.0; // default penalty for opening a new bin
        // But if current bin would leave bad dead space, new bin is attractive:
        let bad_fit = post_residual > 10 && post_residual < 20 && next_item_size > post_residual;
        if bad_fit {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // Few open bins relative to stream: opening is cheaper early.
        score -= (open_bins_count as f64).min(10.0);
    }

    // Mild preference for bins below mean residual (spread load evenly).
    score += (mean_residual - bin_residual as f64) * 0.08;

    // Small tie-breaker noise-free harmonic jitter based on residual class.
    let class = (post_residual % 7) as f64;
    score += class * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (<= 10) are pure waste; punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small-but-usable gaps (< 25) are risky: only next items <= gap fit.
    if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Reward tight fits (best-fit core), scaled by how snug the item is.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; encourage
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 4.0 * progress);

    // New-bin candidate (empty bin): make it attractive only when this bin's
    // fit would leave a bad gap or the fit is loose.
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual < 10 { 80.0 } else if post_residual < 25 { 30.0 } else { 0.0 };
        score += 10.0 + gap_penalty - 20.0 * (1.0 - tightness);
        // Early in the stream, opening fresh bins is cheaper.
        score -= 15.0 * (1.0 - progress);
        // If lookahead item fits the leftover of a fresh bin, opening is fine.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
    } else if next_item_size > 0 && next_item_size as f64 <= post_residual as f64 {
        // Keeping room for the lookahead item is valuable.
        score -= 10.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // This bin's leftover won't host the next item; mild penalty.
        score += 5.0;
    }

    // Slight preference for bins below mean residual (rebalance toward
    // fuller bins, keeping emptier bins flexible).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead: reward post_residual that exactly matches next_item_size ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        // Perfect match: next item exactly fills this bin -> huge reward.
        if diff < 0.5 {
            score -= 60.0;
        } else if pr >= nxt {
            // Next item fits here too: mild reward scaled by closeness of fit.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item will NOT fit: penalize leaving awkward small-but-not-matching gaps,
            // but small leftovers (pr < 10) are nearly dead space anyway -> small penalty.
            let dead = if pr < 10.0 { 0.3 } else { 1.0 };
            score += dead * (nxt - pr).min(40.0) * (0.5 + progress);
        }
    } else {
        // Last item: prefer minimal leftover.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // ---- Relative-to-mean coupling: bins with residual far below mean are "tight" ----
    // Placing into a tight bin (small residual) is good; discourage dipping into large-residual bins
    // when mean is small (bins are mostly full already).
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = res / mean_residual;
        // Favor bins tighter than average.
        score -= 8.0 * (1.0 - rel).clamp(-2.0, 1.0);
    }

    // ---- Last-chance bonus: this is the only bin that fits; avoid opening a new bin ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // Strong reward unless the fit is terrible (huge dead space relative to item).
        let waste = post_residual as f64 / bin_capacity as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        if item_frac > 0.0 && waste / item_frac.max(0.1) < 1.5 {
            score -= 45.0;
        } else {
            score -= 12.0;
        }
    }

    // ---- New-bin candidate handling: keep it attractive only when no open bin fits well ----
    if bin_residual == bin_capacity {
        // Base neutral cost of opening a new bin; grows slightly with number of open bins
        // (encourage filling existing bins when the stream is deep).
        score += 30.0 + 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        // But if the item is large and no good fit exists, opening a bin is fine:
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 25.0;
        }
        // Lookahead: opening a fresh bin guarantees next item fits too.
        if next_item_size > 0 && next_item_size as f64 / bin_capacity as f64 > 0.5 {
            score -= 15.0;
        }
    }

    // ---- Tight-fit preference: reward placements that nearly fill the bin ----
    let fill = item_size as f64 / res.max(1.0);
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Perfect two-item packing bonus.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 30.0 - 10.0 * pressure;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 / 2 {
            score -= 5.0;
        }
    }

    // Time horizon: early in stream, consolidation matters more; late, avoid fragmentation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64 / bin_capacity as f64) * 6.0;

    // Prefer bins below mean residual (keeps residual distribution balanced).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: post-residual, with a non-linear penalty on large dead space.
    let mut score = pr + 12.0 * fit_norm * fit_norm * cap;

    // Smooth coupling: late in the stream, prefer tight fits more aggressively.
    let tightness = 1.0 - fit_norm;
    score -= 20.0 * progress * tightness * tightness;

    // Reward filling bins close to capacity via smooth saturation term.
    score -= 15.0 * (1.0 - (-fit_norm * 4.0).exp());

    // Last-chance bin: strong reward to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Crowding: many open bins -> discourage leaving many nearly-empty bins.
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
    score += 10.0 * open_norm * fit_norm;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = (pr - next_item_size as f64) / cap;
        score -= 12.0 * (1.0 - gap * gap);
    }

    // Mean-residual coupling: bins far from the mean residual get a mild pull.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: residuals that are "usable" classes
    // (multiples of common item sizes) are less costly than odd dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class bonus: post_residual divisible by common divisors (e.g. 10, 20, 25, 50)
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 2.5; }
        if post_residual % 50 == 0 { score -= 2.0; }
    } else {
        // Perfect fill is ideal
        score -= 40.0;
    }

    // Tight fit reward: item occupies most of the residual
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Lookahead: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // perfect chained fit
        } else if next_item_size < post_residual {
            // next item fits: leftover class after chaining matters
            let chained = post_residual - next_item_size;
            if chained % 10 == 0 { score -= 8.0; }
            score -= 5.0 * (chained as f64 / cap);
        } else {
            // next item cannot use this bin's leftover: penalize small dead space more
            if pr > 0.0 && pr < 10.0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // no open bin offers a decent fit and mean residual is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / cap).abs()
        } else { 0.0 };
        // Penalize new bins generally; relax slightly late in stream with fragmented bins
        score += 30.0 - 10.0 * fragmentation - 5.0 * progress;
        // Very large items prefer a fresh bin to avoid stranding small leftovers
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    // Mild preference for filling bins with smaller residuals (best-fit flavor)
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item are "dead". Penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to the current residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // fit here would leave a bad gap. Otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        score += 55.0 * (1.0 - pressure);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0; // new bin can also host the next item
        }
        if fitting_bins_count <= 2 {
            score -= 20.0; // few alternatives -> new bin is fine
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: reward bins whose leftover can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Mild alignment with global mean residual: bins far from the mean
    // residual are less predictable; prefer bins close to the mean.
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    // Late in the stream, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills (small dead space is disproportionately bad).
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 20.0 * (1.0 - post_residual as f64 / 15.0);
    }

    // Aggressive 2-step lookahead: exact match of next item into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // perfect chain: this bin will be closed next step
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / 50.0).max(0.0);
        } else {
            // Next item cannot follow here; penalize slightly more if gap is large.
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 * (gap / 60.0).min(1.0);
        }
    }

    // Prefer bins tighter than the mean residual (good fits), avoid loose bins.
    score += 0.6 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits
    // well (large post_residual relative to capacity elsewhere).
    if bin_residual == bin_capacity {
        // Baseline new-bin score: slightly worse than a good existing fit.
        score = bin_capacity as f64 * 0.55;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        } else if next_item_size > 0 && next_item_size >= item_size {
            // If next item is large, a fresh bin may chain better.
            score -= 20.0;
        }
        // Late in the stream, discourage opening new bins more strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild pressure to fill already-open bins when many are open.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space that is too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the leftover; mild penalty proportional to waste
            score += 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling bins when many bins are open (reduce fragmentation)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins with residual far below mean residual (consolidate fullness)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate handling: make an empty bin moderately attractive only
    // when no good fit exists; penalize opening new bins early in the stream
    if bin_residual == bin_capacity {
        let base_penalty = 8.0 + 20.0 * (1.0 - progress);
        score += base_penalty;
        // If the item is large relative to capacity, opening a fresh bin is more reasonable
        score -= 0.15 * item_size as f64;
        // If many bins are open and mean residual is low, opening a new bin is worse
        score += 0.2 * open_bins_count as f64;
        // If mean residual is high (lots of slack around), prefer existing bins
        score += 0.25 * mean_residual;
    }

    // Small time-dependent jitter-free calibration: later in the stream,
    // be more aggressive about filling existing bins tightly
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Base: reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - post / cap; // 0..1, higher = tighter fit
    score -= 20.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible item (1..100).
    // Smoothly ramp penalty as post_residual drops below the minimum item size region.
    let dead = (1.0 - post / 10.0).max(0.0);
    score += 15.0 * dead * dead;

    // Non-linear coupling with stream progress: early on, keep bins flexible
    // (prefer larger post_residual slightly); late, pack tightly.
    score += (1.0 - progress) * post * 0.05;
    score -= progress * tightness * 10.0;

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            score += 4.0 * ((nxt - post) / cap);
        }
    }

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Default cost of opening a new bin; overridden if open bins are bad fits.
        score = cap * 0.9 + 20.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 1000.0; // must open
        } else if fitting_bins_count == 1 {
            // last chance exists: opening new bin is worse
            score += 40.0;
        } else {
            // several bins fit: prefer reusing unless all residuals are large
            score += (mean_residual / cap) * 10.0;
        }
    }

    // Mild diversity pressure: many open bins with large mean residual -> prefer reuse.
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr as f64;

    // Perfect fit: overwhelming reward
    if pr == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling (k=2): does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if pr > 0 && pr < next_item_size {
            // Dead space: next item cannot use what's left; penalize more as stream progresses
            let waste = (next_item_size - pr) as f64;
            score += 4.0 + waste * 0.5 * (0.5 + t);
        } else if pr >= next_item_size {
            // Residual remains usable for the lookahead item
            score -= 2.0 + (next_item_size as f64) * 0.02;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Opening a new bin while others fit: penalize, scaled by number of alternatives
            score += 20.0 + 5.0 * fitting_bins_count as f64;
        } else {
            // No alternative: new bin is mandatory, mild neutral bonus
            score -= 1.0;
        }
    }

    // Harmonic class logic: residuals that are multiples of small common sizes
    // (10, 20, ...) tend to combine with future items; reward pr % 10 == 0 classes
    let harmonic = (pr % 10) as f64;
    score -= (10.0 - harmonic) * 0.05;

    // Integer-division threshold: residual classes by quarter-capacity
    let quarter = bin_capacity / 4;
    match pr / quarter {
        0 => score -= 3.0,              // nearly full bin: excellent
        1 => score -= 1.0,              // 3/4 used: good
        2 => {}                         // half: neutral
        _ => score += 1.0,              // mostly empty: mild penalty
    }

    // Slight global preference for fuller bins relative to capacity
    score += (cap - pr as f64) * 0.01;

    // Tie-break toward bins close to the current mean residual (keeps bin profile balanced)
    score += ((pr as f64) - mean_residual).abs() * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny gap = wasted space
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit
    }

    // Prefer bins whose gap matches the lookahead item size.
    if next_item_size > 0 && post_residual > 0 {
        let gap_diff = (post_residual as f64 - next_item_size as f64).abs();
        score += gap_diff * 0.8;
        if post_residual == next_item_size as u32 {
            score -= 30.0;
        }
    }

    // Open-bins pressure: discourage spreading across many bins when few fit.
    let fit_ratio = if open_bins_count > 0 {
        fitting_bins_count as f64 / open_bins_count as f64
    } else { 1.0 };
    score -= fit_ratio * 15.0;
    score += open_bins_count as f64 * 0.6;

    // Last-chance bonus: this is the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Dead-space coupling: penalize leaving gaps smaller than the mean item size.
    let gap_usability = post_residual as f64 / 80.0;
    score += (1.0 - gap_usability.min(1.0)) * 20.0 * (post_residual > 0) as i32 as f64;

    // Mild preference for tighter bins (small residual before placement).
    score += bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small dead space (unusable slivers) non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual (chained packing).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if nx <= pr {
            // Chain bonus proportional to how snugly the next item fits.
            let slack_after_next = pr - nx;
            score -= 40.0 - slack_after_next.min(40.0);
            if slack_after_next == 0.0 {
                score -= 200.0; // exact 2-item chain completion
            }
        } else {
            // Dead-end residual: penalize proportionally to how much the next item overflows.
            let overflow = nx - pr;
            score += overflow.min(80.0) * 0.8;
        }
    }

    // Compare residual against mean residual: prefer bins that become tighter than average.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when it creates a clean large residual
    // for a large next item, or when open bins are numerous/fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
        let fragmentation = mean_residual / bin_capacity as f64;
        let new_bin_bonus = 30.0
            + (next_item_size as f64) * 0.6
            + fragmentation * 50.0
            + progress * 20.0
            + (open_bins_count as f64) * 2.0;
        score = 100.0 - new_bin_bonus + post_residual as f64 * 0.3;
        // Discard new bin if current placement would be a perfect fit elsewhere.
        if post_residual == bin_capacity - item_size && item_size > 0 && bin_residual - item_size == 0 {
            score += 500.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
