    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Global pressure: many open bins -> consolidate harder; few bins -> be picky
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += mean_residual * 0.08 * (1.0 - pressure);
    score -= pressure * 6.0;

    // New-bin candidate handling: only attractive when item is large or fits are poor
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let poor_fit = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score -= 5.0 + large_item * 30.0 * (1.0 - pressure) + poor_fit * 10.0;
        // Late in stream, avoid spawning bins for small items
        let progress = step_index as f64 / total_items.max(1) as f64;
