    // Penalize residual that is too small to ever be useful (dead space),
    // with a smooth ramp below the smallest plausible item.
    let dead = (12.0 - post_residual as f64).max(0.0) / 12.0;
    score += 15.0 * dead * dead;

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_fit = (next_item_size as f64 / bin_capacity as f64).powi(2);
        score -= 8.0 * slack_fit * (1.0 + progress);
    } else if next_item_size > 0 {
        // Smooth penalty proportional to how badly the next item misses.
        let miss = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        score += 6.0 * miss * miss;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (0.5 + progress);
    }

    // Mild penalty when many bins are open and this bin is already roomy:
    // prefer filling existing bins rather than spreading across many.
    let roominess = post_residual as f64 / bin_capacity as f64;
    score += 3.0 * roominess * (open_bins_count as f64).sqrt() * 0.2;

    // New-bin candidate handling: an empty bin is attractive early, but as the
    // stream progresses we increasingly prefer squeezing into open bins.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) * (1.0 - progress) + 4.0;
        // If other bins fit and mean residual is small (bins are tight), discourage new bin.
        if fitting_bins_count > 0 {
            score += (mean_residual / bin_capacity as f64).max(0.0) * 8.0;
        }
    }

    // Deviation from mean residual: prefer bins that bring residual closer to the mean
    // (balances the pool of open bins smoothly).
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic-class reward: residual in "usable" classes (multiples of 10, or >= 50)
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit is excellent
    } else {
        let class = pr % 10;
        if class == 0 {
            score -= 12.0;
        } else if pr >= 50 {
            score -= 6.0;
        } else if class >= 5 {
            score += 3.0;
        } else {
            score += 6.0; // tiny unusable sliver
        }
        // dead-space penalty grows for small residuals below typical item sizes
        if pr < 20 {
            score += (20 - pr) as f64 * 1.5;
        }
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // harmonic match classes: exact / near / divisible
            if pr % next_item_size == 0 {
                score -= 15.0;
            } else if pr - next_item_size < 10 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap - (pr as f64) * 0.5; // baseline ~ capacity
        // prefer new bin early when open bins are already fragmented
        score -= progress * 20.0;
        score += (open_bins_count as f64).sqrt() * 4.0;
        score += (mean_residual / cap).max(0.0) * 30.0;
    }

    // Tie-break with mean residual coupling: prefer filling bins below mean residual
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1..100 range)
    // are effectively unusable; penalize them heavily.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 50.0; // perfect fill
    } else if post_residual <= 10 {
        // small dead space: likely unusable later
        score += 8.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 6.0 * fill_ratio;

    // Reward exact fit of bin_residual.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins are already open,
        // and to how much slack would remain after placement.
        score += 10.0 + 4.0 * open_pressure + 0.3 * post_residual as f64;
    } else {
        score -= 2.0 * open_pressure.min(3.0);
    }

    // Lookahead: if next item fits the post-residual, this placement is extra valuable.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 7.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // post-residual likely dead for the known next item
        score += 3.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates from mean in a way
    // that leaves balanced slack across bins.
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Late in the stream: consolidate harder, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 6.0 * progress;
    } else {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64));
        // Slight over-residual matching (next item fits snugly) preferred over under.
        if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 25.0;
        }
        // Penalize leaving dead space that neither the next item nor typical items can use.
        if post_residual < next_item_size && post_residual < 10 {
            score += 15.0;
        }
    }

    // Prefer bins with residuals below mean (compact fills), penalize near-empty bin usage.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0 * (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    }

    // Last-chance bin: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Discard opening a new bin when reasonable fits exist: new bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 55.0;
        // But allow new bin if existing fits would leave tiny unusable gaps.
        if fitting_bins_count > 0 && post_residual < 10 {
            score -= 40.0;
        }
    }

    // Small bonus for tight fits overall (low post residual relative to capacity).
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Penalize dead space: residual too small for the smallest plausible item (1..100 unknown, use item_size as proxy).
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let nxt_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * nxt_fit;
        } else {
            // next item won't fit here; slight penalty proportional to leftover waste potential
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // New-bin candidate handling: bin_residual == bin_capacity means empty bin.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 55.0;
        // Last-chance bin: opening new bin is justified.
        if fitting_bins_count == 1 && bin_capacity > item_size {
            score -= 70.0;
        }
        // Many open bins with slack: discourage new bins.
        if mean_residual > item_size as f64 {
            score += 20.0;
        }
        // Early stream: keep options open, mildly discourage proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
        // Large item relative to capacity: fresh bin is attractive.
        score -= 25.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Prefer filling bins that deviate below the mean residual (balance avoidance of many half-empty bins).
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // If many bins can fit the item, mildly favor tighter ones via fitting pressure.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count.min(10) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let mut score = pr * (1.0 + 0.02 * pr / cap);

    // Dead-space penalty: residuals too small for likely future items are wasted.
    // Smooth non-linear term: residual below next item size is heavily penalized.
    let ni = next_item_size as f64;
    if ni > 0.0 {
        let gap = ni - pr;
        if gap > 0.0 {
            let frac = gap / cap;
            score += 8.0 * frac * frac * (1.0 + progress);
        } else {
            // Reward bins that can also absorb the next item.
            score -= 4.0 * (pr / cap) * (1.0 - pr / cap);
        }
    }

    // Coupling with stream progress: early on, keep bins flexible (penalize low residual);
    // late in the stream, packing tightly matters more.
    let flex = pr / cap;
    score += 6.0 * flex * (1.0 - progress) * (1.0 - progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - flex);
    } else {
        // Slight penalty when many alternatives exist, to keep best-fit dominance clear.
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer new bin when open bins would leave very tight fits or stream is early.
        let tightness = 1.0 - (pr / cap); // = item fraction for new bin
        score += 5.0 * (1.0 - progress) + 3.0 * tightness * tightness;
        // Discourage opening new bins when open bins count is already large and fits are good.
        score += 0.3 * open_bins_count as f64;
    }

    // Mild regularization toward mean residual: avoid extreme fragmentation outliers.
    score += 0.1 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into 10-wide classes.
    // Small post_residual classes are strongly favored (tight packing).
    let class = (post_residual / 10) as f64;
    score += class * class * 0.35;

    // Perfect / near-perfect fits get a big discount.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item
    // (post_residual class compatible with next_item_size).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * (next_item_size as f64);
        // Harmonic bonus if post_residual - next_item_size lands in a good class (<=10)
        if post_residual - next_item_size <= 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // Leftover unusable by next item: mild penalty scaled by waste class
        score += 0.15 * class;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize bins that are already relatively full vs mean residual (keep
    // large-residual bins flexible), reward using the emptiest bins.
    let diff = mean_residual - bin_residual as f64;
    score += 0.10 * diff;

    // New-bin candidate handling: an empty bin has a high base score; only
    // choose it when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheaper; later, discourage it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If many bins are open and mean residual is small, discourage new bin.
        score += 0.05 * (open_bins_count as f64);
        // But if the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 25.0;
        }
        // If the next item is also large, opening a fresh bin now is good.
        if next_item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Mild preference to fill bins that are already more than half used
    // (harmonic class of bin_residual).
    let fill_class = (bin_residual / 10) as f64;
    score -= 0.05 * (10.0 - fill_class.min(10.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // minimum item (1..100 domain, but small gaps < ~15 are hard to fill)
    // are pure waste. Penalize them quadratically.
    let dead_threshold = 15u32;
    if post_residual > 0 && post_residual < dead_threshold {
        let gap = (dead_threshold - post_residual) as f64;
        score += gap * gap * 2.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < item_size {
        // Gap too small even for the current item class -> dead space.
        score += 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // next item won't fit here; slightly penalize leaving a gap
            // that nothing will use.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; favor
    // filling existing bins more tightly.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "nearly full" bin — placing here consolidates waste.
    let residual = post_residual as f64;
    if residual < mean_residual {
        score -= (mean_residual - residual) * 0.4;
    }

    // New-bin candidate: an empty bin should only win when no open bin
    // offers a decent fit. Make the empty bin moderately attractive
    // (large post_residual = flexibility) but not dominant over tight fits.
    if bin_residual == bin_capacity {
        score -= 8.0;
        // If many bins are already open, opening yet another one is costly.
        score += open_bins_count as f64 * 1.2;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild reward for larger items filling larger gaps.
    score -= (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 50.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        if post_residual as i64 == next_item_size as i64 {
            score -= 300.0;
        }
        // Penalize dead space that next item cannot use
        if post_residual < next_item_size {
            score += 40.0;
        }
    }

    // Relative to mean residual: prefer bins with larger residual (roomier)
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins exist that fit reasonably
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
    }

    // Mild late-stream consolidation pressure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.3 * progress * post_residual as f64 / open_bins_count.max(1) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: small post_residual that is awkward (< 10) is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward;
    // if next item cannot fit at all, mild penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post_residual as f64 {
            let follow_tight = nxt / post_residual as f64;
            score -= 20.0 * follow_tight;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only open bin that can fit the item,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: brand-new empty bin gets a neutral baseline.
    // Prefer it only when existing fits are very loose or no good fit exists.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64; // post_residual of fresh bin
        score -= 5.0 * (1.0 - item_size as f64 / cap); // slightly better for big items
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open
        } else {
            // discourage opening when a decent fit exists
            let best_possible = mean_residual.max(0.0);
            if best_possible - item_size as f64 <= 10.0 {
                score += 40.0; // tight fit exists elsewhere -> avoid new bin
            }
        }
    }

    // Global pressure: when many bins are open with scattered residuals,
    // prefer consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a "small leftover" bin — good to consume now.
    let dev = mean_residual - bin_residual as f64;
    score -= 3.0 * dev.max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_ratio = item_size as f64 / cap;
    let post_norm = pr / cap;

    // Base: post residual (tighter fit -> lower score)
    let mut score = pr as f64;

    // Smooth non-linear reward for tight fits (low post_residual)
    score -= 30.0 * (1.0 - post_norm).powi(4);

    // Penalty for awkward dead space: mid-range residuals are least useful
    let mid = (post_norm - 0.5).abs();
    score += 25.0 * mid * (1.0 - mid);

    // Stream progress coupling: later in the stream, prefer tighter packing
    score -= 20.0 * progress * (1.0 - post_norm).powi(2);

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 15.0 * (1.0 - (pr - nx) / cap).powi(2);
        } else {
            score += 8.0 * ((nx - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count <= 1 {
        score -= 40.0;
    }

    // Many open bins: prefer filling existing ones over spreading
    let ob = open_bins_count as f64;
    score += 3.0 * (ob / (ob + 5.0)) * post_norm;

    // Mean residual coupling: prefer bins deviating below mean residual (fill the emptier ones)
    score += 5.0 * ((bin_residual as f64 - mean_residual) / cap);

    // New-bin candidate penalty: discourage opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - fit_ratio) * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: multiples of 25 leave room for
    // "quarter-class" items; near-multiples create dead space.
    let quarter = bin_capacity as f64 / 4.0;
    let class = (post_residual as f64 % quarter) / quarter; // in [0,1)
    let harmonic_bonus = if class < 0.05 {
        -18.0 // residual sits exactly on a quarter mark: excellent
    } else if class > 0.9 {
        -10.0 // close to a quarter mark
    } else {
        class * 14.0 // off-class residuals penalized proportionally
    };
    score += harmonic_bonus;

    // Integer-division threshold: post_residual divisible by small divisors
    // means future items of that class tile perfectly.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        else if post_residual % 5 == 0 { score -= 4.0; }
        if post_residual < 10 { score += 25.0; } // dead sliver
    } else {
        score -= 30.0; // perfect closure
    }

    // Lookahead coupling: can next item exactly fill post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // guaranteed perfect fill next step
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= (1.0 - gap / bin_capacity as f64) * 12.0;
        } else {
            // next item cannot use this bin's residual anyway; slight penalty
            // for wasting a good residual on a mismatched pairing
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: only attractive when current fit is very poor and
    // stream is early enough to amortize the new bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = post_residual as f64 > quarter * 1.5;
        if poor_fit && progress < 0.7 {
            score -= 16.0 + 10.0 * (1.0 - progress);
        } else {
            score += 30.0; // keep consolidating into open bins
        }
    }

    // Prefer filling bins that are already relatively full (tight packing).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fullness * 10.0;

    // Mild pressure against bin sprawl when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Align with global mean residual: bins far below mean residual are
    // already tight; bins far above are wasteful targets.
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Strong penalty for mid-range dead space that likely can't be filled later.
    if post_residual > 0 && post_residual < 25 {
        score += 12.0;
    }

    // Reward tight fits (near-zero post residual).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow and stream progresses.
        score += 30.0 + 3.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        // Reward using existing bins, scaled by open-bin pressure.
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 15.0;
    }
    // Penalize blocking the next item badly.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && next_item_size <= bin_capacity {
        score += 8.0;
    }

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    score += ((bin_residual as f64) - (item_size as f64) - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 150.0; // next item will perfectly fill this bin
        } else if diff <= 10 {
            score -= 60.0;
        } else {
            score += diff as f64 * 0.3;
        }
    }

    // Compare post_residual relative to mean residual of open bins.
    // Low post_residual relative to mean = tight packing, favor it.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize large leftover dead space that no small item (min size 1) can't use,
    // but small residuals are already handled; penalize mid-range waste.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * waste * 30.0;

    // Slight preference for consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.1 * (1.0 - progress);

    // New-bin candidate: only attractive if all open bins fit poorly.
    if bin_residual == bin_capacity {
        // New bin baseline: prefer keeping existing bins unless they fit badly.
        score += 25.0;
        if fitting_bins_count == 1 {
            score += 60.0; // strongly prefer the existing last-chance bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 30.0; // big next item: fresh bin may be useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small dead space).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    } else if post_residual > 50 {
        score += 30.0; // leaving huge unusable slack
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead: reward if the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 40.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize leaving mid-range residual
            score += 10.0;
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or open bins are already fragmented.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64; // high => open bins full
        let big_item = item_size as f64 / bin_capacity as f64;
        let time_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Prefer new bin when existing residuals are fragmented (mean high)
        // and item is big; penalize early-stream new bins for small items.
        score -= 70.0 * pressure + 30.0 * big_item - 40.0 * (1.0 - time_frac) * (1.0 - big_item);
        // If many bins fit the item, opening a new one is wasteful.
        score += 25.0 * (fitting_bins_count as f64).min(5.0);
    } else {
        // Mild preference for bins whose residual is closest to item size
        // (best-fit flavor) scaled by how full the bin already is.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 15.0 * fill;
    }

    // Slight global fragmentation penalty: when mean residual is low, waste is costlier.
    score += 5.0 * (1.0 - mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), non-linearly
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth polynomial coupling of residual waste with stream progress:
    // later in stream -> punish residual waste harder (less time to fill gaps)
    let waste_penalty = norm_pr * norm_pr * (0.5 + 3.0 * progress * progress);
    score += waste_penalty * cap;

    // Reward near-exact fits with a smooth quadratic bonus
    let exactness = 1.0 - norm_pr;
    score -= 6.0 * exactness * exactness * exactness * exactness;

    // Last-chance bin: strongly favor using it (smooth reward)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 8.0 * progress;
    }

    // New-bin candidate handling: mildly penalize early, allow late or when
    // open bins are crowded (mean residual low) or fit is poor
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64).ln() + 1.0;
        let mean_tight = (mean_residual / cap).powi(2);
        let poor_fit = if next_item_size > 0 {
            (next_item_size as f64 / cap).powi(2)
        } else { 0.0 };
        score += 4.0 + 10.0 * (1.0 - progress) - 6.0 * mean_tight - 5.0 * poor_fit - crowded;
    } else {
        // Prefer bins whose residual is close to item (best-fit flavor), smooth
        let gap = (bin_residual as f64 - item_size as f64) / cap;
        score += gap * gap * (2.0 + 2.0 * progress);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = if pr >= nx { 1.0 } else { 0.0 };
        let closeness = 1.0 - ((pr - nx).abs() / cap);
        score -= 3.0 * usable * closeness * closeness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: items of size 1..100, capacity 100.
    // Class 0: perfect fit (post_residual == 0) -> heavily reward.
    // Class by residue mod 10: small residues are "usable slivers" for small items.
    if post_residual == 0 {
        score -= 1000.0;
        // perfect fit with lookahead bonus if next item also fits nothing... perfect is perfect
        return score;
    }

    // Tight-fit reward: waste fraction of capacity
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 40.0; // quadratic dead-space penalty

    // Harmonic residue classes on post_residual (mod 10 buckets)
    let r = (post_residual % 10) as f64;
    score += r * 0.5; // prefer residuals that are round multiples of 10 (align with common sizes)

    // Integer-division thresholds: which canonical item sizes could still fit
    let fits_small = (post_residual >= 10) as f64;
    let fits_mid = (post_residual >= 40) as f64;
    let fits_large = (post_residual >= 70) as f64;
    score -= fits_small * 6.0 + fits_mid * 4.0 + fits_large * 2.0;

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size <= post_residual {
            // how well does next item pair with this residual
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 - gap.min(20.0);
        } else {
            // next item cannot use this residual: penalize leaving space it can't consume
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin starts with score = capacity.
    // Prefer opening a new bin when all open residuals are badly fragmented
    // (high mean residual spread, many open bins with unusable space).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fragmentation = (mean_residual - post_residual as f64).abs();
    if bin_residual == bin_capacity {
        // new bin: attractive early or when item is large relative to residuals
        score -= 25.0 * (1.0 - progress);
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        if open_bins_count > 3 && mean_residual < 25.0 {
            score -= 15.0; // open bins are nearly full anyway
        }
    } else {
        // penalize placing into bins whose residual diverges from mean (fragmentation)
        score += fragmentation * 0.3;
    }

    // Prefer filling bins that are already mostly full (best-fit reinforcement)
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fits get a strong bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 500.0;
    }

    // Dead space: small unusable gaps (below typical min item size ~10)
    // are worthless; penalize heavily. Larger leftovers remain useful.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Fractional tightness reward: reward filling a large share of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Last-chance bin pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new
    // ones; when few are open, new bins are cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 25.0 + 45.0 * progress + 3.0 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
        // Opening a new bin is attractive if the next item is large and this
        // placement would leave a gap the next item cannot use.
        if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
            score -= 70.0;
        }
        // Avoid opening new bins when existing mean residual can absorb items.
        if mean_residual > item_size as f64 + 15.0 {
            score += 30.0;
        }
    } else {
        // Placing into an open bin: mild bonus if residual stays above the
        // next item's size (keeps bin usable for lookahead).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 25.0;
        } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    // Penalize leaving residuals in the awkward 11..25 band: too big to be
    // dead, too small for typical items — mild dead-space tax.
    if post_residual >= 11 && post_residual <= 25 {
        score += 0.8 * (25 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits snugly into post_residual.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    }
    // Next item cannot use the leftover: penalize dead space proportionally.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward tight fits overall (small post_residual relative to capacity).
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Relative to mean residual: prefer bins that are already more filled than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when it enables a perfect next-item match
    // or when existing bins are nearly exhausted.
    if bin_residual == bin_capacity {
        score += 35.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 55.0;
        }
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post residual (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_quality = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 15.0 + 20.0 * chain_quality;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space for the known next item: penalize proportionally.
        score += 8.0 * (1.0 - tightness);
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): make it attractive only when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by global state.
        let mut new_bin_cost = 55.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_cost *= 0.5 + 1.5 * progress;
        // Many open bins with large mean residual: discourage one more bin.
        new_bin_cost += 0.05 * open_bins_count as f64 + 0.1 * mean_residual.max(0.0);
        // If this bin is the only fitting option, opening new bin is fine.
        if fitting_bins_count == 1 && bin_residual == bin_capacity {
            new_bin_cost -= 20.0;
        }
        score += new_bin_cost;
    }

    // Mild penalty for wasting a large bin on a small item when alternatives exist.
    if item_size <= 20 && bin_residual > 60 && fitting_bins_count > 1 {
        score += 10.0;
    }

    // Tie-break: prefer bins with lower residual among equals via mean-residual contrast.
    score += 0.02 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let fill = 1.0 - pr / cap; // fraction of bin used after placement
    let tightness = 1.0 - (item_size as f64) / cap;

    let mut score = pr;

    // Smooth non-linear reward for tight fits: cubic in fill, modulated by progress
    let fill2 = fill * fill;
    score -= 8.0 * fill2 * fill * (0.5 + progress);

    // Penalize small-but-nonzero dead space with a smooth bump around residual ~ next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        let bump = (-0.5 * gap * gap / (0.25 * cap)).exp();
        score -= 6.0 * bump * (1.0 - progress);
    } else {
        // last item: reward filling completely
        score -= 10.0 * fill2 * fill;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + 0.5 * progress);
    }

    // Mild penalty for leaving residual far from mean residual (fragmentation smoothing)
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap * (1.0 - progress);

    // New-bin candidate: penalize opening bins more as stream progresses,
    // scaled by how many open bins could otherwise fit the item
    if bin_residual == bin_capacity {
        let fit_factor = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 5.0 + 20.0 * progress * fit_factor;
        // allow opening early when bins are crowded
        score -= (open_bins_count as f64).ln().max(0.0);
    }

    // gentle global tightening over time
    score *= 1.0 + 0.15 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 buckets capture "how divisible" leftover is.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    let cls = pr % 10;
    // Favor residuals that fall into "harmonic" classes (multiples of 5/10 fit common item sizes).
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if cls == 0 {
        score -= 12.0;
    } else if cls == 5 {
        score -= 6.0;
    } else if pr < 10 {
        score += 25.0; // dead space below smallest item class
    } else if pr < 20 {
        score += 8.0;
    }

    // Integer-division threshold: residual large enough for a "half bin" chunk (50).
    if pr / 50 >= 1 && post_residual != bin_capacity {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as i64;
        if nx == pr {
            score -= 40.0;
        } else if nx <= pr {
            score -= (nx as f64) * 0.3;
        } else {
            // next item cannot use this leftover: penalize proportionally to waste
            score += ((pr - nx).abs() as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && post_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish, but discourage when open bins are already sparse/empty-ish.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening new bin cost grows with number of open bins and stream progress.
        score += 35.0 + 10.0 * (open_bins_count as f64).ln().max(0.0) + 15.0 * progress;
        // But if this bin would otherwise leave tiny dead space, allow opening.
        if pr > 0 && pr < 10 {
            score -= 30.0;
        }
    }

    // Mild preference for bins tighter than the mean residual (fill fuller bins first).
    score -= (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold a plausible
    // future item are heavily penalized (quadratic in how "dead" the gap is).
    let dead_threshold = 20.0f64.min(bin_capacity as f64 * 0.2);
    if (post_residual as f64) < dead_threshold {
        let deadness = dead_threshold - post_residual as f64;
        score += 3.0 * deadness * deadness / dead_threshold;
    }

    // Reward tight fits (small post_residual relative to residual).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 12.0 * fill_ratio * fill_ratio;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Pressure from number of open bins: prefer consolidating when many bins open.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
    score += 10.0 * open_pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: allow opening a fresh bin when existing residuals are
    // large and fragmented, or when the next item would fit better in fresh space.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score -= 6.0;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
        if open_bins_count > 0 && fragmentation < 5.0 {
            score += 8.0; // existing bins are tight; discourage opening needlessly
        }
    }

    // Lookahead: penalize leaving a gap that neither fits nor matches next item.
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u64) < next_item_size as u64 {
            score += 4.0; // gap too small for next item
        } else if post_residual == next_item_size {
            score -= 8.0; // gap exactly fits next item
        }
    }

    // Mild early-stream preference for keeping bins tight (long streams reward consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: 2-step lookahead — reward bins whose post-residual matches the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let exact = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 6.0 * (1.0 - exact / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize wasted lookahead potential
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Favor tight fits (small post residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.0 * tightness * tightness;

    // Compare against mean residual of open bins: a bin far below mean residual
    // is "precious" compact space; using it on a loose fit is wasteful.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual) / bin_capacity as f64;
    } else {
        score -= 0.5 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        score += 4.0
            + 0.3 * crowd
            + (mean_residual.max(0.0)).min(bin_capacity as f64) * 0.02;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // new bin can always host the next item too; slight discount
            score -= 2.0;
        }
        if fitting_bins_count == 0 {
            score -= 20.0; // no open bin fits: must open new bin
        }
    }

    // Late in stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream (dynamic time horizon).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit reward: strongly favor bins that end up nearly full.
    let perfect_fit = (post_residual as f64 / bin_capacity as f64).powi(3);
    score -= 60.0 * (1.0 - perfect_fit * 8.0).max(0.0) * 0.0; // placeholder no-op
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 40.0;

    // Lookahead coupling: reward if the next item can fit into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains nicely: bonus scaled by how snugly it fits later.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize wasted residual that becomes dead space.
            let dead = post_residual as f64;
            score += 0.15 * dead * (0.5 + progress);
        }
    } else {
        // Last item of the stream: just minimize residual.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Many open bins: prefer consolidating into existing bins, penalize spreading.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // Global mean residual coupling: if mean residual is high, tighten selection
    // (penalize bins that leave more than the mean); if low, be more permissive.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only for poor fits elsewhere or tight fits.
        // Penalize new bins moderately; the penalty is waived when the item is large
        // relative to capacity or when no existing bin fits well.
        let poor_fit_elsewhere = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).max(0.0)
        } else {
            100.0
        };
        score += 55.0 - 0.4 * poor_fit_elsewhere;
        // Late in the stream, slightly favor reusing bins over spawning new ones.
        score += 20.0 * progress;
        // If next item is small, a fresh bin has good future utility.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 15.0;
        }
    }

    // Small deterministic tie-breaker based on residual structure.
    score += (post_residual % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual, with a mild super-linear penalty
    // for dead space that grows as the stream progresses (late bins should be tight).
    let mut score = pr + (pr / cap) * (pr / cap) * cap * (0.15 + 0.55 * progress);

    // Reward near-perfect fills smoothly (quadratic trough at post_residual == 0).
    score -= 12.0 * (1.0 - pr / cap) * (1.0 - pr / cap);

    // Lookahead: penalize if post-residual barely fits next item poorly,
    // reward if next item could fill the leftover nicely.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = pr - nx;
            // small slack after next item is great; large slack is waste
            score += 0.25 * slack * (0.5 + progress);
            score -= 6.0 * (1.0 - slack / cap).max(0.0) * (1.0 - slack / cap);
        } else {
            // next item cannot fit here: mild penalty scaled by overshoot
            let over = (nx - pr) / cap;
            score += 3.0 * over * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 9.0 * (1.0 - pr / cap);
    }

    // Tightness relative to mean residual: bins tighter than average are
    // preferred smoothly (cubic coupling).
    let mr = mean_residual.max(0.0);
    score -= (mr - pr) * 0.18 * (1.0 + progress);

    // Slight penalty when many bins are open and this placement keeps a
    // large residual alive (encourage consolidation).
    score += 0.02 * open_bins_count as f64 * (pr / cap) * (pr / cap);

    // New-bin candidate: make it moderately attractive only when the item is
    // large relative to capacity or progress is late and fits are poor.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score -= 4.0 * large * large * (0.5 + progress);
        score += 2.0 * (1.0 - large);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Strongly reward near-perfect fits (post_residual < 10 => almost no dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Modulo arithmetic on post_residual: leftovers that are multiples of common
    // small sizes (10, 20, 25, 50) are reusable -> reward; odd fragments penalized.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0;
            if pr % 50 == 0 { score -= 8.0; }
        } else if pr % 5 == 0 {
            score -= 5.0;
        } else {
            score += 6.0; // awkward remainder
        }
        // Dead space too small for the smallest plausible item is pure waste.
        if pr < 10 {
            score += 25.0 * (1.0 - frac * 10.0);
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; residual becomes dead unless reusable later
            score += 4.0;
        }
        // Harmonic pairing: item + next == capacity exactly -> ideal
        if item_size + next_item_size == bin_capacity && bin_residual == bin_capacity {
            score -= 40.0;
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin is a fallback; prefer it only when
    // no open bin offers a tight fit. Penalize slightly so tight fits win,
    // but reward it when open bins are all loose (mean residual large).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let loose = mean_residual / bin_capacity as f64;
        score += 20.0 - 15.0 * loose - 10.0 * (1.0 - progress);
        // opening fresh bins early keeps flexibility
        if open_bins_count == 0 { score -= 50.0; }
    } else {
        // Prefer bins whose residual is close to item (tight packing) via
        // integer-division threshold classes on bin_residual.
        let cls = bin_residual / 25; // 0..=4 quartile classes
        score -= match cls {
            0 => 10.0,
            1 => 6.0,
            2 => 3.0,
            _ => 0.0,
        };
    }

    // Mild pressure to consolidate when many bins are open.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fitting = fitting_bins_count as f64;
    let mean = mean_residual.max(0.0);

    let denom = if total_items == 0 { 1.0 } else { total_items as f64 };
    let progress = (step_index as f64 / denom).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;
    let max_post = (cap - item).max(0.0);

    let mut score = post;

    if post <= 0.0 {
        score -= 5.0 + 0.05 * open + 2.5 * progress;
    }

    if next > 0.0 && post > 0.0 && post < next {
        let gap_ratio = ((next - post) / next).clamp(0.0, 1.0);
        let open_fragmentation = 1.0 + open / (2.0 + fitting);
        let mut dead_penalty = gap_ratio * gap_ratio
            * (0.85 * cap + 0.15 * item)
            * open_fragmentation
            * (0.55 + 0.75 * progress);

        if next > max_post {
            dead_penalty *= 0.35;
        }

        score += dead_penalty;
    } else if next > 0.0 && post >= next {
        let inv_cap = if cap > 0.0 { 1.0 / cap } else { 0.0 };
        let slack_after_next = post - next;
        let tightness = (1.0 - slack_after_next * inv_cap).clamp(0.0, 1.0);
        score -= (1.0 + 2.5 * tightness) * (0.5 + 0.5 * progress);
    }

    if is_new_bin {
        let mut new_bin_penalty = 2.5 + 0.22 * open + 0.05 * mean + 3.0 * progress;

        if fitting > 0.0 {
            new_bin_penalty += 1.5 + 0.08 * open;
            if fitting <= 1.0 {
                new_bin_penalty += 2.5;
            }
        }

        score += new_bin_penalty;
    } else {
        score -= 0.015 * open * (0.5 + 0.5 * progress);

        if fitting <= 1.0 {
            score -= 1.5 + 0.05 * open + 1.5 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }
    // 2-step lookahead: if next item exactly fills post_residual, huge reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }
    // Next item fits into post_residual: mild reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
    }
    // Next item would NOT fit: penalize wasted residual, scaled by how much it misses
    if next_item_size > post_residual {
        let miss = (next_item_size - post_residual) as f64;
        score += 0.8 * miss;
    }

    // Penalize small dead residuals relative to mean residual (unusable space)
    if post_residual > 0 {
        let ratio = post_residual as f64 / bin_capacity as f64;
        if ratio < 0.1 {
            score += 40.0 * (0.1 - ratio);
        }
    }

    // Favor tighter fits relative to mean residual of open bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize unless item is large or no good fit exists
    if bin_residual == bin_capacity {
        // Opening a new bin is wasteful if item fits well elsewhere; base penalty
        score += 150.0;
        // Less penalty if item is large relative to capacity
        score -= 0.5 * item_size as f64;
        // If many bins fit the item, opening new bin is clearly bad
        if fitting_bins_count > 1 {
            score += 100.0 * (fitting_bins_count as f64 - 1.0);
        }
        // Early in stream, keep bins open longer
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fit reward: strong bonus as post_residual approaches 0 (non-linear).
    let tightness = 1.0 - post / cap;
    score -= 18.0 * tightness * tightness * tightness;

    // Exact / near-exact closure bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Dead-space penalty for awkward residuals that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // chain fit reward scaled by how well it chains
            let chain = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 8.0 * chain;
        } else {
            // next item cannot fit here; mild penalty for wasting residual
            score += 2.0 * (nxt - post).min(20.0) / 20.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open
    // bin fits well. Empty-bin candidate has bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so an existing decent fit beats a new bin.
        score += 45.0;
        // Penalize more when many bins are already open (fragmentation cost).
        score += (open_bins_count as f64).sqrt() * 2.0;
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // If mean residual across open bins is small (bins nearly full), new bin is fine.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
        // If the item is large relative to capacity, a fresh bin is natural.
        if (item_size as f64) / cap > 0.6 {
            score -= 10.0;
        }
    } else {
        // Using an existing bin with large residual for a small item wastes space;
        // mild penalty proportional to wasted fraction.
        let waste = post / cap;
        score += 6.0 * waste * (1.0 - progress_like(step_index, total_items));
    }

    // Global balance: prefer filling bins below mean residual less when open bins
    // are numerous (spread load).
    if !is_new_bin {
        let dev = (post - mean_residual) / cap;
        score += 4.0 * dev;
    }

    score
}

#[inline]
fn progress_like(step_index: usize, total_items: usize) -> f64 {
    if total_items > 0 { (step_index as f64 / total_items as f64).clamp(0.0, 1.0) } else { 0.0 }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mean_r = mean_residual.max(0.0);

    // Base: post residual, slightly sub-linear to tolerate small dead space.
    let mut score = post.powf(0.92);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, dead space is increasingly penalized.
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += post * (0.55 * p2 + 0.35 * p3);

    // Tight fit reward: coupling item size with residual, smooth quadratic.
    let fill = item / cap;
    score -= 12.0 * fill * (1.0 - fill);

    // Reward bins whose residual is close to the item (good matching),
    // smoothly via squared difference normalized.
    let diff = (bin_residual as f64 - item) / cap;
    score += 6.0 * diff * diff;

    // Mean residual interaction: prefer bins below mean residual (tighter bins)
    // with a smooth saturating term.
    let rel = (mean_r - post) / cap;
    score += 4.0 * rel / (1.0 + rel.abs());

    // Last-chance bonus: strongly favor the only fitting bin, scaled by progress.
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * p2;
    }

    // Lookahead: if next item fits in post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 5.0 * (nxt / cap) * (1.0 - progress * 0.5);
        } else {
            // penalize leaving a gap that barely misses the next item
            score += 3.0 * (post / cap) * (1.0 - (post - nxt) / cap).max(0.0);
        }
    }

    // New-bin candidate handling: empty bin gets a smooth opening cost that
    // decreases as existing bins become fragmented (high mean residual).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_r / cap).min(1.0);
        score += 14.0 - 10.0 * fragmentation * fragmentation - 4.0 * p2;
    }

    // Mild open-bin pressure: many open bins -> favor filling existing ones.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic classes: classify post_residual into modulo buckets.
    // Residuals that are multiples of common item sizes (or leave divisible
    // chunks) are more reusable; residuals of 1..9 are near-dead space.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 18.0; // dead space penalty
    }
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0; // leaves a class-aligned chunk
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 4.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack < 10 {
                score -= 10.0; // near-perfect chain
            } else {
                score -= 5.0 / (1.0 + slack as f64 / 20.0);
            }
        } else {
            // next item won't fit here; penalize small residuals less since
            // bin is effectively closed anyway.
            score -= 2.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin wastes capacity if the item
    // fits reasonably well elsewhere. Penalize the empty-bin call unless
    // current item is large and mean residual is small.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_frac = mean_residual / (bin_capacity as f64);
        // Penalize new bins when open bins have plenty of room.
        score += 30.0 + 20.0 * mean_frac;
        // Late in stream, slightly discourage proliferation of open bins.
        score += 10.0 * progress;
        // If item is huge, new bin is more acceptable: reduce penalty.
        score -= (item_size as f64) * 0.35;
        // If no bin could fit (this call is the only option), fitting count
        // logic still applies; make empty bin viable when item is big.
        if item_size >= 60 {
            score -= 15.0;
        }
    } else {
        // Mild preference for fuller bins: waste-aware scaling.
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 8.0 * fill;
    }

    // Prefer bins whose residual is close to the item (minimize fragmentation).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.05;

    // Coupling with open bins count: many open bins -> consolidate.
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.5 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (below min item size 1..=9)
    // are "unusable" waste; penalize them superlinearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else or open-bin pressure is low.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 30.0;
        // If this bin is the last chance, opening new is discouraged.
        if fitting_bins_count == 1 {
            score += 60.0;
        }
        // If the next item is large, keeping residuals tight matters less;
        // a fresh bin preserves large contiguous space for it.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 25.0;
        }
        // Early in the stream, opening bins is cheaper (more items to come).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
        // Many open bins: discourage fragmentation.
        score += open_bins_count as f64 * 1.5;
    } else {
        // Reward placing into bins whose residual is close to the item
        // (tight fit), scaled against mean residual of open bins.
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += tightness * 0.1;
        // Favor bins below mean residual (consolidating fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
        // Lookahead: if next item would fit in the post-residual, reward it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // Open-bin pressure: prefer filling existing bins when many are open.
        score -= open_bins_count as f64 * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tightest fit).
    score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 20.0 * (1.0 - progress);
    }
    // Near match: next item would leave a tiny remainder too.
    if next_item_size > 0 && post_residual > next_item_size {
        let second_residual = post_residual - next_item_size;
        if second_residual <= 10 {
            score -= 35.0 - second_residual as f64;
        } else {
            // Next item fits but leaves waste: mild bonus proportional to tightness.
            score -= (20.0 - (second_residual as f64) * 0.5).max(0.0);
        }
    }
    // If next item CANNOT fit in the resulting residual, penalize locking out the lookahead.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Penalize dead space relative to the smallest meaningful item (10) —
    // residual too small to ever be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative to mean residual: bins already below average residual are precious,
    // waste them less; bins above average are looser, prefer using them.
    score -= (bin_residual as f64 - mean_residual) * 0.4;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large relative to the item (poor fits everywhere).
    if bin_residual == bin_capacity {
        let avg_tightness = if bin_capacity > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Penalize new bins early and when many bins are open but loosely filled.
        score += 30.0 + 40.0 * (1.0 - avg_tightness) + 10.0 * (1.0 - progress);
        // But if the item is large and average residual can barely hold it,
        // a fresh bin is reasonable: relax the penalty.
        if (item_size as f64) > mean_residual + 0.5 * (bin_capacity as f64 - mean_residual) {
            score -= 45.0;
        }
    }

    // Mild preference to consolidate into fewer bins as stream progresses.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    } else {
        // Last item: pure best-fit.
        score -= 2.0 * tightness;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream horizon and congestion.
        let horizon = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 10.0 * (1.0 - horizon);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Congestion pressure: many open bins with large mean residual -> prefer reusing.
    if open_bins_count > 0 && mean_residual > item_size as f64 {
        score += 2.0 * (mean_residual - item_size as f64) / bin_capacity as f64;
    }

    // Mild preference to fill bins that are already relatively full.
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, scaled by stream progress (later stream -> tighter packing preferred)
    let mut score = pr * (1.0 + 0.6 * progress);

    // Non-linear polynomial coupling of normalized residual with progress
    let x = norm_pr;
    let p = x * x * (3.0 - 2.0 * x); // smoothstep in [0,1]
    score += 12.0 * p * (1.0 - progress) - 8.0 * p * progress;

    // Penalize residuals that cannot fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 15.0 * (nx - pr) / cap;
        } else {
            // reward bins that can still host the next item, smoothly
            score -= 5.0 * (1.0 - ((pr - nx) / cap)).min(1.0);
        }
    }

    // Last-chance bonus: only fitting bin -> strong pull toward it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
        score -= 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins vs mean residual
    score += 0.5 * ((open_bins_count as f64) * 0.1) * (mean_residual - pr).abs() / cap;

    // New-bin candidate: prefer opening a fresh bin early or when fit is poor
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress);
        score += 4.0 * progress * norm_pr; // late stream: discourage hoarding empty bins
    }

    // Exact fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Perfect fill: strongly reward closing a bin exactly.
    if pr == 0 {
        score -= 1000.0;
    }

    // Tiny dead space (1..9) is nearly unusable for items >= 10: penalize.
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // Harmonic class of residual modulo 10: prefer residuals in
    // "compatible" classes that many item sizes can combine into.
    let class = pr % 10;
    score += class as f64 * 0.75;

    // Lookahead (k=2): reward residuals that can host the next item,
    // penalize residuals that strand the next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 25.0;
        } else {
            score += 12.0;
        }
        // Harmonic coupling: exact modular match with next item is ideal.
        if next_item_size == pr {
            score -= 80.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate detection: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the mean residual spread; penalize
        // proportionally to how many bins already fit the item.
        if fitting_bins_count > 0 {
            score += 140.0 + 20.0 * (fitting_bins_count as f64);
        } else {
            // No open bin fits: new bin is necessary, reward it.
            score -= 300.0;
        }
        // Late in the stream, avoid spawning bins with big leftover slack.
        if pr > 50 {
            score += 30.0 * progress;
        }
    }

    // Mild pressure to consolidate: prefer bins below mean residual
    // (tighter bins) when many bins are open.
    if open_bins_count > 3 {
        let diff = mean_residual - pr as f64;
        score += 0.15 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (or even for a plausible future item) are pure waste.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual <= 25 {
            score += 25.0; // likely dead space
        } else if post_residual <= 40 {
            score += 8.0; // moderately risky gap
        } else {
            score -= 6.0; // roomy residual, still usable
        }
    } else {
        score -= 40.0; // perfect closure of the bin
    }

    // Tight-fit reward: how fully the item fills the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // loose fits and encourage consolidation; with few bins, opening new
    // ones is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure * (1.0 - fill_ratio);

    // Mean-residual coupling: if this bin's post-residual sits far above
    // the mean, it fragments the residual landscape.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score += 0.05 * dev; // small reward for below-mean residual
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is excellent; if it nearly fits, slightly penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack == 0.0 {
                score -= 35.0;
            } else if slack <= 10.0 {
                score -= 12.0;
            }
        } else {
            score += 5.0;
        }
    }

    // New-bin candidate handling: an empty bin is a flexible resource.
    // Prefer it only when the item is large relative to capacity or when
    // no tight fit exists elsewhere; otherwise keep it closed.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count > 0 {
            score += 35.0 + 30.0 * (1.0 - item_frac);
        } else {
            score -= 20.0; // forced new bin anyway
        }
    }

    // Mild stream progression: later in the stream, waste matters more
    // since fewer items remain to fill gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward when item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the NEXT item fits exactly
    // into the post-placement residual (a chained perfect match).
    if next_item_size > 0 && post_residual > 0 {
        let lookahead_gap = post_residual as f64 - next_item_size as f64;
        if lookahead_gap == 0.0 {
            score -= 500.0;
        } else if lookahead_gap > 0.0 {
            // Next item fits, reward proportionally to tightness of the chain.
            score -= 60.0 * (1.0 - lookahead_gap / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize residual that will likely
            // become dead space relative to the next item's size.
            score += 0.5 * (-lookahead_gap);
        }
    }

    // Compare post_residual against mean residual of open bins: prefer
    // placements that leave residuals close to (but below) the mean,
    // penalizing outliers that create hard-to-fill space.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.15 * mean_gap.abs();

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless existing
    // placements would waste a lot of space.
    if bin_residual == bin_capacity {
        score += 80.0 + 0.3 * mean_residual;
        // If the next item is large, opening a new bin is more attractive.
        if next_item_size > 60 {
            score -= 40.0;
        }
    }

    // Late in the stream, consolidate: favor filling existing bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space ratio.
    let waste_ratio = post_residual as f64 / cap;
    score += 30.0 * waste_ratio * waste_ratio;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly — reward it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            score -= 20.0 * (1.0 - diff / cap);
        } else {
            // Next item cannot use leftover; penalize proportionally to gap.
            score += 8.0 * (diff / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // no open bin fits well, or global residual pressure is high.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a bin.
        let mut penalty = 70.0;
        // As stream progresses, closing out residual space matters more;
        // opening new bins becomes relatively cheaper early on.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty *= 1.0 - 0.3 * (1.0 - progress);
        // If the mean residual across open bins is large, open bins are
        // fragmented; a fresh bin is more attractive.
        penalty -= 0.15 * mean_residual;
        // If this item is the only one that fits nowhere else, soften penalty.
        if fitting_bins_count == 0 {
            penalty -= 60.0;
        }
        score += penalty;
    } else {
        // Favor using bins whose residual is below the mean (consolidation).
        let res = bin_residual as f64;
        if res < mean_residual {
            score -= 6.0 * (mean_residual - res) / cap;
        } else {
            score += 4.0 * (res - mean_residual) / cap;
        }
        // Many open bins: prefer filling existing ones over spreading.
        score -= 0.5 * open_bins_count as f64;
    }

    // Small tie-breaker noise-free coupling with item size: larger items
    // deserve slightly more priority placement in tight bins.
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let tightness = 1.0 - pr / cap; // how full the bin becomes

    // Base: prefer small post residual, with non-linear sharpening
    let mut score = pr + 12.0 * (pr / cap) * (pr / cap) * cap * 0.01;

    // Reward tight fits more strongly as the stream progresses
    let tight_reward = tightness * tightness * (30.0 + 50.0 * progress);
    score -= tight_reward;

    // Cubic coupling: near-perfect fits get a strong boost late in the stream
    let t3 = tightness * tightness * tightness;
    score -= t3 * (20.0 + 40.0 * progress);

    // Penalize dead space relative to next item: if next item fits in post_residual, this is good
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            // waste proportional to gap the next item cannot use
            score += 4.0 * ((nx - pr) / cap).min(1.0);
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild pressure to consolidate when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * tightness * 3.0;

    // Slight pull toward bins near the mean residual (smooth coupling)
    score += ((pr - mean_residual) / cap).abs() * 2.0;

    // New-bin candidate: make it moderately attractive only for large items / poor fits
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * tightness - 10.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 5.0; // a fresh bin also serves the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into capacity fractions.
    let post_frac = post_residual as f64 / cap;
    let harmonic_class = (post_frac * 8.0).floor() as i32; // eighths of capacity

    // Dead-space penalty: tiny leftovers (< ~12% capacity) are nearly unusable.
    if post_residual > 0 && post_residual * 8 < bin_capacity {
        score += 40.0 * (1.0 - post_frac * 8.0);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward residuals that are harmonic multiples of common item sizes (modular harmony).
    let harmony = [10u32, 20, 25, 40, 50, 80]
        .iter()
        .map(|&s| if post_residual >= s && post_residual % s == 0 { 12.0 } else { 0.0 })
        .sum::<f64>();
    score -= harmony;

    // Lookahead coupling: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportional fit quality (tight next fit is best).
            let tightness = next_item_size as f64 / post_residual as f64;
            score -= 20.0 + 30.0 * tightness;
            // Extra reward if next item exactly consumes the leftover.
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else {
            // Penalize residuals that cannot host the lookahead item.
            score += 15.0;
            // If the leftover is below the minimum plausible item size, it's dead space.
            if post_residual < next_item_size.min(20) {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // When many bins compete, prefer tighter fits more aggressively.
    if fitting_bins_count > 2 {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // and the current item would leave a bad (non-harmonic, mid-range) residual.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * (mean_residual / cap);
        let bad_fit = if post_frac > 0.25 && post_frac < 0.6 { 1.0 } else { 0.0 };
        let lookahead_pressure = if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 { 1.0 } else { 0.0 };
        let pressure = (crowded * 0.4) + bad_fit * 30.0 + lookahead_pressure * 25.0;
        // Base cost of opening a new bin, discounted by stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 - progress * 15.0 + pressure;
    }

    // Integer-division threshold: residuals in (cap/3, cap/2) are awkward; penalize mildly.
    if post_residual > bin_capacity / 3 && post_residual < bin_capacity / 2 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    // dead space -> heavy penalty; small gaps below the minimum item size.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 + min_item {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Waste ratio coupling: penalize leaving a large fraction of capacity idle.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        }
    }

    // Open-bins pressure: discourage opening new bins when many are open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 8.0 * open_bins_count as f64;
        // But if this bin is the only option, new bin is less penalized.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidation into open bins less strongly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        score -= 35.0;
    }

    // Prefer bins whose residual is already small (consolidate tight bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Lookahead: reward if next item fits exactly into the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            score -= 150.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty proportional to overshoot
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare post residual against mean residual of open bins:
    // leaving less than average waste is good
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Penalize spreading across many open bins slightly; encourage consolidation
    score += 0.2 * open_bins_count as f64;

    // New-bin candidate handling: opening a fresh bin is attractive only when
    // the item is large relative to capacity or no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 120.0;
        // large items justify a new bin more
        score -= 0.8 * item_size as f64;
        // if many bins can fit the item, opening new bin is wasteful
        if fitting_bins_count > 2 {
            score += 200.0;
        }
        // early in the stream, new bins are cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Dead-space penalty: leftover space that is too small for typical items is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // barely usable
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.15 * next_item_size as f64;
        } else {
            score += 4.0; // blocks the natural follow-up placement
        }
        // Perfect chain: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Global pressure: when many bins are open relative to progress, discourage
    // opening yet another bin; the new-bin candidate gets a rising penalty.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let openness = open_bins_count as f64 / (total_items.max(1) as f64).sqrt().max(1.0);
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * openness + 15.0 * progress;
        // But allow a fresh bin when all existing fits are bad (high post_residual elsewhere
        // is already handled); also allow it when it would create a perfect half-filled bin.
        if item_size * 2 == bin_capacity {
            score -= 30.0;
        }
        // Attraction to fresh bins early in the stream when few bins are open.
        if open_bins_count <= 2 && progress < 0.1 {
            score -= 15.0;
        }
    } else {
        // Mild bonus for reusing bins that are already relatively empty vs. the mean,
        // balancing residual distribution across open bins.
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Slight preference for filling fuller bins overall (best-fit flavor).
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let base = post * (1.0 + 0.6 * progress * norm_post);

    // Reward tight fits (small post residual), stronger late in the stream
    let tight_fit_reward = -8.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 + progress);

    // Penalize dead space: unusable residual relative to smallest plausible item
    let dead_space = if post > 0.0 && post < 10.0 {
        12.0 * (10.0 - post) / 10.0
    } else {
        0.0
    };

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    let last_chance = if fitting_bins_count == 1 { -6.0 } else { 0.0 };

    // Lookahead: reward if next item fits into the post residual
    let lookahead = if next_item_size > 0 {
        if (next_item_size as f64) <= post {
            -4.0 * (next_item_size as f64 / cap)
        } else {
            2.0 * ((next_item_size as f64 - post) / cap)
        }
    } else {
        0.0
    };

    // Mild penalty for spreading across many open bins late in stream
    let spread = 0.15 * (open_bins_count as f64).ln().max(0.0) * progress;

    // Deviation from mean residual: prefer bins near the mean (keeps balance)
    let mean_coupling = -0.3 * (norm_post - mean_residual / cap).abs();

    base + tight_fit_reward + dead_space + last_chance + lookahead + spread + mean_coupling
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: items that fit exactly leave a
    // "perfect" residual; classify residuals into capacity-fraction classes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit reward (post_residual == 0).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space classes: residual that no typical item (1..=100) can use
    // is worthless. Penalize tiny residuals harshly (they are dead space),
    // but only mildly if they fall in a "harmonically useful" class.
    if post_residual > 0 {
        let usable = if post_residual >= 1 { 1.0 } else { 0.0 };
        // Fraction of capacity wasted relative to a full bin.
        let waste_frac = post / cap;
        // Harmonic penalty: waste in (0, 0.1) of capacity is nearly dead.
        if waste_frac < 0.1 {
            score += (0.1 - waste_frac) * 300.0;
        } else if waste_frac < 0.25 {
            score += (0.25 - waste_frac) * 80.0;
        }
        let _ = usable;
    }

    // Modulo-class coupling: if next item fits exactly into post_residual,
    // this bin stays perfectly packed — big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits partially: reward proportional to how tightly.
        let tight = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 120.0 * tight;
    } else if next_item_size > 0 {
        // Next item cannot use this residual: residual risks becoming dead
        // space; penalize more when residual is small.
        score += 40.0 * (1.0 - post / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual; make
    // it attractive only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream
        // and when many items remain to be packed.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_cost = 220.0 - 80.0 * progress;
        // Discount if current open bins are all crowded (high mean residual
        // means bins are full-ish, so a fresh bin is reasonable).
        score = post_residual as f64 + open_cost - (mean_residual / cap).min(1.0) * 60.0;
        // If the next item is large and would pair with this one, opening
        // a fresh bin is more attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 90.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit baseline shaping).
    score -= (1.0 - (bin_residual as f64) / cap) * 10.0;

    // Tie-break noise-free harmonic class: prefer residuals that are
    // multiples of common item sizes (10/20/25/50) — easier future fits.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones.
    let pressure = (open_bins_count as f64 / 20.0).min(1.5);
    if bin_residual == bin_capacity {
        score += 30.0 + 45.0 * pressure;
    } else {
        score -= pressure * 8.0;
    }

    // Lookahead: prefer bins whose leftover can fit the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Mild alignment with mean residual state.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits with small slack left -> moderate reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize residuals too small for typical future items (dead space).
    if post_residual < 10 {
        score += 25.0;
    }

    // Penalize deviations from mean residual: prefer balanced bin usage.
    let dev = post_residual as f64 - mean_residual;
    score += 0.35 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New empty bin candidate: penalize opening a new bin unless residuals
    // across open bins are already tight (little useful space left).
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 45.0 - 40.0 * mean_tightness;
        // Late in the stream, opening a fresh bin is slightly less costly.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size >= 50 {
            score -= 12.0;
        }
    }

    // Slight preference for tighter fits (smaller post_residual relative to item).
    score += 0.15 * (item_size as f64 / bin_capacity as f64) * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear reward.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that is too small for typical items but not zero.
    if post_residual > 0 {
        let dead = if next_item_size > 0 {
            (post_residual as i32 - next_item_size as i32).max(0) as f64
        } else {
            post_residual as f64 * 0.5
        };
        score += 0.6 * dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward leaving room for the next item to co-fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        // next item won't fit here anyway; mild penalty for stranding capacity
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 0.2 * bin_residual as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are badly fragmented or many bins are open.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual - bin_residual as f64).max(0.0);
        // penalty so new bins are not opened frivolously; reduced late in stream
        score += 60.0 - 25.0 * progress;
        // if open bins have plenty of room on average, penalize new bin more
        score += 0.3 * (mean_residual / bin_capacity as f64).max(0.0) * 40.0;
        // if item is large and few fitting bins, new bin is less bad
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if fragmentation > 40.0 {
            score -= 15.0;
        }
    }

    // Mild pressure against accumulating too many open bins.
    score += 0.05 * open_bins_count as f64 * fit_ratio;

    // Small time-varying exploration term (deterministic).
    let t = step_index as f64;
    score += 2.0 * ((t * 0.017).sin()) * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * t) - 0.35 * norm_pr * norm_pr * (1.0 - t);
    score += poly * cap * 0.5;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 20.0 * t);

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * t;
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 - pr) / cap;
    }

    // Penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual).max(0.0);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty for opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) are ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead space penalty grows as post_residual becomes "unusable".
        // Classify residual by integer division thresholds vs typical item sizes.
        let r = post_residual;
        // Residual below the minimum plausible item size is dead space.
        if r < 10 {
            score += 60.0 * (10 - r) as f64;
        }
        // Harmonic class: r mod 10 — residues just above a decade boundary are awkward.
        let m = (r % 10) as f64;
        score += 0.8 * m;

        // Fractional capacity coupling: how much of the bin remains.
        let frac = r as f64 / bin_capacity as f64;
        // Prefer bins whose residual is "close" to a usable chunk: penalize
        // large leftovers that no future item likely fills exactly.
        if frac > 0.5 {
            score += 25.0 * (frac - 0.5);
        }

        // Lookahead: reward if next item fits the post residual (chaining).
        if next_item_size > 0 {
            if next_item_size <= r {
                // Tight chain: next item nearly fills leftover.
                let gap = (r - next_item_size) as f64;
                score -= 40.0 - 0.5 * gap;
                if gap == 0.0 { score -= 100.0; }
            } else {
                // Next item cannot use leftover: penalty scaled by leftover size.
                score += 0.3 * (next_item_size - r) as f64;
            }
        }

        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score -= 80.0;
        }

        // Many open bins: prefer tightening crowded bins (low residual).
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if (bin_residual as f64) < mean_residual {
            score -= 10.0 * (1.0 - t) + 5.0 * t;
        } else {
            score += 5.0 * (1.0 - t);
        }
    }

    // New-bin candidate: residual == capacity. Make it a fallback with
    // moderate score so it wins only when open-bin fits are poor.
    if bin_residual == bin_capacity {
        score = 55.0
            + 0.15 * open_bins_count as f64
            + if next_item_size > 0 { (next_item_size as f64) * 0.1 } else { 0.0 };
        // Late in the stream, closing out bins is cheaper than opening new ones.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 60.0 * t;
        if fitting_bins_count == 1 { score += 120.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the smallest plausible item are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fit, ideal
    } else if post_residual <= 12 {
        // Small unusable-ish gaps are heavily penalized unless they match the lookahead item.
        let dead = 12.0 - post_residual as f64;
        score += dead * 6.0;
    }

    // Reward tight fits relative to residual (best-fit flavor with sharpening).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Lookahead coupling: if next item exactly fills post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual - next_item_size <= 10 {
            score -= 25.0;
        } else {
            // next item leaves another awkward gap
            score += (post_residual - next_item_size) as f64 * 0.3;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here; bin will be dead after this placement
        score += 35.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin starts with high base score,
    // only attractive when open bins are crowded or the fit is bad.
    if bin_residual == bin_capacity {
        score = 60.0 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 {
            score -= (bin_capacity - next_item_size) as f64 * 0.2;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Open-bins pressure: many open bins -> prefer packing tighter into existing ones.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins with residuals near the item (relative tightness vs fleet mean).
    score += (bin_residual as f64 - mean_residual) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead matching ---
    if next_item_size > 0 {
        // Perfect match: post residual exactly equals next item -> reward strongly.
        if post_residual == next_item_size {
            score -= 60.0 + 20.0 * progress;
        } else if post_residual >= next_item_size {
            // Next item still fits in the leftover: reward proportionally to how snug it is.
            let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 25.0 * snug * snug;
        } else {
            // Next item cannot use the residual: penalize dead space, scaled by gap size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap.min(60.0);
        }
    } else {
        // Last item: just prefer tightest fill.
        score -= 10.0;
    }

    // --- Tightness reward relative to bin capacity ---
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * fill_ratio * fill_ratio;

    // --- Relative residual vs mean: prefer bins below-average residual (tighter bins) ---
    score -= 0.20 * (mean_residual - post_residual as f64);

    // --- Last-chance bin: if this is the only fitting bin, strongly favor using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing fits are poor:
        // penalize new bins when many bins already fit, less when few do.
        let crowd = fitting_bins_count.min(10) as f64;
        score += 55.0 - 6.0 * crowd;

        // Late in the stream, slightly discourage spawning extra bins.
        score += 10.0 * progress;

        // If next item is large and this bin is empty, a fresh bin is flexible.
        if next_item_size > 60 {
            score -= 15.0;
        }
    }

    // Mild penalty for many open bins (bin-count economy pressure).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space non-linearly: small residuals that can't fit
        // typical small items (min size 1..) are wasted capacity.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 40.0 * tightness * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus
    // (chained perfect packing). If next item won't fit in post_residual but
    // would fit a fresh bin, mildly penalize leaving it stranded.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            // Next item stranded: penalize proportionally to how much of it
            // overflows, but only if post_residual is small (dead space).
            if post_residual < next_item_size && post_residual < 20 {
                score += 15.0;
            }
        }
    }

    // New-bin candidate handling: only open a new bin when the current bin's
    // post_residual would be unusable dead space, or bins are plentiful.
    if bin_residual == bin_capacity {
        // Base cost of a new bin: keep it expensive so we prefer existing bins.
        score += 70.0;
        // But if placing here leaves terrible fragmentation in the best fitting
        // bin, opening fresh is fine. Approximate via mean_residual: many open
        // bins with large residuals => capacity is abundant, cheaper to open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 50.0 * mean_residual / bin_capacity as f64 * (1.0 - progress);
        // Exact fit of item in fresh bin is great.
        if post_residual == 0 {
            score -= 300.0;
        }
    }

    // Mild preference to spread across bins when many are open (balance load),
    // and to consolidate when few bins are open.
    if open_bins_count > 2 {
        score += (post_residual as f64) * 0.1 * (open_bins_count as f64).ln();
    }

    // Prefer filling bins that are already mostly full (keep few large gaps).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fit_rate = (post_residual as f64 / cap).powi(2);
    let mut score = pr;

    // smooth polynomial coupling of post_residual with stream progress
    let progress_weight = 0.5 + 0.5 * (t * std::f64::consts::PI).sin();
    score -= progress_weight * (pr * pr) / cap * 0.35;

    // reward tight fits more strongly as stream progresses
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * (1.0 + t) * 12.0;

    // penalize dead space relative to mean residual (smooth quadratic)
    let dead = (pr - mean_residual) / cap;
    score += 8.0 * dead * dead * cap;

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    }

    // lookahead: reward residual matching next item smoothly
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64) / cap;
        score -= 10.0 * (1.0 - 2.0 * diff * diff);
    } else {
        // last item: strongly prefer minimal waste
        score -= 25.0 * (1.0 - pr / cap);
    }

    // mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln() * 1.5;

    // new-bin candidate: prefer it only when no open bin fits well
    if bin_residual == bin_capacity {
        score += 20.0 - 18.0 * t + fit_rate * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item (integer division thresholds on size)
    let item_class = item_size / 10; // 0..10 harmonic class
    let next_class = (next_item_size / 10) as f64;

    // Reward tight fits: nonlinear squash of post_residual
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Penalize dead space that cannot hold the next item (lookahead coupling)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0 + 0.25 * (post_residual as f64);
    }

    // Reward leaving exactly enough room for the lookahead item (perfect chaining)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // partial reward scaled by how small the leftover gap is
        let gap = (post_residual - next_item_size) as f64;
        score -= 3.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Harmonic class complementarity: bins whose residual complements the next item's class
    if next_item_size > 0 {
        let res_class = post_residual / 10;
        if res_class == (next_item_size as u32 / 10).max(1) - 1 {
            score -= 2.0;
        }
    }

    // Last-chance bonus: only this bin can fit the item
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Discourage spreading across too many open bins when mean residual is large
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // New-bin candidate handling: empty bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin, softened late in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 9.0 - 3.0 * progress;
        // if item is large, a fresh bin is more attractive (avoids fragmentation)
        if item_class >= 6 {
            score -= 4.0;
        }
        // if many bins fit the item, opening new bin is wasteful
        if fitting_bins_count > 2 {
            score += 3.0;
        }
    }

    // Mild phase modulation via harmonic class of step index
    let phase = (step_index % 7) as f64;
    score += 0.02 * phase * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 + (10 - post_residual) as f64 / 10.0);
    }
    // Medium gaps that only fit tiny items are also risky.
    if post_residual > 10 && post_residual < 20 {
        score += 15.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward tight fits (best-fit coupling).
    score -= 25.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate penalty grows with open bins and stream progress.
        score += 30.0 + 10.0 * open_bins_count as f64 * (0.5 + progress);
    } else {
        score -= 2.0 * open_bins_count.min(20) as f64;
    }

    // Lookahead: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 10.0; // post residual becomes dead space for the known future
    }

    // Prefer bins below mean residual (consolidate waste in few bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits: penalize leftover slack after the pair
            let slack_after_pair = post_residual - next_item_size;
            score += 0.3 * slack_after_pair as f64;
            // bonus for small combined slack
            if slack_after_pair <= 5 {
                score -= 120.0;
            }
        } else {
            // next item won't fit here: penalize leaving a gap smaller than next item
            score += 0.5 * post_residual as f64;
            if post_residual < 10 {
                score -= 40.0; // tiny dead space is cheap
            }
        }
    }

    // Tightness reward relative to bin capacity
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 2.0 * fill;

    // Prefer bins with residual close to item size (relative fit)
    let rel_fit = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 3.0 * rel_fit;

    // Compare against mean residual: favor using bins with below-average residual (tighter bins)
    score += 0.4 * (mean_residual - post_residual as f64);

    // Last chance bonus: only this bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize opening new bins when existing bins fit reasonably well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0;
        // but if next item is large, fresh bin may be valuable
        if next_item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Late in stream: consolidate, discourage new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (nonlinear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.75 {
        score -= 30.0 * fit_ratio * fit_ratio;
    }

    // Penalize dead space: residuals too small to hold even a small item (assume min size 1..100 unknown, use ~10% of capacity).
    let dead_threshold = bin_capacity as f64 * 0.1;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward; if it would need a new bin otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // placing here still allows next item elsewhere? penalize blocking a good residual
            score += 5.0;
        }
        // If next item is large, prefer leaving big residuals: penalize creating tiny residuals.
        if next_item_size > post_residual && post_residual > 0 && (post_residual as f64) < next_item_size as f64 * 0.5 {
            score += 8.0;
        }
    }

    // Time horizon: early in stream, be more selective (avoid fragmenting many bins);
    // late in stream, prefer filling existing bins to reduce count.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage consolidation into existing bins over new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins are already open
        // and how many other bins fit the item.
        score += 20.0 + 3.0 * open_bins_count as f64 + 15.0 * fitting_bins_count as f64;
        // Early stream: new bins are fine.
        score -= 25.0 * (1.0 - progress);
        // If mean residual is large, existing bins have room; discourage new bin.
        score += 0.15 * mean_residual;
    } else {
        // Existing bin: slight preference when its residual is above mean (use slack).
        if bin_residual as f64 > mean_residual {
            score -= 4.0;
        }
    }

    // Small penalty scaling with number of open bins for spreading items.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap; // 0..1
    let t = progress;
    let poly = norm_post * norm_post * (1.0 - t) + norm_post * t * t;
    score += 12.0 * poly * (1.0 + 0.5 * t);

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= 8.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + t);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * t;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Penalize bins whose residual deviates badly from mean residual (fragmentation).
    let dev = (mean_residual - post) / cap;
    score += 4.0 * dev * dev;

    // Lookahead: reward leaving space for the next item, penalize near-miss.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 6.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            let miss = (nxt - post) / cap;
            score += 10.0 * miss * (0.5 + t);
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * norm_post;

    // New-bin candidate: neutral-to-slightly-high baseline, cheaper late in stream
    // only if current fit is bad (handled via post_residual term itself).
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * t * (1.0 - norm_post);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with non-linear penalty on waste.
    score = post_residual as f64 * 1.5 + (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Harmonic class of the post-residual: residuals divisible by large chunks
    // (10, 20, 25, 50) are more reusable by future items.
    let pr = post_residual;
    if pr > 0 {
        if pr % 50 == 0 {
            score -= 30.0;
        } else if pr % 25 == 0 || pr % 20 == 0 {
            score -= 18.0;
        } else if pr % 10 == 0 {
            score -= 10.0;
        } else if pr < 10 {
            // dead space below min item size — heavily penalize
            score += 25.0 + (10 - pr) as f64 * 4.0;
        }
    } else {
        // perfect fit — excellent
        score -= 60.0;
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let nxt_post = pr - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 12.0;
            }
            if nxt_post < 10 {
                score += 8.0;
            }
        } else {
            // next item won't fit here at all: mild penalty for blocking
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): should only win when all fits are poor.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; penalize so existing bins with decent fits win.
        score = 55.0 + item_size as f64 * 0.3;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            // pairing potential makes a fresh bin more attractive
            score -= 15.0;
        }
        if fitting_bins_count == 1 {
            // an existing bin is the last chance — new bin must lose
            score += 40.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Stream progression: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0 * (mean_residual / bin_capacity as f64);

    // Prefer bins whose residual is below mean (already well-filled).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits with small waste
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (-slack / 12.0).exp();
    }

    // Penalize dead space: post_residual too small for any plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Tight fits are generally good
    score += 8.0 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap >= 0.0 {
            score -= 5.0; // existing bins are roomy; new bin is fine
        } else {
            score += 20.0; // existing bins are tight; discourage new bin
        }
        // Late in stream, prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Favor bins with residuals near mean (balanced packing)
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalize waste relative to capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * waste_ratio * 30.0;

    // Perfect or near-perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: mild reward, scaled by leftover after next.
            let after_next = post_residual - next_item_size;
            score -= 10.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit in this bin's remainder; penalize leaving awkward gaps.
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: slight penalty to keep flexibility.
        score += 3.0 * ((fitting_bins_count - 2) as f64).min(5.0);
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    if (bin_residual as f64) > mean_residual {
        score -= 6.0;
    } else {
        score += 4.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Time horizon: early in the stream, be more willing to spread items
    // (explore); late in the stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (1.0 - waste_ratio);

    // New-bin candidate handling: opening a new bin is attractive when the item
    // is large and would leave a large, unusable gap in an existing bin, or when
    // it is the last item.
    if bin_residual == bin_capacity {
        let last_item = next_item_size == 0;
        let big_item = item_size >= bin_capacity * 3 / 4;
        let poor_fit = fitting_bins_count <= 1;
        if last_item {
            score += 100.0; // never open a bin for the final item if any bin fits
        } else if big_item || poor_fit {
            score -= 20.0; // encourage fresh bin for large/awkward items
        } else {
            // Mild default preference for existing bins, softened late in stream.
            score += 12.0 - 8.0 * progress;
        }
    }

    // Small structural bonus for keeping open-bin count stable.
    if open_bins_count > 0 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let r = bin_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fits less aggressively (keep flexibility);
    // late stream: strongly prefer small post_residual (minimize waste).
    let tightness = 1.0 + 3.0 * t * t; // grows smoothly from 1 to 4
    score *= tightness;

    // Smooth penalty for mid-range dead space (post residual neither tiny nor large),
    // modeled as a parabola centered at ~35% capacity, modulated by progress.
    let dead = norm_pr - 0.35;
    score += 60.0 * (dead * dead - 0.12) * (0.5 + 0.5 * t);

    // Reward near-perfect fits (post residual close to 0) with smooth saturation.
    score -= 40.0 * (-(norm_pr * norm_pr) / 0.02).exp();

    // Lookahead coupling: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 25.0 * (-(slack * slack) / 0.01).exp();
    } else if next_item_size > 0 {
        // penalty if next item cannot fit residual (wasted residual)
        score += 10.0 * t;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0 + 30.0 * t;
    }

    // New-bin candidate handling: make empty bin mildly unattractive unless
    // current bins would leave very bad residuals.
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * t;
    }

    // Slight preference for bins with below-average residual (consolidate waste).
    score += 5.0 * ((r - mean_residual) / cap);

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64 * norm_item;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base tightness: reward small post_residual non-linearly.
    let pr = post_residual as f64;
    score += (pr / cap) * (pr / cap) * 20.0;

    // Harmonic class of post_residual: dead space in (0..10] is nearly unusable
    // for items >= 10 in classic streams, but sizes are 1..100, so weight by
    // divisibility structure: post_residual sharing a divisor class with
    // common sizes is more reusable.
    let pr_u = post_residual;
    if pr_u > 0 {
        let reusable = (pr_u % 5 == 0) as i32 as f64 * 3.0
            + (pr_u % 10 == 0) as i32 as f64 * 4.0
            + (pr_u % 25 == 0) as i32 as f64 * 3.0;
        score -= reusable;
    } else {
        // Perfect fill: strong reward.
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr_u {
            score -= 45.0;
        } else if next_item_size <= pr_u {
            let slack = (pr_u - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this residual: mild penalty proportional to gap.
            score += ((next_item_size - pr_u) as f64 / cap) * 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is attractive when open bins
    // are fragmented (high mean residual spread) or few bins exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        // Penalize opening when existing bins are roomy and item fits well.
        score += 30.0 - 25.0 * fragmentation - 15.0 * progress;
        // If the item is large relative to capacity, a fresh bin is natural.
        score -= (item_size as f64 / cap) * 10.0;
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 5.0 + (open_bins_count.min(20) as f64);
    }

    // Exact-fit of item into residual (post_residual == 0 handled above);
    // reward half-fill harmony classes (modulo arithmetic on item).
    if item_size % 50 == 0 || item_size % 33 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..100 range,
    // but typical min ~10) can use are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 15 {
        score -= 8.0; // small-but-recoverable gap is actually useful
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 25.0 * (1.0 - tightness.min(1.0));

    // Exact fit: perfect packing.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize waste proportional to bin capacity usage imbalance.
    score += 0.15 * (bin_capacity as f64 - bin_residual as f64);

    // Open bins pressure: discourage proliferation of many open bins
    // unless the fit is excellent.
    score += 0.5 * open_bins_count as f64 * (1.0 + tightness);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate logic: an empty bin is only attractive when the
    // current item would leave a large dead gap in any existing bin,
    // or when open bins are numerous and fragmented.
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual > 0 && post_residual < 10 { 0.0 } else { 30.0 };
        score = 45.0 + 0.4 * open_bins_count as f64 - gap_penalty
            - 10.0 * (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        if next_item_size > 0 && next_item_size as f64 >= post_residual as f64 {
            // lookahead item would not fit in the fresh bin either; less useful
            score += 15.0;
        }
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            // fresh bin pairs perfectly with the next item
            score -= 35.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this placement (chain packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 0.3 * (next_item_size as f64 / post_residual.max(1) as f64);
    }

    // Mild stream-progress adaptation: later in the stream, be more conservative
    // about opening bins (consolidation phase).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base; add a bonus
    // (subtract more) when the fit is very snug.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // 2-step lookahead: if the next item fits exactly (or nearly) into the
    // post_residual, strongly reward this placement.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits: reward closeness to a perfect 2-item fill.
            score -= 18.0 / (1.0 + gap);
        } else {
            // Next item does not fit: penalize wasted residual relative to next item.
            score += 0.15 * gap;
        }
    } else {
        // Last item: prefer minimal leftover.
        score -= 6.0 * fit_ratio;
    }

    // Penalize creating dead space far below the smallest plausible item,
    // especially late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score += 8.0 + 10.0 * progress;
    }

    // Compare against mean residual: placing into a bin whose residual is
    // much larger than the mean tends to fragment big bins; penalize mildly.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large (poor fit elsewhere is likely) or nothing fits well.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / 100.0) * 14.0;
        score -= large_item_bonus;
        // Late in the stream, prefer consolidating into open bins.
        score += 6.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            score += 9.0;
        }
        // If the next item is small, a fresh big bin wastes capacity.
        if next_item_size > 0 && next_item_size < 30 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Exact or near-exact fill gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead-space penalty: residual too small for typical items (1..=100 range).
    // Post-residual in 1..=9 is nearly unusable -> penalize.
    if post_residual >= 1 && post_residual < 10 {
        score += 18.0;
    }
    // Mid-range awkward residual (10..=20) mildly penalized since few items land there.
    if post_residual >= 10 && post_residual < 21 {
        score += 6.0;
    }

    // Lookahead: if the next item fits in post-residual, reward chaining.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            // Reward chain, but only if slack stays small (usable).
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here: slight penalty proportional to gap.
            score += 0.15 * (nxt - pr).min(50.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoids wasting existing residual).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) / 8.0;
        // Base penalty for opening a new bin; reduced late in stream or when many bins open.
        let mut new_bin_penalty = 35.0 - 10.0 * progress - 2.5 * crowded.min(4.0);
        // If the mean residual across open bins is small (bins nearly full),
        // opening a new bin is more acceptable.
        let mean_tight = 1.0 - (mean_residual / (bin_capacity as f64)).clamp(0.0, 1.0);
        new_bin_penalty -= 20.0 * mean_tight;
        // If nothing else fits (fitting_bins_count counts only open bins; new bin is separate),
        // this call being lowest means we must open: soften penalty when item is large.
        if item_size > bin_capacity / 2 {
            new_bin_penalty -= 8.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Mild preference for filling fuller bins first when many bins are open.
    score += 0.05 * (bin_residual as f64 / (bin_capacity as f64)) * (open_bins_count as f64).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let norm_res = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early stream: mild residual penalty; late stream: strong penalty on wasted space.
    let progress_gain = 1.0 + 1.5 * t * t;
    score += 8.0 * progress_gain * norm_res * norm_res * cap * 0.1;

    // Reward tight fits (small post_residual) with a smooth cubic discount.
    score -= 6.0 * (1.0 - norm_res).powi(3) * (1.0 + 0.5 * t);

    // Penalize deviation from mean residual (fragmentation avoidance), smooth quadratic.
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / (cap * 0.1);

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_res) * (1.0 + t);
    }

    // Lookahead: smooth bonus if next item fits in post_residual.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fits = (ns <= pr) as i32 as f64;
        let tightness = 1.0 - (ns / pr.max(1.0)).abs();
        score -= 5.0 * fits * tightness.max(0.0) * (1.0 + 0.5 * t);
        // Penalize leaving residual too small for next item (smooth).
        let gap = (pr - ns).abs();
        score += 0.05 * gap * gap / cap;
    }

    // New-bin candidate (empty bin): penalize opening new bins smoothly,
    // stronger late in the stream and when many bins are open.
    if bin_residual == bin_capacity {
        let open_scale = (open_bins_count as f64).sqrt();
        score += 15.0 + 10.0 * t + 2.0 * open_scale;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_frac = pr / cap;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // Modulo classes on post_residual: residuals in [1..10] are "harmonically usable"
    // for small future items; residuals like 11..19 are awkward dead space.
    let dead_class = post_residual % 20;
    if dead_class >= 11 && dead_class <= 19 {
        score += 40.0; // awkward zone penalty
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0; // round residuals pair well with decadal item sizes
    }

    // Fractional capacity thresholds
    if pr_frac < 0.10 {
        score -= 60.0; // bin nearly full: excellent
    } else if pr_frac > 0.60 {
        score += 30.0; // leaving a bin mostly empty is wasteful
    }

    // Lookahead coupling: does next item fit into post residual?
    if next_item_size > 0 {
        if next_item_size as f64 <= pr {
            score -= 45.0; // chainable placement
            // extra reward if next item exactly fills or near-fills
            let nxt_gap = pr - next_item_size as f64;
            if nxt_gap <= 5.0 {
                score -= 40.0;
            }
        } else {
            score += 20.0; // next item won't fit here; dead space likely
        }
        // harmonic match: next item size shares divisibility with post residual
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 35.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing fits are poor and residual is large
        let poor_fit = pr_frac > 0.55 && (next_item_size == 0 || (next_item_size as f64) > pr);
        if poor_fit {
            score -= 70.0;
        } else {
            score += 150.0; // keep using open bins when fits are decent
        }
        // scale with stream maturity: early on, avoid spreading bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 40.0;
    }

    // Open-bin pressure: many open bins -> consolidate (favor larger residuals less)
    if open_bins_count > 4 {
        score += pr_frac * 25.0 * ((open_bins_count as f64) / 10.0).min(1.5);
    }

    // Mean residual context: placing into a bin far from mean residual smooths spread
    let dev = (pr - mean_residual).abs();
    score += dev * 0.3;

    // Current item large relative to residual: good packing, small extra reward
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the smallest plausible item) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }
    // Reward fits that still leave room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize a fit that just barely blocks the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Tightness reward: the smaller post_residual relative to capacity, the better,
    // scaled nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tight * tight;

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins whose residual is below average
    // (i.e., bins that are already quite full get priority).
    score += 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: baseline cost of opening a fresh bin, modulated by
    // how bad the alternatives plausibly are. Penalize more when few bins open.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // A new bin is attractive if the current item plus lookahead fits perfectly.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Base: best-fit preference (smaller leftover => lower score)
    let mut score = post;

    // --- Aggressive 2-step lookahead matching ---
    if next_item_size > 0 {
        if post >= nxt {
            // Next item can chain into this bin's leftover.
            // Reward tight chaining hardest (slack == 0 => perfect 2-step fit),
            // with extra urgency early in the stream when flexibility matters.
            let slack = post - nxt;
            score -= 30.0 * (1.0 - slack / cap) + 12.0 * (1.0 - progress);
        } else {
            // Leftover is dead space for the upcoming item: penalize the
            // mismatch, amplified late in the stream when fragmentation hurts.
            let mismatch = nxt - post;
            score += 0.6 * mismatch + 8.0 * (mismatch / cap) * (1.0 + progress);
        }
    } else {
        // Last item: pure best-fit, slightly favor existing bins.
        score -= 5.0;
    }

    // --- Coupling with mean residual across open bins ---
    // Prefer bins that are tighter than the current average; this steers
    // items toward nearly-full bins and keeps large slacks for large items.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev;

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && !is_new_bin {
        // Strongly reward using the only bin that fits; the tighter the fit,
        // the bigger the reward (up to ~35), avoiding needless new bins.
        score -= 15.0 + 20.0 * (1.0 - (post / cap).min(1.0));
    }

    if is_new_bin {
        // New-bin candidate: penalize spreading items thin, especially when
        // open bins already hold plenty of slack or many bins are open.
        score += 6.0
            + 10.0 * (mean_residual / cap).clamp(0.0, 1.0)
            + 2.0 * open_bins_count as f64;
    } else {
        // Mild consolidation pressure: with many open bins, favor placements
        // that leave little residual behind.
        score -= 0.3 * open_bins_count as f64 * (1.0 - (post / cap).min(1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residuals that are large but unusable.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space in the awkward zone (small but too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 10.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fit_quality = if fitting_bins_count > 0 {
            (bin_residual as f64 - item_size as f64) / bin_capacity as f64
        } else {
            0.0
        };
        // Open a new bin when existing residuals are fragmented and item is large.
        let fragmentation = (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64;
        score += 20.0 + 40.0 * (1.0 - fragmentation) - 15.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 10.0; // large items benefit from fresh bins
        }
        if avg_fit_quality > 0.6 {
            score += 15.0; // discourage new bin when plenty of room exists elsewhere
        }
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    } else {
        // Lookahead coupling: reward placements leaving room for the next item.
        if next_item_size > 0 {
            if post_residual as f64 >= next_item_size as f64 {
                score -= 6.0;
            } else if post_residual > 0 {
                score += 4.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
            }
        }
        // Prefer filling bins that are already relatively full (low residual).
        score += 3.0 * (bin_residual as f64 / bin_capacity as f64);
        // Mild penalty for spreading across many open bins.
        score += (open_bins_count as f64).ln().max(0.0) * 0.5;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let item = item_size as f64 / cap;
    let next = next_item_size as f64 / cap;
    let fit = fitting_bins_count as f64;
    let open = open_bins_count as f64;

    // Base: waste after placement
    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, residual waste matters less; late, minimize dead space aggressively.
    let prog_coupling = pr_norm * pr_norm * (0.5 + 1.5 * progress) * cap;
    score += prog_coupling;

    // Reward tight fits (small post_residual relative to item) with smooth term
    score -= 20.0 * item * (1.0 - pr_norm).powi(2);

    // Penalize bins that leave residual too small for likely future items,
    // smoothly scaled by progress (lookahead matters more early).
    if next > 0.0 && pr_norm > 0.0 {
        let gap = (next - pr_norm).abs();
        score += (1.0 - progress) * 10.0 * (next * pr_norm) * (1.0 - gap.min(1.0));
    }

    // Last-chance bonus: smooth sigmoid-like reward when few fitting bins
    let last_chance = 1.0 / (1.0 + (fit - 1.0) * (fit - 1.0));
    score -= 15.0 * last_chance * (1.0 - pr_norm);

    // Mild penalty for spreading across many open bins, coupled with progress
    score += 2.0 * (open / (1.0 + open)).ln().abs() * (0.5 + progress);

    // Penalize deviation of post-residual from mean residual (keeps bin pool balanced),
    // smoothly damped late in the stream.
    let dev = (pr - mean_residual) / cap;
    score += (1.0 - progress) * 8.0 * dev * dev * cap;

    // New-bin candidate: neutral-ish base, penalize slightly so real bins with
    // good fits win, but keep it competitive when all fits are poor.
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        score += 5.0 + 10.0 * progress * (1.0 - item);
    } else {
        // reward using an existing bin proportionally to how full it becomes
        score -= 6.0 * (1.0 - pr_norm) * (1.0 - pr_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit: perfect closure, strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity fractions.
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let eighth = cap / 8.0;

    // Dead-space penalty: residuals that are tiny but nonzero are wasted.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - pr) / 10.0;
    }

    // Residuals in (10, 25] are semi-usable for small items; mild penalty.
    if post_residual > 10 && post_residual <= 25 {
        score += 15.0;
    }

    // Integer-division thresholds: how many "eighth-slots" remain.
    let slots = post_residual / 12; // ~eighth of capacity
    score -= (slots as f64) * 4.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Reward tight packing with lookahead; penalize if gap is dead space.
            if gap <= 10.0 {
                score -= 120.0 - gap * 4.0;
            } else {
                score += gap * 0.3;
            }
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: make empty bin attractive only when open bins are congested.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64;
        let mean_fit_gap = (mean_residual - item_size as f64).abs();
        // Prefer new bin when open-bin residuals are poorly matched to item.
        score = cap - 40.0 + mean_fit_gap * 0.5 - congestion * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 50.0; // new bin can host item + next item comfortably
        }
    }

    // Mild progression term: later in stream, prefer tighter closures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0;

    // Coupling with mean residual: bins far below mean residual are "dusty" — deprioritize slightly.
    score += (mean_residual - pr).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the waste relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are toxic.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // gap can't hold the known next item
        } else {
            // smooth penalty for medium dead space
            score += 8.0 * (post_residual as f64 / 100.0).powi(2);
        }
    } else {
        // Perfect fill is gold.
        score -= 40.0;
    }

    // Exact match with lookahead: reserve space for next item if it fits perfectly after.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open,
    // encourage consolidation when few bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + 20.0 * progress);
    score += pressure * 3.0;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Prefer reusing open bins unless the current bin would be badly fragmented.
        let fragmented = post_residual > 0 && post_residual < 10;
        if !fragmented && open_bins_count > 0 {
            score += 45.0; // keep using open bins by default
        }
        // Opening a new bin is attractive when open bins have large mean residual
        // but none fits well (many open bins with slack = fragmentation problem).
        if mean_residual > 40.0 {
            score -= 10.0;
        }
        // Late in the stream, avoid accumulating many half-empty bins.
        if progress > 0.7 && open_bins_count > 5 {
            score -= 15.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is below average
    // (they are the "fuller" bins; drain them first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // 2-step lookahead: if the next item exactly fills post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            // next item fits here too: mild bonus, scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - tight / bin_capacity as f64);
        } else {
            // next item does NOT fit in post_residual: penalize wasted potential
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 2.0 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Many open bins: discourage opening yet another bin
    if bin_residual == bin_capacity {
        // new-bin candidate baseline
        score += 20.0 + 3.0 * open_bins_count as f64;
        if next_item_size == 0 {
            score += 100.0;
        }
    }

    // Slight late-stream tightening: prefer packing into existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio penalty (non-linear).
    let waste_frac = post_residual as f64 / cap;
    score += 12.0 * waste_frac * waste_frac;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 18.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize bins whose post-residual can't hold the next item
    // if the next item is large; reward if post-residual matches next item exactly.
    if next_item_size > 0 && next_item_size <= 100 {
        let nx = next_item_size as f64;
        if (post_residual as f64) >= nx {
            score -= 6.0;
            if (post_residual as u32) == next_item_size {
                score -= 20.0; // chained perfect fit
            }
        } else {
            // dead space relative to lookahead
            score += 0.25 * (nx - post_residual as f64);
        }
    }

    // Prefer fuller bins: deviation from mean residual.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Time horizon: late in stream, be greedier about tight fits; early, keep flexibility.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * (1.0 - waste_frac);

    // Many open bins: discourage spreading; few open bins: allow opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early or when open bins are loose, costly late.
        score = 30.0 + 25.0 * t + 0.3 * open_bins_count as f64 - 0.1 * mean_residual;
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 8.0; // next item is large, fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base: prefer small post_residual (tight fit), with mild superlinearity.
    let mut score = post + 0.35 * (post / cap) * post;

    // Smooth non-linear coupling: tight fits matter more as stream progresses.
    score -= 2.5 * (1.0 - progress) * (1.0 - (post / cap)) * (post / cap) * cap * 0.05;

    // Penalize leaving dead space that no plausible item can use later.
    if post > 0.0 {
        let usable_gap = ((post - next_item_size as f64) / cap).max(0.0);
        score += 1.2 * usable_gap * usable_gap * cap;
    }

    // Reward bins whose residual is close to the item (good fill ratio).
    let fill = item_size as f64 / residual.max(1.0);
    score -= 4.0 * fill * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, especially early
    // or when other bins can fit the item; relax late in the stream.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 6.0 + 14.0 * (1.0 - progress) + 10.0 * scarcity * (1.0 - progress);
        // If next item would also fit nicely in a fresh bin, soften slightly.
        if next_item_size as f64 <= post {
            score -= 2.0 * progress;
        }
    }

    // Mild preference for bins with residuals near the stream's mean residual
    // (keeps the bin population homogeneous, easing future packing).
    let dev = (residual - mean_residual) / cap;
    score += 1.5 * dev * dev * cap * 0.1;

    // Slight penalty on opening many bins early.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes modulo 10.
    // Small residues (<10) are "dead space" classes -> penalize strongly.
    let r = post_residual;
    let class = r % 10;
    if r == 0 {
        score -= 60.0; // perfect fit, ideal
    } else if r < 10 {
        score += 45.0; // dead space class
    } else {
        // reward classes that are reusable: residue divisible by common item sizes
        if r % 20 == 0 { score -= 12.0; }
        else if r % 10 == 0 { score -= 8.0; }
        else if r % 5 == 0 { score -= 4.0; }
        else { score += 3.0 + (class as f64); }
    }

    // Integer-division thresholds: how many "medium" items (size ~25) still fit
    let fits_medium = r / 25;
    score -= fits_medium as f64 * 6.0;

    // Lookahead: if next item fits exactly or well into post_residual, reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 70.0; // guaranteed perfect fit next step
        } else if next_item_size <= r {
            let slack = (r - next_item_size) as f64;
            score -= 18.0 - slack * 0.4; // prefer tight lookahead fits
            // harmonic check: post_residual after hypothetical next placement
            let r2 = r - next_item_size;
            if r2 % 10 == 0 { score -= 6.0; }
            if r2 < 10 && r2 > 0 { score += 10.0; }
        } else {
            // next item cannot fit here; bin will likely be closed anyway
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current residuals are fragmented.
    if bin_residual == bin_capacity {
        score = 100.0
            - (mean_residual / bin_capacity as f64) * 30.0
            - (open_bins_count as f64).sqrt() * 4.0;
        // but if existing bins have tiny residuals, opening new bin is fine
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 20.0;
        }
    }

    // Late in stream: prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (r as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Mid-range gaps (10..=20) are only usable by the smallest items; mild penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (exact or near-exact packing).
    if post_residual == 0 {
        score -= 40.0;
    } else {
        score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Open-bins pressure: penalize bins with large residuals when many bins are open,
    // encouraging consolidation into fuller bins.
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive if the item leaves a large usable residual
    // and no open bin fits well; make empty bin slightly unattractive by default.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If the next item could combine with this one in a fresh bin, soften penalty.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
    }

    // Lookahead: bonus if the residual left can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 {
        score += 8.0;
    }

    // Late in the stream, avoid leaving scattered small residuals across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 20 {
        score += 20.0 * progress;
    }

    // Deviation from mean residual: prefer bins whose residual is close to the mean
    // unless the fit is tight (keeps residual distribution balanced).
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain fit: post_residual consumed exactly by next item
        } else if post_residual >= next_item_size {
            // next item fits too: mild reward proportional to leftover after next
            let after_next = post_residual - next_item_size;
            score -= 100.0 - (after_next as f64).min(100.0);
        } else {
            // next item cannot fit in post_residual: penalize wasted capacity
            let waste = next_item_size - post_residual;
            score += (waste as f64) * 2.0;
        }
    }

    // Penalize tiny unusable residuals (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // Prefer opening a new bin early when item is large and residual is loose
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above a good fit, penalized when open bins are fragmented
        score += 50.0 + (open_bins_count as f64) * 2.0 - progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the closer post_residual is to 0, the better.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * (1.0 - tightness * tightness);

    // Penalize leaving dead space that is too small for any typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if next item fits almost exactly (chain fit).
            let chain_gap = post_residual - next_item_size;
            if chain_gap < 5 {
                score -= 8.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit. Penalize the empty-bin candidate
    // proportionally to how much residual space already exists elsewhere.
    if bin_residual == bin_capacity {
        // Base penalty so open bins are usually preferred.
        score += 15.0;
        // But if mean residual across open bins is small (all bins nearly
        // full), opening a new bin becomes attractive.
        score -= mean_residual * 0.5;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If many bins are open, mild preference to consolidate.
        score += (open_bins_count as f64).sqrt() * 2.0;
    }

    // Mild preference for bins with below-average residual (pack fuller bins first),
    // which concentrates waste into fewer bins.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Small penalty for very large items going into nearly-full bins is
    // implicitly handled; add slight preference for filling bins that are
    // already heavily loaded.
    let load_frac = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 5.0 * load_frac * load_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize post residual, with non-linear (quadratic/cubic) shaping
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Smooth coupling of post residual with stream progress: late in stream,
    // tight fits (small post_residual) are increasingly valuable
    let progress_coupling = progress * (1.0 - norm_pr).powi(2);
    score -= 20.0 * progress_coupling * pr;

    // Penalize bins whose residual deviates from mean (non-linear divergence)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev * (0.5 + progress);

    // Reward scarcity of fitting bins smoothly (last-chance bonus)
    let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
    score -= 8.0 * scarcity * (pr + 1.0).ln().max(0.0);

    // Lookahead: reward if next item could fit into post residual (smooth gate)
    if next_item_size > 0 {
        let fits = (next_item_size as f64 <= pr) as f64;
        let slack = 1.0 - ((next_item_size as f64 - pr).abs() / cap);
        score -= 10.0 * fits * slack * (1.0 + progress);
    }

    // Mild penalty for opening new bins when many are open and residual is large
    let is_new = (bin_residual == bin_capacity) as f64;
    score += is_new * (5.0 + 15.0 * progress) * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 5.0)));

    // Encourage using nearly-full bins: cubic in item fraction of residual
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_frac * fill_frac * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "small" classes (0..=10, 11..=20, ...) become progressively less useful.
    let class = post_residual / 10;
    score += (class as f64) * 2.0;

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Tiny dead space (1..=5) is also excellent.
    if post_residual >= 1 && post_residual <= 5 {
        score -= 40.0;
    }

    // Modulo-25 harmonic: residuals that are multiples of 25 pair well with
    // mid-size items (25/50/75).
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Lookahead: penalize leaving a residual that exactly fits the next item
    // only if this bin keeps it (otherwise another bin may take it).
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 8.0; // next item can top-off this bin nicely
        }
        if post_residual > 0 && post_residual < next_item_size {
            score += 4.0; // residual too small for lookahead item: dead space risk
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 100.0 - 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing fits anywhere: must open
        }
        if item_size >= 50 {
            score += 10.0; // large items prefer fresh bins less often
        }
    }

    // Tight-fit bonus: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are nearly unusable
    // for future items (min item size 1, but small gaps waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // heavy penalty for creating tiny dead gaps
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fill is heavily rewarded
    }

    // Reward tight fits: closeness of item to residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Penalize leaving large residual when item is small relative to gap
    // (wasteful placement into a big bin when a tighter bin exists).
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, discourage new bins and
    // encourage consolidation into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when
        // this placement would leave a highly usable residual for lookahead.
        score += 70.0 + pressure * 3.0;
        if next_item_size > 0 {
            let gap = post_residual as i64 - next_item_size as i64;
            if gap >= 0 && gap < 10 {
                score -= 55.0; // new bin perfectly preps the next item
            } else if gap < 0 {
                score += 20.0; // new bin can't host next item anyway
            }
        }
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0; // reward leaving room for the lookahead item
    } else if next_item_size > 0 {
        score += 8.0; // this placement kills the lookahead option here
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect 2-step pairing
        } else if next_item_size <= post_residual {
            // reward proportional to how tightly next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize large dead space mildly
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins)
    let diff = mean_residual - post_residual as f64;
    score -= 0.3 * diff;

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist, but allow it for very tight fits
    if bin_residual == bin_capacity {
        // new bin candidate: penalize unless item is large relative to capacity
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 20.0 * (1.0 - large_item);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 15.0; // good 2-step start in fresh bin
        }
    }

    // Slight preference for early stream consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but heavily reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize leaving dead space that nothing typical can use.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead coupling: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain placement possible; reward proportionally to how snug.
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.3;
        } else if next_item_size <= bin_capacity {
            // Next item won't fit here; mild penalty scaled by how much it misses.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.15;
        }
        // Bonus if next item exactly fills residual (perfect chain).
        if next_item_size == post_residual {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // residuals are small relative to the item or when open bins are congested.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open a new bin when few bins are open or mean residual is low.
        score -= (open_bins_count as f64).ln().max(0.0) * 4.0;
        score += (mean_residual - item_size as f64) * 0.2;
        // Later in the stream, prefer consolidating into existing bins.
        score += t * 25.0;
        // If the item is large, a fresh bin is more acceptable.
        score -= (item_size as f64) * 0.25;
    }

    // Prefer filling bins that are already fairly full (small residual) to compact them.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 8.0;

    // Mild penalty for wasting residual far above mean (fragmentation guard).
    if post_residual as f64 > mean_residual + 20.0 {
        score += (post_residual as f64 - mean_residual - 20.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_norm = pr / cap; // 0..1 residual fraction after placement

    // Base: post residual, mildly non-linear (dead space grows superlinearly in badness)
    let mut score = pr + 12.0 * fit_norm * fit_norm * cap;

    // Tight-fit reward: strong discount as post residual approaches zero
    score -= 30.0 * (1.0 - fit_norm).powi(4);

    // Perfect fit bonus (exact fill)
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = 1.0 - (pr - nxt) / cap; // closer reuse -> higher
            score -= 18.0 * slack * slack;
        } else {
            // next item won't fit: penalize proportionally to overshoot
            let over = (nxt - pr) / cap;
            score += 15.0 * over * over * cap;
        }
    }

    // Stream progress: early on, prefer consolidating into open bins;
    // late in the stream, dead space matters less (fewer future items to place)
    let late_factor = 0.5 + 0.5 * progress;
    score *= late_factor;

    // Scarcity pressure: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a bin, more so when good fits exist
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        score += 25.0 + 40.0 * mean_frac + 20.0 * (1.0 - progress);
    }

    // Mild penalty for bin fragmentation relative to fleet mean residual
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    // Interaction: polynomial coupling of residual and progress
    score += 10.0 * fit_norm * (1.0 - progress) * (1.0 - progress) * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: exact-fill classes are gold
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Reward tight fits (small post_residual) strongly
    score -= (cap - post).ln() * 2.0;

    // Dead-space penalty: residuals that are too small to hold typical items
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Harmonic class: post_residual in {0, cap/2, cap/3, ...} are reusable classes
    let classes = [0u32, 50, 33, 25, 20, 34, 40, 66];
    if classes.contains(&post_residual) {
        score -= 8.0;
    }

    // Modulo-based class matching: if next item could exactly fill post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % next_item_size == 0 {
            score -= 12.0;
        }
        // next item leaves a harmonic residual class
        let next_post = post_residual - next_item_size;
        if next_post < 10 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual {
        // post_residual can't fit next item; penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bin would be badly fragmented
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual > 70 || item > 50.0 {
            score -= 20.0;
        }
    }

    // Late-stream consolidation: fewer open bins preferred as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * progress;

    // Prefer bins below mean residual (fill emptier bins less)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        // Perfect fit is heavily rewarded.
        score -= 40.0;
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += 20.0 * tightness;

    // Open bins pressure: penalize using a bin when many bins are already open,
    // to encourage filling existing bins rather than spreading.
    score += 3.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current bin
    // would leave a large, reusable residual or the item is huge.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 70 {
            score -= 15.0;
        }
    }

    // Lookahead: if next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this residual; dead space is more costly.
        score += 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - post_residual as f64);

    // Stream progression: later in the stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (small dead space).
    score += (post_residual as f64 / bin_capacity as f64) * 30.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can exactly or nearly accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect chain match gets a big bonus.
        if slack == 0.0 {
            score -= 60.0;
        } else {
            // Smaller slack after the chained placement is better.
            score -= 25.0 - slack.min(25.0);
        }
    } else if next_item_size > 0 {
        // Dead space that the next item cannot use: penalize proportionally.
        let wasted = (next_item_size - post_residual) as f64;
        score += wasted.min(40.0) * 0.6;
    }

    // Relative to mean residual: prefer bins that reduce the average
    // residual (consolidating space into fewer bins).
    let mr = mean_residual - post_residual as f64;
    score += mr.clamp(-50.0, 50.0) * 0.4;

    // Last-chance bonus: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item
    // is large relative to capacity or existing bins have poor fit.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let size_ratio = item_size as f64 / bin_capacity as f64;
        // Large items near the end of the stream justify new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bonus = size_ratio * 40.0 + progress * 10.0;
        score += 20.0 + open_pressure * 2.0 - bonus;
    }

    // Mild tie-breaking: prefer bins with less residual overall.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that next item cannot use.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
        } else if next_item_size <= post_residual {
            // Next item fits exactly-ish: reward chain potential.
            let gap = post_residual - next_item_size;
            score -= 20.0 / (1.0 + gap as f64);
        }
    } else {
        // Last item: pack as tightly as possible anywhere.
        score -= 40.0 * fit_ratio;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual <= 10 {
            score -= 20.0; // near-perfect fill on a scarce option
        }
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // fits well or residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize new bins mildly; more when many bins are open and mean
        // residual is high (item likely fits somewhere acceptably).
        score += 10.0 + 30.0 * fragmentation * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        if fitting_bins_count == 0 {
            score -= 45.0; // nothing fits: new bin is correct
        }
    }

    // Prefer bins whose residual deviates from mean in a useful way:
    // filling below-average-residual bins consolidates large gaps.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Mild time-horizon shaping: early on, be conservative about tiny
    // residuals (future large items may need them); later, fill aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual < 10 {
        score -= 12.0 * progress;
        score += 8.0 * (1.0 - progress);
    }

    // Slight penalty for spreading across too many bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post residual and item size
    let r = post_residual as f64 / cap;
    let s = item_size as f64 / cap;

    // Non-linear coupling: penalize large residuals more as stream progresses
    score += 6.0 * r * r * (0.5 + progress);

    // Reward tight fits (small post residual) with smooth polynomial
    score -= 4.0 * (1.0 - r) * (1.0 - r) * s;

    // Interaction of progress with item size: prefer filling big items into existing bins late
    score -= 3.0 * s * s * progress;

    // Dead-space penalty: residuals too small for typical future items
    score += 2.5 * (r * (1.0 - r)) * (1.0 - s);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else {
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (n as u32) <= post_residual {
            score -= 3.0 * (n / cap) * (1.0 - progress);
        } else {
            score += 1.5 * (n / cap) * progress;
        }
    }

    // Mild penalty for opening new bins when many are open and mean residual is high
    if bin_residual == bin_capacity {
        score += 2.0 + 1.5 * (mean_residual / cap) + 0.3 * open_bins_count as f64;
    } else {
        score -= 0.5 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: post_residual modulo small divisors.
    // Residuals in {0, 25, 50, 75} are "harmonic" — they can be filled by
    // quarter-capacity item classes, so reward them.
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    for &d in &[10u32, 20, 25, 40, 50] {
        if pr % d == 0 && pr > 0 {
            harmonic_bonus += cap * 0.12;
        }
    }
    score -= harmonic_bonus;

    // Dead-space penalty: small non-harmonic leftovers are hard to fill.
    if pr > 0 && pr < 10 {
        score += 18.0;
    }

    // Perfect fit is ideal.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does the leftover match the next item's class?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0; // exact chain fit
        } else if pr >= next_item_size {
            // leftover can host next item; the tighter, the better
            score -= 20.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            // next item cannot fit here; penalize by gap size
            score += 6.0 + (next_item_size - pr) as f64 * 0.25;
        }
        // Harmonic divisibility between leftover and next item
        if next_item_size > 0 && pr % next_item_size == 0 && pr > 0 {
            score -= 12.0;
        }
    } else {
        // Last item: prefer tightest fill overall
        score += 0.0;
    }

    // Last-chance bin: if this is the only fitting bin, opening a new bin
    // wastes this residual entirely — strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual
    // is small (poor fit) or many bins are open with high mean residual.
    if bin_residual == bin_capacity {
        let waste = pr as f64; // item placed into fresh bin leaves pr free
        score += 25.0 + waste * 0.5;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 40.0; // next item needs a fresh bin anyway
        }
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0 * (mean_residual / cap);

    // Prefer bins whose residual is below the mean (tighter bins first),
    // keeping looser bins available for larger future items.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits strongly (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64);
        score -= 30.0 * tightness * tightness;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize creating a gap that cannot fit the lookahead item (wasted capacity).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }
    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // making the new-bin candidate (residual == capacity) less attractive.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * open_bins_count as f64;
    } else {
        score -= 3.0 * open_bins_count as f64;
    }

    // Relative residual coupling: bins with residuals near the mean are natural targets.
    score -= 0.1 * (bin_residual as f64 - mean_residual).abs().recip().min(5.0);

    // Late in the stream, waste matters more; be stricter with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for next item -> strong reward
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item fits after this placement: reward closeness
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Post residual too small for next item: penalize dead space
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: minimize final waste harder
        score += 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Penalize large residual relative to mean (avoid leaving oversized gaps)
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Reward tight fits (small post residual)
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: prefer it only when open bins are nearly full / poor fits
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) >= 0 {
            score -= 3.0;
        }
    }

    // Late in stream: consolidate, penalize opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize leaving small, hard-to-use dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0;
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Global-state coupling: many open bins with slack -> prefer reusing bins.
    let pressure = mean_residual / bin_capacity as f64;
    score += 8.0 * pressure * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fill_ratio);

    // New-bin candidate: make empty bins slightly less attractive than a decent fit.
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: reward tight fits via non-linear decay of post-residual
    let mut score = (norm_pr.powi(2) * 60.0) + norm_pr * 20.0;

    // Smooth coupling with stream progress: dead space penalized more later
    score += (norm_pr * progress).powi(2) * 80.0;

    // Penalty if post-residual cannot fit the lookahead item (smooth interaction)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += gap * gap * 40.0 * (0.5 + 0.5 * progress);
        // Reward when lookahead fits snugly
        let snug = 1.0 - ((next_item_size as f64 - pr).abs() / cap);
        score -= snug.max(0.0) * snug * 15.0;
    }

    // Last-chance bonus: few fitting bins, reward using this one
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else {
        score += (fitting_bins_count as f64 - 1.0).min(5.0) * 2.0;
    }

    // Divergence from mean residual: prefer bins near mean (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 25.0;

    // Mild pressure against accumulating many open bins early
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 3.0;

    // New-bin candidate: penalize opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * (mean_residual / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 define "usable" vs "dead" space.
    let r = post_residual % 10;
    // Dead-space penalty: residuals not divisible by 10 waste capacity in future packings.
    score += match r {
        0 => -6.0,          // perfect harmonic class: maximally reusable
        1 | 2 | 3 => 4.0,   // near-dead slivers
        4 | 5 | 6 => 1.5,   // semi-usable
        _ => 2.5,           // 7..9
    };

    // Integer-division thresholds: how many "average" items still fit.
    let avg_item = 55.0f64.max(1.0);
    let quot = (post_residual as f64 / avg_item).floor();
    score -= quot * 1.2;

    // Lookahead coupling: if the next item fits the post residual exactly on a
    // harmonic boundary (mod 10), strongly reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair = post_residual - next_item_size;
        if pair % 10 == 0 {
            score -= 8.0;
        } else if pair % 5 == 0 {
            score -= 3.0;
        }
        // penalize leaving a sliver smaller than the minimum item size
        if pair > 0 && pair < 10 {
            score += 5.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this bin's leftover anyway: mild penalty
        score += 2.0;
    }

    // Last-chance bonus: only one fitting bin -> avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score but must
    // lose to good fits and win over poor fits.
    if bin_residual == bin_capacity {
        score += 12.0;
        // early in stream, opening bins is cheap; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 6.0;
    }

    // Tight-fit reward: post_residual small relative to capacity is excellent.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 4.0;

    // Spread control: bins far from mean residual get slight penalty.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Fit quality: prefer tight fits relative to bin capacity.
    score += 0.6 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Pressure on number of open bins: when many bins are open, favor filling existing ones
    // (penalize the new-bin candidate).
    let open_pressure = open_bins_count as f64 / 10.0;
    if bin_residual == bin_capacity {
        score += 15.0 + open_pressure * 20.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size as f64 > post_residual as f64 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Stream progression: early on, be more willing to open bins (spread risk);
    // later, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary driver: tight fit reward (small post_residual is already low score).

    // 2-step lookahead: perfect match with next item => strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // Next item still fits: mild reward proportional to how well it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use this bin: penalize leftover dead space,
            // worse when post_residual is small (unusable sliver).
            let pr = post_residual as f64;
            if pr < 10.0 {
                score += 25.0 * (1.0 - pr / 10.0);
            }
        }
    }

    // Relative to mean residual: prefer bins already tighter than average.
    score += 0.15 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize opening a new bin unless the item
    // is large relative to capacity (better to pack big items fresh).
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * (item_size as f64 / bin_capacity as f64);
        // Late in the stream, opening fresh bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Small general bonus for high fill ratio of the bin.
    score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual penalty so near-exact fills dominate.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Penalize dead space that cannot hold the next item (lookahead coupling).
    if next_item_size > 0 {
        if (post_residual as u64) < (next_item_size as u64) {
            score += (next_item_size as f64 - post_residual as f64) * 1.5;
        } else {
            // Bonus when residual still accommodates the next item.
            score -= 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin, but allow it
    // when the item would leave a large unusable gap in every open bin.
    if bin_residual == bin_capacity {
        let gap_pressure = (post_residual as f64) / (bin_capacity as f64);
        score += 8.0 + 10.0 * gap_pressure;
        // Early in the stream, opening bins is cheap and keeps flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * (1.0 - progress);
    }

    // Global state coupling: prefer bins whose residual is far from the mean
    // (balance the pool), scaled by number of open bins.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.3 * diff.abs() / (1.0 + open_bins_count as f64);

    // Slight preference for filling fuller bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.1;

    // Penalize bins whose post-residual falls into a "hard zone" (small, unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with smooth non-linear shaping
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, large residuals are acceptable (bins can absorb future items);
    // late in the stream, dead space becomes costly, so penalize x^2/x^3 more.
    let t = progress;
    score += (x * x) * (10.0 + 90.0 * t);
    score += (x * x * x) * (200.0 * t);

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - x) * (1.0 - x) * (5.0 + 25.0 * t);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 40.0 + 60.0 * t;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // next item won't fit here; slight penalty scaled by excess
            score += 0.1 * ((nx - pr) / cap) * 10.0;
        }
    }

    // Mild penalty for opening a new bin when many bins already fit the item
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 12.0 + 30.0 * (1.0 - t);
    }

    // Coupling with mean residual: bins far from mean residual are slightly
    // deprioritized to keep residual distribution balanced (smooth quadratic)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev * (0.5 + t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // in [0, 1]

    // Class the post residual into harmonic bins (modulo-style classes of 10 units).
    let class = post_residual / 10; // 0..10 integer class
    let class_center = (class * 10 + 5) as f64;

    // Penalize residuals that fall into "unusable" classes: small but nonzero dead space.
    // Dead space in (0, 10) is nearly unusable for items >= 1..100 unknown distribution.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Harmonic penalty: distance from class center, scaled by class.
        let dist = (post_f - class_center).abs();
        score += 0.15 * dist;
        // Quadratic coupling on fraction of capacity wasted.
        score += 30.0 * frac * frac;
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Great: chain placement possible. Reward proportionally to tightness of chain fit.
            let chain_tightness = 1.0 - (post_residual - next_item_size) as f64 / cap_f;
            score -= 20.0 * chain_tightness;
        } else {
            // Next item won't fit here; penalize more if the leftover is small dead space.
            let waste = post_residual as f64;
            score += 0.1 * waste;
        }
    } else {
        // Last item: prefer zero residual.
        score -= 10.0 * (1.0 - frac);
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // offers a good fit. Give the empty bin a baseline near its residual (capacity),
    // adjusted by stream progression and congestion.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: capacity minus item fills a bit.
        score = cap_f * 0.9;
        // Early in stream or many open bins: opening is cheaper (spread load).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // If existing bins are congested (low mean residual), opening is better.
        score -= 0.5 * (cap_f - mean_residual).max(0.0);
        // If item is large relative to capacity, opening a fresh bin is natural.
        score -= 0.2 * item_size as f64;
        // If next item is large too, a fresh bin can host the pair.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
    } else {
        // Existing bin: reward tightness relative to current residual.
        let fit_tightness = 1.0 - (post_f / (bin_residual as f64).max(1.0));
        score -= 10.0 * fit_tightness;
        // Slight penalty for spreading across too many bins.
        score += 0.3 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (size 1) are fine, but gaps that are small
    // relative to typical item sizes are wasted. Penalize "awkward" gaps
    // (nonzero but tiny) super-linearly.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - pr) * 12.0; // unusable sliver penalty
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit is ideal
    } else {
        // Mild preference for larger usable leftovers.
        score -= (pr / bin_capacity as f64) * 4.0;
    }

    // Lookahead: reward bins whose post_residual can still host next_item_size.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64) * 0.05;
    } else if next_item_size > 0 {
        score += 5.0; // bin becomes dead after this placement
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fits
    // and make the new-bin candidate (residual == capacity) less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        score += 6.0 + pressure * 1.5;
    } else {
        score -= pressure * 0.5;
    }

    // Deviation from mean residual: prefer bins below-average residual (fuller bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits perfectly after this placement: big reward
            let leftover = post_residual - next_item_size;
            score -= 10.0 + 0.5 * (leftover as f64).min(20.0);
            // bonus if next item exactly fills bin
            if leftover == 0 {
                score -= 15.0;
            }
        } else {
            // next item would not fit here: penalize leaving large unusable gap
            let gap = (post_residual as f64) - (next_item_size as f64);
            score += 0.15 * gap.max(0.0);
        }
    }

    // Penalize deviating far from mean residual (keep bin pool balanced)
    let dev = (post_residual as f64) - mean_residual;
    score += 0.08 * dev * dev;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        // scale penalty by stream progress: early on, allow more bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 + 15.0 * progress;
        // but if item is huge and nothing else fits well, new bin is fine
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // Slight preference for filling fuller bins as stream progresses
    score -= 0.05 * (bin_residual - post_residual) as f64 * (1.0 + 0.5 * (1.0 - (open_bins_count as f64).ln().max(0.0)));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Bonus if post-residual is a good fit for the next item too.
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let late = step_index as f64 / (total_items as f64).max(1.0);
        score += 30.0 - 20.0 * pressure - 10.0 * late;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate space).
    score += 0.05 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Time horizon: as stream progresses, favor tighter packing.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (small post_residual), scaled by progress
    let mut score = pr * (0.6 + 1.4 * progress);

    // Non-linear coupling: quadratic + cubic terms of normalized residual
    score += 12.0 * x * x * (1.0 + progress);
    score -= 8.0 * x * x * x * progress;

    // Penalize residuals that are small but unusable for the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = if pr >= nx { 1.0 } else { 0.0 };
        // smooth version: how close the residual is to fitting the next item
        let gap = (nx - pr).max(0.0) / cap;
        score += 15.0 * gap * gap * (1.0 - usable * 0.5);
        // reward residuals that will fit the next item, more later in the stream
        score -= 6.0 * usable * (1.0 - progress);
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 10.0 + 20.0 * progress;
    } else {
        // mild penalty when many bins compete, discourage scattering
        score += 0.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Interaction with mean residual: prefer bins below mean residual (tighter)
    score += 0.4 * (mean_residual - pr);

    // New-bin candidate handling: empty bin gets a moderate penalty so it only
    // wins when all alternatives are bad (large post_residual elsewhere)
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "usable" sizes.
    let post = post_residual as i64;
    let residue = (post % 10) as i64;

    // Dead-space penalty: residuals in (0,10) are nearly unusable for items >=10.
    if post > 0 && post < 10 {
        score += 25.0 + (10 - post) as f64 * 2.0;
    }

    // Reward post_residuals that are exact multiples of 10 (harmonic fits).
    if residue == 0 && post > 0 {
        score -= 8.0;
    }
    // Penalize awkward residues (7,3) which rarely match future item sizes.
    if residue == 3 || residue == 7 {
        score += 4.0;
    }
    if residue == 5 {
        score -= 2.0; // half-capacity fractions are moderately useful
    }

    // Integer-division thresholds: classify post_residual into bands.
    let band = post / 25; // 0..4
    match band {
        0 => score += 6.0,          // tiny leftover: risky
        1 => score -= 1.0,          // 25..49
        2 => score -= 3.0,          // 50..74: very flexible
        _ => score -= 2.0,          // 75+: near-empty bin
    }

    // Coupling with next item: check if next item fits the post residual exactly or closely.
    if next_item_size > 0 {
        if next_item_size as i64 == post {
            score -= 20.0; // perfect lookahead fit
        } else if (post as u32) >= next_item_size {
            let slack = post - next_item_size as i64;
            // Reward small slack after accommodating the next item.
            score -= (10.0 - (slack as f64).min(10.0)) * 0.8;
        } else {
            // Next item cannot fit here; penalize proportionally to the miss.
            score += ((next_item_size as i64 - post) as f64).min(30.0) * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default score so it
    // is chosen only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score = 60.0 - (post_residual as f64) * 0.1;
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: must open new bin
        }
    } else if fitting_bins_count == 0 {
        score += 100.0; // shouldn't happen for a non-fitting open bin, guard anyway
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    // Slight progression-aware tiebreak: prefer tight fits early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (bin_residual - item_size) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Medium gaps (10..30) are only useful for tiny items; mild penalty.
    if post_residual >= 10 && post_residual < 30 {
        score += 0.5 * post_residual as f64;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: make empty bin attractive only when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened by stream progression.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 + 20.0 - 10.0 * progress;
        // If several bins fit, discourage opening a new one.
        score += 8.0 * (fitting_bins_count as f64).min(5.0);
        // Lookahead: if next item could combine with current item's leftover, new bin is fine.
        if next_item_size > 0 {
            let combo = item_size + next_item_size;
            if combo <= bin_capacity {
                score -= 25.0;
            }
        }
    } else {
        // Existing-bin lookahead: if placing here leaves room for the next item, reward it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        // Penalize bins whose residual deviates badly from the mean (fragmentation signal).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Penalize wasted dead space: small post_residual that can't fit next item.
    if next_item_size > 0 && post_residual < next_item_size {
        // dead space relative to capacity
        score += (post_residual as f64 / bin_capacity as f64) * 30.0;
        // extra penalty if dead space is tiny (very unusable)
        if post_residual < 10 {
            score += 20.0;
        }
    } else if next_item_size > 0 && post_residual > next_item_size {
        // leftover still usable by next item: mild reward proportional to closeness
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 / (1.0 + slack / 20.0);
    }

    // Last-chance bin: strongly prefer filling it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Compare against mean residual: bins tighter than mean are better to fill.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Prefer filling nearly-full bins (small residual) more aggressively.
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Early in stream, be more willing to open new bins (keep flexibility).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheaper early, expensive late.
        score -= 40.0 * (1.0 - progress);
        score += 30.0 * progress;
    }

    // Many open bins: discourage spreading; few open bins: encourage consolidation.
    if open_bins_count > 3 {
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual < 10 {
