    } else if post_residual < 20 {
        score += 2.5;
    }

    // Lookahead coupling: bonus if the next item fits the post-residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit here; mild penalty for wasting this residual.
        score += 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer filling bins when many bins are open (consolidation pressure).
    score -= (open_bins_count as f64).ln().max(0.0) * 0.8 * tightness;

    // Mean-residual deviation: prefer bins whose residual is below average (more filled).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 4.0 * dev;

    // Time horizon: early in the stream, be pickier (penalize mediocre fits);
    // late in the stream, accept placements more readily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin should only win when the fit
    // into existing bins is poor or no bin is a last chance.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 14.0;
        // Cheaper to open a new bin when many bins are already open and fragmented.
        score -= 0.35 * (open_bins_count as f64).sqrt();
        // If the item is large, a fresh bin gives flexibility for the future.
        if item_size > bin_capacity / 2 {
            score -= 5.0;
        }
        // If the next item is large too, a fresh bin is attractive.
        if next_item_size > bin_capacity / 2 {
            score -= 4.0;
        }
        // But if this is the only fitting bin, don't open a new one.
        if fitting_bins_count == 1 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * (1.0 + 0.8 * progress * norm_pr) - 0.3 * progress * norm_pr * norm_pr;

    // Penalize dead space more when few bins can fit the item (last-chance bin).
    let last_chance = if fitting_bins_count == 1 { -2.5 } else { 0.0 };

    // Reward tight fits: item_size relative to residual.
    let tight = (item_size as f64 / bin_residual as f64).powi(2) * 3.0;

    // Lookahead: penalize if post_residual can't fit next item.
    let look = if next_item_size > 0 && (next_item_size as f64) > pr {
        1.5 + 0.5 * progress
    } else if next_item_size > 0 {
        -1.0 * (1.0 - pr / cap)
    } else {
        0.0
    };

    // Slight preference to keep mean residual balanced.
    let balance = (mean_residual - pr) * 0.02;

    // New-bin candidate baseline: keep it mildly attractive only when residuals are poor.
    let is_new = if bin_residual == bin_capacity { 6.0 - 4.0 * progress } else { 0.0 };

    let mut score = pr + 10.0 * poly - tight + look + balance + last_chance + is_new;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let pr = post_residual;
    // Dead-space penalty for tiny unusable residuals (below smallest plausible item)
    if pr > 0 && pr < 5 {
        score += 60.0;
    }
    // Class bins into harmonic bands: quarter/half thresholds of capacity
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if pr >= half {
        score -= 25.0; // bin still very usable
    } else if pr >= quarter {
        score -= 10.0;
    } else if pr > 0 {
        score += 15.0; // small residual, risky dead space
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // reward proportional to how well next item fills the remainder
            let fill = next_item_size as f64 / pr.max(1) as f64;
            score -= 40.0 * fill;
        } else {
            // post_residual can't host next item: penalize if residual is small
            score += 10.0 + (pr as f64) * 0.05;
        }
    }

    // Last-chance bin logic: if this is the only fitting bin, avoid forcing new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score with exploration bias
    if bin_residual == bin_capacity {
        // Prefer opening new bin only when existing residuals are fragmented
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 40.0 + 0.5 * open_bins_count as f64 - fragmentation * 0.1;
        // Early in stream, opening new bins is cheap and useful
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    } else {
        // Reward tighter fits relative to mean residual
        let tightness = 1.0 - (post_residual as f64 / cap);
        score -= 20.0 * tightness;
        // Penalize bins deviating from mean residual (keep balanced portfolio)
        score += 0.15 * (bin_residual as f64 - mean_residual).abs();
    }

    // Harmonic modulo bonus: residuals divisible by common item sizes (10, 20, 25, 50)
    if pr % 10 == 0 { score -= 12.0; }
    if pr % 25 == 0 { score -= 8.0; }
    if pr % 50 == 0 { score -= 10.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small residual just above the minimum item size is also risky dead space.
    if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }
    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer new bin only when fit is poor.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 0.05 * open_pressure * (post_residual as f64 / 10.0);

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // If next item fits into post_residual, mild reward; if it would be blocked, penalize small gaps.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 12.0 * (post_residual as f64 / 30.0);
    }

    // New-bin candidate: make it attractive only when the current fit is poor or few bins exist.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > (bin_capacity as f64 - item_size as f64) * 0.75;
        if poor_fit || open_bins_count == 0 {
            score -= 30.0;
        } else {
            score += 25.0;
        }
    }

    // Late in the stream, consolidate: penalize leaving loose residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / 50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: prefer bins where the item fills most of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: reward if next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: penalize leftover dead space after the pair.
            let pair_left = post_residual - next_item_size;
            score -= 15.0;
            score += 0.4 * pair_left as f64;
        } else {
            // Next item won't fit here: penalize, worse if post_residual is small (dead space).
            score += 8.0;
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Compare against mean residual: prefer bins already tighter than average.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of open bins fit the item,
    // unless the fit is very tight (near-perfect packing).
    if bin_residual == bin_capacity {
        let perfect = item_size == bin_capacity;
        let near = post_residual <= 5;
        if perfect || near {
            score -= 20.0;
        } else {
            score += 20.0 + 0.3 * open_bins_count as f64;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual - post_residual) as f64 / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly
    let dead = post_residual as f64;
    score += 0.05 * (dead / 10.0).powi(2) * (dead / bin_capacity as f64);

    // Reward tight fits (small post residual relative to item)
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness * tightness;

    // Lookahead: reward if next item fits in post residual (chain packing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            score -= 0.2 * (post_residual - next_item_size) as f64;
        } else {
            // penalize leaving a gap next item cannot use
            score += 6.0;
        }
    } else {
        // last item: just minimize waste
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins with high mean residual: prefer consolidating into fuller bins
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Favor bins that are already quite full (residual small) to compact load
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Time horizon: early on, allow opening new bins (favor low score for empty bin when few bins);
    // late in stream, discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new bin candidate: base penalty grows with progress and number of open bins
        score += 30.0 * progress + 1.5 * open_bins_count as f64;
        // but early on with no fitting bins, new bin is fine
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr = post_residual as f64 / cap;
    let it = item_size as f64 / cap;

    // Smooth non-linear coupling: dead-space penalty grows quadratically with
    // post_residual, amplified as the stream progresses (late-stage fragmentation
    // is more costly since fewer items remain to fill gaps).
    let dead_space = pr * pr * (1.0 + 2.0 * progress);
    score += 60.0 * dead_space;

    // Reward tight fits: small positive post_residual gets a smooth bonus
    let tightness = (-pr * 8.0).exp();
    score -= 25.0 * tightness * (0.5 + progress);

    // Reward large item consumption (packing big items early is valuable)
    score -= 20.0 * it * it;

    // Lookahead coupling: if the next item fits exactly into the resulting
    // post_residual, strongly favor this bin (smooth gaussian proximity).
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let fit_next = (-gap * gap / 50.0).exp();
        score -= 30.0 * fit_next;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // penalize alternatives implicitly by rewarding this one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more so early on
    // when open bins should be consolidated; also scale with open bin count.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln();
        score += 15.0 + 8.0 * openness * (1.0 - 0.5 * progress);
    } else {
        // Slight preference for bins whose residual deviates from the mean
        // (diversify residual sizes to create complementary gaps).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 5.0 * dev * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is ideal.
    score -= 60.0 * (1.0 - (post_residual as f64) / cap).max(0.0);

    // Penalize dead space in small fragments (wasted capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Harmonic class logic: quantize post_residual into capacity-eighths.
    let class = (post_residual * 8) / bin_capacity;
    score += match class {
        0 => -40.0,                 // near-full bin, excellent
        1 => -15.0,                 // good fit
        2 => 5.0,                   // mediocre
        3 => 15.0,                  // half-empty: risky
        _ => 30.0,                  // mostly empty: wasteful placement
    };

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item chains nicely; reward proportionally to snugness.
            let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 35.0 * snug;
        } else {
            // Next item won't fit: this placement strands the bin.
            score += 20.0;
        }
        // Harmonic pairing: next_item_size divides residual class nicely
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 12.0;
        }
    } else {
        // Last item: prefer filling an existing bin fully.
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless
    // the item is huge and no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / cap;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Base penalty for opening a new bin...
        score += 70.0;
        // ...but relieve it when item is large or nothing fits anywhere.
        score -= 80.0 * pressure * (0.5 + 0.5 * scarcity);
        // If next item is also large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 25.0;
        }
    }

    // Mild stream-phase term: early on, tolerate more bins; late, consolidate.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * (1.0 - phase) * ((post_residual as f64) / cap);

    // Deter spreading across many open bins when mean residual is already low.
    if (post_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // smallest plausible item (or the known next item) are worthless.
    let min_gap = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual > 0 && (post_residual as u64) < (min_gap as u64) {
        score += 25.0 + 0.5 * (min_gap as f64 - post_residual as f64);
    }

    // Perfect / near-perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward bins whose residual tightly matches the item (small slack ratio).
    let fit_tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_tightness;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 5.0;
        } else {
            // dead space relative to known next item
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading into more bins
    // unless the fit is good; few open bins -> new bins are cheaper.
    score += 0.6 * open_bins_count as f64 * (1.0 - fit_tightness);

    // Slight bias toward filling bins below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Early in the stream, opening new bins is less costly (better long-term
    // structure); late in the stream, avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 12.0 * progress - 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact-ish fits: small post_residual is good.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            // next item fits: reward proportional to how tight the leftover would be
            let second_left = post_residual - next_item_size;
            score -= 60.0 - (second_left as f64) * 0.8;
        } else {
            // next item cannot fit here: penalize more if post_residual is small dead space
            if post_residual < 10 {
                score += 30.0;
            }
        }
    }

    // Prefer bins whose residual is below mean (tight bins get filled first),
    // leaving loose bins flexible.
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.5;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= 30 {
        score -= 80.0;
    }

    // New empty bin candidate: penalize unless current bins fit badly.
    if bin_residual == bin_capacity {
        score += 90.0;
        // If nothing else fits well, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // Early in stream, new bins are cheaper to open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Slight preference to fill more-opened bins when many are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward good fits strongly (non-linear).
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Dead-space penalty: post residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0 + 0.2 * next_item_size as f64;
    } else if next_item_size > post_residual {
        score += 5.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // Mean residual coupling: prefer bins near the mean (keeps residuals uniform).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in stream, be more willing to open new bins; late, consolidate.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;

    // New-bin candidate baseline: its post_residual is huge, add a dynamic offset.
    if new_bin > 0.0 {
        score += 60.0 - 70.0 * t + 4.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0 * (1.0 - t);
        }
    }

    // Congestion: many open bins -> penalize opening more, reward filling existing.
    score += new_bin * 3.0 * open_bins_count as f64;
    if new_bin == 0.0 {
        score -= 2.0 * open_bins_count as f64;
    }

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with a convex penalty for large waste.
    let mut score = pr * (1.0 + 0.9 * norm_pr * norm_pr);

    // Non-linear coupling of post_residual with stream progress:
    // early on, keep residual flexible; later, reward compacting bins harder.
    let progress_coupling = 1.0 + 0.8 * progress * (1.0 - progress) * 4.0;
    score *= progress_coupling;

    // Interaction: squared normalized post_residual scaled by progress —
    // dead space is punished more strongly as the stream advances.
    score += 40.0 * norm_pr * norm_pr * progress;

    // Penalize near-full-but-wasteful outcomes when they can't serve the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            let unusable = (nx - pr) / cap;
            score += 25.0 * unusable * (0.5 + progress);
        } else {
            // Reward bins that can still host the lookahead item.
            score -= 6.0 * (1.0 - norm_pr) * (0.3 + 0.7 * progress);
        }
    } else {
        // Last item: maximize compaction.
        score -= 10.0 * (1.0 - norm_pr);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, scaled by how well it fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        let fit_quality = 1.0 - norm_pr;
        score -= 30.0 + 20.0 * fit_quality * (1.0 - progress);
    }

    // Mild penalty when many bins are open and this placement wastes space,
    // encouraging consolidation.
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // Relative waste vs. mean residual: avoid leaving this bin far above average waste.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate: make it moderately attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        score = 55.0 - 15.0 * progress - (fitting_bins_count as f64) * 2.0;
        if next_item_size > 0 {
            let nx = next_item_size as f64;
            let room = ((cap - nx) / cap).max(0.0);
            score += 10.0 * (1.0 - room);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes over capacity fractions
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward near-perfect fits strongly
    if pr == 0 {
        score -= 1000.0;
    } else if pr <= eighth {
        score -= 60.0;
    } else if pr <= quarter {
        score -= 20.0;
    } else if pr > bin_capacity - quarter {
        // huge leftover: penalize dead space
        score += 25.0;
    }

    // Modulo-class penalty: residuals that are awkward (small odd remainders) are dead space
    let m = pr % 10;
    if pr > 0 && m != 0 && m < 5 {
        score += 8.0 + (5 - m) as f64;
    }
    // Residuals expressible as common item sizes are reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 10.0;
    }

    // Lookahead: prefer bins whose post_residual can host the next item
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 15.0 + next_item_size as f64 * 0.2;
        } else {
            score += 12.0;
        }
        // Harmonic pairing: next item exactly divides residual class
        if pr > 0 && next_item_size <= pr && pr % next_item_size.max(1) == 0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a mild baseline so poor fits
    // on open bins are avoided, but not so good that we always open bins
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
        // open new bin if current item is small relative to mean residual spread
        if mean_residual > cap * 0.5 {
            score -= 10.0;
        }
    }

    // Progress-based tightening: late in stream, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64).abs() * 0.1;
    score += progress * 5.0 * (open_bins_count as f64).ln().max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fit
    } else if post_residual <= 10 {
        // gap too small for most items: strongly penalize
        score += 40.0;
    } else if post_residual < item_size {
        // moderately small gap: mild penalty scaled by how unusable it is
        let unusability = 1.0 - (post_residual as f64) / (item_size.max(1) as f64);
        score += 15.0 * unusability;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity, so penalize it.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 / 10.0).min(3.0);
        score += 25.0 + 20.0 * pressure;
    } else {
        // Slight preference for bins with less residual (fill emptier bins first)
        score += 0.05 * (bin_residual as f64);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 35.0;
            } else {
                score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
            }
        } else {
            // next item won't fit here; penalize leaving a gap next item can't use
            score += 8.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual when many bins open.
    score += 0.1 * ((bin_residual as f64) - mean_residual) * (open_bins_count as f64).sqrt().min(3.0);

    // Late-stream consolidation: near the end, favor closing out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 {
        score -= 5.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post residual), slightly superlinear.
    score += (post_residual as f64 / cap) * 12.0;

    // 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        // Exact match is a jackpot.
        if gap < 0.5 {
            score -= 25.0;
        } else if post_residual as f64 >= nxt {
            score -= 14.0 * (1.0 - gap / cap);
        } else {
            // Next item won't fit here; penalize dead space more.
            score += 6.0 + 10.0 * (gap / cap);
        }
    }

    // Relative-to-mean-residual coupling: prefer bins with residual near the mean
    // (balanced packing), punish extreme outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive late in stream or when current fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = (post_residual as f64 > cap * 0.5) as f64;
        score += 30.0 - 15.0 * progress - 12.0 * bad_fit;
    }

    // Mild preference for filling fuller bins when many bins are open.
    score -= 0.05 * open_bins_count as f64 * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor small post residuals (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize unusable dead space: residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.1 * next_item_size as f64;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large item relative to residuals) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_pressure = item_size as f64 / mean_residual.max(1.0);
        let openness = if fit_pressure > 0.8 { -20.0 } else { 10.0 + 15.0 * (1.0 - fit_pressure) };
        score += openness - 5.0 * progress;
    }

    // Mild preference for filling bins with lower residual than the mean.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Prefer bins that are already somewhat filled (avoid scattering).
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += 40.0 * norm_pr * norm_pr * (1.0 + progress);
    score -= 25.0 * norm_pr * (1.0 - progress);

    // Dead-space penalty: small post-residuals that can't fit typical future items
    if pr > 0.0 && (next_item_size as f64) > pr {
        score += 12.0 * (1.0 - pr / cap) * (0.5 + 0.5 * progress);
    }

    // Lookahead synergy: reward bins whose post_residual fits the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 18.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild diversity pressure relative to mean residual
    score += 3.0 * (pr - mean_residual) / cap;

    // New-bin candidate: penalize slightly so it's chosen only when open bins are poor
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // granularity (e.g. 10) are more reusable than prime-like leftovers.
    let r = post_residual;
    if r > 0 {
        let harmony = if r % 10 == 0 {
            -14.0
        } else if r % 5 == 0 {
            -7.0
        } else if r % 2 == 0 {
            -3.0
        } else {
            4.0
        };
        score += harmony;
    }

    // Dead-space penalty: tiny residuals are nearly unusable.
    if r < 10 && r > 0 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if r == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= r {
            // Prefer residuals that can host the next item, especially near-exact.
            let slack = (r - next_item_size) as f64;
            score -= 12.0 - slack * 0.08;
            if (r - next_item_size) % 10 == 0 {
                score -= 5.0; // harmonic chaining
            }
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Capacity-fraction thresholds on the item's class.
    let item_frac = item_size as f64 / bin_capacity as f64;
    if item_frac > 0.5 {
        // Big items: prefer fresher bins (large residual) to avoid fragmentation.
        score += (bin_residual as f64 - item_size as f64) * 0.05;
    } else if item_frac < 0.2 {
        // Tiny items: prefer bins with small residuals to consolidate.
        score += (post_residual as f64) * 0.15;
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline: opening a new bin should cost roughly the wasted capacity
        // it incurs relative to packing into an existing bin.
        score = bin_capacity as f64 * 0.62;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        } else if next_item_size > 0 && next_item_size > mean_residual {
            // Next item is large: a fresh bin may serve it better.
            score -= 10.0;
        }
        // Fewer open bins early in the stream -> cheaper to open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0 - open_bins_count as f64 * 0.5;
    }

    // Mild tie-break toward bins below the mean residual (consolidation).
    if !is_new_bin {
        score += (mean_residual - bin_residual as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are worthless; penalize gaps below the typical item threshold heavily.
    let dead_threshold: f64 = 9.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Penalize mid-range unusable gaps: post_residual in [10..19] is a poor fit zone
    // for many distributions; add graded penalty.
    if post_residual >= 10 && post_residual < 20 {
        score += 2.5;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 3 {
        score -= 6.0;
    }

    // Open-bin pressure: discourage spreading across many bins; slight penalty
    // scaled with open_bins_count relative to stream length.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).powf(0.5) * (0.6 + 0.8 * progress);

    // Lookahead: if the next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
        // Extra reward for a tight chain (next item nearly fills the remainder).
        if post_residual - next_item_size <= 5 {
            score -= 3.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot follow here; penalize slightly more for small leftovers.
        if post_residual < next_item_size && post_residual < 15 {
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
        if post_residual > 40 {
            score += 3.0; // wasteful use of a large bin when it's last chance
        }
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // current fit is very poor. Penalize the empty-bin candidate mildly by default.
    if bin_residual == bin_capacity {
        score += 8.0;
        // But if mean residual across open bins is large (lots of slack exists),
        // opening new bins is cheaper; reduce penalty.
        if mean_residual > 40.0 {
            score -= 6.0;
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual is below mean
    // (tighter bins get priority).
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect two-step match: post_residual == next_item_size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Reward partial lookahead fit, scaled by how close next item comes to filling residual.
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize dead space that the next item cannot use.
        let waste = (next_item_size - post_residual) as f64;
        score += 1.5 * waste;
    }

    // Penalize large absolute dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Reward filling bins tighter than the current mean residual.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Discourage opening a new bin unless it enables a perfect 2-step chain.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 500.0;
        } else {
            score += 40.0;
        }
    }

    // Late in the stream, favor closing out bins (reduce residual more aggressively).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect follow-up fit: this residual exactly hosts the next item.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Residual too small for the lookahead item: dead space penalty scaled by waste.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }
    // Residual can host lookahead with room to spare: mild reward.
    if next_item_size > 0 && post_residual >= next_item_size + 10 {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Brand-new empty bin candidate: penalize so existing bins win unless fit is bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.05 * open_bins_count as f64;
        // But if this bin would be the only fitting one anyway, the +15 is offset by tightness.
        if item_size >= 50 {
            score -= 10.0; // large items: fresh bin less wasteful
        }
    } else {
        // Reward bins tighter than average (relative best-fit pressure).
        if (bin_residual as f64) < mean_residual {
            score -= (mean_residual - bin_residual as f64) * 0.3;
        }
    }

    // Late in the stream: avoid opening new bins, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    // Exact fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling: penalize small residuals more as stream progresses
    let squeeze = (1.0 - norm_pr).powi(2) - (1.0 - norm_pr).powi(3);
    score -= 40.0 * squeeze * (0.5 + t);

    // Penalize wasted dead space quadratically relative to capacity
    score += 12.0 * norm_pr * norm_pr * (1.0 - t);

    // Lookahead coupling: reward bins whose post-residual fits the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_ratio = next_item_size as f64 / pr.max(1.0);
        score -= 25.0 * (1.0 - fit_ratio) * (0.3 + 0.7 * t);
    } else if next_item_size > 0 {
        score += 8.0 * t;
    }

    // Last-chance bin bonus (smoothly scaled)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - t * 0.5);
    }

    // Spread-awareness: prefer bins deviating from mean residual smoothly
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev - 6.0 * dev * (1.0 - t);

    // Mild preference for filling existing bins vs opening new ones late in stream
    if bin_residual == bin_capacity {
        score += 20.0 * (0.5 + t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: small dead space classes are prized.
    // Class by integer division into bands of capacity/8.
    let band = bin_capacity / 8;
    let post_class = post_residual / band;
    let class_bonus: [f64; 9] = [16.0, 12.0, 8.0, 5.0, 3.0, 2.0, 1.0, 0.5, 0.0];
    score -= class_bonus[(post_class as usize).min(8)];

    // Exact-fit reward (post_residual == 0 or tiny)
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: reward if next item fits into post_residual (chain packing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // extra reward for near-perfect chain (next fills residual almost exactly)
            let chain_gap = post_residual - next_item_size;
            if chain_gap <= 5 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual: penalize large stranded residual
            let frac = post_residual as f64 / cap;
            if frac > 0.3 {
                score += 6.0 * frac;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // mild tie-break toward tighter bins handled by base score already
        score += 0.5 * (fitting_bins_count as f64 - 1.0).min(3.0);
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are all poor.
    if bin_residual == bin_capacity {
        let mut base_penalty = 25.0;
        // If mean residual is large (poorly packed open bins), opening new bin is worse.
        base_penalty += 0.5 * mean_residual;
        // Later in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        base_penalty += 10.0 * progress;
        // Large items prefer fresh bins slightly more often.
        if item_size > 60 {
            base_penalty -= 12.0;
        }
        score += base_penalty;
    }

    // Prefer bins with residual close to item (tight fit) via modulo structure:
    let tightness = (bin_residual - item_size) as f64;
    score += 0.05 * (tightness % 10.0);

    // Slight preference for bins whose residual is in a "harmonic" residue class of item size
    if item_size > 0 && bin_residual % item_size == 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item (<= ~15) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0;
    }
    // Residuals in the "awkward" band (15..=30) are semi-dead unless a known
    // next item can use them; apply a moderate penalty.
    else if post_residual >= 15 && post_residual <= 30 {
        score += 12.0;
    }

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the resulting post_residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item cannot fit here, the residual risks becoming dead space;
    // scale penalty with how close the residual is to being unusable.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many bins open, discourage spreading; with few
    // bins, opening a new one is cheap. New-bin candidate gets a baseline.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        // Late in the stream, avoid opening new bins with small leftovers pending.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Mild pressure to consolidate into fewer bins when many are open.
        score += 0.3 * open_bins_count as f64;
    }

    // Prefer bins with residual near the mean (keeps residual distribution tight).
    score += 0.15 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.6;

        if post_residual == next_item_size {
            score -= 40.0; // chain perfect fit
        }
        // Penalize residual that can't fit the next item (dead space risk),
        // unless the residual is small enough to be "closed".
        if post_residual < next_item_size {
            if post_residual >= 10 {
                score += 15.0;
            } else {
                score -= 10.0; // tiny residual is effectively a closed bin
            }
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bins fit poorly (large leftover relative to item).
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 20.0;
        // But if item leaves huge waste in any existing bin context, new bin
        // becomes attractive: reward proportional to item largeness.
        score -= (item_size as f64 / bin_capacity as f64) * 30.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Slight preference to fill bins with larger residuals when many bins open.
    score -= (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits: small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 * (next_item_size as f64 / 100.0);
    }
    // Penalize leaving residual too small for the (large) next item
    if next_item_size > post_residual && next_item_size > 0 {
        score += 10.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }
    // Multiple fitting bins: mild penalty to preserve flexibility, prefer emptiest
    if fitting_bins_count > 1 {
        score += 5.0;
    }

    // New-bin candidate handling: only open a new bin if this is a last chance
    // elsewhere or residuals are badly fragmented
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64);
        let late = step_index as f64 / total_items.max(1) as f64;
        // Early on, opening bins is cheap; later, prefer reusing open bins
        score += 80.0 - 60.0 * late;
        // If mean residual across bins is large, reuse them instead
        score += pressure * 30.0;
        if fitting_bins_count <= 1 {
            score -= 200.0;
        }
    }

    // Prefer filling bins with large residual (consolidate fragmentation)
    score -= (bin_residual as f64 - item_size as f64).max(0.0) * 0.1;

    // Penalize creating dead space below the smallest plausible item late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 30.0 * progress;
    }

    // Mild penalty proportional to open bin count to discourage sprawl
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with a non-linear (quadratic) penalty
    // that grows faster for large dead space.
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth interaction: as the stream progresses, tighten tolerance for
    // leftover space (dead space matters more later).
    let tightness = 1.0 + 1.5 * progress * progress;
    score *= tightness;

    // Smooth coupling of post_residual with mean residual: penalize bins whose
    // resulting residual deviates from the pack average (fragmentation shaping).
    let dev = (pr - mean_residual) / cap;
    score += 20.0 * dev * dev * cap;

    // Lookahead: reward bins whose post-residual can still accommodate the
    // next item (smooth sigmoid-like coupling instead of hard cutoff).
    if next_item_size > 0 {
        let fits_next = (norm_pr - (next_item_size as f64 / cap)).max(0.0);
        score -= 15.0 * (1.0 - (-5.0 * fits_next).exp());
        // Penalize near-miss residuals that waste space just below next item.
        let near_miss = (pr - next_item_size as f64).abs();
        score += 8.0 * (-(near_miss / cap) * 10.0).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin (smoothly scaled by progress).
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Mild preference for consolidating into fewer bins as stream matures.
    score -= (open_bins_count as f64).ln() * (2.0 + 6.0 * progress);

    // Perfect-fit reward with smooth falloff.
    score -= 25.0 * (-(norm_pr * norm_pr) * 20.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
