pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // A residual is "dead" if it's smaller than the smallest plausible item.
        if post_residual < 10 {
            score += 200.0 * (10.0 - post_residual as f64);
        } else if post_residual < 25 {
            // Semi-dead zone: moderate penalty decaying with gap size.
            score += 0.8 * (25.0 - post_residual as f64);
        } else {
            // Larger gaps remain somewhat reusable; mild reward for big leftovers.
            score -= 0.15 * (post_residual as f64 - 25.0);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to current residual (fill ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Pressure from many open bins: discourage spreading across bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one,
    // unless the fit is terrible (post_residual in dead zone already penalized).
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when existing bins would
    // leave dead space or no bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If current item leaves a semi-dead gap in an existing bin,
        // opening fresh becomes comparatively attractive.
        if post_residual > 0 && post_residual < 25 {
            score -= 55.0;
        }
        // Lookahead: if next item is large, a fresh bin with room is valuable.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    } else {
        // Lookahead synergy: prefer bins that can also host the next item.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 12.0;
            } else if post_residual > 0 {
                score += 10.0;
            }
        }
    }

    // Mild drift with stream progress: early on, be conservative about
    // opening bins; later, allow more freedom.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already favored by the base term.

    // 2-step lookahead: strongly reward when post_residual exactly matches the
    // next item size (perfect chaining), penalize residuals that can't host it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = pr - nxt;
        if diff == 0.0 {
            score -= 25.0; // perfect 2-chain
        } else if diff < 0.0 {
            // next item cannot fit here regardless; residual becomes dead space
            score += (-diff) * 0.15;
        } else {
            // next item fits; the smaller the leftover after it, the better
            score -= 8.0 - (diff / 20.0).min(6.0);
        }
        // Bonus if this bin is the only one that fits the current item
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // Penalize opening a new bin when open bins could take the item well
        if bin_residual == bin_capacity && fitting_bins_count > 1 {
            score += 20.0;
        }
        // New bin is attractive only if current item is large and next item is small
        // (large item leaves little residual anyway).
        if bin_residual == bin_capacity {
            let large_item = item_size as f64 > 0.6 * bin_capacity as f64;
            let small_next = nxt < 0.4 * bin_capacity as f64;
            if large_item && small_next {
                score -= 12.0;
            }
        }
    } else {
        // Last item: just take the tightest fit; last-chance bonus still applies.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        if bin_residual == bin_capacity {
            score += 15.0;
        }
    }

    // Prefer bins with residuals below the mean (consolidate waste into few bins),
    // mildly penalize dipping into bins with large residuals early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.05 * (1.0 - progress);
    }

    // Slight preference for keeping many open bins from multiplying late in stream
    if open_bins_count > 0 && bin_residual == bin_capacity {
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual by how much of the bin was consumed.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that is hard to reuse later (post_residual in 1..15 range).
    if post_residual > 0 && post_residual < 15 {
        score += 6.0 * (15.0 - post_residual as f64) / 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 5.0 * (next_item_size as f64 / bin_capacity as f64);
    }
    // If next item would be blocked by a large leftover, penalize slightly.
    if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        score += 3.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score -= (open_bins_count as f64).ln().max(0.0) * fit_ratio * 2.0;

    // Time horizon: early in the stream, be more willing to open new bins;
    // later, tighten packing to avoid excess bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 4.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    // Global residual context: if mean residual across bins is high, prefer
    // spreading load; if low, prefer the best local fit.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Mild penalty for opening a brand-new bin when open bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    let mut score = post;

    // Non-linear polynomial coupling of post residual with stream progress
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep: penalizes mid-range waste
    score += 40.0 * poly * (0.5 + progress);

    // Reward tight fits (small post residual), stronger later in the stream
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (0.4 + progress);

    // Penalize residual smaller than next item (dead space for lookahead)
    if next_item_size > 0 {
        let nx = (next_item_size as f64) / cap;
        if x < nx {
            score += 25.0 * (nx - x) * (1.0 + progress);
        } else {
            score -= 10.0 * (x - nx) * (1.0 - progress);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Mild penalty when bin is far below mean residual (fragmentation)
    score += 3.0 * ((mean_residual - post) / cap).abs();

    // New-bin candidate: slight late-stream bias against opening new bins
    score += 5.0 * progress * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" the leftover space is.
    // Class 0 (residual divisible by 10) is highly reusable; odd/tiny residuals are dead space.
    let pr = post_residual;
    let harmonic_class = (pr % 10) as f64;
    score += harmonic_class * 0.8; // penalize non-decade leftovers

    // Penalize very small dead residuals that nothing (min size ~1..10) can use well.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Reward tight fits: small post_residual is good (already partly via base score).
    if pr == 0 {
        score -= 40.0; // perfect closure
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or nearly,
    // strongly reward this bin (chain packing).
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 20.0 - slack * 0.3;
        // exact chain fit
        if pr == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // next item won't fit here regardless; slight penalty for creating a stranded bin
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if the item is large and no tight fit exists.
        // Penalize mildly so existing bins are preferred unless they score poorly.
        score += 12.0;
        if item_size >= bin_capacity / 2 {
            score -= 8.0; // large items start fresh bins more readily
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer fuller bins relative to mean residual: filling below-mean-residual bins
    // balances the pool of open bins.
    score -= (mean_residual - (bin_residual as f64)) * 0.15;

    // Integer-division threshold: bins whose residual falls in [50,100) quarter classes.
    let quarter = bin_residual / 25;
    match quarter {
        0 => score -= 6.0,   // nearly full bin, keep filling it
        1 => score -= 2.0,
        2 => score += 1.0,
        _ => {}              // mostly empty bin, neutral
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit typical future items
    // are "dead" — penalize them super-linearly.
    if post_residual > 0 {
        let dead_threshold = if next_item_size > 0 { next_item_size.max(10) } else { 10 };
        if post_residual < dead_threshold {
            score += (dead_threshold - post_residual) as f64 * 3.0;
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Lookahead coupling: penalize if the leftover gap cannot host the next item
    // (forcing a future bin opening), reward if it can.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * (post_residual as f64 - next_item_size as f64);
        } else {
            score += 12.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading to new bins
    // and encourage filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 20.0 + pressure;
    } else {
        score -= pressure * 0.1;
    }

    // Mild alignment with mean residual: prefer bins whose post state stays
    // near the fleet average (keeps residual distribution manageable).
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but only if the leftover is usable.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-step match: this bin absorbs both items exactly.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can still land here: mild reward scaled by how well it fills.
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 20.0 - fill_after * 0.3;
        } else {
            // Leftover is dead space for the next item: penalize proportionally
            // to how small/unusable it is relative to mean residual.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
            if post_residual < 10 {
                score += 15.0; // tiny unusable sliver
            }
        }
    } else {
        // Last item: pure tight-fit objective.
        score -= 10.0;
    }

    // Relative-to-mean coupling: bins already tighter than average deserve priority
    // for finishing; loose bins should absorb awkward items.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make it moderately attractive only when the stream is early
    // or no open bin offers a good fit; otherwise keep it penalized via its
    // naturally large post_residual (= full capacity).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress); // early stream: fresh bins cheaper
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // new bin can host the pair cleanly
        }
    }

    // Mild congestion pressure: with many open bins, prefer consolidation.
    if open_bins_count > 4 {
        score += open_bins_count as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly prefer small post_residual, especially
    // when the leftover is hard to reuse (small relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * tightness * item_size as f64;

    // Penalize dead space: post_residual that is too small for typical items
    // (below 10) is nearly useless waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 0.5 * next_item_size as f64;
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Global state coupling: prefer filling bins when many bins are open
    // (consolidation pressure); when few bins are open, new bins are cheap.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= open_pressure * (bin_residual as f64 / bin_capacity as f64) * 3.0;

    // Mean-residual coupling: if this bin is emptier than average, slightly
    // deprioritize it when the item could go elsewhere; if fuller than
    // average, reward consolidating into it.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (bin_res_f - mean_residual) / mean_residual.max(1.0);
        score -= 4.0 * rel;
    }

    // Time horizon: early in the stream, opening new bins is acceptable and
    // we keep flexibility (mild score); late in the stream, squeeze items in
    // aggressively to avoid waste.
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: an empty bin should only win when no open bin fits
    // well. Penalize it moderately, scaled by how many bins could fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative: opening a new bin is correct
        } else {
            // competing open bins exist; make new bin lose unless all
            // alternatives are terrible (their post_residual handled above)
            score += 12.0 + 2.0 * fitting_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Core: strongly convex penalty on wasted residual (favor tight fits).
    let mut score = norm_pr.powf(1.6) * 40.0;

    // Smooth coupling: waste matters more as the stream progresses.
    score += norm_pr * norm_pr * t * 25.0;

    // Reward bins whose residual stays compatible with the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 + 6.0 * (1.0 - t);
    }
    // Penalize residual that is small but nonzero (unusable dead space).
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += (1.0 - pr / next_item_size as f64) * 8.0 * (0.5 + t);
    }

    // Perfect fit bonus (smooth, quadratic decay from zero waste).
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 12.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize proportionally to how many bins could fit,
    // with a smooth relaxation late in the stream (consolidation phase).
    if bin_residual == bin_capacity {
        let fit_pressure = fitting_bins_count as f64;
        score += 10.0 + fit_pressure * 6.0 * (1.0 - 0.5 * t);
    }

    // Mild preference for bins deviating from the mean residual (balance load).
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit gets a massive reward.
    if post_residual == 0 {
        score -= c * 10.0;
    }

    // Dead-space classes: leftover smaller than the smallest useful item (<= ~10)
    // is nearly worthless; penalize mildly, but reward if a small next item can use it.
    if post_residual > 0 && post_residual < 10 {
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 5.0; // lookahead rescues the tiny residual
        } else {
            score += 15.0; // dead space penalty
        }
    }

    // Quarter classes: leftover in (0, C/4] is low-utility; (C/4, C/2] medium;
    // (C/2, 3C/4] good; (3C/4, C) excellent.
    if pr > 0.0 && pr <= c * 0.25 {
        score += 8.0;
        if next_item_size as f64 <= pr {
            score -= 12.0; // next item fits exactly into this class -> strong bonus
        }
    } else if pr <= c * 0.5 {
        score -= 3.0;
        if next_item_size as f64 <= pr {
            score -= 6.0;
        }
    } else if pr <= c * 0.75 {
        score -= 8.0;
        if next_item_size as f64 <= pr && next_item_size as f64 > pr - c * 0.25 {
            score -= 10.0; // next item tightly fills this band
        }
    } else if pr < c {
        score -= 12.0;
    }

    // Integer-division thresholds: reward residuals that are multiples of common
    // item granularity (harmonic classes of size 10 and 20).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead pairing: harmonic match when next item divides the residual cleanly.
    if next_item_size > 0 && post_residual > 0 {
        let n = next_item_size as u32;
        if post_residual % n == 0 {
            score -= 7.0; // residual is an exact multiple of next item -> chain fits
        } else if post_residual >= n {
            score -= 2.0;
        } else {
            score += 6.0; // next item cannot use this bin; residual likely stranded
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 10.0;
        if post_residual > 0 && post_residual < 10 && (next_item_size == 0 || (next_item_size as u32) > post_residual) {
            score += 12.0; // but avoid creating dead space at last chance
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = c * 0.6;
        // Late in the stream, or when many bins are open with slack, discourage new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
        score += (open_bins_count as f64).ln().max(0.0) * 5.0;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= 50 {
            score -= 10.0;
        }
        // If no bin fits (this call is the only option), new bin is fine.
        if fitting_bins_count == 0 {
            score -= c;
        }
    }

    // Mild preference for keeping mean residual low (balance across bins).
    score += (mean_residual - pr).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small gaps (dead space that no plausible item can fill).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 15.0;
    }

    // Reward exact fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure from many open bins: discourage spreading into more bins
    // unless the fit is good; encourage closing out bins with small residuals.
    score += (open_bins_count as f64) * 0.8;

    // If post_residual could still fit the next item, small bonus for keeping it usable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to next item.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Slight preference for tighter bins (below mean residual) to consolidate.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: if the next item exactly matches the post
    // residual, this placement is nearly free — heavily reward it.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if gap == 0.0 {
            score -= 60.0;
        } else if gap <= 10.0 {
            score -= 40.0 * (1.0 - gap / 10.0);
        } else if nxt <= post {
            // next item fits but leaves slack: mild reward proportional to use
            score -= 15.0 * (nxt / post);
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            score += 10.0 * ((gap - 10.0).min(40.0) / 40.0);
        }
    } else {
        // Last item: prefer minimal post residual.
        score += 5.0;
    }

    // Relative-to-mean coupling: bins with residual above mean are better
    // candidates for absorbing this item; tight bins below mean are precious.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 12.0 * rel;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is large and no good fit
    // exists; penalize default new bins moderately.
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size >= 50 {
            score -= 20.0;
        }
    }

    // Early in the stream, be more willing to open bins for good structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space: residuals too small to fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 + 0.5 * next_item_size as f64;
        } else {
            // Next item cannot fit here; penalize leaving a residual close to but below next_item_size.
            let waste = (next_item_size as f64 - post_residual as f64).min(30.0);
            score += 0.4 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 2 {
        // Many alternatives: prefer bins where fit is best; slight penalty to spread risk.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: if mean residual is high, encourage consuming from fuller bins.
    score += 0.15 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, be more willing to open new bins for good structure;
    // late in the stream, prefer packing into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: accept only if current bin would leave a bad residual.
        score += 30.0 + 20.0 * (1.0 - progress);
        if post_residual < 10 && post_residual > 0 {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 {
            score -= 20.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Mild penalty for accumulating many open bins early.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear sharpening.
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr * (1.0 - norm_pr)) * cap;

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, waste is penalized more heavily (quadratic in progress).
    score += 12.0 * (norm_pr * norm_pr) * (progress * (2.0 - progress));

    // Reward near-perfect packing non-linearly: cubic decay as residual -> 0.
    score -= 6.0 * (1.0 - norm_pr).powi(3) * cap * (0.5 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (smoothly scaled by how full the placement leaves the bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity and existing bins are crowded (smooth interaction).
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).sqrt();
        let item_frac = item_size as f64 / cap;
        score += 8.0 * crowding * (1.0 - item_frac) * (1.0 + 0.5 * progress);
        // If next item is small, a fresh bin wastes potential; smooth lookahead term.
        let next_frac = next_item_size as f64 / cap;
        score += 5.0 * (1.0 - next_frac) * (1.0 - next_frac);
    }

    // Lookahead synergy: if the next item exactly matches this bin's post_residual,
    // reward strongly (smooth via squared difference).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 4.0 * (1.0 / (1.0 + diff)) * (1.0 - norm_pr);
    }

    // Mild penalty for deviating from mean residual, encouraging residual balance.
    score += 0.5 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // "dead" classes (1..=9) are heavily penalized; perfectly closed bins rewarded.
    if post_residual == 0 {
        score -= 200.0; // perfect fit: best possible outcome
    } else if post_residual <= 9 {
        score += 120.0; // tiny dead space, nearly unusable
    } else if post_residual <= 19 {
        score += 40.0;  // marginal class
    } else if post_residual <= 29 {
        score += 10.0;
    }

    // Modulo-class coupling: leftover that is a multiple of 10 keeps the
    // residual in "harmonic" alignment with typical item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly,
    // penalize bins that become unusable for the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 5 {
                score -= 45.0; // near-perfect two-item chain
            } else {
                score -= (slack as f64).ln() * 4.0;
            }
        } else {
            // next item won't fit here; slight penalty scaled by how much it misses
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: strongly prefer closing bins.
        if post_residual > 0 {
            score += 5.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin
    // unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
        if post_residual <= 9 && post_residual > 0 {
            score -= 30.0; // accept small dead space rather than new bin
        }
    }

    // New-bin candidate: only attractive when residuals across open bins are
    // fragmented (high mean residual spread implies poor fits) or late in stream.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fragmentation = (mean_residual - item_size as f64).abs();
        score = 150.0 + fragmentation * 0.5 - progress * 40.0
              - if next_item_size > 0 && next_item_size <= bin_capacity { 0.0 } else { 0.0 };
        if open_bins_count == 0 {
            score -= 500.0; // must open the first bin
        }
        if fitting_bins_count == 0 {
            score -= 300.0; // nothing fits anywhere
        }
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps (1..=10) are nearly unusable
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 && post_residual > 0 {
        score += 25.0;
    }

    // Reward exact / near-perfect fits
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones
    score += open_bins_count as f64 * 3.0;

    // Last chance: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: make it unattractive unless residual pressure is high
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 2.0;
        // allow opening a new bin when open bins are mostly full
        let fill_ratio = mean_residual / bin_capacity as f64;
        if fill_ratio < 0.25 {
            score -= 90.0;
        }
    }

    // Lookahead: if next item fits in the post-residual, reward keeping this bin
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // gap cannot host next item: mild penalty
        score += 10.0;
    }

    // Stream progression: early on, be more willing to open bins (spread items)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // Prefer bins tighter than the mean residual (well-utilized bins)
    score += (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer minimal post residual (tight fit)
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when next item fits perfectly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 >= next_item_size {
            // next item fits: reward exact match strongly, partial match mildly
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
            if diff < 1.0 {
                score -= 25.0; // perfect chain placement
            }
        } else {
            // next item does NOT fit in this bin's leftover: penalize large dead space
            score += 0.35 * post_residual as f64;
        }
    }

    // Relative-to-mean-residual coupling: bins with residual far below mean are
    // "nearly full" -> good to fill them now; bins above mean waste capacity.
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    let rel = post_residual as f64 - mr;
    score += 0.25 * rel;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a good fit. Make the empty bin moderately unattractive
    // unless the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // A fresh bin is attractive for big items (little fragmentation risk),
        // unattractive for small items that could top off existing bins.
        score += 55.0 - 60.0 * fill_ratio;
        // Late in the stream, avoid spawning bins for marginal gains
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // If several bins fit, discourage opening another
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    }

    // Slight preference to keep number of open bins small when mean residual is high
    if open_bins_count > 4 && mean_residual > item_size as f64 * 2.0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bonus scaled by how snugly the next item fits afterwards.
            let leftover_after_next = post_residual - next_item_size;
            score -= 12.0 * (1.0 - leftover_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving awkward residue,
            // but reward if residue is small (dead space is minimal).
            if post_residual > next_item_size / 2 {
                score += 6.0;
            }
        }
    }

    // New-bin candidate handling: only open a new bin when current bins are tight
    // or item barely fits anywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is attractive for large items late in the stream,
        // or when few fitting bins exist (fragmentation risk).
        let open_bonus = 55.0 * item_frac
            - 25.0 * (1.0 - progress)
            + 8.0 * (fitting_bins_count as f64).ln().max(0.0);
        score -= open_bonus;
        // Keep new-bin score anchored so it competes fairly with bad fits.
        score += 20.0;
    }

    // Global state coupling: spread of residuals vs mean; prefer bins near the mean
    // to keep residual distribution balanced.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * dev / bin_capacity as f64;

    // Mild preference for consolidating into fewer bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: penalize post residual, non-linearly (quadratic dead-space aversion)
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth coupling: post residual value weighted by stream progress —
    // late in the stream, small residuals matter more (waste is costly).
    score += 30.0 * norm_pr * (0.5 + progress) * cap * 0.1;

    // Reward tight fits via smooth cubic of normalized fill ratio
    let fill = 1.0 - norm_pr;
    score -= 25.0 * fill * fill * fill;

    // Lookahead coupling: smooth reward if next item fits the post residual
    let fits_next = if next_norm > 0.0 && next_norm <= norm_pr { 1.0 } else { 0.0 };
    score -= 12.0 * fits_next * (1.0 - (next_norm - norm_pr).abs());

    // Last-chance bin: smooth penalty for leaving a nearly-unique fitting bin unused
    if fitting_bins_count <= 1 {
        score -= 8.0 * (1.0 - progress) * norm_item;
    }

    // Mean residual coupling: prefer bins near the mean (smooth deviation term)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Congestion term: many open bins -> prefer filling existing ones (smooth)
    score -= 5.0 * (open_bins_count as f64).ln().max(0.0) * fill;

    // New-bin candidate: penalize opening fresh bins, more strongly later in stream
    if bin_residual == bin_capacity {
        score += 60.0 * (0.3 + progress) + 10.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in capacity/8 buckets.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / (c / 8.0)).floor(); // 0..8 harmonic class

    // Reward tight fits: lower class => lower score.
    score -= (8.0 - class) * 3.0;

    // Perfect fit: zero dead space.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        // Unusable sliver below min item size is essentially free.
        score -= 20.0;
    } else {
        // Penalize dead space that can't host typical items, scaled by class.
        score += class * class * 1.5;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Keep residual in the same harmonic class as next item need.
            let gap = post_residual - next_item_size;
            score -= 8.0 - (gap as f64).min(8.0);
        } else {
            // Residual too small for next item: penalize by how far off.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.4;
        }
    } else {
        // Last item: prefer tightest bin strongly.
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer crowded bins when many bins are open (consolidation).
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).sqrt() * 1.0;
    }

    // Early in stream: allow opening new bins to build diverse residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late unless fit is bad.
        let base = 30.0 + progress * 40.0;
        // Penalize new bin if existing bins fit well (low class achievable).
        score = base + class * 2.0 - if next_item_size > 0 && bin_capacity >= next_item_size { 5.0 } else { 0.0 };
    }

    // Mean residual coupling: if this bin is far below mean residual, it's "waste-heavy".
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.15;
    }

    // Integer-division threshold on post_residual: mod-10 classes.
    let m = post_residual % 10;
    if m != 0 && post_residual >= 10 {
        score += m as f64 * 0.1; // slight penalty for awkward remainder
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny unusable sliver
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0; // only fits the smallest items
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit, zero waste
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Pressure from too many open bins: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Pull toward the mean residual: bins with above-average space are better hosts.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0; // sets up a near-perfect follow-up
        } else if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
            score += 10.0; // next item cannot use this gap
        }
    }

    // New-bin candidate: make it moderately attractive only when existing bins would
    // create bad dead space, and early in the stream when consolidation matters less.
    if bin_residual == bin_capacity {
        score = 45.0 + 10.0 * (1.0 - progress) - 2.0 * open_bins_count as f64;
        if post_residual == 0 { score -= 40.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good via base score.

    // Aggressive 2-step lookahead: if the next item exactly fills the post_residual,
    // this is a perfect chain — strongly reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // If next item fits in post_residual, mild reward proportional to how snugly.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    }
    // If next item cannot use the post_residual, penalize dead space, worse when
    // post_residual is small-but-unusable (unattractive sliver).
    else if next_item_size > 0 {
        let slack = post_residual as f64;
        score += 8.0 + 20.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins below mean residual (consolidate waste into few bins).
    score += 0.5 * ((post_residual as f64) - mean_residual).max(-20.0).min(20.0);

    // Penalize leaving exactly tiny unusable slivers (1..=5) hard.
    if post_residual >= 1 && post_residual <= 5 {
        score += 30.0;
    }

    // Early in the stream, be slightly more willing to keep bins compact;
    // late in the stream, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: neutral-ish baseline so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively as stream progresses.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= (cap - post_residual as f64) * (0.5 + t);

    // Penalize dead space that becomes unusable (below min item size 1..=10 range).
    if post_residual < 10 && post_residual > 0 {
        score += 15.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 10.0 * t;
    }

    // Many fitting bins: mildly penalize this one if fit is loose, prefer compacting.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead coupling: if next item fits in the post residual, big reward;
    // if next item is large and this bin is nearly the only option, penalize waste.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 12.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else if nxt > bin_residual as f64 {
            // next item won't fit here anyway; free to fill this bin
            score -= 5.0;
        } else {
            // next item fits this bin now but not after placement: mild penalty unless post_residual tiny
            score += 4.0 * (post_residual as f64 / cap);
        }
    }

    // Global state: penalize adding to already-crowded bin pool with high mean residual
    // (fragmentation); reward using bins when mean residual is low.
    score += 0.05 * (mean_residual - post_residual as f64);
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / cap);

    // New-bin candidate handling: only attractive when current fit is bad or no good options.
    if bin_residual == bin_capacity {
        let good_fit = (post_residual as f64) <= 10.0 || (post_residual as f64) < 0.15 * cap;
        if good_fit && (fitting_bins_count <= 1 || post_residual == 0) {
            score -= 30.0;
        } else {
            score += 35.0 + 20.0 * t;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let base = r
        - 24.0 * (1.0 - progress) * rn * (1.0 - rn)
        - 18.0 * progress * rn * rn;

    // Reward tight fits, scaled by non-linear progress term.
    let tight = (item_size as f64 / cap).powi(3);
    let fit_bonus = 30.0 * tight * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item.
    let look = next_item_size as f64;
    let dead = if look > 0.0 && r < look {
        (look - r) * (1.0 + progress)
    } else if look > 0.0 && r >= look {
        -6.0 * (1.0 - rn)
    } else {
        0.0
    };

    // Last-chance pressure: strongly favor using the only fitting bin.
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -40.0 * (1.0 - progress * 0.5)
    } else {
        0.0
    };

    // New-bin candidate should be mildly penalized early, less later.
    let new_bin = if bin_residual == bin_capacity {
        15.0 + 25.0 * (1.0 - progress)
    } else {
        0.0
    };

    // Smooth dispersion term vs mean residual.
    let disp = 0.15 * (mean_residual - r).abs() * (1.0 - progress);

    base - fit_bonus + dead + last_chance + new_bin + disp
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: prefer residuals that
    // fall into "useful" classes (multiples of common small sizes).
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -40.0 // perfect fit: strongly favored
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr >= 10 {
        0.0
    } else {
        15.0 // dead space below the minimum item size
    };
    score += class_bonus;

    // Harmonic coupling with the lookahead item: reward residuals that can
    // exactly host next_item_size or a harmonic fraction of it.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 20.0;
        } else if pr >= next_item_size {
            score -= 4.0;
        } else {
            score += 6.0;
        }
        // penalize leaving a residual just barely below next item (worst class)
        if pr < next_item_size && pr >= (next_item_size as f64 * 0.6) as u32 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current bin
    // would leave large unusable residue and the stream is early/mid.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 20.0 * progress;
        if post_residual as f64 > cap * 0.5 {
            score -= 10.0; // big item, fresh bin is fine
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64) * 0.3;
    // Slight preference for bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are pure waste.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            3.0
        } else if post_residual < 20 {
            1.5
        } else if post_residual < 30 {
            0.6
        } else {
            0.0
        };
        score += dead * (post_residual as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 10 {
        score -= 5.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins,
    // penalize spreading across many open bins.
    score += (open_bins_count as f64) * 0.35;

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin; reward heavily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bin's
    // post-fit residual is worse than a fresh bin's utility, or the item
    // leaves a dead gap here.
    if bin_residual == bin_capacity {
        // Fresh bin: score is its full residual; make it moderately
        // unattractive so open bins with decent fits win, but attractive
        // when all fits are terrible.
        score += 8.0;
        if post_residual > 50 {
            score -= 10.0; // large item alone in a new bin is fine
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 15.0;
        } else if gap <= 10 {
            score -= 4.0;
        } else {
            score += gap as f64 * 0.2;
        }
    }

    // Mean residual coupling: when open bins are already full-ish on
    // average, slightly favor this bin if it is roomier than average.
    if (bin_residual as f64) > mean_residual {
        score -= 1.0;
    } else {
        score += 1.0;
    }

    // Stream progression: late in the stream, tighten up to avoid
    // stranded residual capacity.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0 * (post_residual as f64).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: next item fits exactly into post_residual (perfect 2-step chain)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits, reward proportional to how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize dead space
            score += 8.0;
        }
    }

    // Prefer bins tighter than average (small residual relative to mean)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize creating tiny unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Late in stream: be more frugal, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New empty bin candidate: penalize unless current bins are very full on average
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize dead space relative to item size: small leftover below next item threshold is bad
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        } else {
            // leftover that can still host the next item is valuable
            score -= 0.25 * (post_residual as f64).min(next_item_size as f64);
        }
    } else {
        // last item: prefer minimal waste
        score += post_residual as f64 * 0.05;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowding: when many bins fit, mild penalty to preserve choice
    if fitting_bins_count > 1 {
        score += fitting_bins_count as f64 * 0.4;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter than average)
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Time horizon: early in stream, be conservative (favor new bins for big items);
    // late in stream, squeeze into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 12.0;

    // New-bin candidate handling: empty bin is a fallback; make it costly unless
    // item is large relative to residual landscape or few bins fit.
    if bin_residual == bin_capacity {
        let large_item_bonus = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 55.0 - large_item_bonus * 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score -= 8.0; // fresh bin can also host next item
        }
        if open_bins_count == 0 {
            new_bin_score = -100.0; // must open first bin
        }
        score = score.min(score) + new_bin_score; // new-bin path evaluated independently
        score = new_bin_score;
    }

    // Slight penalty for wasting an almost-full bin on a tiny item
    if item_size < 20 && bin_residual < 30 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post_residual), smoothed polynomial coupling with progress
    let mut score = pr_norm * (1.0 + 0.5 * progress * pr_norm);

    // Non-linear penalty for medium dead space (worst zone ~ 30-60% residual)
    let dead = pr_norm * (1.0 - pr_norm);
    score += 1.6 * dead * dead;

    // Reward using bins that can barely fit (last-chance bins)
    if fitting_bins_count == 1 {
        score -= 2.0;
    } else if fitting_bins_count > 1 {
        score += 0.15 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: bonus if next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.8 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 0.3 * (1.0 - pr_norm);
    }

    // Slight preference for consolidating into fewer bins early
    score += 0.02 * (open_bins_count as f64) * (1.0 - progress);

    // New-bin candidate: penalize unless current bin would leave awkward residual
    if bin_residual == bin_capacity {
        score = 1.2 + 0.5 * progress - 0.3 * dead;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity-fraction buckets. Residuals in "small" classes (< 10) are dead
    // space -> penalize; residuals that can host a "harmonic" unit (10, 20,
    // 25, 50) are reusable -> reward.
    let pr = post_residual;
    let dead = if pr < 10 { 1.0 } else { 0.0 };
    score += dead * 40.0;

    // Modulo-10 harmony: perfectly divisible leftovers are ideal slots.
    if pr > 0 && pr % 10 == 0 {
        score -= 12.0;
    } else if pr > 0 && pr % 5 == 0 {
        score -= 6.0;
    }

    // Integer-division thresholds: post_residual / item_size ratio tells how
    // many copies of the current item could still fit later.
    if item_size > 0 {
        let copies = pr / item_size;
        if copies >= 1 {
            score -= 8.0 * copies as f64;
        }
    }

    // Lookahead harmony: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect harmonic match with lookahead
        } else if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here; mildly penalize wasting capacity
            score += 0.05 * (next_item_size as f64 - pr as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin (unless post-residual would be dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.1 * bin_residual as f64;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when current fit is bad (large post_residual or dead
    // space) or when many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = (post_residual as f64 / cap).max(0.0);
        score = 55.0 + bad_fit * 30.0 - 15.0 * (open_bins_count as f64 / 8.0).min(1.0) - 10.0 * progress;
        if dead > 0.0 {
            score -= 20.0; // current bin would become dead space -> prefer new bin
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // an empty bin can always host the next item: small bonus
            score -= 3.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is far below the
    // mean (tight bins), penalize dumping into already-loose bins.
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.10 * (resid_f - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (1.0 - (post_residual as f64) / 13.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits generally: fraction of bin filled by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Open-bin pressure: penalize creating more bins / spreading load thin.
    score += 2.0 * open_bins_count as f64;

    // If this is the only fitting bin, strongly prefer using it (last chance).
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // Competition among fitting bins: prefer closest fit via post_residual already.
        score += 3.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If post-residual is small but nonzero and next item cannot use it, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 15.0;
    }

    // Mean-residual coupling: bins deviating far below mean residual are "ragged";
    // prefer bins whose residual is near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is discouraged unless all fits are bad.
        // Base penalty grows with number of open bins that could fit.
        score = bin_capacity as f64 + 10.0 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            // No real alternative: opening a new bin is fine.
            score -= 45.0;
        }
        // If current item is large, a fresh bin is attractive (leaves small gap elsewhere).
        if item_size >= 70 {
            score -= 20.0;
        }
        // Late in the stream, avoid opening bins.
        score += 20.0 * (step_index as f64 / (total_items.max(1) as f64));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: strongly favor bins whose post_residual is small.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // 2-step lookahead: reward bins where next item exactly fills the new residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // exact two-item completion
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot fit here: penalize leaving a residual smaller than next item
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Penalize dead space that is hard to reuse (small residuals below min item size).
    if post_residual < 1 {
        score += 100.0;
    }

    // Compare residual against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins attractive only when few bins exist
    // or the stream is early; otherwise discourage spreading items thin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let early = 1.0 - progress;
        let spread_bonus = 25.0 * early / (open_bins_count as f64 + 1.0);
        score -= spread_bonus;
        // discourage new bins when many open bins could still absorb items
        score += open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize unusable dead space: post_residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size as f64 > post_residual as f64 {
            // Next item won't fit here; mild penalty proportional to gap.
            score += 0.2 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Prefer filling fuller bins when many bins are open (consolidation pressure).
    let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fullness * (open_bins_count as f64).ln().max(1.0);

    // Global state coupling: if mean residual is high, avoid spreading waste.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more tolerant of opening bins;
    // late in the stream, pack tightly to avoid waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: empty bin gets baseline cost plus a bonus when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0 - 30.0 * (fitting_bins_count == 0) as i32 as f64;
        // Favor new bin when item is large (hard to place later).
        score -= 0.15 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): keep residuals large-ish, mild penalty on tiny residuals.
    // Late (progress ~ 1): strongly reward tight fits (small post_residual).
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    let coupling = (1.0 - progress) * (poly * 40.0) + progress * (norm_pr * norm_pr * 60.0);
    score += coupling;

    // Reward exact-ish fits with smooth falloff.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 25.0 * progress;
    }

    // New-bin candidate: penalize opening bins early, allow late when open bins are poor fits.
    if bin_residual == bin_capacity {
        let avg = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score += 30.0 * (1.0 - progress) - 20.0 * avg * progress;
    }

    // Lookahead: bonus if next item fits the resulting residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let snug = 1.0 - ((pr - next_item_size as f64) / cap);
        score -= 8.0 + 12.0 * snug * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space severity via integer division bands
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 0: perfect fit -> huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic band: post_residual / 10 -> 0..10 classes; deeper bands (small residual) penalized super-linearly
        let band = post_residual / 10;
        match band {
            0 => score += 40.0,               // 1..9 : nearly unusable sliver
            1 => score += 25.0,               // 10..19
            2 => score += 12.0,               // 20..29
            3 => score += 5.0,                // 30..39
            4 => score += 0.0,                // 40..49 sweet-ish zone
            5 => score -= 3.0,                // 50..59 flexible zone
            6 => score -= 5.0,                // 60..69
            7 => score -= 6.0,                // 70..79
            _ => score -= 7.0,                // 80..99
        }
    }

    // Lookahead: reward if next item fits into the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact-ish fit for next item gets extra reward
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - gap / cap);
        } else {
            // next item won't fit: penalize leaving residual that blocks nothing useful
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin should only win when fits are poor
    if bin_residual == bin_capacity {
        // new bin baseline: residual after placement = capacity - item_size
        // penalize slightly so that good existing fits win, but allow it when
        // existing residuals would be left in bad harmonic classes
        score += 8.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        // if next item is large, a fresh bin is attractive
        if next_item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Crowd penalty: many open bins with high mean residual -> prefer consolidating
    if open_bins_count > 1 {
        let consolidation = (mean_residual - pr).abs();
        score += 0.05 * consolidation;
        score += 0.5 * open_bins_count as f64;
    }

    // Mild stream-phase modulation: early phase favors tight packing (small residuals ok),
    // late phase favors closing bins out (avoid tiny leftovers)
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += phase * (pr / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps heavily (dead space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward exact fits strongly
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward residual that can still fit typical future items
    if post_residual >= 50 {
        score -= 15.0;
    }

    // Last-chance bonus: only one fitting bin, avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // Penalize if next item is slightly larger than post_residual (near-miss dead zone)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Prefer bins whose residual is close to mean residual (balanced packing)
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // New-bin candidate: penalize opening a new bin when good existing fits exist,
    // but allow it if current bin would leave large dead space
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.5;
        if post_residual > 70 {
            score -= 25.0; // big item in fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual quadratically.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect-fit bonus: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if next item fits exactly into the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // chain of perfect fits
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving awkward gaps.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Allow new bin if item is large and would leave a big gap elsewhere.
        score -= (item_size as f64) * 0.2;
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit: reward small post_residual relative to capacity
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover = post_residual - next_item_size;
            if leftover == 0 {
                score -= 45.0;
            } else {
                score -= 20.0 * (1.0 - leftover as f64 / bin_capacity as f64);
            }
        } else {
            // next item won't fit here after placement: mild penalty proportional to gap
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless no open bin fits
    if bin_residual == bin_capacity {
        if fitting_bins_count > 1 {
            score += 40.0;
        } else {
            score -= 5.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into bins with residual below mean (avoid fragmenting)
    if bin_residual != bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
        score += 0.5 * open_bins_count as f64;
    }

    // Time horizon: early in stream, be more conservative (penalize waste more),
    // late in stream, accept looser fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fit = post_residual == 0;
    let mut score = pr * pr / cap; // quadratic dead-space penalty
    // smooth progress coupling: early stream favors tight fills, late stream favors consolidation
    score += pr * (0.5 + t) * 0.5;
    // reward near-perfect fits smoothly
    score -= (1.0 - pr / cap) * (1.0 - pr / cap) * item_size as f64 * 0.3;
    // last-chance bin bonus
    if fitting_bins_count == 1 { score -= 8.0; }
    // lookahead coupling: prefer residual that next item can use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= (1.0 - gap / cap) * 4.0;
    }
    // penalize deviation from mean residual (smooth consolidation pressure)
    score += ((pr - mean_residual) / cap).powi(2) * 6.0;
    // mild pressure to close full bins vs opening new ones
    score += open_bins_count as f64 * 0.05;
    if fit { score -= 10.0; }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: mod-10 bucket quantization.
    let post_class = post_residual % 10;
    // Dead-space penalty: small nonzero residuals are the worst (unusable gaps).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_class != 0 && post_class < 5 {
        score += 8.0;
    } else if post_class == 0 {
        // Perfectly divisible residual (harmonic with decade classes) is desirable.
        score -= 10.0;
    }

    // Reward exact fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Integer-division threshold: does post_residual harmonically fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward if next item divides the post residual into useful chunks.
            if post_residual % next_item_size == 0 {
                score -= 15.0;
            }
            // Penalize wasting the lookahead slot: post residual much larger than needed
            // leaves an awkward second gap.
            let after_next = post_residual - next_item_size;
            if after_next > 0 && after_next < 10 {
                score += 20.0;
            }
        } else {
            // Next item cannot use this bin's remainder: dead space likely locked in.
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open new bin late in the stream or when open bins are crowded.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    } else {
        // Prefer fuller bins: penalize bins whose residual deviates far below mean.
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score += diff * 0.4;
        }
    }

    // Modulo coupling: item size in "large" harmonic class (>= half capacity) should
    // go into bins with matching large residuals to avoid splitting.
    if item_size * 2 >= bin_capacity {
        if bin_residual >= item_size && (bin_residual - item_size) < bin_capacity / 4 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps after placement.
    // A residual in (0, 10) is pure dead space (min item size is 10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residuals that only a very small item could use.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit bonus: strongly reward leaving zero residual.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit bonus: reward using most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bins pressure: penalize spreading across many bins when residuals are similar.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).sqrt() * 1.5 * (0.5 + progress);

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use the leftover: penalize creating a blocking gap.
        score += 10.0;
    }

    // Mean residual coupling: prefer bins whose post residual stays near the mean
    // (keeps future flexibility), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when no open bin gives a good fit; make the empty bin
    // moderately unattractive so open bins are used first unless they waste space.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - fill_ratio) + 5.0 * progress;
        // If many bins are open and residuals are large, opening a new bin is fine.
        if open_bins_count > 4 && mean_residual > 40.0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual == next_item_size is ideal.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward closeness of post_residual to next_item_size (tight 2-step fit).
        score -= 60.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
    }

    // Penalize dead space: post_residual too small for next item (or any plausible item).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Compare against mean residual: bins far below mean are "tighter", favor them mildly.
    score -= (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bonus: only one fitting bin -> strongly prefer using it over new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0 && post_residual < next_item_size;
        score += if poor_fit { 5.0 } else { 90.0 };
        // Early in stream, new bins are cheap; late, avoid proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Lookahead coupling: if the next item can fit into the post residual,
    // strongly reward this placement (chaining two items in one bin).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.4 * (next_item_size as f64);
        } else {
            // Penalize leaving dead space the next item cannot use.
            let waste = (post_residual as f64).min(next_item_size as f64 - post_residual as f64);
            score += 0.25 * waste;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize bins that deviate from mean residual (prefer balanced residual pool),
    // but only mildly, and scale down late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * deviation * (1.0 - 0.5 * progress);

    // Late in the stream, prefer packing into existing bins more aggressively.
    score -= 10.0 * progress;

    // New-bin candidate: allow opening a fresh bin only when the item is large
    // (poor fit potential elsewhere) or many bins are already open and residuals
    // are fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let large_item_bonus = if item_size > bin_capacity / 2 { 12.0 } else { 0.0 };
        let fragmentation = if mean_residual > 60.0 && open_bins_count > 3 { 10.0 } else { 0.0 };
        let early_exploration = if progress < 0.25 { 8.0 } else { 0.0 };
        score -= large_item_bonus + fragmentation + early_exploration;
    }

    // Mild penalty for accumulating too many open bins.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = (post_residual as f64 / cap).clamp(0.0, 1.0);

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * fit * fit);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; late, dead space is costly
    let prog_weight = 0.5 + 2.5 * progress * progress * (3.0 - 2.0 * progress);
    score += pr * fit * prog_weight;

    // Reward near-perfect fits more strongly as the stream advances
    score -= (1.0 - fit).powi(3) * (20.0 + 60.0 * progress);

    // Last-chance bonus: only one bin fits -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0 + 40.0 * progress;
    } else {
        // mild penalty when many bins compete, prefer concentrated packing
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Prefer bins whose residual is below mean (tighter bins) with smooth coupling
    let mean_fit = (mean_residual / cap).clamp(0.0, 2.0);
    score += (fit - mean_fit) * (10.0 + 20.0 * progress);

    // Lookahead: if next item fits exactly in post_residual, big reward (smooth)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_quality = (-gap / 30.0).exp();
        score -= 45.0 * match_quality * (0.5 + progress);
        // penalize post_residual too small for next item (creates isolation)
        if (next_item_size as f64) > pr {
            score += 8.0 * (1.0 - pr / cap) * (0.3 + 0.7 * progress);
        }
    }

    // New-bin candidate: neutral-ish baseline, penalized when good fits exist elsewhere
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.5 * progress) - (1.0 - fit) * 0.0;
        // make new bin less attractive unless existing fits are poor
        score += 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: partition capacity into fifths; reward post_residual landing
    // on "harmonically useful" residue classes (small, reusable slivers).
    let fifth = bin_capacity / 5; // 20
    let post_class = post_residual / fifth; // 0..5 harmonic class
    match post_class {
        0 => score -= 25.0,                       // near-perfect fit, best outcome
        1 => score -= 10.0,                       // leaves a 20-39 slot, reusable
        2 => score += 0.0,                        // neutral mid class
        3 => score += 8.0,                        // awkward 60-79 dead space
        _ => score += 18.0,                       // nearly empty bin wasted on this item
    }

    // Modulo arithmetic on post_residual: exact divisors of capacity are golden.
    if post_residual > 0 && (bin_capacity % post_residual == 0) {
        score -= 12.0; // residual 50, 25, 20, 10 ... splits cleanly for future items
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0; // decade-aligned residuals are friendlier
    }

    // Lookahead coupling: does this bin's post_residual still serve the next item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here too: reward proportional to leftover tightness
            let next_post = post_residual - next_item_size;
            score -= 6.0 + (next_post as f64 / bin_capacity as f64) * 10.0;
        } else {
            // next item cannot use this bin's remainder: penalize large leftovers
            score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.15;
        }
        // Harmonic pairing: item + next item exactly filling a class boundary
        if (item_size + next_item_size) % fifth == 0 && item_size + next_item_size <= bin_residual {
            score -= 7.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins unattractive unless all else is bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.8 && mean_residual < item_size as f64 {
            score -= 55.0;
        }
    }

    // Prefer filling bins that are already relatively full (small residual).
    score += (bin_residual as f64 / bin_capacity as f64) * 12.0;

    // Mild pressure against hoarding many open bins with large mean residual.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0
        + (mean_residual / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score += 8.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Pressure from number of open bins: when many bins are open,
    // prefer filling existing ones over opening new bins.
    let progress = step_index as f64 / (total_items as f64 + 1.0);
    let open_pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual != bin_capacity {
        score -= open_pressure * 0.5;
    }

    // New-bin candidate logic: only attractive when the item barely fits
    // anywhere else or residuals across bins are already fragmented.
    if bin_residual == bin_capacity {
        score += 5.0; // slight default reluctance to open new bins
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            score += 20.0; // avoid poaching the last-chance bin
        }
        if post_residual as f64 > mean_residual {
            score += 10.0;
        }
        // Lookahead: if next item is large, a fresh bin may be valuable.
        if next_item_size > 60 {
            score -= 8.0;
        }
    } else {
        // Lookahead synergy: if next item fits in the post-residual, reward.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 6.0; // post-residual likely dead space for next item
        }
        // Prefer bins whose residual is above mean (keeps flexibility).
        if (bin_residual as f64) < mean_residual - 10.0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // Next item fits: good, but penalize leftover slack after that.
            score -= 60.0 - slack * 0.8;
        } else {
            // Next item does not fit: dead-space risk, penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.5;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when decent open bins exist, unless current fit is terrible.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus growing penalty with more open bins.
        score += 40.0 + open_bins_count as f64 * 3.0;
        // But if lookahead pairs perfectly with a fresh bin, allow it.
        if next_item_size > 0 && (next_item_size + item_size as u32) == bin_capacity {
            score -= 300.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Mild penalty for very large items in nearly-full bins creating fragmentation.
    if item_size > 60 && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: reward if next item fits into post-residual exactly-ish
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; mild penalty proportional to gap
            score += 5.0 * ((next_item_size - post_residual) as f64 / 100.0);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0);
    }

    // New-bin candidate handling: prefer opening new bin only for large items or late stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = (item_size as f64) / (bin_capacity as f64);
        let poor_fit_pressure = if post_residual > 0 && (post_residual as f64) < mean_residual * 0.5 { 1.0 } else { 0.0 };
        let bias = 20.0 - 15.0 * progress - 20.0 * large_item - 30.0 * poor_fit_pressure;
        score += bias.max(-10.0);
    }

    // Global state: many open bins with high mean residual -> prefer reusing full-ish bins
    let residual_gap = (bin_residual as f64) - mean_residual;
    score += 0.1 * residual_gap;

    // Mild time-horizon exploration term
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * horizon * ((open_bins_count as f64).ln() + 1.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (0.5 + progress);

    // Smooth interaction: reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    let coupling = tightness * (1.0 + progress * progress) * item_size as f64 / cap;

    // Lookahead: penalize post_residual that can't fit next item
    let lookahead_penalty = if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 { -0.5 * gap / cap * (1.0 + progress) } else { 2.0 * (-gap) / cap }
    } else { 0.0 };

    // Last-chance bonus when few fitting bins
    let last_chance = if fitting_bins_count <= 1 { -3.0 * (1.0 + progress) } else { 0.0 };

    // Slight penalty for opening new bins when many bins already open
    let new_bin_penalty = if bin_residual == bin_capacity {
        open_bins_count as f64 * 0.1 + progress
    } else { 0.0 };

    let mut score = pr + 10.0 * poly - 8.0 * coupling + 5.0 * lookahead_penalty + last_chance + new_bin_penalty;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0,10] is worst.
    let pr = post_residual;
    let class_penalty = match pr {
        0 => -40.0,                    // perfect fit
        1..=5 => 25.0,                 // tiny unusable sliver
        6..=10 => 18.0,                // dead space below min item
        11..=20 => 6.0,
        21..=50 => 0.0,
        _ => -8.0,                     // large residual stays reusable
    };
    score += class_penalty;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Harmonic class of next_item_size (mod 10): if the next item can exactly
    // consume this post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // next item fits here later; mild reward proportional to match quality
            let gap = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot use this residual; penalize dead space slightly
            score += 4.0 * (next_item_size as f64 - pr as f64) / 10.0;
        }
        // modulo-class coupling: residual class 0 mod 10 pairs with next item class 0 mod 10
        if pr % 10 == 0 && next_item_size % 10 == 0 && next_item_size <= pr {
            score -= 6.0;
        }
    } else {
        // last item: prefer zero residual
        score += 2.0 * pr as f64 / bin_capacity as f64;
    }

    // When many bins are open, discourage fragmenting: prefer bins whose residual
    // is near the mean (harmonic balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Late in stream: tighten packing (weight residual more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.15 * pr as f64;

    // New-bin candidate: only attractive when current bin would leave a bad class
    // or no bin fits well.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        if pr == 0 || (next_item_size > 0 && next_item_size == pr) {
            score += 100.0; // never open new bin for a perfect fit elsewhere
        }
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else if class_penalty > 10.0 {
            score -= 8.0; // opening a new bin beats creating dead space
        } else {
            score += 10.0 + 0.1 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Mid-size gaps (10..=19) moderately penalized since few item sizes fit them.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bins pressure: discourage spreading across many bins; encourage
    // filling existing bins when open_bins_count is high.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item almost fits (small miss), slight penalty for near-dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly.
        let poor_fit = post_residual >= 10 && (post_residual as f64) < (item_size as f64 * 0.5);
        if poor_fit || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            // Prefer reusing an open bin otherwise.
            score += 25.0 + open_bins_count as f64 * 0.3;
        }
    }

    // Slight preference to pack into bins with low mean residual (nearly full bins).
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // closely matches the next item's size.
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 * 1.5
        };
        score -= 80.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Exact chain fit: item + next item fill bin perfectly.
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Next item fits with minimal leftover.
        else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 120.0;
        }
        // Dead space too small for typical items: penalize.
        if post_residual < 10 && post_residual > 0 {
            score += 15.0;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins.
    score -= (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when item is large and no open bin
    // offers a decent fit (poor fit threshold), or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins generally, less so early on.
        score += 250.0 * (1.0 - 0.5 * progress);
        if fit_ratio > 0.7 && mean_residual < item_size as f64 {
            score -= 180.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally to how well the item fills the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize creating small unusable dead space (post_residual below smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item would leave this bin's post-residual useless anyway, slight penalty.
    if next_item_size > post_residual && post_residual < next_item_size {
        score += 4.0;
    }

    // Prefer filling already-open bins when many bins are open (avoid bin proliferation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0) * (0.5 + progress);
    } else {
        // New-bin candidate: only attractive if existing residuals are large and item is big.
        let avg_tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 15.0 * avg_tightness - 10.0 * (item_size as f64 / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        }
    }

    // Mild preference for bins whose residual deviates below the mean (consolidating small residuals).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;

    // Base: polynomial coupling of post_residual with stream progress.
    // Early on, keep residual flexible (mild); late, strongly prefer tight fits.
    let mut score = pr * (0.6 + 0.9 * progress * progress) + 0.35 * pr * pr / cap;

    // Dead-space penalty: residual too small to ever be useful (smooth quadratic).
    let dead = (cap * 0.2 - pr).max(0.0);
    score += 1.7 * dead * dead / cap;

    // Lookahead: reward bins whose post_residual can host the next item,
    // penalize if next item is stranded.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 3.0 * (nx / cap) * (1.0 - progress * 0.5);
        } else {
            let gap = nx - pr;
            score += 0.9 * gap / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count <= 1 {
        score -= 6.0 * (1.0 - progress * 0.3);
    }

    // New-bin candidate: penalize mildly early, more when many bins already open,
    // but allow it when mean residual of open bins is very low (all bins nearly full).
    if is_new_bin {
        let scarcity = (cap - mean_residual) / cap;
        score += 4.5 + 0.25 * open_bins_count as f64 - 5.0 * scarcity * scarcity;
    } else {
        // Reward using bins with below-mean residual (drain fuller bins first).
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 0.8 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into 8 classes of capacity/8.
    let class = (post_residual * 8) / bin_capacity; // 0..8
    score += match class {
        0 => -30.0,                 // perfect fit: reward heavily
        1 => -12.0,                 // small usable gap
        2 => -4.0,
        3 => 2.0,
        4 => 6.0,                   // half-empty: mildly wasteful
        5 => 10.0,
        6 => 16.0,
        7 => 22.0,
        _ => 0.0,
    };

    // Integer-division threshold: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits: reward proportionally to how tight
            let tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 14.0 * (1.0 - tight);
        } else {
            // lookahead cannot follow: penalize dead space creation
            score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline, opened only when fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: slightly above a decent fit, below a bad one.
        score = bin_capacity as f64 * 0.55;
        // Early in the stream, opening bins is cheap (builds diversity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If many bins already open and mean residual is large, discourage new bin.
        score += 0.08 * open_bins_count as f64;
        score += 0.25 * (mean_residual - post_residual as f64).max(0.0);
    } else {
        // Prefer tighter (fuller) bins: lower residual before placement is better.
        score += 0.05 * (bin_capacity as f64 - bin_residual as f64).max(0.0).min(0.0);
        score -= 0.05 * bin_residual as f64;
    }

    // Modulo coupling: post_residual divisible by small harmonics are "flexible" gaps.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    } else {
        // Reward tight fits: fraction of bin filled by this item.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fill_ratio;
    }

    // Penalize leaving a gap that cannot fit the next item (wasted potential).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading items
    // into new bins; consolidate into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: penalize mildly, but allow it when residuals are
    // fragmented (mean residual low) or the bin is already crowded.
    if bin_residual == bin_capacity {
        score += 45.0;
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 30.0;
        }
    } else if (bin_residual as f64) < mean_residual - 20.0 {
        // Bin is tighter than average: good target.
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-exact fit (minimize dead space).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * (item_size as f64);

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: this bin becomes exactly full next step
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item cannot use the leftover: penalize proportionally to waste
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
    }

    // Compare post_residual against the mean residual: prefer bins whose
    // leftover after placement stays close to (but below) the mean, avoiding
    // fragmenting many bins into tiny unusable residuals.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < 10.0 {
            score -= 15.0; // residual too small for any item (sizes >= 10): good
        } else if pr as f64 > mean_residual + 15.0 {
            score += 0.3 * (pr - mean_residual - 15.0); // leaves unusually large hole
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large and no open bin fits well (post_residual tiny or none fit).
    if bin_residual == bin_capacity {
        let base_penalty = 45.0 + 0.5 * open_bins_count as f64;
        let early_discount = 1.0 - (step_index as f64 / (total_items.max(1) as f64)) * 0.3;
        score += base_penalty * early_discount;
        // If next item is huge, a fresh bin may be worth it: soften penalty.
        if next_item_size >= 70 {
            score -= 30.0;
        }
        // If this is the only fitting option (fitting_bins_count==1 means only
        // the new bin fits), the penalty stands so we still prefer open bins.
    }

    // Mild preference for filling more-opened bins to consolidate state.
    score -= 0.05 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize creating tiny, likely-unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here anyway; slight penalty for wasting residual.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large and no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Base penalty for opening a new bin; reduced when item is large.
        let mut new_bin_cost = 45.0 - 25.0 * item_frac;
        // Late in the stream, prefer consolidating into existing bins.
        new_bin_cost += 20.0 * progress;
        // If many bins fit the item, opening a new one is wasteful.
        new_bin_cost += 6.0 * (fitting_bins_count as f64).min(5.0);
        score += new_bin_cost;
        // A fresh bin paired with a large item followed by a similar large item is fine.
        if next_item_size > 0 && (next_item_size as i32 - item_size as i32).abs() <= 10 && item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean residual
        // (use a bin that is "tighter" than average).
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
        // Slight penalty when many bins are open: encourage consolidation.
        score += 0.5 * open_bins_count as f64;
    }

    // Global packing pressure: early on, be greedy with tight fits; later, be conservative.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth polynomial coupling of post residual with stream progress.
    let base = 100.0 * (x * x * (1.0 - progress) + x * progress * (1.0 - x));

    // Tight fit reward: strongly favor small post residual, non-linearly.
    let tight = -400.0 * (1.0 - x).powi(3);

    // Dead-space penalty grows with stream progress (less chance to reuse).
    let dead = 60.0 * x.powi(4) * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, avoid opening new bin.
    let last_chance = if fitting_bins_count == 1 { -150.0 * (1.0 - x) } else { 0.0 };

    // Lookahead: reward if next item can fit into the post residual.
    let lookahead = if next_item_size > 0 {
        let fits = (next_item_size as f64) <= pr;
        if fits { -40.0 * (pr - next_item_size as f64 + 1.0).ln().max(0.0) } else { 25.0 * (next_item_size as f64 - pr) / cap }
    } else { 0.0 };

    // Mild penalty for spreading across many open bins relative to mean residual.
    let spread = 10.0 * (mean_residual - pr) / cap;

    // New-bin candidate: neutral baseline, slightly penalized early, rewarded late
    // when existing residuals are fragmented.
    let new_bin = if bin_residual == bin_capacity {
        30.0 - 80.0 * progress * (mean_residual / cap)
    } else { 0.0 };

    base + tight + dead + last_chance + lookahead + spread + new_bin
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: post_residual modulo small divisors
    // Leftovers in "nice" classes (multiples of 10 / 5) are more reusable.
    let pr = post_residual;
    let class10 = (pr % 10) as f64;
    let class5 = (pr % 5) as f64;
    score += class10 * 1.5;          // penalize off-class leftovers
    score += class5 * 0.8;

    // Integer-division thresholds: leftover >= 50 is a "half bin" and still valuable
    let half_class = pr / 25; // 0..4 tiers
    score -= (half_class as f64) * 6.0;

    // Perfect fit bonus: post_residual exactly 0 or a reusable class
    if pr == 0 {
        score -= 40.0;
    } else if pr % 10 == 0 {
        score -= 8.0;
    }

    // Next-item coupling: does the leftover admit the lookahead item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 12.0;
            // extra reward if leftover after lookahead is again a good class
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 {
                score -= 6.0;
            }
        } else {
            score += 5.0; // leftover too small for lookahead -> dead space risk
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 0.3 + mean_residual / 20.0;
        score -= 10.0 + pressure.min(18.0);
    }

    // Tightness reward: waste ratio of the placement
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 10.0;

    // Stream progression: late in stream, be greedier about filling bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual is good).
    score -= (bin_capacity as f64 - post_residual as f64).max(0.0) * 0.05;

    // Penalize "dead" unusable gaps: small nonzero leftovers (1..=9).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // New-bin candidate: make it unattractive unless residual would be large dead space.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
        // If item is large relative to typical residual, opening a fresh bin is fine.
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
    }

    // Lookahead: if next item fits in the post residual, reward leaving that gap.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: post_residual equals next item size -> perfect chain
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits here: mild reward proportional to tightness
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.08;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space for the lookahead item: penalize proportionally to wasted gap
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.35;
    }

    // Reward tight fits relative to current residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Penalize leaving residual far below the mean residual (fragmentation)
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.15;
    } else {
        score += dev * 0.05; // small reward for being above mean residual
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 0.5 + (post_residual as f64) * 0.3;
        score += pressure + 20.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Late in the stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual near zero).
    let tight = if item_size > 0 { 1.0 - (post_residual as f64) / (bin_capacity as f64) } else { 0.0 };
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small for typical items (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; slight penalty for wasting capacity.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into existing bins, penalize new bins.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses / bins accumulate.
        score += 15.0 + 30.0 * progress + 2.0 * (open_bins_count as f64).sqrt();
    } else {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a laggard;
    // filling it down toward the mean is good.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Early stream: slight preference for balanced residuals; late stream: pack tight.
    score += (1.0 - progress) * 0.03 * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress, smoothly coupled with post_residual.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = post_residual as f64 / cap;
    let pr2 = pr_norm * pr_norm;
    let pr3 = pr2 * pr_norm;

    // Non-linear polynomial coupling: early in the stream, prefer low post_residual
    // (tight fits); late in the stream, tolerate larger residuals to keep bins flexible.
    let tight_weight = 1.0 + 6.0 * progress * (1.0 - progress);
    score += tight_weight * (12.0 * pr2 - 4.0 * pr3) * cap * 0.1;

    // Reward filling a bin nearly exactly (post_residual near zero) with smooth decay.
    score -= 20.0 * (-((post_residual as f64) * (post_residual as f64)) / 180.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 8.0 * (-gap * gap / 400.0);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportional to how far off it is, smoothly.
        let miss = (next_item_size as f64 - post_residual as f64) / cap;
        score += 6.0 * miss * miss * cap * 0.1;
    }

    // Slight preference for consolidating into fewer bins as open count grows.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins whose residual is below average
    // (filling the emptier-relative-to-average bins smoothly).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = post_residual as f64 / cap;
    score -= (1.0 - tightness).powi(3) * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 { score -= 60.0; }

    // Harmonic classes: classify dead space by integer division thresholds.
    // Residual classes: [0..=10] great, (10..=25] ok, (25..=49] poor, >=50 terrible.
    let class = post_residual / 25; // 0,1,2,>=3
    score += match class { 0 => -15.0, 1 => 0.0, 2 => 20.0, _ => 45.0 };

    // Modulo arithmetic: residuals that are multiples of small harmonics pair well
    // with future items (which are 1..=100); reward residuals divisible by common sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 5 == 0 { score -= 4.0; }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual { score -= 50.0; }
        else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= (1.0 - slack as f64 / cap) * 15.0;
        } else {
            // Next item cannot use this residual: penalize large leftover.
            score += (post_residual as f64 - (next_item_size % 100) as f64).abs() * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well
    // or open bins are very full on average.
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 30.0 + post_residual as f64;
        // Opening a new bin is fine when existing bins are quite full.
        new_bin_score -= mean_fullness * 45.0;
        // Early in stream, fresh bins are cheap; late, prefer filling.
        new_bin_score += progress * 15.0;
        // If item is large, a fresh bin keeps flexibility.
        new_bin_score -= (item_size as f64 / cap) * 20.0;
        // If only one fitting bin and it is this new bin, mild bonus.
        if fitting_bins_count == 0 { new_bin_score -= 25.0; }
        score = new_bin_score;
    }

    // Mild penalty proportional to crowding: many open bins -> prefer consolidating.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual tightly matches the item (relative fit quality).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size > post_residual {
            // Dead space for the lookahead item: penalize proportionally.
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Open-bin pressure: discourage proliferation of bins; favor filling existing bins.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins would create large dead space.
    if bin_residual == bin_capacity {
        let base = 95.0;
        // Early in stream, opening bins is cheaper; later, prefer consolidating.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = base + 25.0 * progress + 0.3 * open_bins_count as f64;
        // If next item is small, new bin is fine; if huge, slightly penalize.
        if next_item_size > 0 {
            score += 0.2 * next_item_size as f64;
        }
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a good absorber.
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of next item into post_residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits: reward tight chains
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leftover dead space
            score += 0.35 * post_residual as f64;
        }
        // small extra reward when chain is near-perfect
        if gap < 5.0 {
            score -= 15.0;
        }
    } else {
        // last item: prefer minimal leftover
        score += 0.5 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins with residuals above average (consolidate emptier bins)
    score -= 0.2 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins could still serve future items well
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference for tighter fits overall
    score += 0.1 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Last chance: only bin that fits -> strong incentive to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * next_item_size as f64;
    }
    // Penalize if next item nearly fits but leaves dead space
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.3 * (next_item_size - post_residual) as f64;
    }

    // Penalize large dead space relative to smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // unusable sliver
    }

    // Prefer bins tighter than average (fill fuller bins first)
    score += 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    // Late in stream: discourage opening new bins; prefer filling existing
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus escalation with progress and open bins
        score += 60.0 + 80.0 * progress + 2.0 * open_bins_count as f64;
        // But if existing bins would leave big dead space, new bin is more attractive
        if post_residual < item_size as f64 * 0.5 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: minimize waste, but with non-linear (quartic) waste penalty
    let mut score = post;

    // Smooth non-linear coupling of waste with stream progress:
    // late in the stream, dead space matters more -> amplify convex penalty
    let waste_penalty = (x * x * x * x) * cap * (0.5 + 1.5 * progress);
    score += waste_penalty;

    // Reward tight fits: smooth bump near x ~ 0
    score -= 12.0 * (-(x * 8.0)).exp();

    // Penalize leaving residuals that are likely unusable:
    // smooth trough matching typical small item sizes via mean residual coupling
    let unusable = ((x * cap - mean_residual) / cap).abs();
    score += 6.0 * unusable * unusable;

    // Lookahead coupling: reward residuals that fit the next item (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (post - nx) / cap;
        score -= 8.0 * (-(diff * diff * 40.0)).exp();
        // penalize post residual slightly larger than next item (dead sliver)
        score += 4.0 * (-(diff.abs() * 25.0)).exp() * (post < nx as u32) as u8 as f64;
    }

    // Last-chance bin: strongly favor using it when it's the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // Mild penalty for many open bins to discourage fragmentation late
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + progress) * 0.5;

    // New-bin candidate: neutral baseline with smooth progress-scaled cost
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * progress) + (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fraction buckets (1..=100)
    let item_class = (item_size * 4 + bin_capacity - 1) / bin_capacity; // 1..=4
    let residual_class = (post_residual * 4 + bin_capacity - 1) / bin_capacity;

    // Reward tight fits: small post_residual is good
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize "dead space": post_residual too small for the smallest plausible item (1..100, min ~10 typical)
    let min_item = 10u32.min(bin_capacity);
    if post_residual < min_item && post_residual > 0 {
        score += 18.0; // unusable sliver
    }

    // Harmonic pairing: does post_residual exactly match a class complement of next_item_size?
    if next_item_size > 0 {
        let next_class = (next_item_size * 4 + bin_capacity - 1) / bin_capacity;
        // Perfect complement: next item fills the bin exactly
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            // Reward leaving a residual that itself stays usable
            if nxt_post >= min_item {
                score -= 10.0 * (1.0 - (nxt_post as f64) / (bin_capacity as f64));
            } else {
                score += 8.0; // would create dead space after next item
            }
            // Class coupling: same or adjacent harmonic classes pack well
            let class_gap = if next_class >= residual_class { next_class - residual_class } else { residual_class - next_class };
            score -= 4.0 / (class_gap as f64 + 1.0);
        } else {
            // next item cannot use this residual anyway: slight penalty for hoarding
            score += 3.0;
        }
        // Integer-division threshold: residual divisible into chunks of next item size
        if next_item_size > 0 && post_residual / next_item_size >= 1 {
            score -= 5.0 * (post_residual / next_item_size) as f64;
        }
    } else {
        // Last item: any fit is fine, prefer tightest
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive if open bins fit poorly
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 20.0;
        // If many bins fit the item already, discourage opening new
        if fitting_bins_count > 0 {
            score += 12.0 * fitting_bins_count as f64;
        }
        // Encourage new bin when existing residuals are awkward vs item (poor class match)
        let item_frac = (item_size as f64) / (bin_capacity as f64);
        let mean_frac = mean_residual / (bin_capacity as f64);
        if mean_frac < item_frac * 0.5 && open_bins_count > 0 {
            score -= 15.0; // existing bins are too empty/fragmented mismatch
        }
        // Late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild consolidation pressure: prefer bins with residual below mean (denser bins)
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.05 * diff;

    // Modulo harmonic bonus: residual that is a multiple of common class sizes (e.g. multiples of 10 or 25)
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 3.0;
    }

    // Small tie-breaker against spreading across many bins
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - slack.min(10.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: dead space confirmed.
        score += 5.0;
    }

    // Open-bin pressure: mild penalty encouraging reuse of existing bins,
    // scaled by how full this bin already is.
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score += open_bins_count as f64 * (1.0 - fill_frac) * 0.05;

    // New-bin candidate: default cost of opening a bin; only attractive
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 3.0 + mean_residual * 0.02;
    }

    // Prefer bins with below-average residual (tighter bins) slightly.
    score += (bin_residual as f64 - mean_residual) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits.
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(8);

    // 2-step lookahead: reward when the next item fits the post residual exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - next_fit_gap / bin_capacity as f64).powi(6);
    }
    // Penalize leaving residual that is smaller than next item but still "wasteful".
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 10.0 * (next_item_size - post_residual) as f64 / item_size.max(1) as f64;
    }

    // Reward pairing with mean residual context: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing open bins,
    // unless the fit is terrible.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (small post_residual relative to capacity)
    score -= 3.0 * (1.0 - post / cap) * (1.0 - post / cap) * 10.0;

    // Penalize dead space: post_residual too small for any future item (min size 1, but typical 10+)
    if post > 0.0 && post < 10.0 {
        score += 25.0; // tiny unusable sliver
    }
    if post_residual >= 10 && post_residual < item_size.max(10) {
        score += 8.0; // residual likely unusable for typical items
    }

    // Lookahead: bonus if next item fits exactly in post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 30.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            score -= 6.0 * (nxt / cap);
        } else {
            // next item won't fit here; penalize less if this bin is nearly full anyway
            score += 4.0 * (1.0 - (post_residual as f64 / nxt.min(cap)));
        }
    }

    // Last-chance bonus: only one bin can fit this item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing bins, discourage new bins
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize when open bins exist and can absorb the item
        if open_bins_count > 0 {
            score += 15.0 + 2.0 * open_bins_count as f64 * (mean_residual / cap).max(0.0);
        }
        // early stream: opening bins is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    } else {
        // reward using bins that are already well-filled
        let fill = 1.0 - bin_residual as f64 / cap;
        score -= 10.0 * fill;
        // many open bins: stronger push to consolidate
        if open_bins_count > 4 {
            score -= (open_bins_count as f64 - 4.0) * 1.5;
        }
    }

    // Prefer bins whose residual is close to mean (balanced packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * (1.0 - norm_post);
    score += 40.0 * poly;

    // Tight fit reward, stronger later in the stream
    let tightness = 1.0 - norm_post;
    score -= (1.0 + progress) * 12.0 * tightness * tightness;

    // Penalize dead space relative to mean residual
    if post > mean_residual {
        score += 0.5 * (post - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: favor bins that also fit the next item
    if next_item_size > 0 && (post as u32) >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 5.0;
    }

    // Discourage spreading across too many bins early
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how it decomposes into capacity fractions
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Dead-space penalty: residuals that can't absorb common small items
    if pr > 0 && pr < 10 {
        score += 25.0; // unusable sliver
    } else if pr < quarter {
        score += (quarter - pr) as f64 * 0.35;
    }

    // Reward residuals in "harmonic" classes (multiples of 10 / quarter blocks)
    if pr % 10 == 0 {
        score -= 6.0;
    }
    if pr % quarter == 0 && pr > 0 {
        score -= 4.0;
    }

    // Integer-division thresholds: which harmonic class the item falls into
    let item_class = item_size / quarter; // 0..3
    match item_class {
        3 => score -= 10.0, // huge item: prefer placing it to avoid fragmentation
        2 => score -= 4.0,
        1 => score += 2.0,
        _ => score += 5.0, // tiny item: discourage wasting big-bin space
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strong reward to use it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead coupling: does post_residual still fit next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // harmonic compatibility: residual class matches next item class
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 8.0;
            }
            score -= (gap as f64).min(20.0) * 0.3;
        } else {
            score += (next_item_size - pr) as f64 * 0.25; // next item won't fit here
        }
    }

    // New-bin candidate handling: only open new bin when current residuals are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = bin_capacity as f64 - mean_residual;
        // Penalize new bin unless existing bins are heavily fragmented
        score += 30.0
            - (mean_residual / bin_capacity as f64) * 20.0
            - progress * 5.0
            + avg_fill * 0.05;
        if pr == bin_capacity {
            // large item into fresh bin is fine
            score -= 12.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;
    score += mean_residual * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    }
    if post_residual > 0 && post_residual < 10 && post_residual < next_item_size.min(100) as u32 && next_item_size > 0 {
        score += 25.0; // gap likely dead for the lookahead item too
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when placement here leaves a bad gap
    // or this bin's residual is already small relative to mean.
    if bin_residual == bin_capacity {
        if post_residual > 0 && post_residual <= 10 {
            score -= 70.0; // opening fresh bin avoids creating dead space
        } else {
            score += 15.0; // default: prefer existing bins
        }
        score += 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // If this bin's residual deviates far above mean residual, mildly discourage.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // 2-step lookahead: reward if next item fits exactly or well into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        // perfect chain match: post_residual == next_item_size
        if next_item_size == post_residual {
            score -= 60.0;
        } else {
            score -= next_fit * 25.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize dead space
        score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.5 + 10.0;
    }

    // Compare residual against mean residual of open bins
    score -= (post_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this is a perfect fit for the current item and lookahead is hopeless
    if bin_residual == bin_capacity {
        let perfect_now = post_residual == 0;
        let lookahead_bad = next_item_size == 0 || next_item_size > post_residual;
        if perfect_now {
            score -= 100.0;
        } else if lookahead_bad && item_size >= 60 {
            score -= 15.0;
        } else {
            // discourage opening new bins when decent fits exist
            score += 40.0 + open_bins_count as f64;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post residual too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: bonus if next item fits exactly in the post residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; slight penalty for wasting capacity.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 2 {
        let pressure = (open_bins_count as f64).ln();
        score -= 2.0 * pressure * tightness;
        // Penalize new bins more when many bins are open.
        if bin_residual == bin_capacity {
            score += 15.0 * pressure;
        }
    }

    // New-bin candidate: base penalty so it's only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Global residual alignment: prefer bins whose residual is close to the mean
    // (keeps residuals homogeneous, easier to pack future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer filling bins that are already heavily used (reduce bin count variance).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 5.0 * fill_ratio * fill_ratio;

    // Mild time-dependent exploration: slightly vary preference across the stream.
    let phase = ((step_index as f64) * 0.37).sin();
    score += 1.5 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual (tight fits)
    let mut score = norm_pr;

    // Non-linear polynomial coupling of post-residual with stream progress:
    // late in the stream, dead space becomes more costly (quadratic/cubic growth)
    let dead_penalty = norm_pr.powi(2) * (0.5 + 1.5 * progress) + norm_pr.powi(3) * (2.0 * progress);
    score += dead_penalty;

    // Reward near-perfect fits smoothly (residual close to 0)
    score -= 0.5 * (1.0 - norm_pr).powi(4);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0 * (1.0 + progress);
    }

    // New-bin candidate handling: empty bin should only win when current bin would
    // leave large dead space relative to the next item's needs
    if bin_residual == bin_capacity {
        let next = next_item_size as f64;
        if next > 0.0 {
            // penalty grows if the wasted space in current placement exceeds next item size
            let waste = (pr - next).max(0.0) / cap;
            score += waste * (1.0 + 3.0 * progress);
            // mild base preference against opening bins early
            score += 0.1 * (1.0 - progress);
        } else {
            score += 0.05;
        }
    } else {
        // reward bins whose post-residual can still host the lookahead item
        let next = next_item_size as f64;
        if next > 0.0 && pr >= next {
            score -= 0.3 * (1.0 - ((pr - next) / cap));
        }
    }

    // Slight preference for bins with below-average residual (consolidate fullness)
    score += 0.1 * ((pr - mean_residual) / cap).max(-1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into capacity fractions.
    let frac = post_residual as f64 / cap;
    let class = (frac * 10.0).floor() as u32; // 0..10 harmonic class

    // Penalize residuals that are "dead zones": too small to be useful but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward exact fits and near-exact fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Modulo arithmetic on post_residual: residuals divisible by 4 pair well with
    // common small item sizes (multiples of 4). Penalize odd, awkward residuals.
    if post_residual % 4 == 0 {
        score -= 6.0;
    } else if post_residual % 2 == 1 {
        score += 4.0;
    }

    // Harmonic coupling: if the next item fits exactly into the post residual,
    // strongly reward this placement (lookahead chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && (post_residual - next_item_size) <= 5 {
            score -= 20.0;
        } else if post_residual > next_item_size {
            // reward if post_residual - next_item stays in a good class
            let rem = post_residual - next_item_size;
            if rem % 4 == 0 {
                score -= 8.0;
            }
            if rem < 10 {
                score += 10.0; // next item creates a dead zone
            }
        } else {
            // next item won't fit here; slight penalty for tight bins
            score += 3.0;
        }
    }

    // Integer-division thresholds on residual class: very full bins (class 0-1)
    // are good; half-full leftovers (class 4-6) are mediocre.
    match class {
        0 | 1 => score -= 10.0,
        4 | 5 | 6 => score += 3.0,
        9 => score += 5.0, // nearly empty bin: opening/wasting capacity
        _ => {}
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless the item
    // is large relative to capacity or open bins are nearly full on average.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let large_item = item_size as f64 > 0.6 * cap;
    if bin_residual == bin_capacity {
        // New bin starts with residual = capacity; penalize so it loses unless
        // nothing fits well. Reward it for large items or when mean residual is low.
        score += 20.0;
        if large_item {
            score -= 30.0;
        }
        if mean_residual < 0.15 * cap && open_bins_count > 0 {
            score -= 25.0;
        }
        if post_residual % 10 == 0 {
            score -= 5.0; // clean harmonic residual for future items
        }
    } else {
        // Existing bin: reward tighter fits more when stream is far along
        // (consolidation matters more late in the stream).
        score -= 5.0 * (1.0 - progress) * (frac);
    }

    // Slight penalty proportional to bin fullness dispersion: prefer bins whose
    // residual is below the mean (fill the emptier-feeling bins first is bad;
    // actually prefer filling bins that are already fuller -> residual below mean).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are small but nonzero are "dead"
    // (unlikely to fit future items, whose sizes are >= 1 but often large).
    if post_residual > 0 && post_residual < 20 {
        score += 30.0 * (20.0 - post_residual as f64);
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 40.0 * tightness;

    // Open-bin pressure: discourage spreading into many bins unless the fit is good.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to mean residual of open bins (i.e., poor fits everywhere).
    if bin_residual == bin_capacity {
        score += 35.0;
        if item_size as f64 > mean_residual {
            score -= 55.0;
        }
        // Late in the stream, opening new bins is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: dead space confirmed.
        score += 15.0;
    }

    // Deviation from mean residual: prefer bins with less residual than average
    // (consolidate fullness) but avoid near-empty bins.
    score += 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: mild reward.
            score -= 0.5 * (next_item_size as f64 / post_residual as f64) * 10.0;
        } else {
            // Next item won't fit: penalize dead space created relative to mean residual.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score -= 0.2 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make empty bins slightly unattractive unless residual
    // situation is desperate (many open bins with low mean residual).
    if bin_residual == bin_capacity {
        score += 60.0 + 0.1 * mean_residual;
    }

    // Late in the stream, avoid opening new bins even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
