pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 + 2.0 * progress) - norm_post * (0.5 + 0.5 * progress);

    // Smooth interaction: dead space penalized more as stream progresses
    let dead_penalty = (norm_post * norm_post) * (progress * 30.0 + 5.0);

    // Lookahead: reward leaving room for the next item (smooth kernel)
    let next = next_item_size as f64 / cap;
    let lookahead = if next > 0.0 {
        let diff = norm_post - next;
        -8.0 * (-diff * diff * 20.0)
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor using the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // Mild preference for tighter bins overall
    let tightness = -0.1 * (item_size as f64 / cap);

    let mut score = post + poly * 10.0 + dead_penalty + lookahead + last_chance + tightness;

    // New-bin candidate: penalize slightly unless open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - norm_post).abs();
        score += 6.0 - 10.0 * fragmentation.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity fractions
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Classify post_residual into harmonic classes (1/2, 1/3, 1/4 of capacity)
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Perfect harmonic fits (post_residual exactly a unit fraction of capacity)
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual == half {
        score -= 20.0; // leaves exactly half: highly reusable
    } else if post_residual == third {
        score -= 15.0;
    } else if post_residual == quarter {
        score -= 10.0;
    } else {
        // Penalize dead space: small unusable residues
        if post_residual < quarter {
            score += (quarter - post_residual) as f64 * 0.6;
        }
    }

    // Modulo arithmetic on post_residual: residues divisible by common item classes
    let m = post_residual % 10;
    if m == 0 {
        score -= 5.0; // aligns with decade-quantized items
    } else {
        score += m as f64 * 0.4; // misaligned residue is harder to fill
    }

    // Lookahead coupling: does next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0; // chain placement possible
            // exact match bonus (harmonic pairing)
            if next_item_size == post_residual {
                score -= 12.0;
            }
        } else {
            // next item won't fit here; penalize more if the leftover is small
            score += (next_item_size - post_residual).min(30) as f64 * 0.3;
        }
    } else {
        // last item: prefer zero waste strongly
        score += post_frac * 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive
    if bin_residual == bin_capacity {
        // attractive only if current item is large or many open bins are fragmented
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_frac * cap) / cap;
        score -= 10.0 + 20.0 * progress + fragmentation.max(0.0) * 15.0;
        if item_size > half {
            score -= 8.0; // big items pair well with fresh bins
        }
    }

    // Mild preference for tighter bins overall
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Slight penalty for accumulating too many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead space below the minimum item size is pure waste.
            score += 60.0;
        } else if post_residual <= 20 {
            // Very small gaps are unlikely to be usable.
            score += 25.0;
        } else if post_residual <= 35 {
            score += 8.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fills relative to capacity.
    score -= 30.0 * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins; opening new bins becomes less attractive.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when pressure is high.
        score += 15.0 + 2.0 * pressure;
    } else {
        score -= 1.5 * pressure;
    }

    // Lookahead: if the next item could use the resulting residual,
    // reward leaving exactly that much space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size && post_residual <= next_item_size + 10 {
            score -= 10.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Residual too small for the next item: penalize.
            score += 12.0;
        }
    }

    // Prefer bins whose residual is near the mean (balance preservation).
    score += 0.3 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the leftover space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Slack after hypothetically placing the next item: tighter is better.
            score -= 40.0 - (post_residual - next_item_size) as f64 * 0.8;
        } else {
            // Next item won't fit here: penalize proportionally to overshoot.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean residual:
    // tighter-than-average bins are precious, use them first.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New empty bin candidate: only attractive when few bins fit the item
    // or the item is large (poor fit anywhere else).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { fitting_bins_count as f64 };
        let big_item = (item_size as f64 / bin_capacity as f64) > 0.7;
        if pressure <= 1.5 || big_item {
            score -= 60.0;
        } else {
            score += 80.0 + pressure * 10.0;
        }
    }

    // Penalize creating very small unusable slivers, unless they match next item.
    if post_residual > 0 && post_residual < 10 && post_residual != next_item_size {
        score += 25.0;
    }

    // Mild progression term: early in the stream, be more willing to open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items
    // (residual in (0, 10) is nearly unusable given min item size, but
    // items can be as small as 1, so scale by how "wasted" it feels).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item exactly fits the post residual,
    // strongly reward this placement (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item still fits here: mild reward proportional to leftover
            let l = post_residual - next_item_size;
            score -= 20.0 * (1.0 - (l as f64) / (bin_capacity as f64));
        } else {
            // next item cannot fit here: mild penalty, worse if gap is small
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 + 0.3 * gap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin is a fallback. Make it
    // attractive only when existing fits are poor (post_residual very large
    // relative to item, or few fitting bins).
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin; grows with number of open bins
        // and with stream progress (encourage consolidation late).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_cost = 8.0 + 0.5 * open_bins_count as f64 + 20.0 * progress;
        score += open_cost;
        // If the item fills a fresh bin well, opening is cheap.
        score -= 30.0 * ((item_size as f64) / (bin_capacity as f64));
    }

    // Global state: prefer packing into bins whose residual is below the
    // mean residual (i.e., already mostly full bins) to keep many
    // medium-residual bins available for future items.
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= 3.0 * diff.min(30.0);
        } else {
            score += 1.5 * (-diff).min(30.0);
        }
    }

    // Small bonus for exact fill.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let mut score = post * post / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in the stream, waste is cheap; late, it compounds.
    let progress_coupling = post * (0.5 + 1.5 * progress * progress);
    score += progress_coupling;

    // Reward filling bins nearly completely (smooth saturation term).
    let fill = 1.0 - post / cap;
    score -= 8.0 * fill * fill * fill;

    // Dead-space penalty: residuals too small for the smallest plausible item
    // (<= ~10) are useless; penalize quadratically.
    if post < 10.0 {
        score += (10.0 - post) * (10.0 - post) * 0.5;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement;
    // if next item is large and this bin is a poor fit for it, slight penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 3.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 1.5 * ((nxt - post) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0 * (1.0 - progress);
    }

    // New-bin candidate handling: opening a bin wastes the residual of all open bins.
    // Penalize a fresh bin unless the item fits poorly everywhere else.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let waste_proxy = mean_residual * open_bins_count as f64;
        score += 4.0 + 0.05 * waste_proxy;
        // If the item nearly fills a fresh bin exactly, opening is attractive.
        if post < 10.0 {
            score -= 12.0;
        }
    } else {
        // Slight preference for bins already below mean residual (balance residuals).
        score += 0.3 * (bin_residual as f64 - mean_residual);
    }

    // Mild penalty for accumulating many open bins early (encourage consolidation).
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Residuals divisible by common item classes (10, 20, 25, 50) are valuable.
    let pr = post_residual;
    let mut harmony_bonus = 0.0;
    if pr == 0 {
        harmony_bonus += 60.0; // perfect fit, ideal
    } else {
        if pr % 10 == 0 { harmony_bonus += 12.0; }
        if pr % 20 == 0 { harmony_bonus += 8.0; }
        if pr % 25 == 0 { harmony_bonus += 8.0; }
        if pr % 50 == 0 { harmony_bonus += 10.0; }
        // Integer-division thresholds: tiny unusable slivers are dead space.
        if pr < 10 { harmony_bonus -= 25.0; }
        else if pr <= 15 { harmony_bonus -= 8.0; }
        else if pr <= 30 { harmony_bonus += 4.0; }
    }
    score -= harmony_bonus;

    // Lookahead coupling: does post_residual harmonically fit the next item?
    if next_item_size > 0 {
        let gap = pr as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 45.0; // next item exactly fills this bin
        } else if gap > 0 && (gap as u32) % 10 == 0 {
            score -= 15.0; // next item leaves a harmonious remainder
        } else if gap < 0 && (-gap as u32) <= 10 {
            score += 12.0; // next item barely misses: bad pairing
        }
        // Modulo-class match between leftover and next item
        if next_item_size % 10 == pr % 10 && pr >= next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bins are badly fragmented
    // or the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual - (post_residual as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(0.5);
        score += 55.0 * pressure * (0.5 + 0.5 * progress);
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 70.0; // nothing fits well; fresh bin is right
        }
        if fragmentation < 0.0 { score += 10.0; }
    } else {
        // Tightness reward: closer fit among open bins wins.
        score -= (bin_capacity - bin_residual) as f64 * 0.15;
    }

    // Mild phase term: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are worthless.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fill
    } else if post_residual <= 10 {
        score += 150.0; // tiny unusable sliver -> heavy penalty
    } else if post_residual <= 25 {
        score += 60.0; // small gap, likely dead space
    } else if post_residual <= 50 {
        score += 15.0; // moderate gap
    } else {
        score -= 10.0; // large residual keeps flexibility
    }

    // Reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 120.0;
        } else if slack <= 20 {
            score -= 40.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 40.0; // next item can't use this sliver either
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Open-bin pressure: penalize opening new bins when many bins are already open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing residuals are badly fragmented.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let pressure = open_bins_count as f64 * 8.0 * (0.5 + progress);
        score += 250.0 + pressure - fragmentation.min(100.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // fresh bin useful for upcoming large item
        }
    } else {
        // Mild reward for keeping bin count stable.
        score -= 5.0;
    }

    // Mean-residual alignment: prefer bins whose residual is near the average (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-match lookahead: reward bins whose post residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // chain two items perfectly
        } else if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            // Favor leaving a usable, well-structured residual after the next item.
            score -= 6.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
            if slack_after_next < 10 {
                score += 8.0; // tiny dead sliver after two placements
            }
        } else {
            // Next item won't fit here after placement: penalize mildly, worse for tiny leftovers.
            score += 4.0 + 6.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Penalize creating unusable dead space relative to the smallest possible item (1).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Compare against mean residual: prefer bins that are already fuller than average
    // (tighter packing), i.e. lower post_residual than the mean.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when nothing decent exists among open bins.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin fine when items are large
        }
    }

    // Late in the stream: consolidate harder, discourage opening bins.
    let progress = step_index as f64 / total_items as f64;
    score += 8.0 * progress * (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).min(5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small post_residual, superlinearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powi(3);
        score += 40.0 * dead;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins that keep flexibility (mid-range residual).
        let spread = (post_residual as f64 - mean_residual).abs();
        score += 2.0 * spread / (fitting_bins_count as f64);
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize wasting post_residual.
            score += 0.05 * post_residual as f64;
        }
    }

    // New-bin candidate handling: empty bin gets a baseline penalty that shrinks
    // as the stream progresses (late in stream, consolidation matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - 0.5 * progress);
        // Opening a new bin is attractive if no open bin fits well.
        if post_residual == 0 && fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Prefer filling bins with lower residual than the mean (consolidate emptier bins).
    score += 0.08 * (mean_residual - bin_residual as f64);

    // Slight preference to keep number of open bins low as stream nears end.
    score += 0.3 * open_bins_count as f64 * progress;

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fills, penalize dead space non-linearly (quadratic waste).
    let mut score = pr + 0.9 * (pr * pr) / cap;

    // Smooth progress coupling: dead space becomes costlier late in the stream.
    let late = progress * progress;
    score += 25.0 * late * (pr / cap);

    // Lookahead synergy: reward residual that matches the next item size (smooth kernel).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        score -= 12.0 * (-diff * diff * 40.0).exp();
        // Penalize leaving residual just below next item (unusable for lookahead).
        let unusable = ((nxt - pr) / cap).max(0.0);
        score += 15.0 * (1.0 - (-unusable * unusable * 60.0).exp()) * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * (pr / cap);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Divergence from mean residual: prefer bins that keep residuals balanced.
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev - 3.0 * dev;

    // Mild preference for consolidating into fewer bins early on.
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 1.5;

    // New-bin candidate: penalize opening a fresh bin unless current item is large
    // and progress is high (future items may then pack better).
    if bin_residual == bin_capacity {
        let big = (item / cap).powi(2);
        score += 30.0 - 35.0 * big - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse granularity classes (mod 25, /10)
    let item_class = item_size / 10;
    let next_class = next_item_size / 10;

    // Reward tight fits strongly (near-perfect packing)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Dead space penalty: residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic coupling: does post_residual align with next item's class?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits exactly into this class of leftover
            let slack = post_residual - next_item_size;
            score -= (10 - slack.min(10)) as f64 * 0.8;
            // Bonus if next item nearly fills the remainder
            if slack <= 5 {
                score -= 8.0;
            }
        } else {
            // Leftover can't host next item: mild penalty scaled by mismatch
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Class-match bonus via integer division thresholds
        if post_residual / 10 == next_class && next_class > 0 {
            score -= 6.0;
        }
        // Modulo harmony: post_residual % 10 == 0 leaves clean class slots
        if post_residual % 10 == 0 && post_residual > 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(1.0);
        // Penalize opening new bins early; allow later when bins are fragmented
        score += 45.0 - 20.0 * progress;
        if item_size >= 60 && fitting_bins_count == 0 {
            score -= 50.0; // big item with no fitting bin: new bin is right
        }
        if mean_residual < item_size as f64 * 0.9 && fitting_bins_count > 0 {
            score += 15.0; // open bins are tight; discourage spreading
        }
        let _ = crowded;
    }

    // Prefer fuller bins generally (lower residual relative to mean)
    if (post_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += ((post_residual as f64) - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space (gaps too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 10.0 * open_bins_count as f64 + 20.0 * progress;
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate large gaps)
    if post_residual as f64 > mean_residual {
        score += 3.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain fit: excellent — residual gets consumed next step
            score -= 8.0 + 0.25 * next_item_size as f64;
        } else {
            // dead space penalty scaled by how badly next item misses
            let miss = (next_item_size - post_residual) as f64;
            score += 0.10 * miss;
        }
    }

    // Compare post_residual against mean residual: prefer bins whose
    // post-residual is close to mean (keeps distribution balanced)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge
    // relative to residual (avoid fragmenting many small bins)
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio < 0.7 {
            score += 15.0 + 20.0 * (0.7 - fill_ratio);
        } else {
            score -= 5.0;
        }
        // late in stream, prefer reusing existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 5.0; // next item won't fit here; mild penalty
        }
    }

    // Last-chance bin: strong incentive to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening bins when good fits exist,
    // but allow it when mean residual across open bins is small (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        score += 15.0 - 20.0 * fragmentation - 10.0 * progress;
        // Avoid hoarding too many open bins late in stream.
        score += 0.3 * open_bins_count as f64 * (1.0 - progress);
    } else {
        // Reward using existing bins, more so when many bins are open.
        score -= 0.15 * open_bins_count as f64;
    }

    // Prefer bins whose residual is close to mean residual (balanced usage).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Early stream: be slightly greedy toward exact fills.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (post_residual == 0) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Base: prefer tight fits via quadratic waste penalty (dead space grows quadratically).
    let mut score = norm_post + 0.9 * norm_post * norm_post;

    // Smooth polynomial coupling of waste with stream progress:
    // early on, waste is cheaper; late in the stream, dead space is penalized more.
    let progress_coupling = 1.0 + 1.6 * progress * (2.0 - progress);
    score *= progress_coupling;

    // Reward bins whose residual is "nearly consumed": smooth cubic-shaped bonus
    // around small post_residuals, avoiding a hard threshold.
    let tightness = (1.0 - norm_post).max(0.0);
    score -= 0.35 * tightness * tightness * tightness;

    // Lookahead coupling: if the next item fits the post-residual smoothly, reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 0.5 * (1.0 - slack) * (1.0 - slack);
        } else {
            // Next item won't fit: penalize proportionally to overshoot, smoothly.
            let over = (nxt - post) / cap;
            score += 0.25 * over * over;
        }
    }

    // Last-chance bin: strong smooth reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 1.2;
    } else {
        // Mild penalty proportional to abundance of alternatives (saturating form).
        let alt = (fitting_bins_count as f64).min(10.0) / 10.0;
        score += 0.15 * alt * alt;
    }

    // Mean-residual coupling: prefer bins deviating from the mean when mean is high
    // (consolidate large residuals), reward closeness to mean when mean is low.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 0.2 * dev * dev.abs().min(2.0);

    // New-bin candidate: penalize smoothly, more so early in the stream and when
    // many bins are already open (consolidation pressure grows over time).
    let is_new = (bin_residual as u32 == bin_capacity) && post_residual == bin_residual;
    if is_new {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 2.0 + 0.3 * open_pressure + 1.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by integer
    // division into "harmonic" capacity fractions (1/2, 1/4, 1/8 of capacity).
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Dead-space penalty: leftovers that no plausible item (1..=100) can use
    // well. Small leftovers are fine (near-perfect fit); mid-range leftovers
    // (quarter..half) are the classic "dead zone" for a 100-capacity bin.
    if post_residual > 0 {
        if post_residual <= eighth {
            score -= 6.0; // near-perfect fit: reward strongly
        } else if post_residual < quarter {
            score += 2.0;
        } else if post_residual <= half {
            score += 9.0; // worst harmonic class: half-empty bin
        } else {
            score += 4.0;
        }
    } else {
        score -= 12.0; // exact fill: bin closed perfectly
    }

    // Lookahead coupling: does the next item fit into the post-residual class?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can follow into this bin: reward proportional to how
            // "snug" the follow-up fit is (harmonic tightness).
            let tight = (post_residual - next_item_size) as f64;
            score -= 5.0 - (tight / 25.0).min(4.0);
        } else {
            // Next item will NOT fit here: penalize if we leave a large gap.
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / 10.0).min(10.0);
        }
    } else {
        // Last item of the stream: prefer closing bins exactly.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only open bin that can fit the item,
    // strongly prefer it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        // Many options: be pickier about dead space.
        score += post_residual as f64 * 0.05;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins are crowded
        // or the item is huge and would leave terrible harmonic waste anyway.
        let pressure = mean_residual / bin_capacity as f64;
        if pressure < 0.25 && open_bins_count > 0 {
            score += 20.0; // plenty of room elsewhere: keep using open bins
        } else {
            score += 3.0; // mild preference for consolidation
        }
        // Huge items (>= half capacity) start fresh bins happily.
        if item_size >= half {
            score -= 6.0;
        }
    }

    // Stream-progression modulation: late in the stream, favor tight fits
    // even more since bin count is what remains to be minimized.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.0 + progress * (post_residual as f64 * 0.1);

    // Small nudge toward bins below mean residual (consolidate emptier bins).
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item (1)
    // are worthless; residuals below the typical item floor are heavily penalized.
    if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 40.0; // unusable tiny gap -> strong penalty
    } else if post_residual < 20 {
        score += 12.0; // risky small gap
    } else {
        // mild reward for leaving medium usable space
        score -= 2.0;
    }

    // Reward bins whose residual exactly accommodates the next item (lookahead synergy)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins;
    // with few open bins, slightly favor tight fits anywhere.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.6 + 0.4 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (tighter than average) when mean is high
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 1.0 {
            score -= 3.0 * (1.0 - rel);
        } else {
            score += 3.0 * (rel - 1.0);
        }
    }

    // New-bin candidate: only attractive when no open bin leaves a decent gap
    if bin_residual == bin_capacity {
        if post_residual as f64 > mean_residual || fitting_bins_count == 0 {
            score -= 10.0; // opening fresh bin is fine
        } else {
            score += 20.0; // prefer existing bins with acceptable fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled mildly.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly or nearly matches the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post_residual as f64 - nxt).abs();
        if post_residual as u64 >= next_item_size as u64 {
            // Next item can chain into this bin: strong reward for exact match.
            score -= 30.0 * (1.0 - gap / cap);
            if gap < 1.0 {
                score -= 15.0; // perfect chain bonus
            }
        } else {
            // Dead space: post_residual too small for next item.
            score += 8.0 + 10.0 * (post_residual as f64 / cap);
        }
    }

    // Compare post_residual against mean residual of open bins:
    // leaving a residual near the mean keeps flexibility.
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: encourage filling existing bins rather than spreading.
    score += 0.4 * (open_bins_count as f64);

    // Early in stream: slightly prefer opening fresh bins for large items
    // (keep big residuals for later big items).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if item_size > bin_capacity / 2 {
        score += (1.0 - progress) * 10.0 * (post_residual as f64 / cap);
    }

    // New-bin candidate: penalize so it's chosen only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if item is large and stream is early, opening a fresh bin is fine.
        if item_size as f64 > 0.6 * cap && progress < 0.5 {
            score -= 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but penalize leaving
    // awkward slivers (< 10) that are hard to fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect closure is excellent
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // this is a great two-item chain; reward it.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += (next_item_size - post_residual as u32) as f64 * 0.15;
        }
    }

    // Penalize opening a new bin when there are many open bins with slack.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let slack_pressure = mean_residual / bin_capacity as f64;
        score += 35.0 + 25.0 * slack_pressure + 10.0 * (open_bins_count as f64).ln().max(0.0);
        // Early in the stream, new bins are cheaper; late, conserve bins.
        score += 20.0 * (1.0 - progress);
    } else {
        // Mild preference for bins with lower residual (best-fit tendency),
        // scaled by how many alternatives exist.
        score += (bin_residual as f64) * 0.1 * (fitting_bins_count as f64).min(5.0) / 5.0;
    }

    // Prefer bins below the mean residual slightly (balancing residual usage).
    score -= (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64 / bin_capacity as f64;
    // smooth non-linear coupling of post_residual with stream progress
    score += 40.0 * pr * pr * (0.5 + progress);
    score -= 25.0 * pr * (1.0 - pr) * (1.0 - progress);
    // lookahead: reward leaving room for the next item
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        score += 8.0;
    }
    // last chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }
    // penalize deviating from mean residual
    score += 0.3 * (post_residual as f64 - mean_residual).abs();
    // new-bin candidate: prefer it only when post_residual is large
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - pr);
        score -= 10.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic class of post_residual (exact classes are best).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else {
        // penalize awkward dead space classes: residuals that few future item sizes can use
        let usable = (1..=100).filter(|&s| (s as u32) <= post_residual).count() as f64;
        let waste = 1.0 - (usable / 100.0);
        score += 25.0 * waste * waste;
    }

    // Modulo-class harmony: reward residuals in "nice" classes (multiples of 10/5)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post {
            score -= 15.0;
            // harmonic bonus if next item exactly consumes a class boundary
            if post_residual as i64 - next_item_size as i64 >= 0 && (post_residual - next_item_size) <= 10 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize large leftover that blocks it
            score += 6.0;
        }
    } else {
        // last item: prefer any fit, prefer tight
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 3 {
        // many alternatives: be pickier about residual quality
        score += 3.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / cap).max(0.001);
        // base penalty so new bins are not opened frivolously
        score += 55.0;
        // if mean residual is small (bins nearly full), new bin becomes attractive
        score -= 40.0 * (1.0 - (mean_residual / cap)).min(1.0).max(0.0);
        // during early stream, opening bins is cheap
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        let _ = crowded;
    }

    // Mild preference for fuller bins overall
    score -= 0.05 * (cap - post);

    // Slight tie-break noise-free determinism via step coupling
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=9) are nearly unusable
    // (min item size is 10) -> heavy penalty; larger gaps decay quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Prefer larger usable leftovers, with diminishing returns.
        let pr = post_residual as f64;
        score -= 0.35 * pr - 0.0015 * pr * pr;
    }

    // Reward bins whose residual was already tight (efficient packing).
    let tightness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness;

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it when few bins exist (early stream).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin is penalized more as stream progresses and bins accumulate.
        score += 15.0 + 20.0 * progress + 0.8 * open_bins_count as f64;
        // If nothing open can fit, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it to avoid a new bin.
        score -= 25.0;
    }

    // Coupling with mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // partial reward proportional to how much of the post residual next item consumes
            let fill_frac = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * fill_frac;
        } else {
            // next item won't fit: penalize leaving post residual that is small/unusable
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare post_residual relative to mean residual of open bins.
    // Favor bins whose post residual ends up near mean (balanced) but penalize
    // leaving post residual far below mean (dead space).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += (mean_residual - pr) * 0.8;
    } else {
        score -= (pr - mean_residual) * 0.3;
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new empty bin unless item is large relative to capacity.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 50.0 + 200.0 * (1.0 - tightness);
    }

    // Late in stream: prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 100.0 * progress;
    } else {
        score += 100.0 * progress;
    }

    // Mild penalty for many open bins when placing in an empty bin.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post-residual is good).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item (<= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for blocking large leftover
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is expensive when few bins are
    // open or early in the stream; cheaper late when residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize new bins generally, but less when open bins are fragmented.
        score += 25.0 - 20.0 * fragmentation - 10.0 * progress;
        // If no open bin can fit, the new-bin call competes fairly; reduce penalty.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Prefer fuller bins relative to the mean residual (pack dense bins first).
    score -= 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Mild preference to keep number of open bins from exploding early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count as f64 > 10.0 * (1.0 - progress) + 2.0 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, mildly non-linear (quadratic waste penalty)
    let mut score = pr + 12.0 * norm_pr * pr;

    // Smooth coupling with stream progress: waste penalized more later in stream
    score *= 1.0 + 0.6 * progress * norm_pr;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness * tightness;

    // Penalize creating dead space that next item (lookahead) cannot use
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 6.0 + 4.0 * progress;
    }
    // Reward when post_residual can host the lookahead item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 4.0;
    }

    // Last-chance bin bonus: avoid opening a new bin when few fitting bins exist
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild pressure against proliferating bins relative to mean residual
    score += 0.02 * open_bins_count as f64;
    score -= 0.05 * (mean_residual - pr);

    // New-bin candidate: prefer only when residuals are large/wasteful elsewhere
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits are golden
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 15.0;
    }

    // Modulo arithmetic on post_residual: residuals in "friendly" classes
    // (multiples of 10 or 5 pair well with typical item sizes)
    let pr = post_residual;
    if pr >= 10 && pr % 10 == 0 {
        score -= 25.0;
    } else if pr >= 5 && pr % 5 == 0 {
        score -= 10.0;
    }
    // Penalize odd/awkward residual classes (prime-ish dead space)
    if pr > 10 && pr % 2 == 1 && pr % 5 != 0 {
        score += 8.0;
    }

    // Integer-division threshold: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 20.0;
            // harmonic bonus: next item lands post_residual near zero
            let nxt_post = pr - next_item_size;
            if nxt_post <= 5 {
                score -= 30.0;
            } else if nxt_post <= 15 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize small unusable leftovers
            if pr < 10 {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 40.0;
        if post_residual <= 20 {
            score -= 40.0;
        }
    }

    // New-bin candidate handling: only prefer fresh bin when it enables
    // a tight harmonic pairing with the next item (e.g. item+next ~ C)
    if bin_residual == bin_capacity {
        score += 30.0; // default: prefer existing bins
        if next_item_size > 0 && item_size + next_item_size >= bin_capacity - 5 {
            score -= 120.0; // open new bin for a perfect pair
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Tightness ratio: reward bins whose residual is mostly consumed
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Stream progression: late in stream, be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fill);

    // Mean residual coupling: if open bins are loose on average,
    // penalize leaving this one loose too (consolidation pressure)
    if post_residual as f64 > mean_residual {
        score += 5.0;
    } else {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // "Almost dead" gaps: usable only by tiny items, heavily penalized.
        score += 30.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Perfect or near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual is tightly consumed by the item
    // (relative fill efficiency), scaled by how "tight" the fit is.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely good; encourage closing bins out.
    score += 2.0 * open_bins_count as f64 * (1.0 - tightness);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when the
    // item would leave a large, flexible residual AND open bins are crowded
    // or the fit elsewhere is poor.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin grows with stream progress and
        // with the number of already-open bins.
        score += 15.0 + 3.0 * open_bins_count as f64;
        // But a large item (leaving small residual) in a fresh bin is fine.
        score -= 0.3 * item_size as f64;
        // If no open bin fits, opening is nearly mandatory.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement strongly (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 35.0;
        } else if slack <= 10 {
            score -= 15.0;
        }
    }

    // Mean-residual coupling: prefer bins below the mean residual (tighter
    // bins), gently.
    score += 0.5 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    // Slight late-stream conservatism: waste matters more as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item size -> chain fill
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Post-residual can also host the next item (partial lookahead reward)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0 + 0.05 * (post_residual as f64 - next_item_size as f64);
    }

    // Penalize dead space below typical minimum item size
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 5.0;
    }

    // Relative to mean residual: prefer bins already below-average residual (tighter bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score -= pressure;
        score += 5.0; // base cost of opening a new bin
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize dead space that cannot fit a typical future item.
    let dead = if post_residual < 10 { post_residual as f64 * 2.5 } else { 0.0 };
    score += dead;

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0 + 0.1 * (next_item_size - post_residual) as f64;
        }
        // Perfect two-item chain: residual fits next item snugly.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize wasting large residual space on small items.
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.15 * waste;

    // Prefer bins tighter than average (best-fit flavor).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when it enables a large future capacity,
    // and especially when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        // Early stream: new bins cheap; late stream: squeeze into open bins.
        score += 30.0 * progress + pressure - 0.1 * open_bins_count as f64;
        if next_item_size >= item_size && next_item_size > 0 {
            score -= 10.0; // big item coming next benefits from fresh capacity
        }
    }

    // Discourage leaving residuals in the awkward 1..10 band after placement.
    if post_residual >= 1 && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer small post_residual, with smooth polynomial coupling to progress.
    let mut score = pr * (1.0 + 0.8 * progress) + 0.35 * pr * pr / cap;

    // Penalize large dead space relative to capacity, amplified late in the stream.
    let dead_frac = pr / cap;
    score += 12.0 * dead_frac * dead_frac * (0.5 + progress);

    // Lookahead coupling: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            // post_residual can't fit next item: mild penalty scaled by unusable fraction
            score += 4.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0 * (1.0 - dead_frac);
    }

    // New-bin candidate: penalize opening a new bin, more so when other bins fit
    // and mean residual is high; relax penalty when open bins are scarce.
    if is_new_bin {
        let scarcity = if open_bins_count == 0 { 1.0 } else { 1.0 / open_bins_count as f64 };
        let fit_pressure = fitting_bins_count as f64;
        score += 20.0 / (1.0 + fit_pressure) - 10.0 * scarcity + 8.0 * (mean_residual / cap);
    } else {
        // Slight reward for using existing bins as stream progresses.
        score -= 2.0 * progress;
    }

    // Tight-fit reward: near-perfect fills get strong discount.
    if pr <= 2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into capacity fractions.
    // Residuals in the "awkward band" (just above small-item sizes) are dead space; penalize them.
    let q = (post_residual * 4) / bin_capacity; // 0..=3 classes: [0,25),[25,50),[50,75),[75,100]
    let class_penalty: f64 = match q {
        0 => 6.0,   // tiny leftover: nearly perfect fit, but if 0 it's ideal
        1 => 10.0,  // 1..25 leftover: hard to fill -> dead space
        2 => 4.0,   // 25..50: fillable by mid items
        _ => 0.0,   // large leftover: flexible
    };
    score += class_penalty;

    // Perfect fit is the gold standard.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: reward bins whose post-residual exactly accommodates the next item
    // (harmonic pairing), punish near-misses that strand space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 40.0; // chains two perfect fits
            } else if gap <= 10 {
                score -= 15.0; // near-chain
            } else {
                score += gap as f64 * 0.3; // leftover after hypothetical next placement
            }
        } else {
            score += 3.0; // next item can't use this bin's leftover anyway
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fullness * (open_bins_count as f64).ln().max(1.0) * 8.0;

    // Mild pull toward mean residual: avoid creating outliers far below mean.
    score += ((mean_residual - post_residual as f64) / bin_capacity as f64).abs() * 5.0;

    // Late in the stream, tighten packing: waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * progress * 0.5;

    // New-bin candidate: only attractive when item is large relative to a fresh bin
    // and no good open fit exists (post_residual large means poor fit elsewhere).
    if bin_residual == bin_capacity {
        score += 12.0; // default cost of opening a bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // fresh bin can absorb the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pre = bin_residual as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let mean_norm = (mean_residual.max(0.0) / cap).clamp(0.0, 1.0);
    let open_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 6.0))
        * (0.65 + 0.35 * mean_norm);
    let fitting = fitting_bins_count as f64;
    let is_new = if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    let mut score = post;

    // Favor tight fills of already-open bins, especially when many bins are open.
    let tightness = (item / pre.max(1.0)).clamp(0.0, 1.0);
    score -= cap * 0.06 * tightness * (1.0 - is_new) * (0.55 + 0.45 * open_pressure);

    // Strong reward for completely closing a bin.
    if post <= 0.0 {
        score -= cap * 0.14;
    }

    // Reward leaving enough room for the lookahead item, especially a near-exact fit.
    if next > 0.0 && post >= next {
        score -= cap * 0.15 * (next / post.max(1.0)).min(1.0);
    }

    // Penalize positive residual that is too small for the next item: a likely dead gap.
    if next > 0.0 && post > 0.0 && post < next {
        let missing = ((next - post) / cap).clamp(0.0, 1.0);
        let severity = 0.22 + 1.15 * missing;
        score += cap * severity * (0.55 + 0.45 * open_pressure + 0.15 * progress);
    }

    // Last-chance protection: if this is the only open bin that fits, avoid opening a new bin.
    if is_new < 0.5 && fitting <= 1.0 {
        let defer_new_until_next =
            next > 0.0 && post < next && pre <= (cap - next).max(0.0);

        let last_chance_reward = if defer_new_until_next {
            0.30 + 0.20 * open_pressure + 0.10 * progress
        } else {
            0.08 + 0.08 * open_pressure
        };

        score -= cap * last_chance_reward;
    }

    // Pressure against opening another bin when existing bins can already fit the item.
    if is_new > 0.5 && fitting > 0.0 {
        let crowding = 1.0 + 0.06 * (fitting - 1.0).min(6.0);
        score += cap * (0.08 + 0.25 * open_pressure + 0.10 * progress) * crowding;

        // Extra penalty if a new bin would itself leave a dead gap for the next item.
        if next > 0.0 && post < next {
            score += cap * 0.04;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        let match_quality = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 25.0 * match_quality;
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover; penalize dead space more strongly.
        score += 8.0;
    }

    // Reward bins whose residual is near the item size (tight fit).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 20.0 * tightness;

    // Relative to mean residual: prefer bins below mean residual (fuller bins).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when open bins can fit the item.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64;
    }

    // Late in the stream, be more conservative: keep bins tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized waste of this placement
    let waste_norm = post_residual as f64 / bin_capacity as f64;

    // Strongly reward tight fits (small post_residual) with a non-linear term
    score += 8.0 * waste_norm * waste_norm;

    // Exact / near-exact fit bonus
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead: reward if the residual left behind can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / bin_capacity as f64);
    }
    // Penalize leaving a residual that is just barely too small for the next item (dead zone)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into existing bins
    score += 0.8 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual deviates favorably from the mean: filling below-mean
    // residual bins keeps a diverse set of residuals available
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Early in the stream: be more willing to open new bins (keep flexibility);
    // later: pack tightly into existing bins
    score += 10.0 * (1.0 - progress) * (bin_residual == bin_capacity) as f64 * 0.0; // placeholder removed below
    score -= 6.0 * progress * (1.0 - waste_norm);

    // New-bin candidate handling: empty bin gets a base cost so it is only chosen
    // when fits in open bins are poor, but the cost shrinks early in the stream
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let base = 18.0 - 10.0 * (1.0 - progress);
        score += base;
        // If nothing else fits well (large waste everywhere), new bin becomes attractive
        // (handled implicitly since poor fits carry high waste penalties).
        // Slight extra nudge when next item is large (needs fresh space)
        if next_item_size > bin_capacity / 2 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with non-linear shaping (favor small but not zero dead space)
    let mut score = pr - 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * cap * 0.1;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste tolerance is higher; late, penalize residual heavily.
    let coupling = pr * (0.5 + 2.0 * progress * progress) - pr * pr / (2.0 * cap) * (1.0 + progress);
    score += 0.3 * coupling;

    // Last-chance bonus: smooth reward scaled by scarcity of fitting bins
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 12.0 * scarcity * (1.0 - progress * 0.5);

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 6.0 * (1.0 - nxt / cap) * (1.0 - progress * 0.3);
        } else {
            score += 4.0 * ((nxt - pr) / cap);
        }
    }

    // Mean residual coupling: prefer bins near the mean (keeps residuals uniform)
    score += 0.5 * ((pr - mean_residual) / cap).abs();

    // Penalize opening new bins when open bins exist and fit is decent
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 * (1.0 - progress) + 5.0;
    }

    // Mild penalty for many open bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near "nice" fill levels
    // (multiples of 25, 50) are more reusable than awkward leftovers.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect closure
    } else if pr % 50 == 0 {
        -30.0
    } else if pr % 25 == 0 {
        -18.0
    } else if pr % 10 == 0 {
        -10.0
    } else if pr < 10 {
        25.0 // dead space below min item size
    } else {
        0.0
    };
    score += class_bonus;

    // Dead-space penalty: residual that no plausible item (1..=100) can use well.
    if pr > 0 && pr < 10 {
        score += 20.0;
    } else if pr >= 10 {
        // fraction of residual usable by items up to 80: small residuals waste less
        let usable_frac = (pr.min(80) as f64) / (pr as f64);
        score -= 8.0 * usable_frac;
    }

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 15.0; // chain placement possible
            // extra reward for tight chained fit (harmonic alignment)
            let gap = pr - next_item_size;
            if gap % 10 == 0 {
                score -= 6.0;
            }
        } else if next_item_size > bin_residual {
            // next item forces a new bin anyway; keep this bin flexible
            score += 4.0;
        } else {
            score += 10.0; // placing here strands the next item
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are crowded.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin; cheaper late in stream? no—cheaper
        // when many items remain to amortize it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 + 25.0 * progress;
        // if next item is huge and current item is small, opening fresh may be wise
        if next_item_size >= 60 && item_size <= 20 {
            score -= 20.0;
        }
    }

    // Prefer filling bins with larger residual gaps less tightly packed than mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Tight fit reward: small post residual relative to item
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 5.0 * tightness;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps that no future item (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    } else if post_residual > 0 && post_residual < next_item_size as f64 * 1.0 && next_item_size > 0 {
        // Gap unusable by the lookahead item: penalize proportionally.
        score += 50.0 + (next_item_size as f64 - post_residual as f64) * 2.0;
    }

    // Reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 300.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Last-chance bonus: only one bin fits the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Lookahead synergy: if next item fits exactly in the post-residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but ease off near the end of the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 - mean_residual / 10.0) * (1.0 - 0.5 * progress);

    // New-bin candidate: neutral-ish baseline so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 40.0 - mean_residual * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled by capacity fraction.
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64);

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0;
        } else {
            // Penalize leftover space that the next item cannot use.
            let next_fits = next_item_size <= post_residual;
            if !next_fits {
                score += 0.35 * post_residual as f64;
            } else {
                score += 0.25 * diff as f64;
            }
        }
    } else {
        // Last item: pure tightness matters.
        score -= 5.0;
    }

    // Compare residual against mean residual across open bins.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a brand-new bin when decent fits exist,
    // unless the item would leave a very large unusable residual everywhere.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score += 10.0; // a fresh bin is fine if next item could go here too
        }
        // Late in the stream, be more conservative about new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild penalty for very small post_residuals that create dead space
    // unusable by typical items (sizes >= 1, but tiny slivers waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize large post_residual that cannot fit the next item (dead space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins whose leftover can host the lookahead item.
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Dead space relative to next item.
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.35;
        if fitting_bins_count == 0 || (poor_fit && post_residual as f64 > mean_residual * 0.5) {
            score -= 12.0 + 10.0 * progress;
        } else {
            // Discourage opening new bins when existing ones can take the item.
            score += 30.0 + 5.0 * open_bins_count as f64;
        }
    }

    // Mild preference for bins below mean residual (balance load across bins).
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // Small early-stream exploration bonus toward tighter residual bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with quadratic smoothing
    let mut score = norm_pr * norm_pr * cap;

    // Smooth polynomial coupling with stream progress: late in stream, prize tightness more
    score += (1.0 - progress) * (pr * 0.5) + progress * (norm_pr * norm_pr * 40.0);

    // Reward filling bins deeply: interaction of item_size fraction with residual
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * fill_frac * 30.0;

    // Penalize very small post residuals only if next item could have used them (smooth gate)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += (gap / cap) * (gap / cap) * 50.0;
        // Reward when post residual matches next item size (smooth)
        let match_term = 1.0 - ((pr - next_item_size as f64).abs() / cap);
        score -= match_term.max(0.0) * 8.0;
    } else {
        // Last item: strongly prefer minimal post residual
        score += norm_pr * 10.0;
    }

    // Last-chance bin bonus (smooth): if it's the only fitting bin, favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Prefer bins deviating below mean residual slightly (balance with tightness)
    score += ((mean_residual - pr) / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward zero post-residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by size class.
    // Small-but-nonzero residuals (<10) are nearly useless dead space -> penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Class-based penalty: residual in (0, 10) mod classes of 5 -> fine-grained waste tiers.
    let waste_class = post_residual / 5; // integer division harmonic class
    score += (waste_class as f64) * (waste_class as f64) * 0.5;

    // Reward when the lookahead item fits exactly into post_residual (chain fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        if slack_after_next == 0 {
            score -= 400.0; // perfect chain: item then next item fills bin completely
        } else {
            // reward proportional to how well next item packs the remainder
            let ratio = slack_after_next as f64 / post_residual as f64;
            score -= 60.0 * (1.0 - ratio);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post_residual cannot host next item: dead space penalty scaled by proximity
        score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bonus: only one bin can fit this item; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer tighter (fuller) bins generally: tighter bin => smaller residual before placement.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Mean-residual coupling: if this bin's residual is far below mean, it's already tight; slight reward.
    let diff = mean_residual - bin_residual as f64;
    score += 0.2 * diff;

    // Modulo harmonic class on post_residual: multiples of 5 and 10 are "clean" classes;
    // odd awkward remainders are penalized slightly.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    } else if post_residual % 2 == 1 && post_residual < 30 {
        score += 6.0;
    }

    // New-bin candidate handling: empty bin should only win when current fit is bad.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 120.0;
        // cheaper to open new bin late in stream? no: late stream => fewer future items, avoid waste
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * progress;
        // if next item is large and current best fits poorly, new bin is attractive
        if next_item_size > 60 {
            score -= 70.0;
        }
        // if many bins are open and mean residual is high, prefer packing existing bins
        score += 0.3 * mean_residual;
        // if this is the only fitting option context (few fitting bins) and item is large, ease opening
        if fitting_bins_count <= 1 && item_size > 50 {
            score -= 90.0;
        }
    }

    // Harmonic threshold on item size classes (integer division by 20).
    let item_class = item_size / 20;
    score += match item_class {
        0 => -3.0, // tiny items fit anywhere; slight preference to dump them in tight bins
        1 => 0.0,
        2 => 2.0,
        _ => 4.0,  // huge items: prefer bins they barely fit -> post_residual already low
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity.max(1) as f64;
    let pre = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let item = item_size as f64;
    let open = open_bins_count as f64;
    let fit = fitting_bins_count as f64;

    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = open.min(80.0);
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post + 0.03 * (post - mean_residual).max(0.0);

    // Perfect closure is the best possible dead-space outcome.
    if post == 0.0 {
        score -= 3.0 + 3.0 * progress;
    }

    // Penalize a nonzero leftover that is already known to be too small
    // for the lookahead item.
    let dead_gap = if next > 0.0 && post > 0.0 && post < next {
        next - post
    } else {
        0.0
    };

    if dead_gap > 0.0 {
        score += 5.0 + dead_gap * (1.2 + 1.6 * progress + 0.025 * open_pressure);

        // If this existing bin could have served the next item before insertion,
        // using it for the current item destroys that opportunity.
        if !is_new_bin && pre >= next {
            score += 3.0 + 5.0 * progress;
        }
    }

    if is_new_bin {
        // Opening a new bin is costly, especially late in the stream and when
        // many bins are already open.
        score += 4.0 + 4.0 * progress + 0.075 * open_pressure;

        // Do not bypass the last existing fitting bin unless the dead-space
        // penalty is truly severe.
        if fit <= 1.0 {
            score += 6.0 + 4.0 * progress;
        }

        if next > 0.0 {
            if post >= next {
                // A new bin that can also absorb the lookahead item is mildly attractive.
                score -= 1.0 + 2.0 * (next / cap);
            } else if mean_residual < next {
                // The new bin cannot take the next item, and the average open pool
                // probably cannot either.
                score += 2.0;
            }
        }
    } else {
        // Mild pressure toward consolidating into existing bins.
        score -= 0.01 * open_pressure;

        // Strongly favor the last existing bin that can fit the item.
        if fit <= 1.0 {
            score -= 7.0 + 5.0 * progress + 0.02 * open_pressure;
        }

        // Reward leaving enough room for the lookahead item.
        if next > 0.0 && post >= next {
            score -= 0.8 + 1.5 * (next / cap);
        }

        // Crumb guard: very small leftovers are treated as risky dead space.
        let crumb_floor = 0.08 * item;
        if post > 0.0 && post < crumb_floor {
            score += 0.8 + 0.05 * (crumb_floor - post);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this placement chains into a perfect fill later.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Next item fits comfortably (leaves room again): mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
    }
    // Next item CANNOT fit into post-residual: dead space unless item is tiny.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0 + (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Prefer bins tighter than the mean residual (good fits), penalize loose bins.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Penalize very small unusable leftovers.
    if post_residual < 10 {
        score += 40.0;
    }

    // Early in the stream, be slightly conservative about filling bins too tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a quadratic penalty
    // on large dead space so badly-fitting bins are strongly deprioritized.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Lookahead: if the next item can fit into the post-residual, reward this bin
    // (chaining placements); otherwise penalize dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += (next_item_size as f64 - pr).min(40.0) * 0.25;
        }
    }

    // Last-chance bonus: if this is the only bin that fits the item, strongly
    // prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Time horizon: early in the stream, be pickier about fragmenting bins
    // (more items remain to fill residual space); late in the stream, just
    // fill whatever fits to avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * pr * 0.5;

    // Global state coupling: when open bins are already loose on average
    // (high mean residual), avoid adding fragmentation to this bin; when bins
    // are tight overall, tolerate imperfect fits rather than opening new bins.
    score += 0.15 * (mean_residual - pr).abs();
    if pr < mean_residual {
        score -= 2.0;
    }

    // New-bin candidate handling: an empty bin scores as its full residual.
    // Prefer opening a new bin only when no open bin is a decent fit, i.e.
    // when the best possible post-residual here would still be very small.
    if bin_residual == bin_capacity {
        // Slight preference against opening new bins when existing bins fit well
        // (fitting_bins_count > 1 means several alternatives exist).
        score += 3.0 + (open_bins_count as f64 * 0.05);
        if fitting_bins_count >= 1 {
            score += 8.0; // push new bin below good existing fits
        }
    } else if pr < 5.0 {
        // Excellent fit: reward strongly.
        score -= 5.0;
    }

    // Mild penalty for spreading across too many open bins when residuals are large.
    if open_bins_count > 8 && mean_residual > 30.0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: penalize post residual quadratically (dead space grows in value over time)
    let mut score = pr + 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Tight fits rewarded, smoothly
    let fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit * fit;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // Lookahead: reward if next item fits post residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = 1.0 - (pr - nx) / cap;
            score -= 12.0 * slack * slack;
        } else {
            score += 8.0 * ((nx - pr) / cap);
        }
    }

    // Spread penalty relative to mean residual
    score += 3.0 * (pr - mean_residual).abs() / cap;

    // Mild encouragement to consolidate when many bins open
    score += 2.0 * (open_bins_count as f64 / (total_items as f64 + 1.0)).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are "clean"
    // fractions of capacity (divisible by common item size classes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left

    // Penalize small unusable leftovers (dead space) super-linearly.
    if post_residual > 0 {
        score += 40.0 / (1.0 + pr);
        if post_residual < 10 {
            score += 25.0; // dead space under smallest item class
        }
    } else {
        score -= 15.0; // perfect fit: bin closed
    }

    // Modulo-class harmony: post residual divisible by 10 / 25 / 50 is reusable.
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            // harmonic fit quality of the next item in this bin
            score -= 6.0 * (nxt / (1.0 + pr)) * (1.0 - (pr - nxt) / cap);
        } else {
            // next item cannot follow here: slight penalty scaled by tightness
            score += 4.0 * (1.0 - frac);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (large item, or many bins but few fit).
    if bin_residual == bin_capacity {
        let base = 55.0
            - 6.0 * (fitting_bins_count as f64)
            - 10.0 * (item_size as f64 / cap);
        // late in stream, opening fresh bins is cheaper than fragmenting
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = base + 20.0 * (1.0 - progress);
    }

    // Mild preference for tight fits overall.
    score -= 10.0 * (1.0 - (item_size as f64 / bin_residual.max(1) as f64).min(1.0));

    // Mean residual context: if this bin is far below mean residual, it's a
    // good "filler" target; if far above, deprioritize.
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, minimum item size)
    // are pure waste; penalize them heavily with a nonlinear blow-up.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 8.0 * (10 - post_residual) as f64;
    }

    // Larger dead space is progressively worse the tighter it is relative to
    // plausible item sizes (10..80): gaps in [10, 30) are awkward.
    if post_residual >= 10 && post_residual < 30 {
        score += 6.0 + 0.25 * (30 - post_residual) as f64;
    }

    // Perfect fit is highly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, favor filling existing ones
    // (penalize the new-bin candidate and lazy spreading).
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // If next item cannot fit in post-residual but the gap is small, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    // Prefer bins whose residual is close to the item (tight fit) over bins
    // with lots of slack being consumed carelessly.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 10.0 * tightness;

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 12.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "ragged"; filling it is fine. If residual is above mean
    // (a roomy bin), slight penalty to keep uniform-ish residuals.
    if (bin_residual as f64) > mean_residual + 20.0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward when next item exactly fits the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; leftover becomes dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }

        // Bonus if next item pairs perfectly with current fill (item + next == capacity usage)
        if item_size + next_item_size == bin_residual {
            score -= 40.0;
        }
    } else {
        // Last item: strongly prefer minimal leftover
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: prefer bins that are already more filled than average
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let large_item = item_size as f64 / bin_capacity as f64;
        // penalize new bin normally, but discount when item is large or nothing fits
        score += 35.0 - 30.0 * pressure - 20.0 * large_item;
        // if next item is large and would waste a fresh bin, discourage slightly less
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Slight penalty for spreading across too many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: small post-residual is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that next item cannot use.
    if next_item_size > 0 {
        if post_residual > 0 && (next_item_size as u32) > post_residual {
            score += 0.6 * (post_residual as f64);
        } else if next_item_size as u32 <= post_residual && post_residual > 0 {
            // reward bins whose leftover can host the lookahead item
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        }
    }

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Fragmentation penalty relative to mean residual of open bins.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Discourage growing the fleet of open bins mildly.
    score += 0.25 * open_bins_count as f64;

    // Time horizon: late in the stream, be conservative — avoid new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item fits badly everywhere (large post_residual penalty
    // already applied) or early in the stream.
    if bin_residual == bin_capacity {
        let open_bias = 8.0 + 20.0 * progress + 0.3 * open_bins_count as f64;
        score += open_bias;
        // If lookahead is large, a fresh bin is more useful.
        if next_item_size > 60 {
            score -= 6.0;
        }
    } else {
        // Existing bins get a modest discount vs a new bin baseline.
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x);
    score -= 40.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as the stream progresses
    score -= (1.0 - x) * (1.0 - x) * 10.0 * (0.3 + 0.7 * progress);

    // Penalize dead space that can't fit the next item
    if next_item_size > 0 && pr > 0.0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (1.0 + progress);
        } else {
            score -= 3.0 * (1.0 - (pr - nx) / cap) * progress;
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when few fitting bins remain
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 6.0 * progress;
    }

    // Mildly discourage accumulating many open bins early
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // Prefer bins with residual near the mean (balanced packing)
    score += (pr - mean_residual).abs() * 0.05 * (1.0 - progress);

    // New-bin candidate: penalize slightly so it's chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize dead space in low harmonic classes (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Reward near-perfect fits (small but nonzero post_residual is fine, zero is ideal)
    if post_residual == 0 {
        score -= 100.0;
    }

    // Integer division thresholds: post_residual classes of bin_capacity/4
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual <= quarter {
        score -= 10.0; // tight packing class
    } else if post_residual <= half {
        score += 5.0; // mid class, moderate
    }

    // Modulo coupling: post_residual divisible classes
    let m = post_residual % 25;
    score += m as f64 * 0.3;

    // Lookahead: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64 / cap) * 20.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here; penalize leaving large residual unusable for it
        score += (post_residual as f64 - (next_item_size as f64 - post_residual as f64)) * 0.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless current bins are fragmented
    if bin_residual == bin_capacity {
        score += 15.0;
        if mean_residual < cap * 0.25 && open_bins_count > 0 {
            score -= 30.0; // open bins are tight, new bin ok
        }
    }

    // Progression coupling: later in stream, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + progress * 0.2;

    // Mean residual alignment: prefer bins near mean residual
    score += (pr - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later are costly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64 + 1.0);
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 10.0;
        }
        if post_residual > 0 && (post_residual as u32) < next_item_size && post_residual < 10 {
            score += 15.0; // blocks next item in a tiny gap
        }
    }

    // Open-bin pressure: prefer filling existing bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Mild preference to use fuller bins (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    // New-bin candidate: make empty bins moderately attractive only when
    // no good fit exists elsewhere (handled via penalties above); slight base cost.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize if we leave dead space next item can't use
        let dead = (post_residual as f64).min(next_item_size as f64);
        score += 8.0 * dead / bin_capacity as f64;
    }

    // Relative to mean residual: prefer bins with residual below mean (consolidating space)
    score += 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless lookahead really wants it
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size >= 40 && item_size >= 40 {
            score -= 25.0;
        }
    }

    // Early in stream: slightly favor opening bins for flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post-residual non-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Perfect or near-perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    }
    // Penalize leftovers that are small but cannot fit the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state coupling: if mean residual is high, prefer filling fuller bins.
    score += 0.1 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: opening a new bin is attractive only if no
    // decent fit exists (many open bins, poor residual usage).
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else {
            (open_bins_count as f64).ln().max(0.0) / (fitting_bins_count as f64).max(1.0)
        };
        let item_heavy = item_size as f64 / bin_capacity as f64;
        score += 40.0 - 25.0 * pressure - 20.0 * item_heavy;
        // Late in stream, avoid scattering.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: non-linear cost of leftover space (dead space grows superlinearly
    // as it becomes unusable relative to typical item sizes).
    let mut score = pr.powf(1.4);

    // Stream-progress coupling: later in the stream, waste is costlier.
    score *= 1.0 + 0.8 * progress * (pr / bin_capacity as f64);

    // New-bin candidate: generally penalized, but the penalty shrinks when
    // few bins fit (last-chance / no alternative) and early in the stream
    // (investing in a fresh bin pays off over many future items).
    if is_new_bin {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { (fitting_bins_count as f64).recip() };
        let invest = (1.0 - progress).powf(2.0);
        score += 30.0 * scarcity * (0.4 + 0.6 * progress) - 25.0 * invest;
    } else {
        // Reward tight fits (small post_residual) more strongly mid-stream.
        score -= 6.0 * (1.0 - pr / bin_capacity as f64).powf(2.0) * (0.5 + progress);
    }

    // Lookahead: bonus if the next item fits the post-residual exactly-ish;
    // penalty if post-residual is a dead sliver that blocks nothing but wastes.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_quality = 1.0 - ((pr - nxt) / bin_capacity as f64);
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            // Residual too small for next item: penalize proportionally to waste.
            score += 4.0 * (pr / nxt) * (0.5 + progress);
        }
    }

    // Prefer spreading across bins when many are open with high mean residual
    // (consolidation pressure); reward filling a bin close to mean residual.
    if !is_new_bin && open_bins_count > 1 {
        let gap = (mean_residual - pr).abs();
        score += 0.05 * gap * (1.0 - progress);
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small"
    // residue classes are nearly full; reward closing them out.
    let pr = post_residual as i64;
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Class A: post_residual <= 10 -> essentially perfect fit, strong reward.
    if pr <= 10 {
        score -= 40.0 + (10 - pr) as f64 * 2.0;
    }
    // Class B: 11..=25 -> good leftover, mild reward.
    else if pr <= 25 {
        score -= 12.0 + (25 - pr) as f64;
    }
    // Class C: 26..=50 -> medium dead space, mild penalty.
    else if pr <= 50 {
        score += (pr - 25) as f64 * 0.4;
    }
    // Class D: >50 -> wasteful split, strong penalty.
    else {
        score += (pr - 50) as f64 * 0.9;
    }

    // Harmonic coupling: does the NEXT item fit into the leftover?
    // Perfect harmonic follow-up (next item exactly fills leftover) is ideal.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // exact complement
        } else if next_item_size < post_residual {
            let npost = post_residual - next_item_size;
            // reward small second-order leftovers
            score -= (1.0 - npost as f64 / cap) * 8.0;
            if npost <= 10 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this leftover: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline so we only open a new bin
    // when no open bin offers a decent fit. New bin starts with full residual;
    // penalize it slightly unless current open bins are all bad fits.
    if bin_residual == bin_capacity {
        score = cap * 0.55; // baseline: mid-range, beats only bad fits
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            score += 5.0; // keep the last-chance bin instead
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        score += open_bins_count as f64 * 0.5;
    }

    // Mean-residual pressure: if open bins are already loose, prefer the tightest.
    if bin_residual != bin_capacity {
        score += (mean_residual - frac * cap) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever host
    // typical items (1..=10) are almost surely wasted -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 45.0;
    } else if post_residual > 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if the next item can no longer fit after this placement,
    // this placement likely strands the bin -> penalize proportionally.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0; // keeps bin usable for the lookahead item
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than fragmenting capacity.
    score += 0.6 * open_bins_count as f64;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; penalize placing there.
    let dev = mean_residual - bin_residual as f64;
    score += 0.25 * dev.max(0.0);

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would create severe dead space or when bin pressure is low.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is fine
        } else {
            score += 30.0 + 0.5 * open_bins_count as f64; // discourage spreading
        }
    }

    // Slight preference to fill earlier-opened bins as stream progresses.
    score += 0.05 * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill reward: bin becomes exactly full.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            score -= 80.0; // perfect 2-chain
        } else if post_residual > next_item_size {
            let gap = post - nxt;
            // Penalize leftover after chaining; small gaps are dead space.
            score -= 30.0 * (1.0 - gap / 100.0);
            if gap > 80.0 {
                score += 20.0; // leftover too large to be useful anyway
            }
        } else {
            // Next item cannot follow: post_residual becomes dead space.
            let dead = post;
            score += 0.5 * dead;
        }
    }

    // Penalize creating large unusable residuals relative to mean residual.
    let post_f = post_residual as f64;
    if post_f > mean_residual + 30.0 {
        score += 0.6 * (post_f - mean_residual);
    } else if post_f < mean_residual {
        score -= 0.3 * (mean_residual - post_f);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Discourage opening new bins early in the stream; encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bins are badly fragmented.
        score += 50.0 - 40.0 * progress;
        if mean_residual < 25.0 && open_bins_count > 0 {
            score -= 30.0; // open bins are nearly full, new bin is reasonable
        }
    }

    // Mild preference for tighter bins when many bins are open.
    score += 0.1 * (open_bins_count as f64) * (post_f / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score as fill ratio of this placement grows.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * fill * 0.35 * cap;

    // Penalize dead space that is small but hard to use (post_residual < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead (k=2): reward if the next item fits into the post residual,
    // penalize otherwise proportionally to how badly it misses.
    if next_item_size > 0 {
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 8.0;
        } else {
            let miss = next_item_size as f64 - post_residual as f64;
            score += 0.15 * miss;
        }
    }

    // Global state coupling: many open bins with high mean residual suggests
    // fragmentation; prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * mean_residual / cap;
    score -= 0.05 * pressure * (1.0 + progress);

    // Early in the stream, be slightly more willing to open fresh bins for
    // good long-term structure; late, squeeze everything in.
    score += 6.0 * (1.0 - progress);

    // New empty bin candidate: baseline relative to average placement so it
    // only wins when all existing fits are poor.
    if bin_residual == bin_capacity {
        score = 0.55 * cap + 0.10 * mean_residual - 6.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 25.0; // still prefer the last existing fitting bin
        }
        if next_item_size > 0 && (next_item_size as u32) <= bin_residual {
            score -= 3.0; // fresh bin can host next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with non-linear (quadratic) shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: late in the stream, waste is costlier
    let late = progress * progress;
    score *= 1.0 + 0.6 * late * norm_pr;

    // Reward near-perfect fits smoothly
    let fit_quality = 1.0 - (pr / cap);
    score -= 15.0 * fit_quality * fit_quality * fit_quality;

    // Penalize dead space that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let waste = (pr - next_item_size as f64).max(0.0);
        score += 0.5 * (waste / cap) * (waste / cap) * cap;
    }

    // Last-chance bin bonus: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Slight preference to keep mean residual balanced (avoid fragmentation)
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + 0.5 * progress);

    // Mild penalty for opening new bins when many are open and residual is large
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space buckets (mod-10 classes).
    let class = post_residual / 10;
    let phase = post_residual % 10;
    // Small phase => near a "clean" capacity fraction; reward it.
    score -= (10 - phase) as f64 * 0.35;
    // Penalize mid-range dead-space classes that rarely fit future items (11..39, 51..69).
    if (class >= 1 && class <= 3) || (class >= 5 && class <= 6) {
        score += 6.0;
    }
    // Very small residuals (<= 9) are effectively sealed: strong reward for producing them.
    if post_residual <= 9 {
        score -= 18.0;
    }
    // Residuals in 10..=19 are a harmonic sweet spot: fit the smallest item class exactly.
    if post_residual >= 10 && post_residual <= 19 {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 14.0 - slack * 0.4;
        // Exact two-item packing (post_residual == next_item_size) is ideal.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use this leftover: penalize proportional to leftover size.
        score += (post_residual as f64) * 0.25;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 16.0;
    }

    // New-bin candidate logic: an empty bin has high raw score via post_residual (= capacity);
    // adjust so it only wins when the fit into existing bins is poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; scaled by how many bins already exist.
        score += 8.0 + (open_bins_count as f64).sqrt() * 2.0;
        // Large items (>= half capacity) justify a fresh bin more readily.
        if item_size * 2 >= bin_capacity {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 6.0;
    }

    // Prefer bins whose residual is below the current mean (tighter bins first).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: post_residual in (0, min_item) is unusable.
    // Estimate the smallest plausible incoming item from stream progression.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let min_item = 1.0 + 9.0 * progress; // drifts from 1 toward 10 as stream advances
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 500.0; // unusable sliver: strong penalty
    }

    // Tight fits (small but usable post_residual) are good — reward them.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize leaving a gap that exactly wastes capacity for the lookahead item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 20.0; // lookahead cannot use this bin afterwards
        } else if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0; // perfect chain for next item
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with open bins and mean residual.
        score += 40.0 + 8.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // Allow new bin when it enables a clean split (item ~ half capacity).
        let half = (bin_capacity as f64) * 0.5;
        let split_bonus = 30.0 * (1.0 - ((item_size as f64) - half).abs() / half);
        score -= split_bonus;
        // If no open bin fits, opening a new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    } else {
        // Mild pressure to fill existing bins rather than spreading load.
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core dead-space penalty: squared post-residual punishes large unusable gaps.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: strongly reward exact or near match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            score -= 22.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportionally to wasted lookahead
            score += 8.0 + 0.25 * gap;
        }
    }

    // Reward tight fits relative to bin capacity (small relative slack).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 12.0 * tightness * tightness;

    // Relative-to-mean coupling: bins with residual near mean are "typical";
    // prefer filling bins whose residual deviates below mean (consolidate small leftovers).
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.08 * dev;
    } else {
        score += 0.04 * dev; // slightly reward below-mean post residual
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: neutral baseline, slightly discouraged early,
    // encouraged late when many bins are open and residual is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.9 + 20.0 * (1.0 - progress) - 0.5 * open_bins_count as f64;
        // If no open bin fits well, allow new bin late in the stream.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Mild stream-progress adaptation: be greedier (prefer tight fits) as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * tightness;

    // Penalize creating small unusable slivers (post_residual below typical min item size).
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if post_residual < 10 && post_residual > 0 {
        score += 6.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly-ish in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - next_fit / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize leaving residual that can't host the lookahead item.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with residuals below the mean (consolidate small leftovers).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate logic: only attractive when open bins are crowded or item is large.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let poor_alternatives = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 25.0 - 8.0 * crowding - 20.0 * poor_alternatives - 10.0 * big_item - 5.0 * progress;
    }

    // Mild penalty for having many open bins: encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer filling bins tightly (penalize large residuals quadratically).
    // Late: relax slightly since remaining stream is short.
    let damp = 1.0 - 0.5 * progress * progress;
    score += damp * (pr * pr) / cap;

    // Reward tight fits: low post_residual relative to item size.
    let tightness = 1.0 - pr / cap;
    score -= item_size as f64 * tightness * tightness / cap;

    // Penalize waste relative to mean residual across open bins (smooth coupling).
    if mean_residual > 0.0 {
        score += (pr - mean_residual).abs() * 0.3 * (1.0 + progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + 2.0 * progress);
    }

    // Lookahead: penalize if post_residual cannot fit next item (dead space),
    // but only when next item exists; smooth quadratic penalty.
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        let gap = next_item_size as f64 - pr;
        score += gap * gap / cap;
    }
    // Reward if post_residual exactly accommodates next item (perfect chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Slight penalty on creating many open bins early (fragmentation control).
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual (mod 10 buckets) ---
    // Residuals in "dead zone" classes (small, hard to reuse) get penalized.
    let class = post_residual % 10;
    if post_residual > 0 {
        match class {
            0 => score -= 6.0,          // clean multiple of 10: highly reusable
            1..=5 => score += 8.0,      // awkward small dead space
            6..=9 => score += 3.0,      // moderate dead space
            _ => {}
        }
    } else {
        // Perfect fill: heavily reward.
        score -= 40.0;
    }

    // Integer-division threshold classes on post_residual
    let q = post_residual / 10; // coarse decile class
    score -= (q as f64) * 0.8;  // larger residual generally more reusable

    // --- Coupling with lookahead item (k=2) ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: reward, scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 + (100.0 - slack) * 0.05;
            // Extra reward if next item then fits almost perfectly
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // Post-residual cannot host next item: penalize dead space proportionally
            let dead = post_residual as f64;
            score += dead * 0.25;
            // Harsher if the dead space is in a bad harmonic class
            if class >= 1 && class <= 5 {
                score += 5.0;
            }
        }
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early in the stream or when few bins fit.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_bias = 55.0
            - progress * 25.0
            - (fitting_bins_count as f64) * 4.0;
        // If item fills more than half of a fresh bin, opening is cheap.
        if item_size >= bin_capacity / 2 {
            score = new_bin_bias - 15.0;
        } else {
            score = new_bin_bias;
        }
        // Discourage opening when many bins already fit the item well.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    }

    // --- Last-chance bin: strongly favor using it to avoid fragmentation ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // --- Mean residual context: prefer bins below mean residual (tighter bins) ---
    score -= (mean_residual - post_residual as f64) * 0.3;

    // --- Open bins pressure: with many open bins, prefer consolidating into existing ones ---
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // --- Exact-fit harmonic bonus: item_size divides capacity nicely ---
    if bin_capacity % item_size == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize proportionally to how close post_residual is to
    // a "dead zone" (very small leftover) relative to bin capacity.
    let dead_zone = 10.0f64;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 8.0;
    }

    // Reward tight fits: the smaller the post_residual relative to item size,
    // the better the packing efficiency.
    if item_size > 0 {
        score -= (item_size as f64 / bin_capacity as f64) * 25.0;
    }

    // Open-bins pressure: penalize bins in proportion to how many bins are open,
    // favoring consolidation into fewer bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins whose residual is already below mean (they are "nearly full");
    // placing into them keeps large residuals available elsewhere.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins would leave large dead space or when few bins are open.
    if bin_residual == bin_capacity {
        // Base cost of consuming fresh capacity.
        score += 30.0;
        // If the item fits almost perfectly alone (small waste), new bin is good.
        if post_residual as f64 <= (bin_capacity as f64 - item_size as f64).min(dead_zone) {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheaper; later, reuse is favored.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 25.0;
        // If many bins are open, discourage yet another one.
        score += (open_bins_count as f64) * 2.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward
    // this placement (creates a perfect slot for the next item).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }
    // Penalize if next item would NOT fit in post_residual but would fit in
    // current residual minus a tighter choice — approximate: if next item is
    // larger than post_residual, this bin wastes potential for the lookahead.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match bonus (post_residual == next_item_size -> next item fills bin exactly)
        if gap < 1.0 {
            score -= 30.0;
        } else {
            score += gap * 0.6;
        }
        // Bonus if next item fits into post_residual (chained placement)
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            // Penalize leaving residual too small for the next item (dead space risk)
            score += 6.0;
        }
    }

    // Relative-to-mean coupling: bins with residual near mean are "typical"; extreme residuals penalized
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Penalize large dead space that nothing can use later (items >= 1, so any residual is usable,
    // but very small residuals < 10 are effectively dead if typical min size is larger)
    if post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer good fits into open bins,
    // but keep it competitive when open bins would waste lots of space.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    // Late-stream consolidation: as stream progresses, favor filling existing bins tighter
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more strongly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (item_size as f64) * 0.8;

    // Penalize dead space that cannot be filled by the lookahead item.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else if post_residual >= next_item_size {
            // Reward bins that can still host the next item.
            score -= 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize bins far from mean residual (prefer homogeneous residuals).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Late in the stream, be more conservative: penalize leaving large residuals.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post_residual as f64 * progress * 0.3;

    // When many bins are open, prefer filling existing ones over opening new.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty, reduced when open bins are crowded/fragmented.
        let crowding = (open_bins_count as f64) * 0.5;
        let fragmentation = (mean_residual - item_size as f64).abs() * 0.2;
        score += 30.0 + crowding - fragmentation;
        // Opening a bin early in the stream is cheaper.
        score -= (1.0 - progress) * 10.0;
    } else {
        // Reward using existing bins when many are open.
        score -= (open_bins_count.min(20) as f64) * 0.4;
    }

    // Slight preference for bins whose residual is just above the item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (progress * 30.0 + 5.0);

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Penalize new bin when existing bins fit
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 15.0 + 25.0 * (1.0 - progress) + 0.1 * open_bins_count as f64;
    }

    // Lookahead: keep room for next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 12.0 * (1.0 - (gap / cap).abs());
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Deviation from mean residual
    score += 0.3 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that are "nice"
    // fractions of capacity (divisible by 25 or 20), penalize awkward ones.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        if pr % 25 == 0 { score -= 18.0; }
        if pr % 20 == 0 { score -= 12.0; }
        if pr % 10 == 0 { score -= 6.0; }
        // Dead-space penalty: residuals too small for the smallest item class
        if pr < 10 { score += 40.0; }
        else if pr < 20 { score += 22.0; }
        else if pr < 30 { score += 10.0; }
    }

    // Lookahead: does the next item fit the resulting residual exactly or well?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0; // chain perfect fit
        } else if next_item_size < pr {
            let nxt = next_item_size as f64;
            let frac = nxt / cap;
            let fill_after = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - frac) - 0.15 * fill_after;
            // harmonic bonus: next item leaves a class-nice residual
            if (pr - next_item_size) % 25 == 0 { score -= 8.0; }
        } else {
            score += 15.0; // next item won't fit here at all
        }
    }

    // Tightness of current fit
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // base cost of a fresh bin; attractive only if current bins are crowded
        score = cap - 10.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 0 { score -= 50.0; }
        if next_item_size > 0 && next_item_size >= 60 { score -= 10.0; }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 15.0 * progress * (1.0 - post_residual as f64 / cap);
    }

    // Mean-residual coupling: if this bin is much emptier than average, mildly
    // prefer it (consolidate emptiness), else penalize spreading
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.08 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual <= 20 && post_residual > 0 {
        score += 8.0;
    }

    // Reward near-perfect fits (waste < 5).
    if post_residual < 5 {
        score -= 30.0;
    }

    // Reward exact fill.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead synergy: if next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // partial reward proportional to how much of the gap the next item uses
        let usage = next_item_size as f64 / post_residual as f64;
        score -= 15.0 * usage;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing bins, penalize opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.5;

    // New-bin candidate handling: empty bin gets a base penalty that grows with open bin count,
    // but a discount if this bin would otherwise leave a large dead gap.
    if bin_residual == bin_capacity {
        let base = 15.0 + open_bins_count as f64 * 2.0;
        // If no open bin fits well, opening new is fine: discount when fitting bins is small.
        let discount = if fitting_bins_count <= 1 { 10.0 } else { 0.0 };
        score += base - discount;
    }

    // Penalize bins whose residual is far above mean (fragmented bins) mildly.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.1 * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills the leftover space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the post-residual: strong reward, scaled by tightness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 - slack * 0.5;
    } else if next_item_size > post_residual {
        // Next item cannot use the leftover: penalize dead space proportionally.
        score += (post_residual as f64) * 0.35;
        // Extra penalty if next item is small and this residual is wastefully large.
        if next_item_size > 0 && (post_residual as f64) > 1.5 * (next_item_size as f64) {
            score += 15.0;
        }
    }

    // Compare against mean residual across open bins: prefer bins whose
    // post-residual is below average (tighter packing).
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize so it's only chosen when open bins are truly bad.
    if bin_residual == bin_capacity {
        score += 70.0;
        // Late in the stream, be even more reluctant to open new bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 20.0;
        }
        // But if next item is large and no open bin could chain, allow new bin.
        if next_item_size > 0 && next_item_size > item_size && post_residual == bin_capacity as u32 {
            score -= 30.0;
        }
    }

    // Reward filling bins nearly full (small absolute post residual).
    score -= (bin_capacity - post_residual) as f64 * 0.1;

    // Mild pressure when many bins are open: prefer consolidating.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post-residual quadratically (dead space).
    score += (post_residual as f64) * (post_residual as f64) * 0.01;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.5 * (next_item_size as f64);
            // bonus for exact chaining (post_residual == next_item_size)
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            // penalize leaving a gap the next item cannot use
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fuller bins: residual relative to capacity.
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= fill * 10.0;

    // Global state coupling: many open bins with low mean residual -> consolidate.
    if open_bins_count > 2 {
        let tight = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += tight * 8.0 * (open_bins_count as f64).ln();
    }

    // Time horizon: early on, be more willing to open bins (favor new bin slightly);
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 20.0 + 30.0 * progress;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host a pair
        }
    } else {
        score -= 15.0 * progress; // favor existing bins late
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: prefer small post residual (tight fits)
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, small dead space is penalized more aggressively.
    let norm_post = post / cap;
    score += norm_post * norm_post * cap * (0.4 + 0.8 * progress);

    // Reward tight fits more strongly as stream progresses (smooth coupling)
    score -= (1.0 - norm_post).powi(3) * cap * (0.15 + 0.35 * progress);

    // Penalize creating dead space smaller than the next item (unusable gap),
    // smoothly scaled by how close the gap is to the next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap_ratio = post / nxt.max(1.0);
        if post < nxt {
            score += (nxt - post) * (1.0 + progress);
        }
        // Reward leaving a gap that exactly accommodates the next item
        score -= 4.0 * (-0.5 * (gap_ratio - 1.0) * (gap_ratio - 1.0)).exp() * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && is_new_bin == 0.0 {
        score -= 25.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize opening a new bin, more so when good fitting
    // alternatives exist or many bins are already open; relax late in stream
    // when open bins are fragmented (mean residual small).
    let fragmentation = 1.0 - (mean_residual / cap).min(1.0);
    score += is_new_bin * (30.0 + 10.0 * (open_bins_count as f64).ln().max(0.0)) * (1.0 - 0.6 * progress * fragmentation);

    // Mild preference to balance residuals across bins
    if is_new_bin == 0.0 {
        score += 0.05 * (post - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by coarse
    // granularity (10) are more reusable than odd residues.
    let class = post_residual / 10; // integer division threshold class 0..=10
    score += match class {
        0 => -6.0,                 // near-perfect fill
        1 => -3.0,                 // leaves a 10..19 slot (small items fit)
        2 | 3 => 1.5,              // awkward mid slots
        4 | 5 => 0.0,              // neutral: half-capacity residues
        6 | 7 => 2.0,              // large dead space
        _ => 3.0,                  // nearly empty bin used wastefully
    };

    // Exact modulo harmony: leftover exactly matches a canonical class
    // (multiple of 10) is rewarded.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 8.0;
        } else if next_item_size <= post_residual {
            let nclass = next_item_size / 10;
            let pclass = post_residual / 10;
            if nclass == pclass {
                score -= 3.0; // same harmonic class: good chain
            } else {
                score += (post_residual - next_item_size) as f64 * 0.05;
            }
        } else {
            // next item cannot use leftover; leftover becomes dead space
            score += post_residual as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Penalize placing into a fresh empty bin when many bins are open and
    // mean residual is large (fragmentation risk).
    if bin_residual == bin_capacity {
        score += 4.0 + 0.1 * open_bins_count as f64 + mean_residual * 0.05;
    } else {
        // Prefer fuller bins: reward low residual relative to mean.
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        }
    }

    // Late in the stream, tighten packing (favor tight fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.3 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for unusable dead space: gaps below the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize moderately small gaps that are unlikely to be useful later.
    if post_residual > 0 && post_residual < 25 {
        score += (25.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item does NOT fit but would fit the current bin's residual, mildly penalize.
    if next_item_size > 0 && post_residual < next_item_size && bin_residual >= next_item_size {
        score += 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 2.0;
    } else {
        score -= (open_bins_count as f64) * 0.5;
    }

    // Mild preference for filling bins below current mean residual (tighter packing).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Early stream: be slightly more conservative (favor new bins to keep flexibility).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 500.0; // perfect 2-step chain
        } else {
            score -= 300.0 / diff; // graded reward for closeness
        }
        // Penalize creating residual too small for the next item (dead space).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // Bonus if post_residual can still fit next item comfortably.
        if post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 60.0;
        // If next item can perfectly chain into a fresh bin, soften penalty.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 40.0;
        }
    }

    // Late in stream: waste matters more; early: keep bins flexible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    // Many open bins: prefer consolidating into emptier-relative bins.
    if open_bins_count > 3 {
        score += (open_bins_count as f64).ln() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver is wasted capacity
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use remaining space; penalize proportionally
            score += 4.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets baseline penalty unless open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is penalized more early when open bins have room.
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
        score += 15.0 + 10.0 * (1.0 - progress) - 3.0 * crowding;
    } else {
        // Prefer bins with residual below the mean (consolidate fuller bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    // Mild preference for filling bins that are already quite full.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill_ratio * fill_ratio;

    // Time horizon: late in the stream, avoid opening bins (handled above) and
    // prefer maximal packing density.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling: post_residual shaped by stream progress.
    // Early stream: mildly penalize large residuals; late stream: penalize them strongly.
    let shape = 1.0 + 2.5 * progress * progress;
    score += shape * norm_pr * norm_pr * cap * 0.35;

    // Smooth reward for tight fits (small post_residual), stronger late in stream.
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (8.0 + 14.0 * progress);

    // Lookahead coupling: reward leaving residual that next item can consume.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fill_ratio = nx / pr.max(1.0);
            score -= (6.0 + 10.0 * progress) * fill_ratio * fill_ratio;
        } else {
            // post_residual too small for next item: penalize dead space smoothly.
            let dead = (nx - pr) / cap;
            score += 18.0 * dead * dead * cap.max(1.0) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 + 10.0 * progress;
    }

    // Mild penalty when many bins already open (prefer consolidating).
    score += 0.05 * open_bins_count as f64 * (0.5 + progress);

    // Nudge toward bins with residual near mean (balanced packing).
    score += 0.10 * (pr - mean_residual).abs() * (1.0 + progress);

    // New-bin candidate: penalize opening a new bin, more so early and when fits exist.
    if bin_residual == bin_capacity {
        let base = 30.0 - 10.0 * progress;
        score += if fitting_bins_count > 0 { base + 5.0 } else { base * 0.4 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes capture "usable" vs "dead" space.
    let class = post_residual % 10;
    // Residuals that are multiples of 10 (or exact 0) are most reusable.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if class == 0 {
        score -= 12.0;
    } else if class <= 2 {
        score += 8.0; // nearly dead slivers
    }

    // Fraction-of-capacity classes (harmonic fractions of C=100).
    let c = bin_capacity as f64;
    let frac = post_residual as f64 / c;
    if (frac - 0.5).abs() < 0.01 { score -= 10.0; }        // half-full residual is golden
    if (frac - 0.25).abs() < 0.01 { score -= 6.0; }
    if (frac - 0.75).abs() < 0.01 { score -= 6.0; }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // next item cannot use leftover: penalize proportionally to waste
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            // discourage opening new bin when open bins can fit; scale with stream progress
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score += 30.0 + 20.0 * progress;
        }
    }

    // Prefer filling bins that are already relatively full (small residual vs mean).
    if bin_residual < bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    // Integer-division threshold: penalize leaving residuals in awkward 3..9 band.
    if post_residual / 10 == 0 && post_residual > 0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<10) are almost unusable later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bin would leave bad dead space
    // or open bins are numerous (pressure to consolidate).
    if bin_residual == bin_capacity {
        let dead_space_penalty = if post_residual > 0 && post_residual < 10 { 30.0 } else { 0.0 };
        score += 15.0 + dead_space_penalty - 0.5 * open_bins_count as f64;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones.
    score += 0.3 * open_bins_count as f64 * (1.0 - tightness);

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 { score -= 20.0; } else { score -= 5.0; }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.2 * (mean_residual - post_residual as f64);

    // Late in stream: be more conservative, avoid creating small gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Near match: next item fits in post residual -> moderate reward scaled by tightness
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit in the leftover -> penalize dead space, worse when leftover small
    else if next_item_size > 0 {
        let dead = post_residual as f64;
        if dead > 0.0 {
            score += 8.0 * (dead / bin_capacity as f64);
        }
    }

    // Compare post residual against mean residual across open bins:
    // leaving less than average is good (compact packing), leaving more is wasteful
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    // Base penalty that shrinks late in the stream or when few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base = 25.0 + 35.0 * (1.0 - progress);
        // If the current item is large relative to capacity, opening fresh is more forgivable
        let big_item_bonus = (item_size as f64 / bin_capacity as f64) * 15.0;
        score += base - big_item_bonus;
    }

    // Mild preference for tighter fits overall (smaller post residual weighted by item size)
    score += 0.05 * (item_size as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on post_residual, stronger for small residuals.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose leftover can host the next item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance: strongly prefer using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely useful
    // (many open bins, poor fit elsewhere, or a big item early in the stream).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = (open_bins_count as f64).ln_1p();
        let mut new_bin_score = 25.0;
        // Cheaper to open early in the stream when few bins are open.
        new_bin_score -= 15.0 * (1.0 - progress) * (1.0 - open_pressure / 5.0);
        // If the item is large relative to typical residual, a fresh bin is attractive.
        new_bin_score -= 0.1 * (item_size as f64 - mean_residual).max(0.0);
        // If the item would leave a lot of dead space in any bin, opening fresh is fine.
        new_bin_score -= 0.05 * (item_size as f64);
        score += new_bin_score.max(-20.0);
    }

    // Mild reward for using bins with residual close to the item (best-fit flavor).
    score -= 0.3 * (bin_residual as f64 - item_size as f64).abs().min(40.0);

    // Prefer consolidating into bins with above-average residual (keeps tight bins free).
    if bin_residual < bin_capacity {
        score += 0.1 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = 1.0 - (post_residual as f64) / cap; // 0 = perfect fit

    // Reward tight fits, amplified smoothly by stream progress.
    score -= 40.0 * (1.0 - fit_ratio).powi(3) * (0.5 + progress);

    // Penalize large dead space non-linearly.
    let dead = post_residual as f64 / cap;
    score += 25.0 * dead * dead * (1.0 - progress);

    // Lookahead coupling: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 15.0 * (1.0 - (post_residual as f64 - nx) / cap) * (0.5 + 0.5 * progress);
        } else {
            score += 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Slight pressure toward consolidating bins as stream progresses.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Mild mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.1 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity quarters
    let quarter = bin_capacity / 4;
    let post_class: u32 = if post_residual == 0 {
        0 // perfect fit: best possible
    } else if post_residual <= quarter {
        1 // small dead space
    } else if post_residual <= 2 * quarter {
        2
    } else if post_residual <= 3 * quarter {
        3
    } else {
        4 // nearly empty bin used wastefully
    };

    // Reward exact and near-exact fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    } else if post_residual <= 20 {
        score -= 40.0;
    }

    // Penalize large classes super-linearly (dead space is quadratic waste)
    score += (post_class as f64).powi(2) * 15.0;

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // chain fit: excellent
        } else if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            if next_post <= 10 {
                score -= 150.0; // next item nearly closes the bin
            }
            score -= next_post as f64 * 0.5;
        } else {
            // next item won't fit here; penalize small post_residual (trapped space)
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Modulo harmonic penalty: residual divisible by common item sizes is reusable
    let reusable = (post_residual % 10 == 0 && post_residual > 0)
        || (post_residual % 25 == 0)
        || (post_residual % 20 == 0);
    if reusable {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: open fresh bins early or when existing fits are bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin if item is large and would leave awkward residue elsewhere
        if item_size >= bin_capacity / 2 || post_class >= 3 {
            score -= 350.0 + 100.0 * progress;
        } else {
            score += 150.0; // discourage wasteful new bins for small items
        }
    }

    // Spread load: prefer bins with residuals below the mean (tight bins)
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Mild entropy bonus: many open bins -> consolidate
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that cannot host the lookahead item
    // are unusable dead space -> penalize quadratically.
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 8.0 + gap * gap * 0.05;
    } else if next_item_size > 0 {
        // Reward perfect lookahead fit
        if post_residual == next_item_size {
            score -= 12.0;
        } else {
            score -= 2.0; // still usable for the next item
        }
    }

    // Reward very tight fits (small post residual overall)
    if post_residual <= 10 {
        score -= 6.0;
    } else if post_residual <= 25 {
        score -= 2.0;
    } else if post_residual > 60 {
        // leaving a huge hole suggests poor packing
        score += 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    score += (open_bins_count as f64) * 0.4;

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit badly
        // and open-bin count is low; otherwise make it costly.
        score += 10.0 + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // fresh bin can host a clean pair
            score -= 5.0;
        }
    }

    // Progress-based mild tightening: late in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.1;

    // Mean-residual coupling: if this bin's post-residual deviates badly
    // from the mean residual, nudge score.
    score += (post_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: prefer it only when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin when other bins can fit the item,
        // unless the fit elsewhere would be terrible (huge dead space).
        let poor_fit_elsewhere = (fitting_bins_count == 0) as f64;
        score += 40.0 - 60.0 * poor_fit_elsewhere;
        // Lookahead: if the next item would fit perfectly in a fresh bin's residual
        // after placing this item, reward opening.
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 25.0;
        }
        return score;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // 2-step lookahead: reward when next item exactly matches post-residual (chain packing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 * (1.0 - gap / 100.0).max(0.0);
        // Penalize leaving post-residual too small for next item (dead space).
        if post_residual < next_item_size {
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins below mean residual (tighter bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize large open-bin count waste lightly, encourage consolidation early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: nonlinear penalty for small post_residual.
    let pr = post_residual as f64;
    score += 0.35 * (pr * 0.06).exp() * 10.0 - 3.5;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // chain fit: next item nearly fills bin too
            if post_residual - next_item_size <= 15 {
                score -= 4.0;
            }
        } else if next_item_size > post_residual && post_residual < 15 {
            // dead space that next item can't use: penalize
            score += (15.0 - pr) * 0.6;
        }
    }

    // Penalize opening new bins when open bins have plenty of room.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0
            + 0.15 * mean_residual
            + 6.0 * (1.0 - progress);
        // Opening a bin is fine if it would create a large residual elsewhere... but new bin has max residual; discourage strongly when many bins fit.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
    } else {
        // Slight preference for bins with larger residual among candidates (best-fit vs worst-fit blend).
        score -= 0.05 * (bin_residual as f64 - pr);
    }

    // Time horizon: late in stream, be greedy about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - pr / bin_capacity as f64);

    // Mild penalty for very small unusable gaps relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear waste term: quadratic in normalized residual
    let norm_residual = pr / cap;
    score += 12.0 * norm_residual * norm_residual;

    // Reward tight fits (small post_residual) more strongly late in the stream
    let tightness = 1.0 - norm_residual;
    score -= 8.0 * tightness * tightness * (0.5 + progress);

    // Lookahead coupling: if next item fits exactly into post_residual, reward heavily
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 6.0 * (1.0 - slack * slack);
        } else {
            // post_residual that can't host next item is riskier as stream progresses
            score += 3.0 * progress * (nx - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly early, more when open bins are sparse or mean residual large
    if bin_residual == bin_capacity {
        score += 4.0 + 0.3 * open_bins_count as f64 + mean_residual * 0.05;
        // late in stream, prefer filling existing bins
        score += 6.0 * progress;
    }

    // Divergence from mean residual: bins far from mean create fragmentation
    score += 0.05 * (pr - mean_residual).abs() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions
    let post = post_residual as u32;
    let class = post % 10; // residue class mod 10
    // Reward residuals that are "clean" harmonic classes (0, 5 -> likely reusable)
    if class == 0 {
        score -= 8.0;
    } else if class == 5 {
        score -= 4.0;
    } else if class >= 8 {
        score += 2.0; // nearly-full bins are fine actually -> small penalty reduction
        score -= 1.0;
    } else if class <= 2 {
        score += 5.0; // awkward tiny dead space
    }

    // Integer division thresholds on post_residual
    if post == 0 {
        score -= 20.0; // perfect fill
    } else if post < 10 {
        score -= 6.0; // small unusable space is acceptable (dead space locked in)
    }

    // Lookahead coupling: can next_item_size fit in the post residual?
    if next_item_size > 0 {
        if post >= next_item_size {
            // exact harmonic match: next item fills remainder perfectly
            if post == next_item_size {
                score -= 15.0;
            } else {
                score -= 3.0;
                // modulo harmony: post % next_item_size small means chainable
                let m = post % next_item_size;
                if m == 0 {
                    score -= 6.0;
                } else if m <= 5 {
                    score -= 2.0;
                } else {
                    score += (m as f64) * 0.3;
                }
            }
        } else {
            // next item cannot fit here: this residual becomes dead space
            score += (next_item_size as f64) * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let tight = mean_residual / cap; // mean free fraction
        // prefer new bin early / when residuals are large and fragmented
        score = 25.0 + tight * 30.0 - pressure * 1.5;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin useful
        }
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
    }

    // Progression coupling: later in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0 * (1.0 - post as f64 / cap);

    // Prefer bins whose residual is far below mean (use up the laggards)
    score += (mean_residual - post as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are highly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Reward bins whose residual tightly matches the item (low slack ratio).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 40.0 * tightness;

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 35.0;
    }
    // Penalize leaving a gap that the next item almost fits but not quite (dead space trap).
    if next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // (the new-bin candidate has bin_residual == bin_capacity, so this doesn't apply to it,
    //  but it pushes selection toward existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual < bin_capacity {
        score -= pressure.min(50.0);
    } else {
        // New-bin candidate: penalize mildly unless current bin would leave big dead space.
        score += 30.0 + 10.0 * (mean_residual / bin_capacity as f64);
    }

    // Prefer bins below mean residual (consolidating fragmentation).
    if bin_residual < bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use remaining space: penalize proportional waste
            score += 50.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong penalty for opening a new bin instead
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > (bin_capacity as f64 * 0.5);
        score += if poor_fit { -50.0 } else { 400.0 };
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else {
        // Penalize large leftover space that is hard to reuse later.
        let dead = (post_residual as f64 / bin_capacity as f64).powf(2.0);
        score += 25.0 * dead;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
