        } else if post_residual > next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Time horizon: early in the stream, be pickier about wasted space;
    // late in the stream, just pack anywhere that fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    // Global state coupling: if many bins are open with high mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins are already roomy.
        score += 12.0 + 0.3 * mean_residual + 2.0 * open_bins_count as f64;
        // But if existing bins have poor fit potential, relax the penalty.
        if mean_residual > item_size as f64 * 1.5 {
            score -= 8.0;
        }
    } else {
        // Existing bin: slight reward when its residual is below average
        // (keeps big holes available for big items).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear fit quality: reward tight packing (small post_residual)
    let fit = 1.0 - pr / cap;
    score -= 30.0 * fit * fit * fit;

    // Penalize dead space relative to mean residual (smooth coupling)
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev.abs();

    // Lookahead coupling: penalize leaving residual that barely can't fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr) / cap;
        if gap > 0.0 {
            score += 8.0 * gap * gap * (1.0 - progress);
        } else {
            score -= 6.0 * (-gap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: mild penalty that grows with open bins and progress,
    // but relaxes when post_residual is large (poor fit elsewhere)
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 18.0 + 3.0 * (open_bins_count as f64).ln().max(0.0) + 10.0 * progress;
        score -= 0.15 * pr;
    }

    // Smooth stream-progress pressure to close bins early
    score += 4.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Harmonic class of post_residual modulo capacity quarters
    let q = post_residual % (bin_capacity / 4);
    let harmonic_penalty = match q {
        0 => -40.0,          // exact quarter alignment: reusable class
        1..=9 => 15.0,       // dead zone, nearly unusable sliver
        _ => 0.0,
    };
    score += harmonic_penalty;

    // Integer-division threshold classes on post_residual
    let class = post_residual / 10;
    score += match class {
        0 => 25.0,           // post_residual < 10: wasted bin space
        1 | 2 => -5.0,       // small but usable
        3 | 4 => -12.0,      // sweet spot for mid items
        _ => 0.0,
    };

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chains where the next item slots in cleanly
            let chain_fit = (next_item_size as f64 - post_residual as f64).abs();
            score -= 20.0 * (1.0 - chain_fit / bin_capacity as f64);
            // Harmonic class of (post_residual - next_item_size)
            let rem = post_residual - next_item_size;
            if rem % 10 == 0 { score -= 10.0; }
        } else {
            // Next item won't fit here; penalize slightly less if this bin is nearly full anyway
            if post_residual <= 15 { score -= 8.0; } else { score += 10.0; }
        }
    }

    // Last-chance bin logic
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Open a new bin only if current bins are fragmented or late in stream
        if mean_residual < 20.0 || fitting_bins_count == 0 {
            score -= 45.0;
        } else {
            score += 20.0 + 30.0 * (1.0 - progress);
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += 0.3 * (mean_residual - post_residual as f64);

    // Mild pressure from number of open bins: consolidate when many are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..10)
    // are "perfect", residuals in the small-gap band (1..=20) are dead space risk.
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual < 10 {
        score -= 30.0; // near-perfect, effectively unusable but tiny waste
    } else if post_residual <= 20 {
        score += 25.0; // dead space: too small for most items
    } else if post_residual <= 40 {
        score += 8.0;  // moderately risky gap
    }

    // Reward tight fits relative to bin capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio * fit_ratio;

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is costly when open bins exist
    // and pressure is low; encourage consolidation when many bins are open.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 15.0 + 2.0 * pressure;
        // Late in the stream, avoid spawning extra bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item cannot use this residual -> residual is likely dead space
            score += 10.0;
        }
    }

    // Open-bin pressure: mildly prefer filling existing bins over opening new ones.
    score += 0.5 * open_bins_count as f64;

    // Prefer bins whose residual deviates favorably from the mean (below-mean
    // residual means this bin is already tight; finish it off).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain: next item seals this bin
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // mild penalty growing with leftover after the lookahead item
            score += 0.25 * slack;
            // extra reward if next item leaves a still-usable residual (>= 10)
            let after_next = post_residual - next_item_size;
            if after_next >= 10 {
                score -= 8.0;
            }
        } else {
            let gap = (next_item_size - post_residual) as f64;
            // post_residual can't host the next item: penalize dead space
            score += 0.6 * gap;
        }
    }

    // Penalize creating small unusable dead space (1..9)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits relative to mean residual of open bins
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 0.15 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Early in stream: slightly prefer consolidating into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.3 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Discourage opening a new bin when decent existing fits exist
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early stream -> be frugal with open bins; late stream -> pack tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0 + 30.0 * progress;
    } else if post_residual < 10 {
        score -= 25.0 * progress;
    }

    // Penalize large dead space more as stream progresses.
    if post_residual > 0 && post_residual < 10 {
        score += (post_residual as f64) * (0.5 + progress);
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 12.0;
        } else {
            // next item won't fit here; mild penalty for wasted lookahead space
            score += 5.0 + 0.1 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 + 20.0 * progress;
    }

    // Many open bins: discourage spreading; favor filling existing bins.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Bin far below mean residual: penalize (keep big-residual bins for big items).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score -= 0.05 * (-dev);
    }

    // New empty bin candidate: default cost of opening a bin.
    if bin_residual == bin_capacity {
        let poor_fit_exists = fitting_bins_count == 0;
        if poor_fit_exists {
            score -= 10.0; // opening new bin is fine when nothing fits
        } else if post_residual == 0 {
            score -= 40.0;
        } else {
            // only open new bin if item is large relative to capacity
            score += 25.0 - 20.0 * (item_size as f64 / bin_capacity as f64);
            score += 10.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fit reward: strongly favor small post_residual (smooth quadratic coupling)
    let tight = (post / cap).powi(2);
    score -= 30.0 * (1.0 - tight);

    // Non-linear coupling of tightness with stream progress: pack tightly more aggressively late
    score -= 20.0 * (1.0 - tight) * progress * (1.0 + progress);

    // Reward if post_residual exactly accommodates the lookahead item (smooth bump)
    if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        let matchness = (-diff / 10.0).exp();
        score -= 25.0 * matchness;
    } else {
        // Last item: any residual is dead space; prefer minimal residual
        score += post * 0.5;
    }

    // Penalize opening a new bin when existing bins fit, especially early/mid stream
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 15.0 + 10.0 * (1.0 - progress);
        // discourage new bin if many open bins already fit the item
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // Mild penalty when bin residual deviates from mean residual (smooth diversity term)
    score += 0.1 * (post - mean_residual).abs();

    // Small non-linear penalty for very large open-bins count (fragmentation pressure)
    score += 0.05 * (open_bins_count as f64).powi(2).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over

    // Penalize residuals in "dead zones": too small for typical items (1..100 unknown, assume >=10-ish useful)
    // Class boundaries via integer division on post_residual.
    let class = post_residual / 10; // harmonic class width 10
    match class {
        0 => score += 60.0,          // 0..9 : nearly perfect fit, but if truly 0 it's ideal
        1..=3 => score += 12.0,      // small dead space, awkward
        4..=6 => score += 4.0,       // medium leftover, moderately reusable
        _ => score += 0.0,           // large leftover, flexible
    }
    if post_residual == 0 {
        score -= 100.0; // perfect fit: strong reward
    }

    // Lookahead coupling: reward if next item fits into post_residual (harmonic pairing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.5 * (next_item_size as f64);
        } else {
            // penalize leaving a gap that the next item just barely misses
            let miss = (next_item_size - post_residual) as f64;
            if miss < 15.0 {
                score += 20.0 - miss;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: neutral-ish score so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 0.1 * mean_residual; // baseline ~55, beaten by decent fits
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // large item arriving: fresh bin useful
        }
    }

    // Progress coupling: later in stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - frac);

    // Mean residual coupling: penalize widening dispersion from mean
    score += 0.15 * (pr - mean_residual).abs();

    // Modulo harmonic term: residues mod 10 create fine-grained tie-breaking
    score += (post_residual % 10) as f64 * 0.3;

    // Open bins pressure: many open bins -> favor filling existing ones
    score += open_bins_count as f64 * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible
    // future item are pure waste. Penalize unusable gaps quadratically.
    let min_item = 1u32;
    let dead_threshold = 10u32; // smallest observed item size historically
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 8.0;
    }

    // Reward exact / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Coupling with lookahead: if the next item fits exactly in the post-residual,
    // this placement is excellent; if the post-residual can't hold next_item but
    // could have, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // next item cannot use this gap -> dead space risk
            score += (post_residual.min(next_item_size - post_residual)) as f64 * 0.3;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (especially when this is the last fitting bin) over opening new ones.
    let pressure = open_bins_count as f64 * 2.0;
    if bin_residual < bin_capacity {
        score -= pressure * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in
    // the stream or when mean residual across open bins is very low (all bins tight).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < item_size as f64 * 0.5;
        if progress > 0.1 && !tight {
            score += 45.0 + open_bins_count as f64 * 3.0;
        } else {
            score += 10.0;
        }
    }

    // Mild penalty for leaving large-but-awkward gaps relative to mean residual.
    if post_residual as f64 > mean_residual * 1.5 && post_residual > 0 {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
