pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize (lower) scores for bins that end up nearly full.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tightness) * 30.0;

    // Penalize small-but-nonzero post residuals (dead space), especially if
    // the next item cannot fit into it.
    if post_residual > 0 {
        if next_item_size > 0 && post_residual < next_item_size {
            score += (post_residual as f64) * 1.5; // dead space unusable by lookahead
        } else {
            score += (post_residual as f64) * 0.2;
        }
    }

    // Lookahead: reward bins whose post residual can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        // Favor leaving just enough room for the next item (chain packing).
        score -= 8.0 + (slack as f64) * 0.05;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins attractive only when no
    // open bin offers a decent fit, or when open bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        // Open a new bin when existing bins are tight or item is large.
        let urgency = mean_tightness * 40.0 + (item_size as f64) * 0.3 + progress * 10.0;
        // Base cost of a fresh bin (avoid opening bins frivolously).
        score += 60.0 - urgency;
    }

    // Mild preference for bins with residuals far below the mean (consolidate
    // fragmented space into fewer bins).
    score += ((bin_residual as f64) - mean_residual) * 0.1;

    // Slight penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling: waste normalized by capacity, shaped by progress.
    let waste = post_residual as f64 / bin_capacity as f64;
    let poly = waste * waste * (1.0 + 2.0 * progress * progress);
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses (smooth coupling).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * (0.5 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits into post_residual (smooth quadratic).
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_frac = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 20.0 * fit_frac * fit_frac;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Penalize dead space that next item cannot use, worse early.
        score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a bin while mean residual is large.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.5 + 20.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - progress);
    }

    // Mild preference for filling bins below mean residual (smooth sigmoid-ish).
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev / (1.0 + dev * dev).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: buckets via integer division.
    // Class 0: post_residual == 0 (perfect fit) -> huge reward.
    // Class 1: post_residual in 1..=10 (tight) -> reward.
    // Class 2: 11..=25 -> mild reward.
    // Class 3: 26..=50 -> mild penalty (half-empty bin).
    // Class 4: >50 -> strong penalty (wasteful).
    let class = if post_residual == 0 { 0 }
        else if post_residual <= 10 { 1 }
        else if post_residual <= 25 { 2 }
        else if post_residual <= 50 { 3 }
        else { 4 };

    match class {
        0 => score -= 100.0,
        1 => score -= 12.0,
        2 => score -= 3.0,
        3 => score += 6.0,
        _ => score += 20.0,
    }

    // Harmonic coupling: next item exactly fills the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            score -= 2.0;
        } else {
            // Next item cannot use this residual: penalize leaving residual
            // that is likely dead space (residual < minimum item size 1..10).
            if post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless nothing else is viable.
    if bin_residual == bin_capacity {
        let mut base = 45.0;
        if fitting_bins_count == 0 { base = -50.0; }
        else if fitting_bins_count == 1 { base = 10.0; }
        // Later in the stream, slightly more willing to open bins if many are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        base -= progress * 5.0;
        score += base;
    }

    // Mild preference for bins below mean residual (balance loads).
    score += (post_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are unusable junk.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward if the next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; residual likely becomes dead space
            score += 0.3 * post_residual as f64;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.4 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean
    // (fill the emptier-than-average bins to balance residuals).
    score -= 0.2 * ((post_residual as f64) - mean_residual);

    // New-bin candidate handling: opening a new bin is only attractive when
    // this would be a fresh empty bin and existing fits are poor.
    if bin_residual == bin_capacity {
        // neutral baseline for a fresh bin; slight penalty so we prefer good
        // existing fits, but not so high that poor fits win.
        score += 10.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin useful if stream items are large
        }
    }

    // Mild stream progression: later in stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match: next item fits with small leftover.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 500.0 - slack * 2.0;
    }
    // Next item does NOT fit here: penalize leaving dead space the next item can't use.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0 + (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Prefer bins tighter than average residual (good fill), penalize wasteful bins.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate handling: empty bin should only win when no open bin is decent.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Penalize opening a new bin mildly; lookahead bonuses above can still override.
        score += 150.0;
    }

    // Late in stream, consolidate: tighten preference for small post_residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared waste penalty
    let waste = post_residual as f64;
    score += 1.5 * (waste / bin_capacity as f64) * waste;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual < 10 {
        score -= 100.0;
    }

    // Lookahead: reward bins whose leftover can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0 + 0.5 * next_item_size as f64;
        } else {
            // creating dead space the next item cannot use
            score += 0.3 * waste;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a bin unless existing fit is terrible
    if bin_residual == bin_capacity {
        score += 120.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    // Global state: many open bins with high mean residual -> consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.2 * open_bins_count as f64 * (1.0 - progress);
    score -= 0.4 * (mean_residual - waste);

    // Late stream: prefer filling existing bins tighter
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic coupling between post_residual and item size.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64).powi(2);
    score -= 14.0 * tightness * (1.0 + progress);

    // Penalize residual that is dead space (too small for typical items 1..100).
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powi(2);
        score += 8.0 * dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Discourage spreading across many open bins when residuals are large.
    if open_bins_count > 0 {
        score += 0.4 * (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: mild preference early, stronger preference late if residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64 - 0.5).max(0.0);
        score += 3.0 - 6.0 * progress * fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction bands.
    let post = post_residual as u32;
    let class = post / 10; // 0..=10 harmonic bands
    // Reward near-perfect fits heavily; dead-space bands penalized.
    score -= match class {
        0 => 60.0,               // perfect / near-perfect fit
        1 => 40.0,
        2 => 25.0,
        3 => 12.0,
        4 => 4.0,
        5 => 0.0,                // half-full: neutral
        6 => -2.0,
        7 => -6.0,
        8 => -12.0,
        9 => -20.0,
        _ => -30.0,              // large residual: bin was roomy anyway
    };

    // Modulo coupling: post_residual mod 10 — tiny slivers are dead space.
    let rem = post % 10;
    if rem > 0 && rem < 5 {
        score += (5 - rem) as f64 * 1.5;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 55.0;
        } else if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual: mild penalty proportional to unused potential
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only open
    // when open bins have poor fits.
    if bin_residual == bin_capacity {
        score += 45.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        // Late in stream, be more willing to open fresh bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    }

    // Prefer packing into bins with already-low residual (tighten full bins).
    score += 0.05 * (mean_residual - post_residual as f64).max(0.0);

    // Slight preference for bins whose residual is close to item size (tight fit).
    let tightness = 1.0 - (bin_residual - item_size).abs() as f64 / cap;
    score -= 10.0 * tightness.max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward (residual exactly 0 after placement)
    if post_residual == 0 {
        score -= 500.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A gap is "dead" if it is too small for typical future items.
    // Assume min item size ~1..100 unknown; use small-gap thresholds.
    if post_residual > 0 {
        // Small gaps (<= 20) are nearly dead space: heavy penalty
        if post_residual <= 20 {
            score += 120.0 * (1.0 - post_residual as f64 / 20.0);
        }
        // Medium gaps (21..50): moderate penalty, scaled by how little
        // the next item could use
        else if post_residual <= 50 {
            score += 30.0;
            if next_item_size > 0 && next_item_size > post_residual {
                score += 40.0; // next item cannot fit in this gap anyway
            }
        } else {
            // Large gaps are flexible; slight reward for keeping them big
            score -= 10.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this placement (chained packing)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 80.0; // near-perfect chain
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening
    // a new bin unless the fit is terrible
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // over spreading; add pressure proportional to open_bins_count for
    // placements that leave large residuals.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 8.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: the empty bin has bin_residual == bin_capacity.
    // Penalize opening a new bin when open bins exist and fit is decent,
    // but allow it when all open bins would create dead space.
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score += 40.0;
        if open_bins_count == 0 {
            score -= 1000.0; // must open
        } else if fitting_bins_count == 1 {
            // only alternative creates dead space -> new bin is fine
            score -= 200.0;
        } else {
            // more open fitting bins -> prefer existing bins
            score += 25.0 * (fitting_bins_count as f64);
        }
        // If next item is large and current item is large, a fresh bin
        // gives flexibility
        if next_item_size > 60 && item_size > 60 {
            score -= 30.0;
        }
    }

    // Stream progression: late in the stream, tighten packing (avoid
    // leaving scattered residuals that will never be used)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 15.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual context: if the fleet average residual is small,
    // this bin's post_residual matters more (relative dead-space term)
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel > 1.5 {
            score += 20.0 * (rel - 1.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            // Perfect match: next item exactly fills this bin.
            score -= 50.0;
        } else if post_residual >= next_item_size {
            // Next item also fits here; reward tightness of the pair.
            score -= 12.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit; penalize leaving dead space that is too small
            // to be useful (dead space below the minimum item size).
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 25.0 * (10.0 - dead);
            } else {
                score += 0.05 * (dead - 10.0);
            }
        }
    } else {
        // Last item: strongly prefer tightest fit (post_residual already does this),
        // extra bonus for filling bin completely.
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Relative-to-mean coupling: bins with residual near the mean are "typical";
    // prefer placing into bins whose residual is close to the item (tight fit),
    // penalize bins far above mean residual only if this creates waste.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    if mean_residual > 0.0 {
        let rel = (bin_residual as f64 - mean_residual) / mean_residual;
        // Slightly favor bins with above-mean residual for larger items,
        // below-mean residual for smaller items.
        score -= 4.0 * rel * (item_size as f64 / bin_capacity as f64 - 0.5);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when no
    // open bin offers a reasonable fit; make the empty-bin score sit at a
    // level that loses against good fits but wins against bad ones.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, be more reluctant to open new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // If next item is small, a fresh bin has more future utility.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space that no plausible item can fill (items are >= 1, but
    // small residuals relative to mean item size are wasteful).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here: slight penalty for large leftover.
            score += 0.1 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Compare against mean residual: bins with residual near the item size are
    // good targets; bins far above mean waste potential.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 120.0 * tightness * tightness;

    // Penalize placing into bins with residual far below mean (they are scarce
    // tight resources), unless this is a near-perfect fit.
    if (bin_residual as f64) < mean_residual && post_residual > 0 {
        score += 20.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Late in the stream, consolidate: prefer open bins over new bins.
    let new_bin_bonus = if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced late in stream or when few bins fit.
        let mut cost = 150.0 * (1.0 - progress);
        if fitting_bins_count <= 2 {
            cost += 200.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity {
            // Fresh bin keeps room for the next item too.
            cost -= 30.0;
        }
        cost
    } else {
        0.0
    };
    score += new_bin_bonus;

    // Mild preference for fewer open bins (fragmentation control).
    score += 0.5 * open_bins_count as f64;

    // Small noise-free tie-break: prefer bins with larger residual among equals.
    score -= 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual and its smooth non-linear shaping
    let x = post / cap; // in [0,1]
    let base = post;

    // Polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fits less aggressively; later, tighten strongly.
    let progress_coupling = 1.0 + 0.8 * progress * progress + 0.6 * progress * x;

    // Dead-space penalty: smooth convex penalty for small residuals,
    // scaled by how much of the bin was consumed.
    let dead_space = (1.0 - x).powi(2) * (item_size as f64 / cap);

    // Lookahead: reward leaving space close to the next item's size (smooth gaussian-like)
    let nx = next_item_size as f64;
    let match_bonus = if nx > 0.0 {
        let d = (x - nx / cap).abs();
        -6.0 * (-8.0 * d * d) * (nx / cap)
    } else {
        0.0
    };

    // Last-chance bonus: strongly favor using the only fitting bin.
    let last_chance = if fitting_bins_count == 1 { -5.0 } else { 0.0 };

    // Mild penalty for leaving residual far from mean residual (fragmentation)
    let frag = 0.3 * (x - mean_residual / cap).abs();

    // Slight preference to fill existing bins over opening new ones as stream progresses
    let open_bias = 0.05 * (open_bins_count as f64 / cap) * progress;

    let mut score = base * progress_coupling + 20.0 * dead_space + match_bonus + last_chance + frag + open_bias;

    // New-bin candidate: empty bin gets a smooth opening cost that decreases with progress
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space by
    // integer division into capacity fractions (dead-space classes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = post_residual / 10; // coarse harmonic class 0..10
    match class {
        0 => score -= 60.0,             // perfect / near-perfect fit
        1 => score -= 25.0,             // small but potentially useful
        2 => score += 8.0,              // awkward mid-range dead space
        3 => score += 14.0,
        4 => score += 18.0,
        5 => score += 10.0,             // half-capacity residual is reusable
        6 => score += 6.0,
        7 => score += 2.0,
        _ => score -= 5.0,              // large residuals remain flexible
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill;

    // Lookahead: if next item fits exactly into post_residual, strong bonus.
    if next_item_size > 0 {
        let n = next_item_size as u32;
        if n == post_residual {
            score -= 55.0;
        } else if n <= post_residual {
            score -= 20.0 * (n as f64 / (post_residual as f64 + 1.0));
        } else {
            // next item won't fit here; penalize leaving medium dead space
            if post_residual > 0 && post_residual < 10 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins
    // are nearly full (low mean residual) and many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = mean_residual / cap;
        score += 45.0 * openness + 10.0 * progress - 2.0 * open_bins_count as f64;
        if next_item_size as f64 > cap - item_size as f64 {
            score -= 15.0; // fresh bin also helps the lookahead item
        }
    } else {
        // Prefer bins whose residual is close to the mean (balance load).
        score += 0.15 * ((bin_residual as f64 - mean_residual).abs());
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item are worthless. Penalize gaps in the "dead zone"
    // (post_residual in 1..=9) harshly, with a non-linear spike.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 9.0;
    } else if post_residual == 0 {
        // Perfect fill: reward strongly.
        score -= 60.0;
    }

    // Reward leaving a residual that exactly matches the lookahead item
    // (perfect chain), mildly penalize wasting space the next item can't use.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 12.0; // dead space relative to lookahead
        } else if post_residual >= next_item_size {
            score -= 8.0; // lookahead still fits here
        }
    }

    // Reward tight fits: fraction of the bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins; when few are open, tolerate opening new ones less.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + 2.0 * progress);
    score += pressure * 4.0;

    // Mean residual coupling: penalize bins whose residual deviates from the
    // mean (keep residuals homogeneous), scaled by open-bin count.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15 * (open_bins_count.min(20) as f64 / 20.0);

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin — reward unless it creates dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual >= 10 || post_residual == 0 {
            score -= 30.0;
        }
    }

    // New-bin candidate: only attractive when current fits are poor.
    if bin_residual == bin_capacity {
        score += 25.0 + pressure;
        if next_item_size > 0 && item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 15.0; // big items: fresh bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
