pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.9 * progress * norm_pr + 0.5 * progress * progress);

    // Penalize dead space more late in the stream
    let dead = norm_pr * norm_pr * (0.6 + 0.8 * progress);

    // Reward tight fits (small post residual)
    let mut score = 100.0 * poly + 40.0 * dead;

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 12.0 + 8.0 * progress;
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins below mean residual (fill emptier bins first)
    score -= 0.3 * (mean_residual - pr);

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - progress) - 10.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize residuals that are too small to be useful (dead space), reward exact/near-exact fills.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill: always best
    } else if post_residual < 10 {
        score -= 200.0; // nearly perfect, small dead space
    } else {
        // Modulo-10 harmonic class: residuals that are multiples of 10 are "clean" slots.
        let class = post_residual % 10;
        score += (class as f64) * 0.8; // dirty residuals penalized
        // Integer-division thresholds: how many items of average size could still fit.
        let slots = post_residual / 10;
        score += slots as f64 * 2.0; // bigger residual = more reusable, so lower score preferred -> subtract instead
        score -= slots as f64 * 4.0; // net reward for reusable capacity
    }

    // Lookahead coupling: does post_residual fit the next item exactly / well?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            if next_post == 0 {
                score -= 350.0; // chain of perfect fills
            } else if next_post < 10 {
                score -= 120.0;
            } else {
                score -= 20.0;
            }
        } else {
            // Next item cannot fit here; residual risk depends on its size vs residual gap.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it's chosen only
    // when open bins have poor fits.
    if bin_residual == bin_capacity {
        score = 55.0 + frac * 40.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // Late in stream, prefer reusing open bins more aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Crowding effect: many open bins with high mean residual -> prefer consolidating.
    if open_bins_count > 2 && mean_residual > 30.0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 6.0;
