    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bins pressure: discourage scattering across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.5 * progress);

    // Prefer tighter-than-average bins.
    score += (mean_residual - bin_residual as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit in the post-residual but would fit a fresh bin,
    // penalize leaving a dead gap that blocks it.
    if next_item_size > post_residual as u32 && post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate: baseline anchor so it only wins when open bins are bad.
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits afterwards: mild reward scaled by tightness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit in the leftover: penalize dead space.
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize tiny unusable leftovers (dead space < smallest item).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Late in the stream, prefer tighter packing over opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // Slight preference for filling fuller bins when many bins are open.
    score += open_bins_count as f64 * 0.05 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual dominates base score already).
    // Penalize dead space relative to typical future item sizes.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 5.0 {
            score -= 25.0;
        } else {
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here afterwards; slight penalty proportional to wasted space.
        score += 4.0;
    }

    // Penalize leaving residuals that are likely unusable (small scraps).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward filling bins tighter than the current mean residual (consolidation).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Mild pressure against hoarding many open bins late in the stream.
    score += 0.3 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; reduced early when few bins exist.
        score = bin_capacity as f64 * 0.9 + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // If next item is large, a fresh bin preserves flexibility.
        if next_item_size >= 50 {
            score -= 15.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let ir = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): tolerate loose fits, keep bins flexible.
    // Later (progress ~ 1): strongly penalize leftover dead space.
    let pr_norm = pr / cap;
    let tightness = 1.0 - pr_norm; // 0 = empty-ish bin, 1 = very tight fit
    score += 30.0 * progress * (1.0 - tightness) * (1.0 - tightness);
    score -= 20.0 * progress * tightness * tightness;

    // Smooth reward for filling bins well relative to capacity, scaled by progress.
    let fill = ir / cap;
    score -= 15.0 * fill * fill * (0.5 + 0.5 * progress);

    // Penalize residual that cannot fit the lookahead item (smooth hinge via polynomial).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = ns - pr;
        if gap > 0.0 {
            let g = gap / cap;
            score += 25.0 * g * g * (1.0 + progress);
        } else {
            // Smooth reward when the next item exactly-ish fits the post residual.
            let g = (-gap) / cap;
            score -= 10.0 * g * (1.0 - g) * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (1.0 - pr_norm) * (1.0 - pr_norm);
    }

    // New-bin candidate: bin_residual == bin_capacity means post_residual is large;
    // penalize it smoothly so we prefer existing bins, but allow it when existing
    // bins would create big dead space (high mean residual mismatch).
    if bin_residual == bin_capacity {
        let mismatch = (mean_residual - pr).abs() / cap;
        score += 8.0 + 10.0 * (1.0 - progress) - 15.0 * mismatch * progress;
    }

    // Mild penalty for spreading across many open bins as stream progresses.
    score += 0.5 * (open_bins_count as f64).ln() * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // residue classes (multiples of common item granularities) are more
    // likely to be filled later, so reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual;

    // Modulo-based harmony: residual divisible by 10 or 25 is reusable.
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0;
        }
        if pr % 25 == 0 {
            score -= 4.0;
        }
        if pr % 50 == 0 {
            score -= 3.0;
        }
    } else {
        // Perfect fill: strongly reward.
        score -= 40.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Fraction-of-capacity coupling: small leftover fraction is good.
    let frac = pr as f64 / cap;
    score += frac * frac * 20.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead harmony: if the next item fits exactly in the post residual,
    // this is a perfect two-item chain.
    if next_item_size > 0 && next_item_size == pr {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        score -= 5.0;
    } else if next_item_size > 0 && next_item_size > pr && pr > 0 {
        // Next item can't use this bin's leftover: mild penalty scaled by waste.
        score += (pr as f64) * 0.15;
    }

    // Prefer filling already-open bins when many are open (bin-count pressure).
    if bin_residual < bin_capacity {
        score -= open_bins_count as f64 * 0.5;
    }

    // New-bin candidate handling: empty bin should only win when it is genuinely
    // better; penalize it mildly so fragmentation in open bins is used first,
    // but less when the current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if post_residual > 0 && post_residual < 10 { 0.0 } else { 8.0 };
        score += poor_fit_penalty + open_bins_count as f64 * 0.2;
    }

    // Stream progression: late in the stream, waste matters more.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += frac * 10.0 * progress;
    }

    // Mean residual coupling: placing into a bin below the mean residual
    // balances the pool of open bins.
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item are wasted.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 18.0 + 0.35 * (next_item_size - post_residual) as f64;
