    }

    // Open-bin pressure: with many open bins, favor consolidating into existing bins.
    score -= (open_bins_count as f64).sqrt() * 2.0;

    // Penalize the brand-new-bin candidate: it must only win when fits are terrible.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * item_size as f64;
        // Late in the stream, be even more reluctant to open bins.
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
    } else {
        // Reward tightness of the current fit relative to the bin.
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * tightness;
    }

    // Mild preference for bins below mean residual (tighter bins first).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
