}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 40.0 * (1.0 - progress);
        // If few bins can fit, opening a fresh bin is more attractive.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Large next item favors a fresh bin.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 15.0;
        }
        return score;
    }

    // Reward tight fits: small post_residual is good (already the base), amplify.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: penalize if the residual left cannot host the next item but could
    // have hosted something else; reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0 + 0.3 * (next_item_size as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Global state coupling: prefer filling bins when many are open (consolidation).
    score -= 0.5 * open_bins_count as f64;

    // Prefer bins with residual below the mean residual (fill the emptiest useful bins
    // less, keep large residuals flexible): penalize using high-residual bins for small items.
    if (item_size as f64) < mean_residual * 0.5 && bin_residual as f64 > mean_residual {
        score += 10.0;
    }

    // Time horizon: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

