    let x = pr / cap;
    let mut score = x * x * (1.0 + 2.0 * progress) + x * (1.0 - progress);

    // Reward tight fits more strongly as the stream progresses.
    score -= (item_size as f64 / cap) * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) / cap * (1.0 + progress);
        } else {
