    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 2.0 + progress;
    }

    // Mild pressure toward consolidating into fewer bins.
    score += (open_bins_count as f64) * 0.01 * (1.0 - progress);

    // Prefer bins with residuals near the mean (balance preservation).
    score += 0.2 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: slight penalty so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 1.5 + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quantize post_residual into
    // capacity fractions. Leftovers near multiples of common item sizes
    // (small classes) are more reusable than odd dead space.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional position of the post-residual within the bin.
    let frac = pr / c; // 0..1

    // Integer-division thresholds: post_residual classes.
    // Class 0: pr < 10  -> nearly dead space, strong penalty.
    // Class 1: 10..20   -> small but usable by small items.
    // Class 2: 20..35   -> sweet spot for medium items.
    // Class 3: >= 35    -> roomy, good.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    } else if post_residual <= 35 {
        score -= 6.0;
    } else {
        score -= 3.0;
    }

    // Harmonic coupling: if the next item fits EXACTLY into the
    // post-residual (perfect modulo match), heavily reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let rem = post_residual % next_item_size;
            if rem == 0 {
                score -= 20.0; // perfect packing chain
            } else if rem < 10 {
                score -= 5.0; // leaves only tiny dead space
            } else {
                score += rem as f64 * 0.3; // penalize awkward remainder
            }
        } else {
            // Next item cannot use this leftover: dead space likely.
            score += 6.0 + (next_item_size as f64 - pr).min(40.0) * 0.2;
        }
    }

    // Exact-fit reward: item fills bin completely.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin has large residual; make it
    // attractive only when current open bins are crowded (low mean
    // residual) or the fit here would leave a bad class of leftover.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base preference against opening new bins.
        score += 15.0;
        // Open more bins early / when open bins are full-ish.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = 1.0 - (mean_residual / c);
        score -= 20.0 * crowding * (1.0 - progress);
        // If the leftover class from placing here is bad, new bin wins.
        if post_residual < 10 && post_residual > 0 {
            score -= 18.0;
        }
    } else {
        // Reward tight fits into existing bins (best-fit core).
        score -= (c - pr) * 0.1;
        // Prefer bins whose residual is close to item size (tight packing).
        score -= (bin_residual - item_size) as f64 * 0.05;
    }

    // Modulo-class bias on item size: large items (size % 20 == 0) pack
    // best into near-empty space; small items tolerate crowded bins.
    if item_size % 20 == 0 && post_residual > 40 {
        score -= 4.0;
    }
    if item_size < 20 && post_residual < 25 && post_residual >= item_size {
        score -= 3.0;
    }

    // Mild penalty for proliferating bins when mean residual is still large.
    if open_bins_count > 3 && mean_residual > 0.4 * c && !is_new_bin {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item (min size 1) can use
    // are pure waste; gaps below typical item sizes are near-waste.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: zero waste
    } else if post_residual < 10 {
        score += 150.0; // tiny unusable sliver
    } else if post_residual < 20 {
        score += 60.0;
    }

    // Waste relative to what the lookahead could use
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            // gap cannot host the next item: dead space until later
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // gap can host next item: reward tight-but-usable fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 2.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Fit tightness: prefer bins where the item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight packing
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.8 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0
            && (bin_capacity as f64 - mean_residual) < item_size as f64 * 0.5;
        if decent_fit_exists {
            score += 250.0; // keep using existing bins
        } else {
            score += 30.0; // mild cost of opening a bin
        }
        // Late in the stream, opening fresh bins is safer for lookahead items
        let progress = step_index as f64 / total_items.max(1) as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 25.0 * progress;
        }
    }

    // Mild preference for bins already below mean residual (consolidate emptier bins)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches
    // the next item size (chained perfect fits), penalize otherwise.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits; mild reward proportional to tightness of match
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 - slack * 0.5;
        } else {
            // next item does NOT fit this bin after placement: penalize
            // proportionally to how much of the next item is stranded.
            let stranded = (next_item_size - post_residual) as f64;
            score += stranded * 1.5;
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving residual well below the mean means we crushed a bin's
    // usefulness; leaving residual above mean suggests wasted space.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize creating small unusable dead space (below typical item floor).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Early in the stream, be more willing to use existing bins; late,
    // packing tightness matters more (slight scaling of base residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.2 * progress;

    // New-bin candidate handling: an empty bin has large post_residual,
    // which is naturally penalized; add a fixed opening cost unless the
    // current bin would be badly fragmented.
    if bin_residual == bin_capacity {
        score += 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize time horizon
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward near-full fills (small post_residual relative to item)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Penalize dead space that is small and unusable
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: penalize if post_residual cannot host the next item,
    // but soften when many bins remain available for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
            score += 8.0 * (1.0 + t) * scarcity;
        } else {
            // Reward bins that can chain: post_residual fits next item snugly
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - chain_fit / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + t);
    }

    // New-bin candidate handling: empty bin should only win when no good fit exists
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 30.0 + 20.0 * t;
        // If many open bins already fit the item, opening a new bin is bad
        if fitting_bins_count > 1 {
            score += 25.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
        }
        // Late in the stream, prefer consolidating into existing bins
        score += 15.0 * t;
        // If mean residual across open bins is large, existing bins are attractive
        score += (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 20.0;
        // Exception: oversized item that barely fits anywhere gets a new bin
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 40.0;
        }
    } else {
        // Mild reward for filling existing bins when few remain open
        score -= 3.0 / (1.0 + open_bins_count as f64);
        // Prefer bins whose residual deviates favorably from mean (larger residual = more expendable space)
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Global fill pressure: as stream progresses, waste matters more
    score += 0.10 * t * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste minimization with non-linear penalty on small residuals
    let mut score = pr as f64;
    score += 40.0 * (1.0 - norm_pr) * norm_pr * (1.0 - norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on tolerate larger residuals, late prefer tight fits
    let tightness = 1.0 - norm_pr;
    score += progress * 60.0 * tightness * tightness * tightness;
    score -= (1.0 - progress) * 25.0 * norm_pr * (1.0 - norm_pr);

    // Dead-space penalty if post_residual too small for plausible future items
    let min_next = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
    let waste = (min_next - pr).max(0.0) / cap;
    score += 35.0 * waste * waste;

    // Lookahead synergy: reward residuals that exactly leave room for next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 20.0 * (1.0 - slack) * (1.0 - slack) * (1.0 - progress);
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Mean residual dispersion coupling
    let disp = (mean_residual - pr) / cap;
    score += 10.0 * disp * disp;

    // New-bin candidate: penalize unless open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64) / (1.0 + open_bins_count as f64);
        let poor_fit = (item_size as f64 / cap).powi(2);
        score += 55.0 - 40.0 * crowd - 30.0 * poor_fit * progress - 15.0 * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small" residue classes are near-perfectly packed; reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual is a multiple of a capacity fraction (tight fit)
    let frac_quarters = (post_residual * 4) % bin_capacity.max(1);
    if frac_quarters == 0 && post_residual > 0 {
        score -= 12.0; // exact quarter-harmonic alignment: perfect class
    }

    // Integer-division thresholds on post_residual (harmonic bands)
    if post_residual <= bin_capacity / 10 {
        score -= 8.0; // tiny dead space, excellent packing
    } else if post_residual <= bin_capacity / 4 {
        score -= 4.0; // small residual class
    } else if post_residual <= bin_capacity / 2 {
        score += 3.0; // medium residual class
    } else {
        score += 6.0; // large residual: bin barely used
    }

    // Modulo coupling: does post_residual match the next item size class?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 25.0; // next item exactly fills this bin
        } else if next_item_size < post_residual {
            let slack = pr - nx;
            // reward small slack after the lookahead item too
            score -= (10.0 * (1.0 - slack / cap)).max(0.0);
            // harmonic band match: next item leaves residual in a good class
            if (post_residual - next_item_size) <= bin_capacity / 10 {
                score -= 5.0;
            }
        } else {
            score += 9.0; // next item cannot use this residual at all
        }
        // modulo-10 harmonic class of next item
        if next_item_size % 10 == 0 && post_residual % 10 == 0 {
            score -= 3.0; // aligned harmonic classes
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: penalize spreading, encourage consolidation
    score += (open_bins_count as f64) * 0.4;

    // Prefer bins whose residual is below the mean (consolidate small leftovers)
    score += 2.0 * ((pr - mean_residual) / cap).clamp(-1.0, 1.0);

    // Early in stream: be more willing to open bins (favor tight fits less rigidly)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - progress);

    // New-bin candidate: neutral-ish default, only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // A fresh bin has full residual; base score is high (post_residual = capacity),
        // but the band penalty above already pushed it up. Add slight extra push
        // unless the stream is early.
        score += 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Zero residual is perfect packing
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward exact-ish fits relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Pressure from too many open bins: prefer filling existing bins
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 3.0 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item is just barely larger than post_residual, penalize creating a trap
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 20.0;
    }

    // Deviation from mean residual: prefer bins deviating positively (larger residual used up)
    score -= 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * 4.0;
        let bad_fit = if post_residual > 0 && post_residual < 10 { 30.0 } else { 0.0 };
        score = 100.0 + crowded - bad_fit;
        if open_bins_count == 0 { score = 0.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect fit bonus: residual exactly matching next item is ideal.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Lookahead coupling: penalize if next item cannot fit in post-residual,
    // reward if it fits snugly (small slack after hypothetical next placement).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack_after_next = post - next;
            score -= 12.0 * (1.0 - slack_after_next / cap);
        } else {
            // next item won't fit here: dead space unless residual is small anyway
            score += 18.0 * (post / cap);
        }
    } else {
        // Last item: prefer tightest fit overall
        score -= 20.0 * (1.0 - post / cap);
    }

    // Reward using bins that are already "wasted" (large residual relative to mean)
    let mean = if mean_residual.is_finite() { mean_residual } else { cap };
    score -= 8.0 * ((post - mean) / cap);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when a reasonable fit exists elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin is only good if item is huge or no good alternative.
        let frac = item_size as f64 / cap;
        score += 25.0 * (1.0 - frac);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    // Early in stream: keep bins open/flexible; late: pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 150.0 + 5.0 * (10 - post_residual) as f64;
    }

    // Penalize large dead space nonlinearly.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 200.0 * waste_ratio * waste_ratio;

    // Lookahead: bonus if next item fits exactly in the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            score -= 60.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mildly penalize leaving awkward gaps.
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 {
                score += 30.0;
            }
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 180.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let crowding = open_bins_count as f64 / (1.0 + step_index as f64);
    score -= 40.0 * crowding;

    // Time horizon: later in the stream, be more conservative (favor tight fits).
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.5 * progress;

    // Mean residual coupling: if open bins are generally roomy, this bin's
    // relative roominess matters less; if bins are tight, prefer the tightest.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        score += 25.0 * (rel - 1.0);
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 120.0;
        // If this bin is the only fitting option, opening is less bad.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in the stream, discourage new bins more.
        score += 100.0 * progress;
        // If many bins are open and roomy, discourage new bins.
        if mean_residual > item_size as f64 * 1.5 {
            score += 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Smooth non-linear coupling of post_residual with stream progress.
    // Early on, prefer tight fills; later, tolerate larger residuals.
    let tightness = 1.0 - progress;
    score += tightness * (pr / cap).powi(3) * cap;

    // Reward near-perfect fits smoothly.
    score -= 12.0 * (-(pr / cap) * 8.0).exp();

    // Penalize bins that leave a residual that could still fit the lookahead item
    // (wasting space the next item could use); smooth via sigmoid.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let waste = (pr - n).max(0.0) as f64;
        score += 4.0 * (waste / cap);
        // If post-residual exactly accommodates next item, reward.
        let fit_next = 1.0 / (1.0 + ((pr - n).abs() / cap * 20.0).powi(2));
        score -= 6.0 * fit_next;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr / cap);
    }

    // Mild penalty when bin residual deviates from mean residual (prefer balanced fills).
    score += 0.5 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Slight preference for using existing bins as stream progresses (avoid bin proliferation).
    score -= progress * 2.0;
    score += 0.3 * open_bins_count as f64 / (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled
    score += post_residual as f64 * 0.01;

    // Harmonic classes: classify post_residual into residue classes of the capacity
    let class = post_residual % (bin_capacity / 4).max(1);
    score += class as f64 * 0.05;

    // Penalize dead space that cannot fit the next item (lookahead coupling)
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space for the lookahead item: penalize proportionally to wasted space
            score += (next_item_size - post_residual) as f64 * 0.08;
        } else {
            // Reward bins that can also host the next item
            score -= 1.5;
        }
    } else {
        // Last item: any bin that fits is fine, prefer the fullest
        score -= 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when current
    // residuals are large (poor fits everywhere) or few bins are open
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin: its post_residual is large, but add a mild
        // opening cost that shrinks as the stream progresses
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 3.0 - 2.0 * progress;
        // If many bins are open with small residuals, discourage a new bin
        if mean_residual < item_size as f64 * 1.5 {
            score += 4.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can host anything; slight reward when lookahead is big
            score -= (next_item_size as f64) * 0.02;
        }
    }

    // Penalize leaving exactly awkward slivers (harmonic thresholds)
    let sliver = post_residual > 0 && post_residual < 10;
    if sliver {
        score += 6.0;
    }

    // Integer-division thresholds: reward near-full bins
    if post_residual <= bin_capacity / 10 {
        score -= 2.5;
    }

    // Mild preference to spread load when many bins are open
    score += (post_residual as f64 - mean_residual) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit even the smallest
    // future item (assume min size ~10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 12.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fill_ratio;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // and penalize opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 + progress) * 0.8;

    // Prefer bins whose residual is already below mean (consolidate waste).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // next item cannot use the leftover gap -> dead space penalty
            score += 6.0;
        }
    }

    // New-bin candidate: only attractive when current bin fit is poor
    // (large post_residual) or item nearly fills a fresh bin.
    if bin_residual == bin_capacity {
        // baseline for fresh bin: small, so it loses only against bad fits
        score = 5.0 + (100 - item_size.min(100)) as f64 * 0.5;
        if fitting_bins_count <= 1 {
            score -= 20.0; // nothing else fits well -> new bin is fine
        }
        if item_size >= 90 {
            score -= 25.0; // big item: fresh bin is excellent
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core archetype: aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        // Perfect chain: post_residual exactly fits the next item -> strong reward.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but reward closeness of the chain fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item does NOT fit: penalize dead space proportional to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 12.0 * gap / 100.0;
            // Extra penalty if the leftover is small enough to be nearly unusable.
            if post_residual < 10 {
                score += 20.0;
            }
        }
    } else {
        // Last item: pure best-fit behavior.
        score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward tight fits relative to current bin residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 20.0 * fit_ratio;

    // Compare against mean residual across open bins: bins tighter than average
    // should absorb the item (filling up near-full bins), loose bins penalized.
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // relative to typical residuals or no good chain exists.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 5.0;
        // Opening a bin is attractive if the item is big (leaves little residual)
        // and the next item can chain into the fresh space.
        score -= 0.25 * item_size as f64;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 10.0;
        }
        // More open bins already -> discourage spreading out.
        score += 1.5 * open_bins_count as f64;
    }

    // Mild stream-progression pressure: later in the stream, consolidate more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
