pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit)
    let mut score = pr;

    // Smooth non-linear coupling: dead-space penalty grows quadratically with residual
    score += 12.0 * norm_pr * norm_pr * cap;

    // Progress coupling: late in the stream, waste is more costly (fewer chances to fill)
    let late = progress * progress;
    score += 20.0 * norm_pr * (0.5 + late);

    // Reward leaving room for the lookahead item (smooth gaussian-like affinity)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = (pr - ns) / cap;
        let affinity = (-8.0 * diff * diff).exp();
        score -= 15.0 * affinity;
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 10.0 * (1.0 - norm_pr);
    }

    // Prefer fuller bins relative to the fleet mean (smooth)
    score += (mean_residual - pr) * 0.3;

    // Mild penalty for opening many new bins late
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * late;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Class A: post_residual <= 10 -> dead space, nearly perfect fit. Strong reward.
    if post_residual <= 10 {
        score -= 60.0;
    }
    // Class B: 10 < post_residual <= 20 -> small but usable for tiny items.
    else if post_residual <= 20 {
        score -= 25.0;
    }
    // Class C: 20 < post_residual <= 40 -> moderate leftover.
    else if post_residual <= 40 {
        score -= 10.0;
    }
    // Class D: 40 < post_residual <= 60 -> awkward zone, mild penalty.
    else if post_residual <= 60 {
        score += 8.0;
    }
    // Class E: post_residual > 60 -> wasteful placement, penalize.
    else {
        score += 20.0;
    }

    // Modulo harmonic structure on post_residual (period 25): leftovers near
    // multiples of 25 are reusable by typical mid-size items.
    let m = post_residual % 25;
    if m == 0 {
        score -= 12.0;
    } else if m <= 5 {
        score -= 6.0;
    } else if m >= 20 {
        score += 4.0;
    }

    // Lookahead coupling: if the next item fits exactly or well into post_residual,
    // reward; if it cannot fit, this leftover becomes dead space for one step.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
            if slack <= 5.0 {
                score -= 20.0; // perfect chaining
            }
        } else {
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when existing bins are all quite full
    // (mean residual low) or late in the stream with many open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_r = mean_residual;
        // Opening a new bin is good if mean residual is small (bins nearly full).
        let openness = mean_r / cap; // 0..1
        score = 55.0 + 45.0 * openness - 25.0 * progress;
        // If nothing else fits (fitting_bins_count counts only this new bin context),
        // new bin must look attractive.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight preference for keeping number of open bins bounded early on.
    score += open_bins_count as f64 * 0.15 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot fit the next item
    // (or are tiny slivers) are heavily penalized.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else {
            // reward leaving a gap exactly usable by the next item
            score -= 6.0 * (next_item_size as f64 / cap);
        }
    }

    // Tiny slivers are dead space regardless of lookahead
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few are open, allow opening new bins more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when pressure is high, reward when low
        score += 15.0 + pressure * 8.0;
        if post_residual == bin_capacity {
            score -= 5.0;
        }
    } else {
        score -= pressure.min(10.0) * 0.5;
    }

    // Coupling with mean residual: prefer bins whose residual deviates
    // favorably from the mean (filling fuller-than-average bins first).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 10.0 * dev;

    // Mild fill-ratio reward
    score -= 8.0 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item doesn't fit: penalize proportional to wasted residual
            let waste = (post_residual as f64 - next_item_size as f64).abs();
            score += waste * 0.5;
        }
    } else {
        // last item: just minimize post_residual
        score -= 10.0;
    }

    // Relative to mean residual: bins tighter than average are precious, prefer filling them
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins unattractive unless current bins are all bad fits
    if bin_residual == bin_capacity {
        let badness = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs().min(50.0)
        } else {
            0.0
        };
        // Only attractive when few fitting bins and item is large relative to capacity
        let pressure = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        score += 70.0 - pressure - badness * 0.3;
    }

    // Slight stream-phase modulation: early on, be more willing to open bins (keep options)
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - phase) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (best-fit core)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Perfect fit gets a big bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits exactly into the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // dead space relative to lookahead item
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if all open bins are too full relative to item, allow new bin
        if bin_residual < item_size {
            score -= 100.0;
        }
    }

    // Time horizon: early in stream, be more exploratory (favor new bins slightly less);
    // late in stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins
    if open_bins_count > 2 {
        score -= mean_residual * 0.05;
    }

    // Penalize leaving residuals that are awkwardly small but nonzero
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let post_norm = post / cap;

    // Base: penalize leftover space, with non-linear shaping
    let mut score = post * (1.0 + 0.5 * post_norm * post_norm);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, small leftovers matter more (save room); later, tighter fits win
    let coupling = 1.0 + progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= coupling;

    // Reward near-perfect fits smoothly (quadratic decay of waste)
    let waste = post / cap;
    score -= (1.0 - waste * waste) * item_size as f64 * 0.15;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 25.0 * progress;
