    // Lookahead: bonus if next item fits the post-residual smoothly
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_frac = next_item_size as f64 / post.max(1.0);
        score -= 10.0 * fit_frac * (1.0 - fit_frac * 0.5);
    }

    // Prefer filling existing bins when many are open
    score += open_bins_count as f64 * 0.5;

    // Penalize deviation from mean residual (keep residuals homogeneous)
    score += (post - mean_residual).abs() * 0.3;

    // New-bin candidate: penalize opening a bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress) + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

