    // "small residue classes" are more likely reusable later -> reward them.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted

    // Non-linear waste penalty: dead space quadratically bad.
    score += 0.6 * frac * frac * cap;

    // Harmonic bucketing of post_residual into residue classes mod 10:
    // residue 0 (perfect fill) heavily rewarded, residues 1..9 mildly penalized
    // by how far they are from a class boundary.
    let r = (post_residual % 10) as f64;
    let harm = match post_residual % 10 {
        0 => -14.0,
        1 | 9 => 3.0,
        2 | 8 => 2.0,
        3 | 7 => 1.0,
        4 | 6 => 0.5,
        _ => 0.0,
    };
    score += harm;

    // Integer-division thresholds: post_residual in [0..20) is prime real estate.
    if post_residual < 20 {
        score -= 8.0;
    } else if post_residual < 40 {
        score -= 3.0;
    } else if post_residual > 70 {
        score += 2.5; // large leftovers suggest we split capacity poorly
    }

