        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; small penalty scaled by overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.05 * over;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Prefer bins already below mean residual (consolidate emptiness).
    score += 0.15 * (mean_residual - post_residual as f64);

    // Slight preference for keeping the number of open bins low as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.02 * open_bins_count as f64 * (0.5 + progress);

    // New-bin candidate handling: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        let mut new_score = cap * 0.55 + 10.0;
        if fitting_bins_count == 0 {
            new_score -= 30.0; // no alternative
        } else if post_residual >= 0 && fitting_bins_count <= 2 {
            // If an existing bin would be left with tiny residue, opening new is fine.
            new_score -= 5.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            new_score -= 3.0; // fresh bin gives room for the lookahead too
        }
        score = new_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

