    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 4.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64) * (0.5 + progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
