pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits exactly or well after this placement
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item would not fit -> penalize proportionally to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (gap / 100.0);
        }
    }

    // Tight fit reward: small post residual is generally good
    let cap = bin_capacity as f64;
    score -= 8.0 * (1.0 - (post_residual as f64 / cap).powf(2.0));

    // Penalize deviating far from mean residual (keeps bin population homogeneous)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Late in stream: prefer filling existing bins over opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (open_bins_count as f64 / 10.0).min(1.0);

    // New-bin candidate: penalize unless current bin would leave big dead space
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: small post residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * (1.0 - tightness) * (1.0 - tightness);

    // Dead-space penalty: residual too small to matter for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead: bonus if the next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual; penalize proportionally
            score += 10.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Global pressure: many open bins with low mean residual -> consolidate
    if mean_residual > 0.0 {
        let ratio = bin_residual as f64 / mean_residual;
        if ratio > 1.0 {
            score -= 15.0 * (ratio - 1.0);
        } else {
            score += 15.0 * (1.0 - ratio);
        }
    }

    // Early stream: prefer packing into existing bins to keep bins dense;
    // late stream: slightly prefer filling larger residuals
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity && bin_capacity == 100 {
        let open_pressure = open_bins_count as f64;
        score += 120.0 + open_pressure * 2.0;
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with smooth non-linear shaping.
    let mut score = pr * (1.0 + 0.35 * (1.0 - progress) * (1.0 - progress));
    score += 60.0 * norm_pr * norm_pr;

    // Smooth coupling of post-residual with stream progress.
    score += 25.0 * norm_pr * progress * (1.0 - progress);

    // Penalize bins whose residual deviates from the mean residual (smooth quadratic coupling).
    let dev = pr - mean_residual;
    score += 0.02 * dev * dev;

    // Reward near-perfect fits smoothly (dead-space avoidance).
    let fit = 1.0 - norm_pr;
    score -= 40.0 * fit * fit * fit;

    // Last-chance bonus: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits the post-residual, reward; else penalize smoothly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let slack = pr - n;
        if slack >= 0.0 {
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            score += 6.0 * (-slack / cap);
        }
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Leftovers in "small" classes are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Integer-division thresholds on post_residual (harmonic classes of 100/8)
    let class = post_residual / 12; // 0..=8 harmonic class
    // Reward mid-small classes that can still host typical items; penalize extremes
    match class {
        0 => score -= 30.0,          // near-perfect fit
        1 => score -= 22.0,          // excellent
        2 => score -= 15.0,
        3 => score -= 10.0,
        4 => score -= 6.0,
        5 => score += 2.0,
        6 => score += 6.0,
        7 => score += 10.0,
        _ => score += 14.0,          // mostly-empty bin: wasteful placement
    }

    // Modulo arithmetic: residuals divisible by common item-size classes (10/20/25)
    // are more reusable. Reward divisibility.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic class match between next item and leftover
            let nclass = next_item_size / 12;
            let bonus = match nclass {
                0 => 18.0,
                1 => 14.0,
                2 => 10.0,
                3 => 7.0,
                4 => 5.0,
                _ => 3.0,
            };
            score -= bonus;
            // Exact modulo harmony: leftover exactly divisible by next item
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to overshoot class
            let over = (next_item_size - post_residual) / 12;
            score += 4.0 + over as f64 * 2.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when residuals are fragmented or stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        // open new bin if existing residuals are large (fragmented poorly) or early stream
        let penalty = 40.0 * (1.0 - progress) + 25.0 * fragmentation.max(0.0);
        score += penalty;
        // big items prefer a fresh bin to avoid creating dead space
        if item_size > 60 {
            score -= 12.0;
        }
    }

    // Mild global pressure: many open bins -> prefer tightening existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (post_residual < 10) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable dead space penalty
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling.
    let obp = open_bins_count as f64;
    score += obp * 0.8 * (post_residual as f64 / bin_capacity as f64);

    // If the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Exact match lookahead is a jackpot.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item can't use the leftover: mild penalty proportional to waste.
        score += (post_residual as f64 - next_item_size as f64).abs() * 0.3;
    }

    // New-bin candidate: prefer it only when current bin would leave a big awkward gap
    // and many bins are open (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64
            - 10.0 * (1.0 - progress)
            + 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        if fitting_bins_count == 1 {
            score += 50.0; // don't abandon the only fitting bin
        }
        if item_size >= bin_residual - item_size {
            score -= 15.0; // big items fine in fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a slight superlinear penalty.
    score += (post_residual as f64 / cap).powi(2) * 30.0;

    // Aggressive 2-step lookahead: reward when next item fits exactly in post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            // Exact match is ideal (perfect 2-chain).
            let diff = pr - nxt;
            score -= 40.0 * (1.0 - diff / cap);
            // Extra bonus if the chain fills the bin completely.
            if diff == 0.0 {
                score -= 60.0;
            }
        } else {
            // Next item cannot follow: dead space likely; penalize proportionally to overshoot.
            let overshoot = (nxt - pr) / cap;
            score += 25.0 * overshoot;
        }
        // If next item fits nowhere else but here afterwards, protect residual room.
        if nxt > pr && pr < 10.0 {
            score += 10.0;
        }
    } else {
        // Last item: just minimize waste.
        score -= 20.0 * (1.0 - post_residual as f64 / cap);
    }

    // Relative-to-mean-residual coupling: bins with residual far below mean are precious;
    // filling them is good, but only if the fit is decent.
    let rel = (bin_residual as f64 - mean_residual) / cap;
    score += 15.0 * rel * (post_residual as f64 / cap);

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if next item is huge and no open bin chains well, opening can win.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 55.0;
        }
        // Early in stream, more openness is fine.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Mild preference to consolidate when many bins are open.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that cannot fit typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: bonus if next item fits into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else if post_residual > 0 {
            score += 8.0; // next item won't chain here
        }
        // If next item is large and this bin would be nearly full, mild bonus (save space elsewhere).
        if next_item_size > item_size && post_residual < next_item_size {
            score -= 5.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Compare against mean residual: placing into an above-average-residual bin
    // helps balance and keep small bins usable; placing into a below-average bin
    // (nearly full) is also fine. Penalize the middle ground slightly.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.05 * diff;

    // Dynamic time horizon: early in the stream, be conservative with new bins;
    // later, allow more freedom.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate: only attractive when open bins would create big dead space
    // or when open-bin count is high and residuals are fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open early (bins will be useful longer) or when fragmentation is high.
        score -= 20.0 * (1.0 - progress);
        if open_bins_count > 3 && mean_residual < item_size as f64 * 1.2 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 - item_size.max(0) {
            // next item is huge; a fresh bin after placing here could help
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    } else {
        // Existing bin: small bonus for keeping bins consolidated over time.
        score -= 3.0 * progress;
    }

    // Slight penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let mut score = post;

    // Non-linear polynomial coupling: penalize mid-range waste, reward very tight fits
    let waste_poly = norm_post * norm_post * (1.0 - norm_post) * (1.0 - norm_post);
    score += 40.0 * waste_poly * (0.5 + progress);

    // Tight fit bonus (small post_residual), amplified later in the stream
    score -= 25.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.4 + 0.6 * progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 12.0 * (1.0 - ((post - next_item_size as f64) / cap).abs());
    } else if next_item_size > 0 {
        score += 8.0 * progress;
    }

    // Penalize opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * (fitting_bins_count as f64);
        score -= 5.0 * progress;
    }

    // Deviation from mean residual: prefer bins close to mean (smooth coupling)
    score += 3.0 * ((post - mean_residual) / cap).abs() * (1.0 - progress);

    // Mild consolidation pressure as stream progresses
    score += 0.05 * (open_bins_count as f64) * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class: reward post_residuals in "good" residue classes
    // (small residuals are dead space; but too-small-but-usable is fine).
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fill
    } else {
        // modulo arithmetic on post_residual: classify dead space
        let class = pr % 10;
        // residuals that are multiples of 10 are more likely reusable
        let class_bonus = match class {
            0 => 12.0,
            1..=5 => 3.0,
            6..=9 => -4.0,
            _ => 0.0,
        };
        score -= class_bonus;

        // integer-division thresholds: can next item fit in post_residual?
        if next_item_size > 0 && next_item_size <= pr {
            score -= 15.0 + (pr - next_item_size) as f64 * 0.3;
        } else if next_item_size > 0 {
            score += 6.0; // next item won't fit here -> dead space risk
        }

        // capacity-fraction coupling: penalize residuals in awkward fractions
        let frac = pr as f64 / cap;
        if frac > 0.0 && frac < 0.1 {
            score += 10.0; // tiny sliver
        } else if frac >= 0.1 && frac <= 0.35 {
            score -= 5.0; // usable chunk
        }

        // last-chance bin: strong reward to avoid opening a new bin
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 20.0;
        }

        // new-bin candidate: penalize unless current bins are nearly full
        if bin_residual == bin_capacity {
            let avg_fill = cap - mean_residual;
            score += 25.0 - 0.4 * open_bins_count as f64
                   + (avg_fill / cap) * 10.0;
            if next_item_size > 0 && next_item_size >= item_size {
                score -= 8.0; // big next item: fresh bin may help
            }
        }

        // late-stream tightening: minimize waste as stream ends
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (post_residual as f64) * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    let min_item = 1.0f64.min(bin_capacity as f64 * 0.01).max(1.0);
    if (post_residual as f64) < min_item * 10.0 && post_residual > 0 {
        score += 40.0; // tiny unusable sliver
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize large leftovers that invite fragmentation relative to capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * frac * frac;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the empty new-bin candidate gets penalized proportionally.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        score -= 15.0;
    } else if next_item_size > 0 && (post_residual as u64) > 0 && (post_residual as u64) < next_item_size as u64 {
        score += 10.0; // blocks the next item
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Early in the stream, be more willing to open bins (exploration).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    if post_residual == 0 {
        score -= 50.0; // perfect fit: heavily favored
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 20.0 * tightness * tightness;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in the post residual,
    // this placement is excellent; strongly reward it.
    if next_item_size > 0 {
        let next_fits = next_item_size <= post_residual;
        if next_fits {
            let next_post = post_residual - next_item_size;
            score -= 15.0 + 10.0 * (1.0 - next_post as f64 / bin_capacity as f64);
            if next_post == 0 {
                score -= 30.0; // chain of two perfect fits
            }
        } else {
            // Next item won't fit here: penalize leaving a large unusable gap
            // relative to the next item's size.
            let gap_waste = post_residual.min(next_item_size.saturating_sub(1)) as f64;
            score += 5.0 * gap_waste / (next_item_size.max(1) as f64);
        }
    }

    // Compare against mean residual: placing in a bin with residual far above mean
    // helps balance, slight reward; creating post_residual far below mean is bad.
    score += 0.3 * ((post_residual as f64) - mean_residual).abs().min(50.0) * 0.0
           + 0.2 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of open bins can fit the item,
    // especially early-to-mid stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    // Mild preference for bins with smaller current residual (best-fit flavor).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit gets a huge reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space that cannot fit even the smallest plausible item,
    // unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Post-residual can still host the next item: mild reward.
            score -= 8.0;
        } else {
            // Post-residual too small for next item: penalize wasted space.
            score += 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // When many bins are open, prefer consolidating into existing bins.
    if open_bins_count > 2 {
        let pressure = (open_bins_count as f64).ln();
        score -= 5.0 * pressure * tightness;
    }

    // Time horizon: early in stream, be pickier about tight fits;
    // late in stream, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Global residual state: if mean residual is high, spreading items
    // is acceptable; if low, prefer the bin closest to full.
    let mean_gap = (mean_residual - bin_residual as f64).abs();
    score += 0.15 * mean_gap;

    // New-bin candidate: only attractive when no good fit exists
    // (post_residual == capacity means fresh bin) or bin is unusable.
    if bin_residual == bin_capacity {
        // Fresh bin baseline: slightly worse than a decent existing fit,
        // better than a bad fit.
        score += 12.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // If next item is large, a fresh bin gives flexibility.
            score -= 6.0;
        }
        if open_bins_count == 0 {
            score -= 50.0; // must open first bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Normalized post-residual and its non-linear polynomial terms
    let r = pr / cap;
    let r2 = r * r;
    let r3 = r2 * r;

    // Base: prefer small post_residual (tight fit), with cubic shaping
    let mut score = pr as f64 * (1.0 + 0.6 * r + 0.4 * r2);

    // Smooth stream-progress coupling: early on, tolerate loose fits;
    // late in the stream, penalize residual space more aggressively.
    let late = progress * progress;
    score += late * 30.0 * r2;

    // Dead-space penalty: residuals too small for the smallest plausible item
    let tiny = (post_residual as f64 / 100.0).min(1.0);
    if post_residual > 0 {
        score += 12.0 * (1.0 - tiny) * (1.0 - r);
    }

    // Lookahead coupling: reward residual that can still hold the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean-residual divergence: prefer bins whose residual is below mean
    // (pack into emptier-of-space bins, keep large residuals for big items)
    let dev = (mean_residual - pr as f64) / cap;
    score += 5.0 * dev * (1.0 + progress);

    // New-bin candidate: only attractive when no open bin is a good fit
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let bad_fit = if post_residual < item_size as f64 * 0.0 { 0.0 } else { 0.0 };
        score = cap * (1.0 - 0.9 * pressure) + 0.1 * cap * progress * (1.0 - pressure);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by common
    // item-size classes (10s, 20s, 25s, 50s) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr % 50 == 0 {
        score -= 25.0;
    } else if pr % 25 == 0 {
        score -= 15.0;
    } else if pr % 20 == 0 {
        score -= 12.0;
    } else if pr % 10 == 0 {
        score -= 8.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    } else {
        // awkward residue: penalize small dead space
        if pr < 10 {
            score += 30.0;
        } else {
            score += 5.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr && pr % next_item_size == 0 {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= 6.0;
        } else {
            // next item won't fit here; mildly penalize leaving big gaps
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: only open a new bin when current bin fits
    // are poor (large awkward residuals) or item is huge relative to residuals.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: neutral residual score
        score = (bin_capacity - item_size) as f64;
        if item_size >= 60 {
            score -= 20.0; // big items like fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    // Progress-based mild preference to consolidate early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (mean_residual - post_residual as f64) * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item (>=1) can use
    // are already counted by post_residual; gaps in the "dead zone" (1..=10)
    // are pure waste — penalize them extra hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }

    // Reward near-perfect fits (post_residual <= 10 but usable by smallest items).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: opening a new bin wastes the residual of every other
    // open bin. Penalize the empty-bin candidate proportionally to how much
    // capacity is stranded, unless the current fit is terrible.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 20.0;
        // Pressure from number of open bins: more open bins => keep packing.
        score += open_bins_count as f64 * 4.0;
        // If existing bins fit well (low mean residual relative to item),
        // discourage opening a new one.
        if mean_residual < 60.0 {
            score += 25.0;
        }
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    // Prefer bins whose post-residual can still host the next item (lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // Penalize leaving a gap that is just barely too small for the next item
    // (dead space from lookahead perspective).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Mild open-bins pressure: favor consolidating into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Late in the stream, waste matters more (no future to amortize it).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post_residual (tight fit).
    score = post_residual as f64 * 1.5;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0; // exact 2-step chain: fills both items perfectly
        } else if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            // Reward proportional to how small the leftover is after the next item too.
            score -= 200.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
            if slack_after_next < 10 {
                score -= 150.0; // near-perfect chain
            }
        } else {
            // Next item cannot follow into this bin: penalize proportional to the gap.
            let gap = next_item_size - post_residual;
            score += 50.0 + gap as f64;
        }
    }

    // Relative-to-mean-residual coupling: bins with residual far below mean
    // are "tight" bins; using them is good. Penalize bins much larger than mean
    // unless the fit is tight.
    let residual_f = post_residual as f64;
    let dev = residual_f - mean_residual;
    if dev > 0.0 {
        score += 0.3 * dev; // wasteful relative to average state
    } else {
        score += 0.15 * dev; // slight reward for tighter-than-average bins
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate handling: make an empty bin unattractive unless the item
    // fits poorly everywhere (handled implicitly by last-chance logic) or the
    // item is large relative to capacity (large items prefer fresh bins).
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.7 {
            score -= 250.0 * (fill_frac - 0.7) / 0.3; // big items like fresh bins
        } else {
            score += 200.0; // small items should use existing space
        }
        // Late in the stream, opening new bins is less costly in expectation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * progress;
    }

    // Slight penalty for too many open bins: encourage consolidation early.
    if open_bins_count > 4 {
        score += 2.0 * (open_bins_count as f64 - 4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual is good).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly fill.
    // Items are 1..100, so residuals smaller than the smallest plausible item are wasted.
    if post_residual > 0 {
        let waste_factor = if post_residual < 10 { 6.0 } else { 1.0 };
        score += waste_factor * (post_residual as f64).powf(1.25) / 8.0;
    }

    // Perfect fit: massive bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to leftover.
            score += 4.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fresh canvas. Prefer it
    // only when no open bin offers a decent fit (high mean residual spread)
    // or when the open-bin count is already large relative to progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = if fitting_bins_count == 0 {
            -100.0 // must open a new bin
        } else {
            0.0
        };
        // Bias toward opening new bins early or when open bins are fragmented.
        let fragmentation = (mean_residual / bin_capacity as f64 - 0.5).abs();
        score += fit_quality
            + 55.0
            - 30.0 * fragmentation
            - 20.0 * (1.0 - progress)
            + 2.0 * open_bins_count as f64;
    } else {
        // Slight preference for filling bins that are already fairly full.
        let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fullness;

        // Prefer bins whose residual is below the mean residual (denser bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Mild penalty for scattering across many bins when many fit.
    if fitting_bins_count > 3 {
        score += 1.5 * (fitting_bins_count as f64 - 3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress (smooth, in [0,1])
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized fill ratio of the bin after placement
    let fill = (cap - post_residual as f64) / cap;
    let fill2 = fill * fill;
    let fill3 = fill2 * fill;

    // Non-linear reward for high fill: strongly favors tight fits, smooth polynomial
    score -= 30.0 * fill3;

    // Penalize small-but-annoying dead space quadratically (dead space ~ post_residual)
    let dead = post_residual as f64 / cap;
    score += 40.0 * dead * dead;

    // Smooth interaction: as stream progresses, prefer packing into existing bins more aggressively
    score -= 25.0 * progress * fill2;

    // Lookahead coupling: reward residual that can still hold the next item, penalize otherwise
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            // Smooth reward proportional to how well next item fits remaining space
            let nx_fit = nx / cap;
            score -= 15.0 * nx_fit * (1.0 - nx_fit) * (1.0 - 0.5 * progress);
        } else {
            // Penalize creating residual too small for the lookahead item
            let waste = (nx - post_residual as f64) / cap;
            score += 20.0 * waste * waste;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Mild penalty when many bins are open and this bin is still loose (encourage consolidation)
    let open_norm = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
    score += 3.0 * (1.0 - fill) * open_norm.min(10.0);

    // New-bin candidate: make it attractive only when nothing fits well
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress);
        // Late in the stream, opening a new bin is less costly
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins whose post_residual lies in
    // "useful" residue classes (multiples of common item sizes / small halves)
    // are more valuable to keep tight than bins leaving odd dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fill is king
    } else if pr <= 10 {
        score -= 12.0; // near-perfect, dead space negligible
    } else {
        // modulo-class quality of the leftover: leftover divisible by small
        // sizes (1..=10) is reusable by future items.
        let mut best_div: u32 = 0;
        for d in 1..=10u32 {
            if pr % d == 0 {
                best_div = d;
                break;
            }
        }
        if best_div > 0 {
            score -= 6.0; // leftover in a "harmonic" residue class
        } else {
            score += 8.0; // awkward leftover, penalize
        }
        // leftover exactly half or quarter capacity is structurally useful
        if pr * 2 == bin_capacity { score -= 10.0; }
        if pr * 4 == bin_capacity { score -= 6.0; }
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly reward; if next item cannot fit any other way, this bin is critical.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            score -= 4.0;
        } else {
            score += 5.0; // kills the next item's chance here
        }
    }

    // Last-chance bin: only one open bin fits the item -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when existing
    // fits are poor (large post_residual waste) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55 + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing else fits, must open
        }
    }

    // Mild preference to consolidate into bins below mean residual (tighter bins)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Medium gaps (10..20) are mildly useful; keep baseline but nudge.
    if post_residual >= 10 && post_residual < 20 {
        score -= 5.0;
    }

    // Open-bin pressure: prefer reusing bins when many are open.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item would be blocked by post_residual in a bad way, penalize.
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin unless it's early or nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.4 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) relative to bin capacity.
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64);

    // Aggressive 2-step lookahead: reward if the next item fits the post residual exactly well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            // Perfect follow-up match is heavily rewarded.
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
            // Penalize large leftover after the imagined second placement.
            score += 0.3 * gap;
        } else {
            // Next item cannot follow: penalize proportionally to the shortfall.
            score += 2.0 * (nxt - post_residual as f64);
        }
    }

    // Contextualize against mean residual across open bins.
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 20.0;
        // If next item is large and nothing fits well, new bin is less bad.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Slight preference for consolidating into fewer bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual non-linearly.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward near-full bins (small residual waste).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / bin_capacity as f64);
    }
    // If next item would be blocked by a bad fit, penalize slightly.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be more open to new bins; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage filling existing ones rather than opening new.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Penalize bins whose residual deviates from the mean (keep residuals homogeneous).
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (post_residual as f64 / bin_capacity as f64) > 0.6;
        if poor_fit {
            score -= 8.0;
        } else {
            // Opening a new bin wastes the residual of the current one on average.
            score += 5.0 + 0.5 * mean_residual;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // wasted space matters more as the stream advances.
    let waste = post / cap;
    let coupling = waste * waste * (0.5 + 2.0 * progress) * cap;
    score += coupling;

    // Cubic smooth term penalizing very small post residuals only mildly,
    // but heavily penalizing mid-range dead space via interaction with mean residual.
    let cubic = (waste - 0.5) * (waste - 0.5) * (waste - 0.5) * cap * (0.5 + progress);
    score += cubic;

    // Reward tight fits (small post_residual) more strongly early on.
    score -= (1.0 - waste) * (1.0 - waste) * 10.0 * (1.2 - progress);

    // Last chance bin: strong reward to use it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_quality = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= 5.0 + 10.0 * fit_quality;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving large unusable gaps.
        score += (next_item_size as f64 - post) / cap * 8.0 * (0.5 + progress);
    }

    // New-bin candidate: keep it attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score += 15.0 - 20.0 * fragmentation * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space into
    // capacity-fraction buckets. Small post_residual in a "useful" class
    // (near 0 or near a common item size) is rewarded.
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;

    // Class boundaries at capacity fractions: 0, 10, 20, 30, 50, 80
    if post_residual <= 10 {
        score -= 12.0; // near-perfect fill
    } else if post_residual <= 20 {
        score -= 6.0;
    } else if post_residual <= 30 {
        score -= 2.0;
    } else if post_residual <= 50 {
        score += 3.0;
    } else if post_residual <= 80 {
        score += 6.0;
    } else {
        score += 10.0; // large dead space class
    }

    // Harmonic coupling: does the next item fit into the post residual?
    // Perfect follow-on fit strongly rewarded.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how tightly the next item nests
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap_f);
        } else {
            // next item cannot use this residual: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 4.0 * (waste / cap_f);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= 50 {
        score -= 8.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin when the
    // current fit is decent, reward when residual is unusable.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score += 15.0;
        // but if all existing residuals are bad (high mean residual unused),
        // opening fresh is fine
        if mean_residual < 25.0 && fitting_bins_count > 0 {
            score += 5.0;
        }
    }

    // Modulo-harmonic bonus: residuals that are multiples of small classes
    // (10/20) are more reusable by integer-sized items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Stream progression: late in the stream, prefer tighter packs
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0 * (post / cap_f);

    // Prefer bins with below-average residual (consolidate waste)
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 1.0;
    }

    // Mild penalty per open bin to discourage proliferation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no item (min size 1..10) can use are waste.
    // Penalize small unusable gaps disproportionately.
    if post_residual > 0 {
        let unusable = if post_residual < 10 { 1.0 } else { 0.0 };
        score += unusable * (bin_capacity as f64) * 3.0;
    }

    // Reward very tight fits (post_residual near zero but not dead).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // next item cannot use the gap -> dead space penalty amplified
            score += (post_residual as f64) * 0.5;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 2.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early in stream, be slightly more willing to open fresh bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let new_bin_bonus = 12.0 * (1.0 - progress);
        // New bin attractive only if item is large and would leave a big awkward gap elsewhere.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= new_bin_bonus;
        } else {
            score += new_bin_bonus;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post residual is better (already the base), amplify it.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the NEXT item fits exactly into the post residual,
    // this bin becomes perfectly packed after two placements -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits: leftover after two placements should be small
            let second_post = post_residual - next_item_size;
            score -= 25.0 * (1.0 - (second_post as f64) / (bin_capacity as f64));
            // penalize leaving awkward small gap after two placements
            if second_post > 0 && second_post < 10 {
                score += 15.0;
            }
        } else {
            // next item does NOT fit this bin after placement: penalize proportionally
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.5 * overflow;
        }
    }

    // Compare against mean residual: bins with residual far above mean are "loose";
    // prefer packing into bins that are already tight relative to the fleet.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = residual_f / mean_residual;
        if rel < 1.0 {
            score -= 8.0 * (1.0 - rel); // tighter than average -> good
        } else {
            score += 4.0 * (rel - 1.0); // looser than average -> mild penalty
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid wasting residual capacity).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline, but discourage opening a new bin
    // when many open bins already exist and the fit is acceptable.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
        // Early in the stream, opening bins is fine (build a portfolio of bins).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    // Late in the stream, consolidate: heavily penalize opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity && progress > 0.7 {
        score += 25.0 * (progress - 0.7) / 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing (min size ~1) can later use efficiently:
    // prefer post_residual near 0 or large enough to be reusable
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in stream, be pickier (penalize loose fits); later, fill anything
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.3 * progress;

    // Global state: many open bins with high mean residual -> prefer reusing fuller bins
    if open_bins_count > 2 {
        score += 0.05 * (mean_residual - post_residual as f64);
    }

    // New empty bin candidate: penalize unless no good fit exists
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear (quadratic/cubic) shaping of post-residual.
    let mut score = pr * (1.0 + norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in the stream, dead space is more costly.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward near-perfect fits smoothly via exponential term on normalized post-residual.
    score -= 8.0 * (-norm_pr * 12.0).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize bins whose residual deviates from the mean residual (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Lookahead: reward if next item fits in post-residual, penalize otherwise (smooth).
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64) <= pr;
        let gap = ((next_item_size as f64) - pr).abs() / cap;
        if fits_next {
            score -= 5.0 * (1.0 - gap);
        } else {
            score += 4.0 * gap;
        }
    }

    // Mild penalty for spreading across many open bins early; encourages consolidation.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make empty bins moderately attractive only for large items
    // relative to residual, otherwise prefer existing bins.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        score += 6.0 * (1.0 - fill_ratio) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into modulo bands
    let post = post_residual as i64;
    let class = match post {
        0 => -60.0,                 // perfect fill
        p if p <= 5 => -40.0,       // near-perfect
        p if p <= 15 => -15.0,
        p if p <= 30 => 5.0,
        p if p <= 50 => 25.0,
        _ => 40.0,                  // large unusable gap
    };
    score += class;

    // Reward tight fits strongly: ratio of item to residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Lookahead coupling: if next item fits into post_residual, big bonus
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // harmonic bonus when next item also lands in a good class
        let npost = post_residual - next_item_size;
        if npost % 10 == 0 { score -= 10.0; }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0; // next item won't chain here
    }

    // Last-chance bin: strongly prefer using it before opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize unless current residuals are all large
    if bin_residual == bin_capacity {
        let avg_gap = mean_residual - post_residual as f64;
        score += 20.0 + 0.5 * avg_gap.max(0.0);
        if open_bins_count == 0 { score -= 100.0; }
    }

    // Progress scaling: later in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Prefer fuller bins among open set
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals below the minimum item size are unusable forever.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0;
    }

    // Non-linear dead-space penalty for small gaps that most items cannot use.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 30 {
        score += (31.0 - pr) * (31.0 - pr) * 0.05;
    }

    // Reward very tight fits (post_residual near zero but still usable).
    if post_residual > 0 && post_residual <= 10 {
        score -= 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: prefer spreading load when many bins are open,
    // but keep pressure mild so a good existing fit beats a new bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.15 * (0.5 + 0.5 * progress);

    // Mean-residual coupling: penalize bins whose residual is far below the mean
    // (they are the "cramped" ones; filling them may create dead space).
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score += diff * 0.3;
    } else {
        score += diff * 0.1;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead: if the next item could use this bin's post_residual,
    // reward leaving a compatible gap; penalize gaps the next item cannot use.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual as f64 >= n {
            score -= 5.0;
        } else if post_residual > 0 {
            score += (n - pr).min(20.0) * 0.4;
        }
    }

    // New-bin candidate: make an empty bin moderately attractive only when
    // the item leaves a large, flexible residual or existing fits are poor.
    if bin_residual == bin_capacity {
        score -= 3.0;
        if post_residual as f64 >= 40.0 {
            score -= 5.0;
        }
        // Discard new-bin option early when many bins already fit the item.
        if fitting_bins_count >= 2 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            // Perfect two-item fill: post_residual == next_item_size -> item fills bin completely later.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to tightness.
            score -= 25.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize dead space that blocks the lookahead item.
            score += 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Penalize small unusable residuals (dead space) more than linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Prefer tight fits relative to mean residual across open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly discourage opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive if no open bin fits well (large residual waste otherwise).
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * open_bins_count as f64;
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: low post_residual means little wasted space.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to ever fit a future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit elsewhere is bad
    // and the next item is large (needs a fresh bin anyway).
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size > post_residual && post_residual < item_size {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Lookahead: reward leaving post_residual that can fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Global state: when many bins are open with high mean residual, favor
    // consolidating into the fullest bins (post_residual small).
    if open_bins_count > 0 {
        let mean_r = mean_residual;
        if (post_residual as f64) < mean_r {
            score -= 5.0;
        } else {
            score += 5.0;
        }
        // Encourage reducing bin count pressure when many bins are open.
        if open_bins_count > 4 {
            score += 0.5 * (open_bins_count as f64).ln();
        }
    }

    // Prefer bins whose residual is close to item size (perfect packing).
    let diff = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += 0.3 * diff;

    // Slight preference for using bins with larger residual early (keep small
    // residual bins for small items), unless it's a tight fit.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.5 {
        score += 0.05 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1]
    let t = progress;
    let coupling = prn * prn * (0.5 + 1.5 * t) - prn * (0.3 * t + 0.2);
    score += 40.0 * coupling;

    // Penalize dead space more as stream progresses (less time to fill gaps)
    score += prn * prn * prn * 25.0 * t;

    // Reward tight fits (small post residual)
    if pr == 0.0 {
        score -= 10.0;
    }

    // Last-chance bonus: only one bin fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - prn);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 3.0 * prn;
    }

    // Slight penalty for spreading across many open bins
    score += (open_bins_count as f64).ln() * 0.5;

    // New-bin candidate: prefer opening a new bin when existing residuals are large
    if bin_residual == bin_capacity {
        score -= mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: quantize post_residual into
    // capacity-fraction buckets. Residuals in the "hard to fill" class are penalized.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i32; // 0..=7 eighth-capacity classes
    let class_penalty = match class {
        0 => -6.0,               // near-perfect fit, reward strongly
        1 => -2.5,               // small sliver, still fine
        2 => 0.0,
        3 => 1.5,
        4 => 2.5,                // half-full residual: mediocre
        5 => 1.0,
        6 => -1.0,               // large residual easy to refill
        _ => -2.0,
    };
    score += class_penalty;

    // Integer-division threshold on post_residual: residuals <= 10 are dead space.
    if post_residual <= 10 && post_residual > 0 {
        score += 12.0; // unusable sliver penalty
    }
    if post_residual == 0 {
        score -= 15.0; // perfect closure
    }

    // Lookahead coupling: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item size divides-ish into residual
            let slack = post_residual - next_item_size;
            score -= 5.0 - (slack as f64) * 0.15;
            if post_residual % next_item_size.max(1) == 0 {
                score -= 3.0; // exact harmonic subdivision
            }
        } else {
            score += 2.0; // next item cannot reuse this bin
        }
    } else {
        // last item: prefer closing bins tightly
        score -= 4.0;
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // current bin fit is poor and mean residual is small.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        let poor_fit = frac > 0.5;
        let early = progress < 0.35;
        if poor_fit && !early {
            score -= 3.0; // open a fresh bin rather than fragmenting
        } else {
            score += 8.0 + 10.0 * (1.0 - progress); // prefer reusing open bins early
        }
    }

    // Spread-aware adjustment: if this bin's residual deviates strongly from the
    // mean, gently push toward bins closer to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03;

    // Mild preference for filling already-open bins when many are open.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are worse than large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // If the next item can exactly fill the resulting residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    // If next item cannot fit in the post-residual but would fit elsewhere,
    // mildly penalize leaving a gap the lookahead can't use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 20.0 + pressure * 3.0;
        // But allow a new bin if all existing fits would create tiny dead space.
        if post_residual == bin_capacity {
            // neutral start for fresh bin
            score -= 10.0;
        }
    } else {
        // Existing bin: reward using it, scaled by how full it already is.
        let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fullness * 12.0;
        // Penalize bins whose residual deviates far from the mean (fragmentation).
        score += (bin_residual as f64 - mean_residual).abs() * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for large dead space after placement (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual > 0 && post_residual < item_size as f64 * 0.25 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            // next item fits: mild reward proportional to remaining slack after next item.
            let after_next = post_residual - next_item_size;
            score -= 20.0 - (after_next as f64) * 0.3;
        } else {
            // next item will not fit: penalize proportionally to the gap.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer bins whose residual deviates below the mean (tighter bins absorb items first).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Mild penalty for opening new bins when plenty of open bins exist.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
    }

    // Late in the stream, favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose post-residual is small but nonzero.
    if post_residual > 0 {
        score -= 8.0 / (post_residual as f64).sqrt();
    }
    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits into the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 - 0.15 * gap;
    }
    // Penalize leaving a residual that is too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 0.25 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when current
    // bins are heavily fragmented (large mean residual spread vs item size).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty so new bins are used sparingly.
        let mut new_bin_score = 45.0;
        // If mean residual across open bins is large (poorly filled bins), opening
        // a new bin is more acceptable to preserve large residuals for big items.
        new_bin_score -= (mean_residual / bin_capacity as f64) * 20.0;
        // Many open bins relative to progress: prefer consolidating, penalize more.
        new_bin_score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        // If the item is large, opening a fresh bin is more reasonable.
        new_bin_score -= (item_size as f64 / bin_capacity as f64) * 15.0;
        // Late in the stream, avoid opening bins that will be mostly empty.
        new_bin_score += progress * 10.0;
        score = new_bin_score;
    }

    // Mild preference for filling already-open bins when many are open.
    if bin_residual < bin_capacity {
        score += 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.17;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space thresholds
    // Residuals that are "usable" by typical small items (multiples of 10 classes) are less penalized.
    let pr = post_residual;
    let dead_penalty = if pr == 0 {
        -30.0 // perfect fit, strongly rewarded
    } else if pr < 10 {
        40.0 // tiny unusable sliver
    } else {
        // modulo classes on capacity fraction: residual in [10,20) vs [20,50) vs [50,100)
        let frac = pr as f64 / bin_capacity as f64;
        if pr % 10 == 0 {
            -5.0 * frac // aligned residual, mildly good
        } else if pr % 20 < 10 {
            6.0 * frac  // awkward class
        } else {
            2.0 * frac
        }
    };
    score += dead_penalty;

    // Integer-division threshold classes on post_residual
    let class = pr / 25; // 0..4 harmonic class
    score += match class {
        0 => 8.0,  // 1..24 : nearly dead
        1 => 3.0,  // 25..49
        2 => 0.0,  // 50..74
        _ => -4.0, // 75..99 : roomy bin kept usable
    };

    // Lookahead: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item chains nicely; reward proportional to tightness of that fit
            let chain_tightness = (pr - next_item_size) as f64;
            score -= 10.0 - 0.1 * chain_tightness;
        } else {
            // next item won't fit here: penalize slightly more if residual is large but misaligned
            score += 4.0;
        }
    }

    // Last-chance bin: only one open bin can fit this item -> strong reward to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open (tight packing pressure)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity - bin_residual) as f64 * (0.05 + 0.05 * progress);

    // Mild penalty for leaving residual far from mean residual (encourage consolidation)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        // neutral base; new bin beats bad fits because dead penalties already raised their scores
        score += 15.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead-space penalty: tiny gaps (< 10, minimum item size) are pure waste.
        if gap < 10.0 {
            score += 200.0 * (10.0 - gap);
        } else if gap < 25.0 {
            // Small gaps unlikely to fit future items on average.
            score += 40.0 * (25.0 - gap) / 15.0;
        }
    }

    // Reward perfect / near-perfect packing.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Tight fit bonus relative to bin capacity.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness * tightness;

    // Open bins pressure: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize if post-residual is smaller than the next item (dead space for lookahead).
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (more filled bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (bin_residual - post_residual) as f64 / bin_capacity as f64;

    // New-bin candidate: neutral baseline, only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) — already encoded above.

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: reward proportionally to how snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize large leftover dead space.
            score += 8.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Perfect chaining: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate (empty bin): penalize so we only open when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * (open_bins_count as f64);
        // But if no open bin fits (this is the only candidate), the penalty is moot.
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        // If next item is huge and post_residual here is large, new bin is attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Mild pressure against accumulating many open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer reusing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 3.0 * (mean_residual / bin_capacity as f64);
    }

    // Early in the stream: be more willing to open bins (new-bin candidate attractive).
    // Late in the stream: consolidate into existing bins.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: slightly above typical good fits.
        score += 20.0;
        if progress < 0.25 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Mild penalty for leaving residual far from common item sizes (10..80).
    if post_residual > 0 && post_residual < bin_capacity {
        let mid = 45.0;
        let dist = (post_residual as f64 - mid).abs();
        score += 0.05 * dist;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear decay favoring small leftover space
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr) * (1.0 - 0.4 * progress);

    // Smooth coupling: tight fits matter more as stream progresses
    score += 8.0 * progress * norm_pr * (1.0 - norm_pr);

    // Penalize residual that can't fit next item (dead space), smoothed
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 12.0 * gap * gap * (1.0 + progress);
    }

    // Last-chance bonus: only one fitting bin -> encourage using it
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - norm_pr);
    }

    // Mild pressure to prefer already-open bins vs opening new ones
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Reward bins whose residual deviates from mean (consolidation of slack)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline with slight progress dependence
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.2 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: dead space that cannot host
    // typical small items (<=10) is doubly bad; reward "recyclable" residues.
    let small = 10u32;
    if post_residual < small {
        score += 60.0; // unusable dead space penalty
    } else {
        // Reward residues in harmonic classes that match common item sizes
        let class = post_residual % 10;
        if class == 0 {
            score -= 25.0; // round residue: highly reusable
        } else if class <= 3 {
            score -= 10.0;
        } else if class >= 8 {
            score -= 6.0;
        }
    }

    // --- Perfect fit detection via integer division thresholds
    let fits_exact = post_residual == 0;
    if fits_exact {
        score -= 200.0;
    }

    // --- Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly prefer this bin (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit_quality = (post_residual - next_item_size) as f64;
        score -= 40.0 - 0.3 * next_fit_quality;
    } else if next_item_size > post_residual {
        // residue too small for lookahead: mild penalty scaled by how close
        score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
    }

    // --- Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate: penalize opening a new bin unless current residues
    // are all poor. Compare post_residual of new bin (capacity) against mean residual.
    if bin_residual == bin_capacity {
        // New bin is attractive only late in stream or when open bins are fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 120.0; // base reluctance to open new bin
        if open_bins_count == 0 {
            score -= 150.0; // must open first bin
        }
        if fragmentation < 15.0 {
            score -= 30.0; // existing bins are healthy, keep using them
        }
        if progress > 0.8 && open_bins_count > 4 {
            score -= 20.0; // late stream: consolidation matters
        }
        // large items (harmonic class of size > 50) deserve fresh space
        if item_size > bin_capacity / 2 {
            score -= 55.0;
        }
    }

    // --- Waste-avoidance: penalize leaving residue just below the smallest item
    if post_residual >= 1 && post_residual < 10 {
        score += 35.0;
    }

    // --- Prefer tighter bins: relative fill fraction via capacity fraction
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // --- Mean-residual divergence: bins far from mean residual are either
    // hoarders or nearly full; nudge selection toward the mean.
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual as i32) as f64 * 8.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the next item (lookahead fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + 0.1 * next_item_size as f64;
    }
    // Penalize when next item cannot fit in the resulting gap.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open;
    // encourage consolidation when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins.
        score += 25.0 + bin_pressure;
    } else {
        // Slight reward for using existing bins, more when bins are crowded.
        score -= 2.0 + 0.3 * bin_pressure.min(10.0);
        // Prefer bins tighter than average (good packing).
        score += 0.2 * ((post_residual as f64) - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (near-zero post residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // 2-step lookahead: reward post_residual that can host next_item_size,
    // penalize dead space that neither fits next item nor is tight.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // next item fits here afterwards -> bonus proportional to match quality
            score -= 30.0 * (1.0 - (post_residual as f64 - nxt) / bin_capacity as f64);
        } else {
            // post residual is dead space relative to next item
            score += 20.0 * (1.0 - (post_residual as f64) / nxt.max(1.0));
        }
    }

    // Penalize large leftover space being wasted in a bin that is much
    // emptier than average (fragmentation avoidance).
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.5 * (pr - mean_residual);
    } else {
        score -= 0.25 * (mean_residual - pr);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // or no good fit exists (large post residual otherwise).
    if bin_residual == bin_capacity {
        score -= 40.0 * (item_size as f64 / bin_capacity as f64);
        if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            score += 25.0; // new bin would leave dead space for next item
        }
    }

    // Slight preference to fill bins earlier in the stream (fewer open bins).
    score += 0.05 * open_bins_count as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio).powi(3);

    // Penalize dead space that cannot fit the average upcoming item.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 18.0 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving space the lookahead item could use later.
            score -= 6.0 * ((post_residual - next_item_size) as f64).min(30.0);
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * (1.0 - progress);
    }

    // New-bin candidate handling: penalize opening a new bin, more so early in
    // the stream and when many open bins still have room.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 40.0 + 25.0 * (1.0 - progress) + 10.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 12.0; // keep fresh bins for bigger upcoming items
        }
    } else {
        // Mildly reward using bins that are already fragmented.
        let frag = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * frag;
    }

    // Prefer balancing residuals toward the mean across open bins.
    score += 0.03 * (post_residual as f64 - mean_residual).abs();

    // Encourage consolidation when many bins are open.
    score += 0.2 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: quadratic in post-residual, mildly weighted by stream progress
    let mut score = pr * (1.0 + 0.8 * progress) + 0.6 * pr * pr / cap;

    // Reward tight fits (small post_residual relative to item)
    score -= 6.0 * fit_ratio * (1.0 - pr / cap);

    // Penalize creating dead space that no typical item could use
    let dead = if pr > 0.0 { pr / cap } else { 0.0 };
    score += 4.0 * dead * dead;

    // Smooth interaction: progress amplifies post-residual cost quadratically
    score += 2.5 * pr * progress * progress / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 5.0 + 3.0 * progress;
    }

    // Lookahead: reward if next item fits in the post-residual, penalize otherwise
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 2.0 * (next_item_size as f64 / cap);
        } else {
            score += 1.5 * (next_item_size as f64 / cap);
        }
    }

    // Mild penalty when bin deviates from mean residual (prefer balanced packing)
    score += 0.3 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // New-bin candidate: keep it competitive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 3.0 + 2.0 * fit_ratio - 0.5 * crowding.min(4.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residue modulo capacity quarters
    let quarter = bin_capacity / 4;
    let residue_class = post_residual % quarter;

    // Dead-space penalty: residuals in the smallest class (1..=9) are nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward post-residuals that are perfect harmonic classes (multiples of common item sizes)
    let harmonic_sizes: [u32; 8] = [10, 20, 25, 40, 50, 60, 75, 80];
    for h in harmonic_sizes.iter() {
        if post_residual == *h {
            score -= 18.0;
        }
    }

    // Modulo coupling: post_residual divisible by next_item_size means next item fits perfectly
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % next_item_size == 0 {
            score -= 12.0;
        }
        // penalize leaving a gap the next item barely misses
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 8 {
            score += 14.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this residual at all -> dead space
        score += (post_residual as f64) * 0.4;
    }

    // Integer-division threshold on residual fraction of capacity
    let frac_class = bin_residual / quarter; // 0..4
    match frac_class {
        0 => score += 6.0,   // nearly full bin, fine to use
        1 => score -= 4.0,   // sweet spot
        2 => score += 0.0,
        3 => score += 3.0,
        _ => {}
    }

    // Last-chance bin bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: neutral score slightly above well-fitting open bins
    if bin_residual == bin_capacity {
        score = 55.0 - (next_item_size as f64) * 0.15;
        if fitting_bins_count == 0 {
            score = 1.0; // must open new bin
        }
        // late in the stream, prefer consolidating into open bins
        if step_index as f64 / total_items.max(1) as f64 > 0.7 {
            score += 8.0;
        }
    }

    // Mild pressure toward tight packing relative to mean residual
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize unusable small gaps: post_residual < 10 (min item size per spec,
        // but be conservative for unknown distributions: treat < 15 as dead space).
        if post_residual < 15 {
            score += (15 - post_residual) as f64 * 8.0;
        }
        // Gently reward leaving a gap that the lookahead item could fill.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0;
        }
        // Penalize gaps too small for any plausible item (1..=100 range).
        if post_residual > 0 && post_residual < 1 {
            score += 100.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless post_residual is dead space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and remaining stream.
        score += 10.0 + pressure * 3.0;
    } else {
        score -= 2.0;
    }

    // Prefer bins tighter than average (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Prefer placing large items into tight bins early (big items first effect).
    score += item_size as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            score -= 50.0 - (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here: penalize dead space creation
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (mean_residual - bin_residual as f64) * 0.6;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Slight bias against opening new bins early in the stream.
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post-residual, this placement is great.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // Perfect chaining: post residual exactly matches next item.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // Dead space relative to the lookahead item: penalize proportionally.
            let waste = post_residual as f64;
            score += 0.15 * waste;
        }
    } else {
        // Last item: only exact fit matters; slight penalty for any leftover.
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize opening a new bin when open bins already fit the item,
    // unless the fit is very tight in this new bin (item ~ capacity).
    if bin_residual == bin_capacity && item_size < bin_capacity {
        // New-bin candidate: base penalty, reduced for large items that waste little.
        let waste_in_new = (bin_capacity - item_size) as f64;
        score += 10.0 + 0.3 * waste_in_new;
        // Early in the stream, opening bins is cheaper (more future use of them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 4.0 * (1.0 - progress);
    }

    // Global pressure: if mean residual across open bins is low, space is scarce;
    // favor placements that leave more room (mild counterweight to tightness reward).
    if mean_residual > 0.0 {
        score += 0.05 * (post_residual as f64 - mean_residual).abs().signum()
            * (post_residual as f64 - mean_residual).abs().min(30.0) * 0.1;
    }

    // Penalize leaving tiny unusable slivers (1..=5) that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with a non-linear (quadratic) coupling
    let mut score = pr_norm * pr_norm * 60.0 + pr_norm * 40.0;

    // Smooth stream-progress coupling: late in the stream, tighten preference for tight fits
    let late = progress * progress;
    score += pr_norm * (20.0 + 60.0 * late);

    // Reward exact-ish fits: smooth sigmoid-like bonus around tiny post_residual
    let tightness = (-pr_norm * 18.0).exp();
    score -= 25.0 * tightness * (1.0 + late);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * late;
    } else {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: penalize if post-residual barely fails to fit next item (smooth dead-space measure)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt) / cap;
        if gap >= 0.0 {
            // next item fits: reward leaving useful space, scaled by gap usefulness
            score -= 12.0 * (1.0 - (gap * gap));
        } else {
            // dead space penalty, smooth in shortfall
            score += 10.0 * (gap * gap * 4.0).min(1.0) * (1.0 + late);
        }
    }

    // Mild penalty for spreading across many open bins vs consolidating
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is below average (consolidation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev - 4.0 * dev;

    // New-bin candidate: penalize opening a new bin unless current bin is very fragmented
    if bin_residual == bin_capacity {
        score += 30.0 - 15.0 * late;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect-fill classes get strong reward.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Exact fills are ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modulo classes on post_residual relative to capacity fractions:
    // residuals that are multiples of small divisors are more reusable.
    if post_residual % 10 == 0 {
        score -= 25.0;
    }
    if post_residual % 20 == 0 {
        score -= 15.0;
    }
    if post_residual % 25 == 0 {
        score -= 15.0;
    }
    if post_residual % 50 == 0 {
        score -= 10.0;
    }

    // Dead-space penalty: tiny unusable residuals (harmonic "bad classes" 1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Mid-range awkward residuals penalized mildly, scaled by position in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual >= 10 && post_residual < 30 {
        score += 20.0 * (0.5 + progress);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if next item cannot fit anywhere else, penalize refusal.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Harmonic class match: next item leaves a "nice" residual too.
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 40.0;
            }
            score -= 20.0;
        }
        // If this is the only fitting bin and next item is large, avoid wasting.
        if fitting_bins_count == 1 && next_item_size > post_residual {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin should only win when it's genuinely
    // better (early stream, or current fit is very poor).
    if bin_residual == bin_capacity {
        score += 80.0 * (1.0 - progress);
        if post_residual < 20.0 {
            score += 50.0; // opening fresh bin for a near-full item is fine
        }
        if mean_residual > 60.0 {
            score -= 40.0; // open bins are crowded; new bin attractive
        } else {
            score += 30.0;
        }
    }

    // Prefer bins tighter than the mean (good packing density).
    score -= (mean_residual - post) * 0.3;

    // Slight preference for fewer open bins when many are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure
    }

    // Tightness reward relative to item size.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidation over new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (open_bins_count as f64 - mean_residual / 5.0).max(0.0);

    // New-bin candidate handling: only attractive when residuals are fragmented
    // or the next item pairs better with a fresh bin.
    if bin_residual == bin_capacity {
        score += 12.0; // default: prefer existing bins
        if post_residual >= next_item_size as f64 && next_item_size > 0 {
            score -= 18.0; // fresh bin can host the next item too
        }
        if mean_residual < 15.0 && open_bins_count > 2 {
            score -= 20.0; // open bins nearly dead; fresh capacity better
        }
        if progress > 0.9 {
            score += 5.0; // avoid opening bins near stream end
        }
    }

    // Lookahead: penalize leaving a gap that neither closes the bin nor fits next item.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size as f64 {
            score += 10.0; // stranded gap for the known next item
        } else {
            score -= 5.0; // next item can still use this bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward if next item exactly fits post_residual.
    if next_item_size > 0 {
        let next_fits = next_item_size as f64 <= post_residual as f64;
        if next_fits {
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            // Exact match is a jackpot: subtract heavily.
            if gap < 0.5 {
                score -= 40.0;
            } else {
                score -= 15.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: penalize wasted potential, scaled by how much it overshoots.
            let overshoot = next_item_size as f64 - post_residual as f64;
            score += 8.0 * (overshoot / bin_capacity as f64).min(1.0);
        }
    }

    // Compare residual against mean residual: bins with less residual than average
    // should be filled first (consolidate near-full bins).
    let resid_diff = mean_residual - post_residual as f64;
    score += 0.35 * resid_diff;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Penalize creating tiny dead space that nothing (min size ~1, typically >=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Late in the stream: be more conservative, prefer closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    // New-bin candidate: only attractive when current fits are poor (large post_residual
    // relative to capacity or no good lookahead match). An empty bin has score = capacity
    // baseline; add mild penalty so it's chosen only when open bins score worse.
    if bin_residual == bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Lookahead (k=2): penalize placements that strand space the next item cannot use.
    if next_item_size > 0 {
        if (next_item_size as u64) > (post_residual as u64) {
            let stranded = next_item_size as f64 - post_residual as f64;
            score += stranded * (0.5 + 0.5 * progress); // dead space matters more later in the stream
        } else {
            // Next item fits too: reward tight chaining.
            score -= next_item_size as f64 * 0.35 * (1.0 - progress);
        }
    }

    // Tightness reward: filling a large fraction of the bin's current residual is good.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // New-bin candidate handling: opening a fresh bin wastes the collective residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty grows with number of open bins (avoid bin proliferation),
        // but shrinks when no open bin fits well (post_residual of alternatives is high).
        score += 30.0 + 0.2 * open_bins_count as f64;
        // If this item would leave a very usable chunk (post_residual >= 20), opening
        // is less attractive; if it leaves almost nothing, opening is cheap.
        if post_residual >= 20 {
            score += (post_residual as f64 - 20.0) * 0.4;
        } else {
            score -= 10.0;
        }
        // If many bins can already fit the item, strongly prefer one of them.
        score += 5.0 * (fitting_bins_count as f64).min(4.0);
    } else {
        // Last-chance bonus: this is the only open bin that fits; avoid a new bin.
        if fitting_bins_count == 1 {
            score -= 18.0;
        }
        // Mild reward for using bins that are already relatively empty (consolidation).
        score -= 0.05 * (mean_residual - post_residual as f64).max(0.0);
    }

    // Slight late-stream conservatism: prefer exact-ish fits as the stream ends.
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 - progress) + prn * (0.5 + progress);

    // Penalize small dead space (poor packing), scaled by progress
    let dead_penalty = if pr > 0.0 {
        (1.0 / pr) * (10.0 + 40.0 * progress)
    } else {
        -50.0 // perfect fit
    };

    // Reward last-chance bins
    let last_chance = if fitting_bins_count == 1 { -30.0 } else { 0.0 };

    // Lookahead: reward if next item fits the post residual
    let lookahead = if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size { -15.0 } else { 5.0 }
    } else {
        0.0
    };

    // Encourage using bins with residuals above mean as stream progresses
    let mean_coupling = (pr - mean_residual) * (0.1 + 0.3 * progress);

    let mut score = pr + 20.0 * poly + dead_penalty + last_chance + lookahead + mean_coupling;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "small" classes (<=10) which are effectively dead space anyway.
    let cls = post_residual / 10; // integer division threshold classes 0..10
    score -= match cls {
        0 => 40.0,          // near-perfect fill
        1 => 20.0,
        2 => 10.0,
        3 => 4.0,
        4 => 0.0,
        5 => 2.0,
        6 => 4.0,
        _ => 0.0,
    };

    // Modulo-25 harmonic: residuals divisible by 25 pair well with common sizes.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: bonus if the next item exactly fits the post_residual,
    // or if post_residual can still hold the next item (keeps bin useful).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item can't use this residual: penalize leaving awkward gaps
            score += 6.0;
        }
    } else {
        // last item: prefer tightest fit
        score -= 5.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral baseline; opening a new bin is
    // only attractive if every existing fit would waste a lot of space.
    if bin_residual == bin_capacity {
        // Baseline score = capacity; subtract a mild incentive so a new bin
        // beats only genuinely bad fits (post_residual > ~55 waste).
        score -= 15.0;
        // Late in the stream, slightly discourage hoarding empty bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Penalize bins whose residual is far below the mean (fragmented bin).
    if (bin_residual as f64) < mean_residual * 0.5 {
        score += 5.0;
    }

    // Mild preference for tighter bins overall (best-fit core).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 60.0 * (10.0 - pr) / 10.0; // tiny gap = wasted space
    } else if pr == 0.0 {
        score -= 25.0; // perfect fit is ideal
    }

    // Penalize gaps too small for the lookahead item if the lookahead could
    // otherwise be packed tightly elsewhere.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // leaves room for the next item
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and prefer consolidating into existing residual.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + progress * 20.0);
    score += pressure * 6.0;

    // New-bin candidate handling: only attractive when current bin fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced if open bins are nearly full.
        let mut new_bin_score = 55.0 + pressure * 4.0;
        if mean_residual < item_size as f64 * 0.25 {
            new_bin_score -= 30.0; // existing bins are tight; new bin is fine
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // no alternative
        }
        score = new_bin_score + pr;
    } else {
        // Prefer bins whose residual is well-matched to the item (tight fit).
        let tightness = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
        score -= 15.0 * tightness;
    }

    // Mild preference for larger residuals when mean residual is high
    // (spreads load across bins with room).
    if bin_residual as f64 > mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Aggressive 2-step lookahead: perfect if next item exactly fills post_residual.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        let post_f = post_residual as f64;
        if (post_f - next_f).abs() < 0.5 {
            score -= 60.0; // perfect chained fit
        } else if next_f < post_f {
            let ratio = next_f / post_f;
            if ratio > 0.5 {
                score -= 25.0 * ratio; // next item consumes most of leftover
            } else {
                score += 10.0 * (1.0 - ratio); // leaves awkward sliver
            }
        } else {
            // next item cannot fit here: leftover becomes dead space
            score += 0.5 * (next_f - post_f);
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when reasonable fits exist.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64).sqrt() * 5.0;
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let tightness = (item_size as f64 / bin_residual as f64).clamp(0.0, 1.0);
    score -= 14.0 * tightness * tightness;

    // Penalize dead space that no future item (10..100) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // extra bonus for near-perfect two-item fill
            let total_fill = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 8.0 * total_fill * total_fill;
        } else {
            // next item won't fit here: slight penalty proportional to leftover
            score += 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let open_pressure = open_bins_count as f64 / (total_items as f64).max(1.0);
    score -= 6.0 * open_pressure * (bin_residual as f64 / bin_capacity as f64);

    // Global residual balance: prefer bins whose residual is below mean (fill emptier side).
    score += 1.5 * (post_residual as f64 - mean_residual) / bin_capacity as f64;

    // Time horizon: early in the stream, keep flexibility (penalize very small post_residual);
    // late in the stream, prioritize filling bins aggressively.
    let progress = step_index as f64 / total_items as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);
    score += 4.0 * (1.0 - progress) * if post_residual < 30 { 1.0 } else { 0.0 };

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score = 55.0
            - 20.0 * (fitting_bins_count == 0) as i32 as f64
            - 15.0 * poor_fit
            + 10.0 * (mean_residual / bin_capacity as f64).clamp(0.0, 1.0)
            - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual
    let poly = prn * prn * (1.0 - prn) * (1.0 - prn); // peaks near mid residuals
    score -= 30.0 * poly * (0.5 + progress);

    // Penalize very small dead space (waste) more strongly as stream progresses
    if pr > 0.0 {
        score += 12.0 * (1.0 - prn) * (1.0 - prn) * (0.3 + 0.7 * progress);
    }

    // Reward tight fits relative to mean residual
    let mr = mean_residual / cap.max(1.0);
    score -= 8.0 * prn * (1.0 - mr);

    // Lookahead: reward leaving space for the next item
    let ni = next_item_size as f64;
    if ni > 0.0 {
        let gap = pr - ni;
        if gap >= 0.0 {
            let gn = (gap / cap) * (1.0 - gap / cap);
            score -= 15.0 * gn;
        } else {
            score += 6.0 * (-gap / cap);
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mild preference for keeping bin count low early on
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: discourage opening a new bin unless residuals are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress) - 10.0 * (1.0 - mr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: partition capacity into 8ths.
    let eighth = bin_capacity as f64 / 8.0;
    let class = (post_residual as f64 / eighth).floor();

    // Penalize residuals that fall into "dead space" classes (odd mid-band classes
    // are hard to fill by typical small items).
    if class == 3.0 || class == 5.0 {
        score += 6.0;
    }

    // Reward exact-ish tight fits (post_residual in lowest class).
    if class <= 1.0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits exactly into the post residual,
    // strongly favor this bin (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0;
        } else if next_item_size < post_residual {
            let chain_post = post_residual - next_item_size;
            let chain_class = (chain_post as f64 / eighth).floor();
            if chain_class <= 1.0 {
                score -= 5.0;
            }
            score += 0.15 * chain_post as f64;
        } else {
            // next item cannot chain here; mild penalty proportional to gap
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 10.0 + 0.3 * open_bins_count as f64;
        if item_size >= bin_capacity / 2 {
            score -= 12.0; // large items deserve fresh space
        }
        if fragmentation > 2.0 * eighth {
            score -= 6.0;
        }
    }

    // Mild time decay: early in stream, be conservative with tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.0 * progress * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Mean-residual alignment: prefer bins whose residual is near the mean
    // (keeps bin population homogeneous).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: strong penalty unless existing bins are unusable/dead-space traps.
    if bin_residual == bin_capacity {
        let mut penalty = 12.0;
        // If this bin is the only fitting bin, opening a new bin is cheaper.
        if fitting_bins_count <= 1 {
            penalty = -6.0;
        }
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += 8.0 * progress;
        // Many open bins: discourage adding another.
        penalty += 0.4 * open_bins_count as f64;
        score += penalty;
        return score;
    }

    // Dead-space avoidance: tiny post_residual that the next item cannot use is waste.
    let pr = post_residual;
    if pr > 0 && next_item_size > pr {
        // Unusable gap: penalize heavily as it approaches item-size-scale waste.
        score += (pr as f64) * 1.5 + 4.0;
        // Extra penalty if this was the last chance bin (forced placement).
        if fitting_bins_count == 1 {
            score += 2.0;
        }
    } else if pr > 0 && next_item_size <= pr && next_item_size > 0 {
        // Gap is reusable by the lookahead item: reward.
        score -= 3.0 + (pr as f64 - next_item_size as f64).min(5.0);
    }

    // Perfect/near-perfect fit reward.
    if pr == 0 {
        score -= 15.0;
    } else if pr <= 5 {
        score -= 6.0;
    }

    // Prefer bins whose residual is close to the item (tight fit) over loose fits.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Mild preference for fuller bins (smaller residual before placement).
    score += (bin_capacity as f64 - bin_residual as f64) * -0.05;

    // Open-bin pressure: when few bins fit the item, favor using one rather than new bin.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Mean residual coupling: if average residual is small, conserve space aggressively.
    if mean_residual < 20.0 {
        score += (20.0 - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post residual exactly matches next item
            if post_residual == next_item_size {
                score -= 60.0;
            } else {
                // Partial reward scaled by how well the leftover after next item stays small
                let after_next = (post_residual - next_item_size) as f64;
                score -= 30.0 - after_next * 0.35;
            }
        } else {
            // Next item cannot follow into this bin: penalize proportionally to waste
            score += 12.0 + (next_item_size as f64) * 0.15;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins)
    score += (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (hard-to-fill slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Slight preference to fill nearly-full bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (bin_capacity - bin_residual) as f64 * 0.1 * (0.5 + progress);

    // Mild penalty for opening new bins when many are already open
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill is ideal.
    let residual = bin_residual as f64;
    let item = item_size as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fit quality: fraction of the bin's residual consumed by this item.
    let fill_ratio = item / residual.max(1.0);
    score -= 30.0 * fill_ratio;

    // Penalize dead space: small post-residual is good, but a post-residual
    // too small to fit the smallest future item (1) is perfect; larger
    // post-residuals risk becoming waste. Quadratic penalty on waste.
    score += 0.35 * post * post / cap;

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let next = next_item_size as f64;
        let chain_fit = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 12.0 * chain_fit;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual can't hold next item: mild penalty unless it's near zero.
        score += 0.10 * post;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With many fitting bins, favor the tightest; slight penalty to
        // spread preference toward best-fit behavior.
        score += 2.0 * (fitting_bins_count.min(8) as f64 - 1.0);
    }

    // Global state coupling: if mean residual across open bins is high,
    // there is slack in the system — prefer reusing existing bins and
    // penalize opening new ones.
    let open = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of opening a bin.
        score += 18.0;
        // Opening a bin is more attractive early in the stream and when
        // existing bins are crowded (mean residual low relative to item).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        if mean_residual < item {
            score -= 8.0;
        }
        // If no open bin can fit the item at all, opening is necessary.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Reusing an existing bin: reward grows with number of open bins
        // (consolidation pressure) and with mean residual slack.
        score -= 4.0 * open.min(20.0).ln().max(0.0);
        score -= 3.0 * (mean_residual / cap).min(1.0);
    }

    // Time-horizon modulation: late in the stream, avoid leaving awkward
    // gaps; exact or near-exact fills get extra reward.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post <= 5.0 {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr + 0.5 * norm_pr * norm_pr);

    // Reward tight fits more strongly as the stream progresses
    let tight = 1.0 - norm_pr;
    score -= tight * tight * (20.0 + 40.0 * progress);

    // Penalize dead space below the smallest plausible item (waste)
    if pr < 10.0 && pr > 0.0 {
        score += 25.0 * (1.0 - pr / 10.0) * (1.0 + progress);
    }

    // Last-chance bin bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else {
        // Mild penalty when many bins fit: keep options open
        score += (fitting_bins_count as f64).ln() * 3.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // Prefer spreading across bins when open-bin count is low relative to progress
    score -= (open_bins_count as f64) * 0.5 * (1.0 - progress);

    // New-bin candidate: neutral baseline with smooth regulation
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) - (open_bins_count as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity (multiples of 10/20/25) are more reusable for future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: zero dead space is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that lie in harmonic classes (divisible by 10 or 20):
    // they tend to accept future items exactly.
    if post_residual % 10 == 0 {
        score -= 8.0;
        if post_residual % 20 == 0 {
            score -= 4.0;
        }
    }
    // Penalize awkward residuals in the "dead zone" (1..10): nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }
    // Mid-range dead space (25..40) is the classic waste band for C=100.
    if post_residual > 25 && post_residual < 40 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this residual: mildly penalize tight fits
            // that leave nothing for the lookahead item.
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual < 10 {
            score -= 5.0; // even a near-full fill beats a fresh bin
        }
    }

    // New-bin candidate: only attractive when all open bins would leave
    // large unusable remnants or there are no open bins.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 50.0;
        } else {
            // Base cost of opening a new bin, discounted when mean residual
            // across open bins is fragmented (high mean residual = poor reuse).
            score += 18.0;
            let fragmentation = (mean_residual - pr) / cap;
            if fragmentation > 0.3 {
                score -= 10.0;
            }
            // Early in the stream, new bins are cheaper (more future items
            // to fill them); late in the stream, consolidate.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 10.0 * progress;
        }
    }

    // Mild global pressure: many open bins -> favor consolidation into
    // existing bins rather than spreading.
    score += 0.3 * open_bins_count as f64;

    // Small tie-breaker favoring tighter fits (smaller post residual)
    // with a slight non-linear sharpening.
    score += (pr * pr) / (cap * 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead space (gaps below the minimum item size are waste)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Reward very tight fits (near-perfect packing)
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Dead-space ratio term: penalize leaving a large fraction wasted relative to capacity
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Open-bin pressure: mildly discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins
        score += 25.0 + 2.0 * open_bins_count as f64;
        // If this item is a last-chance fit, strongly prefer using the existing bin
        if fitting_bins_count == 1 {
            score += 200.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance to use an existing bin: strong reward
        score -= 80.0;
    }

    // Lookahead: reward bins whose post-residual can still fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Mean residual coupling: prefer bins close to the mean residual (balanced packing)
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for fuller bins as the stream progresses
    score -= 0.1 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual,
    // penalize if next item cannot fit at all (dead space for the lookahead).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits but imperfectly: mild reward proportional to how snug.
            score -= 100.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item cannot use this residual: penalize dead space, especially small residuals.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 50.0 * (1.0 - dead / bin_capacity as f64);
            }
        }
    }

    // Compare residual to mean residual across open bins: prefer filling
    // bins that are already emptier than average less; prefer tight bins.
    score -= 2.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when existing bins can fit the item,
    // unless the current bin residual is very small (nearly full anyway).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus small discount if lookahead matches well.
        score += 40.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
        // As stream progresses, prefer reusing bins more strongly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Mild penalty for large residuals relative to capacity (waste avoidance).
    score += 0.3 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to fit a plausible future item
    if post_residual > 0 && post_residual < 10 {
