    } else if next_item_size > 0 && next_item_size > post_residual {
        // penalize leaving space the next item cannot use
        score += 5.0;
    }

    // Prefer filling fuller bins as the stream progresses (time horizon coupling)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * progress * fill;

    // Crowding: many open bins -> consolidate into existing bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // Global residual state: if mean residual is high, prefer the bin closest to it (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference for new bin only when nothing fits well
    if bin_residual == bin_capacity {
        score += 10.0 - 8.0 * fit_ratio;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

