    }

    // Last-chance bin: strong discount to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer tighter bins relative to mean residual.
    score += 3.0 * (mean_residual - post) / cap;

    // Mild new-bin penalty grows with progress to encourage consolidation.
    if bin_residual == bin_capacity {
        score += 10.0 + 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues near 0 are "dead" unless exact fit.
    let pr = post_residual as u32;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else {
        // Small residuals are dead space; penalize the smallest classes hardest.
        let class = pr % 10;
        let mut dead = 0.0;
        if pr <= 10 { dead = 45.0; }
        else if pr <= 20 { dead = 25.0; }
        else if pr <= 30 { dead = 12.0; }
        score += dead;
        // Modulo-10 coupling: residues 1..3 are nearly unusable (min item size 10 baseline)
        if class >= 1 && class <= 3 { score += 8.0; }
        if class == 0 { score -= 6.0; } // divisible class is reusable
    }

    // Tightness reward: fraction of bin consumed by this placement
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill;

    // Lookahead: does the post residual still fit the next item?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (pr as f64) >= nx {
            // bonus scaled by how much slack remains after the next item
            let after = pr as f64 - nx;
            score -= 15.0 * (1.0 - after / cap);
            if (after as u32) % 10 == 0 && after > 0.0 { score -= 5.0; }
        } else {
            score += 20.0; // this placement strands the next item
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: neutral-ish baseline, penalized when many open bins exist
    if bin_residual == bin_capacity {
        score += 40.0 + 3.0 * open_bins_count as f64;
    }

    // Phase and congestion modulation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress; // late stream: pack tighter, avoid spreading
    if (pr as f64) < mean_residual { score -= 4.0; } // better than average reuse

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (too small for the smallest plausible item) are heavily penalized.
    let dead_lo = 1u32;
    let dead_hi = 12u32;
    if post_residual >= dead_lo && post_residual <= dead_hi {
        score += 40.0 + (dead_hi - post_residual) as f64 * 3.0;
    } else if post_residual == 0 {
        // Perfect fill is maximally rewarded.
        score -= 25.0;
    } else {
        // Larger usable residuals are mildly attractive.
        score -= (post_residual as f64).sqrt() * 1.5;
    }

    // Reward tight fits: item consuming a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 20.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many fitting bins: this bin is not scarce, mild penalty against waste.
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 1.2;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward leaving that space; if it cannot fit, penalize stranding space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 6.0;
            if gap <= dead_hi as f64 {
                score += gap * 0.5;
            }
        } else if post_residual > 0 {
            score += (post_residual as f64) * 0.4;
        }
    }

    // Mean-residual coupling: placing into a bin far below mean residual
    // consolidates space; penalize bins that deviate upward from the mean.
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.3;

    // New-bin candidate: only attractive when no open bin fits well
    // (tight fill ratio) and bin count pressure is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fill_ratio > 0.6 && fitting_bins_count <= 1 {
            score -= 30.0 + progress * 10.0;
        } else {
            score += 12.0 + open_bins_count as f64 * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

