    if bin_residual == bin_capacity {
        let crowded = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let scarcity = 1.0 / (fitting_bins_count as f64).max(1.0);
        // Base penalty so open bins are preferred unless they fit poorly.
        score += 250.0 - crowded * 150.0 - scarcity * 120.0;
        // If lookahead item is huge, opening fresh bin is more attractive.
        if next_item_size > 0 && next_item_size > post_residual.max(1) {
            score -= 50.0;
        }
    }

    // Mild preference for bins below mean residual (balancing load).
    score += (post_residual as f64 - mean_residual) * 0.1;

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
