        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If mean residual is large, existing bins likely have room
        score += 0.4 * mean_residual;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 6.0 * fill * (open_bins_count as f64).ln().max(1.0);

    // Mild penalty for leaving residuals that no typical item (>=1) can use later
    if post_residual > 0 && post_residual < item_size.min(10) {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fit_ratio = pr / cap;
    let mut score = pr;

    // Smooth non-linear waste penalty: quadratic in normalized post-residual
    score += 30.0 * fit_ratio * fit_ratio * (1.0 + progress);

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio) * (0.3 + 0.7 * progress);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly early, more strongly when many bins open
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
        // Allow opening a new bin if it enables a perfect fit for the next item
        if next_item_size > 0 && (next_item_size as f64) >= cap * 0.9 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: penalize leaving residual close to next item size (fragmentation)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let d = (pr - nx) / cap;
        score += 20.0 * (1.0 - d * d) * (pr >= nx) as i32 as f64;
    }

    // Deviation from mean residual: prefer bins below mean (consolidate small residuals)
    score += 0.5 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-halving / thirding residuals are valuable
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit
    } else if pr <= 10 {
        score -= 15.0; // tiny dead space
    } else {
        // residual classes by integer division of capacity
        let quarter = bin_capacity / 4;
        let half = bin_capacity / 2;
        if pr % 2 == 0 { score -= 3.0; }          // even residual pairs better
        if pr % 5 == 0 { score -= 3.0; }          // multiple of 5 class
        if pr == half || pr == 2 * half { score -= 8.0; }
        if pr >= quarter && pr < half { score += 4.0; } // awkward middle class
        if pr > (3 * bin_capacity) / 4 { score -= 6.0; } // roomy bin stays flexible
    }

    // Lookahead coupling: does post_residual accommodate next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 10.0 + (slack as f64).min(20.0) * 0.3;
        } else {
            score += (next_item_size - pr) as f64 * 0.15;
        }
        // harmonic pair: item + next sums near capacity multiples
        let s = item_size + next_item_size;
        if bin_residual >= s && s % 10 == 0 { score -= 5.0; }
    } else {
        score += 2.0; // last item: mild preference for finishing bins
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current fits are poor
    if bin_residual == bin_capacity {
        score += 18.0;
        if mean_residual < item_size as f64 * 0.5 && open_bins_count > 0 {
            score -= 10.0;
        }
    }

    // Stream progression: consolidate more aggressively late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * progress;
    score -= (open_bins_count as f64).ln() * 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit even the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 15 {
        score += 18.0;
    } else if post_residual <= 25 {
        score += 6.0;
    } else {
        // Larger usable gaps are mildly rewarded.
        score -= 4.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap that blocks the next item: penalize proportionally.
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // favor filling existing bins (mildly).
    score += 0.8 * open_bins_count as f64;

    // New-bin candidate (empty bin): make it attractive only when current
    // bin fits are poor (large post_residual or blocking next item),
    // otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // nothing else fits: must open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item followed by big item: fresh bin ok
        }
    }

    // Stream progression: late in the stream, tighten up and avoid
    // opening bins with lots of leftover space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Prefer bins whose residual is close to the item (tight fit).
    score += 0.15 * ((bin_residual as f64) - (item_size as f64)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let tightness = (post_residual - next_item_size) as f64;
            score -= 300.0 - 2.0 * tightness;
        } else {
            // penalize dead space relative to next item
            score += 50.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Prefer tighter fits relative to mean residual
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize opening new bins when open bins exist, unless residual is small
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0 - 80.0 * progress;
        if next_item_size > 0 && bin_residual >= item_size + next_item_size {
            score -= 60.0; // fresh bin good for pairing
        }
    }

    // Mild penalty for leaving awkward small residuals (unusable gaps)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post-residual quadratically (dead space).
    score += 0.02 * (post_residual as f64) * (post_residual as f64);

    // Lookahead: if next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (nr - post_residual as f64).abs() < 0.5 {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 0.3 * nr;
        } else {
            // next item won't fit here: mild penalty proportional to wasted pairing potential
            score += 0.15 * (nr - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Discourage opening new bins when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Prefer bins with residuals far from the mean residual (avoid fragmenting typical space).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Slight preference for fuller bins (smaller residual) beyond raw post_residual.
    score -= 0.05 * (bin_capacity - bin_residual) as f64;

    // Time horizon: late in the stream, be more conservative — favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual < item_size * 2) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 + progress) - norm_post * progress * (1.0 - progress);
    score += 8.0 * poly;

    // Tight fit reward: cubic in fill fraction
    let fill = (bin_residual as f64 - post) / cap;
    score -= 12.0 * fill * fill * fill;

    // Last-chance bonus, smoothed by progress
    if fitting_bins_count == 1 {
        score -= 10.0 + 15.0 * progress;
    }

    // Penalize opening new bins late when many bins exist
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Lookahead coupling: quadratic in next item fit
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post - nxt).max(0.0);
        let waste = (nxt - post).max(0.0);
        score -= 2.0 * (1.0 - fits_next / cap);
        score += 4.0 * (waste / cap) * (waste / cap);
    }

    // Mean residual divergence penalty
    score += 0.3 * (post - mean_residual).abs() * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by small
    // item sizes (10, 20, 25, 50) remain "usable" by future items.
    let harmonic_bonus = if post_residual == 0 {
        -30.0 // perfect fit
    } else if post_residual % 50 == 0 {
        -12.0
    } else if post_residual % 25 == 0 || post_residual % 20 == 0 {
        -8.0
    } else if post_residual % 10 == 0 {
        -5.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Penalize small dead space that almost nothing can fill (waste zone).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Tightness reward: relative fill of the bin.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 15.0 * fill * fill;

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            score -= 6.0;
        } else {
            score += 8.0; // next item won't fit here: mild penalty
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a fresh bin is good only when the
    // item is large (big fill) or no open bin is a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let new_fill = item_size as f64 / cap;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 10.0 };
        // Penalize new bin unless the item fills it well.
        score += 22.0 * (1.0 - new_fill) + pressure;
        // Encourage new bin early in the stream when few bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress) * (1.0 - open_bins_count.min(8) as f64 / 8.0);
    }

    // Slight preference for bins below mean residual (keeps balance).
    score += 0.05 * (mean_residual - bin_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold the minimum item (1..10) are pure waste. Penalize them hard.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward near-perfect fits (small but still-usable residuals).
    if post_residual > 0 && post_residual <= 15 {
        score -= 12.0;
    }

    // Reward exact fills.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // this placement is doubly valuable; if not, the residual risks
    // becoming dead space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    // Open-bin pressure: discourage spreading across many open bins;
    // prefer filling existing bins when several are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make the empty bin moderately attractive so it
    // wins only when open bins have poor fits (large post_residual or
    // dead-space penalties).
    if bin_residual == bin_capacity {
        score -= 20.0;
    }

    // Slight preference for bins with below-average residual (tighter bins),
    // keeping large residuals free for large future items.
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Late in the stream, consolidate: penalize residual waste more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: item + next item fills bin completely
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize dead space
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.4;
        }
    }

    // Compare post_residual relative to mean residual of open bins.
    let mean_post = mean_residual - item_size as f64;
    if mean_post > 0.0 {
        score += (post_residual as f64 - mean_post) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize very small dead space that is hard to reuse (< 10).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Early in stream, be more willing to open new bins (keep residuals large).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 - 30.0 * progress; // new bin attractive early, unattractive late
    }

    // Late stream: consolidate into existing bins aggressively.
    score -= progress * 10.0 * (1.0 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more strongly as item size grows.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * (item_size as f64 / bin_capacity as f64);

    // Penalize dead space: post residual that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 6.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin before opening a new one: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // When many bins can fit the item, mild penalty for hogging scarce residual capacity.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Global state: prefer filling bins when mean residual is high (many scattered bins).
    score += 0.08 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, be more willing to spread (open new bins);
    // late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);
    score -= 6.0 * progress * tightness;

    // New-bin candidate: only attractive when no open bin fits well or stream is early.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        score += 14.0 - desperation - 10.0 * progress;
    }

    // Encourage using very full bins (low residual) to close them out.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_frac = pr / cap;

    // Base: penalize post-residual, with non-linear (quadratic) coupling to stream progress.
    // Early on, prefer tight fits mildly; later, dead space matters more.
    let mut score = pr * (1.0 + progress * progress)
        + 0.5 * fit_frac * fit_frac * cap * (0.3 + 0.7 * progress);

    // Reward using nearly-full bins (small post residual) with a smooth saturating term.
    score -= 20.0 * (1.0 - fit_frac).powi(3);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack * slack);
        } else {
            // Next item cannot fit here; slight penalty proportional to overflow.
            score += 0.05 * (nxt - pr);
        }
    }

    // Penalize spreading residuals far above mean (fragmentation smoothing).
    score += 0.3 * (pr as f64 - mean_residual).abs() * (0.5 + 0.5 * progress);

    // Mild penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (open_bins_count as f64).sqrt() - 20.0 * progress * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "reusable" classes (multiples of small harmonics) are preferred.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity left after placement.
    let frac = post / cap;

    // Penalize residuals that are too small to ever be useful again
    // (dead space). Items are 1..100, so residual < ~10 is nearly dead.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (1.0 - post / 10.0);
    }

    // Reward residuals in "harmonic" classes: divisible by 25, 20, 10.
    if post_residual > 0 {
        if post_residual % 25 == 0 {
            score -= 8.0;
        } else if post_residual % 20 == 0 {
            score -= 6.0;
        } else if post_residual % 10 == 0 {
            score -= 4.0;
        }
    }

    // Perfect fit is best.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: leftover after both placements matters.
            let both = post_residual - next_item_size;
            if both % 10 == 0 {
                score -= 6.0;
            }
            score -= 10.0 * (1.0 - both as f64 / cap).min(1.0);
        } else {
            // Next item will not fit here: slight penalty proportional to
            // how much leftover is wasted relative to next item.
            score += 3.0 * (1.0 - (next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity
    // minus item. Prefer keeping it closed unless open bins are fragmented.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress
        // (later in the stream, fewer items remain, opening is cheaper).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 12.0 * (1.0 - 0.5 * progress);
        // If many open bins are badly fragmented, opening is more attractive.
        if mean_residual > 0.0 {
            let fragmentation = (mean_residual - post).abs() / cap;
            score -= 6.0 * fragmentation.min(1.0);
        }
    } else {
        // Filling an existing bin: reward tightness relative to mean residual.
        if mean_residual > 0.0 {
            // Prefer bins whose residual is below the mean (tight bins).
            let tightness = (mean_residual - bin_residual as f64) / cap;
            score -= 5.0 * tightness;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln() * (cap - bin_residual as f64) / cap;
    }

    // Integer-division threshold on post_residual: residuals in
    // [cap/2, cap) are very reusable; residuals in (0, cap/4) are poor.
    if post_residual >= bin_capacity / 2 {
        score -= 5.0;
    } else if post_residual < bin_capacity / 4 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 60.0 * (10.0 - dead) / 10.0;
    }
    // Moderate penalty for medium gaps that are unlikely to fit typical items.
    if dead >= 10.0 && dead < 25.0 {
        score += 12.0 * (25.0 - dead) / 15.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> discourage opening a new one.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.5 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins tighter than the current mean residual (consolidate waste).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Lookahead: favor leaving space exactly usable by the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 3.0;
        } else {
            score += 4.0;
        }
    }

    // Early in the stream, be slightly more willing to consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Near match: next item fits with small leftover -> reward proportionally.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot use this residual: penalize if residual becomes dead space.
    else if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 20.0; // tiny unusable sliver
        } else {
            score += 5.0;
        }
    }

    // Reward tight fits relative to mean residual (bin tighter than average is good).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when item is large or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Penalize opening new bins generally; relax when item is big / many bins open.
        let penalty = 55.0 - 25.0 * item_frac - 10.0 * (open_bins_count as f64 / 10.0).min(1.0) - 10.0 * (1.0 - progress);
        score += penalty.max(0.0);
    }

    // Slight preference for fuller bins.
    score += 0.1 * (bin_capacity - bin_residual) as f64 * 0.0; // neutralized filler
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (near-zero post residual is ideal).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals that are too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is attractive only when
    // the item fits poorly anywhere else (large post residual would result).
    if bin_residual == bin_capacity {
        // Mild default penalty so existing good fits win.
        score += 8.0;
        // But if this bin would leave a perfect residual, it's a great start.
        if post_residual == 0 {
            score -= 40.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Next item can't use this bin's leftover: slight penalty.
            score += 3.0;
        }
    }

    // Prefer filling bins when many are open (consolidation pressure).
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Prefer bins whose residual is close to the global mean residual
    // (keeps bin states homogeneous, easing future packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Early in the stream, be slightly more willing to spread out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 12.0 * norm_pr * norm_pr * (0.5 + p2);
    score -= 8.0 * norm_pr * (1.0 - progress) * (1.0 - progress);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * (0.3 + p3);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let wasted = (pr - nxt).max(0.0) / cap;
        score += 20.0 * wasted * wasted * (1.0 + progress);
        if pr >= nxt {
            score -= 6.0 * (1.0 - nxt / cap) * (1.0 - progress);
        }
    } else {
        // Last item: strongly prefer fullest packing
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Last-chance bin bonus when few fitting bins exist
    if fitting_bins_count == 1 {
        score -= 10.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    let mean_dev = (pr - mean_residual) / cap;
    score += 3.0 * mean_dev * mean_dev * (1.0 - progress);

    // New-bin candidate: only attractive when existing residuals are poor
    if bin_residual == bin_capacity {
        let poor_existing = (mean_residual / cap).min(1.0);
        score += 30.0 * (1.0 - poor_existing) * (0.4 + 0.6 * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual modulo small divisors.
    // Leftovers in "friendly" classes (multiples of 10, or >= 50) are less dead.
    let pr = post_residual;
    let class10 = (pr % 10) as f64;
    let class5 = (pr % 5) as f64;

    // Penalize awkward remainders (not divisible by 5/10) -> likely dead space.
    score += class10 * 0.8 + class5 * 0.4;

    // Reward large usable leftovers with a concave (square-root) bonus so
    // moderate gaps are preferred over tiny gaps only weakly.
    if pr >= 50 {
        score -= (pr as f64).sqrt() * 2.0;
    }

    // Integer-division thresholds on post_residual: perfect small-slot zones.
    if pr == 0 {
        score -= 30.0; // perfect fit is ideal
    } else if pr <= 10 {
        score += 6.0; // tiny gap: nearly dead space
    } else if pr <= 20 {
        score -= 4.0; // usable small-slot zone
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if it cannot fit, mildly penalize (dead-end risk).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size > pr {
            score += 3.0;
        } else {
            // Harmonic divisibility: next item divides the gap evenly.
            if pr % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    // (huge post residual wasted relative to a fresh bin) or no good fit exists.
    if bin_residual == bin_capacity {
        // Fresh bin: baseline score of full residual, adjusted by context.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 20.0 * (1.0 - progress);
        if item_size >= 50 {
            score -= 5.0; // big items start fresh bins more readily
        }
    }

    // Prefer bins below mean residual (tighter packing pressure balance).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Slight preference to keep open bin count low early in the stream.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps hard (dead space avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // post_residual won't fit next item: penalize proportional to wasted space
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Open bins pressure: discourage spreading across many bins unless residual is small
    score += open_bins_count as f64 * 2.0;

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if fitting_bins_count == 1 {
            score += 20.0;
        }
    }

    // Tight packing: prefer bins whose residual was already small relative to mean
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits after this placement: strong reward, scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.2 * leftover;
    }

    // Penalize dead space too small for the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin before opening a new one: strong reward.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when plenty of bins are open and fitting.
    if bin_residual == bin_capacity {
        score += 10.0 * (open_bins_count as f64).sqrt();
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0; // fresh bin still great if it chains perfectly
        }
    }

    // Late-stream urgency: close bins tightly as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 0.1 * (bin_capacity - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: shrink score when post_residual is a small unusable sliver.
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * 0.45 * cap;

    // Perfect/near-perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 3 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin;
    // if the next item would be blocked, penalize proportionally to blocking severity.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // Chain fit bonus, stronger for larger next items (chaining value).
            score -= 8.0 + (nxt / cap) * 25.0;
        } else {
            // Dead-space penalty scaled by how much of next item is blocked.
            let blocked = (nxt - post).min(cap);
            score += 0.30 * blocked * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance dynamics: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin; scale with stream progress.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0 + 25.0 * progress;
    }

    // Crowding penalty: when many bins are open, discourage spreading into bins
    // with large residuals; encourage consolidating into low-residual bins.
    if open_bins_count > 1 {
        let spread = (bin_residual as f64 - mean_residual).max(0.0);
        score += 0.12 * spread;
        // Mild consolidation bonus for below-average residual bins.
        if (bin_residual as f64) < mean_residual {
            score -= 0.08 * (mean_residual - bin_residual as f64);
        }
    }

    // Time horizon: early in the stream, keep bins flexible (penalize very low
    // post-residuals slightly less; prefer leaving room). Late in the stream,
    // prioritize filling bins completely.
    if progress < 0.35 {
        // Early: keep flexibility — penalize creating tiny dead space less,
        // penalize consuming large-residual bins slightly.
        if bin_residual > 0.8 * cap {
            score += 4.0;
        }
    } else {
        // Late: full-fill pressure.
        score -= 10.0 * progress * tightness;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize opening a new bin unless the item is large
    // (poor fit candidates) or late in the stream with few bins.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = fitting_bins_count == 0 || (fitting_bins_count == 1 && post_residual > 0.55 * cap);
        if poor_fit_elsewhere && item >= 50.0 {
            score -= 20.0 + 0.2 * item; // allow a fresh bin for big items
        } else {
            score += 25.0 + 10.0 * (1.0 - progress); // discourage needless new bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress * norm_pr + 0.5 * progress * progress * (1.0 - norm_pr));

    let mut score = poly * cap;

    // Penalize dead space more strongly as the stream progresses
    score += 1.5 * progress * pr * (pr / cap);

    // Reward tight fits (small post_residual), smoothly
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 4.0;
    } else if next_item_size > 0 {
        score += 2.0 * (next_item_size as f64 - pr) / cap;
    }

    // Mild penalty for spreading across many open bins
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Encourage keeping residuals near mean (balanced bins), smooth term
    score += 0.5 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: baseline competitive score so it is chosen only when good
    if bin_residual == bin_capacity {
        score += 8.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into "useful"
    // residue classes (small remainders that later small items can fill).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals in (0, 10) are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic class reward: residual divisible by common small item sizes
    // (10, 20, 25, 50) is more likely to be exactly filled later.
    for d in [10u32, 20, 25, 50] {
        if post_residual % d == 0 && post_residual > 0 {
            score -= 8.0 + (d as f64) * 0.2;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size < post_residual {
            // reward small leftover after hypothetically placing next item
            let after_next = post_residual - next_item_size;
            score -= (after_next as f64) * 0.5;
            if after_next % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this residual: penalize proportional waste
            score += (next_item_size as f64 - pr).min(40.0) * 0.3;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + (item_size as f64) * 0.2;
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses
        // (early stream: cheap to open; late stream: prefer filling existing bins).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * (0.85 - 0.35 * progress) + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 5.0; // new bin can host a future pair
        }
        // If many bins fit the item, opening a new one is wasteful.
        score += (fitting_bins_count as f64) * 4.0;
    }

    // Mild preference for bins tighter than the mean residual (best-fit flavor).
    score += (pr - mean_residual) * 0.15;

    // Tie-break with harmonic class of residual modulo capacity quarter.
    let q = (bin_capacity / 4) as f64;
    score += ((pr % q) / q) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers (< 10) are unusable for
    // typical items (min size 10 in classic streams, but sizes can go to 1).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - 4.0 * post_residual as f64; // heavy penalty for 1..9 gap
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item if it can fit in post_residual.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0;
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            // creating a gap just below next item size is dead space
            score += 8.0;
        }
    }

    // Open-bins pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // already "cramped"; prefer bins near the mean or larger.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.08 * diff.abs();

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when the
    // item is large relative to capacity or no tight fit exists.
    if bin_residual == bin_capacity {
        score += 12.0; // default bias toward reusing open bins
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0; // big items may justify a fresh bin
        }
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            score -= 4.0; // fresh bin leaves room for lookahead
        }
    }

    // Slight preference for tighter fits overall.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), but weight it non-linearly.
    score = (post_residual as f64).powf(1.25);

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this bin achieves a perfect 2-item packing -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves a further residual: reward proportional
            // to how little slack remains after the second placement.
            let second_post = post_residual - next_item_size;
            score -= 25.0 - 0.15 * second_post as f64;
        } else {
            // Next item cannot use the leftover: penalize leftover dead space,
            // scaled by how large it is relative to the next item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.10 * gap;
        }
    } else {
        // Last item: leftover is pure waste, penalize heavily.
        score += 0.5 * post_residual as f64;
    }

    // Reward bins whose residual deviates below the mean (tight bins first),
    // penalize bins close to the mean (ambiguous fit quality).
    let dev = mean_residual - post_residual as f64;
    score -= 0.05 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has post_residual = capacity - item.
    // Only prefer it when existing bins would leave very large unusable slack.
    if bin_residual == bin_capacity {
        // Neutral baseline; add a mild penalty so tight existing fits win,
        // but it can still win if all open bins score very high.
        score += 8.0;
        // Late in the stream, opening fresh bins is safer (less dead-space risk).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Slight penalty for very small post_residuals that are NOT exact matches
    // for the next item (fragmentation risk: unusable slivers).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / cap;
    score += 40.0 * waste_frac * waste_frac;

    // Reward near-perfect packing (small absolute leftover).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Penalize bins whose residual is much above the mean (they stay useful elsewhere).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() <= 1.0 {
            score -= 35.0;
        } else if nxt <= post_residual as f64 {
            score -= 0.3 * (post_residual as f64 - nxt);
        } else {
            // Next item won't fit here: mildly penalize leaving awkward gaps.
            score += 0.2 * (nxt - post_residual as f64).min(40.0);
        }
    }

    // New-bin candidate handling: penalize opening a new bin, more so early in the stream
    // and when other bins fit; relax when the item is huge or nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut penalty = 55.0 - 25.0 * progress;
        if fitting_bins_count == 0 {
            penalty = -10.0;
        } else if item_size as f64 > 0.8 * cap {
            penalty -= 40.0;
        } else if post_residual as f64 >= 0.45 * cap && fitting_bins_count > 2 {
            penalty -= 20.0;
        }
        score += penalty;
    }

    // Mild preference for filling bins with smaller residuals (best-fit flavor) scaled
    // by stream position: later in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 0.1 * (cap - bin_residual as f64);

    // Slight penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;

    // Smooth normalized post-residual (0..1)
    let x = (pr / cap).clamp(0.0, 1.0);

    // Base: prefer small post-residual, with non-linear polynomial shaping
    // penalizing both very small (dead space) and moderately wasteful residuals.
    let mut score = pr as f64 * (1.0 + 0.6 * x * (1.0 - x));

    // Dead-space penalty: smooth cubic rise for tiny residuals that fit nothing.
    let deadness = 1.0 - (pr / 10.0).min(1.0);
    score += 14.0 * deadness * deadness * deadness;

    // Lookahead coupling: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let fits_next = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 8.0 * fits_next * (1.0 - gap).max(0.0);
        score += 3.0 * (1.0 - fits_next) * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: smooth reward when this bin is nearly the only option.
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 6.0 * scarcity * (1.0 - progress * 0.5);

    // Stream-progress coupling: later in the stream, waste matters more.
    score += 10.0 * progress * x * x;

    // New-bin candidate: smooth penalty that relaxes when open bins are crowded
    // or residuals are large relative to the item.
    if is_new_bin {
        let crowding = (open_bins_count as f64).ln().max(0.0);
        let fit_pressure = item_size as f64 / cap;
        let relax = (mean_residual / cap).clamp(0.0, 1.0);
        score += 18.0 + 4.0 * crowding - 20.0 * fit_pressure - 12.0 * relax * progress;
    } else {
        // Mild preference for using already-open bins when mean residual is high.
        score -= 2.0 * ((bin_residual as f64 - mean_residual) / cap).clamp(-1.0, 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quarter fractions of capacity
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * quarter;

    // Reward tight fits (post_residual in the lowest harmonic band)
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual <= quarter / 4 {
        score -= 25.0;
    } else if post_residual <= quarter {
        score -= 12.0;
    } else if post_residual <= half {
        score -= 3.0;
    } else if post_residual <= three_quarter {
        score += 8.0; // wasteful large leftover
    } else {
        score += 18.0;
    }

    // Dead-space penalty via integer division: unusable residue for next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = post_residual as f64 / next_item_size as f64;
        score += 6.0 + 10.0 * dead;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // small bonus if next item fits exactly into this residual (chained packing)
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual - next_item_size <= quarter / 4 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // mild competition bonus, tighter fits still preferred via post_residual
        score -= 2.0;
    }

    // New empty bin candidate: only attractive when open bins are nearly full
    if bin_residual == bin_capacity {
        let avg_fill = cap - mean_residual.max(0.0);
        let pressure = avg_fill / cap; // 0..1
        // penalize opening new bin normally, discount when bins are crowded
        score += 30.0 - 35.0 * pressure;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // late in the stream keep consolidating
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 5.0 * progress;
    }

    // Modulo harmonic: residuals that align with common item classes (multiples of 10) are more reusable
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 4.0;
    }
    if item_size % 10 == 0 && post_residual % 10 == 0 {
        score -= 3.0;
    }

    // Mild mean-residual coupling: prefer bins below mean residual (more filled than average)
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item are "dead space" — penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual >= 20 && post_residual < 30 {
        score += 6.0;
    } else if post_residual == 0 {
        // Perfect fill — strong reward.
        score -= 120.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading items
    // across more bins; prefer consolidating into existing space.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward; if post residual is just barely too small for the next item,
    // penalize the wasted gap.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 12.0 * (1.0 - (next - post_residual as f64) / next);
        }
    }

    // Mean-residual coupling: bins with residual near the mean are "typical"
    // targets; deviating bins (very full or very empty) get slight penalties
    // to keep residual distribution compact.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: opening a new bin is only attractive when no open
    // bin offers a decent fit (post residual would be tiny) or stream is
    // early. Otherwise penalize it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let worst_gap = post_residual as f64; // residual after placing in new bin
        let _ = worst_gap;
        score += 35.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // If next item is large, a fresh bin is more forgiving.
        score -= 0.2 * next_item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/compact fit (small post_residual)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post == next {
            score -= 500.0;
        } else if post >= next {
            let slack = post - next;
            score -= 40.0 / (1.0 + slack);
            // penalize large leftover after hypothetical next placement
            score += 0.3 * slack;
        } else {
            // next item won't fit here: mild penalty proportional to gap
            score += 0.15 * (next - post);
        }
    } else {
        // last item: strongly prefer tightest fit
        score -= 200.0;
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins)
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New empty bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 80.0 };
        score += 120.0 + pressure + 0.5 * open_bins_count as f64;
        // allow new bin if item is large and would leave big residual elsewhere
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 60.0;
        }
    }

    // Prefer filling bins that are already fairly full
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fullness;

    // Early stream: be slightly more conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed -> dynamic time horizon
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (small post_residual), with a non-linear sharpening
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += (pr / cap) * (pr / cap) * 20.0;

    // Reward when the lookahead item can still fit into the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_pair = post_residual - next_item_size;
        // reward proportional to how well the pair packs
        score -= 8.0 + (slack_after_pair as f64 / cap) * 6.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next item fits this bin only if we place current item here poorly? penalize waste
        score += 2.0;
    }

    // Last chance: this is the only bin that can fit the item -> strong reward
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins with large mean residual -> prefer consolidating
    let pressure = open_bins_count as f64 * (mean_residual / cap);
    score -= pressure * 0.5;

    // Early in the stream: be picky about dead space; late: just fill anything
    let pickiness = 1.0 - progress;
    score += (pr / cap) * 10.0 * pickiness;

    // New-bin candidate: only attractive if this bin would otherwise be a terrible fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty for opening a new bin
        let mut new_score = cap as f64 * 0.9 + open_bins_count as f64 * 2.0;
        // if lookahead item is large, a fresh bin is valuable
        if next_item_size > 0 {
            new_score -= (next_item_size as f64 / cap) * 20.0;
        }
        // late in stream, opening bins is less costly
        new_score -= progress * 15.0;
        // if no open bin fits (fitting_bins_count refers to open bins; new bin always fits)
        if fitting_bins_count == 0 {
            new_score -= 30.0;
        }
        score = new_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling between post_residual and stream progress
    let poly = norm_pr * norm_pr * (0.5 + 1.5 * progress) + norm_pr * (1.0 - progress) * 0.8;
    score += poly * 12.0;

    // Reward tight fits more strongly as stream progresses
    let fit_tightness = 1.0 - norm_pr;
    score -= fit_tightness * fit_tightness * (10.0 + 20.0 * progress);

    // Lookahead: reward leaving room for next item, smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let room = (pr - n) / cap;
        if room >= 0.0 {
            score -= room * (8.0 + 12.0 * progress);
        } else {
            score += (-room) * cap * 0.15;
        }
    }

    // Penalize near-mean residual divergence (smooth coupling)
    score += ((pr - mean_residual) / cap).powi(2) * 6.0;

    // Last-chance bin bonus: avoid opening new bins unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: penalize mildly, more so late in stream
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    // Slight penalty for too many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residues divisible by common
    // item sizes (10/20/25/50) are more reusable, so reward them.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 { 60.0 }
        else if pr % 10 == 0 { 12.0 }
        else if pr % 25 == 0 { 10.0 }
        else if pr % 20 == 0 { 8.0 }
        else if pr % 5 == 0 { 4.0 }
        else { 0.0 };
    score -= harmonic_bonus;

    // Perfect fit is ideal.
    if pr == 0 { score -= 40.0; }

    // Small but awkward residuals are dead space: penalize sub-threshold slivers
    // (integer division class: pr in 1..10 is nearly unusable).
    if pr > 0 && pr < 10 { score += 25.0; }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin; if it nearly fits, mild penalty.
    if next_item_size > 0 {
        if next_item_size == pr { score -= 35.0; }
        else if next_item_size > pr {
            let overflow = (next_item_size - pr) as f64;
            score += 0.15 * overflow;
        } else {
            let slack = (pr - next_item_size) as f64;
            if slack < 10.0 { score += 0.5 * slack; }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is large relative to the
    // capacity (would leave open bins cramped) or few bins fit the item.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / cap;
        let mut nb = 55.0;
        nb -= 40.0 * fill_frac;
        if fitting_bins_count == 0 { nb -= 60.0; }
        if next_item_size > 0 && next_item_size >= (bin_capacity - item_size) { nb -= 20.0; }
        // late in the stream, prefer consolidation over opening bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb += 20.0 * progress;
        score = nb;
    }

    // Mild preference to fill bins that are already mostly full.
    let used_frac = (bin_capacity - bin_residual) as f64 / cap;
    score -= 8.0 * used_frac;

    // Spread across many open bins is bad; favor bins below mean residual
    // (i.e., fuller than average) slightly.
    score += 0.05 * (mean_residual - (bin_residual as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100, min 1)
    // are pure waste. Penalize unusable gaps super-linearly.
    if post_residual > 0 {
        // any gap is potentially usable for tiny items, but small gaps (< 10)
        // are highly likely dead; penalize sharply.
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64);
        } else {
            // smooth extra penalty for awkward mid-size gaps relative to mean residual
            let gap = post_residual as f64;
            let awkward = (gap - mean_residual.max(1.0)).abs();
            score += 0.25 * awkward;
        }
    } else {
        // perfect fit: strong reward
        score -= 50.0;
    }

    // Reward tight fits: fraction of bin used by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins; when few bins are open, be less picky.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless it creates large dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual < 10 {
            // dead space anyway; mild preference still (avoid new bin sprawl)
            score -= 5.0;
        } else {
            score -= 25.0;
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits, but leaves further residual: small reward
            score -= 8.0;
        } else {
            // next item won't fit here; penalize leaving a gap next item can't use
            if post_residual < next_item_size {
                score += 10.0;
            }
        }
    }

    // New-bin candidate handling: empty bin should only win when no existing
    // bin offers a decent fit. Make the empty bin moderately unattractive.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * pressure;
        // but if stream is early, opening bins is fine
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Mild preference for bins whose residual is close to item (best-fit core)
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 150.0 / (post_residual as f64).sqrt();
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chaining: next item fits exactly into the leftover.
            if post_residual == next_item_size {
                score -= 400.0;
            } else {
                // Partial reward scaled by how well the next item fills the residual.
                let fill_ratio = next_item_size as f64 / post_residual as f64;
                score -= 200.0 * fill_ratio;
            }
        } else {
            // Penalize leftovers that the next item cannot use (potential dead space),
            // unless the leftover is tiny (still a good fit for the current item).
            let waste = next_item_size - post_residual;
            score += 0.35 * waste as f64;
        }
    }

    // Relative to mean residual: prefer bins that are already more loaded than average
    // (tight packing) when they still fit well.
    let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 30.0 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Slight preference for consolidating into fewer bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate (empty bin): penalize mildly so it is only chosen when
    // no open bin offers a decent fit or a strong lookahead chain.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Allow new bin if the lookahead chain is perfect from a fresh bin.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early in stream, pack tightly; later, be more flexible.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 12.0;

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item fills the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * fill;
        } else {
            // post_residual too small for next item: penalize dead space
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 8.0 * dead * (1.0 - progress);
        }
    } else {
        // last item: any bin that fits is fine, prefer tightest
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
        if post_residual as f64 > bin_capacity as f64 * 0.5 {
            score += 10.0; // wasteful use of the last fitting bin
        }
    }

    // Global state coupling: many open bins with high mean residual ->
    // discourage opening new bins, encourage filling existing ones.
    if bin_residual != bin_capacity {
        let crowd = (open_bins_count as f64).ln().max(1.0);
        score -= 4.0 * (mean_residual / bin_capacity as f64) / crowd;
    }

    // New-bin candidate handling: make it expensive, but cheaper when
    // remaining open space is fragmented (mean residual low, many bins).
    if bin_residual == bin_capacity {
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = bin_capacity as f64 + 20.0 - 30.0 * fragmentation - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 50.0; // nothing open can hold next item anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: waste after placement, scaled non-linearly.
    let mut score = post * (1.0 + 0.8 * post / cap);

    // Tight fit reward: strongly subtract when post_residual is small.
    let tightness = 1.0 - (post / cap);
    score -= 30.0 * tightness * tightness * tightness;

    // Non-linear coupling of waste with stream progress:
    // late in the stream, dead space is more costly; early on, keep bins flexible.
    let waste_penalty = post / cap;
    let progress_coupling = waste_penalty * (1.0 - waste_penalty) * progress * progress;
    score += 25.0 * progress_coupling;

    // Lookahead: penalize if post_residual can't fit next item but barely misses,
    // reward if next item fits snugly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let next_tight = 1.0 - ((post - nxt) / cap);
            score -= 12.0 * next_tight * next_tight;
        } else {
            let miss = (nxt - post) / cap;
            score += 15.0 * miss * (1.0 - miss);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * (1.0 - post / cap);
    }

    // Prefer bins below mean residual when many bins are open (balance load),
    // smooth polynomial coupling with open_bins_count.
    let open_norm = (open_bins_count as f64).ln_1p();
    let mean_gap = (mean_residual - post) / cap;
    score += 5.0 * open_norm * mean_gap * mean_gap.abs() * mean_gap.signum();

    // Mild preference for fuller bins overall (quadratic in fill ratio).
    let fill = 1.0 - post / cap;
    score -= 10.0 * fill * fill;

    // New-bin candidate: penalize opening a bin unless current bin waste is severe.
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fractions (1/2, 1/3, 1/4 of C)
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Reward tight fits: residual in low harmonic classes is nearly dead space
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < quarter {
        score -= 25.0;
    } else if post_residual < third {
        score -= 10.0;
    } else if post_residual < half {
        score += 5.0;
    } else {
        score += 15.0; // leaves a big hole
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // item classes (10, 20, 25) are reusable -> reward them.
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 1.5;
    } else {
        score += 2.0; // awkward residual
    }

    // Lookahead coupling: does the residual accommodate the next item?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize more if the gap is small but useless
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening fresh is attractive early in the stream
    // or when many bins are open and this fit is poor.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new bin: baseline cost of consuming fresh capacity
        score = 100.0 - 30.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 80.0; // nothing fits anywhere, must open
        }
    } else if open_bins_count > 3 && post_residual < quarter {
        // good compaction when many bins open: keep closing them
        score -= 6.0;
    }

    // Mild alignment with mean residual: prefer bins whose post-residual stays near mean
    let mean_dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * mean_dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let dead_zone = 15.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Next-item lookahead: reward residuals that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5;
    score += mean_residual * 0.1;

    // Slight progress-scaled bias to keep early bins open longer.
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual == 0 is perfect packing.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to the smallest possible item (1).
        score += (post_residual as f64 / bin_capacity as f64) * 50.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // Next item fits here: mild reward proportional to how well it fills the remainder.
            let fill_after_next = (post_residual - next_item_size) as f64;
            score -= (1.0 - fill_after_next / bin_capacity as f64) * 120.0;
            score += fill_after_next * 0.4;
        } else {
            // Next item won't fit here: penalize bins whose residual is just below next_item_size
            // (near-miss wasted space), scaled by stream progression.
            let progress = step_index as f64 / total_items.max(1) as f64;
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += gap * (2.0 + 3.0 * progress);
            }
        }
    }

    // Relative-to-mean coupling: prefer bins with below-average residual (denser bins).
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: make it unattractive unless current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual * 0.2;
        // If no other bin fits, the new bin is the only option anyway (fitting_bins_count==1 case
        // for the empty bin itself), so it wins naturally.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 40.0; // fresh bin useful for upcoming large items
        }
    }

    // Mild penalty for bin sprawl: fewer open bins preferred when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional tightness: reward near-perfect fills
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: penalize dead space that the next item cannot use
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // unusable gap for the known next item
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // next item fits nicely: reward leaving a usable slot
            let slack = (post_residual - next_item_size) as f64;
            score -= 0.35 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + 6.0 * progress;
    }

    // Penalize scattering across many open bins when few fit
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Global state coupling: with many open bins and high mean residual,
    // prefer consolidation into existing bins
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.05 * crowding;

    // New-bin candidate logic: empty bin gets a handicap that shrinks
    // late in the stream or when existing bins are badly fragmented
    if bin_residual == bin_capacity {
        let handicap = 10.0
            - 6.0 * progress
            - (item_size as f64 / bin_capacity as f64) * 4.0;
        score += handicap.max(0.0);
    }

    // Mild penalty for very large leftover gaps that likely become dead space
    if post_residual > 0 && post_residual < 10 {
        score -= 3.0; // tiny residual = near-perfect packing
    } else if post_residual >= 10 && post_residual < item_size.min(60) {
        score += 0.2 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post-residual, slightly super-linear (dead space penalized more later).
    let mut score = post * (1.0 + 0.8 * progress) + 0.35 * post * post / cap;

    // Reward tight fits (low post_residual relative to item).
    score -= 2.5 * (item / cap) * (1.0 - post / cap);

    // Penalize leaving a residual that no plausible next item (>=1) can use well:
    // dead space if post_residual too small relative to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - post).max(0.0);
        score += 0.9 * (gap / cap).powf(1.5) * (1.0 - progress * 0.5);
        // Reward leaving room exactly for the next item.
        score -= 0.6 * (1.0 - (nxt - post).abs() / cap);
    } else {
        // Last item: strongly prefer filling bins as tightly as possible.
        score += 3.0 * post / cap;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: penalize opening bins when good fits exist,
    // but allow early-opening when many bins are open and residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        score += 4.0 - 2.5 * fragmentation - 3.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score += 0.5; // new bin can host next item too; slight penalty still
        }
        if item as u32 >= 60 {
            score -= 1.0; // big items: fresh bin more acceptable
        }
    }

    // Mild diversity bonus: prefer bins whose residual deviates from the mean
    // when mean residual is large (consolidate fragmented space).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score -= 0.4 * dev * fragmentation_hint(mean_residual, cap);

    score
}

#[inline]
fn fragmentation_hint(mean_residual: f64, cap: f64) -> f64 {
    (mean_residual / cap).clamp(0.0, 1.0)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: harmonic decay of wasted-space penalty
    let tight = (bin_capacity as f64 / (post_residual as f64 + 1.0)).min(6.0);
    score -= tight;

    // Lookahead: reward bins whose residual can host the next item (harmonic chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
        // extra reward if next item fills residual nearly exactly
        let gap = post_residual - next_item_size;
        if gap <= 10 { score -= 2.0; }
    }

    // Dead-space classes: tiny residuals are cheap, mid-range residuals are wasteful
    if post_residual == 0 {
        score -= 8.0;
    } else if post_residual < 10 {
        score -= 3.0;
    } else if post_residual <= 25 {
        score += 2.0;
    }

    // New-bin candidate: discourage opening a bin when good fits exist,
    // but strongly favor it when it is the only option (fitting_bins_count == 0)
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 15.0;
        } else if fitting_bins_count == 1 {
            score += 1.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bonus: this is the only open bin that fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0;
    }

    // Late-stream consolidation: prefer reusing bins as stream matures
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead-space penalty strongest for tiny gaps (1..=20), decaying beyond.
        let dead_weight = if gap <= 20.0 {
            60.0 - gap * 2.5
        } else {
            (25.0 - gap * 0.15).max(0.0)
        };
        score += dead_weight;

        // If the next item cannot fit into the resulting gap, penalize more.
        if next_item_size > 0 && next_item_size > post_residual {
            score += 18.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            // Reward gaps that exactly or nearly accommodate the lookahead item.
            let slack = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= (14.0 - slack.min(14.0)) * 0.8;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 45.0;
    }

    // Reward tight fits relative to the current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: when many bins are open, discourage spreading;
    // favor reusing bins instead of opening new ones.
    score += (open_bins_count as f64) * 0.35;

    // Mean residual coupling: penalize placing into bins whose residual is far
    // below the mean (they are already tight), mildly favor average bins.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.12;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, reduced if many bins are open
        // (fragmentation already high) or if this is a large item.
        let mut new_bin_cost = 55.0;
        if fitting_bins_count == 0 {
            new_bin_cost -= 40.0;
        }
        if item_size > bin_capacity / 2 {
            new_bin_cost -= 8.0;
        }
        if open_bins_count > 6 {
            new_bin_cost -= 6.0;
        }
        // Early stream: slightly cheaper to open bins (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_cost -= (1.0 - progress) * 6.0;
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 300.0;
    } else {
        // Squared penalty on wasted space, normalized by capacity.
        score += (post_residual as f64).powi(2) / bin_capacity as f64;
    }

    // Aggressive 2-step lookahead: reward if the next item exactly fills
    // the post-residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits, but how tight is the chain?
            let chain_waste = post_residual - next_item_size;
            score -= 200.0 - (chain_waste as f64) * 3.0;
        } else {
            // Next item will NOT fit in this bin's remainder: mild penalty
            // proportional to the overflow gap.
            score += ((next_item_size - post_residual) as f64) * 0.5;
        }
    }

    // Compare against mean residual: bins with residual far above the mean
    // are "rich" and should absorb items to consolidate space.
    let residual_gap = bin_residual as f64 - mean_residual;
    score -= residual_gap * 0.8;

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no existing
    // bin offers a decent fit (post_residual would be large relative to
    // capacity) and there are already open bins to fall back on.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0 && bin_residual - item_size == bin_capacity - item_size;
    if is_new_bin {
        let open_fits_well = mean_residual >= item_size as f64 * 1.2;
        if open_fits_well {
            // Existing bins are roomy enough: discourage opening a new bin.
            score += 400.0 + (open_bins_count as f64) * 5.0;
        } else {
            // Existing bins are tight: opening a new bin is attractive,
            // especially early in the stream.
            let progress = step_index as f64 / (total_items.max(1) as f64);
            score -= 250.0 * (1.0 - progress);
        }
    }

    // Slight preference for keeping the number of open bins in check.
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly prefer bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize large dead space relative to capacity, especially for small post-residuals
    // that are unlikely to be usable later.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 5.0; // tiny unusable slivers are wasted space
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // post-residual cannot fit the next item: mild penalty scaled by how close it was.
        let gap = (next_item_size - post_residual.min(next_item_size)) as f64;
        score += 3.0 * (gap / 50.0).min(1.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // residuals are fragmented (high mean residual spread) or many bins are open.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: waste of full capacity.
        score = bin_capacity as f64 * 0.85;
        // If open bins are mostly full / fragmented, a new bin is more acceptable.
        let frag = mean_residual / bin_capacity as f64;
        score -= 20.0 * frag * frag;
        // More open bins => slight preference to spread load.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
        // Late in the stream, avoid leaving many nearly-empty bins; prefer reuse.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 10.0 * progress;
        // If the next item is large and this bin would be the only low-residual one,
        // opening a new bin preserves flexibility.
        if next_item_size > 60 && mean_residual < 30.0 {
            score -= 6.0;
        }
    }

    // Time-horizon coupling: early in the stream, be greedy about consolidation;
    // later, prioritize minimizing residual variance across bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += progress * (post_residual as f64 - mean_residual).abs() * 0.3;

    // Slight penalty for placing into bins that are much better than average
    // (save the best-fitting residual for harder items).
    if (mean_residual > 0.0) && (bin_residual as f64 > mean_residual * 1.5) && bin_residual != bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog_c = progress * (1.0 - progress) * 4.0; // smooth bump peaking mid-stream

    // Reward tight fits: post_residual near zero is good
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= 2.5 * tightness * tightness * cap * (0.6 + 0.4 * prog_c);

    // Penalize small dead space that is too small for typical items (wasted slivers)
    let pr = post_residual as f64;
    if pr > 0.0 {
        let sliver = (pr / cap).powi(3);
        score += 12.0 * sliver * cap * (1.0 - 0.5 * progress);
    }

    // Lookahead coupling: if next item fits the post residual, reward heavily
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let pair_eff = (item_size + next_item_size) as f64 / cap;
        score -= 6.0 * pair_eff * (1.0 + prog_c);
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty scaled by leftover size
        score += 0.3 * (post_residual as f64) * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + progress);
    }

    // New-bin candidate handling: penalize opening a new bin unless residuals are fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap).powi(2);
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 4.0 + 10.0 * (1.0 - frag) * (1.0 - pressure) - 6.0 * progress * frag;
    } else {
        // Prefer bins below mean residual slightly (balance), smooth coupling
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 1.5 * dev * (1.0 - prog_c);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals near multiples of
    // common item sizes are reusable, others are dead space.
    let harmonic_bases: [u32; 8] = [10, 20, 25, 30, 40, 50, 60, 80];
    let mut harmonic_bonus = 0.0;
    for (i, &b) in harmonic_bases.iter().enumerate() {
        let r = post_residual % b;
        let closeness = (r as f64).min((b - r) as f64) / b as f64;
        harmonic_bonus += closeness / (1.0 + i as f64);
    }
    score -= harmonic_bonus * 6.0;

    // Perfect-fit reward: post_residual exactly zero is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Sub-minimum dead space is nearly unusable.
        score += 25.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a fresh bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // this placement is harmonically perfect.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            let nxt = next_item_size as f64;
            let frac = nxt / bin_capacity as f64;
            // reward leaving room proportional to next item's size class
            score -= frac * 15.0;
        } else {
            // next item won't fit here: penalize tight leftover slightly
            score += 8.0;
        }
    }

    // Prefer fuller bins relative to mean residual of open bins.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Early stream: be frugal with opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax late when bins fragment.
        score += 20.0 - progress * 25.0 + open_bins_count as f64 * 1.5;
    }

    // Integer-division threshold: bins whose residual falls in the
    // "awkward middle band" (just above half capacity) are good targets.
    if post_residual > bin_capacity / 2 && post_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual as f64);
    } else {
        // Usable residual: reward proportional tightness (small usable gaps ok)
        score -= 8.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Perfect / near-perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly favor this bin (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tightness = (next_item_size as f64) / (post_residual as f64);
        if chain_tightness > 0.8 {
            score -= 15.0;
        } else {
            score -= 6.0 * chain_tightness;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Post residual too small for next item: mild penalty if gap is tiny
        if post_residual < 15 {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // consolidating into existing bins; few open bins -> new bins cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin by the mean residual it
    // abandons plus a fixed opening cost.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.3 * mean_residual + 2.0 * (open_bins_count as f64);
    }

    // Mean residual divergence: prefer bins whose residual is below average
    // (fill the emptier-feeling bins first when tight fits are equal).
    score += 0.1 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement is highly desirable.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 500.0;
        } else if slack <= 10.0 {
            score -= 120.0 - 6.0 * slack;
        } else {
            score -= 30.0 / (slack * 0.1 + 1.0);
        }
    }

    // Penalize post-residuals too small to ever fit anything useful
    // (dead space): the smaller the leftover below the minimum item size,
    // the worse the placement.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0 - 8.0 * post_residual as f64;
    }

    // Compare against mean residual: placing into a bin whose residual is
    // far above average wastes the large residual; prefer bins below mean.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit would be terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate (empty bin): penalize it moderately so we prefer
    // reusing open bins, but allow opening a new bin when the fit into any
    // open bin is poor (post_residual very small or next item mismatch).
    if bin_residual == bin_capacity {
        let mut new_bin_score = 100.0 + post_residual as f64;
        if open_bins_count == 0 {
            new_bin_score -= 200.0;
        }
        // If lookahead shows next item pairs badly with this item, opening
        // a fresh bin for the pair becomes attractive.
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            new_bin_score -= 60.0;
        }
        // Late in the stream, consolidate rather than open new bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            new_bin_score += 40.0 * progress;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1), affects risk appetite.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;

    // Reward tight fits: post_residual near 0 is great.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (bin_capacity as f64 * 0.5);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= (1.0 - gap / bin_capacity as f64) * 80.0;
    } else if next_item_size > 0 {
        // Next item cannot use the leftover; penalize proportionally to wasted space.
        score += fit_ratio * 40.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 120.0;
    }

    // Global pressure: many open bins -> prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / bin_capacity as f64);
    score += pressure * 5.0;

    // Mean residual alignment: bins with residual close to mean are "typical"; prefer
    // dumping into bins with large residual (below-mean residual bins are precious).
    if (bin_residual as f64) < mean_residual {
        score -= 25.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score += 10.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive early in the
    // stream or when the leftover space would be dead (too small for anything).
    if is_new_bin {
        // Base cost of opening a bin: increases with progress and open-bin count.
        score += 150.0 + 100.0 * progress + 2.0 * open_bins_count as f64;
        // If the leftover after placement is large and the next item could use it,
        // a fresh bin becomes more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
        // Late in the stream, strongly discourage new bins.
        if progress > 0.8 {
            score += 200.0 * progress;
        }
    }

    // Dead-space penalty: leftover smaller than the smallest plausible item (1..100
    // unknown distribution, so use a conservative small threshold).
    if post_residual > 0 && post_residual < 5 {
        score += 90.0;
    }

    // Mild time-horizon modulation: early stream, be greedy about tight fits;
    // late stream, prioritize not opening bins (already covered) and exact fills.
    score -= (1.0 - progress) * fit_ratio * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tight packing favored via smooth polynomial in post_residual
    let x = post / cap; // normalized post residual in [0,1]
    let mut score = 2.0 * x * x + 0.5 * x;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, tolerate slack; later, penalize dead space more strongly.
    let late_weight = 0.5 + 1.5 * progress * progress;
    score += late_weight * x * x * cap * 0.01;

    // Lookahead: strongly reward if the next item fits into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - (post - nxt) / cap; // snugness of lookahead fit
            score -= 1.2 * snug * snug;
        } else {
            // penalize leaving residual that next item cannot use, scaled by gap
            let gap = (nxt - post) / cap;
            score += 0.6 * gap * gap;
        }
    }

    // Reward using bins that are already open, especially when many are open.
    if bin_residual != bin_capacity {
        score -= 0.3 + 0.02 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize mildly, but relax when few fitting bins
        // or when open bins are on average very full (mean residual small).
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        let crowded = (mean_residual / cap).exp() - 1.0; // smooth growth with slack
        score += 1.5 + 0.5 * scarcity + 0.3 * crowded - 0.4 * progress;
    }

    // Last-chance bin: strongly reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.0;
    }

    // Mild preference for filling bins below mean residual (balancing slack).
    score += 0.1 * (post - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: classify leftover space by capacity fraction bands.
    // Classes: 0 (perfect/zero), small (1..=15), mid (16..=40), large (41..=79), huge (80+)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Base: prefer small post-residuals strongly (tight packing)
    score = pr * (1.0 + 0.8 * frac);

    // Harmonic penalty ladder via integer division thresholds on post_residual
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 4.0;
    } else if post_residual <= 40 {
        score += 6.0;
    } else {
        score += 15.0; // huge dead space
    }

    // Dead-space waste penalty: residual that no plausible item (1..100) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let nxt = next_item_size as f64;
            let fill_ratio = nxt / pr.max(1.0);
            // reward when next item will fill most of the leftover
            score -= 20.0 * fill_ratio * fill_ratio;
            // harmonic class of next-item remainder
            let nxt_rem = post_residual - next_item_size;
            if nxt_rem <= 5 {
                score -= 10.0;
            } else if nxt_rem > 50 {
                score += 8.0;
            }
        } else {
            // next item won't fit here: leftover likely becomes dead space
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins that would be left with harmonically nice residuals
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer filling already-open bins over opening new ones, especially late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, more when many bins open or stream is late.
        score += 40.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
        // But if mean residual across open bins is tiny (all nearly full), new bin is fine.
        if mean_residual < 15.0 && fitting_bins_count == 0 {
            score -= 55.0;
        }
    } else {
        // Mild reward for using existing capacity relative to mean residual.
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        }
    }

    // Modulo harmonic classes on post_residual (mod 10): multiples of 10 are "harmonic"
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 10 >= 7 {
        score += 3.0; // ragged leftover
    }

    // Item-size harmonic classes: large items should go into large-residual bins.
    if item_size >= 50 && bin_residual >= 60 {
        score -= 8.0;
    }
    if item_size <= 20 && post_residual >= 70 {
        score += 5.0; // don't waste a big bin on a tiny item if alternatives exist
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap exactly matching the lookahead item (k=2 synergy).
    if next_item_size > 0 && post_residual > 0 {
        let gap = post_residual as f64;
        let nxt = next_item_size as f64;
        if (gap - nxt).abs() < 1.0 {
            score -= 25.0;
        } else if gap > nxt && gap - nxt < 10.0 {
            // gap slightly larger than next item -> creates small dead space next step
            score += 8.0 * (gap - nxt);
        }
    }

    // Tightness reward: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (fresh empty bin): penalize moderately so it is chosen
    // only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins below mean residual (denser bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Late-stream tightening: as stream progresses, favor fuller bins more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post_residual is prime real estate usage.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits; reward proportional to how snug the chain is
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 - slack.min(100.0);
        } else {
            // next item won't fit here; penalize wasted post_residual relative to next item
            let waste = (next_item_size - post_residual) as f64;
            score += 0.3 * waste;
        }
    }

    // Penalize leaving large dead space relative to mean residual of open bins.
    if (post_residual as f64) > mean_residual + 20.0 {
        score += 0.5 * ((post_residual as f64) - mean_residual - 20.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only open a new bin if all existing fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty keeps new bins as fallback; relax late in the stream or with many bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 120.0;
        penalty -= 80.0 * progress;
        penalty -= (open_bins_count as f64).min(50.0);
        // If next item is large and no residual chain is promising, new bin is more attractive.
        if next_item_size > 0 && next_item_size > item_size {
            penalty -= 30.0;
        }
        score += penalty.max(10.0);
    }

    // Mild preference for filling fuller bins first (small bin_residual means fuller bin).
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (small post-residual is already favored by base term).
    // Reward bins where the lookahead item also fits the post-residual (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, use it aggressively.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize the brand-new empty bin candidate unless the item is large
    // (opening a bin for a big item is fine; wasting a fresh bin on small items is not).
    if bin_residual == bin_capacity {
        let largeness = (item_size as f64) / (bin_capacity as f64);
        score += 25.0 - 40.0 * largeness;
        // Early in the stream, opening bins is cheaper; late, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Prefer bins whose residual deviates from the mean toward being well-used:
    // a bin with residual much larger than mean is underfilled -> favor filling it.
    score -= 0.15 * ((bin_residual as f64) - mean_residual);

    // Mild penalty for leaving awkward dead space (small but nonzero post-residual).
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // With many open bins, favor consolidating into existing bins.
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let w = 1.0 + 0.6 * progress - 0.4 * progress * progress;
    score *= w;

    // Penalize dead space more as stream progresses (smooth cubic coupling)
    let dead = pr_norm * pr_norm * pr_norm;
    score += 30.0 * dead * (0.5 + progress);

    // Reward tight fits: subtract smoothly for small post_residual
    score -= 12.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 + progress);

    // Last-chance bin bonus (smooth, stronger later in stream)
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_frac = next_item_size as f64 / cap;
        score -= 6.0 * fit_frac * (1.0 + progress);
    } else if next_item_size > 0 {
        // penalize post residuals that leave next item stranded
        score += 4.0 * progress;
    }

    // Slight preference for consolidating when many bins are open
    score += 0.3 * (open_bins_count as f64 - mean_residual / cap.max(1.0)).max(0.0) * progress;

    // New-bin candidate: make it mildly unattractive unless residuals are messy
    if bin_residual == bin_capacity {
        score += 5.0 + 15.0 * (1.0 - progress) - 10.0 * (mean_residual / cap).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual (integer division into capacity fractions)
    let post_class = post_residual / 10; // 0..10 classes
    let item_class = item_size / 10;

    // Reward exact or near-exact fits (post_residual in a low harmonic class)
    score -= (10 - post_class as f64) * (10 - post_class as f64) * 0.8;

    // Penalize dead space: residuals that no typical item (<=80) can use well
    if post_residual > 80 {
        score += 25.0;
    } else if post_residual >= 50 {
        score += 8.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect packing
    }

    // Modulo coupling: residual leaving a residue compatible with next item is good
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 40.0; // next item fills bin exactly
        } else if gap > 0 && gap <= 10 {
            score -= 20.0; // near-exact chain
        } else if gap < 0 {
            score += (gap.abs() as f64).min(30.0) * 0.5; // next item won't fit here
        }
        // residue-class match: post_residual % next_item_size small means divisibility harmony
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless current fits are poor
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score += 55.0;
        // worth it if no bin fits or remaining fits are terrible
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // later in the stream, prefer consolidation into existing bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
        // large items start fresh bins more readily
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Slight preference for bins with residuals below mean (tighter bins first)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.05;

    // Mild penalty scaled by item class vs residual class mismatch
    if (post_class as i64 - item_class as i64).abs() > 5 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10) are near-unusable dead space.
    if post_residual < 10 {
        score -= 40.0; // strong reward for near-perfect fills
    } else if post_residual < 20 {
        score -= 12.0;
    } else if post_residual < 30 {
        score -= 3.0;
    }

    // Penalize leaving a gap that just barely misses the next item (wasted potential).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0; // bin remains useful for the lookahead item
    } else if next_item_size > 0 && post_residual > 0 {
        // gap smaller than next item: dead space unless tiny
        score += (post_residual as f64) * 0.5;
    }

    // Reward filling bins that are already quite full (consolidation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: with many open bins, prefer existing bins over new ones.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item is
    // large and no bin fits well. Empty-bin call has bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        // But if item is huge and mean residual is small, opening may be right.
        if item_size as f64 > mean_residual + 20.0 {
            score -= 45.0;
        }
    }

    // Mild stream-progression damping: late in the stream, be slightly more
    // conservative about leaving medium gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.1 * progress;

    // Prefer bins whose residual is close to the mean (balance load).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / tight fit reward: minimize wasted residual relative to item size.
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 40.0 * (-tightness * 2.0).exp();

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (-gap / 15.0).exp();
        // Penalize leaving residual that is too small for the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 + 0.5 * post_residual as f64;
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score += 0.5 * post_residual as f64;
    }

    // Relative-to-mean adjustment: prefer bins already below mean residual
    // (consolidate fragmentation) unless it's a near-perfect fit.
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., this call has large post_residual potential waste elsewhere).
    if bin_residual == bin_capacity {
        // Base penalty: prefer reusing open bins generally.
        score += 20.0;
        // But if many bins are open and mean residual is small (fragmented),
        // opening fresh is less bad; also scale with stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - (open_bins_count as f64 / 10.0).min(1.0)) * (1.0 - progress);
        // If next item is huge, a fresh bin with full residual is valuable.
        if next_item_size >= bin_capacity / 2 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual is already favored by the base term,
    // but amplify non-linearly to strongly prefer near-exact fills.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 20.0;

    // Penalize dead space that cannot fit the next item (wasted residual).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Reward residual that can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + (post_residual - next_item_size) as f64 * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many fitting bins: mild penalty to spread load and keep larger residuals
    // available for future large items.
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 1.5;
    }

    // Progress-based modulation: early in the stream, be conservative with new
    // bins (favor filling existing ones); late in the stream, allow new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = (bin_residual == bin_capacity) as f64;

    if new_bin > 0.0 {
        // Opening a new bin: penalize unless existing bins have poor fits
        // (high mean residual spread or this item is large).
        let early_penalty = (1.0 - progress) * 12.0;
        let big_item_bonus = (item_size as f64 / bin_capacity as f64) * 8.0;
        let crowded = if open_bins_count > 0 { (open_bins_count as f64).ln() * 2.0 } else { 0.0 };
        score += early_penalty - big_item_bonus - crowded;
    } else {
        // Existing bin: small bonus when bin residual is well below mean
        // (i.e., this bin is already tight, keep filling it).
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= diff * 0.15;
        }
    }

    // Exact fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post residual), with non-linear shaping.
    let mut score = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate moderate residuals; late, penalize wasted space quadratically.
    let tightness = pr / cap;
    let w = 0.4 + 1.6 * progress * progress;
    score += w * tightness * tightness;

    // Cubic term: strongly punish near-empty bins created late in the stream.
    let cubic = (tightness - 0.5) * (tightness - 0.5) * (tightness - 0.5);
    score += (0.3 + 1.7 * progress) * cubic;

    // Lookahead coupling: reward leaving room exactly matching the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_err = (pr - nxt) / cap;
        score -= 0.9 * (-match_err * match_err);
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 1.2 + 0.8 * progress;
    }

    // Slight penalty for proliferating bins relative to mean residual.
    score += 0.05 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    // Prefer bins whose residual is near the mean (balanced packing).
    score += 0.1 * ((bin_residual as f64 - mean_residual) / cap).abs();

    // Mild bias toward filling larger items into emptier bins early.
    score -= 0.15 * (item_size as f64 / cap) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity fractions (1/8 granularity) and reward "usable" classes.
    let frac = post_residual as f64 / cap; // 0..1
    let eighth = (frac * 8.0).round() as i32; // 0..8 harmonic class
    // Class 0 = perfect fill; classes 1-3 = small dead space (bad);
    // classes 4-8 = large residual (good, reusable).
    match eighth {
        0 => score -= 60.0,                       // perfect fill -> strong reward
        1 => score += 25.0,                       // near-dead space -> penalize
        2 => score += 10.0,
        3 => score += 0.0,
        _ => score -= 8.0 * (eighth as f64 - 3.0), // larger residuals preferred
    }

    // Modulo arithmetic: residuals that are multiples of common item sizes
    // (or of capacity quarters) are more likely to be exactly filled later.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 4.0; }
        if cap as u32 % pr == 0 && pr > 0 { score -= 5.0; }
        // awkward primes / odd residues are less reusable
        if pr % 7 == 0 && pr % 2 == 1 { score += 3.0; }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            let nf = next_item_size as f64;
            // reward proportional to how well next item fills the leftover
            score -= 15.0 * (nf / (pr as f64 + 1.0));
            // harmonic class of next item relative to capacity quarters
            let nq = ((nf / cap) * 4.0).round() as i32;
            if nq >= 2 { score -= 6.0; } // next item is large -> residual valuable
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible (post_residual very small).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual > 0 {
            score -= 20.0;
        }
        // but if it creates a tiny dead sliver, prefer new bin
        if post_residual < bin_capacity / 20 {
            score += 30.0;
        }
    }

    // New-bin candidate handling: empty bin has fixed residual = capacity.
    // Prefer using an existing bin unless existing fits are all poor.
    if bin_residual == bin_capacity {
        // baseline for fresh bin; slightly worse than a good existing fit
        score += 12.0;
        // early in stream, opening bins is cheaper (more future items to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // many open bins -> discourage opening yet another
        score += 3.0 * open_bins_count as f64;
    }

    // Tightness reward: the fuller the bin becomes, the better.
    let fill = (bin_residual as f64 - post_residual as f64) / cap;
    score -= 30.0 * fill * fill;

    // Mean-residual coupling: placing into a bin whose residual is below mean
    // (i.e., consolidating fuller bins) is preferred.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 5.0 * (res_f - mean_residual) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 10) are unusable for any
    // future item (min size 1, but tiny gaps waste capacity). Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, allow opening new bins more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate (empty bin): baseline is its large post_residual.
    // Give it a moderate bonus so it wins only when all fits are bad,
    // but bias by mean residual: if open bins are already very full,
    // opening fresh space is cheap and natural.
    if bin_residual == bin_capacity {
        score -= 10.0;
        if mean_residual < 15.0 {
            score -= 8.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit signal).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect-ish fits: tiny post residual is very desirable.
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            // Next item fits too: mild reward proportional to leftover after next item.
            let after_next = post_residual - next_item_size;
            score -= 12.0 - (after_next as f64).min(12.0);
        } else {
            // Next item won't fit here: penalize wasted space relative to next item size.
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Penalize deviating from mean residual (prefer bins that keep residuals homogeneous,
    // unless it's a tight fit).
    let dev = post_residual as f64 - mean_residual;
    score += dev.abs() * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item is huge relative to capacity and few bins fit it, opening is fine.
        if item_size * 2 >= bin_capacity && fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Slight preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 18.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Placing here strands the next item: penalize proportionally to waste.
            let stranded = (post_residual as f64) / (bin_capacity as f64);
            score += 25.0 * stranded;
        }
    }

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is large and no bin fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.35 };
        score = bin_capacity as f64 - 70.0 * large_item * pressure;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // large items coming; fresh bin useful
        }
        if open_bins_count > 6 {
            score += 8.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer reusing emptier bins.
    if open_bins_count > 0 {
        let rel = (post_residual as f64 - mean_residual).abs();
        score += 0.15 * rel;
    }

    // Time horizon: early in the stream, be slightly conservative about dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, penalized non-linearly by wasted space
    let mut score = pr as f64 + 30.0 * norm_pr * norm_pr;

    // Stream-progress coupling: late in stream, dead space matters more
    score += 60.0 * progress * norm_pr * (1.0 - norm_pr);

    // Reward leaving room exactly for the lookahead item (smooth bump)
    let look = next_item_size as f64;
    if look > 0.0 {
        let diff = (pr - look) / cap;
        score -= 25.0 * (-8.0 * diff * diff).exp();
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Slight preference for consolidating into bins below mean residual
    score += 0.3 * (pr - mean_residual);

    // New-bin candidate: keep it available unless current fit is poor
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 35.0 - 50.0 * progress * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Dead-space penalty: residuals that are too small to hold typical items are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Perfect fit reward (harmonic class 0).
    if post_residual == 0 {
        score -= 100.0;
    }

    // Classify post residual into harmonic bands of capacity/8.
    let band = (post_residual * 8) / bin_capacity; // 0..=7 integer division
    let band_bonus: f64 = match band {
        0 => -40.0, // nearly full: excellent
        1 => -25.0, // leaves <= 12.5% : good
        2 => -10.0,
        3 => 5.0,
        4 => 10.0,
        5 => 15.0,
        6 => 20.0,
        _ => 8.0,   // nearly empty bin: mild penalty, but a fresh bin may absorb it
    };
    score += band_bonus;

    // Modulo arithmetic on post_residual: residuals divisible by 4 or 8 pair well
    // with item sizes drawn from fine-grained distributions.
    if post_residual % 8 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 4 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            let nf = next_item_size as f64 / post.max(1.0);
            // prefer post residuals close to the next item size (tight chaining)
            score -= 20.0 * (1.0 - (nf - 1.0).abs());
        } else {
            // next item cannot fit here; penalize proportionally to wasted potential
            score += 6.0 * (next_item_size as f64 - post).min(cap) / cap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin starts with high base cost, but is
    // attractive when the current bin would leave a bad residual or many bins exist.
    if bin_residual == bin_capacity {
        score = cap + 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin anyway
        }
        if post_residual >= 0 && fitting_bins_count > 0 {
            // opening a new bin is penalized if an existing bin fits decently
            let best_alternative_waste = (bin_residual - item_size) as f64;
            if best_alternative_waste < 20.0 {
                score += 50.0;
            }
        }
        if next_item_size > 0 && next_item_size as f64 > frac * cap + cap {
            score -= 10.0;
        }
    }

    // Stream progression: early on, be conservative about opening bins; late in
    // the stream, prefer filling existing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    // Mean residual coupling: when open bins have plenty of room on average,
    // discourage spreading items into new bins; encourage using roomy bins.
    if bin_residual != bin_capacity {
        let rel_room = (bin_residual as f64 - mean_residual).max(-cap) / cap;
        score -= 15.0 * rel_room;
    }

    // Penalize excessive bin sprawl mildly.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (<= ~10)
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear penalty for medium-small gaps that only fit tiny items
    if post_residual > 0 && post_residual < 25 {
        score += 25.0 * (25.0 - post_residual as f64) / 25.0;
    }

    // Reward tight fits (post_residual near zero but not penalized dead space)
    if post_residual == 0 {
        score -= 40.0;
    }

    // Perfect fill of the bin: strong reward
    if post_residual == 0 && bin_residual == item_size {
        score -= 60.0;
    }

    // Open bins pressure: discourage spreading across many bins
    score += 0.35 * open_bins_count as f64;

    // Prefer bins whose residual deviates below the mean (more filled bins first)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward leaving a gap that fits the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 15.0; // next item would leave dead space here
        }
    }

    // New-bin candidate handling: only attractive when current fit would waste space
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with stream progress
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 55.0 + 25.0 * progress;

        // If no existing bin fits well (large dead space would result), new bin is better
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // If the item would fit snugly in an existing bin's typical residual, discourage new bin
        if (mean_residual - item_size as f64).abs() < 8.0 && fitting_bins_count > 0 {
            score += 20.0;
        }
        // Early stream: opening bins is fine to build a portfolio
        if progress < 0.2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference for tight fits relative to the mean residual across open bins.
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Aggressive 2-step lookahead: reward when the leftover space exactly (or nearly)
    // matches the next item's size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 6.0 * (1.0 - gap / (bin_capacity as f64));
        // Perfect chain: post_residual == next_item_size -> strong bonus.
        if post_residual == next_item_size {
            score -= 12.0;
        }
        // Penalize leaving a residual that neither fits the next item well nor is tiny.
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize waste strictly.
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        // Prefer new bin when no open bin fits (fitting_bins_count counts open fitting bins).
        if fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            // Penalize opening a new bin if the item would fit tightly somewhere.
            let waste_here = post_residual as f64;
            if waste_here < 20.0 {
                score += 10.0; // item fits tightly in an existing bin -> keep it there
            }
            score += 0.15 * open_bins_count as f64;
        }
    }

    // Dead-space penalty: residuals too small to ever fit typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Early in the stream, slightly favor consolidation into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Reward filling the bin more completely.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill;

    // Lookahead: penalize if the next item cannot fit in the post-residual,
    // reward if it fits snugly (chaining placements).
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 12.0;
        } else {
            let next_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 * (1.0 - next_tight);
        }
    } else {
        // Last item: strongly prefer fullest bin.
        score -= 25.0 * fill;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // or open bins are nearly saturated.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 {
            0.0
        } else {
            open_bins_count as f64 / (fitting_bins_count as f64 + 1.0)
        };
        let mean_tight = 1.0 - (mean_residual / bin_capacity as f64);
        // Cost of a new bin amortized over remaining stream.
        let horizon = 1.0 - (step_index as f64) / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * pressure + 25.0 * mean_tight + 40.0 * horizon;
    }

    // Mild penalty for leaving awkward small residuals that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr_norm = post / cap;

    // Base: quadratic penalty on wasted space (non-linear in post_residual).
    let mut score = pr_norm * pr_norm * cap + 0.5 * post;

    // Smooth cubic coupling of waste with stream progress: late in the
    // stream, dead space becomes progressively more costly.
    score += 8.0 * pr_norm.powi(3) * cap * (0.5 + progress);

    // Lookahead synergy: reward residuals that can host the next item,
    // smoothly scaled by how well next item would fit.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let fit_quality = 1.0 - (post - nxt) / cap;
            score -= 6.0 * fit_quality * (1.0 - progress);
        } else {
            // Smooth penalty when next item cannot follow into this bin.
            let gap = (nxt - post) / cap;
            score += 4.0 * gap * gap * cap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - pr_norm);
    }

    // Mild pressure against hoarding many open bins with large residuals.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);

    // New-bin candidate handling: an empty bin should only win when the
    // current bin would leave a badly fragmented residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin; the penalty decays as the waste
        // from using an existing bin grows (smooth crossover).
        let waste_penalty = (pr_norm * cap / 40.0).powi(2);
        score += 25.0 - waste_penalty.min(20.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low-modulo classes is worse
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual is a "perfect slot" for the next item -> big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // next item cannot use this residual at all -> penalize proportionally
        score += 0.5 * (next_item_size as f64) * (pr / cap);
    }

    // Integer-division thresholds on post_residual: tiny fragments are dead weight
    if post_residual <= bin_capacity / 20 {
        score += 6.0; // unusable sliver
    } else if post_residual <= bin_capacity / 10 {
        score += 2.5;
    } else if post_residual <= bin_capacity / 4 {
        score += 0.5;
    } else if post_residual >= bin_capacity / 2 {
        // keeping large residual is good (bin stays flexible)
        score -= 2.0 * (pr / cap);
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 pair better with
    // typical item sizes
    if post_residual % 10 == 0 {
        score -= 1.0;
    }
    if post_residual % 5 == 0 {
        score -= 0.3;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when current bin would be
    // left with unusable residue or bin count is low
    if bin_residual == bin_capacity {
        // baseline: slightly worse than a good fit, better than a bad one
        score = cap - (item_size as f64);
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative anyway
        } else if fitting_bins_count == 1 {
            score += 15.0; // discourage skipping the last fitting bin
        }
        // early stream: opening bins is cheap/flexible
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 3.0 * (1.0 - progress);
    }

    // Prefer fuller bins overall: closeness of fill to capacity
    let fill = (bin_capacity - bin_residual) as f64;
    score -= 1.5 * (fill / cap);

    // Crowding: many open bins -> prefer consolidating into existing ones
    if open_bins_count > 4 {
        score -= 0.2 * (open_bins_count as f64).ln();
    }

    // Mean-residual coupling: if this bin's residual is below mean, it is
    // relatively full -> reward using it
    if (bin_residual as f64) < mean_residual {
        score -= 1.0;
    } else {
        score += 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 5.0; // gap 1..9 -> +55..+15
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Favor bins whose residual is close to the item (tight fit ratio).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Open-bin pressure: discourage spreading across many bins unless fit is great.
    score += (open_bins_count as f64) * 1.5;

    // If this is the only fitting bin, strongly prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large relative to capacity or no bin fits well.
    if bin_residual == bin_capacity {
        let last_chance = fitting_bins_count == 1; // counts only the new bin itself
        let good_fit_elsewhere = !last_chance;
        if good_fit_elsewhere && post_residual > 20 {
            score += 30.0; // keep using existing bins
        }
        // Prefer a fresh bin if the item would leave a big hole in an existing bin.
        if mean_residual < (item_size as f64) * 1.3 && mean_residual > 0.0 {
            score -= 15.0;
        }
    }

    // Lookahead: if the next item could use the post-residual, reward leaving it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // leftover gap likely wasted
    }

    // Late in the stream, consolidate: avoid opening bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    // Mild preference for bins below mean residual (use the emptier ones first
    // when fits are comparable keeps large residuals for big items).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (zero waste).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the leftover space.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score += diff as f64 * 0.8;
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Penalize leftovers too small for the next item (dead space risk).
        if next_item_size > post_residual && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    } else {
        // Last item: only exact fit matters.
        score += post_residual as f64 * 0.5;
    }

    // Penalize opening a new bin when existing bins fit, unless fit is very poor.
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count <= 1 { 3.0 } else { 1.0 };
        score += 60.0 * urgency;
        // New bin is attractive if no open bin fits well (post_residual small in others).
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: reward using it rather than opening a new bin.
        score -= 35.0;
    }

    // Prefer bins with residuals below mean residual (denser bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild preference for keeping few open bins as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize dead space relative to the smallest plausible item.
    let waste = post_residual as f64;
    score += 0.35 * waste;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Cost of opening a new bin, modulated by how poorly existing bins fit.
        let fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
        let avg_goodness = (mean_residual - item_size as f64).abs();
        let base_cost = 55.0 + 0.5 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let time_penalty = 30.0 * progress;
        // If next item is large, a fresh bin with lots of room is valuable.
        let lookahead_bonus = if next_item_size > 0 && next_item_size > post_residual && !is_new_bin { 0.0 } else { 0.0 };
        score = base_cost * fit_pressure + time_penalty + lookahead_bonus
            - 0.2 * next_item_size as f64 * fit_pressure;
    } else {
        // Lookahead: penalize bins whose post-residual can't hold the next item
        // if the next item is large relative to remaining space.
        if next_item_size > 0 {
            if post_residual as u32 >= next_item_size {
                // This bin stays useful: small reward.
                score -= 3.0;
            } else if post_residual > 0 && (post_residual as f64) < 10.0 {
                // Unusable sliver for the next item: penalty grows with item size.
                score += 0.25 * next_item_size as f64;
            }
        }
        // Slight preference for bins already below average fullness? No:
        // prefer filling fuller bins first (lower residual => lower base score already).
        // Tie-break with mean residual: bins with residual near mean are neutral.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Global load balancing: with many open bins, discourage spreading.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let util = 1.0 - pr / cap;

    // Core: reward high utilization, non-linearly
    let mut score = pr * (1.0 + 0.8 * progress) - 40.0 * util * util;

    // Dead-space penalty grows smoothly with wasted space
    let waste = pr * pr / cap;
    score += 0.15 * waste;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 60.0 + 30.0 * progress;
    }

    // Lookahead: bonus if next item fits the post-residual exactly-ish
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        let gap = pr - next_item_size as f64;
        score -= 25.0 * (1.0 - gap / cap).max(0.0);
    } else if next_item_size > 0 {
        score += 10.0;
    }

    // Late in stream: discourage opening new bins
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        score += 35.0 + 45.0 * progress + 2.0 * open_bins_count as f64;
        // but allow new bin when it would be very full
        score -= 30.0 * util;
    }

    // Mild coupling with mean residual: prefer bins below mean residual (tighter)
    score += 0.05 * (mean_residual - pr).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by capacity fractions.
    let pr = post_residual as f64;
    let quarter = cap / 4.0;
    let half = cap / 2.0;
    let eighth = cap / 8.0;

    // Dead-space penalty: leftovers that no future item (10..80 range assumed, but be
    // conservative for 1..100) can use are pure waste. Very small leftovers are fine
    // (bin nearly full); mid-range leftovers are the danger zone.
    if pr > 0.0 && pr < eighth {
        score -= 12.0; // excellent packing, nearly sealed
    } else if pr >= eighth && pr <= quarter {
        score += 8.0; // awkward sliver: hard to fill later
    } else if pr > quarter && pr < half {
        score += 3.0; // moderately usable
    }

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Integer-division harmonic classes on post_residual:
    // group leftovers into buckets of 10 (classic dual of item granularity).
    let bucket = post_residual / 10;
    match bucket {
        0 => score -= 10.0,           // 0-9 left: sealed
        1 => score += 6.0,            // 10-19: only tiny items fit
        2 => score += 2.0,            // 20-29
        3 | 4 => score -= 1.0,        // 30-49: common item sizes land here
        5 => score += 4.0,            // 50-59: half-empty, wasteful
        _ => {}
    }

    // Lookahead coupling: does next_item_size fit the post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // next item fits here: reward proportionally to how well it nests.
            let nest = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - nest);
            // harmonic bonus when next item exactly consumes a class boundary
            if ((post_residual as u32).wrapping_sub(next_item_size)) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item will need another bin: mild penalty proportional to gap.
            score += 4.0 + (nxt - pr) / cap * 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when this item
    // is large relative to capacity or all existing fits are terrible.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        // Base cost of a fresh bin: high, so it's chosen only when justified.
        score = cap * 0.55 + frac * 20.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // If many bins are open, discourage spreading further.
        score += open_bins_count as f64 * 1.5;
        // If the only alternative is a bad fit (large mean residual with many
        // fitting bins means fragmentation), a new bin becomes cheaper.
        if fitting_bins_count == 1 && mean_residual < 30.0 {
            score -= 20.0;
        }
        if next_item_size > 0 && (next_item_size as f64) <= (cap - item_size as f64) {
            // new bin can also host the next item: pair bonus
            score -= 10.0;
        }
    }

    // Mild pressure to prefer fuller bins among comparable options.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items (<=10) are pure waste; penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Gaps below 20 are usable only by the smallest items; soft penalty.
        score += 18.0;
    }

    // Reward tight fits (exact or near-exact packing).
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Non-linear tightness reward: smaller relative gap gets more reward.
        let tightness = (post_residual as f64 / bin_capacity as f64).powi(2);
        score -= 40.0 * (1.0 - tightness);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new
    // bins and encourage consolidating into existing residual space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many open bins carry slack.
        score += 25.0 + 2.0 * pressure + 15.0 * progress;
    } else {
        score -= 1.5 * pressure.min(10.0);
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // Next item cannot use the gap at all: dead space confirmed.
            score += 10.0;
        }
    }

    // Mild alignment with mean residual: prefer bins with residual near/below
    // the mean (i.e., already well-filled bins) to consolidate fullness.
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Exact match bonus
        if post_residual == next_item_size {
            score -= 50.0;
        }
        // Penalize post_residual slightly larger than next item (dead space chain)
        if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fit anywhere
        score -= 100.0;
    }

    // Reward leaving small post_residual (tight packing) relative to capacity
    let pr = post_residual as f64;
    score += (pr * pr) / (bin_capacity as f64 * 2.0);

    // Compare against mean residual: bins with residual near mean are natural targets
    let dev = (pr - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0
            || (next_item_size > 0
                && fitting_bins_count <= 2
                && post_residual as f64 > mean_residual + 20.0);
        if bad_fit {
            score -= 45.0;
        } else {
            score += 70.0;
        }
    }

    // Mild preference for reusing many-open-bin states to consolidate
    score -= (open_bins_count as f64).sqrt() * 2.0;

    // Slight stream-phase drift: pack tighter later in the stream
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += pr * 0.1 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to item size, the better.
    if post_residual > 0 {
        score -= 12.0 * (item_size as f64 / post_residual as f64).min(3.0);
    } else {
        // Perfect fit is ideal.
        score -= 40.0;
    }

    // Penalize dead space that no future item (sizes >= 1... but realistically >= 10)
    // could ever use; residual < smallest plausible item is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to leftover gap.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item of the stream: just minimize waste.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large (poor fits everywhere) or many bins are open.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        // Penalize new bins when existing bins are mostly empty (early stream).
        score += 20.0 * (1.0 - avg_pressure);
        // Slight preference for consolidating when few bins are open.
        if open_bins_count <= 2 {
            score += 15.0;
        }
        // As the stream progresses, opening fresh bins becomes more acceptable.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
    }

    // Mild global regularization: prefer bins with residuals near the mean
    // to keep the bin population homogeneous.
    score += 0.03 * ((bin_residual as f64 - mean_residual).abs());

    // Tie-breaker: slightly favor fuller bins.
    score -= 0.02 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let it = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: prefer small post-residual (tight fit), normalized
    let mut score = pr;

    // Smooth non-linear tightness reward: quadratic coupling of post_residual with item size
    let tightness = (pr / cap) * (1.0 - pr / cap);
    score -= 12.0 * tightness * (0.5 + it / cap);

    // Reward exact/near-exact fills with smooth exponential decay
    score -= 25.0 * (-pr / 8.0).exp();

    // Next-item lookahead: penalize post_residual that awkwardly fails to host next item
    if nxt > 0.0 {
        let gap = pr - nxt;
        if gap < 0.0 {
            // wasted space relative to lookahead: smooth quadratic penalty
            score += 0.35 * (gap * gap) / cap;
        } else {
            // small positive gap is ideal; smooth reward decaying with gap
            score -= 6.0 * (-gap / 20.0).exp();
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - progress);
    }

    // Stream progress coupling: early on, tolerate loose fits (explore); later, be strict
    let strictness = progress * progress;
    score += strictness * pr * 0.5;

    // New-bin candidate: penalize opening a bin unless residuals are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / cap).clamp(0.0, 1.0)
        } else {
            1.0
        };
        // Opening a bin is attractive when existing mean residual is large but unusable
        score += 30.0 - 25.0 * fragmentation * (1.0 - progress);
        // Late in stream, prefer filling existing bins strongly
        score += 20.0 * progress;
    }

    // Mild penalty when many bins fit the item (less urgency), smooth in fitting_bins_count
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions
    let c = bin_capacity;
    let pr = post_residual as i64;
    let nis = next_item_size as i64;

    // Exact next-item fit lookahead: big reward if next item fits perfectly or well
    if next_item_size > 0 && next_item_size <= post_residual {
        let post2 = post_residual - next_item_size;
        if post2 == 0 {
            score -= 400.0;
        } else if post2 <= c / 10 {
            score -= 150.0;
        } else {
            score -= 40.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this residual: penalize dead space by class
        let class = pr % (c as i64 / 4);
        score += 20.0 + (class as f64) * 3.0;
    }

    // Integer-division thresholds on post_residual (harmonic bands)
    if post_residual > 0 {
        if post_residual <= c / 10 {
            score -= 60.0; // near-full bin: good, low waste
        } else if post_residual <= c / 4 {
            score -= 20.0;
        } else if post_residual <= c / 2 {
            score += 10.0;
        } else if post_residual > (3 * c) / 4 {
            score += 60.0; // leaving bin mostly empty: wasteful
        }
    }

    // Last-chance bin: strongly prefer using it before opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize unless current bin fit is terrible
    if bin_residual == bin_capacity {
        let base = 300.0;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).sqrt() * 10.0;
        // open new bin only if it would leave existing bins with tiny residuals
        let poor_fit_bonus = if bin_residual - item_size <= c / 10 { 0.0 } else { 0.0 };
        let _ = poor_fit_bonus;
        score += base + pressure - 50.0 * (1.0 - progress);
        // if next item is large and current residual small, new bin more attractive
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 30.0;
        }
        // reward opening new bin when many bins have small mean residual (fragmented state)
        if mean_residual < (c as f64) / 4.0 && open_bins_count > 2 {
            score -= 120.0;
        }
    }

    // Coupling with mean residual: prefer bins below mean residual (fill emptier-of-space bins less? prefer tighter bins)
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 15.0;
    } else {
        score += 8.0;
    }

    // Modulo tie-breaking on (post_residual * 7 + item_size) classes to diversify
    let harmonic = (pr * 7 + item_size as i64) % 13;
    score += harmonic as f64 * 0.5;

    // Mild penalty scaled by number of open bins to encourage consolidation
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for the smallest plausible item are worthless.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score -= 60.0; // perfect fill is great
    } else if post_residual <= 25 {
        score += 35.0 * (1.0 - (post_residual as f64 - dead_threshold as f64) / 15.0);
    } else {
        // large residuals are mildly okay (usable space)
        score -= 5.0;
    }

    // Reward tight fits (post_residual close to 0 but not dead).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 45.0;
        } else {
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use leftover: leftover likely becomes dead space
        score += 25.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: with many open bins, avoid opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // New-bin candidate: make it unattractive unless all alternatives are bad.
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 3.0;
        // but if mean residual across open bins is tiny (all bins nearly full),
        // opening a fresh bin becomes reasonable
        score -= mean_residual.min(50.0);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual is close to mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong penalty for dead space: small post_residual is good.
    let post_f = post_residual as f64;
    score -= 0.6 * (cap - post_f) / cap * item_size as f64;

    // 2-step lookahead: exact match of post_residual with next item is a perfect pairing.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (post_f - nx).abs();
        if post_f >= nx {
            // next item fits exactly -> big reward, scaled by tightness
            score -= 25.0 * (1.0 - gap / cap) * (nx / cap);
        } else {
            // next item does NOT fit: penalize leaving a残 gap smaller than next item
            score += 12.0 * (1.0 - post_f / cap);
        }
        // moderate residual near mean is fine; deviation from mean residual penalized slightly
        score += 0.15 * (post_f - mean_residual).abs();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else {
            // discourage opening new bin when existing bins fit, unless post_residual would be tiny dead space
            let waste = post_f.min(next_item_size as f64);
            score += 20.0 - 0.2 * waste;
            if open_bins_count > 0 && post_f < 10.0 {
                score -= 15.0; // a fresh bin with tiny future item is fine
            }
        }
    }

    // Late in stream: prefer closing bins tightly, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * post_f;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small unusable dead space, but tolerate it late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - progress);
    }

    // Last-chance bin: heavy penalty to open a new bin instead of using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += (post_residual as f64).min(next_item_size as f64) * 0.3;
        }
        // Prefer exact pairing: post_residual == next_item_size is ideal.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    }

    // Prefer bins tighter than the fleet average residual.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // New-bin candidate: keep it attractive early, discourage as stream matures.
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - progress) - 10.0 * progress;
        // Don't open a new bin when many bins already fit the item well.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Mild pressure to consolidate into fewer bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let pr = post_residual as f64;
    let pn = pr / cap; // normalized post residual in [0,1]
    let w = 0.5 + 1.5 * progress; // dead space becomes more costly as stream advances
    score += w * 12.0 * pn * pn;          // quadratic penalty on leftover space
    score -= 6.0 * pn * (1.0 - progress); // mild reward for residual early on

    // Non-linear tightness reward: strongly favor near-perfect fits.
    let tightness = 1.0 - pn;
    score -= 10.0 * tightness * tightness * tightness;

    // Lookahead: reward if next item fits into post_residual (smooth coupling).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fits = (pr - ns).max(0.0);
        let fit_quality = 1.0 - fits / cap;
        if ns <= pr {
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            // penalize leaving residual that is just barely too small for next item
            let gap = (ns - pr) / cap;
            score += 5.0 * (1.0 - gap) * (1.0 - gap) * progress;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate: penalize mildly early, more when mean residual is large.
    if bin_residual == bin_capacity {
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score += 25.0 - 15.0 * progress + 20.0 * mean_norm * mean_norm;
        // opening a new bin late in the stream with high mean residual is very bad
        score += 10.0 * progress * mean_norm;
    }

    // Encourage consolidation when many bins are open.
    score += (open_bins_count as f64).sqrt() * pn * 4.0;

    // Small smooth bias toward bins whose residual is close to item size.
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score += 3.0 * diff * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor minimal post_residual.
    let tight = (post_residual as f64) / bin_capacity as f64;
    score += tight * tight * 30.0;

    // Harmonic class of post_residual: small remainders get bonuses.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 10 {
        score -= 25.0;
    } else {
        // dead-space penalty grows with unusable remainder classes
        let class = pr % 10;
        score += (10 - class) as f64 * 0.5;
        if pr < 20 {
            score -= 8.0;
        }
    }

    // Lookahead: bonus if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item can't use this residual: penalize leaving medium dead space
            score += 6.0;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when all open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let best_alt = mean_residual; // average slack elsewhere
        // Prefer new bin when existing residuals are small relative to item
        score = (bin_capacity as f64) - 55.0 * pressure
            - if (best_alt - item_size as f64) < 5.0 { 15.0 } else { 0.0 };
        if fitting_bins_count > 0 {
            score += 20.0; // discourage opening when fits exist
        }
    }

    // Late in stream: consolidate, avoid waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving room for the lookahead item when possible.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Open-bin pressure: prefer existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
    }

    // Mild preference for bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // 2-step lookahead: reward post_residual matching next_item_size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (-diff / 15.0).exp();
        // Penalize post_residual that is too small for the next item (dead space).
        if (post_residual as i64) < (next_item_size as i64) {
            score += 10.0 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Relative to mean residual: prefer bins below-average residual (tighter bins).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it moderately attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        // If next item is huge relative to post-residual space, opening fresh is fine.
        if next_item_size > 0 && (item_size + next_item_size) > bin_capacity {
            score -= 20.0;
        }
    }

    // Late-stream consolidation: prefer reusing existing bins near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later on, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits (small post_residual), stronger as stream progresses.
    let tight_fit = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 55.0 * tight_fit * tight_fit * (0.6 + 0.8 * progress);

    // Penalize dead space: post_residual too small for the smallest possible
    // follow-up item (items >= 1) is pure waste, but tiny slivers are the worst.
    if post_residual > 0 {
        let sliver = (post_residual as f64).ln();
        score += 18.0 * (1.0 - sliver / 100.0f64.ln()).max(0.0);
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Reward leaving room for the next item, scaled by how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill;
        } else {
            // Penalize blocking the next item unless post_residual is nearly zero.
            score += 12.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Many open bins with high mean residual: encourage consolidating into
    // bins that are already partially filled (avoid bin proliferation).
    if open_bins_count > 2 {
        let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln();
        score -= 8.0 * consolidation;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize it, but relax the penalty when the
    // item would leave a large usable residual (good for future items) or
    // when open bins are nearly full.
    if bin_residual == bin_capacity {
        let openness = post_residual as f64 / bin_capacity as f64;
        let crowded = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 45.0 - 20.0 * openness - 10.0 * crowded.min(3.0);
        // If this bin is the only fitting option, allow opening a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    } else {
        // Mild preference for fuller bins (best-fit bias) beyond raw residual.
        score += 0.35 * (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let tightness = 1.0 - norm_pr * norm_pr; // favors small post residuals
    score -= 30.0 * tightness * (0.3 + 0.7 * progress);

    // Penalize large dead space quadratically as stream nears end
    score += 25.0 * norm_pr * norm_pr * norm_pr * progress;

    // Last-chance bonus: smooth sigmoid-like term on fitting_bins_count
    let last_chance = 1.0 / (1.0 + (fitting_bins_count.saturating_sub(1)) as f64);
    score -= 20.0 * last_chance * (1.0 - progress * 0.5);

    // Lookahead coupling: reward residual that can fit next item, smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = if pr >= nxt { 1.0 - (pr - nxt) / cap } else { 0.0 };
        score -= 15.0 * fits_next * fits_next;
    }

    // Mild penalty for proliferation of open bins late in the stream
    score += (open_bins_count as f64).ln() * (1.0 + progress) * 2.0;

    // Deviation from mean residual: prefer bins near the mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits are the best class.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Dead-space penalty grows when the leftover is a "bad class":
        // small nonzero leftovers that cannot host the next item.
        let fits_next = next_item_size > 0 && post_residual >= next_item_size;
        if !fits_next {
            // modulo-class penalty: leftovers in (0..10) are nearly worthless
            let cls = post_residual % 10;
            score += (10 - cls) as f64 * 1.5;
            // small absolute leftovers are dead space
            if post_residual < 10 {
                score += 25.0;
            } else if post_residual < 20 {
                score += 12.0;
            }
        } else {
            // leftover can host the lookahead item: reward by how snugly it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Integer-division threshold classes on post_residual vs capacity quarters
    let quarter = bin_capacity / 4;
    let q_class = post_residual / quarter;
    score += match q_class {
        0 => 6.0,   // tiny leftover: bad class
        1 => 2.0,
        2 => 0.0,
        3 => -2.0,
        _ => -4.0,  // large leftover: flexible bin
    };

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    // Crowding pressure: with many fitting bins, mild penalty to spread via tightness instead
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate: penalize opening fresh bins unless stream is early
    // or the item would leave an awkward class in every open bin.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 - 10.0 * progress;
        if next_item_size > 0 && post_residual < next_item_size {
            score += 5.0; // new bin at least pairs with lookahead poorly too
        }
    }

    // Mild alignment with mean residual: prefer bins whose residual deviates
    // from the mean in the "harmonically tight" direction.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits relative to residual (waste ratio).
    if bin_residual > 0 {
        score += 0.8 * (item_size as f64 / bin_residual as f64) * (bin_capacity as f64 - item_size as f64) * 0.1;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, discourage spreading; encourage closing gaps.
    let open_pressure = open_bins_count as f64 / 10.0;
    score += open_pressure * post_residual as f64 * 0.05;

    // New-bin candidate: baseline score so it's chosen only when all open bins are bad fits.
    if bin_residual == bin_capacity {
        score = 60.0 + post_residual as f64;
        // Late in the stream, opening new bins is cheaper than leaving many open bins.
        if step_index as f64 / total_items.max(1) as f64 > 0.8 {
            score -= 10.0;
        }
        if fitting_bins_count == 1 {
            score += 30.0; // don't open new bin when a last-chance bin exists
        }
    }

    // Lookahead: if next item could use the post residual, reward leaving that exact space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins) to consolidate.
    score += 0.3 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
