            score -= 25.0; // perfect chain: bin becomes exactly filled by next item
        } else if post_residual >= next_item_size {
            // next item fits; reward proportional to how tight the chain is
            let chain_tightness = next_item_size as f64 / post_residual as f64;
            score -= chain_tightness * 10.0;
        } else {
            // next item does NOT fit in this bin's residual: penalize wasted space
            // especially if post_residual is a small dead fragment
            if post_residual < 10 {
                score += 15.0;
            } else {
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    } else {
        // Last item: strongly prefer filling bins as fully as possible
        score -= (1.0 - fit_ratio) * 20.0;
    }

    // Compare residual against mean residual across open bins:
    // prefer bins with below-average residual (already tight bins).
    let mean_gap = mean_residual - post_residual as f64;
    score += mean_gap * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate logic: an empty bin has residual == capacity.
    // Penalize opening a new bin when decent existing fits exist,
    // but allow it when the item would leave a large dead fragment elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
        // If few fitting bins exist, opening a new bin is less costly
        if fitting_bins_count == 0 {
            score -= 35.0;
        } else if fitting_bins_count == 1 {
            score += 5.0;
        }
        // Late in the stream, prefer consolidating into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // Large items starting a fresh bin is fine (they'll fill it)
        if item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mild penalty for very small unusable post-residuals (dead space)
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    // Slight preference to spread across bins when many bins are open
    // (keeps residuals balanced, enabling future perfect matches)
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Dead space penalty: small post_residual that cannot fit the next item is waste.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Lookahead bonus: next item can chain into this bin.
            let chain = (next_item_size as f64) / (post_residual as f64);
            score -= 10.0 * chain;
        } else {
            // Dead space relative to the lookahead item.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.25 * waste;
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count == 0) as i32 as f64;
        let big_item = (item_size as f64) / (bin_capacity as f64);
        // Penalize new bin mildly; discount when item is large or no alternatives.
        score += 55.0 - 40.0 * big_item - 45.0 * scarcity;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Global fragmentation pressure: many open bins with high mean residual -> prefer reusing.
    if open_bins_count > 0 {
        let frag = mean_residual / (bin_capacity as f64);
        score -= 6.0 * frag * ((open_bins_count as f64).ln() + 1.0);
    }

    // Time horizon: early in the stream, be conservative (penalize near-full bins);
    // late in the stream, allow aggressive packing into leftovers.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 8.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * t * tightness;

    // Mild penalty for very small items occupying large residuals.
    let ratio = (item_size as f64) / (bin_residual as f64);
    if ratio < 0.3 {
        score += 6.0 * (0.3 - ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), with non-linear sharpening
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * (1.0 - progress));

    // Smooth polynomial coupling with stream progress: tighten packing as stream advances
    score += 0.35 * norm_pr * norm_pr * progress;

    // Reward using the bin when it's the last chance to fit
    if fitting_bins_count == 1 {
        score -= 2.5 + 1.5 * progress;
    }

    // Penalize crowded bin sets slightly less as progress grows (keep bins closed)
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Coupling with mean residual: prefer bins below mean residual (tighter than average)
    let mean_norm = mean_residual / cap;
    score += 0.4 * (norm_pr - mean_norm) * (1.0 + progress);

    // Lookahead: bonus if next item fits into post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 0.6 * (next_item_size as f64 / cap) * (1.0 - 0.5 * progress);
    } else if next_item_size > 0 {
        // mild penalty for dead space that next item cannot use
        score += 0.3 * (pr - (pr % next_item_size.max(1) as f64)) / cap;
    }

    // New-bin candidate: neutral-ish baseline so it wins only when fits are poor
    if bin_residual == bin_capacity {
        score = 1.2 + 0.8 * (1.0 - progress) + 0.02 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction does it land in?
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Reward near-perfect fits heavily (dead space minimization).
    if post == 0 {
        score -= 60.0;
    } else if post <= eighth {
        score -= 25.0;
    } else if post <= quarter {
        score -= 10.0;
    } else if post > bin_capacity / 2 {
        // Very roomy bin left: mild penalty for wasting a large residual on this item
        score += 8.0;
    }

    // Modulo-based harmonic classes of post_residual: small "granular" leftovers
    // (multiples of 10) pair well with typical item sizes, reward them.
    let class = post % 10;
    if class == 0 {
        score -= 6.0;
    } else if class <= 3 {
        score -= 2.0;
    } else if class >= 7 {
        score += 2.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 40.0;
        } else if next_item_size <= post {
            // Next item fits: leftover after that predicts chain quality.
            let chain_left = post - next_item_size;
            if chain_left <= eighth {
                score -= 12.0;
            } else if chain_left > bin_capacity / 2 {
                score += 4.0;
            }
        } else {
            // Next item will NOT fit here: penalize less if post is tiny anyway,
            // penalize more if we squandered a useful residual.
            if post >= quarter {
                score += 10.0;
            } else {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad
    // or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 30.0;
        // Large items benefit from a fresh bin (no fragmentation constraints).
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
        // If many open bins already, discourage opening yet another unless necessary.
        score += (open_bins_count as f64) * 1.5;
        // Early in stream, opening bins is cheaper (long horizon to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
        // If next item is huge, a fresh bin may serve it better later.
        if next_item_size >= bin_capacity / 2 {
            score += 5.0;
        }
    } else {
        // Existing bin: mild bonus for keeping bins consolidated when many are open.
        if open_bins_count > 4 {
            score -= 2.0;
        }
        // Prefer bins whose residual is close to the mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Small tie-breaker: tighter fit (smaller post residual) always preferred.
    score += post as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Dead space is worse if it cannot host the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size as f64 {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize opening new bins), scaled by stream progression.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).sqrt() * (1.0 + progress);
    if bin_residual == bin_capacity {
        score += 25.0 + 10.0 * pressure;
    } else {
        score -= 2.0 * pressure.min(15.0);
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with residuals below the mean (tighter bins get used first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Mild preference for exact-tight fits relative to item size.
    score -= (item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-match bonus: next item fits with small leftover
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 / (1.0 + slack);
    } else if next_item_size > 0 {
        // Next item won't fit here after placement; penalize proportionally
        let gap = (next_item_size - post_residual) as f64;
        score += 0.5 * gap;
    }

    // Tight fit reward relative to bin capacity
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 50.0 * tightness * tightness;

    // Reward bins whose residual is below mean (compact bins), penalize wasteful ones
    score += 0.3 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Mild preference to keep number of open bins low
    score += 0.5 * open_bins_count as f64;

    // Slight early-stream bias toward filling existing bins aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * (1.0 - progress);

    // Penalize the new-bin candidate unless existing fits are poor
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 60.0;
        if poor_fit {
            score -= 150.0; // open a new bin rather than waste space
        } else {
            score += 250.0; // discourage needless bin opening
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit signal: reward tight fits nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small to hold typical items.
    let horizon = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + 15.0 * (1.0 - horizon);
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else if post_residual > 0 {
