        }
        // Bonus if next item fits perfectly (chained packing).
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: make empty bin attractive only when fits are poor.
    if bin_residual == bin_capacity {
        // Baseline penalty so a decent fit in an open bin wins.
        score = bin_capacity as f64 * 0.55 + 0.3 * mean_residual;
        // If current bin can't even be considered (handled by caller), keep moderate.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 8.0; // big items coming: fresh bin is valuable
        }
        if open_bins_count as f64 * mean_residual > bin_capacity as f64 {
            score -= 6.0; // lots of scattered residual space: consolidate instead
        }
    }

    // Mild pressure to prefer bins with below-mean residual (consolidate space).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Slight time decay: late in the stream, tighten fits even more.
    score -= 4.0 * horizon * fit_ratio;

    // Tie-break toward fewer open bins.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = (pr / cap).clamp(0.0, 1.0); // normalized post residual

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, larger residuals are acceptable; late in the stream, dead space is penalized more.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * (x * x * cap) * 0.35;

    // Smooth bonus for tight fits (small post residual), scaled by progress
    let tightness = 1.0 - x;
    score -= tightness * tightness * (10.0 + 15.0 * progress);

    // Penalize creating residual that is small but nonzero (dead space) via smooth cubic
    if x > 0.0 {
        let dead = (1.0 - x) * x * x; // peaks at small x
        score += dead * 12.0;
    }

    // Lookahead coupling: reward residual that can fit next item, smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = ((pr - nx) / cap).clamp(0.0, 1.0);
        let usable = if pr >= nx { 1.0 } else { 0.0 };
        score -= usable * (1.0 - fits_next) * 8.0 * (1.0 - progress * 0.5);
        // penalize wasting a bin that could have fit next item exactly
        let gap = (pr - nx).abs();
        score += (gap / cap) * 3.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Crowd penalty: with many open bins, prefer consolidating into existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Mean residual coupling: prefer bins whose post residual stays near the mean (balance)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 6.0;

    // New-bin candidate handling: empty bin gets a moderate baseline so it only wins
    // when open bins score poorly (large dead space would result)
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bucket residuals by capacity fraction.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // residual fraction after placement

    // Integer-division thresholds on post_residual (harmonic classes of 25).
    let class = post_residual / 25; // 0..=4
    match class {
        0 => score -= 40.0,                 // near-perfect fit: reward strongly
        1 => score -= 12.0,                 // good fit
        2 => score += 0.0,                  // neutral (residual 50..74)
        3 => score += 10.0,                 // awkward residual
        _ => score += 25.0,                 // nearly empty bin used wastefully
    }

    // Modulo arithmetic: residuals divisible into small harmonics are dead space.
    if post_residual > 0 {
        for m in [5u32, 10, 20, 25, 50].iter() {
            if post_residual % m == 0 {
                score -= 4.0; // residual reusable by common item sizes
            }
        }
    } else {
        score -= 100.0; // exact fill: best possible
    }

    // Dead-space penalty: residual too small for the smallest plausible item (1..100 unknown,
    // assume >=10-ish typical) but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: does post_residual fit next_item_size?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + (next_item_size as f64).sqrt();
        } else {
            score += 6.0; // bin useless for lookahead item
        }
        // Harmonic match: next item exactly fills remaining space
        if next_item_size == post_residual {
            score -= 35.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a moderate prior so it wins only
    // when all open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 45.0 + 0.05 * open_bins_count as f64;
    }

    // Progression-aware tightness: as stream advances, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    // Mean residual context: prefer bins below mean residual (tighter bins).
    score += 0.2 * ((post_residual as f64) - mean_residual);

    // Slight preference for bins with residual close to item size (tight fit envelope).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

