    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: discourage spreading across many bins when few bins fit the item
    if fitting_bins_count <= 2 {
        score -= 10.0; // last-chance bins are valuable, prefer using them
    } else {
        score += 0.3 * open_bins_count as f64;
    }

    // Dead-space coupling with mean residual: penalize bins far below mean residual
    // (those are the emptiest bins; using them keeps fragmentation concentrated)
    let dev = mean_residual - post;
    score += 0.05 * dev.abs();

    // Lookahead: if the next item fits exactly in post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
