    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // next item cannot use the gap -> dead space confirmed
        score += 6.0;
    }

    // New-bin candidate handling: an empty bin has high base score so it is only
    // chosen when open bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
