    score -= 30.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Penalize deviation from mean residual (prefer balanced usage).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-high so it's chosen
    // only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.2 * item_size as f64;
        if next_item_size > 0 && item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 30.0; // large item: fresh bin is fine
        }
    }

    // Late in the stream, consolidate: favor filling existing bins harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is a perfect chain; reward it heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item cannot follow here; slight penalty scaled by slack.
            score += 5.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Global state: when many bins are open, discourage opening new bins
    // (penalize the new-bin candidate via its full residual).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins and mean residual.
        score += 25.0 + 2.0 * open_bins_count as f64 + 0.3 * mean_residual;
        // But late in the stream, with few fitting bins, a fresh bin is fine.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        score -= 10.0 * progress;
    }

    // Prefer bins whose residual is below the mean residual (more congested bins),
    // keeping larger residuals available for larger future items.
    if bin_residual as f64 > mean_residual {
        score += 8.0;
    }

    // Mild time-horizon modulation: early in stream, be more tolerant of slack;
    // late in stream, tighten packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: tightness of fit, normalized
    let mut score = post / cap;

    // Smooth polynomial coupling: tight fits (small post_residual) are increasingly
    // rewarded as the stream progresses, using a non-linear interaction term.
    let tightness = 1.0 - post / cap;
    score -= 0.8 * tightness * tightness * (0.5 + progress);

    // Penalize dead space non-linearly: residuals too small to be useful later
    let dead = if post < 10.0 { (10.0 - post) / 10.0 } else { 0.0 };
    score += 0.5 * dead * dead;

    // Last-chance bonus: strongly favor the only bin that fits, more so late in stream
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.5 * (1.0 + progress);
    }

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score += 0.3 * gap / cap;
        score -= 0.6 * (1.0 - gap / cap).max(0.0) * (0.3 + progress);
    }

    // Mild pressure toward consolidating into existing bins vs opening new ones
    score += 0.05 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // New-bin candidate: penalize slightly unless current residuals are fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap - 0.5).abs();
        score += 0.4 - 0.6 * frag * frag;
    }

    // Mean-residual deviation coupling (smooth quadratic)
    score += 0.2 * (post - mean_residual) / cap * (post - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic classes: classify post_residual by integer division into capacity fractions
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Dead-space penalty grows superlinearly for tiny residuals in awkward classes
    if post_residual > 0 && post_residual < eighth {
        score += (eighth - post_residual) as f64 * 2.5;
    } else if post_residual >= eighth && post_residual < quarter {
        score += 1.5;
    }

    // Reward near-perfect fits (residual in tiny classes)
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 4 {
        score -= 25.0;
    }

    // Lookahead coupling: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 6.0; // next item won't fit here anyway
        } else {
            // reward residual that matches next item size class (modulo-friendly)
            let gap = post_residual - next_item_size;
            if gap <= 4 {
                score -= 12.0;
            } else {
                score += gap as f64 * 0.3;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless item is huge or perfect fit
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        if frac > 0.85 {
            score -= 30.0; // big item: fresh bin is fine
        } else if fitting_bins_count > 0 {
            score += 25.0; // prefer existing bins for small/medium items
        }
    }

    // Slight preference for fuller bins overall (low residual relative to mean)
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Stream progression: early on, be more conservative about fragmenting bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Dead space that can't fit a typical small item (1..=10 range worst case).
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving space for the next item, penalize wasting
    // a big residual on an item when the next item is large.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
        if bin_residual >= item_size + next_item_size {
            score -= 10.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and encourage filling existing ones tightly.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open-bin pressure,
        // but allow it when this bin would otherwise be a tight dead fit.
        score += 15.0 + 10.0 * pressure;
        if post_residual < 10 && post_residual > 0 {
            score -= 20.0;
        }
    } else {
        // Slight reward for packing into existing bins when many are open.
        score -= 2.0 * pressure;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += 0.05 * tightness * tightness / bin_capacity as f64;

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64);

    // Deviation from mean residual: prefer bins already below-average residual
    // (filling the emptiest bins keeps others available for large items).
    score += 0.3 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fills
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness of fit relative to capacity
        let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 200.0 * tight * tight;
    }

    // 2-step lookahead: exact match of next item into post_residual is ideal
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let leftover2 = post_residual - next_item_size;
            // Reward a good second fit, penalize dead space after it
            score -= 150.0 * (1.0 - leftover2 as f64 / bin_capacity as f64);
            if leftover2 == 0 {
                score -= 300.0;
            }
        } else {
            // Next item cannot fit here; mild penalty growing with overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.5 * over;
        }
    }

    // Compare against mean residual: favor bins tighter than average
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Penalize creating tiny unusable residuals (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }

    // Late in stream: prefer closing bins tightly rather than opening new ones
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 50.0 * progress * (post_residual == 0) as i32 as f64;
    score += 30.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    // Mild penalty when many bins are open: encourage consolidation
    score += 2.0 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary tightness term: nonlinear reward for small post residual.
    let cap = bin_capacity as f64;
    let fill_ratio = 1.0 - (post_residual as f64) / cap;
    score -= 60.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: reward if the next item fits into post_residual (chaining),
    // penalize if post_residual is a dead sliver the next item can't use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 12.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else {
            let waste = post_residual as f64;
            if waste < 10.0 {
                score += 8.0; // dead sliver
            } else {
                score += 4.0 * (waste / cap);
            }
        }
    }

    // Last-fitting-bin pressure: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be pickier about waste (many items left
    // to fill residual); late in the stream, accept mediocre fits to avoid
    // opening near-empty bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill_ratio;

    // Global state coupling: many open bins with high mean residual suggests
    // fragmentation -> prefer consolidating into bins below mean residual.
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 6.0 * dev;
    }

    // New empty bin candidate: neutral-ish baseline; only wins when open bins
    // offer poor fits. Scaled by how fragmented the current state is.
    if bin_residual == bin_capacity && bin_capacity == cap as u32 {
        score = cap * 0.75 + 5.0 * (open_bins_count as f64).sqrt() - 10.0 * (1.0 - fill_ratio);
        if fitting_bins_count == 1 {
            score += 30.0; // never open new bin when a sole fitting bin exists
        }
        if next_item_size > 0 && (next_item_size as u32) <= bin_residual {
            score -= 5.0 * progress; // late stream: fresh bin can still chain
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth polynomial decay
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Progress coupling: later in stream, penalize larger residuals more strongly
    let progress_term = 40.0 * progress * norm_pr * norm_pr;
    score += progress_term;

    // Tight fit reward (quadratic in fill ratio)
    let fill = 1.0 - norm_pr;
    score -= 30.0 * fill * fill;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual exactly-ish, reward
    if next_item_size > 0 {
        let nd = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 15.0 * (1.0 - nd / cap).max(0.0) * (1.0 - nd / cap);
    }

    // Penalize deviating from mean residual (avoid fragmented outliers)
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish score scaled by progress
    if bin_residual == bin_capacity {
        score = 60.0 + 40.0 * progress - 10.0 * (1.0 - (open_bins_count as f64 / (open_bins_count as f64 + 5.0)));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: partition post_residual into residue classes mod 10.
    // Residuals that are "useful" for typical item sizes (multiples of 10) get rewarded.
    let pr = post_residual;
    let class = (pr % 10) as f64;
    // Penalize awkward leftover (class != 0) proportionally to how much it wastes.
    score += class * 0.9;

    // Harmonic tiers of post_residual: which item sizes could still fit (10..80 grid)?
    let mut usable_slots = 0u32;
    let mut s = 10u32;
    while s <= 80 {
        if s <= pr { usable_slots += 1; }
        s += 10;
    }
    // Reward bins that remain able to host future items; dead bins get penalized.
    score -= (usable_slots as f64) * 2.5;

    // Integer-division threshold: exact-fill is perfect.
    if pr == 0 {
        score -= 1000.0;
    }

    // Lookahead coupling: does next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Great: bin stays useful for the known next item.
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 + slack * 0.05;
        } else {
            // Next item won't fit here; residual is likely stranded.
            score += (next_item_size - pr) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // barely fits anywhere else or all open bins would be badly fragmented.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin.
        score += 30.0 + (open_bins_count as f64) * 1.5;
        // Late in the stream, opening new bins is less costly (fewer future items).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 12.0;
        // If other fitting bins exist but are all fragmented (high mean residual
        // relative to capacity), opening a fresh bin is more attractive.
        if mean_residual > bin_capacity as f64 * 0.5 {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose fill ratio is already high (best-fit flavor),
        // scaled by harmonic tier of residual.
        let tier = (pr / 10) as f64;
        score += tier * 1.2;
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (min size 1) are pure waste,
    // and small residuals that only fit tiny items are nearly dead.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual as f64) * 4.0;
    } else if (post_residual as f64) < 25.0 {
        score += 20.0;
    }

    // Reward tight fits (exact or near-exact fill).
    if post_residual == 0 {
        score -= 80.0;
    } else if (post_residual as f64) <= 5.0 {
        score -= 40.0;
    }

    // Reward fitting next item exactly into the post-residual gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 70.0;
        } else if (gap as f64) < dead_threshold {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // next item cannot use this residual: residual is likely dead weight
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bins pressure: with many open bins, avoid opening another.
    if bin_residual == bin_capacity {
        // New-bin candidate score: baseline cost of a fresh bin.
        let mut new_bin_score = bin_capacity as f64 - 30.0
            + (open_bins_count as f64) * 2.0;
        // Late in the stream, prefer closing out existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += progress * 20.0;
        // If existing bins fit poorly (large post_residual elsewhere), new bin is fine.
        // If this bin is the only fitting one, opening new is bad.
        if fitting_bins_count == 1 {
            new_bin_score += 80.0;
        }
        score = new_bin_score;
    } else {
        // Mild penalty proportional to how much of the bin is left unused relative to mean residual.
        score += ((mean_residual - post_residual as f64).abs()) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward closing the bin exactly.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Penalize small dead space that likely can't be reused (items >= 1).
        let waste = post_residual as f64;
        if waste < 10.0 {
            score += 60.0 * (10.0 - waste);
        }
        // 2-step lookahead: reward if next item fits exactly or well into post_residual.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if post_residual as f64 >= nxt {
                let next_gap = post_residual as f64 - nxt;
                if next_gap == 0.0 {
                    score -= 450.0;
                } else if next_gap < 10.0 {
                    score -= 200.0 - 10.0 * next_gap;
                } else {
                    score -= 40.0;
                }
            } else {
                // Next item cannot follow here: penalize proportionally to the gap.
                score += 0.5 * (nxt - post_residual as f64);
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when it enables a large lookahead fit
    // (fresh capacity 100 can host item + next item comfortably).
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (item_size + next_item_size) as f64 <= bin_capacity as f64 {
            let slack = bin_capacity as f64 - (item_size + next_item_size) as f64;
            score -= 80.0 - 2.0 * slack;
        } else {
            score += 150.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 100.0 * progress;
    }

    // Slight preference to spread load when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Dead space penalty: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 5 {
        score += 12.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward if next item fits exactly in post residual (chaining),
    // penalize if next item can't use the leftover.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins are crowded (low mean residual) or many bins already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let crowd = mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early stream with roomy bins: discourage new bins.
        score += 30.0 - 25.0 * (1.0 - crowd) - 10.0 * progress;
        // If no bin currently fits, new bin becomes the natural choice.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Lookahead: fresh bin will hold item + next item nicely.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    // Base: prefer small post-residual (tight fits)
    let mut score = post;

    // Smooth non-linear waste penalty: dead space hurts more as it approaches mid-range
    let waste_curve = norm_post * (1.0 - norm_post) * 4.0; // peaks at 0.5
    score += waste_curve * cap * 0.35;

    // Stream-progress coupling: later in the stream, tolerate larger residuals less
    score += (norm_post * norm_post) * cap * (0.15 + 0.55 * t * t);

    // New-bin candidate penalty: opening a bin wastes capacity unless it's a good idea
    let open_pressure = (open_bins_count as f64 + 1.0).ln();
    score += is_new_bin * (cap * (0.6 + 0.4 * t) + open_pressure * 8.0);

    // Reward scarce fitting options (last-chance bin)
    if fitting_bins_count == 1 && is_new_bin == 0.0 {
        score -= cap * 0.45;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 3.0;
    }

    // Lookahead coupling: if next item fits exactly in the resulting residual, reward strongly
    if next_item_size > 0 {
        let diff = (post - next_item_size as f64).abs();
        score -= (1.0 - diff / cap).max(0.0) * cap * 0.3;
        // If next item cannot fit, mild penalty proportional to residual
        if post < next_item_size as f64 {
            score += 5.0;
        }
    }

    // Mean-residual alignment: prefer bins whose residual is near the mean (keeps bin population homogeneous)
    score += (post - mean_residual).abs() * 0.1;

    // Item-size interaction: large items should prefer very tight fits
    let large = (item_size as f64 / cap).powi(2);
    score += large * post * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic classes: classify post_residual into residue classes mod 10 and integer-division bands
    let class = post_residual % 10;
    let band = post_residual / 10; // 0..10

    // Dead-space penalty: residuals too small for typical items are waste
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // unusable dead space
        } else if post_residual < 20 {
            score += 12.0;
        } else if post_residual < 30 {
            score += 4.0;
        }
    }

    // Reward residual classes that pair well with common item sizes (multiples of 10, 25, 50)
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual % 25 == 0 {
        score -= 18.0;
    } else if post_residual % 10 == 0 {
        score -= 10.0;
    } else if class == 5 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size as u32) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use this residual; penalize tight-ish residuals less if band is deep
            score += 0.5 * (10 - band.min(10)) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score = cap - post; // = 0 baseline
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 20.0 * progress; // prefer existing bins early
        if next_item_size > 0 && (next_item_size as u32) > bin_residual {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a bin
        } else if mean_residual > item_size as f64 * 1.5 {
            score += 15.0; // existing bins have room; don't open new
        }
    }

    // Mild tightness reward proportional to fill ratio
    score -= 20.0 * (item_size as f64 / cap) * (bin_residual as f64 / cap);

    // Slight preference for bins below mean residual (consolidating fuller bins)
    score += 0.15 * (mean_residual - bin_residual as f64).max(-30.0).min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps that no item (min size 1, but
    // typically >= 10) can ever use are wasted capacity. Penalize hard when
    // post_residual falls into an unusable dead zone.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // gap smaller than any typical item: pure dead space
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0; // gap can't host the lookahead item: likely dead
        } else {
            // Usable gap: reward proportionally to how reusable it is
            score -= 8.0;
        }
    } else {
        // Perfect fit: strongly reward closing the bin exactly
        score -= 40.0;
    }

    // Exact-fit flavor: residual matches a common small-item size
    if post_residual == 10 || post_residual == 20 || post_residual == 25 || post_residual == 50 {
        score -= 12.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins; when few bins are open, tolerate spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += pressure * (1.0 + 2.0 * progress);

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bin
    // would leave a dead gap and the new bin offers a clean full capacity.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if placing here would create dead space in existing bins anyway,
        // a fresh bin becomes relatively attractive.
        if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(6) * 30.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0; // perfect chain: bin completely filled by next item
        } else if next_item_size < post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= (1.0 - chain_waste / bin_capacity as f64).powi(4) * 25.0;
        } else {
            // next item cannot fit here: mild penalty for tight fits that strand space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual above the mean (absorb waste there).
    let dev = post_residual as f64 - mean_residual;
    score += dev * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item is large
    // and no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 60.0; // base cost of a fresh bin
        if item_size >= 60 && next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 90.0; // pack a big item plus its chain together in a fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 70.0; // no alternative: new bin is fine
        }
    }

    // Late-stream tightening: as the stream progresses, avoid leaving dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += fit_ratio * progress * 20.0;

    // Many open bins: prefer consolidating into existing ones.
    score += open_bins_count as f64 * 0.5 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items
    // (post_residual in the awkward 1..30 range is wasted space).
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 1.5;
    }

    // Lookahead: if the next item fits into the post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.3 * next_item_size as f64;
        } else {
            // Next item won't fit here; mild penalty scaled by overflow.
            let overflow = next_item_size as f64 - post_residual as f64;
            score += 0.15 * overflow;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Time horizon: early in the stream, prefer consolidating into open bins
    // (avoid opening many bins); later, allow more freedom.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let openness = 1.0 - 0.5 * t;

    // Penalize choosing a new empty bin early unless the fit is terrible elsewhere.
    if bin_residual == bin_capacity {
        score += 80.0 * openness;
        // But if the item is large relative to mean residual, opening a new bin
        // may be better; relax the penalty.
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 45.0;
        }
    } else {
        // Slight reward for using bins with large residuals when many bins are open.
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Many open bins: encourage filling existing ones to allow closing them.
    if open_bins_count > 8 {
        score -= 0.5 * open_bins_count as f64 * fit_ratio;
    }

    // Coupling: perfect fit bonus (post_residual exactly 0).
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - (pr / cap); // fraction of bin used after placement

    // Core: penalize leftover space non-linearly (dead space grows quadratically in cost)
    let mut score = pr * pr / cap;

    // Reward high fill ratio with a smooth saturating term
    score -= cap * fill * fill * fill;

    // Lookahead coupling: if the next item exactly fits the post residual, strong reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_deg = 1.0 - ((pr - nxt).abs() / cap);
        score -= 12.0 * match_deg * match_deg * match_deg;
        // Penalize leaving residual that is awkwardly small for the next item
        if pr < nxt {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * (1.0 - progress);
    }

    // Late in the stream, consolidate into existing bins rather than opening new ones
    score += 5.0 * progress * (pr / cap);

    // Slightly discourage spreading across many open bins when residuals are large
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // Smooth interaction: post residual scaled by stream progress
    score += pr * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition by quarter-capacity bands
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty grows superlinearly for small residuals
    if post_residual > 0 {
        let dead = (post_residual as f64).powf(1.4);
        score += dead * 0.6;
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Harmonic class: post_residual divisible structure (mod 10, mod 25)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0; // round residual likely reusable by future items
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Quarter-capacity band penalty
    let q = pr / cap;
    if q > 0.0 && q < 0.1 {
        score += 15.0; // near-dead sliver
    } else if q < 0.25 {
        score += 5.0;
    } else if q > 0.5 {
        score -= 3.0; // large residual is flexible
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 4.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current options are bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + 20.0 * (1.0 - progress);
        if post_residual % 10 == 0 {
            score -= 5.0;
        }
    }

    // Mild dispersion term: prefer bins near mean residual (balance load)
    score += ((pr - mean_residual).abs()) * 0.05;

    // Early stream: be slightly greedy with big residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (pr / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item can use are pure waste.
    let min_item = 1u32;
    if post_residual < min_item.max(next_item_size) && post_residual > 0 {
        // Dead space below the next item's size: penalize heavily, scaled by how close
        // the gap is to being truly useless.
        score += (post_residual as f64) * 4.0 + 25.0;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 30.0;

    // Lookahead synergy: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 + 30.0 * progress;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins
    // and favor consolidating into bins with larger residuals.
    score += open_bins_count as f64 * 0.5;

    // Favor bins with residual above the current mean (consolidation of slack).
    if bin_residual as f64 > mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: only attractive when nothing fits well. If this is the
    // empty new bin, make it costly unless existing bins create large dead space.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin; grows with number of already-open bins.
        score = bin_capacity as f64 + open_bins_count as f64 * 2.0;
        // But if the best alternative would leave big dead space, opening is fine:
        // the comparison against other candidates handles this naturally.
        if next_item_size > 0 && post_residual == bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post residual (perfect 2-step chain).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
    }

    // Penalize post residual that is too small to ever be useful (dead space below min item size).
    if post_residual < item_size.min(10) {
        score += 25.0;
    }

    // Compare post residual against mean residual: prefer bins left with typical, reusable space.
    score -= 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bins unless current bin would leave big waste.
    if bin_residual == bin_capacity {
        score += 60.0 - 0.5 * (bin_residual as f64 - post_residual as f64);
    }

    // Late in the stream, tighten packing: penalize any leftover space more heavily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            score += 3.0;
        }
        // Chain fit: residual after next item still usable.
        if post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            score -= 2.0 * (chain as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a good fit or open bins are very full on average.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let good_fit_exists = fit_ratio > 0.5 && bin_residual < bin_capacity;
        let _ = good_fit_exists;
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 {
            score += 10.0 + 20.0 * pressure; // discourage opening when fits exist
        } else {
            score -= 5.0; // encourage fresh bin when nothing fits well
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 * progress;
    }

    // Mild preference for filling fuller bins when many bins are open.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 4.0 * fullness * (open_bins_count.min(50) as f64).sqrt();

    // Slight pull toward bins near the mean residual (balanced packing).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: quadratic in post_residual scaled by capacity
    let norm_pr = pr / cap;
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth exponential decay
    score -= 20.0 * (-(pr / cap) * 6.0).exp();

    // Perfect-fit bonus (post_residual near zero), smooth
    score -= 15.0 * (-(pr * pr) / 18.0).exp();

    // Last-chance bin: strongly reward using it (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins with much larger residual than the mean (waste of big space)
    score += 0.15 * (pr - mean_residual).abs() * (0.5 + progress);

    // Lookahead: if next item fits the post-residual well, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = (post_residual as u32 - next_item_size) as f64;
        score -= 10.0 * (-(gap * gap) / 200.0).exp();
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // dead space: next item can't use remainder
        score += 5.0 * (pr / cap);
    }

    // Stream progress: later in stream, prefer filling existing bins
    score -= 8.0 * progress * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: which "slot band" does the leftover fall in?
    // Residuals in (0,10] are near-dead space; (10,20] still usable for min items, etc.
    let class = post_residual / 10; // 0..=10 integer division class
    let class_penalty: f64 = match class {
        0 => 45.0,                 // dead space, nothing (min size 1) can even use it well
        1 => 22.0,                 // only tiny items fit
        2 => 10.0,
        3 => 4.0,
        4 => 1.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Reward tight fits: fraction of the bin consumed by this item
    let fill_frac = item_size as f64 / cap;
    score -= 18.0 * fill_frac;

    // Perfect / near-perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 35.0;
    }

    // Lookahead: does the leftover accommodate the next item? Harmonic compatibility:
    // next_item_size class vs post_residual class.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover chainable: reward proportional to how snugly next item fits
            let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
            score -= 14.0 * snug;
        } else {
            // leftover cannot host next item: penalize more if it's just barely too small
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 12.0 * (1.0 - gap / 15.0);
            }
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when no open bin
    // offers a decent harmonic fit. Penalize new bins mildly by default.
    if bin_residual == bin_capacity {
        score += 8.0;
        // but if existing bins are fragmented (mean residual low relative to item),
        // new bin becomes less bad
        let fragmentation = mean_residual / cap;
        score -= 10.0 * fragmentation;
        // late in the stream, avoid spreading out
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 6.0 * progress;
    } else {
        // Prefer bins whose residual is far from the awkward mid-band
        // (residuals just below common item sizes create dead space)
        let awkward = (bin_residual as i64 - item_size as i64).unsigned_abs() as f64;
        score += 0.05 * awkward;
        // favor bins with residual close to mean (balance load)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.08 * dev;
    }

    // Modulo-style threshold: residuals that are multiples of 10 are "clean" slots
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..10)
    // can use efficiently are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0 * (10.0 - post_residual as f64); // tiny unusable gap
        } else if post_residual < 20 {
            score += 12.0; // hard-to-fill zone
        }
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 20.0; // leaves another good small gap
        } else if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 15.0; // blocks next item's fit with a dead gap
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the fit is loose.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - fit_ratio) * 2.0;

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset slightly by low open-bin count.
        score += 35.0 + 3.0 * open_bins_count as f64;
        // Prefer opening a new bin when existing mean residuals are small (fragmented).
        score -= (mean_residual / 10.0).min(20.0);
        // If the item is large relative to capacity, a fresh bin gives clean packing.
        if item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mild stream-progression term: tighten packing as the stream matures.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Exact fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly matches the next item size (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // Next item fits here too: mild reward proportional to how well it uses the post residual.
            let next_util = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * next_util;
        } else {
            // Next item cannot use the residual: penalize wasted space, worse for big leftovers.
            let waste = (post_residual - next_item_size) as f64;
            score += 0.15 * waste;
        }
    }

    // Compare residual against mean residual across open bins:
    // prefer bins with below-average residual (more packed bins first).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.5 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize spreading across many open bins early; encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (post_residual as f64) > 0.6 * (bin_capacity as f64);
        if poor_fit {
            score -= 200.0;
        } else {
            score += 250.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * (item_size as f64 / bin_capacity as f64);

    // Penalize small unusable leftovers (dead space), especially below next item scale.
    if post_residual < 10 {
        score -= 2.0; // perfect fill bonus
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 1.5 * (1.0 - (post_residual as f64 / next_item_size as f64));
    }

    // Lookahead coupling: reward leaving exactly the room the next item needs.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.6 * (gap / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 4.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // Prefer bins with low residual relative to mean (consolidate leftovers).
    score -= 0.8 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Time horizon: early in stream, be more willing to open bins for better structure;
    // late in stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 1.2;

    // Many open bins: discourage spreading; few open bins: encourage using them.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 { 0.0 } else { 0.0 };
        let poor_fit = (bin_residual - item_size) as f64 / bin_capacity as f64;
        let scarcity = if fitting_bins_count == 0 { 2.0 } else { 0.0 };
        score = 40.0 + poor_fit * 20.0 - scarcity - best_possible;
        if fitting_bins_count == 1 {
            score += 6.0; // don't open when a last-chance bin exists
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0; // new bin accommodates lookahead too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
