pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: mod-10 dead space bands
    let pr = post_residual;
    if pr > 0 {
        let m = pr % 10;
        // residuals in 1..9 are hard to fill -> penalize; multiples of 10 friendlier
        score += match m {
            0 => -5.0,
            1 | 9 => 12.0,
            2 | 8 => 9.0,
            3 | 7 => 6.0,
            4 | 6 => 3.0,
            _ => 0.0,
        };
    }

    // Small residuals are dead space; big residuals waste capacity
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // chainability reward, scaled by tightness of that hypothetical fit
            let chain_tight = (pr - next_item_size) as f64;
            score -= 15.0 - chain_tight * 0.15;
        } else {
            // next item won't chain here
            score += 8.0;
        }
        // harmonic class match: item and next item same decade suggests pairing
        if next_item_size / 10 == item_size / 10 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 55.0;
        // but if item is large relative to capacity, opening a fresh bin is fine
        if item_size as f64 > 0.6 * cap {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 > 0.6 * cap {
            score -= 20.0;
        }
    }

    // Prefer filling bins with below-average residual (compact bins first)
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Late in stream: be more aggressive at closing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but gaps too small to
    // hold even the smallest plausible item (<= 1) are pure dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < item_size.min(20) {
        // Unusable sliver: penalize heavily beyond its raw size.
        score += (20 - post_residual) as f64 * 2.5;
    }

    // Bonus for leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // creates dead space relative to next item
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the
    // fit is mediocre, but encourage using existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: mild baseline so it's chosen only when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
    } else {
        // Slight preference for fuller bins (smaller residual before placement).
        score += (bin_residual as f64) * 0.05;
    }

    // Coupling with mean residual: prefer bins below mean residual (fuller bins).
    score += (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with the next item is gold.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            // Exact match: next item fills this bin completely.
            score -= 60.0;
        } else {
            // Penalize mismatch relative to next item size.
            score += 0.35 * diff;
            // Extra penalty if next item can't fit here either (double dead space).
            if next_item_size > post_residual {
                score += 8.0;
            }
        }
    }

    // Tightness reward: small post_residual is good (dense packing).
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 10.0;

    // Penalize post_residual that is unusably small (< min item size 1 is fine,
    // but residual below ~10 is dead space for typical distributions).
    if post_residual < 10 {
        score += 5.0;
    }

    // Compare against mean residual across open bins: bins with larger-than-mean
    // residual should absorb this item to consolidate slack.
    if (bin_residual as f64) > mean_residual + 5.0 {
        score -= 4.0;
    } else if (bin_residual as f64) < mean_residual - 5.0 {
        score += 4.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 12.0;
        if post_residual < 10 {
            score += 10.0; // but not if it creates dead space
        }
    }

    // New-bin candidate handling: an empty bin has high post_residual; make it
    // mildly unattractive so it's only chosen when all fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if no existing bin fits well (large dead space everywhere), the
        // new bin becomes attractive via the natural post_residual comparison.
        if item_size >= 60 {
            score -= 10.0; // big items: fresh bin is often best
        }
    }

    // Slight preference to fill older bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

