        let pr = post_residual as f64;
        score += (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * 20.0;
        // Dead-space penalty: residual too small for smallest plausible item
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Lookahead coupling: favor bins whose leftover can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 - (slack / bin_capacity as f64) * 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover can't host next item: mild penalty, stronger late in stream
        score += 6.0 + 10.0 * t;
    }

