    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer filling bins with larger residual (consolidation) when many bins open
    let frac = bin_residual as f64 / bin_capacity as f64;
    score += frac * (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Global fragmentation pressure: penalize bins far from mean residual
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate handling: neutral baseline, open only when fits are poor
    if bin_residual == bin_capacity {
        score = 45.0 + 30.0 * t - (fitting_bins_count as f64) * 5.0;
        if next_item_size > 0 && item_size <= next_item_size {
            score += 5.0; // large item now, keep fresh bins for smaller next item
        }
        if mean_residual > item_size as f64 * 1.5 {
            score += 10.0; // open bins have plenty of room; don't open new one
        }
    }

    // Slight late-stream urgency to close out bins
    score *= 1.0 + 0.1 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
