    let mut score = pr * (1.0 + 0.8 * progress) - 6.0 * fill * fill;

    // Non-linear penalty on wasted residual relative to mean residual
    let waste = (pr - mean_residual).abs();
    score += 0.05 * waste * waste / cap;

