                score -= 300.0;
            } else {
                let slack = pr - next_item_size;
                score -= 20.0 + (slack as f64).min(20.0);
            }
        } else {
            // Next item won't fit here: penalize wasting a good residual
            score += (next_item_size - pr) as f64 * 0.5;
        }
        // Harmonic class coupling: next item divisible with residual
        if pr > 0 && next_item_size % 10 == 0 && pr % 10 == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are tight
    if bin_residual == bin_capacity {
        let tightness = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 1.0 };
        // If mean residual across open bins is small (bins nearly full),
        // opening a new bin is reasonable -> reduce penalty.
        score += 40.0 + 30.0 * tightness;
        if fitting_bins_count == 0 { score -= 100.0; }
    }

    // Progress-based mild pressure to consolidate early
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the next item
    // (or any plausible item) are wasted space -> heavy penalty.
    let min_item = 1u32;
    if post_residual < next_item_size && post_residual > 0 {
        // gap unusable by lookahead item
        let gap = post_residual as f64;
        let tightness = 1.0 - gap / (next_item_size.max(1) as f64);
        score += 18.0 * tightness;
    }
    if post_residual < min_item + 9 {
        // near-zero residual: perfectly tight fit, strongly reward
        score -= 25.0;
    }

    // Reward tight fits relative to item size (small waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * waste_frac * waste_frac;

    // Lookahead synergy: if next item also fits the resulting residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let pair_slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - pair_slack / bin_capacity as f64);
    }

    // Open-bin pressure: discourage scattering across many open bins,
    // but relax pressure late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = 2.5 * (1.0 - 0.5 * progress);
    score += pressure * ((open_bins_count as f64) / 20.0).min(1.0);

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): make it unattractive unless all fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0; // no open bin fits -> must open new bin
        }
    }

    // Mild alignment with mean residual: prefer bins whose post state
    // stays near the fleet mean (balanced residual portfolio).
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: this item's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Near-match: leftover close to next item size (within 10).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap > 0 && gap <= 10 {
            score -= 12.0 - gap as f64;
        }
        // Penalize leftover that is too small for the next item but nonzero (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 4.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Reward tight fits relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.35;
    } else {
        score += (pr - mean_residual) * 0.25;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Discourage opening new bins early when many bins are open and item fits well.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty unless lookahead suggests a fresh bin is useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - 6.0 * progress;
        if next_item_size > 0 && bin_capacity - next_item_size as u32 <= item_size.max(1) {
            score -= 10.0; // fresh bin can chain next item
        }
    }

    // Bonus for zero waste.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    } else {
        // Penalize dead space that nothing can ever use (min item size 1, but
        // typical items are much larger) with a nonlinear curve.
        let dead = post_residual as f64;
        score += (dead * dead) / (bin_capacity as f64 * 1.5);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = mean_residual / bin_capacity as f64; // high => open bins are full
        // Cost of opening a bin grows with number of open bins and decreases
        // with how full existing bins are.
        let open_cost = 30.0 + 2.0 * open_bins_count as f64 - 25.0 * open_pressure;
        score += open_cost;
        // Late in the stream, prefer filling existing bins even more.
        score += 10.0 * progress;
        // If the next item fits perfectly in a fresh bin, slightly favor opening.
        if next_item_size > 0 && next_item_size == bin_capacity - item_size {
            score -= 8.0;
        }
    } else {
        // Prefer bins whose residual matches the next item's needs (lookahead).
        if next_item_size > 0 {
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score += gap * 0.3;
            // Reward leaving exactly the space the next item needs.
            if post_residual == next_item_size {
                score -= 12.0;
            }
        }
        // Mild preference for fuller bins when many bins are open (consolidation).
        score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count as f64).min(10.0);
    }

    // Global balance: penalize bins far from mean residual to keep residuals homogeneous.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let mut score = pr;

    // Smooth polynomial coupling: penalize residual non-linearly, more later in stream
    let prn = pr / cap;
    score += 40.0 * prn * prn * (0.5 + 0.5 * progress);

    // Reward tight fits (low post residual) more strongly as stream progresses
    score -= (1.0 - prn) * (1.0 - prn) * 20.0 * (0.3 + 0.7 * progress);

    // Lookahead coupling: reward residual that can host next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 12.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many bins already open with slack
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        score -= mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 20.
    let pr = post_residual;
    let class10 = (pr % 10) as f64;
    let class20 = (pr % 20) as f64;
    // Penalize residuals whose harmonic class makes them hard to fill later
    // (residuals in 1..10 are dead space; multiples of 10 are reusable).
    if pr > 0 && pr < 10 {
        score += 25.0; // dead space penalty
    } else {
        score -= class10 * 0.3; // reward exact decade alignment
        score -= (class20 == 0.0) as i32 as f64 * 5.0;
    }

    // Perfect fit bonus tiers via integer division thresholds.
    if pr == 0 {
        score -= 60.0;
    } else if pr <= 5 {
        score -= 30.0;
    } else if pr <= 15 {
        score -= 10.0;
    }

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let post = pr as f64;
        if nx <= post {
            // Reward if next item divides or nearly fills the residual
            let ratio = nx / post;
            if (post % nx).abs() < 1e-9 {
                score -= 20.0; // exact divisor: harmonic match
            } else if ratio > 0.7 {
                score -= 12.0;
            } else if ratio > 0.4 {
                score -= 4.0;
            } else {
                score += 3.0; // leaves awkward chunk
            }
        } else {
            score += 6.0; // next item won't fit here regardless
        }
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only prefer when open bins fit poorly.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / cap;
        // Opening a new bin costs ~1 bin; require poor fit in existing bins.
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else {
            (bin_residual as f64 - item_size as f64) / cap
        };
        if fitting_bins_count > 0 && post_residual >= 30 {
            score += 15.0; // existing bin leaves plenty of room, use it
        }
        score += 5.0 * (1.0 - tightness); // small items shouldn't open bins
        let _ = poor_fit;
    }

    // Mid-stream consolidation pressure: fewer open bins is better.
    let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
    score += (open_bins_count as f64).ln() * (1.0 + progress);

    // Nudge toward bins with residuals near mean (balance load).
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual that cannot host the next item is waste.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * next_item_size as f64;
    }

    // Reward perfect/near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: discourage scattering across many bins when residuals are plentiful.
    score += open_bins_count as f64 * 0.3;

    // Mild bonus if this placement keeps the bin's residual near the fleet mean (balance).
    score -= 0.2 * (post_residual as f64 - mean_residual).abs().recip().min(5.0);

    // Slight tightness reward scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - post_residual) as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose residual after placement matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            // leftover after hypothetically placing next item too
            let left2 = post_residual - next_item_size;
            score -= 150.0 - (left2 as f64).min(150.0);
        } else {
            // next item cannot fit here; penalize small dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare post_residual against mean residual across open bins
    score -= (post_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening new bins when open bins exist with good fit
    if bin_residual == bin_capacity {
        score += 50.0 + (open_bins_count as f64) * 2.0;
        // allow new bin only if existing fits are terrible
        if post_residual > bin_capacity as f64 * 0.6 {
            score -= 30.0;
        }
    }

    // Tightness reward: smaller relative waste is better
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: perfect wrap with lookahead item is ideal.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    }
    // Pairing where lookahead fits with some slack left is still good.
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 12.0 + 0.3 * (post_residual - next_item_size) as f64;
    }
    // Lookahead would NOT fit here: penalize mildly, worse if it barely misses.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 8.0;
    }

    // Reward small dead space quadratically.
    let pr = post_residual as f64;
    score += 0.05 * (pr / bin_capacity as f64).powi(2) * 100.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Time horizon: later in stream, consolidate more aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * (1.0 - pr / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> favor filling existing bins.
    if open_bins_count > 0 {
        score -= 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or when the current item is small relative to capacity.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.5 * item_size as f64;
        // But if item is huge and nothing else helps, new bin is fine.
        if item_size > bin_capacity / 2 && fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual)
    let mut score = pr;

    // Smooth non-linear coupling: residual quality decays with stream progress
    // (late in stream, tight fits matter more; dead space is costlier)
    let tightness = 1.0 - pr_norm;
    let progress_weight = progress * progress;
    score -= 6.0 * tightness * tightness * (1.0 + progress_weight);

    // Lookahead: reward post_residual that can still host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 4.0 * (1.0 - slack) * (1.0 + 0.5 * progress);
        } else {
            // dead space relative to next item
            let gap = (nx - pr) / cap;
            score += 5.0 * gap * gap * cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize spreading across too many open bins relative to mean residual
    let mean_dev = (pr - mean_residual).abs();
    score += 0.02 * mean_dev;

    // Slight penalty for opening new bin when many bins already open
    if bin_residual == bin_capacity {
        score += 1.0 + 0.05 * open_bins_count as f64 - 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: modulo arithmetic on capacity fractions.
    let cap_q = post_residual / (bin_capacity / 4); // quarter-class: 0..4
    let cap_mod = post_residual % (bin_capacity / 4);

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 500.0;
    }
    // Near-perfect fits within small dead-space window.
    if post_residual <= 5 {
        score -= 120.0 - (post_residual as f64) * 15.0;
    }

    // Reward leaving residuals in "usable" harmonic classes (multiples of common item sizes).
    let usable = [0u32, 10, 20, 25, 30, 40, 50, 60, 70, 80];
    let mut best_gap = u32::MAX;
    for &u in usable.iter() {
        if post_residual >= u {
            best_gap = best_gap.min(post_residual - u);
        }
    }
    if best_gap != u32::MAX {
        score -= (best_gap as f64) * 1.5; // residual close to a reusable size
    }

    // Penalize residuals that fall into dead zones: too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0; // unusable sliver
    }

    // Quarter-class shaping: mid-capacity leftovers are flexible.
    match cap_q {
        0 => score += 10.0,                       // tiny leftover, nearly full bin
        1 => score -= 15.0,                       // ~25 free: decent
        2 => score -= 25.0,                       // ~50 free: very flexible
        3 => score -= 10.0,                       // ~75 free: bin barely used
        _ => {}
    }
    // Fine-grain modulo bonus: residuals aligned to multiples of 5 pack well.
    if cap_mod % 5 == 0 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits the post-residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 60.0;
        if slack <= 10 {
            score -= 40.0; // next item packs tightly too
        }
    } else if next_item_size > 0 && next_item_size > bin_capacity / 2 {
        // Next item is large; avoid leaving it stranded.
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0;
    }

    // New-bin candidate handling: opening a new bin should only win when current
    // fits are all poor. Give the empty bin a moderate baseline.
    if bin_residual == bin_capacity {
        score = 55.0
            + (post_residual as f64)
            - if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If many open bins already, discourage sprawl.
        score += (open_bins_count as f64) * 1.5;
        return score;
    }

    // Prefer bins whose residual deviates from the mean toward tightness.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Mild preference for using fuller bins when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * (bin_residual as f64) * 0.05;

    // Progress-based consolidation: as stream ends, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_capacity - bin_residual) as f64 * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item (min size 1..100, but small gaps < next_item_size are risky).
    // Penalize gaps that are unusable for the lookahead item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead need.
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // Penalize very small leftover gaps (likely dead space for any item).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * 15.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from many open bins: prefer filling existing bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins below mean residual (filling emptier bins less aggressively
    // keeps balanced residuals; filling fuller bins first consolidates waste).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: make it moderately attractive only when the fit is
    // poor (large post_residual), otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score += 20.0 - 0.4 * item_size as f64;
        if fitting_bins_count > 0 {
            score += 15.0; // existing bins can fit: discourage new bin
        }
    }

    // Lookahead pairing: perfect pairing bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when the next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64;
        score -= 60.0 - 0.6 * snug;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        // small dead space that likely can't fit anything (min item 1..100, penalize moderately)
        score += 10.0;
    }

    // Penalize large wasted residual relative to mean residual across open bins.
    let waste = post_residual as f64 - mean_residual;
    score += 0.3 * waste.max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit is poor
    // (post_residual too small to be useful) or many bins are already open.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
        let mut penalty = 120.0;
        if poor_fit > 0.0 { penalty -= 140.0; } // allow opening when fit would create dead space
        if next_item_size > 0 && post_residual >= next_item_size { penalty += 40.0; }
        penalty += (open_bins_count as f64).min(20.0);
        score += penalty;
    }

    // Slight preference early in the stream to keep bins consolidated.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;

    // Core: prefer small post-residual, but avoid useless near-zero leftovers
    let mut score = post * 1.0;

    // Reward tight fits (fill fraction of the bin consumed)
    score -= (item / cap) * 8.0;

    // Penalize dead space that is too small to be useful later (items >= 1, so
    // residual < smallest plausible item is dead). Treat < 10 as dead zone,
    // scaled by how dead it is.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 3.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 6.0 + (post - nxt) * 0.3; // prefer exact lookahead match
        } else {
            score += 2.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin should only win when the fit is bad
    if bin_residual == bin_capacity {
        // Opening a new bin is cheap when many bins are open and mean residual is high
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_bonus = 4.0 + mean_residual * 0.05 + open_bins_count as f64 * 0.2;
        score += new_bin_bonus * (1.0 - 0.5 * progress);
        // But if the item nearly fills a fresh bin, opening is attractive
        score -= (item / cap) * 4.0;
    }

    // Global state coupling: prefer placing into bins whose residual is far
    // below the mean (consolidating fragmented bins).
    score += (mean_residual - resid).max(0.0) * 0.05;

    // Prefer reducing the number of very fragmented bins: penalize leaving
    // large post-residual when many bins are open (encourage consolidation).
    score += post * (open_bins_count as f64).ln().max(0.0) * 0.02;

    // Mild time horizon shaping: early in the stream, be conservative about
    // opening bins (penalize new bins); late, allow flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, waste is cheap; late, tight fits are strongly rewarded.
    let waste_weight = 0.5 + 2.0 * progress * progress;
    score += waste_weight * (pr * pr) / (cap * cap) * 10.0;

    // Reward tight fits smoothly: small post_residual relative to capacity.
    let tightness = 1.0 - pr / cap;
    score -= 8.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize bins that deviate from the mean residual (smooth coupling),
    // preferring balanced residual pools.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    // Lookahead coupling: reward residual close to next item size (smoothly).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 6.0 * (1.0 - gap) * (1.0 - gap);
    }

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a bin unless item is large
    // relative to capacity (smoothly relaxed).
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 4.0 + 6.0 * (1.0 - fill) * (1.0 - fill);
        score -= 2.0 * progress;
    }

    // Mild penalty for many open bins, encouraging consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that fall into
    // "nice" residue classes likely to be filled by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction of post-residual

    // Reward small post_residual strongly (tight fits are good).
    score -= 40.0 * (1.0 - frac).powi(2);

    // Penalize residuals that are awkward: not expressible as a small
    // combination of typical item sizes. Use modulo-10 class logic.
    let mod10 = post_residual % 10;
    let class_bonus: f64 = match mod10 {
        0 => 6.0,  // perfectly divisible residual is reusable
        5 => 4.0,
        2 | 8 => 2.0,
        1 | 9 => 0.5,
        _ => -1.5, // odd/awkward residues are dead-space prone
    };
    score -= class_bonus;

    // Integer-division thresholds: residual bands.
    let band = post_residual / 10;
    let band_penalty = match band {
        0 => -30.0,           // 0-9: near-perfect fit
        1..=3 => -12.0,       // 10-39: very reusable
        4..=6 => 0.0,         // 40-69: neutral
        7..=9 => 8.0,         // 70-99: half-empty, wasteful unless needed
        _ => 0.0,
    };
    score += band_penalty;

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let next_gap = post_residual - next_item_size;
            score -= 25.0 * (1.0 - (next_gap as f64) / cap);
            // harmonic match: next item's residue class complements post-residual
            if (post_residual % next_item_size.max(1)) < 5 {
                score -= 8.0;
            }
        } else {
            // next item cannot use this residual at all: mild penalty
            score += 5.0;
        }
    } else {
        // Last item: any residual is pure waste; prefer tightest.
        score += 20.0 * frac;
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening a new
    // bin by favoring this one strongly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; only allow
    // it to win when all open bins would leave very large post-residuals.
    if bin_residual == bin_capacity {
        score += 55.0
            + 10.0 * (open_bins_count as f64).sqrt()
            - 30.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (i.e., fuller bins), closing them out early.
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score -= 6.0 * dev / cap;
    } else {
        score += 4.0 * (-dev) / cap;
    }

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - frac);

    // Slight preference to keep the number of open bins manageable.
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        // Dead-space penalty: strongest for tiny unusable gaps (1..10),
        // decaying as the gap becomes more likely reusable.
        let gap = post_residual as f64;
        let dead_zone = 10.0_f64.min(gap);
        score += (dead_zone / 10.0) * 40.0; // up to +40 for near-zero gaps
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 25.0;
        }
    } else {
        score -= 25.0;
    }

    // Reward good fits relative to bin fullness.
    let fill_ratio = item_size as f64 / capacity_f;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / capacity_f;
    score += tightness * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual too small for the next item: dead space penalty.
        score += 15.0;
    }

    // New-bin candidate: attractive when open bins are fragmented.
    if bin_residual == bin_capacity {
        // Base new-bin cost, scaled by how many bins are open.
        score = capacity_f + open_bins_count as f64 * 8.0;
        // If the item is large relative to mean residual, opening fresh is fine.
        if mean_residual > 0.0 && (item_size as f64) > mean_residual {
            score -= 10.0;
        }
        // Last item: cheap to just open a bin.
        if next_item_size == 0 {
            score -= 20.0;
        }
    }

    // Mild stream progression term: later in the stream, consolidation matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Penalize creating dead space the next item cannot use.
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score = 120.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A new bin can host both current and next items.
            if item_size + next_item_size <= bin_capacity {
                score -= 100.0;
            }
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize leaving residuals that are too small for future items (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            score += 8.0;
        }
        // Perfect pairing: item + next item exactly fills the bin.
        if item_size + next_item_size == bin_residual {
            score -= 35.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // no open bin fits well (post_residual small) or many bins are open.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Cheaper to open new bins early in the stream (long horizon to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
        // If many bins are open, discourage spreading items across new bins.
        score += open_bins_count as f64 * 2.0;
        // If the item is small, a new bin wastes capacity; discourage.
        score += (100 - item_size.min(100)) as f64 * 0.3;
    } else {
        // Favor reusing existing bins, especially ones with low residual relative to mean.
        score -= 5.0;
        if mean_residual > 0.0 {
            let rel = post_residual as f64 / mean_residual;
            if rel < 1.0 {
                score -= (1.0 - rel) * 10.0;
            } else {
                score += (rel - 1.0) * 5.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, waste is cheap (favor smooth packing); late, residual
    // waste is penalized super-linearly to force tight fits.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    let progress_coupling = pr_norm * (1.0 + 3.0 * progress * progress);
    score += progress_coupling * cap * 0.5;

    // Smooth interaction: bins whose post_residual matches the next item's need
    // are rewarded (subtract), using a smooth quadratic affinity term.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let affinity = 1.0 - ((pr - nxt) / cap) * ((pr - nxt) / cap) * 4.0;
        score -= affinity * 6.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mild penalty when many bins are open and this placement fragments space.
    let fragmentation = (pr_norm * pr_norm) * (open_bins_count as f64).ln().max(1.0);
    score += fragmentation * 4.0;

    // Reward tight fits smoothly: post_residual near zero gets extra discount.
    let tightness = (-pr_norm * 6.0).exp();
    score -= tightness * 10.0;

    // New-bin candidate handling: opening a new bin is penalized mildly early,
    // more strongly late, so it only wins when no open bin fits well.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 15.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and residues divisible by
    // common item sizes are valuable; keep them.
    let r = post_residual;
    if r == 0 {
        score -= 1000.0; // perfect fit, ideal
    } else if r % 10 == 0 {
        score -= 30.0;
    } else if r % 5 == 0 {
        score -= 15.0;
    } else {
        // awkward residue classes penalized proportionally to how far from a
        // multiple of 10 they are
        let off = (r % 10).min(10 - r % 10) as f64;
        score += off * 3.0;
    }

    // Reward bins whose residual pairs with the lookahead item (k=2 lookahead)
    if next_item_size > 0 && next_item_size <= r {
        score -= 25.0;
        if r % next_item_size == 0 {
            score -= 40.0; // residue is an exact multiple of next item: chainable
        }
    } else if next_item_size > 0 && next_item_size > r {
        // residue too small for next item: dead space risk
        score += (r as f64) * 0.5;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: keep it mid-range; open only when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 120.0 + 50.0 * progress + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 30.0; // big lookahead item: fresh bin attractive
        }
        if fitting_bins_count == 1 {
            score += 150.0; // never open new bin when a last-chance bin exists
        }
    }

    // Prefer tighter bins overall (small residual relative to mean)
    score += 0.4 * (mean_residual - post_residual as f64);

    // Slight preference for using more-open bins early (consolidation)
    score -= 1.0 / (1.0 + open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer bins with small post_residual (tight fit).
    // Dead-space penalty: residuals too small to ever be useful are heavily punished.
    // Assume minimum useful item size ~1; treat "unusable" as post_residual < 10
    // (typical minimum item), scaled by how close to a full waste it is.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - pr) * 8.0; // tiny slivers are pure waste
    }

    // Reward exact or near-exact fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual is "designed" for the lookahead item:
    // if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 10.0;
    }
    // Penalize leaving a gap that the lookahead item cannot use (dead space for k=2).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += pr * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this bin.
    if bin_residual == bin_capacity {
        // A fresh bin is attractive only when current item is large and no tight fit exists.
        // Penalize new bins when open bins count is low (plenty of room to consolidate),
        // reward slightly when many bins are open and item is huge (better distribution).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = (open_bins_count as f64).ln() + 1.0;
        score = 100.0 - item_size as f64 * 0.3 + openness * 5.0 - progress * 10.0;
        // If the item fits almost perfectly in some open bin, new bin is bad;
        // approximate via mean residual: if mean residual is small, discourage new bin.
        score += (mean_residual / bin_capacity as f64) * 20.0;
        // Large items into fresh bins are fine (they define the bin's shape).
        if item_size >= 60 {
            score -= 15.0;
        }
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones harder
    // (consolidation) rather than spreading.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64) * 0.8;
        // Prefer bins below mean residual (emptier bins get filled first, keeping
        // tight bins tight... inverse: fill tighter bins to close them out).
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled.
    score *= 1.0;

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Slack after hypothetically placing next item: lower slack => better.
            let chain_slack = post - nxt;
            score -= 0.6 * (bin_capacity as f64) * (1.0 - chain_slack / bin_capacity as f64);
            // Perfect chain (post == next) heavily rewarded.
            if chain_slack == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot follow: penalize leaving awkward residual.
            let waste = post;
            score += 0.15 * waste;
            if post < 10.0 {
                // Tiny unusable residual -> dead space penalty.
                score += 10.0 * (10.0 - post) / 10.0;
            }
        }
    }

    // Compare post_residual against mean residual: prefer bins whose residual
    // stays near the mean (balanced packing) but reward shrinking big residuals.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; penalize opening new bins when many are open,
        // unless item is large relative to capacity.
        let frac = item_size as f64 / bin_capacity as f64;
        score = 0.5 * bin_capacity as f64
            + 8.0 * (open_bins_count as f64).ln().max(0.0)
            - 20.0 * frac * frac
            + 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Late in stream: consolidate aggressively, discourage new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    // Mild preference for bins with more residual being consumed fully.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(3);
    score += tightness * 40.0;

    // Penalize leaving residuals that are "dead space" (too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0; // awkward gap
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score -= 20.0 * (1.0 - waste as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for wasting capacity on this bin
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > item_size as f64 * 1.5 {
        score -= 8.0 * (mean_residual / bin_capacity as f64);
    }

    // Early in stream: be more willing to open new bins (keep options open);
    // late in stream: consolidate into existing bins.
    score += (1.0 - progress) * 5.0 * (open_bins_count as f64).sqrt();

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score = bin_capacity as f64 * 0.85;
        // cheaper to open a new bin early in the stream
        score -= (1.0 - progress) * 15.0;
        // expensive when many bins already open
        score += open_bins_count as f64 * 2.0;
        // if item is large, a fresh bin gives a clean fit
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = pr / cap;

    // Base: reward small post_residual with a non-linear (quadratic) coupling
    let mut score = pr * (1.0 + fit_norm * fit_norm);

    // Stream-progress coupling: late in the stream, tighten tolerance for wasted space
    score += 30.0 * progress * fit_norm * (1.0 - fit_norm);

    // Penalize bins whose residual deviates from the mean residual (fragmentation signal)
    let dev = (pr - mean_residual).abs() / cap;
    score += 20.0 * dev * dev;

    // Lookahead: reward leaving room for the next item; penalize if next item won't fit
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack_fit = (pr - nxt) / cap;
            score -= 15.0 * (1.0 - slack_fit) * (1.0 - slack_fit);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: neutral-ish score that decays as stream progresses / bins accumulate
    if bin_residual == bin_capacity {
        score = cap * (1.0 - 0.5 * progress) + 10.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded,
    // tiny dead spaces (1..=5) heavily penalized, mid zones graded.
    let cls = match post_residual {
        0 => -40.0,
        1..=5 => 25.0,
        6..=15 => 6.0,
        16..=30 => -2.0,
        _ => 0.0,
    };
    score += cls;

    // Modulo arithmetic: residuals divisible by common item-size classes (10, 20, 25, 50)
    // are more reusable by future items.
    if post_residual % 10 == 0 { score -= 8.0; }
    if post_residual % 25 == 0 { score -= 5.0; }
    if post_residual % 20 == 0 && post_residual % 10 != 0 { score -= 3.0; }
    // Odd residuals are less reusable.
    if post_residual % 2 == 1 && post_residual > 0 { score += 2.0; }

    // Integer-division thresholds: can post_residual host the lookahead item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // Harmonic bonus: lookahead fits exactly.
            if post_residual == next_item_size { score -= 15.0; }
            // Chain check: residual after hypothetical second placement.
            let r2 = post_residual - next_item_size;
            if r2 % 10 == 0 { score -= 4.0; }
        } else {
            score += 6.0;
        }
    } else {
        // Last item: prefer tightest fit only.
        score = post_residual as f64 - 20.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 && post_residual >= next_item_size { score -= 6.0; }
    }

    // Progress-aware tightening: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;

    // Crowding: many open bins -> prefer reusing bins to avoid sprawl.
    if open_bins_count > 4 {
        score -= 1.5;
    }
    // Mean residual coupling: prefer bins below mean residual (less attractive space).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 10) are pure waste; penalize them heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits: post_residual close to zero relative to item size.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * tightness * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins would leave
    // bad dead space or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, softened by open-bin pressure.
        score += 15.0 + 3.0 * open_bins_count as f64;
        // A new bin is good if placing in an existing bin wastes a lot.
        let waste_here = post_residual as f64;
        if waste_here > 30.0 {
            score -= waste_here * 0.8;
        }
        // Large items fit better in a fresh bin.
        score -= 20.0 * tightness;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 35.0 * (1.0 - gap / 10.0);
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover; penalize proportionally.
        score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Open-bin pressure: discourage spreading across many bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * open_bins_count as f64 * (1.0 - progress);

    // Mild pull toward bins with below-average residual (consolidation).
    if bin_residual as f64 > mean_residual {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Stream progression (0..1), used to amplify lookahead later in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Detect the brand-new empty bin candidate.
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize opening a new bin; the penalty shrinks for large items
    // (a large item leaves little usable space anyway, and hoarding it
    // in a partial bin can strand capacity).
    if is_new_bin {
        let large_item_relief = 1.0 - (item_size as f64 / bin_capacity as f64);
        score += 45.0 * large_item_relief;
    }

    // Aggressive 2-step lookahead coupling with next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr > 0.0 && (pr - nxt).abs() < f64::EPSILON {
            // Perfect pairing: the next item exactly fills this bin.
            score -= 25.0 * (1.0 + progress);
        } else if pr >= nxt {
            // Next item can still fit here: keeps options open.
            score -= 6.0;
        } else {
            // Dead space: leftover is too small for the next item.
            // Penalize proportionally to the wasted capacity.
            score += pr * 0.6;
        }
    }

    // Last-chance bonus: this is the only open bin that fits the item,
    // so strongly prefer it over opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild tiebreak toward bins whose residual is below the mean
    // (consume tighter/most-constrained bins first, preserve flexible space).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor tight fits: reward small post_residual non-linearly.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Penalize leaving dead space that the known next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size - post_residual) as f64;
    }
    // Reward when post_residual exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin when plenty of open bins exist with slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 55.0 + 45.0 * (1.0 - progress);
        score += new_bin_penalty;
        // Allow new bin only if mean residual across open bins is very small.
        if mean_residual < 8.0 {
            score -= 60.0;
        }
    } else {
        // Reward reusing bins whose residual is close to mean (keeps balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Mild bonus for filling bins well late in the stream (compaction phase).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - tightness);

    // Discard bins with residual too small for any future item class.
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_ratio = post / cap;

    // Base: waste after placement, with non-linear shrinkage of large residuals
    let mut score = post * (1.0 + 0.5 * fit_ratio * fit_ratio);

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) are rewarded more strongly
    let tightness = 1.0 - fit_ratio;
    score -= (post * tightness) * (0.4 + 1.2 * progress * progress);

    // Penalize deviation from mean residual (keeps bin pool homogeneous)
    let dev = (post - mean_residual).abs();
    score += 0.15 * dev * (1.0 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a bin, especially early or when good fits exist
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 40.0 + 30.0 * (1.0 - progress) - 10.0 * scarcity;
        // If lookahead item would fit nicely in a fresh bin, soften penalty
        if next_item_size > 0 && next_item_size as f64 <= cap {
            let look_fit = (cap - next_item_size as f64) / cap;
            score -= 15.0 * look_fit * look_fit;
        }
    }

    // Reward bins that can also host the lookahead item after this placement
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 8.0 * (1.0 - slack * slack);
    }

    // Mild penalty for too many open bins relative to progress
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: waste created by this placement (primary objective signal).
    let mut score = post_residual as f64;

    // ---- Harmonic class of post_residual (modulo arithmetic on capacity) ----
    // Residuals in "dead" classes (small, unusable slivers) are heavily penalized.
    let r = post_residual;
    if r > 0 {
        // Class by residue mod 10 and mod 25: tiny residues (<10) are dead space.
        if r < 10 {
            score += 60.0; // unusable sliver for any item (min size 1)
        } else if r < 25 {
            score += 25.0; // only fits very small items
        }
        // Harmonic bonus: residual divisible by common item granularities
        // is more likely reusable by future items.
        if r % 10 == 0 {
            score -= 8.0;
        } else if r % 5 == 0 {
            score -= 3.0;
        }
        // Integer-division threshold: residual in [50, 100) can host half-capacity items.
        if r >= 50 {
            score -= 12.0;
        } else if r >= 34 {
            score -= 5.0;
        }
    } else {
        // Perfect fill is the best outcome.
        score -= 100.0;
    }

    // ---- Tightness reward: fraction of bin consumed by this item ----
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_frac;

    // ---- Lookahead coupling (k=2): does post_residual still fit next item? ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-friendly placement: residual can absorb the next item.
            score -= 15.0;
            // Extra reward when residual exactly matches next item's harmonic class.
            if post_residual == next_item_size {
                score -= 20.0;
            } else if post_residual % next_item_size == 0 && next_item_size > 0 {
                score -= 6.0;
            }
        } else {
            // Placement strands the next item into a new bin; penalize proportionally.
            score += 10.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // ---- Last-chance logic: this is the only bin that fits ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0; // strongly prefer using the sole fitting bin
    }

    // ---- New-bin candidate handling (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive if the item fits poorly everywhere.
        // Base cost of a fresh bin: its full unused capacity, discounted by
        // how many bins are open (consolidation pressure).
        score = bin_capacity as f64 - 0.5 * fill_frac * bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open
        } else if fitting_bins_count == 1 {
            // Existing last-chance bin should usually win; make new bin expensive.
            score += 30.0;
        } else {
            score += 15.0; // default: prefer consolidation into open bins
        }
    }

    // ---- Stream progression: early on, keep bins open/loose; late, tighten ----
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // ---- Mean-residual coupling: penalize placing into bins whose residual is
    // already far below the fleet mean (they are nearly closed); favor bins
    // close to mean residual to balance the open-bin pool. ----
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // ---- Open-bin pressure: many open bins -> discourage new bins implicitly
    // (handled above) and slightly encourage filling existing ones. ----
    score -= 0.5 * open_bins_count as f64 * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10.0 - post_residual as f64) * 2.0;
    }
    // Residuals that cannot fit the lookahead item either are semi-dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0 + 0.15 * post_residual as f64;
    }
    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into
    // new bins; a brand-new empty bin candidate gets penalized.
    if bin_residual == bin_capacity {
        score += 8.0 + 1.5 * open_bins_count as f64;
    } else {
        score -= 0.3 * open_bins_count as f64;
    }

    // Early in the stream, allow slightly more freedom to open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 * if bin_residual == bin_capacity { 1.0 } else { -0.5 };

    // Prefer bins whose residual deviates favorably from mean residual
    // (use bins with less remaining space, keeping large-residual bins flexible).
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Mild lookahead synergy: if the next item fits exactly in post_residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, with slight superlinear penalty on wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: strongly reward if the next item exactly fits
    // the post_residual (perfect chain), mildly reward if it fits at all.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt == post {
            score -= 60.0;
        } else if nxt < post {
            let slack = post - nxt;
            // reward decays as slack grows
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            // penalize leaving awkward slivers the next item can't use well
            if slack < 10.0 {
                score += 15.0;
            }
        } else {
            // next item cannot fit here: penalize blocking potential
            score += 10.0 + 0.2 * (nxt - post);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight"
    // and should be prioritized to be closed out.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (res - mean_residual);
    }

    // Exact fit bonus (item fills bin completely).
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: penalize opening a new bin when open bins exist,
    // scaled by how many bins could fit the item.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 120.0 + 10.0 * fitting_bins_count as f64;
        } else {
            // nothing fits elsewhere: new bin is fine, slight bonus to keep it clean
            score -= 5.0;
        }
    }

    // Stream progression: late in the stream, be more conservative (avoid
    // fragmenting space when few items remain).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Small tie-breaker noise-free jitter based on bin index proxy (open bins count)
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: penalize residual too small for the next item (dead space),
    // reward residual that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
            if post_residual == next_item_size {
                score -= 15.0; // exact two-item pairing
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin, but less when current bins
    // are fragmented (item fits many bins poorly) or late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 25.0 - 8.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
        if fitting_bins_count > 2 {
            score += 10.0; // plenty of alternatives exist; don't open more bins
        }
    }

    // Penalize bins whose residual is far above the mean (hoarding space),
    // mildly favor filling bins that are already low.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Prefer concentrating into few bins when many are open.
    score += 0.05 * (open_bins_count as f64);

    // Discard tiny residuals that will likely never be used (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth coupling: as stream progresses, penalize residual more strongly (waste matters later)
    score += 40.0 * progress * norm_pr * norm_pr;

    // Perfect-fit reward via smooth term (post_residual near 0)
    score -= 20.0 * (-norm_pr * 12.0).exp();

    // Penalize creating residual that fails to fit the lookahead item (dead space)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 8.0 * (ns - pr) / cap * (1.0 + progress);
        } else {
            // reward leaving room for the next item
            score -= 4.0 * (1.0 - ((pr - ns) / cap).abs()) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many open bins: mild penalty for spreading, favor tighter bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins below mean residual (tighter packing)
    score += 0.3 * (pr as f64 - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline with smooth decay as stream progresses
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress) - 10.0 * (fitting_bins_count == 0) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: exact fit is perfect, small residuals are golden.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Harmonic class of post_residual: dead space is bad if it can't host
    // typical small items (min size 1, but common sizes cluster in classes).
    let usable = if post_residual >= 50 { 3 }
        else if post_residual >= 25 { 2 }
        else if post_residual >= 10 { 1 }
        else { 0 };
    score += (3 - usable) as f64 * 8.0;

    // Penalize residuals that are just below common item sizes (dead zones).
    for s in [10u32, 20, 25, 30, 40, 50] {
        if post_residual > 0 && post_residual < s && post_residual + 3 >= s {
            score += 6.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // next item won't fit here; mildly penalize leaving large gap
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: residual == capacity means empty bin. Opening a new
    // bin is only attractive if current bin fit is very poor.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin; offset by how badly the item fits elsewhere
        score = 70.0 + post_residual as f64 * 0.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    // Late in the stream, prefer closing bins tightly (fewer open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * mean_residual * 0.05;
    score -= open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are useless.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Gaps too small for the smallest plausible item are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }
    // Moderately small gaps unlikely to fit average future items.
    if post_residual > 0 && post_residual < 20 {
        score += 150.0;
    }

    // Reward perfect / tight fits.
    if post_residual == 0 {
        score -= 300.0;
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 120.0 * tightness;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when open bins are quite full
    // (mean residual low) or too many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64;
        score += 60.0
            + 0.8 * pressure
            - 0.6 * mean_residual
            + 40.0 * (1.0 - progress);
        // If lookahead item fits in the new bin's residual, slightly favor it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        }
    } else {
        // Penalize wasting a large residual on a small item when other
        // bins could also fit (save big gaps for big items).
        let waste = bin_residual as f64 - item_size as f64;
        if fitting_bins_count > 1 {
            score += 0.3 * waste;
        }
    }

    // Lookahead coupling: bonus if the post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 50.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Mild open-bin pressure to consolidate early.
    score += 0.05 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the NEXT item fits the post-residual exactly well.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Next item fits: reward tight leftover after the pair.
            let pair_left = post - nxt;
            score -= 18.0 * (1.0 - pair_left / bin_capacity as f64);
            // Extra reward for near-perfect two-item packing.
            if pair_left <= 5.0 {
                score -= 12.0;
            }
        } else {
            // Next item won't fit here: penalize leaving large unusable gaps.
            score += 6.0 * (post / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual: prefer bins that stay near the pack's average tightness.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.25 * dev;

    // Penalize wasteful large post-residuals on big items (dead space risk).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score += 4.0 * fill_ratio * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Early in the stream, be more willing to spread (favor low post-residual less aggressively).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress);

    // New-bin candidate: only attractive when existing bins are very full/tight on average.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / bin_capacity as f64);
        score = 55.0 + 25.0 * tightness;
        if fitting_bins_count == 1 {
            score += 30.0; // don't open new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose post residual is small.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness) * (1.0 - tightness);

    // Exact fit: huge reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Dead-space penalty: residuals too small to fit any plausible item are wasted.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 0.0; // impossible, safe guard
    }
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64; // tiny unusable slivers
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain-fit bonus scaled by how snugly the next item fits afterwards.
            let chain = post_residual - next_item_size;
            score -= 15.0 * (1.0 - chain as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow: penalize mildly, more when sliver left.
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate logic: empty bin should lose unless current fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 30.0 + open_bins_count as f64 * 2.0;
        // But if existing bins would leave big slivers, opening is attractive.
        if fitting_bins_count > 0 {
            let best_possible = (bin_residual - item_size) as f64;
            if best_possible > 40.0 {
                score -= 10.0; // all existing fits are loose -> new bin ok
            }
        }
    }

    // Global state coupling: prefer filling bins when many bins are open
    // (consolidation pressure), scaled by mean residual.
    let consolidation = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score -= consolidation * (item_size as f64 / bin_capacity as f64) * 8.0;

    // Mean residual alignment: bins near the mean residual are "typical";
    // filling far-below-mean (already tight) bins wastes their scarcity.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: late in the stream, be greedier about tight fits
    // (less future to amortize partial fills).
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        score -= 10.0 * t * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = base * (1.0 + 0.8 * progress * base) - 0.5 * progress * base * base;

    // Reward tight fits, more so late in the stream
    let tightness = 1.0 - base;
    score -= 0.6 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that can't hold the next item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 0.4 * (1.0 - progress) * (next_item_size as f64 - pr) / cap;
    } else if next_item_size > 0 {
        score -= 0.25 * progress;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // Slight preference for bins with residuals near the mean (balance)
    score += 0.1 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: mild penalty so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 0.3 + 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual via harmonic-class logic.
    // Classify post_residual into integer-division classes of capacity.
    let quarter = bin_capacity / 4;
    let tenth = bin_capacity / 10;

    if post_residual == 0 {
        // Perfect fit, strongly reward.
        score -= 1000.0;
    } else if post_residual <= tenth {
        score -= 400.0;
    } else if post_residual < quarter {
        score -= 150.0;
    } else if post_residual < quarter * 2 {
        score -= 40.0;
    } else if post_residual < quarter * 3 {
        score += 20.0;
    }

    // Harmonic coupling with next item: if next item fits exactly in post_residual,
    // strongly reward; if next item cannot use post_residual, penalize dead space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 600.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 200.0 / (1.0 + gap as f64);
        } else {
            // Next item too big for this residual: residual may become dead space.
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // Multiple options: prefer the tightest (already captured), add mild penalty
        // to spread pressure across bins.
        score += 5.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // New-bin candidate logic: opening a new bin is only attractive when no open bin
    // fits well, or when mean residual is large (existing bins are fragmented).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // New bin baseline: score equals residual (100). Reward new bin when
        // mean residual across open bins is high (fragmented state).
        score -= 80.0 * (mean_residual / bin_capacity as f64);
        score -= 60.0 * progress;
        // Penalize opening new bins when many bins are already open but fragmented.
        if open_bins_count > 3 && mean_residual < (bin_capacity as f64) * 0.25 {
            score += 50.0;
        }
    }

    // Slight preference for bins whose residual is a harmonic multiple of common sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0 * (10.0 - post_residual as f64);
    } else if post_residual > 9 && post_residual < 20 {
        // Medium gaps are semi-wasted: moderate penalty.
        score += 0.8 * (post_residual as f64 - 9.0);
    }

    // Reward tight fits (near-zero post residual).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward using bins that can also host the lookahead item afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; with few bins, mild preference for tight fits anywhere.
    let pressure = (open_bins_count as f64).ln() * 3.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to the item (best-fit core signal).
    score += (bin_residual as f64 - item_size as f64) * 0.3;

    // New-bin candidate: attractive early or when existing fits are poor,
    // but discourage when the current bin already yields a good fit.
    if bin_residual == bin_capacity {
        let early = 1.0 - (step_index as f64 / (total_items.max(1) as f64));
        score = 45.0 - 20.0 * early + 0.5 * open_bins_count as f64;
        // A new bin is great if the item is large and would leave a big usable gap.
        if item_size >= 70 { score -= 15.0; }
        // But bad if a last-chance bin exists.
        if fitting_bins_count == 1 { score += 35.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: exact match of post_residual with next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits here after placing current one: mild reward scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.3;
        } else {
            // next item won't fit here after placement: penalize
            score += 8.0;
        }
    }

    // Relative tightness vs mean residual of open bins
    let tightness = mean_residual - post_residual as f64;
    score += tightness * 0.4;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent open bins exist
    if bin_residual == bin_capacity {
        let new_bin_penalty = 15.0 + 0.5 * open_bins_count as f64;
        // Only open a new bin if current item leaves large unusable residue elsewhere
        if post_residual <= 5 {
            score -= 30.0;
        }
        score += new_bin_penalty;
    }

    // Large dead space is bad
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // near-perfect fill
    } else if post_residual > 50 {
        score += 5.0; // wasteful
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that leave little dead space.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).powi(3);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize small unusable residuals (dead space that can't fit typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here anyway; mild penalty if we waste a big residual.
            if post_residual > 0 && next_item_size > post_residual {
                score += 3.0;
            }
        }
    }

    // Compare against mean residual: prefer bins with below-average residual
    // (consolidating space) when the fit is good.
    score += 0.15 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // New-bin candidate handling: opening a new bin is penalized more when
    // many bins are open and stream is early (future items can use leftovers).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score = 60.0 + 10.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        // If no existing bin fits well, allow opening a new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, opening a fresh bin is less costly.
        score -= 20.0 * progress;
    }

    // Mild penalty for very large residuals being consumed by small items.
    if item_size < 20 && bin_residual > 60 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

