    let norm_pr = pr / cap;
    score += 40.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Perfect fit reward (smooth bump near zero)
    score -= 25.0 * (1.0 - norm_pr).powi(4);

    // Lookahead coupling: residual that fits the next item is valuable
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits_next = if pr >= n { 1.0 } else { 0.5 * (pr / n) };
        score -= 15.0 * fits_next * (1.0 - (n / cap));
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Prefer bins below mean residual (tighter packing) with smooth interaction
    score += 5.0 * ((pr - mean_residual) / cap);

    // New-bin candidate: penalize mildly, more when many open bins or late stream
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress + 1.5 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: multiples of 10 (and 5) align with
    // common item size classes, leaving re-usable space.
    if post_residual % 10 == 0 {
        score -= 3.0;
    } else if post_residual % 5 == 0 {
        score -= 1.5;
    }
    score += (post_residual % 5) as f64 * 0.5;

    // Lookahead coupling: reward residuals that can host the next item,
    // penalize dead space that cannot.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - 0.5 * progress);
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - 0.5 * progress);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty when many bins compete (prefer consolidating into
    // already-crowded bins to keep mean residual low).
    if bin_residual < bin_capacity {
        score += 0.3 * ((bin_residual as f64) - mean_residual).max(-10.0).min(10.0) * 0.1;
    }

    // New-bin candidate: baseline mid-range score so it loses to any decent
    // fit, but wins when all open bins leave large unusable residuals.
    if bin_residual == bin_capacity {
        score = 0.55 * cap
            + 12.0 * fitting_bins_count as f64
            + (next_item_size as f64 / cap) * 5.0
            - 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: perfect or near-perfect fill strongly favored.
    if post_residual == 0 {
