    } else if post_residual <= 10 {
        score -= 300.0;
    } else if post_residual < item_size {
        // Residual too small for any item (items >= 1, but small gaps < typical min size)
        // become dead space; penalize heavily.
        score += 200.0;
    }

    // Dead-space penalty: small-but-nonzero gaps that likely cannot be filled.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score = 120.0 + open_bins_count as f64 * 2.0;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        // If next item would fit in leftover, opening new bin is less attractive.
        if next_item_size > 0 && next_item_size <= item_size {
            score += 30.0;
        }
        return score;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let waste = (bin_residual - item_size) as f64;
    score += waste * 0.5;

    // If the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 150.0;
        }
    }

    // Open-bin pressure: mildly discourage proliferation of bins with large residuals.
    if open_bins_count > 4 && mean_residual > 30.0 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item still fits comfortably with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Next item cannot follow into this bin: penalize dead space more.
        score += 10.0;
    }

    // Reward tight fits (small post_residual) with a non-linear term.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Penalize wasting a large residual on a small item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.5 {
        score += 15.0 * (0.5 - fill_ratio);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive when no good fit exists
    // (poor fill ratio or item barely fits nowhere else).
    if bin_residual == bin_capacity {
        score += 45.0;
        if fill_ratio < 0.6 {
            score -= 20.0;
        }
    }

    // Context: early in stream, slightly favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
