    if (mean_residual - post_residual as f64).abs() < 5.0 {
        score -= 4.0 * (1.0 - progress);
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual for an empty bin is bin_capacity - item_size; make it
    // expensive unless it offers a genuinely better long-term residual).
    if bin_residual == bin_capacity {
        let fresh_waste = post_residual as f64 / bin_capacity as f64;
        score += 10.0 + 20.0 * fresh_waste * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: opening is fine
        }
    }

    // Mild penalty for very large dead space relative to typical small items.
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0; // tiny residual is effectively dead space but tiny waste
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0; // awkward gap zone
    }

