    if post_residual == 0 { score -= 50.0; }

    // Lookahead: if the next item can fit exactly in post_residual, strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 20.0 * (1.0 - (post - nxt) / cap);
        } else {
