        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating residual far from mean residual (fragmentation risk),
    // with strength growing over the stream.
    let dev = (post - mean_residual).abs() / cap;
    score += dev * dev * (10.0 + 40.0 * progress);

    // Late in stream: consolidate into few bins; penalize spreading.
    if progress > 0.5 {
        score += post * (0.2 * (progress - 0.5));
    }

    // Mild penalty for opening a brand-new bin when others could fit.
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (1.0 - progress);
    }

