    // Many fitting bins: slight penalty to prefer tighter alternatives
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // New-bin candidate handling: only open a new bin when current bins fit poorly
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = cap * 0.5;
        // open a new bin if existing residuals are small/fragmented
        if mean_residual < 15.0 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size >= 90 {
            score -= 5.0;
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    } else {
        // favor bins whose residual is far from mean (keeps diversity)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // slight preference for fewer open bins when many are open
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
