    score += 6.0 * dev * dev;

    // Mild penalty for many open bins early (encourage consolidation early)
    score += open_bins_count as f64 * (1.0 - progress) * 0.3;

    // New-bin candidate: penalize slightly unless post_residual would be very usable
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - norm_item) * (1.0 + progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets strong discount.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Harmonic class of post_residual: dead space in (0,10] is nearly unusable
    // for typical items; penalize small-but-nonzero leftovers.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let nres = post_residual - next_item_size;
            score -= 15.0 * (1.0 - nres as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; mildly penalize leaving large gap unused
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or many bins are already open.
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * open_bins_count as f64;
        // If item would leave a harmonically useful residual (multiple of ~10),
        // soften the penalty slightly.
        let cls = post_residual % 10;
        if cls == 0 && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Encourage consolidation early in the stream when mean residual is high.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity && mean_residual > (bin_capacity as f64) * 0.5 {
        score -= 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Prefer bins whose residual was already small (tight packing).
    score += 0.4 * (bin_residual as f64 - item_size as f64 - post_residual as f64);

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item would leave a large gap elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 - item_size as f64 + 30.0 + 0.5 * open_bins_count as f64;
        // If no existing bin fits, new bin is the only option: make it cheap.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Lookahead: if next item is large, a fresh bin is more valuable.
        if next_item_size > 60 {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that cannot host the next item: extra penalty.
        score += 15.0;
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - leftover / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize leaving large residuals that waste space
            let waste = (post_residual as f64 - next_item_size as f64).abs();
            score += 0.05 * waste;
        }
    }

    // Compare residual against mean residual: prefer bins below mean residual (tighter bins)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when open bins could accept the item well
    if bin_residual == bin_capacity {
        score += 60.0;
        // New bin is acceptable if item is large relative to capacity
        score -= 0.3 * item_size as f64;
        // Early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
    }

    // Mild penalty for fragmenting bins with many other fitting options
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for future items (1..100).
    if post_residual > 0 {
        let min_useful = 1.0;
        if (post_residual as f64) < min_useful {
            score += 25.0;
        }
        // Dead space penalty grows if it can't fit the lookahead item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Lookahead coupling: if the post residual exactly fits the next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make opening a new bin costly unless current bin is a poor fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0;
        // But if this bin is the only fitting option among open bins is handled above;
        // if many bins fit, opening new is wasteful.
        if fitting_bins_count > 0 {
            score += 5.0 * (fitting_bins_count as f64).min(10.0);
        }
    }

    // Time horizon: early in stream, prefer keeping residuals balanced; late, prefer tight packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0 * (1.0 - fit_ratio);

    // Global state: penalize spreading across many open bins when mean residual is large.
    if !is_new_bin {
        let residual_gap = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * residual_gap * (open_bins_count as f64).sqrt();
    }

    // Mild preference for bins with larger residual when item is large (avoid fragmentation).
    score -= 0.02 * bin_residual as f64 * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Non-linear waste penalty: quadratic growth of residual cost, damped by stream progress
    let norm_post = post / cap;
    score += 40.0 * norm_post * norm_post * (1.0 + 0.5 * progress);

    // Reward tight fits (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Lookahead coupling: penalize if post_residual can't fit next item but could have
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 15.0 * (1.0 - post / nxt) * (1.0 - progress);
        } else {
            score -= 10.0 * (1.0 - (post - nxt) / cap);
        }
    }

    // Last-chance bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize fragmenting bins far below mean residual (keep balanced bins)
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score -= 8.0 * dev;
    }

    // New-bin candidate: mildly discourage opening new bins unless current residual is tiny
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * (1.0 - progress);
        if post < next_item_size as f64 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements leaving small post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Harmonic class of post_residual: residual buckets of width 10.
    // Small residuals (<=10) are "dead-space free" classes; large ones are wasteful.
    let cls = post_residual / 10;
    score += match cls {
        0 => -6.0,
        1 => -2.0,
        2 => 0.0,
        3 => 2.5,
        4 => 5.0,
        5 => 8.0,
        6 => 11.0,
        7 => 14.0,
        8 => 17.0,
        9 => 20.0,
        _ => 22.0,
    };

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual,
    // penalize if next item is close but leaves another awkward remainder.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 8.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: residual becomes dead space
            score += (post_residual as f64 - mean_residual).abs() * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large relative to capacity or no bin fits well.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let pressure = open_bins_count as f64 * mean_residual / bin_capacity as f64;
        score = 40.0 - 30.0 * large_item + 6.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size >= post_residual && post_residual == 0 {
            score -= 5.0;
        }
    }

    // Mild stream-phase adaptation: late in the stream, consolidate harder.
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * phase * tightness;

    // Prefer bins whose residual is near the mean (keeps bin profile uniform),
    // but reward below-mean residual usage slightly.
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (post_residual in (0, 10) is nearly wasted).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 25 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space is worse early/late depending on stream pressure; scale with open bins count.
    score += (open_bins_count as f64) * (post_residual as f64) * 0.05;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 10.0; // opening a fresh bin helps the next big item
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // dead space that next item cannot use
    }

    // Progress-based pressure: as stream completes, prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward residuals that match the next item exactly.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        // Exact match is ideal: next item fills the bin completely.
        score -= 30.0 * (1.0 - diff / 100.0).max(0.0);
        // Penalize leaving residual that is too small for the next item (dead space).
        if (post_residual as f64) < next && post_residual > 0 {
            score += 0.5 * (next - post_residual as f64);
        }
    } else {
        // Last item: prefer tightest fit.
        score += 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Prefer filling existing bins over opening new ones as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses or many bins open.
        score += 15.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Mild penalty for very small unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (near-zero post residual).
    let tight = (post_residual as f64) / bin_capacity as f64;
    score -= 40.0 * (1.0 - tight).powi(6) * tight.powi(1) / (tight + 0.05);

    // Penalize dead space that cannot fit the average next item.
    if next_item_size > 0 {
        if (post_residual as f64) < next_item_size as f64 {
            score += 12.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        } else {
            // Reward residuals that can still host the lookahead item.
            score -= 6.0 * (1.0 - ((post_residual as f64 - next_item_size as f64) / bin_capacity as f64));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only when existing fits are poor.
    if bin_residual == bin_capacity {
        let base = (bin_capacity as f64 - item_size as f64);
        let crowd = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = base * 0.55 + crowd * 1.5 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 10.0; // nothing else fits; opening is fine
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier space).
    if bin_residual != bin_capacity {
        score += 0.35 * (mean_residual - bin_residual as f64);
    }

    // Late-stream consolidation: prefer fewer bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = post / cap;

    // Base: prefer small post-residual, with non-linear (quadratic/cubic) coupling
    let mut score = post * (1.0 + 2.0 * fit_frac * fit_frac);

    // Stream-progress coupling: later in stream, penalize large residuals more strongly
    score += 30.0 * progress * fit_frac.powf(1.5);

    // Perfect-fit bonus (smooth, no hard threshold)
    let perfect = (-fit_frac * 12.0).exp();
    score -= 25.0 * perfect;

    // Lookahead: reward if next item fits well into the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let nxt_fit = nxt / cap;
        let slack = (post - nxt).max(0.0) / cap;
        score -= 15.0 * (1.0 - slack) * nxt_fit * (1.0 - nxt_fit);
        // Penalize leaving residual that neither helps next item nor closes bin
        if nxt > post {
            score += 8.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a bin unless existing bins fit poorly
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        let mean_frac = (mean_residual / cap).clamp(0.0, 1.0);
        // Opening a bin is worse when there are many open bins with usable residual
        score += 45.0 + 5.0 * crowding.sqrt() - 40.0 * mean_frac * (1.0 - fit_frac);
        // Early in stream, opening fresh bins is more acceptable
        score -= 25.0 * (1.0 - progress);
    } else {
        // Mild bonus for consolidating into existing bins
        score -= 3.0 * (mean_residual / cap).clamp(0.0, 1.0);
    }

    // Small dead-space penalty for residual too small to be useful (smooth)
    let dead = (0.12 - fit_frac).max(0.0) / 0.12;
    score += 10.0 * dead * dead;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else {
        // Dead-space penalty grows superlinearly for large unusable gaps.
        let pr = post_residual as f64;
        score += 0.08 * pr * pr / cap;
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 pair
    // well with the 1..100 integer item spectrum.
    let m = post_residual % 10;
    let class_bonus: f64 = match m {
        0 => 60.0,
        5 => 30.0,
        2 | 8 => 12.0,
        4 | 6 => 8.0,
        1 | 9 => 4.0,
        _ => 0.0, // 3 | 7 worst classes
    };
    score -= class_bonus;

    // Lookahead coupling: reward residual that exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 150.0 - 5.0 * slack;
            }
        } else {
            // Residual too small for next item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(40.0);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this is a large item early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / cap;
        let big_item = item_size as f64 > 0.5 * cap;
        if crowding < 0.25 || (big_item && progress < 0.3) {
            score -= 80.0 + 200.0 * (0.25 - crowding).max(0.0);
        } else {
            score += 250.0 + 100.0 * crowding;
        }
    }

    // Prefer filling bins below mean residual (tighter bins first).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Mild open-bins pressure: fewer bins -> keep them tight.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post_residual gaps are "dead" if no
    // plausible future item can use them. Penalize gaps that are too small.
    let dead_threshold = 10.0f64.min(post_residual as f64);
    if post_residual > 0 && (post_residual as f64) < 10.0 {
        score += (10.0 - post_residual as f64) * 3.0; // unusable sliver penalty
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit reward
    } else {
        // Larger gaps are reusable; mild reward proportional to usefulness
        score -= dead_threshold * 0.5;
    }

    // If the lookahead item fits exactly in the post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Lookahead won't fit here: the remaining gap may become dead space
        let waste = post_residual as f64;
        if waste < next_item_size as f64 {
            score += (next_item_size as f64 - waste) * 0.8;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: penalize placements that leave many half-empty bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual is below mean residual (tighter bins fill first),
    // keeping mean residual high for future large items.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., residual is large relative to item) or bins are very full.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin
        score += 30.0;
        // Large items deserve fresh bins more than tiny items
        score -= tightness * 25.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
        // If many bins are open with slack, discourage another
        if mean_residual > item_size as f64 * 2.0 && open_bins_count > 2 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward residuals that match the next item exactly.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Exact match => strong reward; near match => proportional reward.
        if match_gap < 1.0 {
            score -= 60.0;
        } else {
            score -= 40.0 / match_gap.sqrt();
        }
        // Penalize residuals that can never fit the next item's range meaningfully.
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" —
    // filling them is good (they'd otherwise become dead space).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Tight-fit bonus: near-perfect fill of the current bin.
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral-ish baseline; only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.3 * mean_residual;
        // Late in the stream, be more conservative about opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that cannot plausibly host the next item.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        } else if post_residual >= next_item_size {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with below-mean residual (tighter bins get priority).
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Time horizon: late in the stream, consolidate more aggressively;
    // early on, allow spreading to keep flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage filling existing ones rather than opening more.
    score += 0.8 * (open_bins_count as f64).ln().max(0.0) * (fitting_bins_count as f64).recip().max(0.1);

    // New-bin candidate: only attractive when the item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        let poor_options = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score += 30.0 - 25.0 * large * (poor_options + 0.3 * progress);
        // If a perfect-ish fit exists elsewhere, keep new bin unattractive.
        if post_residual == 0 { score += 10.0; }
    }

    // Reward exact fits decisively.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep
    score += norm_pr * norm_pr * 40.0 * (1.0 - poly);
    score -= norm_pr * 30.0 * poly;

    // Penalize residual that cannot fit the next item (dead space)
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 10.0 + gap * (0.5 + poly);
    } else if next_item_size > 0 && (next_item_size as u64) <= (post_residual as u64) {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty relative to mean residual to prefer tighter bins
    score += (mean_residual - pr) * 0.3;

    // New-bin candidate: penalize opening a new bin early, allow late
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - poly) + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover is
    // for common small items (1..=20). Classes via integer division.
    let post = post_residual;
    let class = post / 10; // 0..10 harmonic classes on capacity 100
    score += match class {
        0 => -18.0,                 // nearly perfect fit
        1 => -8.0,                  // leaves room for a small item
        2 => -3.0,
        3 => 0.0,
        4 => 2.0,
        5 => 4.0,                   // half-empty bin: mediocre
        6 => 5.0,
        7 => 6.0,
        8 => 7.0,
        _ => 9.0,                   // mostly empty: wasteful placement
    };

    // Reward exact modular harmony: post_residual divisible by common sizes
    if post > 0 && post % 10 == 0 {
        score -= 4.0;
    }
    if post > 0 && post % 20 == 0 {
        score -= 2.0;
    }

    // Lookahead coupling: does post_residual nicely accommodate next item?
    if next_item_size > 0 {
        if post >= next_item_size {
            let slack = (post - next_item_size) as f64;
            score -= 3.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to waste
            score += 2.0 + (next_item_size - post) as f64 * 0.05;
        }
        // modulo harmony between post and next size
        if post > 0 && next_item_size > 0 && post % next_item_size == 0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalty scaling with crowding: with many open bins, prefer tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.03 * (open_bins_count as f64) * (post as f64 / bin_capacity as f64);
    score *= 1.0 + 0.5 * progress;

    // Mean-residual anchoring: penalize bins far above the mean residual
    score += 0.05 * ((post as f64) - mean_residual).abs();

    // New-bin candidate: baseline score so it loses only against good fits
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.62 - 5.0
            + 0.05 * (open_bins_count as f64)
            - if next_item_size > 0 && next_item_size <= bin_capacity { 2.0 } else { 0.0 };
        if fitting_bins_count <= 1 {
            score += 15.0; // don't open a new bin if this is the only fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (small post_residual), but penalize dead space
    // super-linearly when it falls into an "unusable gap" zone.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Dead-space zones: gaps too small for typical future items.
    // Anything below the minimum item size is pure waste; small gaps
    // (1..~25) are hard to fill; large residuals remain usable.
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Dead space: unusable for any item (min size 10). Heavy penalty.
        score += 80.0 + (10.0 - pr) * 3.0;
    } else if post_residual < 25 {
        // Risky gap: only small items can use it.
        score += 20.0 + pr * 0.8;
    } else {
        // Usable residual: mild preference for tighter fits.
        score += pr * 0.3;
    }

    // Coupling: dead space is worse when the bin is nearly full relative
    // to capacity (little chance of recovery) — already captured, but add
    // a fill-ratio term favoring high utilization.
    let fill = 1.0 - pr / cap;
    score -= fill * 15.0;

    // Last-chance bonus: if this is the ONLY bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open
    // with slack; encourage consolidation.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // It should only win when no open bin offers a decent fit, i.e. when
    // the item would otherwise create dead space. Give the new bin a
    // moderate baseline penalty so existing bins with good fits win.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item is large and would leave a well-shaped residual
        // elsewhere is irrelevant here — instead, if next item is large,
        // opening a fresh bin is attractive (keeps big contiguous space).
        if next_item_size as f64 > 0.5 * cap {
            score -= 20.0;
        }
        // Late in the stream, fewer new bins matter less; consolidate more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Lookahead: if the post_residual exactly accommodates the next item,
    // this placement sets up a perfect follow-up — reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // If post_residual can't fit the next item but this bin could have,
    // slight penalty for fragmenting.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Slight nudge toward bins whose residual is above the mean (keep
    // tight bins tight, use slack bins first).
    let res = bin_residual as f64;
    if res > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space that likely cannot host future items (min item ~1, but small gaps are wasteful).
        if post_residual < 10 {
            score += 60.0;
        }
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Exact match for the next item is excellent.
            if slack == 0.0 {
                score -= 400.0;
            } else {
                score -= 120.0 - slack.min(120.0);
            }
        } else {
            // Next item cannot follow in this bin: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Relative to mean residual: prefer bins whose post residual is near/below mean (compact bins).
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than opening new ones.
    if open_bins_count > 3 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; offset slightly if item is large relative to capacity.
        score += 150.0 - (item_size as f64 / bin_capacity as f64) * 100.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 50.0; // fresh bin can host the next item too
        }
    }

    // Late in stream: waste matters more, prefer tightest fits.
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is excellent.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.5 * next_item_size as f64;
    }
    // Reward bins whose residual can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }
    // Many alternatives: prefer bins with larger residual (keep small holes together).
    if fitting_bins_count > 2 {
        score += 0.3 * (bin_residual as f64 - mean_residual).abs();
    }

    // Prefer bins already below mean residual (consolidate waste).
    score -= 0.2 * (mean_residual - bin_residual as f64);

    // Time horizon: late in the stream, be conservative with new bins.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, slightly less late when open bins are fragmented.
        score += 15.0 + 20.0 * (1.0 - progress) - 0.5 * mean_residual.min(50.0);
    } else {
        score -= 3.0 * progress;
    }

    // Discourage overloading many open bins when item is large.
    if item_size > 60 && bin_residual != bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear waste penalty: quadratic-ish in normalized post residual
    score += 12.0 * norm_pr * norm_pr;

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 8.0 * (0.3 + progress);

    // Smooth coupling with mean residual: prefer bins below mean residual (tighter than average)
    let mr = mean_residual / cap;
    score += 6.0 * (norm_pr - mr) * (norm_pr - mr);
    score -= 4.0 * (mr - norm_pr).max(0.0) * (0.5 + progress);

    // Lookahead: reward if next item can use the post residual exactly-ish
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= next_item_size {
            let gap = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            let gap = (nxt - pr) / cap;
            score += 5.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate (empty bin): penalize mildly unless current bins are poor fits
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count > 0 { (fitting_bins_count as f64).recip() } else { 1.0 };
        score += 8.0 - 6.0 * scarcity * (0.5 + progress);
        // opening a new bin is attractive when open bins have large residuals (fragmented)
        score -= 5.0 * mr / cap;
    }

    // Penalize spreading across many open bins late in stream
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + 2.0 * progress) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo common item sizes
    let classes: [u32; 6] = [10, 20, 25, 30, 40, 50];
    let mut class_bonus = 0.0;
    for c in classes.iter() {
        if post_residual >= *c && post_residual % c == 0 {
            class_bonus += 8.0;
        }
        if post_residual > 0 && post_residual < *c && post_residual % c != 0 {
            class_bonus -= 2.0;
        }
    }
    score -= class_bonus;

    // Penalize dead space: residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Next-item lookahead: reward residuals that exactly fit next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 25.0;
        }
        // Harmonic coupling: next item fits into post_residual with clean division
        if post_residual > 0 && next_item_size > 0 && post_residual % next_item_size == 0 {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * mean_residual;
        if post_residual < 20 {
            score -= 10.0; // fresh bin keeps large residual anyway
        }
    }

    // Prefer filling bins with low residual (close bins sooner)
    score -= 0.3 * (bin_capacity as f64 - bin_residual as f64);

    // Late-stream tightening: minimize waste as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.5;

    // Many open bins: discourage spreading
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical items are wasted.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        // Small unusable gap -> heavy penalty (this bin is a bad choice).
        score += 60.0 + (dead_threshold - post_residual as f64) * 4.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 80.0;
    } else {
        // Reward tight fits relative to capacity.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 25.0;
    }

    // Reward leaving a gap that the lookahead item could fill (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= 15.0 - (leftover as f64).min(15.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creates a gap the next item cannot use -> penalize.
        score += 12.0;
    }

    // Open-bin pressure: prefer existing bins when many bins are open.
    score -= (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Less reluctance to open a bin early in the stream or when open bins are crowded.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 20.0;
        score -= (open_bins_count as f64) * 0.5;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 25.0; // existing bins are cramped; opening new is fine
        }
    }

    // Mild preference for bins whose residual is above the mean (keep balanced bins usable).
    if bin_residual != bin_capacity && (bin_residual as f64) > mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: zero post_residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.45 * gap;
        if post_residual == next_item_size {
            score -= 40.0; // exact 2-step chain match
        }
        // Penalize leaving residual too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
    }

    // Tightness relative to mean residual: prefer filling bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist, unless it enables a perfect chain.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Mild pressure to consolidate as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;

    // Core: penalize leftover space after placement (primary packing pressure).
    let mut score = post;

    // Tight-fit reward: fraction of residual consumed by the item.
    let fill_frac = item / resid.max(1.0);
    score -= 18.0 * fill_frac * fill_frac;

    // Perfect or near-perfect fit bonus.
    if post == 0 {
        score -= 25.0;
    } else if post <= 3 {
        score -= 12.0;
    }

    // Dead-space penalty: leftover space too small for typical future items.
    // Items range 1..100, so leftover < some threshold is often unusable.
    if post > 0.0 && post < 12.0 {
        score += 10.0 * (12.0 - post) / 12.0;
    }

    // Lookahead coupling (k=2): reward leaving room exactly for the next item,
    // penalize leaving awkward room that neither fits nor is zero.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let gap = post - nxt;
            if gap == 0.0 {
                score -= 20.0; // chains perfectly with next item
            } else if gap < 12.0 {
                score += 6.0 * (12.0 - gap) / 12.0; // nearly chains but wastes a sliver
            } else {
                score -= 4.0 * (gap / cap); // roomy leftover still useful
            }
        } else {
            // Next item can't use this bin's leftover; mild penalty scaled by closeness.
            let miss = (nxt - post) / nxt.max(1.0);
            score += 5.0 * miss;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is attractive when the
    // item fits poorly everywhere else, or when open bins are already crowded.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: keeps it competitive only against bad fits.
        let mut new_bin_score = post + 22.0;
        // As the stream progresses and bins accumulate, slightly discourage sprawl.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score += 10.0 * progress * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        // If mean residual across open bins is small (all bins nearly full),
        // opening a new bin is clearly right.
        new_bin_score -= 8.0 * (1.0 - (mean_residual / cap).clamp(0.0, 1.0));
        // If next item is large and this empty bin would serve it perfectly, favor opening.
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            new_bin_score -= 3.0;
        }
        score = new_bin_score;
    } else {
        // Existing-bin context: prefer bins whose residual deviates from the mean
        // in a "consolidating" direction (fill below-average-residual bins first).
        let dev = resid - mean_residual.max(0.0);
        score += 0.05 * dev;
        // Mild pressure to prefer bins with less residual overall (best-fit bias).
        score += 0.03 * resid;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post-residual in [0,1)

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping.
    // Small residuals are good; large residuals are increasingly bad.
    let mut score = x * (1.0 + 0.9 * x + 0.6 * x * x) * cap;

    // Stream-progress coupling: later in the stream, tighten packing more
    // aggressively (dead space matters more as the stream ends).
    let tighten = 0.5 + 1.5 * progress;
    score *= tighten;

    // Reward near-perfect fits: strong subtraction when post_residual is tiny.
    let perfect_bonus = (1.0 - x).powi(6) * 30.0;
    score -= perfect_bonus;

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // heavily reward this placement; if next item cannot fit, mild penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = (pr - nxt) / cap;
            score -= 20.0 * (1.0 - gap).powi(4);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among several candidates, mildly prefer tighter fits (already via x).
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate (empty bin): make it attractive only when no good
    // fit exists — i.e. its raw score is high (x = 1 - item/cap), but allow
    // it to win over very bad fits via a calibration offset.
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * progress;
    }

    // Slight global pressure: many open bins -> prefer consolidating.
    score += 0.15 * (open_bins_count as f64);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's a tighter bin; reward using it.
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: bins whose post_residual lands in
    // "usable" residue classes mod 10 are rewarded (many item sizes 1..100 can
    // later fill them), while odd/prime-ish gaps are penalized.
    let gap = post_residual;
    let gap_mod10 = (gap % 10) as f64;
    let gap_div10 = (gap / 10) as f64;

    // Reward gaps that are multiples of 10 (harmonic alignment with capacity 100)
    if gap % 10 == 0 {
        score -= 8.0 + gap_div10 * 1.5;
    } else if gap % 5 == 0 {
        score -= 4.0;
    } else {
        // penalize awkward residues; larger deviation from nearest multiple of 5
        let dev = gap_mod10.min(10.0 - gap_mod10);
        score += dev * 1.2;
    }

    // Small unusable dead space penalty (harmonic dead zone: gap < 10 is hard to fill)
    if gap > 0 && gap < 10 {
        score += (10 - gap) as f64 * 3.0;
    }

    // Integer division thresholds: reward filling a bin past 50%, 75%, 90%
    let fill = (bin_capacity - gap) as f64 / bin_capacity as f64;
    if fill >= 0.9 { score -= 15.0; }
    else if fill >= 0.75 { score -= 10.0; }
    else if fill >= 0.5 { score -= 5.0; }

    // Lookahead coupling: if next item fits the resulting gap, big reward
    if next_item_size > 0 && next_item_size <= gap {
        let next_mod = (next_item_size % 10) as f64;
        score -= 12.0 - next_mod * 0.3;
    } else if next_item_size > 0 && next_item_size > gap {
        // gap cannot host next item; mild penalty scaled by how far off
        score += ((next_item_size - gap) as f64).min(30.0) * 0.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): penalize so we prefer existing bins,
    // unless the item is huge relative to capacity and bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / bin_capacity as f64).max(0.0).min(1.0);
        // default penalty keeps new bins closed; relax late in stream or when
        // open bins are highly fragmented (high mean residual = poor fits)
        score += 25.0 - 15.0 * fragmentation - 10.0 * progress;
        // opening a fresh bin for a large item is fine (it pairs with future items)
        if item_size >= 60 { score -= 8.0; }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = (post_residual as f64).ln().max(0.0);
        // Gap is "unusable" if smaller than the smallest plausible item (<=10)
        // or smaller than the lookahead item.
        let unusable = post_residual < 10 || (next_item_size > 0 && post_residual < next_item_size);
        if unusable {
            score += 60.0 + dead * 20.0;
        } else {
            score -= dead * 6.0;
        }
    } else {
        // Perfect fit is ideal.
        score -= 80.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Pressure from number of open bins: discourage opening new bins when
    // many are already open; encourage consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 4.0 * progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive if nothing fits well.
    if bin_residual == bin_capacity {
        let good_existing = fitting_bins_count > 0 && (bin_capacity - item_size) >= 0;
        let poor_options = mean_residual < item_size as f64 * 1.15;
        if good_existing && !poor_options {
            score += 90.0; // keep packing into existing bins
        } else {
            score -= 25.0; // allow a fresh bin for a poor-fit situation
        }
    }

    // Lookahead coupling: if next item would fit the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 + (next_item_size as f64 / (post_residual as f64)) * 8.0;
    }

    // Slight preference for bins below mean residual (balance residuals).
    score += ((post_residual as f64) - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive best-fit — tighter residual is better, with amplification.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * 100.0;

    // 2-step lookahead: reward if the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect pairing
        } else if next_item_size <= post_residual {
            // next item fits here: penalize leftover dead space after the pair
            let pair_left = post_residual - next_item_size;
            score += pair_left as f64 * 0.8;
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            score += (next_item_size - post_residual).min(post_residual) as f64 * 0.3;
        }
    }

    // Last chance: strongly favor using the only bin that fits (avoid new bin).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Discourage opening a new bin when open bins give a decent fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 18.0 + (item_size as f64) * 0.2;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 4.0 * tightness * tightness * (item_size as f64);

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 15.0 * dead;
    }

    // Lookahead coupling: bonus if next item fits the post-residual exactly-ish
    if next_item_size > 0 && (post_residual as i64) - (next_item_size as i64) >= 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        score -= 6.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // next item won't fit here; slight penalty for leaving a mid-sized hole
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins that waste less
        score += 0.3 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: make empty bins less attractive unless
    // the fit would be very tight or open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / 10.0;
        let waste = (bin_capacity - item_size) as f64;
        score = 20.0 + 0.4 * waste + crowding * (1.0 - progress) - 30.0 * tightness;
        // opening a new bin is fine late in stream or when many bins are open
        if progress > 0.5 {
            score -= 5.0;
        }
    }

    // Mild preference for bins below mean residual (consolidate waste)
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    } else {
        score += 0.5 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post_residual (tight fit), non-linearly damped.
    let norm_post = post / cap;
    let mut score = norm_post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate loose fits; late, demand tightness.
    let prog_curve = 0.5 + 1.5 * progress * progress;
    score *= prog_curve;

    // Lookahead: reward if next item fits the post residual (smooth quadratic match).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt) / cap;
        if gap >= 0.0 {
            score -= 0.6 * (1.0 - gap * gap) * (1.0 - progress);
        } else {
            score += 0.3 * gap * gap * cap;
        }
    }

    // Penalize creating dead space that no plausible item (10..80 typical) can use.
    let unusable = ((post - 80.0).max(0.0)) / cap;
    score += 2.0 * unusable * unusable;

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 1.2 * (1.0 - progress);
    }

    // New-bin candidate: penalize mildly, scaled by how many bins are already open,
    // but relax late in the stream (spreading load can pay off).
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln() + 1.0;
        score += (0.4 + 0.25 * openness) * (1.0 - 0.5 * progress);
    }

    // Mild alignment with mean residual across open bins: prefer bins whose
    // post-residual moves toward the mean (balances future fits).
    score += 0.15 * (post - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
