pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward perfect fits strongly
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward residual close to next item size (lookahead coupling)
    if next_item_size > 0 && post_residual >= next_item_size {
        let diff = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - diff / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0; // dead space relative to lookahead
    }

    // Open bins pressure: discourage spreading when many bins open
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize slightly so it only wins on very poor fits
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.1;
    }

    // Tight-fit reward: item filling most of the bin
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with non-linear penalty
    // on large dead space (squaring amplifies wasted capacity).
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // 2-step lookahead: strongly reward bins whose post_residual can hold
    // the next item (perfect chain fit).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            // Exact match bonus (post_residual == next_item_size is ideal).
            let gap = (post - next) / bin_capacity as f64;
            score -= 30.0 * (1.0 - gap);
            // Extra bonus if next item fills the bin completely afterward.
            if (post - next).abs() < 1e-9 {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here: penalize leaving awkward residual.
            score += 10.0 * (next - post) / bin_capacity as f64;
        }
    } else {
        // Last item: just minimize residual.
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Compare residual against mean residual across open bins: prefer bins
    // that are already more filled than average (consolidation).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Mild preference to fill bins when many bins are open (reduce spread).
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Early in stream: be slightly more willing to open new bins for large
    // items (keeps flexibility); late in stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless item is large or no good fit exists.
        score += 15.0 - 10.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no typical item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: bonus if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 / (1.0 + slack);
        } else {
            score += 6.0; // next item won't chain here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: discourage spreading, favor consolidation into fuller bins.
    let pressure = (open_bins_count as f64) / (1.0 + total_items as f64);
    score += 40.0 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // Mean residual deviation: prefer bins close to mean residual to keep balance,
    // but only mildly; late in the stream prefer fuller bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early stream, be tolerant; late stream, be greedy for tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress * tightness;

    // New-bin candidate: neutral-ish baseline, only attractive when fits are bad.
    if bin_residual == bin_capacity {
        let best_possible = 100.0;
        score = 55.0 + 0.5 * (post_residual as f64)
            - 20.0 * (fitting_bins_count as f64).recip()
            + 10.0 * progress;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
        let _ = best_possible;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear shrinkage of large dead space later in the stream.
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr * norm_pr);

    // Reward tight fits (post_residual near zero) with smooth quadratic bonus.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 20.0 * progress);

    // Penalize leaving a hole smaller than the next item (smooth logistic coupling).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let gap = ni - pr;
        let sig = 1.0 / (1.0 + (-gap / 10.0).exp());
        score += 15.0 * sig;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild penalty when bin residual deviates from mean residual (encourage balance).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // New-bin candidate: penalize slightly more as stream progresses unless item is large.
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: quantize dead space into capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as u32; // 0..=10 harmonic class
    // Penalize classes that are hard to reuse: small but nonzero residuals
    score += match class {
        0 => -50.0,
        1 => 60.0,   // residual <=10: nearly dead space
        2 => 40.0,
        3 => 20.0,
        4 => 5.0,
        5 => -10.0,  // half-full leftover is very reusable
        6 => 0.0,
        7 => 5.0,
        8 => 10.0,
        9 => 15.0,
        _ => -5.0,
    } as f64;

    // Lookahead: does next item fit into post_residual? Strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 80.0 + (next_item_size as f64) * 0.3;
        // extra reward if next item exactly fills post_residual
        if next_item_size == post_residual {
            score -= 120.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space relative to lookahead
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Prefer bins that are already quite full (tight packing)
    let tightness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= tightness * 40.0;

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        let good_fit_exists = post_residual == 0 || (next_item_size > 0 && next_item_size <= post_residual);
        score += if good_fit_exists { 500.0 } else {
            // opening new bin is OK if residual would be small class-1 dead space
            120.0 + mean_residual * 0.5
        };
    }

    // Mild coupling with mean residual: prefer bins below mean residual (fuller bins)
    score += (mean_residual - post_residual as f64).max(0.0) * -0.5;

    // Stream progression: later in stream, be greedier about perfect fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.0 + progress * (post_residual == 0) as i32 as f64 * 50.0;

    // Modulo-based harmonic penalty on post_residual: residuals divisible by common item sizes are reusable
    if post_residual > 0 && (post_residual % 10 == 0) {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 12.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 2.0 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (tight fit).
    score += 0.3 * (bin_residual as f64 - item_size as f64).abs();

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would not fit here but could fit elsewhere, slight penalty.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Mean residual coupling: avoid bins far below mean residual (fragmented bins).
    score += 0.2 * (mean_residual - post_residual as f64).abs();

    // New-bin candidate baseline: neutral-ish, only chosen when fits are bad.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 == next {
            score -= 60.0; // perfect chained fit
        } else if post_residual >= next_item_size {
            let slack = post_residual as f64 - next;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize proportionally to wasted potential
            score += 15.0 * (next - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Compare post_residual relative to mean residual of open bins.
    let diff = post_residual as f64 - mean_residual;
    score += 0.8 * diff;

    // Tight fit reward: small post_residual is good unless it's a dead sliver.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += 12.0; // unusable sliver penalty
    } else {
        score -= 10.0 * (1.0 - pr / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize spreading across too many open bins when plenty of alternatives exist.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Early in stream: encourage filling bins densely to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.3 * pr;

    // New-bin candidate: prefer it only when this bin would leave a large awkward gap.
    if bin_residual == bin_capacity {
        score -= 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let nxt = next_item_size as f64;

    // Core: prefer tight fits (small post residual).
    let mut score = post;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize creating dead space that no plausible item can use.
    // Items in [1,100]; small post_residual is more likely reusable.
    let reusability = (post / cap).powi(2); // small post -> small penalty term
    score += 40.0 * reusability;

    // Lookahead coupling: if next item fits in the post residual, bonus;
    // if post residual is just barely below next item, extra penalty (teasing gap).
    if next_item_size > 0 && post_residual > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 10.0 {
                score += 10.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 3.0 * (open_bins_count as f64).ln().max(0.0) * (resid / cap);

    // Global state: if mean residual is large, prefer bins below mean residual
    // (drain the emptiest bins first) to close bins out.
    if resid < mean_residual {
        score -= 8.0 * (1.0 - resid / mean_residual.max(1.0));
    }

    // Time horizon: late in the stream, be greedier about tight fits;
    // early, keep flexibility by mildly penalizing very small post residuals
    // only when lookahead is unknown.
    if next_item_size == 0 {
        score -= 20.0 * progress;
    } else {
        score += 6.0 * progress * (1.0 - reusability);
    }

    // New-bin candidate: neutral-ish baseline so it wins only when all open bins
    // score poorly (poor fits / dead space creation).
    if bin_residual == bin_capacity {
        score = 45.0 + 10.0 * (1.0 - progress) - 15.0 * (fitting_bins_count as f64).min(5.0) / 5.0;
        if next_item_size > 0 && next_item_size as u32 >= item_size {
            score -= 8.0; // big next item: fresh bin attractive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;

    // Base: reward tight fits via smooth nonlinear decay of post residual.
    let mut score = post_norm * (1.0 + 0.8 * post_norm * post_norm);

    // Non-linear coupling with stream progress: late in stream, waste is costlier.
    score *= 1.0 + 1.2 * progress * (1.0 - post_norm) * (1.0 - post_norm);

    // Penalize bins whose residual deviates from mean residual (smooth quadratic coupling).
    let dev = (post - mean_residual) / cap;
    score += 0.35 * dev * dev;

    // Last-chance bonus: strongly prefer using the only fitting bin (smooth sigmoid-like factor).
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 1.0 / (1.0 + 0.6 * (fitting_bins_count as f64 - 1.0)) };
    score -= 4.0 * last_chance * (1.0 - post_norm);

    // Lookahead coupling: if next item fits into post residual, reward; else penalize smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (post - nxt) / cap;
        if fit_gap >= 0.0 {
            score -= 1.5 * (fit_gap * (1.0 - fit_gap)) * (1.0 + progress);
        } else {
            score += 0.8 * (-fit_gap) * (1.0 + 0.5 * progress);
        }
    }

    // Mild penalty for proliferating open bins relative to stream length.
    score += 0.05 * (open_bins_count as f64 / (1.0 + total_items as f64 * 0.01));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * 1.0;

    // Harmonic class of the post residual: modulo classes of capacity fractions.
    let class = post_residual % (bin_capacity / 10).max(1);
    match class {
        0 => score -= 25.0,                 // exact multiple: perfectly reusable slot
        1 | 3 | 7 | 9 => score -= 8.0,      // near-multiple classes still pair well with small items
        _ => score += 4.0,                  // awkward mid-class dead space
    }

    // Integer-division thresholds on post_residual: which harmonic band does it land in?
    let band = post_residual / (bin_capacity / 4).max(1);
    match band {
        0 => score += 18.0,                 // tiny residual: nearly sealed bin, low value lost
        1 => score -= 2.0,
        2 => score -= 6.0,
        _ => score -= 10.0,                 // large residual left: bin stays highly usable
    }

    // Lookahead coupling: does next_item_size fit harmonically into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            // next item fits exactly into the leftover: strong reward, scaled by tightness
            let tight = 1.0 - (post - nxt) / cap_f;
            score -= 30.0 * tight;
            // modulo harmony: next item divides residual into a clean class
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 15.0;
            }
        } else {
            // next item cannot use this residual: penalize leaving big useless gaps
            score += 0.35 * (post_residual as f64 - (cap_f - nxt)) * 0.5;
        }
        // next item is large: prefer conserving residual in open bins
        if next_item_size > bin_capacity / 2 {
            score += 0.15 * post;
        }
    }

    // Penalize poor fits relative to mean residual of open bins.
    if post > mean_residual {
        score += 0.25 * (post - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a fresh bin wastes the residual of all open bins.
    if bin_residual == bin_capacity {
        let waste = open_bins_count as f64 * mean_residual * 0.5;
        score = cap_f + waste;
        // Early in the stream or when nothing fits, opening a bin is fine.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
    }

    // Prefer consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64 * (post / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item (min item size 1, but small gaps under ~12 are nearly dead)
    // are heavily penalized.
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward tight fits (waste ratio small).
    let waste_ratio = post_residual as f64 / cap;
    score -= (1.0 - waste_ratio) * 10.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins would leave
    // large unusable gaps or when open-bin pressure is high.
    if bin_residual == bin_capacity {
        // Base penalty: prefer filling existing bins when they fit well.
        score += 20.0;
        // If placing in an open bin would leave a dead gap, new bin becomes better.
        if bin_residual >= item_size && (bin_residual - item_size) < 12 && bin_residual - item_size > 0 {
            score -= 35.0;
        }
        // Open-bin pressure: many open bins with high mean residual -> consolidate.
        if open_bins_count > 4 && mean_residual > 40.0 {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item would not fit in post residual but fits in residual, slight
    // penalty for blocking the lookahead.
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Usable leftover: next item can still fit afterwards.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.3;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: residual smaller than next item but nonzero.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Penalize tight fits that leave very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward exact fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Relative to mean residual: prefer bins that are already low relative to average.
    score += (mean_residual - bin_residual as f64) * 0.2;

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Mild penalty when many bins are open; encourage filling existing ones.
    score += open_bins_count as f64 * 0.1;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 10.0 + (fitting_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly discount bins whose post-residual is small.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 60.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Prefer bins with residual above the mean (keeps small bins for small items).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // Mild preference to fill existing bins rather than open new ones as stream grows.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as the stream progresses and many bins are open.
        score += 15.0 + 40.0 * progress + 0.8 * open_bins_count as f64;
    } else {
        score -= 5.0 * progress;
    }

    // Prefer closing out nearly-empty bins.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let rn = r / cap;
    let is_new = (bin_residual == bin_capacity) as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    let poly = rn * rn * (1.0 - progress) + rn * (0.5 + progress);

    // Reward tight fits (small post_residual) more strongly later in stream.
    let tight_reward = -2.0 * (1.0 - rn) * (1.0 - rn) * (0.5 + progress);

    // Penalize dead space that cannot fit the next item.
    let dead = if next_item_size > 0 && r < next_item_size as f64 {
        (next_item_size as f64 - r) / cap
    } else {
        0.0
    };

    // Last-chance bin bonus: strongly favor using the only fitting bin.
    let last_chance = if fitting_bins_count == 1 && is_new == 0.0 {
        -3.0 * (1.0 - rn)
    } else {
        0.0
    };

    // Mild penalty for opening new bins when open bins fit well.
    let new_bin_pen = is_new * (1.5 + 2.0 * progress * (1.0 - rn));

    let mut score = r + poly * 2.0 + tight_reward * 4.0 + dead * 10.0 + last_chance + new_bin_pen * cap * 0.1;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into capacity fractions.
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Penalize leftovers that fall into "dead" classes: too small to host typical items.
    // Class boundaries at 1/5, 1/3, 1/2 of capacity via integer-division-like thresholds.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, ideal
    } else if post_residual < bin_capacity / 5 {
        // dead space class (1..20): nearly unusable
        score += 45.0 * (1.0 - post_frac * 5.0);
    } else if post_residual < bin_capacity / 3 {
        // small class (21..33): usable only by tiny items
        score += 12.0;
    } else if post_residual < bin_capacity / 2 {
        // medium class (34..50): decent
        score -= 5.0;
    } else {
        // large class: plenty of room, but wasteful now
        score -= 10.0;
    }

    // Lookahead coupling: reward if next item fits exactly into the projected residual,
    // penalize if next item is stranded.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // modular harmony: leftover after chaining the next item
            let chain = post_residual - next_item_size;
            score -= (chain as f64) * 0.35;
            if chain < bin_capacity / 5 {
                score += 6.0; // chaining creates a new dead class
            }
        } else {
            // next item cannot use this bin's residual: dead space persists
            score += (next_item_size as f64 - post_frac * cap) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: keep it competitive only when open bins are crowded or this is a big item.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bias = 30.0 - 55.0 * crowded - 20.0 * (item_size as f64 / cap) - 15.0 * progress;
        score += bias.max(-20.0).min(45.0);
    }

    // Mild preference for filling bins close to the mean residual (balance avoidance of many near-empty bins).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Slight penalty per open bin to encourage consolidation.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 - 4.0 * post_residual as f64;
    }
    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward tightness relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Dead space as fraction of bin: penalize leaving large unusable chunks
    // when the next item cannot use the leftover space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }
    // If the next item fits exactly in the leftover, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Open-bin pressure: prefer closing out bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Mean residual coupling: placing into a bin below mean residual
    // (tighter bin) is preferred to consolidate space.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it unattractive unless all open bins are
    // nearly full or the item is huge relative to typical residual.
    if bin_residual == bin_capacity {
        let avg_open_res = if open_bins_count > 0 { mean_residual } else { bin_capacity as f64 };
        // Open a new bin only when existing residuals are too tight on average.
        score += 25.0 + 0.4 * avg_open_res;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: new bin is mandatory
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact fits (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits perfectly into the post-residual,
    // this placement is ideal (chains two items into one bin).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Next item fits (but not exactly): still good, mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + (post_residual - next_item_size) as f64 * 0.2;
    }
    // Next item does NOT fit into the leftover: penalize wasted residual,
    // scaled by how close the next item is to fitting (frustration penalty).
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 2.0;
    }

    // Compare residual to mean residual across open bins:
    // filling a bin with more residual than average is good (tightens big bins),
    // leaving a residual much larger than mean is wasteful.
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    score += (post_residual as f64 - mean_r) * 0.5;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    // Penalize opening a new bin unless it's a perfect or near-perfect fit
    // for the current or next item.
    if bin_residual == bin_capacity {
        score += 150.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
        if item_size >= 80 {
            score -= 120.0; // large items are fine in fresh bins
        }
        // As the stream progresses, prefer closing out open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Mild preference for tighter bins when many bins are open.
    score += (post_residual as f64 / bin_capacity as f64) * (open_bins_count as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = fitting_bins_count as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: prefer tight fits (small post residual), with a mild convex penalty
    // so that very small residuals are extra attractive (near-perfect packing).
    let mut score = post + 12.0 * (post / cap) * (post / cap);

    // Dead-space penalty: residual too small to ever hold a future item (items >= 1)
    // is fine, but residual in an awkward mid-range wastes capacity.
    if post > 0.0 && post < 10.0 {
        score += 6.0; // small but unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid proliferation of bins).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    } else if fitting_bins_count >= 2 {
        // Multiple options: mild reward for using an already-crowded bin,
        // keeps bin count low.
        score -= 2.0 * (fit - 1.0).min(5.0);
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement chains beautifully — reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let waste = post - nxt;
            score -= 15.0 * (1.0 - waste / cap);
        } else {
            // Next item won't fit here afterwards; slight penalty proportional
            // to how far off it is, encouraging saving bigger bins.
            score += 4.0 * ((nxt - post) / cap);
        }
    }

    // Global state coupling: when mean residual across open bins is high,
    // we should be filling existing bins rather than opening new ones.
    let mean_r = mean_residual;
    if bin_residual < bin_capacity {
        // Reward placing into bins below mean residual (tighter bins first),
        // keeps a set of "fresher" bins available.
        if (bin_residual as f64) < mean_r {
            score -= 5.0;
        } else {
            score += 2.0;
        }
    }

    // New-bin candidate handling: bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Early stream: opening bins is cheap-ish, allow exploration.
        // Late stream: strongly discourage new bins unless fit is terrible.
        let open_penalty = 20.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        score += open_penalty;
        // But if no open bin fits well (post residual large), new bin becomes
        // relatively attractive — reduce penalty when item is large.
        score -= 0.25 * item_size as f64;
    }

    // Time horizon modulation: as the stream nears its end, prioritize
    // minimizing current bin count even more (no future to amortize).
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: penalize leftover space, non-linearly (waste grows quadratically).
    let mut score = post + 0.015 * post * post / cap;

    // Reward tight fits: small post_residual gets a bonus, amplified late in stream.
    let tightness = 1.0 - post / cap;
    score -= (1.5 + 2.5 * progress) * tightness * tightness * cap * 0.05;

    // Penalize bins whose residual deviates badly from mean residual (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev * (0.5 + progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 4.0 + 3.0 * (1.0 - post / (next_item_size as f64 + 1.0)).max(0.0);
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty for leaving awkward residue.
        score += 0.03 * post * (1.0 - progress);
    }

    // Late-stream: consolidate; discourage spreading across many bins.
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 + 3.0 * progress) * 0.5;

    // New-bin candidate: neutral-ish early, penalized late (prefer filling existing bins),
    // but attractive when item is huge and fits perfectly in a fresh bin.
    if bin_residual == bin_capacity {
        let perfect = (item_size as f64 / cap - 1.0).abs() < 1e-9;
        score += 6.0 + 10.0 * progress - if perfect { 20.0 } else { 0.0 };
        if next_item_size as f64 > cap * 0.7 {
            score -= 3.0; // reserve space strategy for big upcoming item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "nice"
    // residue classes (multiples of common item sizes) are more reusable.
    let pr = post_residual;
    let harmonics = (pr % 10 == 0) as f64 * 6.0
        + (pr % 5 == 0) as f64 * 3.0
        + (pr % 20 == 0) as f64 * 4.0
        + (pr % 25 == 0) as f64 * 3.0
        + (pr % 50 == 0) as f64 * 4.0;
    score -= harmonics;

    // Penalize dead space: post_residual too small for the smallest item (1..=10)
    if pr > 0 && pr < 10 {
        score += 25.0;
    }
    // Reward near-perfect fits
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 / (1.0 + slack / 10.0);
        } else {
            // next item cannot use this bin's leftover; penalize large leftovers a bit
            score += (pr as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it unattractive unless current bin fit is terrible.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        // good fit (small post_residual) -> new bin loses; bad fit -> new bin wins
        score += 15.0 + fit_quality * 60.0;
        // early stream: slightly favor consolidating into existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 5.0;
    }

    // Prefer filling bins that are already relatively full (small residual).
    score += (bin_residual as f64) * 0.02;

    // Mean-residual coupling: when open bins are loose on average, reward tight fits more.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;

    // Integer-division threshold on residual class: leftover >= 50 is versatile.
    if pr / 25 >= 2 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 12.0; // barely usable gap, mildly penalized
    }

    // Tightness reward: fraction of residual consumed by this item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Open-bin pressure: discourage scattering into many bins when plenty fit elsewhere,
    // but encourage using a nearly-full last-chance bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0; // last chance: strongly prefer this bin
    }
    if open_bins_count > 8 {
        score += 2.0 * (open_bins_count as f64 - 8.0); // consolidate when too many bins open
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0 + 1.5 * open_bins_count as f64;
        // If no open bin fits at all, opening is fine (fitting_bins_count includes new bin).
        if fitting_bins_count <= 1 {
            score -= 50.0;
        }
    }

    // Lookahead: favor residuals that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 10.0; // gap too small for the known next item
        }
    }

    // Late-stream consolidation: as the stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild alignment with mean residual: prefer bins below-average full (larger residual use).
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to tightness
            score -= 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // next item cannot use the residual: penalize dead space
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize bins that are too far below the mean residual (wasteful choice)
    score += 0.2 * (mean_residual - post_residual as f64).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate handling: keep empty bins attractive unless an open bin fits well
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
    }

    // Late-stream tightness: as stream progresses, prefer tighter fills
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to hold a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty for fragmenting.
            score += 5.0;
        }
    }

    // Time horizon: late in the stream, prefer closing bins tightly rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * fit_ratio;

    // Global state: many open bins with large mean residual -> discourage opening new bins,
    // encourage using bins with above-average residual.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when plenty of open bins exist or mean residual is high.
        score += 10.0 + 0.15 * open_bins_count as f64 + 0.3 * mean_residual;
        // But if no existing bin fits well (post_residual would be tiny elsewhere), new bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else if (bin_residual as f64) >= mean_residual {
        score -= 5.0;
    }

    // Mild penalty for very full bins early on (save tight fits for small items),
    // but reward them late when consolidation matters.
    let fullness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fullness * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 - prn) * (1.0 + progress);
    score -= 12.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - prn;
    score -= tightness * tightness * (2.0 + 6.0 * progress);

    // Penalize creating dead space below next item size
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr < n {
            score += (n - pr) * (0.5 + progress);
        } else {
            // reward leaving space that the next item could use
            score -= 1.5 * (1.0 - (pr - n) / cap) * (pr - n) / cap;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 1.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Prefer bins with residual below mean (consolidating fullness)
    score += 0.3 * (mean_residual - pr) * (0.5 + progress);

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.1 * open_bins_count as f64 + 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead-space quality via modulo arithmetic.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Class A: post_residual is an exact divisor-friendly residue (fits common small items)
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else {
        // modulo classes: residuals divisible by 10 are "harmonic" with item granularity
        if pr % 10 == 0 {
            score -= 12.0;
        }
        if pr % 20 == 0 {
            score -= 8.0;
        }
        // awkward odd residuals are dead space
        if pr % 2 == 1 {
            score += 6.0;
        }
        // tiny dead space (1..=5) is nearly perfect
        if pr <= 5 {
            score -= 25.0;
        }
        // large leftover waste
        if pr > 50 {
            score += (pr as f64 - 50.0) * 0.4;
        }
    }

    // Coupling with lookahead item: reward residuals that exactly or closely fit next_item_size
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // chain fill
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack <= 5 {
                score -= 15.0;
            } else {
                score -= (10.0 * (1.0 - slack as f64 / cap)).max(0.0);
            }
        } else {
            // next item cannot fit here: mild penalty scaled by overshoot
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Empty new-bin candidate: penalize mildly so it's chosen only when fits are poor,
    // but reward it when item is large and residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 25.0 - 20.0 * fragmentation - 10.0 * progress;
        if item_size >= 60 {
            score -= 10.0; // large items deserve fresh bins
        }
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone: f64 = 9.0;
    if post_residual > 0 && (post_residual as f64) <= dead_zone {
        score += (dead_zone - post_residual as f64 + 1.0) * 25.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual was already small (tight packing tendency).
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.15;

    // Open-bin pressure: prefer consolidating into fewer bins when many are open.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin fits poorly
    // (post_residual small/dead) or when the next item could use the fresh bin better.
    if bin_residual == bin_capacity {
        let base = 55.0;
        // Penalize opening new bins when there are many open bins already.
        let mut new_score = base + (open_bins_count as f64) * 2.0;
        // Reward opening a new bin if next item is large and current fit leaves dead space.
        if next_item_size > 0 && post_residual > 0 && (post_residual as f64) <= dead_zone {
            new_score -= 30.0;
        }
        if next_item_size > 0 && next_item_size <= 10 {
            new_score += 10.0; // tiny next item wastes a fresh bin
        }
        return new_score;
    }

    // Lookahead: favor leaving room for the next item if it fits the post-residual well.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 5.0;
    }

    // Mild normalization with stream progression and mean residual.
    score -= mean_residual * 0.05;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward perfect match where next item fills post_residual exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-item completion
        } else if post_residual > next_item_size {
            // next item fits, but leaves a new gap: penalize by remaining gap size
            score -= 15.0;
            score += (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot fit in post_residual: dead space risk
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Penalize tiny unusable residual (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins tighter than average (best-fit flavor)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when open bins are all poor fits
    if bin_residual == bin_capacity {
        // base cost of opening a bin, discounted when many bins open / late stream
        score += 45.0;
        score -= (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin can host both items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Penalize residual values that are awkward (small but nonzero dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual < next_item_size {
            // dead space that next item cannot use; mild penalty scaled by how close
            let waste_ratio = post_residual as f64 / (next_item_size as f64).max(1.0);
            score += 6.0 * (1.0 - waste_ratio.min(1.0));
        }
    }

    // Penalize opening a new bin, more so when many bins are already open.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if no open bin fits well (post_residual large relative), relax penalty.
        if post_residual as f64 > mean_residual.max(1.0) {
            score -= 10.0;
        }
    }

    // Prefer filling bins that are already mostly used (small residual).
    score += 0.05 * bin_residual as f64;

    // Time horizon: early in stream, be more conservative about new bins; late, exploit tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * tightness;

    // Deviation from mean residual: prefer bins below mean residual (more filled).
    score += 0.08 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;
    let fit_frac = if open_bins_count > 0 { fitting_bins_count as f64 / open_bins_count as f64 } else { 0.0 };
    let item_frac = item_size as f64 / cap;
    let next_frac = next_item_size as f64 / cap;

    let mut score = post;

    // Non-linear waste penalty: quadratic in normalized residual, modulated by stream progress
    score += norm_post * norm_post * cap * (0.5 + 0.8 * progress);

    // Cubic dead-space term for very small residuals (hard to fill later)
    score += norm_post.powi(3) * cap * 1.2;

    // Reward tight fits (small post_residual relative to item)
    score -= item_frac * cap * 0.6 * (1.0 - norm_post);

    // Scarcity bonus: if this is nearly the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    } else {
        score += (1.0 - fit_frac) * 5.0;
    }

    // Lookahead coupling: penalize if post_residual can't fit next item but another bin could
    if next_item_size > 0 {
        if post >= next_item_size as f64 {
            score -= 4.0 * next_frac;
        } else {
            score += 3.0 * next_frac * (1.0 - post / (next_item_size as f64 + 1.0));
        }
    }

    // Mean-residual divergence: prefer bins deviating below mean residual (tighter bins)
    score += (mean_residual - post) * 0.15;

    // Mild pressure against hoarding many open bins early
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual after placement: classify dead space
    // by quarters of the capacity. Small post_residual = tight fit = good.
    let quarter = bin_capacity / 4;
    match post_residual {
        0 => score -= 60.0,                       // perfect fill
        r if r <= quarter / 2 => score -= 40.0,   // near-perfect
        r if r <= quarter => score -= 20.0,       // good
        r if r > bin_capacity - quarter && r < bin_capacity => {
            // bin was nearly empty before: wasteful use
            score += 25.0;
        }
        _ => {}
    }

    // Modulo-arithmetic class: residual divisible by small harmonics is
    // more reusable by typical item sizes.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 5 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 6.0; }
        // residual too small for any item (min size 1 handled by dist,
        // but for sizes >=10 style streams penalize < 10 dead space)
        if post_residual < 10 { score += 5.0; }
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward; if it cannot fit any future item, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; residual becomes dead unless small
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: prefer reusing an existing bin unless
    // open bins are very fragmented (high mean residual spread) or we
    // already have many bins and the fit is poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = cap * 0.9;
        if fitting_bins_count == 0 { score -= cap * 0.5; } // no alternative
        if open_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 10.0;
        }
        // late in the stream, avoid spawning bins for marginal reasons
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    } else {
        // slight preference to balance load across bins: favor bins with
        // residual close to the mean (harmonic centering)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    // Integer-division threshold on post_residual: reward when residual
    // falls into a "useful slot" class (can host a mid-size item).
    let slot = post_residual / 20; // classes: 0..5
    score -= match slot {
        0 => 12.0,
        1 => 10.0,
        2 => 6.0,
        3 => 2.0,
        _ => 0.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the smallest item class
    // are effectively wasted -> heavy penalty, escalating as gap shrinks.
    let dead_zone = 20.0;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 4.0;
    }

    // Reward near-perfect fits (residual <= 5).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 12 {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins are fragmented
    // (high mean residual spread) or many bins are already open.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
        let fragmentation = (mean_residual - (cap - item_size as f64)).abs() * 0.5;
        score += 40.0 + pressure - fragmentation;
    }

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this placement sets up a perfect chain -> big reward.
    if next_item_size > 0 && post_residual as f64 == next_item_size as f64 {
        score -= 35.0;
    } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 5.0;
    }

    // Open-bin pressure: mildly discourage adding to already-crowded state
    // unless the fit is tight (tight fits already discounted above).
    score += (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
