pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: fraction of stream completed
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward small post_residual relative to capacity
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * (1.0 - fit_ratio); // penalize both huge and tiny wastes asymmetrically later

    // Reward near-perfect fits strongly
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Penalize creating dead space that no typical item can fill
    if post_residual > 0 && post_residual < 10 {
        score += 35.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.3 * next_item_size as f64;
        } else {
            // penalize leaving residual that next item nearly fits but not quite
            let gap = next_item_size as f64 - post_residual as f64;
            if gap > 0.0 && gap < 10.0 {
                score += 12.0;
            }
        }
    } else {
        // last item: minimize residual as much as possible
        score -= 20.0 * (1.0 - fit_ratio);
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Crowding: many open bins -> prefer filling existing ones over opening new
    let crowding = open_bins_count as f64 / (1.0 + t * 10.0);
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin baseline: capacity residual, plus penalty scaled by crowding and progress
        score = bin_capacity as f64 * 0.9 + 8.0 * crowding.min(12.0) + 20.0 * t;
        // If no other bin fits at all, opening new bin is fine
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        // If mean residual across open bins is large, avoid new bin
        score += 0.4 * mean_residual;
    } else {
        // Reward using bins with residual below mean (compact bins first)
        let dev = mean_residual - bin_residual as f64;
        score += 0.25 * dev; // lower residual than mean -> dev positive -> lower score
        // Slight preference for opening fewer bins early vs late
        score -= 5.0 * (1.0 - t);
    }

    // Global regularization: keep magnitude bounded
    score = score.max(-200.0).min(400.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer minimal post-residual, with non-linear emphasis on tight fits.
    let tightness = (post / cap).powf(2.0 + 2.0 * progress);
    let mut score = post * (1.0 + 0.5 * tightness);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, leftover space is valuable; late, waste hurts more.
    let waste_penalty = (post / cap).powi(3) * (0.5 + 3.0 * progress * progress);
    score += 40.0 * waste_penalty;

    // Reward bins that are already fragmented (low residual relative to mean)
    // to consolidate open bins rather than spreading across many.
    let consolidation = ((mean_residual - post) / cap).max(0.0);
    score -= 15.0 * consolidation * (1.0 + progress);

    // Penalize opening a new bin, more so as the stream progresses.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        score += 25.0 + 20.0 * progress;
        // But if no open bin fits well, allow new bin when post_residual would be small.
        if fitting_bins_count == 0 {
            score -= 30.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bonus: this is the only fitting bin; strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // Lookahead: if next item could fill this bin's post-residual exactly, reward.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        if post >= next_item_size as f64 {
            score -= 12.0 * (1.0 - gap / cap).max(0.0);
        } else {
            score += 8.0 * (gap / cap);
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "nice"
    // classes (multiples of common item sizes) are more reusable.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit, always great
    } else if pr % 10 == 0 {
        -18.0
    } else if pr % 5 == 0 {
        -8.0
    } else if pr < 10 {
        25.0 // dead space below min item size
    } else {
        0.0
    };

    // Integer-division threshold: how many "average" items still fit.
    let slots = pr / 20; // coarse slot count
    let slot_bonus = -(slots as f64) * 4.0;

    // Lookahead coupling: reward residuals that can host the next item exactly
    // or with tiny waste.
    let lookahead = if next_item_size > 0 {
        if next_item_size == pr {
            -30.0
        } else if next_item_size <= pr {
            let waste = pr - next_item_size;
            if waste % 10 == 0 { -12.0 } else if waste < 10 { 10.0 } else { -4.0 }
        } else {
            6.0 // next item won't fit here anyway; residual quality matters less
        }
    } else {
        0.0
    };

    // Last-chance bin: strongly prefer using it over opening a new bin.
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -35.0
    } else {
        0.0
    };

    // New-bin candidate: only attractive when current bin fit is terrible
    // (large post_residual waste relative to capacity) or late in stream.
    let new_bin_penalty = if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_ratio = post_residual as f64 / cap_f;
        // base cost of opening a bin, reduced if existing fit is bad
        55.0 - 70.0 * waste_ratio - 10.0 * progress
    } else {
        0.0
    };

    // Tightness coupling: bins with residual close to item_size are great fits.
    let tightness = -((bin_residual as f64 - item_size as f64) / cap_f) * 20.0;

    // Mean-residual regularization: prefer bins near the mean (avoid stranding outliers).
    let mean_pull = ((post_residual as f64 - mean_residual).abs()) * 0.15;

    score += class_bonus + slot_bonus + lookahead + last_chance + new_bin_penalty + tightness + mean_pull;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the next item are "dead".
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Unusable for the lookahead item: harsh penalty scaled by how close
            // the dead gap is to being useful (wasting a nearly-fitting gap is worse).
            let gap_deficit = (next_item_size - post_residual) as f64;
            score += 40.0 + 2.0 * gap_deficit;
        } else {
            // Usable gap for the next item: reward proportionally.
            score -= 6.0 + 0.05 * next_item_size as f64;
        }
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Zero residual is perfect: extra reward.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading onto new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 8.0 + pressure;
    } else {
        // Slight reward for reusing existing bins, scaled by open-bin count.
        score -= 1.0 + 0.2 * pressure;
    }

    // Discourage bins whose residual deviates far below the mean (fragmented bins).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (-gap / 20.0).exp();
        // Exact match for the next item is excellent
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual too small for next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (post_residual as f64);
        }
    }

    // Compare against mean residual: prefer bins that are already below-average filled
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 45.0;
        // Opening fresh is good if the item is huge and lookahead is large
        if item_size > 70 && next_item_size > 60 {
            score -= 55.0;
        }
        // Fewer open bins -> cheaper to open new
        score -= 2.0 * open_bins_count as f64;
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let cap = bin_capacity as f64;
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 18.0 * tight * tight;

    // Penalize dead space that is too small to hold any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here; slight penalty for leaving awkward gap
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    } else {
        score -= 1.5;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep flexibility); late in the stream, fill existing bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tight;

    // New-bin candidate: only attractive when current bin is a poor fit
    // or when many bins are already open and this is an early step.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // Cheaper to open a bin early (future placements benefit).
        score -= 20.0 * (1.0 - progress);
        // If no existing bin can fit (fitting count refers to open bins),
        // opening a new bin is necessary: remove the cost.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= 50 {
            score -= 8.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * t) - norm_pr * norm_pr * norm_pr * (1.0 + t * t);
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + t);

    // Lookahead: reward residuals that can host the next item, smoothly
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * (1.0 - slack * slack) * (0.4 + 0.6 * t);
    } else if next_item_size > 0 {
        score += 8.0 * (1.0 + t);
    }

    // Penalize waste relative to mean residual (smooth coupling)
    score += 6.0 * (norm_pr - mean_residual / cap).abs() * (1.0 + t);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - 0.5 * t);
    }

    // New-bin candidate: penalize opening bins early, allow later when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - t) + 5.0 * norm_item;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Mild penalty for many open bins, smoothed
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Class boundaries: residual in (0,10], (10,25], (25,50], (50,100)
    // Small residuals are "dead space" — penalize them extra.
    if post_residual == 0 {
        score -= 40.0; // perfect fit, strongly reward
    } else if post_residual <= 10 {
        score -= 12.0; // near-perfect fit
    } else if post_residual <= 25 {
        score += 4.0; // mildly awkward leftover
    } else if post_residual <= 50 {
        score += 10.0;
    } else {
        score += 16.0; // half-empty bin: poor packing
    }

    // Modulo arithmetic on post_residual vs common item sizes (10..80 multiples / classes)
    // Reward residuals that are congruent to likely future item sizes.
    let mut congruent_bonus = 0.0;
    for k in 1..=8 {
        let s = k * 10;
        if s <= post_residual {
            let d = post_residual - s;
            congruent_bonus += 6.0 / (1.0 + d as f64);
        }
    }
    // Also check residuals matching sums of two small items (harmonic pairs)
    for a in 1..=4 {
        for b in 1..=4 {
            let s = 10 * (a + b);
            if s <= post_residual && s >= 20 {
                congruent_bonus += 2.0 / (1.0 + (post_residual - s) as f64);
            }
        }
    }
    score -= congruent_bonus;

    // Integer-division threshold: how many "typical" items (size ~ mean of range) still fit
    let typical = 25u32;
    let fits_n = post_residual / typical;
    score -= fits_n as f64 * 3.0;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here: penalize leaving a residual that is "almost" fitting
            let gap = (next_item_size - post_residual) as f64;
            if gap <= 15.0 {
                score += 8.0 * (1.0 - gap / 15.0);
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score.
    if bin_residual == bin_capacity {
        // Opening a new bin is worthwhile only when existing bins fit poorly
        // (large post_residual would result elsewhere) or many bins already open.
        score = 55.0 + 0.15 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin can host the larger upcoming item too
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Mild pressure to fill bins that are already below mean residual (i.e., emptier than average)
    if (bin_residual as f64) > mean_residual && bin_residual != bin_capacity {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals in the "unusable" band (1..=15) are heavily
    // penalized since few future items (min size 1, typically >=10) can use them.
    if post_residual > 0 && post_residual <= 15 {
        score += 60.0 * (16.0 - post_residual as f64) / 16.0;
    }

    // Perfect or near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Favor bins whose residual is close to the item (tight fit) beyond raw residual.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 25.0 * (1.0 - tightness);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a new bin should only win when the current bin
    // would leave a bad gap. Base new-bin score is moderately high; it becomes
    // attractive only if existing-bin scores are inflated by dead-space penalties.
    if bin_residual == bin_capacity {
        score += 35.0;
        // Early in the stream, opening fresh bins is cheaper (more future items
        // to combine); later, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If many bins are open, discourage adding more.
        score += 2.0 * open_bins_count as f64;
    }

    // Lookahead: if the next item could exactly use this bin's post_residual,
    // reward leaving exactly that gap.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit the gap; gap likely wasted unless small enough to matter.
        if post_residual >= 10 {
            score += 15.0;
        }
    }

    // Mild pressure from open bin count: prefer filling existing bins when many are open.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with below-mean residual (consolidate emptier space elsewhere).
    score += 0.3 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base fit quality: prefer bins whose post_residual is small relative to capacity.
    score += 0.35 * (post_residual as f64 / cap) * 100.0;

    // Exact/near-exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let slack = post_residual as f64 - next_item_size as f64;
        score -= 30.0 - 0.4 * slack; // tight chain fits rewarded more
        if slack == 0.0 {
            score -= 20.0; // perfect 2-item chain
        }
    } else if next_item_size > 0 {
        // Penalize dead space that cannot host the next item, scaled by deadness.
        let dead = post_residual as f64;
        let nd = next_item_size as f64;
        score += 0.5 * (nd - dead).min(nd) * (dead / cap);
    }

    // Compare post_residual against mean residual: avoid leaving more slack than average.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: make it attractive only when fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / cap; // = 1 - item/cap
        let chain_ok = next_item_size > 0 && post_residual >= next_item_size;
        let mut new_score = 55.0 + 40.0 * poor_fit;
        if chain_ok {
            new_score -= 25.0;
        }
        if fitting_bins_count == 0 {
            new_score -= 100.0; // no alternative
        }
        score = new_score;
    }

    // Mild pressure against bin proliferation as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress * (1.0 - post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(4);

    // Dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item can fit into post_residual (chaining),
    // penalize if post_residual is stranded between sizes.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += (next_item_size as f64).min(post_residual as f64 + 1.0) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit_penalty = (item_size as f64 / bin_capacity as f64) * 30.0;
        score += 35.0 - scarcity * 70.0 - poor_fit_penalty
               + (open_bins_count as f64).ln().max(0.0) * 8.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    if mean_residual > 0.0 {
        score += (mean_residual - post_residual as f64) * 0.1;
    }

    // Time horizon: early on, be frugal with new bins; late, tighten fits.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * progress;
    score += 40.0 * poly;

    // Penalize dead space more as stream progresses
    score += 10.0 * pr_norm * pr_norm * progress;

    // Reward tight fits (small post residual) with smooth term
    score -= 15.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.5 + 0.5 * progress);

    // Lookahead: penalize if post_residual cannot fit next item (smooth quadratic)
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            score += 8.0 * (gap / cap) * (gap / cap) * cap;
        } else {
            score -= 4.0 * (-gap / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr_norm);
    }

    // Mild penalty for proliferating open bins early
    score += (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * 2.0;

    // Deviation from mean residual: prefer bins near mean (smooth)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev * cap;

    // New-bin candidate: slight penalty so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong best-fit term: prefer minimal post_residual.
    score += (post_residual as f64) * 0.5;

    // Harmonic class of post_residual: perfect fit is golden.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Classify residual into harmonic buckets by integer division of capacity.
        let class = post_residual / 10; // 0..10 buckets
        // Small residuals (<10) are dead space -> penalize relative to usefulness
        if post_residual < 10 {
            score += 25.0;
        } else if post_residual <= 25 {
            score -= 5.0; // tight but reusable
        } else if post_residual <= 50 {
            score -= 2.0;
        }
        let _ = class;
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // reward proportional to tightness of the follow-up fit
            score -= (cap - slack as f64) * 0.3;
            if slack < 10 {
                score -= 30.0;
            }
        } else {
            // next item cannot use this residual: penalize large wasted space
            score += (post_residual as f64) * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: make it mildly unattractive unless residuals are all bad.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.1;
    }

    // Progress coupling: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - (post_residual as f64) / cap);

    // Prefer spreading across many open bins when mean residual is large.
    score += (mean_residual - post_residual as f64).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space zone: residuals too small for the smallest plausible item (<=10)
    // are nearly worthless; penalize them super-linearly.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual <= 20 {
        // Semi-dead zone: only usable by small items; mild penalty.
        score += 12.0;
    } else {
        // Usable residual: reward proportionally to how well next item could use it.
        score -= 6.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 + 8.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize residuals that leave the next item stranded in a tiny gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 14.0;
    }

    // Perfect / near-perfect fit reward.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.95 {
        score -= 30.0;
    } else if fill_ratio > 0.8 {
        score -= 15.0;
    } else if fill_ratio < 0.4 {
        // Wasteful placement into a large bin.
        score += 10.0 * (0.4 - fill_ratio);
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }
    // Many fitting bins: mild penalty to encourage spreading consolidation pressure.
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones;
    // when few are open, a fresh bin is cheap.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure term.
        score += 25.0 + 6.0 * open_bins_count as f64 + 20.0 * progress;
        // But if no open bin fits well (post_residual here equals capacity anyway,
        // so this call only wins when alternatives are terrible) — handled by score.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin always fits the next item after this one; slight bonus.
            score -= 8.0;
        }
    } else {
        // Using an existing bin keeps bin count down; small reward scaled by pressure.
        score -= 2.0 * open_bins_count as f64;
    }

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps residuals balanced and reusable), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Favor chaining placements, but prefer small leftover after the chain.
            let chain_left = post_residual - next_item_size;
            score -= 80.0 - (chain_left as f64) * 0.5;
        } else {
            // Dead space: the next item cannot use the remainder.
            let waste_gap = (next_item_size - post_residual) as f64;
            score += waste_gap * 1.5;
        }
    }

    // Compare against mean residual: bins with unusually low residual are "tight" fits;
    // placing here concentrates waste into fewer bins.
    let tightness = mean_residual - bin_residual as f64;
    score += tightness * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins could still serve the item well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 + 80.0 * progress;
        // New bin is acceptable if the item is large and would leave big dead space elsewhere.
        if item_size >= bin_capacity * 8 / 10 {
            score -= 250.0;
        }
    }

    // Mild penalty for proliferating open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low dead space).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize post-residuals that are too small to be useful for future items
    // (items are 1..100; residuals < ~10 are near-dead).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // New-bin candidate handling: only attractive when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let good_fit_exists = fitting_bins_count > 0
            && (bin_capacity as f64 - mean_residual).abs() > 0.0
            && post_residual == bin_capacity;
        // Base penalty so a new bin is chosen only when it beats poor fits.
        score += 15.0 + 0.15 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
        if good_fit_exists {
            score += 10.0;
        }
        // Late in the stream, avoid proliferating bins with tiny leftovers.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Mild preference for filling bins with larger residuals when mean residual is high.
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Slight preference to consolidate across fewer open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual
    let mut score = pr;

    // Smooth non-linear penalty on residual normalized to capacity, coupled with progress
    let r = pr / cap;
    score += 12.0 * r * r * (1.0 + progress);

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness * tightness;

    // Dead-space penalty: residual too small to hold typical items
    let min_item = 1.0;
    let dead = ((min_item - r).max(0.0)) / min_item.max(1e-6);
    score += 8.0 * dead * dead;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fit_gap = (nx - pr).abs();
        score -= 15.0 * (-fit_gap / 20.0) * (1.0 - progress);
        // Penalize leaving residual that almost fits next item (tempting but wasteful)
        if nx > pr {
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly, scaled by how many bins could fit and mean residual
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * fitting_bins_count as f64 + 0.1 * mean_residual;
    }

    // Mild preference to spread across many open bins late in the stream
    score += 0.02 * open_bins_count as f64 * progress;

    // Smooth progress coupling on raw residual
    score += 4.0 * pr * progress * progress / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: post_residual divisible into useful chunks
    let pr = post_residual;
    if pr > 0 {
        // Dead-space penalty for residuals that are too small to be useful
        // (below the minimum plausible item size of 1..10 range)
        if pr < 10 {
            score += 60.0; // tiny unusable sliver
        } else if pr <= 30 {
            score -= 25.0; // small but usable
        } else if pr <= 50 {
            score += 10.0; // mid-range: risky dead space
        } else {
            score -= 15.0; // large residual keeps flexibility
        }

        // Modulo/harmonic coupling: residuals that are multiples of common
        // item-size classes (10, 20, 25, 50) are more reusable
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 25 == 0 { score -= 8.0; }
        if pr % 50 == 0 { score -= 6.0; }

        // Integer-division threshold: can it host a "half bin" item?
        if pr / 50 >= 1 { score -= 10.0; }
        if pr / 25 >= 2 { score -= 5.0; }
    }

    // Lookahead: does post_residual fit the next item exactly or well?
    if next_item_size > 0 && (next_item_size as u32) <= pr {
        let next_fit_gap = pr - next_item_size;
        if next_fit_gap == 0 {
            score -= 200.0; // chain of perfect fits
        } else if next_fit_gap < 10 {
            score -= 40.0;
        } else if next_fit_gap < 30 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty if this bin becomes dead
        if pr < 10 {
            score += 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when current fit is terrible and many bins are open with slack
    if bin_residual == bin_capacity {
        // baseline score for a fresh bin = full capacity residual
        // penalize opening new bins unless the stream is early or
        // existing fit creates dead space
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_r = mean_residual;
        let poor_fit = (post_residual as f64) > 0.0 && (item_size as f64) / cap < 0.2;
        let mut new_bin_score = cap * 0.9; // start high: prefer existing bins
        if poor_fit && mean_r < 25.0 && open_bins_count > 2 {
            new_bin_score -= 150.0; // existing bins are nearly full anyway
        }
        if progress < 0.05 {
            new_bin_score -= 50.0; // early stream: fresh bins cheap
        }
        if next_item_size > 0 && (next_item_size as u32) > pr {
            // new bin could hold next item alongside
            new_bin_score -= 30.0;
        }
        score = score.min(score) ; // keep current-bin path intact
        return new_bin_score;
    }

    // Tightness reward: prefer bins where item fills a large fraction
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Slight preference for bins with below-mean residual (consolidation)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual below ~10 can almost never be filled (min item size 1,
    // but small gaps waste capacity relative to mean item size).
    if post_residual > 0 && post_residual < 12 {
        score += 40.0;
    } else if post_residual < 25 {
        score += 12.0;
    } else if post_residual < 45 {
        score += 4.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading out; opening new bins becomes costlier.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * 2.5;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item cannot fit post-residual but would fit a fresh bin,
    // slightly penalize leaving a gap that strands the next item.
    if next_item_size > post_residual && next_item_size > bin_residual {
        score += 6.0;
    }

    // New-bin candidate handling: an empty bin is a fresh start; make it
    // attractive only when existing bins would create bad dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin (grows with open bins count).
        score = bin_capacity as f64 * 0.35 + pressure * 3.0;
        // If no good fit exists elsewhere (this call sees fitting count),
        // new bin is relatively better.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Lookahead: fresh bin can hold next item too.
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 5.0;
        }
    }

    // Mild stream-progression tightening: later in the stream, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    // Deviation from mean residual: prefer bins whose residual is already
    // below average (tighter bins get filled first).
    score += (post_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

