    // (residuals < 10 are useless; residuals just above next_item_size are valuable).
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powf(1.7);
        score += 9.0 * dead;
        if post_residual < 10 {
            score += 14.0; // unusable sliver
