    }

    // New-bin candidate handling: opening a bin is only attractive when
    // open bins are mostly full or the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin: grows with number of open bins and progress.
        score += 30.0 + 3.0 * open_bins_count as f64 + 10.0 * progress;
        // If no other bin can fit (fitting_bins_count == 1 refers only to this new bin),
        // the new bin is necessary: discount the penalty.
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        // If mean residual across open bins is large, existing bins are roomy:
        // discourage opening a new one.
        score += 0.25 * mean_residual;
    } else {
        // Slight preference for bins with less residual (best-fit flavor),
        // modulated by global mean residual.
        score += 0.08 * (bin_residual as f64 - mean_residual);
    }

    // Late-stream effect: near the end, prefer packing into existing bins
    // to avoid leaving many almost-empty bins.
    score -= 6.0 * progress * tightness;

    // Mild penalty for very full open bins count (encourage consolidation early).
    if open_bins_count > 4 {
        score -= 0.5 * (open_bins_count as f64).ln();
    }

