    let mut score = post + 0.008 * post * post / cap;

    // Tight-fit reward: strong discount as post_residual approaches zero.
    let tightness = 1.0 - post / cap; // 1.0 when perfectly full
    score -= 25.0 * tightness * tightness * tightness;

    // New-bin candidate: penalize opening a bin unless it is genuinely needed.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 18.0 + 6.0 * (open_bins_count as f64).ln().max(0.0);
        // If many bins already fit the item, opening a new one is wasteful.
        score += 5.0 * (fitting_bins_count as f64).min(5.0);
    }

    // Last-chance bin: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
