    }

    // Lookahead coupling: reward leaving residual that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let match_bonus = (1.0 - gap / cap).max(0.0);
        score -= 8.0 * match_bonus * match_bonus;
        // Penalize leaving residual slightly larger than next item (unusable sliver).
        if post > nxt && post - nxt < 10.0 {
            score += 6.0 * (1.0 - (post - nxt) / 10.0);
        }
    }

    // Stream-progress coupling: late in the stream, be more conservative —
    // favor tighter fits and avoid spreading across many bins.
    let late = progress * progress;
    score += late * (post * 0.15 + mean_residual * 0.05);
    score -= late * 10.0 * tightness;

    // Mild pressure to prefer bins already below mean residual (balance residuals).
    score += 0.05 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
