    } else if fitting_bins_count > 1 {
        // Mild preference for bins that are scarcer fits.
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.8;

    // Favor bins with residual close to the mean (balanced packing),
    // penalize outliers that create fragmented space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            // Post-residual cannot hold next item: mild penalty scaled by waste.
            score += (post_residual as f64 / 20.0);
        }
    }

    // New-bin candidate: opening a new bin should only win when no open bin
    // offers a decent fit. Make the empty bin moderately expensive by default.
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin.
        score += 35.0;
        // But if the item is large relative to capacity, a fresh bin is fine
        // (large items leave little fragmentation anyway).
        let size_frac = item_size as f64 / bin_capacity as f64;
        score -= size_frac * 20.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // If many bins can already fit the item, opening a new bin is wasteful.
        score += fitting_bins_count as f64 * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits
    score += 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 6.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        if post_residual == next_item_size {
            score -= 10.0; // perfect pair
        }
        // Penalize leftover too small for the next item (dead space)
        if post_residual < next_item_size {
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Relative to mean residual: prefer bins deviating from the mean
    score -= 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin bonus: avoid opening a new bin if this is the only fit
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening fresh bins unless item is large or no good fit
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 60 && next_item_size >= post_residual.min(50) {
            score -= 10.0; // large items pair well in a fresh bin
        }
    }

    // Early stream: slightly discourage spreading across many bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Reward tight fits: fractional fill bonus
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize small dead space that nothing can use (min item 1..100 unknown, assume ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits the post residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > 0 && post_residual > 0 {
        // wasted space relative to next item
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening new bins, more so early / when many bins open
    if is_new_bin {
        let mut penalty = 35.0 + 4.0 * open_bins_count as f64;
        if progress < 0.2 { penalty += 15.0; }
        // allow new bin when current fit is terrible (post_residual large relative to capacity)
        penalty -= 0.15 * post_residual as f64;
        score += penalty.max(0.0);
    }

    // Prefer bins below mean residual (keep spread balanced)
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // Late in stream: consolidate, discourage spreading
    if progress > 0.7 {
        score += 0.1 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += prn * prn * (30.0 + 40.0 * p2) * (1.0 - p3);

    // Reward tight fits (small post residual) more strongly as stream advances
    let tightness = 1.0 - prn;
    score -= tightness * tightness * (10.0 + 25.0 * p2);

    // Penalize waste relative to mean residual across open bins
    score += (pr - mean_residual).abs() * (0.3 + 0.5 * progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= (8.0 + 12.0 * (1.0 - progress)) * (1.0 - slack * slack);
        } else {
            score += (nxt - pr) * 0.25;
        }
    }

    // New-bin candidate: mildly penalize so it is chosen only when open bins are bad
    if bin_residual == bin_capacity {
        score += 12.0 + 15.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    }

    // Prefer fuller bins (smaller residual before placement)
    score += (br / cap) * (5.0 + 10.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which capacity fraction band it lands in.
    let q = (bin_capacity as f64) / 4.0; // quarter classes
    let class = (post_residual as f64 / q).floor() as i32; // 0..4

    // Penalize residuals that are "dead space": too small to fit typical future items.
    // Class 0 (post_residual < 25) is nearly dead unless next item is tiny.
    match class {
        0 => score += 30.0,
        1 => score += 8.0,
        2 => score -= 4.0,
        3 => score -= 10.0,
        _ => score -= 14.0,
    }

    // Modulo arithmetic on post_residual: values divisible by common item sizes
    // (10, 20, 25, 50) are reusable "harmonic" residuals.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 5.0; }
    }

    // Lookahead coupling: reward bins whose post_residual harmonically matches
    // the next item (next fits exactly or leaves a good class again).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 { score -= 12.0; }
            if next_item_size == post_residual { score -= 15.0; }
        } else {
            // Next item won't fit here: penalize slightly, more if this bin
            // would then be stranded with tiny residual.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but avoid opening new
    // bins when the current bin's fit is decent (post_residual class >= 2).
    if bin_residual == bin_capacity {
        score = 45.0;
        if fitting_bins_count <= 1 { score -= 10.0; } // open new bin if only poor fits exist
        if class <= 1 && fitting_bins_count >= 1 { score += 5.0; } // keep old bin if it fit well
    }

    // Stream progression: early on, be pickier about dead space; late, prefer
    // closing bins out (favor tighter fits more aggressively).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Mild tie-break toward reducing open bin count variance.
    score += (open_bins_count as f64).sqrt() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space zone: residuals too small for the smallest items (1..=10)
    // are likely wasted forever. Penalize heavily when post_residual falls
    // in an unusable gap, scaled by how "stuck" it is.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement chains perfectly.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual - next_item_size < 10 {
            score -= 80.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for stranding space.
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // open bins are very full (low mean residual) or there is pressure
    // from many open bins with poor fitting options.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its residual is full capacity,
        // but that baseline is already high; add pressure terms.
        score += open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 50.0; // existing bins can't host the next item either
        }
        if fitting_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            score += 80.0; // existing bins still roomy; discourage new bin
        }
    }

    // Open-bin pressure: many open bins -> favor consolidating into
    // existing ones rather than spreading.
    score += open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64) * 3.0;

    // Mild late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.5;

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (balanced packing), penalize outliers.
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly fit the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // chain fit possible, mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize dead space below next item size
            score += 60.0 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual across open bins
    score -= 0.5 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New empty bin candidate: penalize unless item is large relative to capacity
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 200.0 * (1.0 - tightness);
    }

    // Late in the stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 40.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space relative to capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_ratio * waste_ratio;

    // Penalize bins whose residual is much larger than the mean (poorly packed outliers),
    // encouraging consolidation into bins that are already partially filled.
    let excess = bin_residual as f64 - mean_residual;
    score += 0.35 * excess;

    // Last-chance bonus: if this is the ONLY bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // reward this placement strongly (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 12.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // Next item cannot use the leftover: penalize proportionally to dead space.
            score += 0.25 * (next_item_size as f64 - post_residual as f64).min(next_item_size as f64);
        }
    }

    // New-bin candidate logic: opening a new bin is only attractive when no open bin
    // offers a good fit (post_residual would be large) or when many bins are open
    // with high mean residual (fragmentation is already high).
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && (bin_capacity.saturating_sub(item_size)) <= mean_residual as u32 + 5;
        let mut penalty = 0.0;
        if good_fit_exists {
            penalty += 55.0;
        }
        // Early in the stream, prefer reusing bins; later, allow more opening.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty += (1.0 - progress) * 20.0;
        // If open bins are fragmented (high mean residual), opening is less bad.
        penalty -= 0.15 * mean_residual;
        score += penalty;
    }

    // Mild bonus for using bins with small residual overall (tighten packing).
    score -= 0.10 * (bin_capacity as f64 - bin_residual as f64);

    // Slight penalty when many bins are open and this bin is nearly full but
    // the item leaves awkward space (between 1 and 9, unusable for items >=10).
    if post_residual >= 1 && post_residual <= 9 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear penalty on wasted residual, amplified by stream progress.
    let norm_pr = pr / cap;
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual relative to capacity).
    score -= 4.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize opening a brand-new bin when existing bins could fit,
    // unless the new bin yields a much better residual.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 6.0 + 10.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly reward using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 3.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 2.0 * (nx - pr) / cap;
        }
    }

    // Mild pressure to consolidate bins as more bins are open.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Penalize bins whose residual deviates far from the mean (balance).
    score += 0.3 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: residual exactly divisible classes
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 30.0;
    } else if pr <= 20 {
        score -= 12.0;
    }

    // Harmonic classes: penalize residuals that few future item sizes can use
    // Items 1..100; residual pr usable by next item if next_item_size <= pr
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 8.0 + (pr - next_item_size) as f64 * 0.15;
        } else {
            score += 10.0; // this bin useless for lookahead
        }
        // pair fit: post residual exactly matches next item later
        if pr >= next_item_size && (pr % next_item_size.max(1)) == 0 {
            score -= 6.0;
        }
    }

    // Modulo-class logic on post_residual (harmonic bands of capacity)
    let q = pr / 25; // quarters of capacity
    score += match q {
        0 => -5.0,
        1 => 2.0,
        2 => 6.0,
        _ => 10.0,
    };

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins relative to mean residual
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight preference to spread early, consolidate late
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.1 - progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

