    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect or near-perfect fits get strong rewards.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Tightness ratio coupling: reward filling the bin well.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // If the next item would fit exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 30.0 - gap as f64;
        } else {
            score -= 5.0;
        }
    }
    // Penalize if next item cannot fit here anyway (bin becomes dead-end).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening bins when good fits exist,
    // but allow it when open bins would leave large dead space.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
        if post_residual > 60 {
            score -= 20.0; // huge item, new bin is natural
        }
    }

    // Open-bin pressure: mild penalty scaling with number of open bins
    // to encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.8;

    // Progress-aware: early in stream, be slightly more willing to open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

