            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item would not fit here: penalize small dead space that blocks it.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(80.0);
        }
    }

    // Penalize leaving residuals that are hard to reuse (small but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early in the stream, be more willing to spread items (keep flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score += 10.0 * (1.0 - progress * 5.0);
    }

    // Many open bins: prefer consolidating into existing bins.
    if open_bins_count > 4 {
        score += 2.0 * open_bins_count as f64;
    }

    // New-bin candidate: only attractive when item is huge relative to capacity
    // or fit elsewhere is hopeless.
    if bin_residual == bin_capacity {
        score += 150.0;
        if item_size >= 80 {
            score -= 120.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Best-fit base already captured via post_residual; add mild superlinear
    // penalty for large leftover space that is likely dead space.
    let dead_threshold = 0.35 * bin_capacity as f64;
    if post_residual as f64 > dead_threshold {
        score += 0.9 * (post_residual as f64 - dead_threshold);
    }

    // Penalize the brand-new empty bin candidate; the penalty decays as the
    // stream progresses and when few bins can fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_pressure = 1.0 / (fitting_bins_count as f64 + 1.0);
        let time_relief = 0.35 * progress;
        score += 55.0 * (1.0 - time_relief) * (0.55 + 0.45 * fit_pressure);
    } else {
        // Reward using an existing bin (implicit via new-bin penalty above),
        // extra reward when this bin is the last chance before opening a new one.
        if fitting_bins_count == 1 {
            score -= 12.0;
        } else {
            score -= 3.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this placement; if next item would be stranded by this
    // placement while other bins could take the current item, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Global state coupling: when mean residual is high and open bins are many,
    // prefer tightening existing bins rather than spreading items.
    score += 0.25 * (mean_residual - post_residual as f64);

    // Slight time-varying exploration term to break ties differently over the
    // stream horizon (deterministic function of progress).
    score += (progress * 6.2831853).sin() * 0.75;

    // Mild preference for bins whose residual is close to the item (tight fits)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 5.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let t = progress;

    // Quadratic/cubic shaping: small residuals are increasingly penalized late in stream
    score += 12.0 * pr_norm * pr_norm * (0.5 + t);
    score -= 8.0 * pr_norm * (1.0 - t);

    // Tight fits reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill * fill;

    // Lookahead coupling: reward if next item fits into post_residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > 0 {
        score += 3.0 * t;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - t);
    }

    // Prefer bins with residual below mean (consolidate waste)
    score += 2.0 * ((pr - mean_residual) / cap);

    // Penalize opening new bins when open bins can fit, more so early on
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via post_residual, but with diminishing returns
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Harmonic class of post_residual: classify dead space quality
    // Residuals that are "harmonically useful" (small, or multiples of common sizes) are less penalized
    let post = post_residual;
    let class: f64 = if post == 0 {
        -50.0 // perfect fill
    } else if post <= 10 {
        -20.0
    } else if post % 10 == 0 {
        0.5 * (post as f64 / 10.0) // clean multiples of 10 remain usable
    } else if post % 5 == 0 {
        1.5 * (post as f64 / 5.0)
    } else {
        3.0 // awkward residual
    };
    score += class;

    // Non-linear penalty on fraction of wasted capacity (quadratic growth of dead space)
    score += 40.0 * frac * frac;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 60.0;
        } else if next_item_size <= post {
            let slack = (post - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / cap);
            // harmonic check: does next item leave a clean residual too?
            let npost = post - next_item_size;
            if npost % 10 == 0 || npost == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; mild penalty if this was the only fitting bin
            if fitting_bins_count == 1 {
                score -= 5.0; // last-chance bin still favored to close it out
            }
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it over new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default score so that
    // it only wins when all open bins are poor fits
    if bin_residual == bin_capacity {
        score = 55.0 + 0.15 * open_bins_count as f64 + 20.0 * frac;
        // late in stream, prefer reusing bins more aggressively
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        return score;
    }

    // Prefer bins below mean residual (filling emptier bins balances open-bin pool)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Mild pressure against proliferating bins
    score += 0.05 * open_bins_count as f64;

    // Progress-scaled tightness weight: later in stream, waste matters more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * progress * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical future items are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Dead space is worse late in the stream when fewer chances remain to fill it.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 20 {
        score += 30.0 * progress;
    }

    // Pressure from number of open bins: prefer placing into existing bins
    // rather than spreading across many partially filled bins.
    score += 3.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 30.0;
        } else if gap < 10.0 {
            score -= 10.0;
        }
    }

    // Penalize bins whose residual deviates badly from the mean residual
    // (keeps residuals homogeneous and fillable).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: opening a fresh bin should only win when the current
    // fit is poor. Give it a moderate baseline plus open-bin pressure.
    if bin_residual == bin_capacity {
        score += 15.0 + 4.0 * open_bins_count as f64;
        // But if the item is large and no good fit exists, new bin is attractive.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: aggressive 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Reward exact/near match between post_residual and next item size.
        let match_gap = (post_residual as f64 - nxt).abs();
        score -= 60.0 * (-match_gap / 8.0).exp();

        // Reward post_residual being large enough for next item (chaining).
        if post_residual as f64 >= nxt {
            score -= 12.0;
        } else {
            // Penalize creating residual just below next item (near-miss dead space).
            let miss = nxt - post_residual as f64;
            if miss <= 10.0 {
                score += 18.0 * (1.0 - miss / 10.0);
            }
        }
    }

    // Penalize small unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit relative to bin residual: prefer bins where item fills a large share.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Prefer bins below mean residual (using emptier space among open bins),
    // but mildly, so tight fits dominate.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // New-bin candidate: keep it neutral-to-slightly-poor unless stream is early
    // and no good fits exist; opening bins early in stream is cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * (1.0 - progress);
    }

    // Mild penalty for accumulating many open bins late in stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: strongly reward small post-residual.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving dead space that the lookahead item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Reward if the lookahead item fits exactly in the post-residual.
    if next_item_size == post_residual && post_residual > 0 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Early in the stream, be more willing to open new bins (keep residuals large).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cheaper early, expensive late.
        score = 55.0 + 60.0 * progress - 10.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 30.0; // never open a new bin when a last-chance bin exists
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // pair large items early
        }
    }

    // Prefer bins whose residual is close to the item (minimize waste relative to mean).
    let diff = bin_residual as f64 - item_size as f64;
    score += (diff - mean_residual).abs() * 0.15;

    // Slight penalty for many open bins late in the stream (encourage consolidation).
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize residual, with non-linear (quadratic/cubic) coupling to progress
    let mut score = pr * (1.0 + 0.8 * progress) + 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic dead-space term: large residuals late in the stream are costly
    score += 60.0 * norm_pr.powi(3) * progress;

    // Tight fits are rewarded more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (next_item_size as f64 / cap) * (1.0 - 0.5 * progress);
    } else if next_item_size > 0 {
        score += 8.0 * progress * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: mildly discourage opening yet another
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64 - 15.0 * progress;
        // But encourage a fresh bin when mean residual across open bins is low
        score -= 6.0 * (mean_residual / cap).max(0.0);
    }

    // Mean residual coupling: prefer bins deviating below mean (consolidation)
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);
    score -= 0.5 * (pr - mean_residual) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: waste that is "useless"
    // (too small for the smallest plausible item) should be penalized hard.
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score -= 1000.0; // perfect fit bonus
    } else {
        // dead-space penalty grows when residual falls below typical item size
        let dead = (10.0 - post_residual as f64).max(0.0);
        score += dead * dead * 2.0;
    }

    // Reward if next item fits exactly into the post-residual (harmonic pairing)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // reward proportional to how well next item fills the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * fill;
        } else {
            // next item cannot fit here: slight penalty for tight residuals
            score += 10.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer bins whose residual deviates from the mean (consolidate waste)
    score += 0.5 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for older bins when everything else is equal
    score += 0.01 * open_bins_count as f64;

    // Modulo-class coupling: residuals near multiples of 20 are more reusable
    let r = post_residual % 20;
    if r == 0 {
        score -= 15.0;
    } else {
        score += r as f64 * 0.3;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = cap * 0.8 + 50.0 * (1.0 - pressure) - 50.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are nearly useless -> heavy penalty.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 - 3.0 * post_residual as f64;
    }
    // Perfect or near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 3 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Reward when this bin's residual exactly matches the item (perfect fill).
    if bin_residual == item_size {
        score -= 80.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin, unless the fit is terrible (large dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual <= 15 {
            score -= 30.0;
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when the current
    // fit is bad (large post_residual) and few bins can fit the item.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        // Baseline for a fresh bin: its residual is large, so it already scores high;
        // add pressure so we prefer existing bins unless fit is poor.
        score += 20.0 + 2.0 * open_bins_count as f64;
        // If no tight fit exists anywhere (this call context: many fitting bins means
        // alternatives exist), keep new bin penalized; if few fit, soften penalty.
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
        // Lookahead: if next item is small it can use leftover gaps; discourage new bin.
        if next_item_size > 0 && next_item_size <= post_residual.max(0) {
            score += 15.0;
        }
    } else {
        // Lookahead synergy: if the next item fits in the post residual, reward.
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 12.0 + 0.2 * next_item_size as f64;
        }
    }

    // Open-bins pressure: many open bins -> prefer filling existing ones (penalize new bin implicitly).
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Prefer bins below mean residual (fill emptier-relative bins to balance).
    score -= 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step fit: post_residual exactly matches next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect lookahead fit.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap <= 5.0 {
            score -= 25.0 * (1.0 - gap / 6.0);
        }
    }

    // Penalize small unusable dead space (nothing typical fits).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Reward leaving large, reusable residuals relative to mean residual.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score -= 0.5 * (pr - mean_residual);
    } else {
        score += 0.5 * (mean_residual - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when residual would be wasted or few fitting bins.
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64;
        let pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 1.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bin when it would keep a big, useful residual and many bins can't fit item.
        score = 40.0 + waste * 0.6 - pressure * 8.0 + progress * 10.0;
        if next_item_size > 0 && (bin_residual - item_size) >= next_item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits relative to capacity
    score -= 30.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Penalize dead space that cannot fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable slivers
    }

    // Lookahead coupling: reward bins whose post-residual fits the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // bonus if next item then fits nearly perfectly
            let nxt_post = post_residual - next_item_size;
            if nxt_post < 10 {
                score -= 8.0;
            }
        } else {
            // post-residual too small for next item: mild penalty scaled by wasted amount
            score += 5.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage spreading; prefer consolidating into low-residual bins
    if open_bins_count > 4 {
        score += 0.15 * (open_bins_count as f64);
        score += 0.4 * ((bin_residual as f64 - mean_residual).abs());
    }

    // New-bin candidate logic: only attractive when no good fits exist
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = if fitting_bins_count == 0 { 40.0 } else { (fitting_bins_count as f64).powi(2) * 6.0 };
        score = 60.0 + pressure + 20.0 * progress;
        // opening a bin is fine if mean residual is low (existing bins nearly full)
        score -= 0.5 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling of post_residual with progress:
    // dead space becomes increasingly costly as the stream advances.
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    score += 8.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Lookahead: reward bins whose post_residual pairs well with the next item
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let gap = pr - next_item_size as f64;
        score -= 4.0 * (1.0 - gap / cap).max(0.0);
    } else if next_item_size > 0 {
        // post_residual cannot host next item: penalize proportionally
        score += 2.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Many fitting bins: mild penalty to prefer the best-fit among them
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only attractive when open bins have poor residuals
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - pr).max(0.0) / cap;
        score += 25.0 - 30.0 * mean_gap - 10.0 * progress;
    }

    // Fragmentation pressure: bins whose residual is small-but-not-zero are bad targets
    if pr > 0 && pr < item_size as f64 {
        score += 3.0 * (1.0 - pr / item_size as f64);
    }

    // Mild dispersion term: prefer bins deviating from mean residual in a useful way
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near capacity/k boundaries
    let pr = post_residual;
    if pr > 0 {
        // Dead-space penalty scaled by how "unusable" the residue class is.
        // Residues in the smallest classes (1..10) are nearly dead -> heavy penalty.
        let class = if pr <= 10 { 3.0 }
                    else if pr <= 20 { 2.0 }
                    else if pr <= 50 { 1.0 }
                    else { 0.5 };
        score += class * (pr as f64 / cap_f) * 20.0;
    } else {
        // Perfect fill: strong reward
        score -= 50.0;
    }

    // Lookahead coupling: reward if next item fits the post-residue well.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            // Harmonic fit quality: exact division-like fits are best.
            let fit_quality = 1.0 - (slack as f64 / cap_f);
            score -= 15.0 * fit_quality;
            if pr % next_item_size == 0 && pr > 0 {
                score -= 8.0; // exact harmonic multiple
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overflow gap class
            let gap = next_item_size - pr;
            score += if gap <= 10 { 6.0 } else { 2.0 };
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): base cost of opening a bin.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if no good open bin exists (few fitting bins, poor mean fit), discount it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let scarcity = (fitting_bins_count == 0) as i32 as f64;
        let poor_open = ((mean_residual - item_size as f64).abs() > 0.0 && mean_residual < item_size as f64 + 10.0) as i32 as f64;
        score -= scarcity * 40.0 + poor_open * 15.0 + progress * 5.0;
    }

    // Prefer bins with residual close to item (tight fit) via harmonic fraction.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * (fill_frac - 0.5).abs().min(0.5);

    // Mild pressure against accumulating too many open bins late in the stream.
    score += open_bins_count as f64 * 0.05 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Reward tight fits relative to the item size.
    score -= (item_size as f64) * 0.3;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many bins when fit is loose.
    score += (open_bins_count as f64) * 0.5 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item can use the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 5.0; // residual likely wasted for the next item
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.2;

    // New-bin candidate handling: opening a new bin is attractive only when no
    // open bin gives a tight fit (i.e., this empty-bin call sees a big item).
    if bin_residual == bin_capacity {
        let waste = bin_capacity - item_size;
        if waste <= 20 {
            score -= 30.0; // fresh bin packs this large item tightly
        } else {
            score += 20.0 + (waste as f64) * 0.4; // prefer existing bins
        }
    }

    // Slight stream-progression bias toward consolidation late in the stream.
    if total_items > 0 {
        score -= (step_index as f64 / total_items as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 {
        // Penalize leaving residual the next item cannot use.
        if post_residual < next_item_size {
            score += 12.0;
        } else {
            // Reward residuals close to next_item_size (soft matching).
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            score -= (18.0 / (1.0 + gap)).max(0.0);
        }
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Penalize tiny dead space (< next typical item sizes) relative to mean residual.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Encourage balancing residuals toward the mean (spread load evenly).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual here equals capacity - item_size).
    if bin_residual == bin_capacity {
        let base = 100.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score += base * 0.4; // new bin could host the next item too: less bad
        } else {
            score += base;
        }
    }

    // Slight late-stream consolidation pressure.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual, penalize large dead space.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 6.0 * tightness * tightness * (item_size as f64) / cap;

    // Penalize bins that end with tiny unusable residuals (dead space creation).
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 4.0 * (10.0 - pr);
        } else if pr < 20.0 {
            score += 0.5 * (20.0 - pr);
        }
    }

    // Lookahead: if next item fits exactly in the post_residual, strongly favor this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= 3.0 * (1.0 - slack / cap);
            if (pr - nxt).abs() < 1.0 {
                score -= 5.0;
            }
        } else if pr > 0.0 && pr < nxt {
            // residual too small for next item: mild penalty proportional to waste
            score += 0.3 * pr / nxt;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; prefer it only when
    // open bins are crowded or the fit is bad. Penalize empty bins when good fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64;
        score += 12.0 - 4.0 * progress - 0.5 * crowd.min(10.0);
        // If mean residual is large, existing bins have room; discourage new bin.
        score += 0.05 * mean_residual.max(0.0);
    }

    // Global state: many open bins with high mean residual -> prefer filling existing bins.
    let mean_r = mean_residual.max(0.0);
    if bin_residual < bin_capacity {
        score -= 0.02 * mean_r * (open_bins_count as f64).sqrt();
    }

    // Time horizon: late in the stream, be greedy about filling bins to capacity.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && bin_residual >= item_size {
        score -= 2.0 * progress * (1.0 - (post_residual as f64) / cap);
    }

    // Mild preference for bins whose residual is close to the item (best-fit flavor).
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 2.0 * fit_gap * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Penalize dead space quadratically when it can't fit the next item
    if next_item_size > 0 && pr < next_item_size as f64 {
        let waste = (next_item_size as f64 - pr) / cap;
        score += 40.0 * waste * waste * (1.0 - progress);
    }

    // Reward leaving room exactly for the next item
    if next_item_size > 0 && pr == next_item_size as f64 {
        score -= 15.0 * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor filling this bin if it's the only fit
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * (1.0 - norm_pr));
    }

    // Prefer bins tighter than average (smooth coupling with mean residual)
    score -= 0.3 * (mean_residual - pr) * (1.0 - progress);

    // Mild preference for consolidating into fewer bins early on
    score += 2.0 * norm_pr * (1.0 - progress);

    // Slight penalty for opening a new bin when good fits exist
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress) + 10.0 * norm_pr * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item sizes
    // (10, 20, 25, 50) are "usable" classes; odd fragments are dead space.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr == 0 {
        class_bonus -= 30.0; // perfect fit
    } else if pr % 50 == 0 {
        class_bonus -= 12.0;
    } else if pr % 25 == 0 {
        class_bonus -= 8.0;
    } else if pr % 20 == 0 {
        class_bonus -= 6.0;
    } else if pr % 10 == 0 {
        class_bonus -= 3.0;
    } else if pr < 10 {
        class_bonus += 25.0; // unusable dead space
    } else {
        class_bonus += 4.0; // awkward residue
    }
    score += class_bonus;

    // Lookahead: does the next item fit exactly / well in the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0; // chains perfectly
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 3.0; // next item won't fit here anyway
        }
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / bin_capacity as f64;
        score = 100.0 - 25.0 * crowding - 10.0 * progress;
        if fitting_bins_count == 0 {
            score = -10.0; // must open a bin
        }
    }

    // Mild preference for tighter existing bins (small residual before placement).
    score += bin_residual as f64 * 0.05;
    score -= mean_residual * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no plausible item can use are costly.
    // Items are integers in 1..=100; a residual gap < some small threshold is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit reward: item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Penalize leaving a gap that is slightly larger than the next item (near-miss waste),
    // reward leaving a gap the next item can exactly or nearly fill.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this gap; mild penalty proportional to how far off
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins when mean residual
    // is already low (bins nearly full); encourage consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    score += pressure * (0.5 + 0.5 * progress);

    // New-bin candidate (empty bin): make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin, offset by its large flexibility.
        score = 55.0 - 10.0 * progress;
        if next_item_size > 0 {
            // A fresh bin can host both current and next item comfortably.
            if item_size + next_item_size <= bin_capacity {
                score -= 15.0;
            }
        }
        // If many bins already fit the item, opening a new one is wasteful.
        score += 20.0 * (fitting_bins_count as f64).min(5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 200.0; // near-perfect chain fit
        }
        // Penalize leaving a sliver that the next item cannot use.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Reward tight fits relative to item size.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Penalize dead space: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let good_fits_exist = next_item_size > 0 && post_residual == 0; // placeholder neutral
        let _ = good_fits_exist;
        score = 60.0 + mean_residual * 0.3;
        if fitting_bins_count == 1 {
            score += 400.0; // don't open a new bin when a last-chance bin exists
        }
        if fitting_bins_count > 2 {
            score -= 30.0;
        }
    }

    // Coupling with mean residual: prefer bins whose post-residual stays near mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Slight preference to consolidate early in the stream.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity)
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Penalize leaving dead space that cannot fit the next item (lookahead)
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 + 0.15 * (next_item_size as f64 - post_residual as f64);
        } else if post_residual >= next_item_size && next_item_size > 0 {
            // Reward bins that can also host the next item
            score -= 3.0 * (post_residual as f64 / (next_item_size as f64 + 1.0)).min(2.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Penalize opening a new bin when good open bins exist and stream is early
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: cost grows with number of open bins and early progress
        score += 4.0 + 0.3 * open_bins_count as f64 + 6.0 * (1.0 - progress);
        // But if item is large and mean residual is small, opening is fine
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 5.0 * large_item * (1.0 - mean_residual / bin_capacity as f64).max(0.0);
    }

    // Prefer bins whose residual deviates below the mean (consolidate fragmented space)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight preference for bins with larger residual when item is small (avoid wasting tight bins)
    let small_item_bonus = (1.0 - item_size as f64 / bin_capacity as f64) * (bin_residual as f64 / bin_capacity as f64);
    score -= 2.0 * small_item_bonus;

    // Mild time-horizon regularization: later in stream, be greedier about tight fits
    score -= 2.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual

    // Base: prefer small post-residual, with mild non-linear tightening
    let mut score = post + 20.0 * pr * pr * cap;

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly (less time to fill it)
    let progress_penalty = 30.0 * pr * pr * (0.5 + progress) * (1.0 + progress);
    score += progress_penalty;

    // Reward near-perfect fits smoothly (post_residual close to 0)
    score -= 25.0 * (-post * post / (2.0 * cap)).exp() * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or when open bins have plenty of room; relax slightly late in the stream.
    if bin_residual == bin_capacity {
        let room = mean_residual / cap;
        score += 35.0 + 60.0 * (1.0 - room) - 15.0 * progress;
        // If next item is large, a fresh bin is more attractive
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            score -= 0.3 * nxt * (0.5 + progress);
        }
    } else {
        // Favor bins whose residual is close to the item (smooth fit affinity)
        let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
        score += 15.0 * fit_gap * fit_gap;
        // Lookahead: reward leaving residual that can host the next item
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if post >= nxt {
                score -= 6.0 * (1.0 - (post - nxt) / cap);
            } else {
                score += 5.0 * (nxt - post) / cap;
            }
        }
    }

    // Mild consolidation pressure: more open bins -> prefer filling existing ones
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
