pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (1..=100 interface => min item = 1, but tiny
    // gaps < 10 are practically dead) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward fits that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * next_item_size as f64;
    }

    // Penalize wasteful fits: leaving a gap just below the next item size.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * next_item_size as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty grows with open bins count.
        score += 8.0 + 2.5 * open_bins_count as f64;
        // Opening a fresh bin is more attractive early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * (1.0 - progress);
        // If the current bin would be a poor fit elsewhere, new bin gains appeal:
        // compare mean residual: if item barely fits average open bin, allow new bin.
        if item_size as f64 > mean_residual - 5.0 {
            score -= 10.0;
        }
        // Perfect-fit culture: fresh bin guarantees clean packing of next items.
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 3.0;
        }
    } else {
        // Mild reward for using bins whose residual is above mean (drain large gaps).
        if bin_residual as f64 > mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for unusable dead space: residual too small for any item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2-step lookahead: reward when the next item exactly fits the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // partial credit, better the tighter the fit
            score -= 30.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow in this bin: mild penalty scaled by leftover
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins with residuals below the mean
    // (fill down the "emptier" spread) unless it creates a perfect fit above.
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bin before opening a new one: reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin
    // offers a tight fit; otherwise discourage opening bins unnecessarily.
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && (bin_capacity - next_item_size) >= item_size {
            score -= 10.0; // opening a bin that can chain the next item
        }
        if open_bins_count == 0 {
            score -= 200.0; // must use a bin
        }
    }

    // Late in the stream, consolidate harder (avoid opening bins near the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Strong reward for perfect fill.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            // Penalize leaving residuals that only very small items could use.
            let waste = (post_residual as f64 - (next_item_size as f64)).abs();
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when other bins fit, scaled by how many alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let alternatives = fitting_bins_count as f64;
        let open_pressure = open_bins_count as f64;
        let new_bin_penalty = 55.0 + 10.0 * open_pressure + 30.0 * (1.0 - progress);
        // Reduce the penalty if the current residual would be badly wasted anyway
        // (i.e. item barely fits nowhere well) and mean residual is high.
        let escape_bonus = if fitting_bins_count > 0 {
            let worst_waste = (mean_residual - item_size as f64).abs();
            0.2 * worst_waste
        } else {
            0.0
        };
        score += new_bin_penalty - escape_bonus;
    }

    // Mild preference for bins whose residual is close to the mean (keep balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight time-dependent tightening: as stream progresses, discourage loose fills.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * fit_ratio;

    // Tiny deterministic tie-breaker favoring fuller bins.
    score -= 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: non-linear decay of residual penalty
    let tightness = 1.0 - (pr / cap);
    score -= 18.0 * tightness.powi(3);

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: penalize residuals too small for the next item (dead space),
    // reward residuals that can host it
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 6.0 * (1.0 - pr / cap);
        } else {
            let gap = (nx - pr) / cap;
            score += 10.0 * gap.sqrt() * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 8.0 * progress;
    }

    // New-bin candidate: penalize mildly early, less late (consolidation pressure grows)
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * progress;
        // but if existing bins would leave bad residuals, new bin becomes attractive
        score += 0.15 * mean_residual;
        score -= 1.5 * open_bins_count as f64;
    }

    // Stream-progress coupling: as stream advances, prefer filling existing bins harder
    score += 5.0 * progress * (pr / cap).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is golden
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: modulo-10 buckets (classic residual classes)
    let class = post_residual % 10;
    // Residuals in {0,1} are dead space; residuals matching common item sizes are reusable
    match class {
        0 => score -= 30.0,                    // round residual, very reusable
        1 | 2 => score += 25.0,                // nearly dead
        5 => score -= 15.0,                    // half-class, flexible
        8 | 9 => score += 10.0,                // awkward
        _ => {}
    }

    // Integer-division thresholds: large residual chunks are valuable
    let chunk = post_residual / 25; // 0..4 quarters
    score -= chunk as f64 * 8.0;

    // Reward if next item fits exactly into post_residual (perfect chaining)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // coupling: next item fits, but how well?
            let next_post = post_residual - next_item_size;
            score -= 40.0 - (next_post as f64) * 0.5;
            if next_post % 10 == 0 {
                score -= 20.0;
            }
        } else {
            // next item cannot use this bin's residual; slight penalty for tight fits
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only prefer fresh bin when open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 100.0
            + fragmentation * 0.3
            + (open_bins_count as f64) * 2.0
            - progress * 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 15.0; // fresh bin can host next item too
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host even
    // the minimum item are pure waste — punish them hard.
    if post_residual < 10 {
        score += 120.0;
    } else if post_residual < 20 {
        score += 45.0;
    } else if post_residual < 35 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // residual too small for the known next item — likely dead space.
        score += 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: discourage opening new bins when few are open,
    // but allow consolidation when many bins are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bins count.
        score += 30.0 + 8.0 * (open_bins_count as f64).sqrt();
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * progress;
    } else {
        // Placing in an existing bin reduces open-bin pressure slightly.
        score -= 4.0 * (open_bins_count as f64).sqrt();
        // Prefer bins with below-average residual (keeps mean residual spread even).
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

