    // Dead-space penalty: tiny unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if lookahead chains perfectly in a fresh bin, allow it.
        if next_item_size > 0 && post_residual >= next_item_size && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 55.0;
        }
        // Early stream: opening bins cheaply spreads capacity.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 10.0;
        }
    }

    // Prefer filling bins with many open bins (consolidation pressure).
    score += 0.3 * open_bins_count as f64;

    // Mild tight-fit reward relative to item size.
    score -= 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
