        score -= 25.0;
    }

    // Many open bins: discourage spreading items; prefer filling existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.5 * pressure * (1.0 - tightness);

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when no open bin fits well (high mean residual spread / many bins).
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 30.0 - 20.0 * scarcity - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth polynomial coupling: residual squared scaled by stream progress
    score += 2.0 * norm_pr * norm_pr * (0.5 + progress) * cap;

    // Favor tight fits (low post residual) more strongly late in the stream
    score -= 1.5 * norm_item * (1.0 - norm_item) * cap * (0.3 + 0.7 * progress);

    // Penalize waste relative to mean residual across open bins
    score += 0.4 * (pr - mean_residual) / cap;

    // Last-chance bin bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let slack = (norm_pr - nx).max(0.0);
        score -= 1.2 * slack * slack * cap;
    }

    // Mild penalty on opening a new bin when many bins already fit
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * fitting_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
