    score -= class_bonus;

    // Penalize residuals in awkward dead-zone (1..10) unless tiny.
    if r > 0 && r < 10 {
        score += 15.0;
    }

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward scaled by how much slack remains
            score -= 10.0 * (1.0 - ((post_residual - next_item_size) as f64) / cap);
        } else {
            // next item cannot fit here: penalize small residuals harder
            score += 5.0 * (1.0 - pr / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current residuals are mostly unusable
    // (item is large relative to mean residual) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = item_size as f64 / mean_residual.max(1.0);
        score += 25.0 - 20.0 * tight.min(2.0) - 10.0 * (1.0 - progress);
    }

    // Prefer tighter (fuller) bins mildly: normalize residual fraction.
    score += 5.0 * (pr / cap);

    // Integer-division threshold: bins where item occupies > half capacity are good.
    if item_size * 2 >= bin_capacity && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // Modulo-25 harmonic class on residual: quarter-capacity multiples are ideal.
    if r % 25 == 0 && r > 0 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A residual below the minimum item size (1) is impossible, but small
    // gaps (< 10) are effectively dead space for typical streams; gaps that
    // cannot fit the lookahead item are also less valuable.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 25.0; // tiny unusable gap => heavy penalty
        } else if post_residual < 20 {
            score += 8.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Reward tight fits: small post_residual relative to item size.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than spreading; opening new bins is penalized via
    // the new-bin candidate (bin_residual == bin_capacity) getting a bonus.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when few bins open or late in stream
        score += 15.0 + 20.0 * (1.0 - progress) + open_bins_count as f64 * 0.5;
    } else {
        // Existing bin: reward using it, especially when open_bins_count is high
        score -= open_bins_count as f64 * 0.8;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin for a poor fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins whose residual is below the mean (denser bins first),
    // encouraging completion of nearly-full bins.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Lookahead pairing: reward placements that leave exactly the lookahead
    // size (perfect pairing) or a still-useful gap.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual >= next_item_size && post_residual <= next_item_size + 15 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Aggressive 2-step lookahead: reward when next item fits perfectly in post_residual.
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - lookahead_gap / bin_capacity as f64).max(0.0);

        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 60.0; // perfect chain match
        } else if (post_residual as u32) < next_item_size {
            // dead space relative to next item: penalize proportionally
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // next item fits but with slack: mild penalty scaled by slack
            score += 0.12 * (post_residual - next_item_size) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.25 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when reasonable open bins exist.
    if bin_residual == bin_capacity {
        let waste = bin_capacity as f64 - item_size as f64;
        score += 30.0 + 0.5 * waste;
        if fitting_bins_count > 0 && post_residual as f64 > mean_residual {
            score += 20.0 * (1.0 - progress);
        }
        // new bin more attractive late in stream when many bins already open
        score -= 15.0 * progress;
    }

    // Reward tight fits (small post_residual) nonlinearly.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 10.0 * tightness * tightness;

    // Mild penalty for very small unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Dead-space penalty: residuals too small for the smallest future item are waste.
    if post_residual < 10 {
        score += 6.0 * (10 - post_residual) as f64;
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 9.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Leftover useless for the next item: mild penalty, stronger late in stream.
            let t = step_index as f64 / (total_items.max(1) as f64);
            score += 4.0 * (0.3 + 0.7 * t);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: only attractive when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin, scaled by how many alternatives exist.
        score += 14.0 + 2.5 * (open_bins_count as f64).ln().max(0.0);
        // If the item nearly fills a whole bin, a new bin is great.
        if item_size >= 70 {
            score -= 30.0;
        }
        // Late in the stream, consolidating matters more than spreading.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * t;
    } else {
        // Prefer bins with below-average residual (denser bins keep big gaps elsewhere).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0 * ((bin_residual as f64) - mean_residual) / bin_capacity as f64;
        }
    }

    // Perfect-fit climax reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr) - 20.0 * progress * norm_pr * (1.0 - norm_pr);

    // Penalize large post-residual more as stream progresses (dead space matters later)
    score += 30.0 * progress * norm_pr * norm_pr;

    // Reward tight fits (small post residual) smoothly
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // Slight penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // New-bin candidate: mildly penalize so it only wins when fits are poor
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress) + mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable" classes
    // (divisible into small common denominators) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: extreme reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Class the residual by integer division into harmonic bands of capacity/10.
    let band = post_residual / (bin_capacity / 10).max(1); // 0..=10
    score -= match band {
        0 => 60.0,             // tiny dead space but nearly full bin: good
        1 => 40.0,
        2 => 25.0,
        3 => 10.0,
        4 => 0.0,
        5 => -5.0,             // half-full leftover is flexible
        6 => -3.0,
        7 => 5.0,
        8 => 15.0,
        9 => 30.0,             // mostly empty bin used for one item: wasteful
        _ => 45.0,
    };

    // Modulo arithmetic: residuals divisible by small integers pair well with
    // many item sizes; reward those classes.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 12.0; }
        else if post_residual % 5 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 4.0; }
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size < post_residual {
            let npost = post_residual - next_item_size;
            // reward chained fits with small final leftover
            score -= 25.0 * (1.0 - npost as f64 / cap);
            if npost % 10 == 0 { score -= 8.0; }
        } else {
            // next item cannot follow here: penalize blocking
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are poor fits for the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so a new bin is chosen only when open bins waste space.
        score += 70.0;
        // If item would leave a harmonically nice residual in a fresh bin
        // (e.g. item_size divides capacity), soften the penalty.
        if item_size > 0 && bin_capacity % item_size == 0 {
            score -= 45.0;
        }
        if post_residual % 10 == 0 { score -= 10.0; }
        // Late in the stream, avoid spawning bins for marginal gains.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Prefer bins tighter than the current mean residual (good packing).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Many open bins: encourage consolidation into fuller bins.
        if open_bins_count > 4 {
            score += 0.5 * (open_bins_count as f64).ln().max(0.0);
        }
    }

    // Slight preference for bins with residual close to item_size (tight fit).
    let tightness = 1.0 - (post as f64 / cap);
    score -= 15.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly useless.
    let dead_zone = 9.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward tight fits proportionally to fill ratio.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 10.0;

    // Penalize moderate leftover gaps that can't hold a typical next item.
    if post_residual > 0 && next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 8.0;
    }
    // Reward bins whose leftover exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is great.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = fill < 0.5 && fitting_bins_count > 1;
        if poor_fit {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    // Mild drift: late in stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits the post-residual exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // next item fits: mild reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item does NOT fit: penalize small post-residuals that waste space
            let wasted = (post_residual as f64) / bin_capacity as f64;
            score += 80.0 * wasted;
        }
    }

    // Penalize leaving a large unusable dead space relative to mean residual.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.5 * (pr - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when open bins fit poorly.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 120.0;
        // allow opening a new bin if remaining open bins have tiny residuals
        if mean_residual < 20.0 {
            score -= 140.0;
        }
    }

    // Early in the stream, be slightly more willing to spread items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a non-linear squashing
    // so that near-perfect fits are strongly preferred.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += (pr / cap).powi(3) * 40.0;

    // Reward bins whose residual exactly matches the item (perfect fit).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes the residual of
    // all existing bins; penalize unless existing fits are terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize proportional to how many bins could already fit the item.
        if fitting_bins_count > 0 {
            score += 30.0 + 8.0 * fitting_bins_count as f64;
        } else {
            // No open bin fits: opening a new bin is necessary; mild bonus.
            score -= 12.0;
        }
        // If the next item would fit nicely in the leftover of this new bin,
        // opening is more attractive (lookahead coupling).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0 + (post_residual - next_item_size) as f64 * 0.15;
        }
    } else {
        // Lookahead: reward placing the item here if the next item also fits
        // the resulting residual (chaining good placements).
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0 + (next_item_size as f64 / cap) * 10.0;
        } else if next_item_size > 0 {
            // Penalize leaving a residual too small for the next item (dead space).
            score += 4.0;
        }
    }

    // Global state coupling: when many bins are open with high mean residual,
    // encourage consolidating into existing bins rather than opening new ones.
    if !is_new_bin {
        score -= (mean_residual / cap) * 3.0;
        score -= (open_bins_count as f64).ln().max(0.0) * 1.5;
    } else {
        score += (mean_residual / cap) * 5.0;
    }

    // Time horizon: early in the stream, be more willing to open bins
    // (long future amortizes flexibility); late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if is_new_bin {
        score += progress * 15.0; // late stream: opening new bins costs more
    } else {
        score -= progress * 4.0; // late stream: favor existing bins
    }

    // Slight penalty for large unused residual relative to the item, to
    // discourage putting tiny items into huge empty spaces when alternatives exist.
    if !is_new_bin && post_residual > item_size as u32 * 2 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear base: prefer tight fits, with progressive shaping
    let mut score = norm_pr + 0.8 * norm_pr * norm_pr - 0.4 * norm_pr * norm_pr * norm_pr;

    // Stream-progress coupling: early on, tolerate loose fits; late, punish dead space harder
    let progress_term = 1.0 + 1.5 * progress * (1.0 - 0.5 * progress);
    score *= progress_term;

    // Interaction: post residual vs mean residual (avoid wasting space when bins are loose)
    let mr = mean_residual / cap;
    score += 0.6 * norm_pr * mr * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 2.0 + 1.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual, penalize near-miss dead space
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 0.5 * (1.0 - (pr - nx) / cap);
        } else {
            score += 0.3 * ((nx - pr) / cap);
        }
    }

    // Penalize opening new bins when many are open and fitting options exist
    if bin_residual == bin_capacity {
        score += 1.2 + 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover space: classify residual into deciles of capacity.
    let cap = bin_capacity as f64;
    let post_class = (post_residual as f64 / (cap / 10.0)).floor() as i32; // 0..10
    let item_class = (item_size as f64 / (cap / 10.0)).floor() as i32;

    // Dead space penalty grows super-linearly for small, hard-to-use residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward placements whose leftover matches the next item's size class (harmonic pairing).
    if next_item_size > 0 {
        let next_class = (next_item_size as f64 / (cap / 10.0)).floor() as i32;
        if post_residual > 0 {
            if (post_residual as i64) >= (next_item_size as i64) {
                // Next item can fit here afterwards: strong reward, scaled by tightness.
                let tightness = 1.0 - (post_residual as f64 - next_item_size as f64) / cap;
                score -= 30.0 * tightness;
                if post_residual == next_item_size {
                    score -= 200.0; // chain of exact fits
                }
            } else {
                // Next item cannot use the leftover: penalize proportional to waste.
                score += (next_item_size as f64) * 0.5;
            }
        }
        // Modulo harmony: leftover is an integer multiple of next item size.
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
            score -= 15.0;
        }
    }

    // Class alignment bonus: item class equal to bin's residual class implies tight fit.
    let resid_class = (bin_residual as f64 / (cap / 10.0)).floor() as i32;
    if item_class == resid_class {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when residuals
    // across open bins are large and fragmented (mean residual high relative to item).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so new bins are opened only when clearly better.
        score += 55.0;
        // If mean residual is small (bins are well-packed), opening a new bin is bad.
        if mean_residual < item_size as f64 * 1.5 {
            score += 60.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
        // Many open bins: discourage yet another one.
        score += (open_bins_count as f64).sqrt() * 4.0;
        // Exception: large items that would leave tiny dead space anywhere else
        // (post_residual here == capacity - item_size; if item is large, this is small).
        if item_size > 70 {
            score -= 70.0;
        }
    } else {
        // Mild bonus for keeping bin count stable.
        score -= 2.0;
        // Prefer fuller bins (smaller residual) beyond raw post_residual ordering.
        score -= (bin_residual as f64 / cap) * 5.0;
    }

    // Integer-division threshold: leftover divisible by common small sizes (10/20/25)
    // is more reusable in future packing.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space is worse late in the stream.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * 0.3 * progress;

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Prefer bins tighter than the mean residual (good fill).
    score -= (mean_residual - post_residual as f64) * 0.2;

    // New-bin candidate baseline: keep it moderately attractive so it wins
    // only when all open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: penalize opening a new bin unless current bin
    // fits are poor (large post_residual dead space).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 25.0;
        // If many bins fit the item, opening new bins is wasteful.
        score += 8.0 * (fitting_bins_count as f64).min(4.0);
        // If exactly one bin fits and it would leave huge dead space, allow new bin.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fills the
    // post_residual (perfect chain), penalize when next item leaves awkward gaps.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: next item exactly consumes remaining space.
        if post_residual as i64 == next_item_size as i64 {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score += 0.5 * gap;
        } else {
            // Next item won't fit here; mildly penalize small post_residual
            // (unusable sliver) but keep large residuals attractive.
            score += 0.2 * gap;
        }
        // If next item fits perfectly into post_residual AND this bin is the
        // last chance, strongly favor it.
        if fitting_bins_count == 1 && next_item_size <= post_residual {
            score -= 15.0;
        }
    }

    // Tight fit reward: small post_residual means dense packing.
    if post_residual < 10 {
        score -= 20.0;
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Relative to mean residual: prefer bins that stay near/below the mean
    // (keeps residuals balanced), penalize consuming from the emptiest bin.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Late in the stream, tighten packing further (avoid leftover slivers).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on leftover space.
    let pr = post_residual as f64;
    score += 0.6 * pr * pr / bin_capacity as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // Mild reward when many bins compete (we can afford to be picky).
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // Lookahead: penalize if the next item cannot fit into the post-residual,
    // scaled by how close the next item is to being unusable anywhere.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 4.0 + (nxt - pr) * 0.15;
        } else {
            // Reward leaving space exactly usable by the next item.
            score -= 3.0 * (1.0 - (pr - nxt) / bin_capacity as f64);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0; // near-perfect: dead space is small anyway
    }

    // Penalize leaving residuals that are hard to fill later (large awkward gaps).
    if pr > 0.0 && pr < 10.0 {
        score -= 5.0;
    }

    // Global state coupling: when many bins are open, prefer consolidating
    // into bins below the mean residual (balance the load).
    let mr = mean_residual;
    let dev = pr - mr;
    score += 0.08 * dev * (1.0 + open_bins_count as f64 / 10.0);

    // Time horizon: early in the stream, be conservative (slight penalty for
    // any placement that isn't tight); late in the stream, accept decent fits
    // to avoid opening bins for few remaining items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let remaining = (total_items.saturating_sub(step_index)) as f64;
    if remaining < 5.0 {
        // Endgame: strongly prefer existing bins over opening new ones.
        if bin_residual < bin_capacity {
            score -= 15.0;
        }
    } else {
        score += (1.0 - progress) * 2.0;
    }

    // New-bin candidate: make it moderately expensive so it is chosen only
    // when no open bin offers a reasonable fit (score otherwise dominated by
    // tight fits and last-chance bonuses).
    if bin_residual == bin_capacity {
        score += 30.0 + 0.1 * open_bins_count as f64;
        // But if the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Normalized post-residual and its smooth polynomial shaping.
    let x = post / cap;
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep: penalizes mid-range waste softly
    let mut score = post * (1.0 + 0.8 * poly);

    // Non-linear coupling of waste with stream progress: late in the stream,
    // dead space is more costly, so amplify the quadratic term.
    score += 40.0 * progress * x * x;

    // Reward tight fits (small post_residual) with a smooth exponential bonus.
    score -= 25.0 * (-post / 12.0).exp();

    // Last-chance bin: strongly reward using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // reward; if it cannot fit, penalize slightly (wasted capacity).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 15.0 * (1.0 - (post - nxt) / cap).abs().min(1.0);
        } else {
            score += 8.0 * (1.0 - progress);
        }
    }

    // New-bin candidate: default penalty so existing bins are preferred,
    // smoothly relaxed when the item is large relative to remaining capacity
    // of open bins (approximated via mean_residual) late in the stream.
    if bin_residual == bin_capacity {
        let pressure = (item / cap) * (1.0 - (mean_residual / cap).clamp(0.0, 1.0));
        score = cap - 30.0 * pressure * (0.5 + 0.5 * progress) + 10.0 * (1.0 - item / cap);
    }

    // Mild regularization toward the mean residual to spread load smoothly.
    score += 0.05 * (post - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead-space" classes are preferred.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity left over after placement.
    let post_frac = post / cap;

    // Classify leftover into harmonic bands (1/8 granularity).
    let band = (post_frac * 8.0).floor(); // 0..8
    match band as u32 {
        0 => score -= 18.0,               // near-perfect fit
        1 => score -= 12.0,               // excellent
        2 => score -= 6.0,                // good
        3 => score += 2.0,                // mediocre
        4 => score += 6.0,                // half-empty leftover
        5 => score += 9.0,
        6 => score += 11.0,
        _ => score += 13.0,               // large dead space
    }

    // Exact modulo harmony: post_residual divisible by small integers
    // suggests future small items can tile the leftover.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 5.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        if pr % 7 == 0 { score -= 2.0; }
        if pr % 3 == 0 { score -= 1.0; }
    }

    // Lookahead coupling: if the next item fits exactly into the leftover,
    // strongly reward; if it cannot fit, penalize proportional to its size.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (1.0 - (ni / (post + 1.0)));
        } else {
            score += 4.0 + 0.08 * (ni - post);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open
        // (fragmentation pressure) or late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 22.0;
        if open_bins_count > 4 { new_bin_cost -= 3.0; }
        if open_bins_count > 8 { new_bin_cost -= 3.0; }
        if progress > 0.75 { new_bin_cost -= 2.0; }
        // A new bin is relatively better when the item is large (few bins fit).
        if item_size > bin_capacity / 2 { new_bin_cost -= 6.0; }
        if item_size > (3 * bin_capacity) / 4 { new_bin_cost -= 6.0; }
        score += new_bin_cost;
    }

    // Slight preference for fuller bins overall (best-fit flavor).
    score -= 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=10) are "dead"
    // because future items (min size 1) rarely fit well; penalize hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0 * (1.0 - (post_residual as f64) / 10.0) + 10.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Larger leftovers are reusable: mild reward proportional to size.
        score -= (post_residual as f64) * 0.15;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: many open bins -> favor consolidating into
    // existing bins; penalize the new-bin candidate (residual == capacity).
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * pressure;
    } else {
        score -= 2.0 * pressure.min(15.0);
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward heavily (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Next item cannot use the leftover: dead space confirmed.
            score += (post_residual as f64) * 0.1;
        }
    }

    // Deviation from mean residual: prefer bins whose residual is close to
    // the mean (balanced packing), penalize outliers.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0;

    // Early in the stream, be slightly more willing to open bins to build
    // a diverse residual portfolio.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter fit (smaller post_residual) is better.

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();
        if post >= next {
            // Next item can chain into this bin.
            score -= 25.0 * (1.0 - diff / 60.0).max(0.0);
            if diff < 1.0 {
                score -= 30.0; // perfect chain: post_residual exactly next_item_size
            }
        } else {
            // Dead space that the next item cannot use; penalize proportionally.
            score += 0.35 * (next - post).min(40.0);
        }
    } else {
        // Last item: pure tightness.
        score += 0.5 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual far above mean are generic
    // candidates; prefer bins that are tighter than average.
    let post_f = post_residual as f64;
    score += 0.25 * (post_f - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, slightly prefer bins that are less "valuable" overall.
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate (empty bin): only attractive when the item is large and
    // no good chain exists; otherwise keep filling open bins.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let no_chain = next_item_size == 0 || post_residual < next_item_size;
        let many_open = open_bins_count as f64 > 4.0 + 6.0 * (step_index as f64 / total_items.max(1) as f64);
        if large_item > 0.5 && no_chain && many_open {
            score -= 8.0; // allow opening a fresh bin for huge items with no chain
        } else {
            score += 15.0; // discourage opening bins while decent fits exist
        }
    }

    // Mild penalty for leaving tiny unusable gaps (< 10 units) unless chainable.
    if post_residual > 0 && post_residual < 10 && (next_item_size == 0 || post_residual < next_item_size) {
        score += 6.0;
    }

    // Small pressure toward consolidating bins as the stream progresses.
    score -= 0.01 * (open_bins_count as f64) * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual).
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small to hold typical future items.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += 2.5 * (dead_threshold - post_residual as f64);
    }

    // Lookahead coupling: bonus if next item exactly fills post_residual or fits well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual; mild penalty proportional to leftover
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins attractive only when fits are poor.
    if bin_residual == bin_capacity {
        let avg_fit = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 15.0 * avg_fit + 0.3 * mean_residual;
        // Early in the stream, opening bins is cheap; later, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation pressure).
    score -= 0.05 * bin_residual as f64 * (open_bins_count as f64).ln().max(0.0);

    // Slight preference for bins below mean residual to balance load.
    score += 0.02 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer low post-residual, with non-linear shaping
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth coupling of post-residual with stream progress:
    // later in the stream, tighten more aggressively (quadratic ramp)
    score += 30.0 * norm_pr * norm_pr * (progress * progress);

    // Reward tight fits (small post_residual relative to item) with smooth term
    score -= 0.5 * item * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Lookahead: reward bins whose post-residual matches the next item size
    if next > 0.0 {
        let match_term = (pr - next).abs() / cap;
        score += 25.0 * match_term * match_term;
        score -= 5.0 * (1.0 - (pr - next).abs() / cap) * progress;
    }

    // Penalize creating dead space that likely cannot be filled
    if pr < 10.0 {
        score -= 20.0 * (10.0 - pr) as f64 / 10.0; // near-zero residual is great
    }
    score += 8.0 * (1.0 - (pr / 10.0).min(1.0)) * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild preference for bins with residual below mean (compact bins)
    score += 0.3 * (pr as f64 - mean_residual) * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin, more so early and when fits exist
    if bin_residual == bin_capacity {
        score += 40.0 + 30.0 * progress;
        if fitting_bins_count > 0 {
            score += 20.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item sizes (harmonic classes) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are "harmonic" with typical item sizes.
        let class = pr % 10;
        let harmonic_bonus = match class {
            0 => 12.0,          // multiple of 10: most reusable
            5 => 6.0,           // multiple of 5
            2 | 4 | 6 | 8 => 3.0, // even
            _ => 0.0,           // odd: poor reuse
        };
        score -= harmonic_bonus;

        // Integer-division threshold: tiny dead space is wasted space.
        if pr < 10 {
            score += 25.0; // dead space penalty
        } else if pr <= 20 {
            score -= 4.0;  // still usable for small items
        }

        // Coupling with lookahead item: if next item fits exactly into the
        // post residual, strongly reward this placement.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 40.0; // perfect chaining
            } else if pr >= next_item_size {
                score -= (pr - next_item_size) as f64 * 0.5;
                // harmonic match: next item divides residual
                if pr % next_item_size == 0 && next_item_size >= 10 {
                    score -= 10.0;
                }
            } else {
                // next item cannot use this residual; penalize proportionally
                score += (next_item_size - pr) as f64 * 0.2;
            }
        }
    } else {
        // Perfect fill: best possible outcome.
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin when the item fits well
    // elsewhere; but if this bin is fresh (residual == capacity) treat it
    // neutrally so it wins only when open bins are bad fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (tighter packing targets).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Slight pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let post = post_residual as f64;
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post) * 12.0; // dead space of 1..10 is worse than large leftovers
    }
    if post_residual == 0 {
        score -= 30.0; // perfect fit strongly rewarded
    } else {
        // fractional fill quality: prefer bins where item fills a large share of residual
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 10.0;
    }

    // Open-bins pressure: discourage scattering across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (item large relative to mean residual) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 25.0 + mean_residual * 0.3 - progress * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity && next_item_size as f64 > mean_residual {
            score -= 10.0; // new bin can host the next item too
        }
        if item_size as f64 >= mean_residual {
            score -= 15.0; // open bins are too full for this item anyway
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here afterwards: strong reward proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.3;
        } else {
            // Dead space relative to the lookahead item: penalize unusable remainder.
            let dead = (post_residual as f64).min((next_item_size - post_residual) as f64);
            score += dead * 0.8;
        }
    } else {
        // Last item: simply prefer tightest fit.
        score += 0.0;
    }

    // Prefer tight fits relative to the mean residual of open bins.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.15;

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (unless post_residual is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when the item
    // is large or current bins have poor residual structure. Penalize opening
    // a new bin mildly so it wins only when existing fits are bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Large items or many open bins with big residuals favor a fresh bin.
        score += 40.0
            - item_frac * 45.0
            - (open_bins_count as f64 * 1.5).min(15.0)
            + mean_residual * 0.1
            - progress * 5.0;
        // If the next item is small, a fresh bin wastes potential; discourage.
        if next_item_size > 0 && next_item_size <= 20 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best; quadratic penalty on waste.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // current fit is poor. Make the empty bin moderately attractive but not dominant.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, new bins are cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item fits but not perfectly: mild reward proportional to tightness.
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 * tight;
        } else {
            // Next item won't fit in the residual: penalize leaving awkward gaps.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap.min(50.0);
        }
    }

    // Global state: when many bins are open with high mean residual, prefer
    // consolidating into existing bins rather than spreading out.
    if bin_residual != bin_capacity {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 0.15 * spread;
        // Slight bonus for using bins with below-average residual (filling fuller bins).
        if (post_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Penalize very small residuals that become dead space (unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Mild preference for keeping the number of open bins in check late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, non-linearly
    let mut score = pr.powf(1.3);

    // Smooth polynomial coupling of post-residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them more
    let coupling = 1.0 + 2.0 * progress * (1.0 - progress) * 0.5 + progress * progress;
    score *= coupling;

    // Penalize dead space (very small residuals that nothing can use)
    let dead = (1.0 - (pr / 10.0).min(1.0)).max(0.0);
    score += 40.0 * dead * (0.5 + progress);

    // Reward tight fits
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // Last-chance bonus: only fitting bin -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 15.0 * (next_item_size as f64 / cap);
        } else {
            score += 10.0 * (1.0 - pr / (next_item_size as f64).max(1.0));
        }
    }

    // Slight preference for filling bins with lower-than-mean residual
    score += 0.5 * (mean_residual - pr);

    // New-bin candidate: make it moderately attractive only when residuals are poor
    if bin_residual == bin_capacity {
        score = pr as f64 - 20.0 * (1.0 - progress) + 30.0 * progress * (1.0 - norm_pr);
        if fitting_bins_count <= 1 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.5;

    // Harmonic class of post_residual: residues near multiples of 10 are "usable" dead space
    let r = post_residual % 10;
    let residue_penalty = match r {
        0 => -12.0,               // perfect decade residual, very reusable
        1..=3 => 4.0,             // awkward sliver
        4..=6 => 0.0,
        7..=9 => -3.0,            // can absorb a small item (sizes 7-9 common)
        _ => 0.0,
    };
    score += residue_penalty;

    // Integer-division thresholds: post_residual buckets
    let bucket = post_residual / 10;
    score += match bucket {
        0 => -8.0,   // almost full bin: excellent
        1 => -4.0,
        2 => 0.0,
        3 => 3.0,
        _ => 6.0,    // mostly empty bin chosen: wasteful
    };

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this residual; penalize proportionally to wasted space
            score += (post_residual as f64).min(next_item_size as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when current residual is very poor
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 15.0;
        // If item fits tightly in a fresh bin relative to capacity, slight discount
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.8 { score -= 10.0; }
        // If open bins are crowded (mean residual low), opening is more acceptable
        score -= (mean_residual / bin_capacity as f64) * 5.0;
        // Late in the stream, prefer consolidating
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 5.0;
        }
    }

    // Prefer bins with residual close to item (best-fit sharpening)
    score += (post_residual as f64).powf(1.5) * 0.05;

    // Mild penalty for spreading across too many open bins
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: punish gaps that are too small to hold
    // any plausible future item (below the minimum item size of 1, but
    // practically below a useful threshold ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    } else if post_residual < 25 {
        // Moderate dead-space penalty with quadratic coupling.
        score += (25.0 - post_residual as f64) * (25.0 - post_residual as f64) * 0.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Exact fit for the lookahead item: very desirable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    }
    // Lookahead fits comfortably: mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead won't fit here: penalize to prefer bins where it can.
        score += 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins when
    // open_bins_count is high, encouraging consolidation.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: make it unattractive unless residual is very tight
    // elsewhere; slight bonus early in the stream.
    if bin_residual == bin_capacity {
        score += 120.0 - (step_index as f64 / total_items.max(1) as f64) * 60.0;
    }

    // Prefer bins below mean residual (tighter bins) mildly.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.9;
        if post_residual == next_item_size {
            score -= 18.0; // perfect 2-chain: item + next item fills bin
        } else if post_residual > next_item_size {
            score -= 6.0; // can still host the next item
        }
        // Penalize leaving dead space the next item cannot use
        if post_residual < next_item_size {
            score += (post_residual as f64) * 0.25;
        }
    }

    // Prefer tight fits: relative residual against mean residual of open bins.
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Penalize small unusable post_residual (dead space) non-linearly.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.5;
    }

    // Last-chance bonus: only bin that fits the item -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral baseline, slight penalty so it is only
    // chosen when open bins would waste too much space.
    if bin_residual == bin_capacity {
        score += 8.0;
        // Opening a new bin is attractive late in the stream or when open bins are crowded.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 4.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // large next item pairs well with a fresh bin
        }
    }

    // Mild preference for filling fuller bins early.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Penalize wasted space relative to capacity (dead space creation).
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // Lookahead (k=2): reward bins whose post-residual can host the next item,
    // penalize leaving a sliver the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual > 0 {
            score += 0.5 * post_residual as f64; // stranded sliver
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large (would leave a big, reusable residual) or few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let large_item = item_size as f64 / bin_capacity as f64;
        let opening_pressure = 8.0 * (1.0 - large_item) - 2.0 * progress - 0.3 * open_bins_count as f64;
        // Empty bin starts with post_residual = capacity - item_size; adjust score.
        score += opening_pressure.max(-25.0).min(25.0);
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += 0.02 * open_bins_count as f64 * (bin_residual as f64 - mean_residual).abs();

    // Small time-decay: late in the stream, prefer filling existing bins tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let r = post_residual as f64 / bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // waste is penalized more aggressively as the stream matures.
    let coupling = r * r * (1.0 + 2.0 * progress) + r * progress * progress;
    score += 40.0 * coupling;

    // Perfect or near-perfect fits get a strong reward, modulated by progress.
    if post_residual == 0 {
        score -= 60.0 + 30.0 * progress;
    } else if post_residual <= 5 {
        score -= 25.0 + 15.0 * progress;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 * (1.0 - slack);
        } else {
            // Dead space the next item cannot use, penalized non-linearly.
            let dead = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 15.0 * dead * dead;
        }
    }

    // Slight aversion to fragmenting bins when many bins are open and residuals are high.
    let frag = (mean_residual - post_residual as f64).abs() / bin_capacity as f64;
    score += 5.0 * frag * (1.0 - progress);

    // New-bin candidate: keep it neutral-to-slightly-attractive only when the item
    // fits poorly everywhere else; otherwise discourage spreading across bins.
    if bin_residual == bin_capacity {
        let tight = item_size as f64 / bin_capacity as f64;
        score += 10.0 * (1.0 - tight) - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by large
    // power-of-two classes are more "reusable" by typical item sizes.
    let pr = post_residual;
    let harmonic = if pr == 0 {
        0.0 // perfect fit — best possible outcome
    } else if pr % 50 == 0 {
        1.0
    } else if pr % 25 == 0 {
        2.0
    } else if pr % 10 == 0 {
        3.0
    } else if pr % 5 == 0 {
        4.0
    } else if pr % 2 == 0 {
        5.0
    } else {
        6.0
    };
    score += harmonic * 4.0;

    // Dead-space penalty: small unusable leftovers (below the smallest
    // plausible item) are wasted capacity.
    if pr > 0 && pr < 10 {
        score += 60.0;
    } else if pr < 20 {
        score += 12.0;
    }

    // Reward tight fits (best-fit baseline sharpened by fill ratio).
    let fill = (item_size as f64) / cap_f;
    score -= fill * 15.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement enables a perfect follow-up — big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if pr >= next_item_size {
            // next item still fits: mild reward scaled by leftover quality
            score -= 8.0 * ((pr - next_item_size) as f64 / cap_f);
        } else {
            // next item will not fit here: penalize blocking future packing
            score += 6.0 + (next_item_size as f64 - pr as f64) * 0.3;
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when existing bins would leave bad dead space or the
    // stream is early (plenty of future items to fill a fresh bin).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        // Prefer new bin when existing residuals barely fit (large mean gap
        // implies tight fits elsewhere) or stream is young.
        score = 55.0 + progress * 45.0 - mean_gap * 0.8 - fill * 10.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 12.0; // fresh bin can host a good pair
        }
        if fitting_bins_count <= 1 {
            score += 30.0; // don't abandon the last usable bin cheaply
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 10) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with
    // few open bins, opening a new one is cheap so a poor fit is avoided.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + 8.0 * progress);
    score += 2.5 * pressure;

    // If this bin's residual is far above the mean, it is roomy; mildly
    // prefer saving roomy bins for big future items.
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Lookahead: if the next item fits exactly in the post-residual, keep
    // this bin attractive; if next item would not fit, residual is dead.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // New-bin candidate: baseline attractiveness so it wins only when all
    // open bins are poor fits.
    if bin_residual == bin_capacity {
        score = 45.0 + 2.0 * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: exact fill is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Matched lookahead: the tighter the fit for the next item, the better.
            let next_fit_tightness = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.4 * next_fit_tightness;
        } else {
            // Post-residual too small for the next item: dead-space penalty,
            // scaled by how close it came (small leftover gap is less wasteful).
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.3 * gap;
        }
    }

    // Compare post_residual against mean residual: creating a much-below-average
    // residual fragment is penalized (unusable sliver), while keeping residuals
    // near the mean preserves packing flexibility.
    let pr = post_residual as f64;
    if pr < mean_residual * 0.35 {
        score += 25.0;
    } else if (pr - mean_residual).abs() < 8.0 {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the
    // item is large (would leave an awkward fragment in any existing bin) or the
    // stream is early (plenty of future items to fill the new bin).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let large_item_bonus = item_size as f64 * 1.2;
        let early_stream_bonus = (1.0 - progress) * 30.0;
        score += 120.0 - large_item_bonus - early_stream_bonus;
    }

    // Mild preference for filling fuller bins among equals (small post_residual already
    // encodes this; add tie-break noise-free coupling with occupancy).
    score += 0.05 * (bin_capacity - bin_residual) as f64 * -1.0 * 0.0; // no-op guard

    // Penalize opening many bins late in the stream when consolidation is possible.
    if open_bins_count > 4 && progress > 0.6 && bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual nonlinearly.
    let fit_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * fit_ratio * fit_ratio * (item_size as f64);

    // Perfect or near-perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Dead space penalty: residuals too small for any future item (min size 1..100 unknown,
    // assume small items may come) — mildly penalize mid-range dead space.
    if post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward keeping this residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // Next item could still go here; mild reward proportional to how well it fits.
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64));
        } else {
            // Next item cannot fit here; penalize leaving a residual that blocks it.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Early in the stream, opening bins is cheaper (more items to come to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Global state coupling: if mean residual is high, prefer spreading load into emptier bins.
    if (mean_residual - post_residual as f64).abs() > 30.0 {
        score += 3.0;
    }
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Many open bins: discourage fragmentation, favor filling existing bins.
    if open_bins_count > 5 {
        score -= 1.5 * (open_bins_count.min(20) as f64) * (fit_ratio);
    }

    // Time horizon: late in the stream, tightness matters more (few chances to recover).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer leaving moderate space (mild penalty on very tight fits);
    // late, tight fits (small post_residual) are heavily rewarded.
    let tightness = (pr_norm * std::f64::consts::PI).sin(); // 0 at empty, 1 at half, 0 at full
    score -= tightness * (1.0 - progress) * 12.0;
    score += pr_norm * pr_norm * 40.0 * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += 3.0;
    }

    // Penalize bins deviating from mean residual (fragmentation control),
    // scaled smoothly by progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev.abs() * (5.0 + 10.0 * progress);

    // Mild penalty on opening new bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space below the smallest item (<=10)
    // is unusable; penalize it strongly via modular arithmetic on capacity fractions.
    let small_threshold = bin_capacity / 10; // = 10
    if post_residual < small_threshold {
        score += (small_threshold - post_residual) as f64 * 3.0;
    } else if post_residual == 0 {
        score -= 50.0; // perfect fit reward
    }

    // Quotient class: post_residual / 10 tells how many small items still fit.
    let slots = post_residual / small_threshold;
    score -= slots as f64 * 2.0;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item cannot use this bin's leftover: penalize large leftovers
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < small_threshold {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a baseline that must be beaten
    // only by genuinely good fits; encourage opening fresh bins early in stream
    // or when mean residual is already high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = bin_capacity as f64 * 0.6
            - progress * 10.0
            - (mean_residual / bin_capacity as f64) * 15.0;
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "dead space": small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 2.0; // tiny gaps are worst
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Pressure from number of open bins: prefer filling existing bins
    // when many are open; allow opening new bins when few are open.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    score += pressure;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        score += 8.0; // dead space relative to lookahead
    }

    // Mean residual coupling: bins far below mean residual are less attractive
    // (keeps residual distribution tight for future items).
    score += ((bin_residual as f64) - mean_residual) * 0.15;

    // New-bin candidate handling: empty bin gets a moderate default score,
    // beaten by good fits but beating poor fits into nearly-full bins.
    if bin_residual == bin_capacity {
        score = 35.0 + pressure - (item_size as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward tiny post residuals strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space non-linearly (small leftovers are least useful).
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 2.0;
        }
    }

    // 2-step lookahead: if the next item exactly matches post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Next item fits here: mildly reward, scaled by how well it fills afterwards.
            let chain_residual = post_residual - next_item_size;
            score -= 10.0 * (1.0 - chain_residual as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit after placing here: penalize proportionally to overshoot.
            let overshoot = (next_item_size - post_residual) as f64;
            score += overshoot * 0.3;
        }
    }

    // Compare against mean residual: prefer bins that are tighter than average.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.5;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's genuinely better.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in stream, new bins are cheaper; late, avoid bin proliferation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
        // If next item is huge, a fresh bin is attractive.
        if next_item_size > 60 {
            score -= 25.0;
        }
    }

    // Slight preference for fewer open bins when many are open (fragmentation control).
    if open_bins_count > 5 {
        score += (open_bins_count as f64 - 5.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post-residual non-linearly.
    if post_residual > 0 {
        score += (post_residual as f64 / bin_capacity as f64).powf(1.7) * 18.0;
    } else {
        // Perfect fill is excellent.
        score -= 30.0;
    }

    // Lookahead: if the next item fits into this bin's post-residual,
    // reward; if post-residual is dead space (too small for anything
    // but next item can't use it), penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual > 0 {
            // dead space unless next item small enough on average
            let dead = post_residual as f64;
            score += dead * 0.25;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when open bins are badly fragmented relative to the item.
    if bin_residual == bin_capacity {
        let fragmentation = if mean_residual > 0.0 {
            (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64
        } else { 0.0 };
        // Base cost of a fresh bin, discounted by how useless existing
        // residuals are for this item.
        score += 40.0 - fragmentation * 60.0;
        // Early in the stream, prefer keeping few bins; later, opening
        // is cheaper since consolidation chances shrink.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    } else {
        // Placing into an existing bin saves a bin: reward, scaled by
        // how many bins are already open (more open bins -> more value).
        score -= 8.0 + (open_bins_count.min(20) as f64) * 0.5;
    }

    // Mild pull toward bins whose residual is close to mean: keeps
    // residual distribution balanced for future items.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Base preference: minimize post residual with non-linear emphasis on small leftovers
    score += 0.35 * (post / cap) * (1.0 - post / cap) * cap;

    // Perfect fit reward (smooth exponential)
    score -= 12.0 * (-(post / cap * 6.0)).exp();

    // Dead-space penalty: residual too small for typical future items
    let dead_threshold = 0.12 * cap;
    if post < dead_threshold {
        score += 8.0 * (1.0 - post / dead_threshold).powi(2);
    }

    // Lookahead: if next item fits in post residual, reward; else penalize
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 3.0 * (nxt - post) / cap;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 0.05 * post;
    }

    // New-bin candidate (empty bin): penalize mildly unless existing fit is bad
    if bin_residual == bin_capacity {
        score += 5.0 + 0.02 * item_size as f64;
        // Early stream: opening bins is cheap and useful
        score -= 8.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
    }

    // Stream progress: later in stream, be greedier about tight fits
    score -= 4.0 * progress * (1.0 - post / cap);

    // Mild penalty when bin deviates from mean residual (keeps bin diversity)
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of small divisors) are more valuable to keep tidy.
    let pr = post_residual;
    let usable = (pr == 0)
        || (pr % 10 == 0)
        || (pr % 25 == 0)
        || (pr % 50 == 0)
        || (pr % 20 == 0);
    if usable {
        score -= 6.0;
    } else {
        // Dead-space penalty grows for awkward leftovers in low bands.
        let band = (bin_capacity - pr) as f64 / bin_capacity as f64;
        score += 4.0 * (1.0 - band) * (1.0 - band);
    }

    // Perfect fit is the best possible outcome.
    if pr == 0 {
        score -= 25.0;
    } else if pr <= 5 {
        score -= 12.0;
    }

    // Lookahead harmony: does the leftover accommodate the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Leftover is reusable by the next item -> reward, scaled by how snug.
            let snug = (pr - next_item_size) as f64;
            score -= 5.0 - 0.05 * snug;
            if next_item_size % 10 == 0 && pr % 10 == 0 {
                score -= 3.0; // harmonic alignment of both residuals
            }
        } else {
            // Leftover too small for next item: penalize proportionally to waste.
            let waste = (next_item_size - pr) as f64;
            score += 0.08 * waste;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (many fitting bins -> keep compacting, discourage new bin).
    if bin_residual == bin_capacity {
        let pressure = fitting_bins_count as f64;
        score += 8.0 + 2.5 * pressure;
        // Early in the stream, opening bins is cheaper; late, avoid sprawl.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 6.0 * progress;
        // Large items justify fresh bins.
        if item_size >= bin_capacity / 2 {
            score -= 9.0;
        }
    }

    // Prefer filling bins below the mean residual (compaction tendency).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        if diff > 0.0 {
            score -= 0.05 * diff.min(50.0);
        }
    }

    // Harmonic threshold on item size: big items prefer tightest residual.
    let big_item = item_size > bin_capacity / 2;
    if big_item {
        score += 0.10 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space hard
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Pressure from number of open bins: prefer compacting when many bins open
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item fits the post residual exactly-ish, reward
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }
    // If next item is bigger than post residual, penalize leaving a tempting-but-insufficient gap
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Dead-space ratio relative to mean residual
    if mean_residual > 0.0 {
        score += (post_residual as f64 / mean_residual) * 3.0;
    }

    // New-bin candidate: make it moderately unattractive unless open bins are scarce
    if bin_residual == bin_capacity {
        score += 25.0 - open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Tighter chain-fit is better: subtract more when next item nests well.
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 150.0; // exact 2-step chain: both items consumed fully.
            }
        } else {
            // Penalize creating dead space that the next item cannot use.
            let dead = (post_residual - (post_residual % next_item_size.max(1))) as f64;
            score += 0.5 * dead;
        }
    }

    // Compare against mean residual: bins tighter than average are better targets.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * diff;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize new-bin candidate so it's only chosen when open bins fit poorly,
    // except when the item is huge and would leave unusable fragments elsewhere.
    if bin_residual == bin_capacity {
        score += 60.0;
        // A fresh bin is attractive for very large items with no good fit.
        if item_size > bin_capacity / 2 && (bin_residual - item_size) == 0 {
            score -= 400.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Mild preference for filling more-open bins when many are open.
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // Penalize unusable dead space: post_residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward if the next item fits into the post residual (chaining),
    // penalize if it almost fits (wasting the leftover).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else if next_item_size > post_residual && next_item_size - post_residual <= 15 {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate logic: opening a fresh bin is only attractive when the
    // current fit is poor and the stream still has plenty of items left.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream.
        score += 25.0 + 20.0 * progress;
        // Attractive if this item would leave large dead space elsewhere.
        if post_residual < 20 {
            score -= 30.0;
        }
    } else {
        // Penalize spreading across many open bins when mean residual is high.
        if (mean_residual - post_residual as f64).abs() > 30.0 {
            score += 5.0;
        }
        // Slight penalty for using a bin that is already quite full of small leftovers.
        if bin_residual < item_size + 10 {
            score += 3.0;
        }
    }

    // Mild preference for balancing residuals toward the mean across open bins.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping.
    let mut score = 2.0 * pr + 40.0 * norm_pr * norm_pr;

    // Stream-progress coupling: later in stream, punish residual more aggressively.
    score += 30.0 * progress * norm_pr * (1.0 - progress);

    // Perfect/near-perfect fit reward (smooth exponential-like via polynomial).
    let fit_quality = 1.0 - norm_pr;
    score -= 25.0 * fit_quality * fit_quality * fit_quality;

    // Penalize dead space that next item can't use.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let unusable = if pr < ns { (ns - pr) / cap } else { 0.0 };
        score += 20.0 * unusable * unusable;
        // Reward leaving exactly enough room for next item (smooth coupling).
        let gap = (pr - ns).abs() / cap;
        score -= 15.0 * (1.0 - gap) * (1.0 - gap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Mild penalty when many bins are open (consolidation pressure).
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins near the mean (balance).
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: neutral-ish baseline, penalized late in stream.
    if bin_residual == bin_capacity {
        score += 60.0 * (1.0 - progress) + 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (post_residual small)
    if post_residual == 0 {
        score -= 120.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 60.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Harmonic classes of post_residual: dead space that cannot host
    // small items (>=1) is penalized; classes divisible by common small
    // sizes are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let class_penalty = match pr % 10 {
            0 => 0.0,                      // highly reusable class
            1 | 2 | 3 | 4 | 5 => 18.0,     // awkward slivers
            _ => 8.0,
        };
        score += class_penalty;

        // Fraction-of-capacity coupling: residuals near half capacity
        // are flexible, near-full or near-empty extremes less so.
        let frac = pr as f64 / bin_capacity as f64;
        score += 25.0 * (frac - 0.5).abs();
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward strongly; if it cannot fit, penalize mildly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let diff = post_residual - next_item_size;
            if diff == 0 {
                score -= 45.0;
            } else if diff <= 10 {
                score -= 20.0;
            }
        } else {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate: make it unattractive unless current bin would
    // be badly fragmented. Brand-new bin gets a fixed opening cost plus
    // a penalty that grows with how many bins are already open.
    if bin_residual == bin_capacity {
        score += 90.0 + 6.0 * open_bins_count as f64;
        // Allow new bin only if item leaves a bad remainder in every
        // existing bin context: soften when item is large.
        let big = item_size as f64 / bin_capacity as f64;
        score -= 80.0 * big * big;
    }

    // Progression: slightly tighten thresholds later in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below the mean (compact them first).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    // Gaps below the minimum plausible item size (1..=100, but small gaps < 10 are near-useless)
    // are heavily penalized; moderately small gaps get a quadratic penalty.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // dead space: nothing can ever fill this
        } else if post_residual < 25 {
            score += 0.9 * (25.0 - post_residual as f64) * (25.0 - post_residual as f64) / 2.0;
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // If next item would fit in post residual, mild reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item would NOT fit after this placement, penalize (this placement blocks lookahead).
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // (make existing bins more attractive), i.e. penalize the empty new-bin candidate.
    if bin_residual == bin_capacity {
        score += 15.0 + 4.0 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins whose residual deviates favorably
    // from the mean — tight bins (small residual) are more valuable to fill now.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Late-stream consolidation: as the stream progresses, tighten preference for
    // near-full bins to avoid scattering leftovers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.10 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward: zero post-residual is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this placement enables a perfect chain.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits too: mild bonus proportional to tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit in the post-residual: penalize dead space
            // that is too small for the next item.
            let dead = next_item_size - post_residual;
            score += 8.0 * dead as f64 / item_size.max(1) as f64;
        }
    }

    // Reward leaving residuals that are hard to use later (small dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when few/no good fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (fitting_bins_count == 0) as i32 as f64 * 30.0
            + (fitting_bins_count == 1) as i32 as f64 * 10.0;
        score += 20.0 - pressure - 5.0 * progress;
    }

    // Mild preference to fill more-opened bins early in the stream.
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * bin_capacity as f64) * 20.0;

    // Penalize dead space that can never fit a typical item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (post_residual as f64 - next_item_size as f64) * 0.1;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // This placement destroys space needed by the next item
            score += 15.0;
        }
    }

    // New-bin candidate handling: only prefer fresh bin when existing fits are poor
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when existing bins are bad
        score += 30.0;
        // More open bins with high mean residual => prefer reusing
        score += open_bins_count as f64 * 2.0;
        score += mean_residual * 0.5;
        // Early in stream, opening bins is cheap; later, reuse matters
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If next item is large, a fresh bin is attractive
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Reward bins whose residual is close to item (best-fit flavor with scaling)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    // Slight preference for bins below mean residual (consolidate waste)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual (tight fit)
    let mut score = pr;

    // Non-linear polynomial coupling of post residual with stream progress:
    // tightness matters more as the stream advances
    let tight = (norm_pr * norm_pr) * (0.5 + progress);
    score += 40.0 * tight;

    // Penalize residuals too small to ever be useful again (dead space),
    // smooth quadratic around the minimum plausible item size
    let dead = ((pr as f64) - 10.0).max(0.0) / cap;
    score -= 25.0 * (1.0 - dead).max(0.0) * (1.0 - dead).max(0.0) * (1.0 - progress);

    // Lookahead: reward if next item fits the post residual (smooth kernel)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_kernel = (-gap / 30.0).exp();
        score -= 20.0 * fit_kernel;
    } else {
        // last item: strongly prefer filling bins completely
        score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        // penalize new bins mildly early, more when many bins already open
        score += 10.0 + 3.0 * (open_bins_count as f64).sqrt() + 20.0 * progress;
        // but if post residual would be perfect for the next item, soften
        if next_item_size > 0 && (pr - next_item_size as f64).abs() < 5.0 {
            score -= 25.0;
        }
    }

    // Mild penalty when this bin's residual is far from the mean residual
    // (prefer balanced packing), smooth quadratic
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: leftover >= 50 (can host any item) -> good
    // Class 1: leftover in 10..50 -> moderate
    // Class 2: leftover < 10 -> dead space -> penalize
    let pr = post_residual;
    if pr < 10 {
        score += 60.0; // dead space penalty
    } else if pr < 50 {
        score += 15.0;
    } else {
        score -= 20.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 45.0;
        } else {
            // penalize when next item almost fits but not quite (wasted potential)
            let gap = (next_item_size - pr) as f64;
            if gap <= 10.0 {
                score += 25.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Prefer bins with residual far below mean (tight bins absorb items)
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Modulo / integer-division thresholds on post_residual (harmonic classes)
    let pr_class = pr / 25; // 0,1,2,3 quartile class
    score += match pr_class {
        0 => 0.0,
        1 => -10.0,
        2 => -5.0,
        _ => -12.0,
    };

    // Penalize opening new bins when many open bins exist and stream is early
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, discounted late in the stream
        score = score.max(0.0) + 30.0 + 40.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (low post_residual), but with a dead-space penalty.
    score += post_residual as f64;

    // Strict dead-space avoidance: residual gaps that are too small to ever
    // hold a future item (min item size 1, but practically < 10) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver penalty
    }
    // Medium dead space (10..=20) is risky: only tiny items can use it.
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward near-perfect packing.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage proliferating bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin offers a decent fit. Penalize the
    // empty bin mildly so existing bins win on tight fits, but if the best
    // post_residual among open bins is poor, the empty bin's clean 100-C
    // residual should win. We approximate: empty bin gets a moderate score
    // that tight fits easily beat, but sliver-penalized bins do not.
    if bin_residual == bin_capacity {
        // Slightly worse than a good fit, better than a sliver-penalized bin.
        score += 5.0;
        // Late in the stream, opening fresh bins is fine (future demand low).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward;
    // if post_residual is too small for next item, penalize mildly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let waste = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - waste / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Mean-residual coupling: if this bin's post-residual deviates badly from
    // the mean, small nudge toward balanced residual portfolios.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near match: next item fits with small leftover dead space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - leftover / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here: penalize proportionally to how close we came.
        let miss = (next_item_size - post_residual) as f64;
        score += 6.0 * (miss / 100.0);
    }

    // Tight fit reward: small post_residual is good dead space.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize bins whose residual deviates far below the mean (fragmented bins).
    if (bin_residual as f64) < mean_residual {
        score += 0.5 * (mean_residual - bin_residual as f64);
    }

    // Last chance: only one bin can fit this item -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * progress;

    // Discard opening a new bin when a decent fit exists in an open bin.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared dead-space penalty.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 60.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it when the fit is decent,
    // since rejecting it likely opens a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 30 {
            score -= 25.0;
        } else {
            score += 15.0; // poor fit into the only bin: dead space risk
        }
    }

    // Penalize bins whose residual deviates far below the mean residual
    // (they are nearly full; save them unless this is a great fit).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.35;
    } else {
        score += dev * 0.15; // slightly favor emptier bins for big items
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward this placement strongly (chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.25;
        } else {
            // next item won't fit here: prefer leaving larger residuals
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // New-bin candidate handling: opening a fresh bin is attractive when
    // the item fits badly everywhere else. Empty-bin call: post_residual
    // = capacity - item_size; make it competitive for large items and
    // unattractive for small ones (small items should fill gaps).
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill > 0.5 {
            score -= 18.0 * (fill - 0.5) * 2.0; // big items favor new bin
        } else {
            score += 22.0 * (0.5 - fill) * 2.0; // small items avoid new bins
        }
        // Late in the stream, avoid spawning bins that will stay nearly empty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // If other fitting bins exist, new bin needs to beat them clearly.
        if fitting_bins_count > 1 {
            score += 6.0;
        }
    }

    // Prefer consolidating into bins that are already relatively full
    // when many bins are open (reduces bin count pressure).
    if open_bins_count > 4 {
        score += (bin_residual as f64 / bin_capacity as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Tight-fit reward: strongly favor small post residuals (non-linear).
    let tight = 1.0 - (pr / cap).powi(2);
    score -= 22.0 * tight * tight;

    // Dead-space penalty grows with stream progress (waste matters more later).
    let dead = (pr / cap).powi(3);
    score += 18.0 * dead * (0.4 + 0.6 * t);

    // Exact-fill reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a bin when open bins fit, unless residual is large
    // and mean residual is small (poor fit everywhere).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_penalty = 16.0 + 10.0 * (1.0 - t);
        score += fit_penalty;
        if item_size as f64 / cap > 0.7 {
            score -= 20.0; // big items are fine in a fresh bin
        }
        if mean_residual < item_size as f64 {
            score -= 14.0; // nothing else can absorb future items well
        }
    }

    // Lookahead coupling: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 8.0 * (1.0 - ((pr - n) / cap).powi(2));
        } else if pr > 0.0 {
            // penalize leaving a sliver that blocks the next item
            score += 6.0 * (n - pr) / cap;
        }
    }

    // Mild penalty for spreading across many open bins early on.
    score += 0.02 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely desirable, kill residual entirely.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic class bonus: residual on a clean decade class is easier
    // to pack for future items (sizes 10..80 grid).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Dead-space penalty: post residual too small for the lookahead item
    // (and nonzero) is likely wasted space.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 0.3 * next_item_size as f64;
        // extra penalty if it falls into an awkward odd class
        if post_residual % 2 == 1 {
            score += 2.0;
        }
    }

    // New-bin candidate: slight default penalty so we prefer reusing bins,
    // but relax it for large items where a fresh bin is naturally good.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 3.0 - 4.0 * frac;
        // opening a bin when many bins are already open and mean residual
        // is high is wasteful
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score += 4.0;
        }
    }

    // Fuller bins (below mean residual) get priority to consolidate space.
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        } else {
            score += 0.5;
        }
    }

    // Late in the stream, tighten packing: penalize leftover space more.
    let progress = step_index as f64 / total_items as f64;
    score += 2.0 * progress * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the enemy.
    // Any post_residual below the minimum item size (1) can't happen,
    // but gaps in the "hard to fill" band (1..=12) are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 8.0;
    }

    // Reward tight fits: post_residual near zero is excellent.
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 4.0;

    // Exact fit is a jackpot.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit here would create bad dead space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with open bin count pressure.
        score += 30.0 + (open_bins_count as f64) * 2.0;
        // But if mean residual across open bins is small (they're all nearly full),
        // a new bin is genuinely needed.
        if mean_residual < item_size as f64 * 0.75 {
            score -= 45.0;
        }
        // If lookahead item won't fit well anywhere, fresh bin helps.
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 15.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones rather than spreading out.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Slight preference to fill bins with larger residuals early in the stream,
    // keeping tighter bins available for later small items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual > (bin_capacity as f64 * 0.5) as u32 && progress < 0.5 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 500.0; // next item will perfectly fill this bin
        } else if post_residual as i64 == next_item_size as i64 + item_size as i64 {
            score -= 50.0;
        }
        // Penalize post_residual that is too small for the next item (dead space risk),
        // unless it is near zero (already tight).
        if post_residual > 0 && (post_residual as f64) < nxt {
            let dead = (nxt - post_residual as f64) / nxt;
            score += 150.0 * dead;
        }
        // Reward residuals that leave room for next item with slack.
        if post_residual as f64 >= nxt {
            score -= 30.0 * ((post_residual as f64 - nxt) / bin_capacity as f64);
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    let diff = post_residual as f64 - mean_residual;
    score += 0.5 * diff;

    // Last-chance bonus: if this is the only fitting bin, use it rather than open new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: make fresh bins costly unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 400.0 + 0.3 * open_bins_count as f64;
        // But if the item is huge relative to capacity, opening a fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 250.0;
        }
    }

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 200.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where item fills most of the residual.
    let residual_before = bin_residual as f64;
    let fill_ratio = item_size as f64 / residual_before.max(1.0);
    score -= 12.0 * fill_ratio;

    // Penalize large post-residual relative to capacity (dead space), but
    // only if that dead space is unlikely to be reused by the next item.
    let waste = post_residual as f64 / bin_capacity as f64;
    if next_item_size > 0 {
        let next_fits = (next_item_size as u32) <= post_residual;
        if next_fits {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            score += 15.0 * waste;
        }
    } else {
        score += 5.0 * waste;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to typical residuals or open bins are many.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        // Penalize new bins mildly; relax penalty when the item is big.
        score += 20.0 - 10.0 * crowding - 8.0 * (item_size as f64 / bin_capacity as f64) - 5.0 * progress;
        // If next item is huge, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Global state coupling: when mean residual is low, conserve open bins'
    // remaining space more aggressively.
    let mean_gap = (mean_residual - post_residual as f64).abs();
    score += 0.5 * mean_gap;

    // Prefer bins whose residual is already small (consolidate waste).
    score += 0.1 * residual_before;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr;
    score += 40.0 * x * x;             // penalize large leftover space quadratically
    score -= 20.0 * x * x * x;         // smooth cubic coupling
    score += 15.0 * x * x * x * x;

    // Stream progress coupling: later in stream, care more about tight fits
    let progress_scale = 1.0 + 2.0 * t * t;
    score *= progress_scale;

    // Tightness reward: smooth polynomial in fill ratio
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill * (1.0 - t);

    // Last chance bin: strong smooth bonus
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * t;
    }

    // Lookahead: reward if next item fits the post residual (smooth coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0) as f64;
        let fit_frac = nxt / cap;
        score -= 20.0 * fit_frac * (1.0 - fits / cap);
        // penalize if next item cannot fit
        if nxt > pr {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Mean residual coupling: prefer bins deviating from mean smoothly
    score += 5.0 * (pr - mean_residual).abs() / cap;

    // Open bins pressure: more open bins -> prefer filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - x);

    // New bin candidate: make it moderately attractive only for large items / bad fits
    if bin_residual == bin_capacity {
        let waste_if_open = (cap - item_size as f64) / cap;
        score = cap - 30.0 * waste_if_open - 20.0 * (1.0 - x) * t;
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes of capacity
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Penalize residuals in "dead" classes: small but nonzero leftovers (1..=10)
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    }
    // Reward exact fill strongly
    if post_residual == 0 {
        score -= 40.0;
    }

    // Integer division thresholds: post_residual in quarter-capacity classes
    let quarter = (post / (cap / 4.0)).floor();
    score -= quarter * 3.0;

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= post {
            // next item fits: reward proportional to how snugly
            score -= 8.0 + 6.0 * (n / post);
            // harmonic bonus if next item's class matches post_residual class
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 12.0;
            }
        } else {
            // next item won't fit here: penalize wasted potential
            score += 4.0 + 3.0 * (n / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it mildly unattractive unless open bins are congested
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // but if next item is large and current item small, fresh bin is fine
        if next_item_size > 60 && item_size < 30 {
            score -= 20.0;
        }
    }

    // Prefer filling bins below mean residual (tighter bins first)
    score -= 2.0 * (mean_residual - post).clamp(-20.0, 20.0) / 10.0;

    // Stream progression: early on, be greedy for tight fits; later, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post_residual gaps that cannot
    // fit typical future items are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) + 9 {
        score += 500.0; // tiny unusable sliver -> very bad
    }
    // Dead space that cannot fit the lookahead item is worse than one that can.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 40.0 + 0.5 * post_residual as f64;
        } else {
            score -= 15.0; // lookahead fits: reward
        }
        // Perfect chain: post_residual exactly matches next item
        if post_residual == next_item_size {
            score -= 60.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Reward near-exact fills.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading; prefer
    // filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if current bin fit is terrible.
        score += 25.0 + pressure;
        // Opening a new bin is fine if item is large and mean residual is high.
        if item_size as f64 > 0.6 * bin_capacity as f64 && mean_residual < item_size as f64 {
            score -= 90.0;
        }
    } else {
        // Existing bin: mild bonus scaled by how much it beats mean residual.
        score -= 5.0 + (mean_residual - post_residual as f64).max(0.0) * 0.2;
    }

    // Prefer bins whose residual is close to item size (minimal waste).
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score -= 20.0 / (1.0 + waste);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space that no future item (min size 1..10 typical) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: favor bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.5 * next_item_size as f64;
        } else {
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is fine early or when open bins
    // are nearly full on average; penalize when open bins still have slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_slack = mean_residual / (bin_capacity as f64);
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score += 30.0 * avg_slack * pressure - 10.0 * progress;
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 8.0; // room for pairing with lookahead item
        }
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Prefer filling larger-residual bins when many bins are open.
    score += 0.02 * bin_residual as f64 * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Smooth polynomial coupling of post-residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr);

    // Penalize large dead space quadratically as stream advances
    score += 25.0 * norm_pr * norm_pr * progress;

    // Reward tight fits
    score -= 18.0 * norm_item * (1.0 - norm_pr);

    // Last-chance bonus when only this bin fits
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 6.0;
        }
    }

    // Mild penalty for bin proliferation relative to mean residual
    score += 0.4 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // New-bin candidate: prefer it only when current fit is very poor
    if bin_residual == bin_capacity {
        score -= 4.0;
        if norm_item > 0.6 {
            score -= 6.0 * (norm_item - 0.6);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward post_residual in "good" residue classes of 10
    let r = post_residual % 10;
    let harmonic_reward: f64 = match r {
        0 => 12.0, // perfectly reusable residual class
        1 | 2 | 3 => 4.0,
        8 | 9 => 6.0, // nearly full bin, dead space is small
        _ => 0.0,
    };
    score -= harmonic_reward;

    // Penalize mid-range residuals (awkward dead space, 30..60)
    if post_residual >= 30 && post_residual <= 60 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits the post-residual, big bonus
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + (next_item_size as f64) * 0.1;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) * 0.5 + mean_residual * 0.05;
        score += 60.0 - crowded - progress * 10.0;
        // opening a new bin is fine if item would leave bad residue everywhere
        if post_residual == 0 {
            score -= 5.0;
        }
    }

    // Prefer tighter fits overall
    score += (bin_residual - item_size) as f64 * 0.02;

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..100
    // but practically small) can use are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 15.0; // hard to fill
    }

    // Reward tight fits (small waste relative to item size)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 40.0 / (1.0 + tightness);

    // Exact fill is perfect
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open
    score += (open_bins_count as f64).sqrt() * 2.0;

    // Lookahead: if the next item fits exactly in the post residual, reward this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 8.0; // next item cannot use this bin's leftover
        }
    }

    // Prefer bins with residual below the mean (consolidate large gaps)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, discounted late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 75.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count == 1 {
            score += 60.0; // never open when a last-chance bin exists
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 150.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual exactly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 200.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving medium dead space.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    } else {
        // Last item: minimize post residual aggressively.
        score *= 2.0;
    }

    // Compare residual against mean residual of open bins.
    if (post_residual as f64) > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin bonus: if this is the only bin that fits, prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bins are all poor fits (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        // New bin: base score is full capacity; make it attractive only when
        // existing fits would waste a lot.
        score += 60.0;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 50.0; // fresh bin can likely host next item too
        }
        if open_bins_count == 0 {
            score -= 1000.0; // must open a bin
        }
    }

    // Prefer filling bins as stream progresses (encourage closing out bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally to fill ratio of residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item is large and won't fit post-residual, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0;
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: prefer only when current fit is poor and many bins open.
    if bin_residual == bin_capacity {
        let poor_fit = fill_ratio < 0.5;
        if poor_fit && open_bins_count > 2 {
            score -= 10.0;
        } else {
            score += 12.0;
        }
    }

    // Time horizon: early in stream, be less picky (encourage consolidation later).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state: if mean residual is high, favor bins below mean (balance).
    if bin_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    // Penalize opening new bins when many are open.
    score += 1.5 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - (post_residual as f64 / cap); // fraction of bin used after placement
    let tight = item_size as f64 / bin_residual.max(1) as f64; // how well item fills bin

    // Non-linear reward for tight fits (smooth coupling)
    score -= 12.0 * tight.powi(3) * (1.0 + progress);

    // Penalize small unusable dead space non-linearly (dead space < 10 is waste)
    let dead = post_residual as f64;
    if dead > 0.0 {
        score += 40.0 * (-dead / 12.0).exp();
    }

    // Stream progress: later in stream, prefer filling existing bins tightly
    score -= 6.0 * progress * fill.powi(2);

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 8.0 * (next_item_size as f64 / cap);
        } else {
            // penalize leaving residuals that no typical item can use
            score += 3.0 * (1.0 - (post_residual as f64 / cap));
        }
    }

    // New-bin candidate: make it moderately attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (open_bins_count as f64 + 2.0);
        score += 18.0 - 14.0 * crowded - 10.0 * (1.0 - progress);
        // discourage new bin if mean residual is large
        score += 0.15 * mean_residual;
    }

    // Mild penalty for bin count proliferation
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: mod-10 buckets
    let pr = post_residual;
    let class = pr % 10;
    // Dead-space classes: residuals that are hard to fill (1..9 mod 10 but small)
    if pr > 0 && class != 0 {
        // small odd/prime-ish remainders are wasteful
        score += match class {
            1 | 2 | 3 => 6.0,
            4 | 6 | 8 => 3.0,
            5 | 7 | 9 => 4.5,
            _ => 0.0,
        };
    }

    // Perfect fits: exact match (post_residual == 0) is ideal
    if pr == 0 {
        score -= 25.0;
    }

    // Harmonic fraction of capacity: post_residual as fraction of capacity
    let frac = pr as f64 / bin_capacity as f64;
    if frac < 0.05 && pr > 0 {
        score += 8.0; // sliver residual, nearly useless
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            // next item fits but leaves another residual; reward proportional to tightness
            let nxt_post = pr - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; penalize slightly more if this bin would be stranded
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it less attractive
    // unless the item is large or no good fit exists
    if bin_residual == bin_capacity {
        // baseline penalty so open bins win when they fit decently
        score += 15.0;
        if item_size >= bin_capacity / 2 {
            score -= 10.0; // big items are fine in fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing else fits, must open
        }
    }

    // Prefer filling bins with smaller residuals (best-fit flavor via residual term already)
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Slight pressure to consolidate as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (pr as f64 / 10.0);

    // Integer-division threshold on item size: large items want tight bins
    if item_size / 20 >= 3 {
        score += 0.1 * bin_residual as f64; // big item: penalize loose bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps that no realistic item can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let pressure = (open_bins_count as f64 / (1.0 + step_index as f64).max(1.0)) * 5.0;
    score += pressure * (1.0 - fit_ratio);

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 10.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
    }

    // Mild pull toward bins with below-mean residual (consolidate fullness).
    score += 0.1 * (bin_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            score += 15.0 + 0.5 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: strong reward.
        if diff == 0.0 {
            score -= 40.0;
        } else {
            // Gradient reward: closer post_residual to next item => better.
            score -= 30.0 / (1.0 + diff / 10.0);
        }
        // Penalize post_residual that is positive but too small for the next item
        // (dead space that can never be used by the lookahead item).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: simply prefer tightest fit.
        score += 0.0;
    }

    // Relative-to-mean coupling: bins tighter than the mean are better targets.
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= 3.0 * (mean_residual - resid_f).abs() / (mean_residual + 1.0);
    } else {
        score += 2.0 * (resid_f - mean_residual).abs() / (mean_residual + 1.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good open candidates exist,
    // unless the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced when item is big.
        score += 20.0 - 0.15 * item_size as f64;
        // But if lookahead pairs perfectly with a fresh bin, allow it.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            let pair_slack = bin_capacity - item_size - next_item_size;
            score -= 25.0 - 2.0 * pair_slack as f64;
        }
    }

    // Mild late-stream tightening: as stream progresses, prefer tighter fits more.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward tight fits (waste minimization), with quadratic penalty on large leftovers.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score += 0.35 * (post * post) / cap;

    // Lookahead: if the next item fits into post_residual, strongly reward this bin (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.15 * next_item_size as f64;
    }
    // If next item cannot fit here, mildly penalize leaving a mid-sized gap that is hard to reuse.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && post_residual < 10 {
        score += 8.0; // tiny dead space, unusable
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer bins that are already heavily loaded (close the bin out rather than spreading).
    let fill_ratio = (bin_residual as f64) / cap;
    score += 10.0 * fill_ratio;

    // Global state coupling: when many bins are open and mean residual is high,
    // discourage opening new bins; when residuals are fragmented, allow new bins for better fits.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling with open bin count.
        score += 30.0 + 4.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (build a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // If mean residual across open bins is low (all nearly full), a new bin is fine.
        score -= 0.2 * mean_residual;
        // If no open bin fits well (post_residual would be tiny), new bin gets extra cost
        // unless item is large; large items waste less in a fresh bin.
        if post_residual > (bin_capacity / 4) {
            score += 10.0;
        }
    } else {
        // Existing bin: mild reward to keep using it, scaled by how well it absorbs the item.
        let tightness = 1.0 - (post_residual as f64) / cap;
        score -= 6.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Strong reward for tight fits: quadratic in post_residual, scaled by capacity.
    score -= 1.6 * (1.0 - (pr / cap).powi(2)) * cap * 0.35;

    // Perfect fit bonus (near-zero post residual).
    if post_residual == 0 {
        score -= 12.0;
    }

    // Penalize dead space that cannot fit typical future items: post_residual
    // that is small but nonzero is the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead coupling: reward leaving exactly enough room for the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score -= 8.0 * (-gap / 15.0).exp();
        // Penalize residuals that fit next item only wastefully.
        if pr >= nx && pr - nx < 10.0 {
            score -= 4.0;
        }
    }

    // Stream-progress coupling: later in the stream, prefer consolidating into
    // existing bins (opening new bins late wastes capacity).
    let new_bin = (bin_residual as u32 == bin_capacity) as f64;
    let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
    score += new_bin * (10.0 + 25.0 * progress) - new_bin * 12.0 * scarcity;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && new_bin < 0.5 {
        score -= 20.0;
    }

    // Mild pressure to keep open_bins_count low; favor fuller bins overall.
    score += 0.4 * open_bins_count as f64 * (pr / cap);
    score -= 1.5 * (1.0 - pr / mean_residual.max(1.0)).tanh();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: reward post_residuals that are "usable" sizes
    // (multiples of 10, and common small residuals), penalize dead space.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 12.0; // clean harmonic class: likely reusable
        }
        if pr % 5 == 0 && pr % 10 != 0 {
            score -= 4.0;
        }
        // dead space: residual too small for typical items
        if pr < 10 {
            score += 40.0;
        } else if pr < 20 {
            score += 8.0;
        }
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0 + (next_item_size as f64) * 0.1;
        } else {
            // next item won't fit here; penalize more if we wasted a lot
            score += 6.0;
        }
        // harmonic match: next item exactly consumes residual later
        if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate logic: empty bin should lose unless current bins are full-ish
    if bin_residual == bin_capacity {
        let tight = mean_residual / bin_capacity as f64;
        score += 15.0 - 20.0 * tight;
        // open new bin early in stream or when many bins already open and tight
        if open_bins_count > 4 && tight < 0.35 {
            score -= 10.0;
        }
        if step_index as f64 / total_items as f64 > 0.8 {
            score += 10.0; // late stream: prefer filling existing bins
        }
    }

    // Prefer bins tighter than average
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Integer-division threshold: bins whose residual class (res/20) matches item class
    if (bin_residual / 20) == (item_size / 20) {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized,
    // perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0; // perfect fill
    } else if post_residual < 10 {
        score += 60.0;   // dead space: gap too small for any future item
    }

    // Reward tight fits: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating;
    // when few bins are open, allow spreading (slightly favor new bins).
    let open_pressure = open_bins_count as f64 / 20.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins already open, reward early.
        score += 25.0 + 30.0 * open_pressure;
    } else {
        score -= 10.0 * open_pressure;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 20.0; // gap blocks the known next item
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins),
    // spreading load toward emptier bins to balance.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 20.0 * dev;

    // Late in the stream, be more conservative: avoid leftover dead space even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-exact fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward post_residual that exactly matches next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            score -= 40.0; // next item can still fit here
        } else {
            // dead space relative to lookahead item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening new bins when good open bins exist.
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline is its residual (capacity), plus pressure
        // to avoid opening bins early in the stream / with many open bins.
        score += 120.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 30.0; // pairing lookahead with a fresh bin is less useful
        }
    }

    // Late in the stream, close out bins aggressively (avoid leftover spread).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    // Reward near-perfect fills (post_residual small).
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Penalize dead space that no future item can plausibly use:
    // if post_residual is smaller than the smallest plausible item (1..=10),
    // it's likely wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual.max(1) as f64) * 15.0;
        } else {
            // Next item won't fit here; slight penalty for blocking.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
        if post_residual <= 20 {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: empty bin gets a moderate penalty so we prefer
    // reusing open bins unless they fit poorly.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    // Global state: many open bins with high mean residual -> encourage consolidation.
    if open_bins_count > 2 && mean_residual > 30.0 {
        score += (mean_residual - 30.0) * 0.1;
    }

    // Prefer bins whose residual is close to item_size (minimal waste fraction).
    let waste_ratio = (bin_residual - item_size) as f64 / bin_residual.max(1) as f64;
    score += waste_ratio * 25.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with non-linear (quadratic/cubic) coupling
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        + 20.0 * norm_pr * norm_pr * norm_pr * (1.0 + progress);

    // Lookahead: penalize post residuals that can't fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 25.0 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            // reward leaving space exactly usable by the next item
            let slack = pr - nxt;
            score -= 15.0 * (1.0 - (slack / cap).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 * (1.0 - progress);
    }

    // New-bin candidate handling: neutral baseline, slightly penalized early,
    // allowed late when existing residuals are fragmented
    if bin_residual == bin_capacity {
        score = cap * (1.1 - 0.4 * progress)
            + 10.0 * (open_bins_count as f64).ln().max(0.0);
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            score -= 15.0; // open bins too fragmented, new bin is attractive
        }
    } else {
        // Mildly penalize bins far from the mean residual (fragmentation)
        let dev = (pr - mean_residual).abs() / cap;
        score += 8.0 * dev * dev;
    }

    // Tight fit bonus (non-linear)
    let tight = 1.0 - norm_pr;
    score -= 30.0 * tight * tight * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual (capacity fraction classes) ----
    let cap = bin_capacity as f64;
    let post_frac = post_residual as f64 / cap;

    // Class boundaries: residual in (0,10] is near-perfect fill (great),
    // (10,30] medium dead space, (30,50] awkward, >50 half-empty.
    if post_residual == 0 {
        score -= 200.0; // perfect fill: best possible outcome
    } else if post_residual <= 10 {
        score -= 120.0;
    } else if post_residual <= 30 {
        score -= 40.0;
    } else if post_residual <= 50 {
        score -= 10.0;
    }

    // ---- Modulo arithmetic on post_residual: harmonic residue classes ----
    // Residuals divisible by common item granularities (10, 5, 20) are
    // more likely to be filled by future items.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    // Odd, unharmonic residuals are dead-space prone
    if post_residual % 2 == 1 {
        score += 5.0;
    }

    // ---- Lookahead coupling: does next_item_size fit the post residual? ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can chain into this bin: strong reward
            score -= 60.0;
            // Harmonic bonus if next item divides the leftover cleanly
            let left2 = post_residual - next_item_size;
            if left2 == 0 {
                score -= 80.0;
            } else if left2 <= 10 {
                score -= 30.0;
            }
        } else {
            // Next item cannot use the leftover: penalize by how wasteful
            let waste = post_residual as f64 - (next_item_size as f64 % post_residual.max(1) as f64);
            score += 0.3 * waste;
        }
    }

    // ---- Integer-division threshold on item_size (harmonic size classes) ----
    let size_class = item_size / 20; // 0..=4 classes: tiny, small, mid, large, huge
    match size_class {
        0 => score -= 5.0,   // tiny items fit anywhere; keep flexibility
        1 => {}
        2 => {}
        3 => score += 5.0,   // large items: prefer tight fits only
        _ => score += 15.0,  // huge items: only in very roomy bins
    }

    // ---- Last-chance bin logic ----
    if fitting_bins_count == 1 {
        // If this is the only fitting bin, using it avoids opening a new bin
        // UNLESS the residual left would be terrible dead space.
        if post_residual <= 30 {
            score -= 100.0;
        } else {
            score += 25.0; // maybe better to open a fresh bin
        }
    }

    // ---- New-bin candidate handling (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        // A fresh bin has residual 100; baseline score is its post_residual (100 - item).
        // Prefer it only when the item is huge and no open bin fits well,
        // or when the stream is early and we expect many items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size >= 60 {
            score -= 10.0; // big items justify fresh bins
        }
        if progress < 0.3 {
            score -= 5.0; // early stream: opening bins is cheap long-term
        }
        if open_bins_count == 0 {
            score -= 500.0; // must open a bin
        }
        // Penalize opening new bins when many bins are already open and idle
        score += 2.0 * open_bins_count as f64;
        // If mean residual across open bins is large, reuse them instead
        if mean_residual > item_size as f64 * 1.5 {
            score += 40.0;
        }
    }

    // ---- Mean residual coupling: prefer bins near the mean (balanced packing) ----
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // ---- Tightness reward: smaller post_residual relative to capacity ----
    score += 30.0 * post_frac * post_frac; // quadratic penalty on large residuals

    // ---- Small tie-breaker noise grounded in step (deterministic) ----
    score += ((step_index % 7) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Prefer tight fits: reward small positive residuals relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Open-bin pressure: penalize creating more bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if nothing fits well.
        score += open_bins_count as f64 * 3.0;
        if fitting_bins_count > 0 {
            score += 25.0;
        }
        // Slightly favor new bin late in stream if mean residual is small.
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    } else {
        // Reward using existing bins, more when many bins are open.
        score -= open_bins_count as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Mild stream-progression pressure to consolidate early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (post_residual == 0 as u32) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item fits the post-residual,
    // this bin chains two items -> big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 80.0;
            // Bonus proportional to how snugly the next item also fits.
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Penalize leaving a residual that neither fits the next item
            // nor is likely useful (dead space).
            score += 0.3 * post_residual as f64;
        }
    }

    // Compare residual against the mean residual across open bins:
    // prefer consuming bins with large residuals (keep tight bins intact).
    if post_residual as f64 > mean_residual {
        score -= 0.4 * (post_residual as f64 - mean_residual);
    } else {
        score += 0.4 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 120.0 + 0.5 * open_bins_count as f64;
    }

    // Early in the stream, be slightly more willing to open fresh bins
    // for better long-term structure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 60.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual with a superlinear term.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Reward bins whose residual exactly equals the item size (perfect fit).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item can fit into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.1 * next_item_size as f64;
    }
    // If next item is large and post_residual is small-but-nonzero, dead space is likely.
    if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // New-bin candidate handling: only open a new bin when fits are poor
    // (item is large relative to best residual) or late in the stream with many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Baseline penalty for opening a new bin; shrinks if item is big.
        score += 55.0 - 0.4 * item_size as f64 + 10.0 * progress;
        // If many open bins have decent mean residual, discourage new bins.
        score += 0.15 * mean_residual;
    } else {
        // Reward using existing bins slightly more as stream progresses.
        score -= 5.0 * progress;
        // Penalize leaving residuals that are awkward (small, non-zero).
        if post_residual > 0 && post_residual < 10 {
            score += 12.0;
        }
        // Mild penalty when many bins are open (consolidation pressure).
        score += 0.05 * open_bins_count as f64;
    }

    // Coupling: prefer placing large items into bins with small residual (hard-to-fill space).
    score -= 0.2 * (item_size as f64) * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = pr as f64;

    // Quadratic/cubic coupling of post-residual with stream progress:
    // early on, tolerate slack; late in the stream, penalize wasted space harder.
    let progress_coupling = 1.0 + progress * (norm_pr * norm_pr) * 40.0
        + progress * progress * (1.0 - norm_pr) * 10.0;
    score *= progress_coupling;

    // Dead-space penalty: very small post-residuals that can't fit typical items
    // are penalized smoothly via a bump function around mid-range residuals.
    let bump = (norm_pr * std::f64::consts::PI).sin();
    score += bump.abs() * (1.0 - progress) * 8.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // unless post residual is egregious.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr * norm_pr);
    }

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (next_item_size as f64 / cap));
    } else if next_item_size > 0 {
        // smooth penalty growing with mismatch between next item and post residual
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += gap * gap * 20.0;
    }

    // Mean-residual coupling: when average slack is high, prefer consolidating
    // into bins with below-average residual (fill the emptiest usable bins less).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 6.0 - dev * 3.0 * (1.0 - progress);

    // Mild encouragement to reuse open bins vs opening new ones as stream grows.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * norm_pr;

    // New-bin candidate handling: empty bin gets a smooth prior that decays
    // with progress and with how poorly existing bins fit.
    if bin_residual == bin_capacity {
        let fit_pressure = (fitting_bins_count as f64).recip();
        score = score.max(0.0) + cap * 0.35 * (1.0 - progress * 0.5) * (1.0 - fit_pressure * 0.8);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: bins whose residual falls into
    // "nice" modular classes are more reusable for future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward small post_residual (tight fit) with a superlinear bonus.
    score -= 40.0 * (1.0 - pr / cap).powf(3.0);

    // Modular class logic: residual divisible by common item sizes (10,20,25,50)
    // leaves clean partitions -> reward.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        if post_residual % 25 == 0 { score -= 5.0; }
        if post_residual % 50 == 0 { score -= 4.0; }
        // Odd/awkward classes penalized.
        if post_residual % 10 != 0 && post_residual < 10 { score += 12.0; }
        if post_residual % 20 == 1 || post_residual % 20 == 19 { score += 3.0; }
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Dead-space bands: residuals in (0,10) are unusable (min item size 10... but
    // sizes go down to 1, so weight by next item compatibility).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can still host the next item: reward proportionally.
            score -= 6.0 * (next_item_size as f64 / cap);
            // Harmonic bonus if next item exactly divides residual.
            if post_residual % next_item_size == 0 { score -= 10.0; }
        } else {
            // Residual becomes dead space for the lookahead item.
            score += 10.0 * (1.0 - post_residual as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins with large mean residual: prefer consolidation into tight bins,
    // penalize scattering into bins with big residuals.
    if open_bins_count > 3 {
        score += 0.15 * ((bin_residual as f64 - mean_residual).abs());
    }

    // Early in stream: keep bins flexible (moderate residuals fine);
    // late in stream: prefer exact packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.2 * progress;

    // New-bin candidate: neutral-ish baseline, only attractive when current fit is bad.
    if bin_residual == bin_capacity {
        score = cap * 0.75 + 10.0 * (1.0 - item_size as f64 / cap);
        if fitting_bins_count == 0 { score -= 100.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A residual gap that no plausible future item (sizes >= 1, but practically
    // small items are rare) can fill is "dead space". Penalize gaps in the
    // awkward small range super-linearly.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap <= 10.0 {
            // tiny sliver: nearly unusable dead space
            score += 40.0 * (10.0 - gap) / 10.0 + 15.0;
        } else if gap < 25.0 {
            // small awkward gap
            score += 10.0 * (25.0 - gap) / 15.0;
        }
        // perfect fit reward
        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual <= 5 {
            score -= 20.0;
        }
    }

    // --- Tight fit reward: fraction of bin used ---
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill;

    // --- Last-chance bonus: only this bin fits; avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- Open-bin pressure: discourage proliferation of bins ---
    score += 0.8 * open_bins_count as f64;

    // --- Prefer bins with residuals below the mean (consolidate emptier space) ---
    score += 0.3 * (mean_residual - bin_residual as f64);

    // --- Lookahead: if next item fits in post_residual, reward strongly ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && post_residual < 10 {
        score += 12.0; // next item cannot use this sliver
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current item is large
        // (little waste expected) or no real alternative exists.
        let large_item = item_size >= 60;
        let late_stream = (step_index as f64) / (total_items.max(1) as f64) > 0.8;
        if large_item || late_stream {
            score -= 10.0;
        } else {
            score += 30.0; // prefer filling existing bins early/mid stream
        }
        // A fresh bin wastes capacity - item_size; penalize proportionally
        score += 0.5 * (bin_capacity - item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills the post
    // residual, this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Next item fits here afterward: good chaining, scale by tightness.
            let chain_tightness = next_item_size as f64 / post_residual as f64;
            score -= 150.0 * chain_tightness;
        } else {
            // Next item will NOT fit in this bin's post residual: penalize
            // proportionally to how much dead space is stranded.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 60.0 * waste;
        }
    }

    // Compare residual against mean residual across open bins: prefer bins
    // that are already more filled than average (below-mean residual).
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.3 * residual_gap;

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 120.0;
    }

    // Mild preference for using fewer open bins (consolidation pressure),
    // especially late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Penalize leaving large unfillable residuals relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 0.0; // already rewarded above; keep as-is
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor placements that nearly fill the bin.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    } else {
        // Last item: prefer fullest fill.
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mean_fit = item_size as f64 / mean_residual.max(1.0);
        let pressure = mean_fit - 1.0;
        score += 25.0 * (1.0 - pressure.clamp(0.0, 1.5) / 1.5);
        score -= 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // Discourage hoarding many open bins.
        score += (open_bins_count as f64).ln().max(0.0) * 4.0;
    }

    // Mild preference for bins below mean residual (balance load).
    if bin_residual < bin_capacity {
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (1.0 + 2.5 * progress) + 0.8 * norm_pr * (1.0 - progress);

    let mut score = pr + 60.0 * poly;

    // Lookahead: reward residual that can host the next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 12.0 * (ns / cap) * (1.0 - progress);
        } else {
            score += 8.0 * (1.0 - pr / cap) * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when decent open bins exist, especially early.
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - progress) + 5.0 * (open_bins_count as f64).sqrt();
    }

    // Slight preference toward bins tighter than the mean residual.
    score += 4.0 * (mean_residual - bin_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues divisible by common item sizes
    // are reusable dead space; odd/prime residues are risky.
    let pr = post_residual;
    let mut reusable = 0u32;
    for m in [10u32, 20, 25, 50, 100] {
        if m <= pr && pr % m == 0 {
            reusable += 1;
        }
    }
    score -= 8.0 * reusable as f64;

    // Penalize small unusable residues (dead space), modulo thresholds
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr < 20 {
        score += 8.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // great: chain placement possible; reward exact-class matches
            if pr % next_item_size == 0 {
                score -= 15.0;
            } else {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; penalize proportionally to overshoot
            let over = (next_item_size - pr) as f64;
            score += 0.3 * over;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // more attractive late in the stream or when few bins fit
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // if mean residual across open bins is large, prefer reusing them
        score += 0.4 * mean_residual;
    }

    // Mild preference for tighter bins overall (best-fit flavor)
    score += 0.05 * ((bin_residual as f64) - (post_residual as f64)) * 0.0
        + 0.02 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for unusable dead space: gaps too small for the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 5.0;
    }
    // Perfect fit: heavy reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if the next item also fits in the resulting residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't chain here; penalize moderately proportional to wasted potential.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // over opening new ones (penalize the new-bin candidate).
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 3.0;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    } else {
        // Mild penalty proportional to how "loose" this bin's residual is vs the mean,
        // to prefer filling bins that are already well-used.
        score += (bin_residual as f64 - mean_residual).max(0.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here; penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 25.0 * (gap / bin_capacity as f64);
        }
    }

    // Relative-to-mean coupling: tight bins (below mean residual) are precious.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 40.0 * (mean_residual - res_f) / bin_capacity as f64;
    } else {
        score += 20.0 * (res_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin before opening a new one: strong bonus.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Prefer using existing bins over opening new ones as the stream matures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when open bins are all quite full.
        score += 80.0 + 60.0 * (1.0 - progress);
        if mean_residual < 30.0 {
            score -= 50.0;
        }
    } else {
        score -= 10.0 + 20.0 * progress;
    }

    // Penalize large dead space nonlinearly.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Reward tight fits (large fraction of residual consumed)
    let fill_frac = item / bin_residual as f64;
    score -= 25.0 * fill_frac;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 10.0;
    }

    // Penalize small unusable dead space (hard to fill later)
    if post > 0.0 && post < 12.0 {
        score += (12.0 - post) * 0.8;
    }

    // Lookahead: bonus if next item can also fit into resulting residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0;
    }
    // Lookahead: slight penalty if next item would be blocked by this placement
    if next_item_size > 0 && post > 0.0 && (next_item_size as f64) > post {
        score += 2.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Brand-new empty bin candidate
    if bin_residual == bin_capacity {
        score = 45.0 - 20.0 * (item / cap);
        if open_bins_count == 0 {
            score -= 60.0;
        }
        if fitting_bins_count == 0 {
            // No open bin can fit the item: must open a new bin
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            // An existing last-chance bin exists; discourage opening a new one
            score += 15.0;
        }
        // Early in the stream, opening bins is cheaper; later, consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: post-residual, smoothly warped by stream progress.
    let mut score = pr * (1.0 + 0.5 * progress * (pr / cap));

    // Non-linear penalty on dead space: small post-residuals are valuable.
    let tightness = (pr / cap) * (1.0 - pr / cap); // peaks at half-full
    score -= 8.0 * tightness * (1.0 - progress);

    // Reward near-perfect fits with smooth exponential shaping.
    score -= 6.0 * (-pr / (cap * 0.15)).exp() * it / cap;

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    } else {
        score += 1.5 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let nx = next_item_size as f64;
        score -= 4.0 * (nx / cap) * (1.0 - (pr - nx) / cap);
    } else if next_item_size > 0 {
        // Next item won't fit: penalize wasting residual on awkward splits.
        score += 2.0 * (pr / cap) * (1.0 - progress);
    }

    // Divergence from mean residual: prefer bins whose residual matches stream average.
    let dev = (pr - mean_residual).abs() / cap;
    score += 2.0 * dev * dev * cap / 10.0;

    // Slight preference for consolidating into fewer bins as stream ends.
    score += 0.05 * (open_bins_count as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "reusable" classes (multiples of common small sizes) are favored.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -40.0 // perfect fit is always excellent
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr >= 10 && pr <= 30 {
        0.0 // still usable by small items
    } else {
        8.0 // awkward dead space
    };
    score += class_bonus;

    // Dead-space penalty: residuals below the minimum plausible item size.
    if pr > 0 && pr < 10 {
        score += 25.0 + (10 - pr) as f64 * 2.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if it cannot fit anywhere else, reward keeping room.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 10.0;
        } else if next_item_size > bin_residual {
            // next item won't fit this bin regardless; mild neutral shift
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; prefer it
    // only when no open bin offers a good fit (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        let empty_penalty = if post_residual == bin_capacity as u32 - item_size {
            // placing a big item in a fresh bin is fine
            18.0 + item_size as f64 * 0.15
        } else {
            60.0
        };
        // As the stream matures, opening new bins becomes cheaper than
        // fragmenting many partially-filled bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += empty_penalty * (1.0 - 0.5 * progress);
    }

    // Prefer filling bins that are already below-average full (balance residuals)
    // so that mean residual stays high and bins remain usable.
    let deviation = mean_residual - post_residual as f64;
    score += 0.15 * deviation;

    // Mild reward for using bins among many open bins (consolidation).
    score -= (open_bins_count.min(20) as f64) * 0.3;

    // Integer-division threshold on item class: large items (>= half capacity)
    // should go into emptier bins.
    if item_size >= bin_capacity / 2 {
        score += 0.2 * (bin_residual - item_size) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable.
