    // few future items can fill), scaled by how dead the gap is.
    if post_residual > 0 {
        let dead = 20.0_f64.min(post_residual as f64);
        score += (20.0 - dead) * 3.0; // gap of 1..20 => penalty 57..0
        // Extra quadratic penalty for tiny unusable slivers
        if post_residual < 10 {
