        // But if this bin is the only fitting option, new bin is attractive
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // Late in the stream, prefer compacting into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Prefer bins with below-mean residual (more filled bins first)
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Lookahead: if the next item fits exactly in the post_residual, reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if next item would not fit and post_residual is non-trivial
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
