    // Penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        score += 60.0 + (open_bins_count as f64) * 2.0;
        // But allow a new bin if current fit is very poor (large dead space).
        if post_residual > 0 && (post_residual as f64) < 0.15 * (bin_capacity as f64) {
            score -= 250.0;
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (open_bins_count as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
