            score -= 12.0;
        } else if post_residual > next_item_size {
            score -= 3.0;
        } else {
            score += 4.0; // next item won't fit here; mild penalty
        }
    }

    // New-bin candidate handling: opening a new bin is attractive only
    // when existing bins are crowded or the fit is poor.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64).max(1.0).ln() / (1.0 + mean_residual / bin_capacity as f64);
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_bonus = 6.0 * crowded;
        if poor_fit { new_bin_bonus += 5.0; }
        if progress > 0.8 { new_bin_bonus -= 4.0; } // late stream: consolidate
        score -= new_bin_bonus;
    } else {
        // Slight global pressure: more open bins with high mean residual
        // favors reusing existing bins.
        score += (mean_residual / bin_capacity as f64) * 2.0;
    }

    // Prefer filling bins with more of the item relative to residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * fill_ratio.min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer low post_residual (tight fit)
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream, tolerate larger residuals (bins stay flexible);
    // late in the stream, demand tight packing.
    let tightness_weight = 0.5 + 2.5 * progress * progress;
    score += tightness_weight * norm_post * norm_post * cap;

    // Penalize residuals that cannot fit the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size as f64 - post) / cap;
        score += (1.0 + 3.0 * progress) * dead * cap * 0.5;
    }

    // Reward when next item exactly continues to fit (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain = post_residual - next_item_size;
        score -= (chain as f64) * (0.3 + 0.7 * (1.0 - progress));
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Mild penalty when many bins are open and this bin is far above mean residual
    // (prefer balancing residuals early on).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += (1.0 - progress) * dev * dev * cap * 0.25;

    // Slight preference for using existing bins over opening new ones:
    // the new-bin candidate has bin_residual == bin_capacity (norm_post == 1),
    // which the quadratic term already penalizes; add explicit offset scaled
    // by number of open bins.
    if bin_residual == bin_capacity {
        score += 2.0 + 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: small post_residual is good; penalize unusable slivers.
        // A residual is "dead" if smaller than the smallest plausible item (harmonic class 1..=10).
        if post_residual < 10 {
            score += 60.0;
        }
        // Harmonic class of the leftover: leftover divisible by common item classes
        // (items often cluster at multiples of 5/10). Reward leftovers in those classes.
        if post_residual % 10 == 0 {
            score -= 25.0;
        } else if post_residual % 5 == 0 {
            score -= 12.0;
        }
        // Integer-division thresholds: leftover big enough for medium/large future items
        if post_residual >= 80 { score -= 8.0; }
        else if post_residual >= 50 { score -= 4.0; }
        else if post_residual >= 30 { score -= 2.0; }
        else { score += 10.0; } // awkward zone: leftover fits only small items
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 90.0;
        } else if post_residual > next_item_size {
            score -= 15.0;
        } else {
            // next item won't fit here: penalize based on wasted potential
            score += (next_item_size as f64 - post_residual as f64).min(40.0) * 0.5;
        }
        // Harmonic coupling: next item complements leftover into a clean class
        if post_residual >= next_item_size && (post_residual - next_item_size) % 10 == 0 {
            score -= 20.0;
        }
    }

    // Prefer filling bins with low residual relative to the mean (balance pressure)
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: opening a new bin wastes the residual of this bin.
    // Penalize the fresh bin proportionally to how much residual would be stranded,
    // but allow it when open bins are crowded (few fitting bins) or stream is late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (1.0 + fitting_bins_count as f64) };
        // fresh bin cost grows with open bins count and stream progress
        score += 70.0 + 3.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        // but if many bins fit the item, prefer an existing bin (this penalty stands);
        // if only one bin fits, existing-bin bonus above usually wins.
        let _ = crowding;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=10) are nearly unusable
    // for items >= 10, so punish them hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits proportionally: small post_residual relative to capacity.
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(6);

    // Penalize opening a new bin when existing bins fit (pressure on open_bins_count).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + open_bins_count as f64 * 6.0;
        // But if this is the only fitting option, opening a bin is fine.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // Extra reward if next item then fills the bin nearly exactly.
        let after_next = post_residual - next_item_size;
        if after_next <= 5 {
            score -= 15.0;
        }
    }
    // Penalize leaving a gap that exactly blocks the next item (dead space for it).
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 20.0;
    }

    // Slight preference to fill bins with larger residuals as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.5 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chaining
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space relative to next item
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize leaving residual that is small and unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Compare against mean residual: prefer bins with less residual (fuller bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        score += 45.0 - 0.5 * (item_size as f64);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Early in stream, slightly favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but dead space that can't
    // hold a typical item is worse than moderate usable space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item.
        score += 4.0 * (next_item_size as f64 - post_residual as f64) / 20.0;
    }

    // Last chance: if this is the only fitting bin, penalize opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Prefer bins with residual already below mean (consolidate fuller bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Penalize leaving awkward residuals (small but nonzero leftovers).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins would be badly fragmented
    // (high mean residual spread vs item) or early in the stream with few bins.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity - item_size) as f64).abs();
        let mut nb = 25.0 + 0.2 * fragmentation;
        // Early stream: opening bins is cheaper; late stream: prefer filling.
        nb -= 10.0 * (1.0 - progress);
        // If many bins can fit the item, opening a new one is wasteful.
        if fitting_bins_count > 2 {
            nb += 5.0 * (fitting_bins_count as f64 - 2.0);
        }
        score += nb - 25.0; // baseline so empty bin competes fairly
    }

    // Slight time pressure: as stream ends, favor using existing space.
    score -= 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post residual (fraction of capacity wasted after placement)
    let pr = post_residual as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: waste penalty grows super-linearly with progress
    // (dead space late in the stream is more costly since fewer items remain to fill it)
    score += 40.0 * pr * pr * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth cubic discount
    score -= 30.0 * (1.0 - pr).powi(3) * (1.0 + progress);

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 * (1.0 + progress);
    }

    // Penalize opening new bins when many bins are open and mean residual is large
    if bin_residual == bin_capacity {
        score += 25.0 * (open_bins_count as f64).sqrt() * (mean_residual / bin_capacity as f64);
        // Smooth lookahead: prefer new bin if next item fits better in a fresh bin
        let nfit = (bin_capacity as f64 - next_item_size as f64).max(0.0) / bin_capacity as f64;
        score -= 15.0 * nfit * nfit * progress;
    } else {
        // Prefer bins whose residual is close to the mean (balance load smoothly)
        let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
        score += 10.0 * dev * (1.0 - progress);
    }

    // Lookahead coupling: reward leaving residual compatible with next item
    if next_item_size > 0 && bin_residual != bin_capacity {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score += 0.3 * gap * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: residue modulo 10 buckets the
    // "usability" of leftover space for typical small items.
    let residue_class = post_residual % 10;
    score += residue_class as f64 * 0.8;

    // Integer-division thresholds: post_residual >= 50 is half-usable,
    // >= 25 quarter-usable; reward larger usable remainders.
    if post_residual >= bin_capacity / 2 {
        score -= 12.0;
    } else if post_residual >= bin_capacity / 4 {
        score -= 4.0;
    } else if post_residual > 0 {
        score += (bin_capacity / 8 - post_residual.min(bin_capacity / 8)) as f64 * 0.5;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this placement (perfect harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let fit_frac = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 10.0 * fit_frac;
        } else {
            // Next item won't fit here; small penalty scaled by waste class.
            score += 3.0;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins already have slack
    // comparable to the item (fragmentation control).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + open_bins_count as f64 * 2.0;
        if mean_residual >= item_size as f64 {
            score += 10.0;
        }
    } else {
        // Reward tight fits relative to current residual.
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 8.0 * tightness;
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / cap);

    // Mean-residual drift: keep bin residuals balanced across open bins.
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible item (min size 1..10) are dead space. Penalize hard when
    // post_residual falls into the "unusable small gap" band.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits: perfect fill gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // graded bonus proportional to how much of the bin is consumed
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 8.0 * fill_ratio;
    }

    // Penalize leaving a gap that is just slightly larger than the next item
    // wasted opportunity is small, but leaving a gap the next item cannot use
    // is dead space too.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0; // next item can still fit here: good
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5; // next item cannot use this gap
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading into
    // bins with large residuals; prefer consolidating into fuller bins.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += open_pressure * (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Give the empty bin a mild penalty so it loses
    // to any reasonable fit, but wins over badly-dead-space placements.
    if bin_residual == bin_capacity {
        score += 12.0;
        // late in the stream, opening new bins is fine since fewer future
        // opportunities to consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * progress;
    }

    // Slight global pressure to keep total open bins low.
    score += open_bins_count as f64 * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // gap between next item and post residual: smaller gap is better
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to the miss
            let miss = (next_item_size - post_residual) as f64;
            score += 0.5 * miss;
        }
    }

    // Relative to mean residual: prefer bins with below-average residual (tighter bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist, more so early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress);
    }

    // Slight preference to consolidate: fewer open bins -> favor existing crowded bins
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (waste-free placement).
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward tight fits nonlinearly: small post_residual is much better.
        let pr = post_residual as f64;
        score -= (bin_capacity as f64 / (pr + 1.0)).sqrt() * 2.0;
        // Penalize dead space that no plausible future item can use.
        if next_item_size > 0 && next_item_size > post_residual {
            // residual too small for the lookahead: mild penalty unless very small (usable later)
            if post_residual < 10 {
                score += 3.0;
            } else {
                score += (post_residual as f64) * 0.15;
            }
        }
        // Reward residuals that exactly accommodate the lookahead item.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // When several bins fit, prefer the tightest: post_residual already does this,
        // add slight penalty for bins far above mean residual (poor consolidation).
        score += ((bin_residual as f64) - mean_residual).abs() * 0.05;
    }

    // New-bin candidate handling: empty bin gets a baseline that becomes more
    // attractive early (stocking up) and less attractive late (consolidate).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64 + open_bins_count as f64 * 2.0 - progress * 10.0;
        // If nothing open fits, opening a new bin is inevitable: make it cheap.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild global pressure: many open bins -> prefer filling existing ones.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_post * (1.0 + 2.0 * progress * norm_post + 3.0 * progress * progress * (1.0 - norm_post));

    let mut score = poly * cap;

    // Reward tight fits, stronger later in the stream
    let tightness = 1.0 - norm_post;
    score -= tightness * tightness * (1.0 + progress) * 12.0;

    // Penalize being the last fitting bin less if fit is tight (avoid opening bins)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_post);
    }

    // Encourage matching the next item's residual needs
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score += 0.15 * gap * (0.5 + progress);
    }

    // Mild penalty when bin residual deviates from mean residual (balance bins)
    score += 0.05 * (post - mean_residual).abs();

    // Slight preference for reusing existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Best-fit core: reward tight fits non-linearly.
    let fit_frac = (post_residual as f64) / cap_f;
    score += 12.0 * fit_frac * fit_frac;
    if post_residual == 0 {
        score -= 40.0; // perfect closure
    }

    // Harmonic classes: modulo classes on post_residual create "usable residue" buckets.
    // Residuals divisible by 10 are more likely reusable by future items.
    let class = post_residual % 10;
    let class_penalty = match class {
        0 => -8.0,
        1 | 9 => 6.0,
        2 | 8 => 4.0,
        3 | 7 => 2.5,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division thresholds: small post_residual (<10) is dead space.
    if post_residual < 10 {
        score += 10.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - gap / cap_f);
        } else {
            // next item won't fit here; mildly penalize leaving large gaps
            score += 3.0 * fit_frac;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate penalty: prefer existing bins unless they fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin fine when items are large
        }
    }

    // Spread awareness: penalize bins far from mean residual to keep bins balanced.
    let dev = post - mean_residual;
    score += 0.15 * dev.abs();

    // Early stream: be slightly greedier toward tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 4.0 * (1.0 - fit_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that can likely never host a future item is wasted capacity.
    let dead_threshold = 10.0; // minimum plausible item size region
    if (post_residual as f64) < dead_threshold {
        score += 60.0 + (dead_threshold - post_residual as f64) * 8.0;
    } else {
        // Mildly reward leaving a gap that can still fit something.
        score -= 4.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }
    // Many fitting bins: less pressure to fill any particular one; slight penalty
    // to encourage spreading toward best fits elsewhere.
    if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Open-bin pressure: with many open bins, avoid leaving moderately large
    // residuals scattered; consolidate instead of opening new bins.
    let pressure = (open_bins_count as f64 / 10.0).min(3.0);
    score += post_residual as f64 * 0.05 * pressure;

    // New-bin candidate handling: an empty bin should only win when the current
    // item would create a large unusable gap in every existing bin, or when
    // residuals across open bins are already small (well-packed).
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let gap_penalty = if (post_residual as f64) < dead_threshold { 80.0 } else { 0.0 };
        // Base cost of a new bin, discounted when open bins are tightly packed.
        let base = 35.0 + mean_r * 0.6;
        score = base + gap_penalty;
        // Lookahead: if next item is large, a fresh bin may be valuable.
        if next_item_size > 0 && (next_item_size as f64) >= post_residual as f64 + 20.0 {
            score -= 12.0;
        }
    } else {
        // Lookahead synergy: leaving room exactly for the next item is great.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 40.0;
            } else if post_residual >= next_item_size {
                score -= 8.0;
            } else {
                // Next item won't fit here: penalize slightly more with progress.
                let progress = step_index as f64 / total_items.max(1) as f64;
                score += 6.0 * (0.5 + progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills (small post_residual is already favored by base term).
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: strongly favored
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: does the next item fit the post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward when next item fits snugly into the remaining space.
            score -= 150.0 * (1.0 - slack / bin_capacity as f64);
            if slack == 0.0 {
                score -= 300.0; // chain of two perfect fits
            }
        } else {
            // Next item cannot use the leftover; penalize proportional dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.8 * dead;
        }
    }

    // Penalize residual far below mean (wasteful bin usage relative to average).
    score += 0.5 * (mean_residual - post_residual as f64).abs() * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // When many bins can fit the item, prefer tighter fits: add small penalty scaled by alternatives.
    if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New empty bin candidate: only attractive when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; offset if lookahead suggests a big item is coming.
        score = bin_capacity as f64 + 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 80.0;
        }
        if fitting_bins_count == 1 {
            // An open bin exists as last chance; discourage new bin unless this item is huge.
            score += (100 - item_size.min(100)) as f64 * 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 50.0;
    }

    // Lookahead: if the next item can also fit into the post residual,
    // this bin is doubly valuable — reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_waste = post_residual - next_item_size;
        score -= 30.0 + 0.5 * (pair_waste as f64);
    }

    // Last-chance bin: penalize skipping it heavily when it fits decently.
    if fitting_bins_count == 1 {
        score -= 40.0;
        if post_residual <= 20 {
            score -= 30.0;
        }
    }

    // Penalize creating small dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer placing into bins with lower residual relative to the mean
    // (keeps tight bins tight, spreads load evenly).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.3 * residual_gap;

    // Late in the stream: consolidate aggressively, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized later.
        score += 20.0 * progress + 0.05 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0 * (1.0 - progress);
        }
    } else {
        score -= 5.0 * progress;
    }

    // Mild tie-breaker: favor bins with more remaining usable space
    // normalized against capacity.
    score += 0.1 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Non-linear waste penalty: quadratic in post_residual, scaled by progress.
    score += (post / cap).powi(2) * cap * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item).
    score -= (item / cap) * (1.0 - (post / cap)) * 20.0;

    // Penalize bins whose residual deviates from mean residual (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits the post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // Next item cannot follow: penalize leaving awkward gaps.
        score += 5.0 * (post / cap);
    }

    // New-bin candidate: prefer opening new bins early, discourage late when many bins open.
    if bin_residual == bin_capacity {
        score = cap - item * 0.5;
        score += (open_bins_count as f64) * (1.0 + 3.0 * progress);
        if fitting_bins_count <= 1 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space by integer division
    let class = post_residual / 25; // 0..4 harmonic quarter-classes
    score += match class {
        0 => -20.0, // tiny leftover -> excellent fit
        1 => 5.0,
        2 => 12.0,
        3 => 22.0,
        _ => 30.0,
    };

    // Perfect-fill reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Next-item lookahead: does the post_residual admit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chainability bonus, stronger when the leftover closely matches next item
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Leftover too small for next item -> penalize proportionally to wasted space
            score += 8.0 + 0.2 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter fits (post_residual already does this)
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Only attractive if current bin would leave large unusable residue
        // and open bins are numerous (avoid bin explosion early on)
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_penalty = score - post_residual as f64; // accumulated fit-quality terms
        score = bin_capacity as f64 * 0.5
            + waste_penalty * 0.8
            - 10.0 * progress
            + 0.5 * open_bins_count as f64;
        if item_size > 60 {
            score -= 15.0; // big items start fresh bins happily
        }
    }

    // Mild preference for bins below mean residual (balances load)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never host the smallest
    // item (1..=min_item) are pure waste; penalize them super-linearly.
    let min_item = 1.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < min_item * 8.0 {
        // tiny unusable sliver -> large penalty proportional to wasted capacity
        score += (min_item * 8.0 - pr) * 6.0 + 12.0;
    }

    // Reward near-perfect fits (small but still usable leftovers).
    if pr == 0.0 {
        score -= 25.0; // exact fill
    } else if pr <= 10.0 {
        score -= 8.0; // compact residual, still useful
    }

    // Penalize leaving a residual that cannot host the lookahead item
    // (wasted opportunity for a 2-item packing).
    if next_item_size > 0 && pr > 0.0 && (pr as u32) < next_item_size {
        score += 5.0 + (next_item_size as f64 - pr) * 0.3;
    } else if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 4.0; // bin stays useful for the next item
    }

    // Open-bin pressure: discourage spreading across many bins when
    // a decent fit exists; the emptier the bin (large post_residual),
    // the more this matters.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * (pr / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise the item forces a new bin anyway.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): make it attractive only when current
    // open bins would leave awkward gaps or when few bins are open.
    if bin_residual == bin_capacity {
        let awkward = mean_residual < 25.0 && open_bins_count > 0;
        if awkward {
            score -= 20.0; // prefer a fresh bin over poor fits
        } else {
            score += 10.0 + 2.0 * open_bins_count as f64; // keep using open bins
        }
        // scale new-bin appeal with item size (big items start bins better)
        score -= (item_size as f64 - 50.0) * 0.1;
    }

    // Mild alignment with mean residual state: bins deviating far below the
    // mean residual are already tight; prefer filling them further.
    score -= (mean_residual - pr).clamp(-50.0, 50.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 150.0; // chain two perfect placements
        } else if next_item_size as u32 <= post_residual {
            // next item still fits after this placement: mild reward, scaled by closeness
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit: penalize proportionally to wasted potential
            score += 20.0 * (gap / bin_capacity as f64);
        }
    }

    // Penalize residuals that are too small to ever be useful (dead space below min item size 1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual is tight vs fleet average.
    let res = post_residual as f64;
    score += 0.5 * (res - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: make it moderately attractive only when no good fit exists
    // (i.e., current bin would leave large awkward residual).
    if bin_residual == bin_capacity {
        let waste_if_placed_in_open = (bin_residual - item_size) as f64;
        // Base penalty so perfect fits in open bins always win.
        score += 80.0;
        // If placing in an open bin wastes a lot, ease the penalty for opening a new bin.
        if next_item_size > 0 && item_size <= bin_capacity {
            let new_bin_post = bin_capacity - item_size;
            if (new_bin_post as i64 - next_item_size as i64).abs() == 0 {
                score -= 120.0; // opening a fresh bin enables a perfect next fit
            }
        }
        let _ = waste_if_placed_in_open;
    }

    // Early in the stream, allow more bins to spread items (better long-run packing).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 10.0;
    }

    // Slight preference to fill more-occupied bins first (smaller residual before placement).
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    let waste = post_residual as f64;
    score += 0.6 * waste * waste / bin_capacity as f64;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 8.0;
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize bins whose residual deviates far below the mean residual
    // (they are already tight; avoid fragmenting them further).
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.25 * dev;
    }

    // Lookahead: reward leaving a residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space the next item cannot use.
            score += 0.3 * next_item_size as f64;
        }
    }

    // New-bin candidate handling: opening a new bin is attractive only
    // when existing bins fit poorly (large post_residual everywhere).
    if bin_residual == bin_capacity {
        // Cost of a fresh bin, discounted when many bins are open and
        // residual space is fragmented.
        let mut new_bin_score = bin_capacity as f64 * 0.35;
        new_bin_score -= open_bins_count as f64 * 1.5;
        new_bin_score += mean_residual * 0.2;
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64) >= 0 {
            // Fresh bin can host both current and next item.
            new_bin_score -= 15.0;
        }
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score -= 10.0 * progress; // late in stream, consolidation matters less
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Base: wasted space after placement, non-linearly penalized.
    let mut score = pr * (1.0 + 0.6 * pr / cap);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits matter more (dead space is permanent).
    let tightness = 1.0 - pr / cap; // 1 = perfect fit
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Reward near-perfect fits with a smooth cubic bonus.
    let near = (tightness - 1.0).abs();
    score -= 8.0 * (1.0 - near * near * near);

    // Lookahead: strongly favor bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let match_q = 1.0 - gap / cap;
        if match_q > 0.0 {
            score -= 15.0 * match_q * match_q;
        } else {
            score += 3.0 * (-match_q);
        }
    }

    // Last-chance bin: big reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * (1.0 - progress);
    } else if fitting_bins_count > 1 {
        // Mild penalty when many alternatives exist, scaled by fit quality.
        score += 2.0 * ((fitting_bins_count as f64).ln()) * (1.0 - tightness);
    }

    // Prefer bins with residuals below the mean (consolidate small leftovers),
    // as a smooth function of the deviation.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * (1.0 - progress);

    // New-bin candidate: residual == capacity. Penalize opening a new bin,
    // but allow it when the item would leave a very awkward remainder in
    // existing bins (smooth escape hatch via tightness of this placement).
    if (bin_residual as f64 - cap).abs() < 1e-6 {
        let new_pr = pr; // capacity - item_size
        let awkward = 1.0 - (new_pr / cap); // large item -> smaller penalty
        score += 25.0 * awkward * awkward - 10.0 * (1.0 - progress);
    }

    // Mild load-balancing pressure on open-bin count.
    score += 0.05 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Small item-size regularization for stability.
    score += 0.01 * item;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the leftover space: perfect fits (0), tiny slivers (<10),
    // and mid-range residuals are treated differently via integer-division classes.
    let pr = post_residual;
    let class = pr / 10; // 0..=10 harmonic class
    match class {
        0 => score -= 60.0,                       // exact fit: perfect closure
        1 => score += 55.0,                       // 1..9 sliver: nearly dead space
        2 => score += 18.0,                       // 10..19: only smallest items fit
        3 => score += 8.0,
        4 | 5 => score -= 6.0,                    // 30..59: sweet spot for mid items
        6 | 7 => score -= 2.0,
        8 | 9 => score -= 10.0,                   // 80..99: still very usable
        _ => score -= 25.0,                       // full bin candidate (new bin)
    }

    // Modulo-20 arithmetic: residuals congruent to common item sizes are valuable.
    let m = pr % 20;
    if m == 0 { score -= 12.0; }
    else if m >= 15 { score += 6.0; }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if (next_item_size as u32) <= pr {
            let slack = pr - next_item_size;
            score -= 20.0 - (slack as f64) * 0.25; // tight lookahead fit rewarded
            if slack == 0 { score -= 25.0; }        // chain of perfect fits
        } else {
            score += 10.0;                          // lookahead breaks the bin
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so we only open when existing bins are bad,
    // but relax penalty early in the stream when few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 0.3 * mean_residual - 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 15.0; // open bins are all too small for the future too
        }
    }

    // Congestion term: many open bins with large mean residual -> prefer compacting.
    if open_bins_count > 3 && mean_residual > 25.0 {
        score += (mean_residual - post).abs() * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1) can't occur,
    // but residuals too small to be useful for typical items are dead space.
    // Penalize small non-zero post_residual super-linearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 10 {
            score += (10.0 - pr) * 8.0; // tiny gap = dead space
        } else if post_residual < 25 {
            score += (25.0 - pr) * 3.0; // small gap penalty
        }
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly or well into post_residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.3;
        if post_residual == next_item_size {
            score -= 40.0; // chain perfect fit
        }
    } else if next_item_size > post_residual {
        // next item can't use this residual: leftover is likely dead space
        score += (post_residual as f64) * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: prefer denser packing when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.15 + 0.35 * progress);

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first).
    score -= (mean_residual - bin_residual as f64) * 0.2;

    // New-bin candidate: make it attractive only when the item is large relative
    // to capacity or existing fits are poor; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a bin anyway
        } else if size_ratio > 0.6 {
            score -= 10.0 * size_ratio; // large items pack well fresh
        } else {
            score += 55.0; // discourage abandoning open bins for small items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = (item_size as f64) / (bin_capacity as f64);
    score -= tightness * 12.0;

    // Aggressive 2-step lookahead: reward bins whose residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.6;
        // Perfect 2-step chaining bonus
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual too small for typical next item
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    } else {
        // Last item: just minimize post residual
        score -= 10.0;
    }

    // Relative to mean residual: prefer bins with more residual than average
    score += (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize new empty bin unless item is large and fit is poor elsewhere
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size > 70 {
            score -= 15.0;
        }
        // Early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Penalize many open bins slightly (encourage consolidation)
    score += open_bins_count as f64 * 0.3;

    // Dead-space penalty: residuals below 10 are wasted
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a non-linear coupling.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit a plausible future item (next item lookahead).
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
        // Reward bins whose leftover can still host the next item.
        if post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate: penalize opening a new bin when decent fits exist,
    // but relax the penalty late in the stream or when open bins are crowded.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).abs()
        } else { 1.0 };
        let new_bin_penalty = 15.0 - 6.0 * progress - 8.0 * (1.0 - crowding);
        score += new_bin_penalty.max(2.0);
    } else {
        // Favor bins whose residual deviates from the mean in a "fillable" way:
        // prefer bins with residual close to item_size + next_item_size combos.
        let combo = item_size as f64 + next_item_size as f64;
        let dev = (bin_residual as f64 - combo).abs();
        score += 0.05 * dev;
        // Slightly prefer bins below mean residual (consolidating fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 1.5;
        }
    }

    // Mild global pressure: with many open bins, encourage consolidation.
    score += 0.02 * open_bins_count as f64;

    // Small time-horizon modulation: early on, be pickier about tight fits.
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;
    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;
    let mut score = base + 0.6 * coupling;
    // Reward tight fits more strongly as stream progresses
    let tight = 1.0 - norm_pr;
    score -= 8.0 * tight * tight * (0.5 + progress);
    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }
    // Penalize bins that are also the only fit when many bins are open (spread usage)
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }
    // Lookahead: reward leaving space compatible with next item, penalize wasted near-fit space
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            // next item can fit here: reward proportional to how well
            let slack = (pr as f64 - nx) / cap;
            score -= 6.0 * (1.0 - slack) * (0.4 + progress);
        } else {
            // dead space relative to lookahead item
            let dead = (nx - pr as f64) / cap;
            score += 10.0 * dead * dead * cap / cap;
        }
    }
    // New-bin candidate: prefer only when no good fit exists; make it less attractive as residuals shrink
    if bin_residual == bin_capacity {
        let avg_dead = mean_residual / cap;
        score += 12.0 + 10.0 * (1.0 - avg_dead) * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        }
    }
    // Mild penalty for very small unusable residuals (dead space)
    if pr > 0 && pr < 10 {
        score += 6.0 * (1.0 - pr as f64 / 10.0);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: how "usable" is the leftover space? Residuals that are
    // multiples of common item-size classes (e.g. 10, 20, 25, 50) are more
    // likely to be filled by future items.
    let harmonic_bonus = match post_residual {
        0 => 60.0,                       // perfect fit — huge reward
        r if r % 50 == 0 => 30.0,
        r if r % 25 == 0 => 22.0,
        r if r % 20 == 0 => 18.0,
        r if r % 10 == 0 => 12.0,
        r if r % 5 == 0 => 6.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // Dead-space penalty: very small leftovers (< 10, minimum item size) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: reward residuals that can host the next item exactly
    // or as a harmonic class.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            let rem = post_residual - next_item_size;
            let rem_class = match rem {
                0 => 20.0,
                r if r % 25 == 0 => 12.0,
                r if r % 10 == 0 => 8.0,
                _ => 0.0,
            };
            score -= rem_class;
        } else {
            // Next item cannot fit here; penalize proportionally.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: keep it attractive only when open bins would create
    // bad fits; otherwise slightly discourage spreading out.
    if bin_residual == bin_capacity {
        let spread_pressure = mean_residual / bin_capacity as f64;
        score += 15.0 - 20.0 * spread_pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large item then next large item in fresh bin
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Mild stream-progression pressure: consolidate more as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Tie-break noise via deterministic coupling (no RNG).
    score -= ((post_residual as usize).wrapping_mul(2654435761) % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than linearly.
    // A post_residual that no future item (>=1, but practically small items) can use well
    // is waste. Treat gaps below a "useful threshold" as dead space with superlinear cost.
    let dead_threshold = 12.0; // gaps <= 12 are hard to fill with items 10..80; small items 1..9 possible
    if (post_residual as f64) < dead_threshold {
        // superlinear penalty on tiny gaps
        score += (dead_threshold - post_residual as f64).powf(1.8) * 1.5;
    }

    // Reward tight fits: exact or near-exact fills get a strong discount.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a decent fit exists.
    // But if this bin is the LAST chance (fitting_bins_count == 1) and it fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: with many open bins, prefer filling existing ones
    // (especially this candidate) over opening yet another.
    let ob = open_bins_count as f64;
    score += ob * 0.6;

    // Mean-residual coupling: if mean residual across open bins is high, there is slack
    // elsewhere; be pickier about this bin's fit (penalize large post_residual more).
    let pr = post_residual as f64;
    score += (pr - mean_residual).max(0.0) * 0.4;

    // Lookahead (k=2): if the next item can use this bin's post_residual exactly,
    // reward leaving exactly that gap; if post_residual is too small for next item,
    // penalize the dead gap relative to next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 0.5 {
            score -= 30.0; // perfect two-step chain
        } else if pr < nxt && pr > 0.0 {
            // gap is unusable by the next item: extra dead-space penalty scaled by waste
            score += (nxt - pr).min(40.0) * 0.5;
        }
    }

    // New-bin candidate handling: an empty bin has maximal residual. Opening a new bin
    // should only win when existing fits are terrible. Give the empty bin a moderate
    // baseline cost that grows with open_bins_count pressure so it loses against
    // reasonable fits but wins against very poor fits.
    if bin_residual == bin_capacity {
        score += 55.0 + ob * 1.2;
    }

    // Slight preference to pack into bins earlier in the stream (stabilize, close bins early)
    score += (step_index as f64 / total_items.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: perfect if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // exact chain fill: ideal
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how much it consumes
            let consumed = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * consumed;
        } else {
            // next item does not fit: penalize dead space left behind
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    } else {
        // last item: strongly prefer minimal residual
        score += 0.0;
        score -= 20.0 * tightness;
    }

    // Compare residual against mean residual across open bins.
    // Prefer bins with residual below mean (more filled bins first).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty, reduced if item is large and
        // existing residuals are all poor fits.
        let mut base = 45.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            base -= 15.0; // fresh bin chains well with next item
        }
        if post_residual < item_size {
            base += 10.0;
        }
        score += base;
    }

    // Slight late-stream consolidation: fewer open bins favored as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (small dead space).
    if post_residual < 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize dead space scaled by how unusable it is relative to future items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // Dead space that cannot host the next item: penalize more early.
            score += (next_item_size - post_residual) as f64 * (1.5 - progress);
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // Bonus: bin can still host the lookahead item.
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: baseline cost of opening a bin, modulated by state.
    if bin_residual == bin_capacity {
        let mut open_cost = 30.0;
        // With many open bins and high mean residual, prefer reusing space.
        open_cost += open_bins_count as f64 * 2.0;
        open_cost += (mean_residual - post_residual as f64).max(0.0) * 0.3;
        // Late in the stream, waste matters more; opening bins is costlier.
        open_cost += progress * 20.0;
        // If the item perfectly fills a fresh bin, opening is great.
        if item_size >= bin_capacity - 5 {
            open_cost -= 60.0;
        }
        score += open_cost;
    }

    // Mild preference for bins with residual close to item_size (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.1;

    // Slight pull toward bins with residual near the global mean (balance).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Base: prefer tight fits, with a non-linear (quadratic) reward on packing density.
    let mut score = pr - 0.9 * cap * fill * fill;

    // Smooth progress coupling: later in the stream, waste is penalized more steeply.
    let prog_term = progress * progress;
    score += 0.6 * prog_term * pr;

    // Interaction: density reward amplified as stream advances.
    score -= 0.5 * prog_term * cap * fill * fill;

    // Penalize residuals that are too small to be useful later, smoothly via mean residual.
    let useless = (mean_residual - pr).max(0.0) / cap;
    score += 0.4 * useless * useless * cap;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits into the resulting residual, penalize near-misses.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 3.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 0.5 * (nx - pr) / cap;
        }
    }

    // Mild penalty for proliferating bins when this bin is nearly empty.
    if fill < 0.2 {
        score += 2.0 * (0.2 - fill) * cap * 0.1;
    }

    // New-bin candidate bias: keep it competitive only when open bins are fragmented.
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * (mean_residual / cap).min(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space in small residue classes
    // (0..=10) is nearly perfect packing; large residues waste capacity.
    let class = post_residual % 25;
    let class_penalty = match class {
        0 => -30.0,          // perfect fill
        1..=5 => -15.0,      // near-perfect
        6..=10 => 0.0,
        11..=15 => 8.0,      // awkward gap
        16..=20 => 15.0,
        _ => 22.0,           // large unusable remainder
    };
    score += class_penalty;

    // Integer-division threshold: post_residual large enough to host a
    // typical next item is valuable; below half-capacity it is dead weight.
    if post_residual >= 50 {
        score -= 12.0;
    } else if post_residual < 25 {
        score += 10.0;
    }

    // Lookahead coupling: reward residual that exactly accommodates next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 12.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 6.0; // next item can't reuse this bin anyway
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when the item is huge
    // relative to mean residual (poor fits everywhere) or early in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_tightness = item_size as f64 / mean_residual.max(1.0);
        if fitting_bins_count > 0 && fit_tightness < 0.75 {
            score += 40.0 + 30.0 * progress; // prefer existing bins
        } else {
            score -= 15.0; // item too big for typical residuals; fresh bin
        }
    }

    // Mild pressure toward consolidating into fewer bins.
    score -= (open_bins_count.min(20)) as f64 * 0.3;

    // Slight preference for tighter fits as the stream progresses.
    score += (post_residual as f64) * (0.1 + 0.2 * (step_index as f64 / total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero post_residual is unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Reward tight fits relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a bin unless residual is badly fragmented
    // or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score = 55.0 + post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 40.0; // keep using the last-chance bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin helps upcoming larger item
        }
        return score;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into bins
    // with small residuals to close them out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual as f64 <= mean_residual {
        score -= 8.0 + 6.0 * progress;
    } else {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly into this bin's post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled by capacity.
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches
    // (or nearly matches) the next item's size — the bin stays "usable".
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect chain: post_residual == next_item_size => strong reward.
        if post_residual as f64 == nxt {
            score -= 25.0;
        }
        // Penalize post_residual that is unusably small for the next item
        // (dead space: too small to fit next item, wasted).
        if post_residual > 0 && (post_residual as f64) < nxt {
            score += 12.0 * (1.0 - post_residual as f64 / nxt.max(1.0));
        }
    } else {
        // Last item: pure tightness.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative to mean residual: bins with residual near/below mean are
    // "mature"; placing there consolidates waste.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.35 * mean_gap;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless the
    // fit elsewhere is terrible. Encourage keeping new bins for large items.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If item is large relative to capacity, opening fresh is less bad.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // Late in stream, fewer future items => opening new bin cheaper.
        if total_items > 0 {
            score -= 15.0 * (step_index as f64 / total_items as f64);
        }
    }

    // Many open bins: discourage spreading; prefer filling existing bins.
    score += 1.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 12.0;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving awkward residue.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste;
        }
    }

    // Penalize opening new bins when many open bins with slack exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus penalty scaled by open bins.
        score += 8.0 + 4.0 * open_bins_count as f64;
        // But if existing bins are all nearly full, new bin is fine.
        let mean_tight = 1.0 - (mean_residual / bin_capacity as f64);
        score -= 20.0 * mean_tight;
        // Late in stream, prefer filling existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Favor bins with residual below mean (fill the emptier-tail bins first).
        score += 0.05 * (bin_residual as f64 - mean_residual).abs().signum()
            * (bin_residual as f64 - mean_residual).abs().min(30.0);
        // Slight reward for using more-open bins to consolidate.
        score -= 0.3 * open_bins_count as f64;
    }

    // Mild penalty for very large dead space in mid-stream.
    if post_residual > 40 && post_residual < bin_capacity {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;
    score += (1.0 + progress) * (x * x) * cap * 0.35;
    score -= (1.0 - progress) * (x * (1.0 - x)) * cap * 0.25;

    // Tight fit bonus (smooth)
    score -= (1.0 - x).powi(3) * item_size as f64 * 0.6;

    // Prefer conserving bins that can also fit the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    } else if next_item_size > 0 {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Slight penalty when bin residual deviates from mean residual
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    // New-bin candidate: mild penalty so open bins are preferred unless very poor fit
    if bin_residual == bin_capacity {
        score += 8.0 + progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
