pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 10.0;
    } else if post_residual < 10 {
        score -= 3.0;
    }

    // Penalize dead space that no future item can use (items >= 1, min size 1).
    // Small residuals are only useful if a small item may follow; use lookahead.
    if post_residual > 0 {
        let usable = if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            1.0
        } else {
            0.35
        };
        score += 0.5 * (1.0 - usable) * (post_residual as f64).sqrt();
    }

    // Lookahead pairing: if next item fits exactly after this placement, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 1.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        let mean_fit_gap = (mean_residual - item_size as f64).max(0.0);
        // If open bins have plenty of room, prefer them; penalize new bin.
        score += 3.0 + 0.05 * mean_fit_gap;
        // Fewer open bins -> prefer consolidation into open bins less strongly.
        score -= 0.1 * open_bins_count as f64;
        // Early in stream, slightly discourage proliferation of bins.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 2.0 * (1.0 - t);
    } else {
        // Mild preference for bins with less residual among fitting bins (best-fit bias).
        score += 0.02 * bin_residual as f64;
    }

    // Slight preference to keep many bins' residuals balanced around mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: strongly reward tight fits (small post_residual), non-linearly.
    let mut score = pr.powf(1.6);

    // Extra penalty when the leftover is small-but-unusable (dead space),
    // coupled smoothly with stream progress (late stream => waste hurts more).
    let unusable = (pr / cap).powf(2.0);
    score += 40.0 * unusable * (0.5 + 0.5 * progress);

    // Perfect fit bonus (smooth, non-piecewise).
    let perfect = (-pr * 0.5).exp();
    score -= 25.0 * perfect;

    // Lookahead coupling: reward leaving room for the next item.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.15 * gap;
        let fits_next = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 10.0 * fits_next;
    }

    // Last-chance bin: strongly favor using it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening bins, more so early/mid stream
    // and when the item fits well elsewhere; relax slightly late in stream.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 45.0 + 10.0 * open_pressure - 25.0 * progress;
        // If many bins fit the item, opening a new one is clearly worse.
        score += 5.0 * (fitting_bins_count as f64);
        // But if mean residual is large (bins fragmented), a fresh bin is less bad.
        score -= (mean_residual / cap).powf(1.5) * 20.0;
    }

    // Mild preference for bins below mean residual (consolidation), smooth coupling.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues mod 10 (typical item granularity)
    let r = post_residual % 10;
    let harmonic_bonus = match r {
        0 => 30.0,           // round residual: highly reusable
        5 => 15.0,           // half-decade residual still decent
        _ => -(r as f64),    // ragged residual penalized
    };
    score -= harmonic_bonus;

    // Integer-division thresholds on post_residual: big dead space penalty
    if post_residual > 0 && post_residual < 10 {
        score += 80.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 30 {
        score += 10.0;
    }

    // Coupling with next item: reward residuals that can host the lookahead
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.5 * (next_item_size as f64);
            // exact two-item closure: post_residual == next_item_size
            if post_residual == next_item_size {
                score -= 60.0;
            }
        } else {
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize unless current bin fit is terrible
    if bin_residual == bin_capacity {
        score = 60.0 + post_residual as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // big item coming, fresh bin attractive
        }
        if fitting_bins_count == 1 {
            score += 150.0; // don't open new bin when a last-chance bin exists
        }
    }

    // Progress-aware tightness: late in stream, waste hurts more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    // Prefer bins below mean residual (denser bins) for tight packing
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64; // 1..9 residual => heavy penalty
    }
    // Zero residual is perfect packing: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward exact-tight fits relative to bin size (low waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_frac;

    // Dead-space coupling: gap too small for the next item AND below min item size is dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins; but when many bins
    // are open, consolidating (small post_residual) is more valuable.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate: opening a new bin should only win when no decent fit exists.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 55.0;
        // If few bins fit the item, opening new is less bad.
        if fitting_bins_count == 0 {
            score -= 70.0;
        } else if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // If existing mean residual is large (plenty of room around), avoid new bins.
        if mean_residual > item_size as f64 + 15.0 {
            score += 20.0;
        }
    }

    // Mild stream-progression term: later in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - waste_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near-exact match with next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            score -= 18.0 * (1.0 - slack / post.max(1.0));
            // perfect chain bonus
            if slack == 0.0 { score -= 12.0; }
        } else {
            // next item cannot fit here: penalize relative dead space
            score += 6.0 * (1.0 - post / bin_capacity as f64);
        }
    } else {
        // Last item: minimize leftover aggressively.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Reward tight fits overall (small post_residual relative to capacity).
    score -= 4.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Penalize bins with residuals far from mean (fragmentation avoidance),
    // unless it is a new-bin candidate.
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    } else {
        // New empty bin: only attractive when current item is large relative
        // to residuals of open bins or there are no open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = bin_capacity as f64 * (1.0 + 0.3 * progress)
            - 6.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
