        } else {
            // Next item cannot follow here; slight penalty for wasting the slot.
            score += 6.0;
        }
    }

    // Prefer filling bins with large residuals when many bins are open (consolidation).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.3 * residual_gap;

    // Discourage opening new bins early in the stream; more open bins => prefer existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (2.0 - 1.5 * progress);

    // New-bin candidate: only attractive when nothing fits well or bin count is tiny.
    if bin_residual == bin_capacity {
        let desperate = fitting_bins_count == 0
            || (mean_residual < item_size as f64 * 0.6 && open_bins_count > 0);
        if desperate {
            score -= 25.0 + 10.0 * (1.0 - progress);
        } else {
            score += 55.0 + 20.0 * open_bins_count as f64;
        }
    }

    // Mild time-dependent noise-free tiebreak toward later-opened (smaller residual spread).
    score += 0.001 * (step_index as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, smoothed non-linearly
    let mut score = x * x * (2.0 - x);

    // Polynomial coupling of post_residual with stream progress:
    // later in the stream, tighter packing matters more
    let coupling = (x - 0.5) * (x - 0.5) * (0.5 + progress);
    score += 8.0 * coupling;

    // Penalize post residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let dead = 1.0 - (post_residual as f64) / (next_item_size as f64);
        score += 6.0 * dead * (1.0 + progress);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward exact/near fit for the lookahead item
        let tightness = 1.0 - (post_residual as f64 - next_item_size as f64) / cap;
        score -= 4.0 * tightness * tightness * (1.0 - progress);
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Slight preference for bins below mean residual (balance load)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev * (0.5 + progress);

    // Mild penalty for opening a new bin when other bins fit
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64 + 1.0).ln();
        score += 3.0 * pressure * (1.0 - progress * 0.5);
        // Reward opening a new bin if item is huge relative to typical residual
        if (item_size as f64) > mean_residual {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose leftover falls into
    // "small residue" classes are more likely to be closed out usefully later.
    let r = post_residual;
    let class = if r == 0 { 0 } else if r <= 10 { 1 } else if r <= 20 { 2 } else if r <= 30 { 3 } else if r <= 50 { 4 } else { 5 };
    // Reward tight fits (small classes), punish large dead space super-linearly.
    score += match class { 0 => -30.0, 1 => -18.0, 2 => -8.0, 3 => 4.0, 4 => 14.0, _ => 22.0 };

    // Modulo-structure on residual: residues divisible by common item sizes are
    // more reusable. Reward residuals that are "harmonious" with typical sizes.
    let harmonious = (r % 10 == 0) as f64 * 6.0 + (r % 5 == 0) as f64 * 3.0 + (r % 25 == 0) as f64 * 3.0;
    score -= harmonious;

    // Lookahead: strongly reward a bin that can also host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 + slack * 0.15;
    } else if next_item_size > 0 {
        // Penalize creating a residual that just barely misses the next item.
        let miss = (next_item_size - post_residual) as f64;
        score += miss * 0.25;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a new bin is only attractive when current bins
    // would leave large dead space; otherwise penalize spreading out.
    if bin_residual == bin_capacity {
        let waste_elsewhere = mean_residual - item_size as f64;
        if waste_elsewhere > 0.0 {
            score += 10.0 + open_bins_count as f64 * 0.8;
        } else {
            score -= 5.0;
        }
    }

    // Prefer filling bins with lower mean residual (denser packing state).
    score += (mean_residual - post_residual as f64) * 0.1;

    // Slight preference to consolidate into fewer bins early in the stream.
    score += open_bins_count as f64 * 0.3 * (step_index as f64 / total_items.max(1) as f64).min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (1.0 - (post_residual as f64) / 11.0);
    }
    // Medium gaps (11..=30) are also poor: few future items fit them.
    if post_residual > 10 && post_residual <= 30 {
        score += 25.0 * (1.0 - (post_residual as f64 - 10.0) / 21.0);
    }

    // Reward tight fits strongly (post_residual near zero but not dead-space zone).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual >= 31 && post_residual <= 60 {
        score -= 20.0; // flexible gap, good placement
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 50.0;
        } else if slack <= 10 {
            score += 15.0; // next item creates dead space, discourage
        } else {
            score -= 10.0;
        }
    }

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but reward using the last fitting bin (avoid opening a new bin).
    score += (open_bins_count as f64) * 0.8;
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: neutralize base residual so an empty bin scores
    // as a modest constant, only winning when all open bins are bad fits.
    if bin_residual == bin_capacity {
        score = 20.0 + (open_bins_count as f64) * 0.5
            - if fitting_bins_count == 0 { 40.0 } else { 0.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: item + next item perfectly fill the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward near matches: next item can fit into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        // Tighter leftover after hypothetically placing the next item is better.
        let after_next = post_residual - next_item_size;
        score -= 25.0 * (1.0 - after_next as f64 / bin_capacity as f64);
    }

    // Penalize post residuals that are too small to ever be useful again
    // (dead space below the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Penalize wasting a large residual on a small item (poor fill efficiency).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.5 {
        score += (0.5 - fill_ratio) * 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: it should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits are preferred.
        score += 45.0;
        // Soften the penalty when many bins are open (fragmentation risk)
        // or when the mean residual is small (open bins are nearly full).
        score -= (open_bins_count as f64).min(10.0) * 1.5;
        if mean_residual < item_size as f64 + 5.0 {
            score -= 30.0;
        }
        // If next item is large, having a fresh bin may help later.
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // Mild normalization toward mean residual: prefer bins whose remaining
    // space stays close to the average (balanced packing).
    score += 0.1 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements leaving small post residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * tight * 40.0;

    // Reward good fill ratio of the bin.
    let fill = (bin_capacity - bin_residual + item_size) as f64 / bin_capacity as f64;
    score -= fill * 25.0;

    // Lookahead: if next item fits in post_residual, this is a great pairing.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
        // Extra reward if next item nearly fills remaining space.
        let leftover_after_next = post_residual - next_item_size;
        score -= (post_residual as f64 - leftover_after_next as f64) * 0.15;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Post residual becomes dead space relative to lookahead item.
        score += (next_item_size - post_residual) as f64 * 0.10;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize creating small unusable slivers (below min item size 1..100 context).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Time horizon: early on, be more willing to spread items (explore);
    // later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 8.0 - progress * 6.0;

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than opening new ones.
    if open_bins_count > 4 {
        score += mean_residual * 0.05;
    }

    // New-bin candidate: only attractive when current bin fit is poor
    // (post_residual large) — make its baseline moderately high but beatable.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score = 55.0 + poor_fit * 30.0 - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0, 1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling of post_residual with progress:
    // early in stream: prefer moderate residuals (flexibility);
    // late in stream: strongly prefer small residuals (tight packing).
    let progress_weight = 0.35 + 0.65 * progress * progress;
    score += progress_weight * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * bin_capacity as f64 * 0.1;

    // Reward tight fits (small post_residual) with a non-linear bonus
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * tightness * item_size as f64 * 0.5;

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this bin smoothly; otherwise penalize proportionally.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            let slack = (post_residual as f64 - ni) / bin_capacity as f64;
            score -= (1.0 - slack) * ni * 0.3;
        } else {
            let overshoot = (ni - post_residual as f64) / bin_capacity as f64;
            score += overshoot * ni * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good alternatives exist,
    // with smooth dependence on number of open bins and mean residual.
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / bin_capacity as f64) * (1.0 + (open_bins_count as f64).ln().max(0.0));
        score += 15.0 + 20.0 * (1.0 - pressure.min(1.0));
    }

    // Mild preference for bins whose residual deviates from the mean
    // (consolidate similar residuals to keep remaining bins usable).
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += dev * dev * 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post-fit residual (mod-10 classes)
    let class = (post_residual % 10) as f64;
    score += 0.35 * class;

    // Prefer perfect / near-perfect fits
    if post_residual == 0 { score -= 60.0; }
    if post_residual <= 5 && post_residual > 0 { score -= 25.0; }

    // Penalize dead space that no future item (min size 1) can use well
    if post_residual > 0 && post_residual < 10 { score -= 8.0; }

    // Fraction of capacity wasted
    let waste_frac = post_residual as f64 / cap;
    score += 12.0 * waste_frac * waste_frac;

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let tight = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - tight / cap);
        if (post_residual - next_item_size) % 10 == 0 { score -= 10.0; }
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count == 0 { score -= 80.0; }
        if item_size >= 60 { score -= 15.0; }
        // late in stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Prefer fuller bins relative to current mean residual
    score -= 4.0 * (mean_residual - post_residual as f64) / cap;

    // Mild preference to spread across bins when many are open
    score += 0.4 * open_bins_count as f64 * waste_frac;

    // Integer-division threshold: residuals divisible by 25 are reusable
    if post_residual % 25 == 0 && post_residual > 0 { score -= 12.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual matches the next item (chain lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score += gap * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidation;
    // with few open bins, tolerate spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 * 0.15);

    // New-bin candidate: make it attractive only when no good fit exists
    // (i.e., all fits would leave small dead space or item is large).
    if bin_residual == bin_capacity {
        let bad_fit_exists = fitting_bins_count > 0
            && (post_residual == 0
                || (post_residual >= 10 && next_item_size > 0 && post_residual >= next_item_size));
        if bad_fit_exists {
            score += 50.0; // keep using existing bins when fit is decent
        } else {
            score -= 5.0; // opening a new bin beats creating dead space
        }
        // Early in stream, fresh bins are cheap; later, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
    }

    // Slight preference for bins tighter than average residual.
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // 2-step lookahead: reward perfect match between post_residual and next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // exact match bonus
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // penalize leaving residual that next item cannot use but is large
        if next_item_size > post_residual {
            score += 0.3 * post_residual as f64;
        }
    } else {
        // last item: strongly prefer minimal residual
        score += 2.0 * post_residual as f64;
    }

    // Relative to mean residual: bins tighter than average are more valuable to fill
    let rel = post_residual as f64 - mean_residual;
    score += 0.4 * rel;

    // Last-chance bin: strong reward to use it, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive when no good fits exist
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            // penalize opening new bin when alternatives exist, unless current fit is terrible
            if post_residual > 30 {
                score -= 10.0;
            } else {
                score += 60.0;
            }
        }
    }

    // Late in stream: waste less, prefer compacting
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 3 {
        score += 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space: residual too small for the smallest plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
        // Chain fit: post-residual fits next item AND its own successor margin.
        if post_residual >= next_item_size + 10 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += 3.0 * crowd * (1.0 - fit_ratio);

    // Global residual alignment: prefer bins whose residual is close to the mean residual
    // (keeps bin residuals balanced, preserving future placement options).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late-stream consolidation: near the end, avoid opening new bins.
    if progress > 0.7 && bin_residual == bin_capacity {
        score += 40.0 * progress;
    }

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (fitting_bins_count == 1 && fit_ratio < 0.35);
        if poor_fit {
            score -= 45.0;
        } else {
            score += 55.0;
        }
        // Early stream: opening bins is cheap and gives future flexibility.
        if progress < 0.3 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let tightness = 1.0 - post / cap; // how full the bin becomes

    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space is more costly -> amplified post_residual penalty.
    let progress_coupling = post * (1.0 + 2.0 * progress * progress);
    score = progress_coupling;

    // Reward tight fits with a smooth saturating polynomial in tightness.
    score -= cap * (tightness * tightness * (3.0 - 2.0 * tightness)) * 0.6;

    // Penalize leaving residual that is awkwardly mid-range (hard to fill later):
    // smooth non-linear "valley" around half-capacity residuals.
    let r = post / cap;
    let awkward = 4.0 * r * (1.0 - r); // peaks at r=0.5
    score += awkward * cap * 0.35;

    // Lookahead: reward if next item can use the post_residual; penalize otherwise.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            let slack = 1.0 - ((post - next) / cap).abs();
            score -= 8.0 + 12.0 * slack * slack;
        } else {
            let gap = (next - post) / cap;
            score += 4.0 + 10.0 * gap * gap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when it yields a genuinely better fit
    // than a tight existing placement; penalize mildly otherwise.
    if bin_residual == bin_capacity {
        score += 10.0 + 6.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);
        score += 3.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).ln() * 0.5;

    // Small nudge toward bins with residuals close to the current mean (balance).
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into "usable" classes.
    // Class 0: post_residual == 0 (perfect fit) -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Integer-division thresholds: small residuals (<10) are nearly dead space.
        let pr = post_residual;
        if pr < 10 {
            score += 25.0; // dead space penalty
        } else {
            // Harmonic classes via division: 10-19, 20-29, ... larger class = more reusable
            let class = pr / 10;
            score -= class as f64 * 4.0;

            // Lookahead: does next item fit in the post-residual? (harmonic match)
            if next_item_size > 0 && next_item_size <= pr {
                score -= 18.0;
                // Extra reward if next item nearly fills it (class match on sum)
                if pr - next_item_size < 10 {
                    score -= 12.0;
                }
            } else if next_item_size > 0 {
                // next item won't fit here after placement
                score += 6.0;
            }
        }
    }

    // Last chance: only one bin fits -> strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so it loses
    // unless no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Penalize opening new bins when many bins are already open and mean residual is high.
        score += 30.0 + 0.05 * open_bins_count as f64 + mean_residual * 0.1;

        // Late in the stream, opening new bins is cheaper to penalize less (fewer future synergies).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
    } else {
        // Favor tighter bins: closeness of fit (item_size / bin_residual).
        let tightness = item_size as f64 / bin_residual.max(1) as f64;
        score -= 20.0 * tightness;

        // Prefer bins whose residual is below mean residual (already well-packed).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize small non-zero gaps super-linearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 10 {
            score += (10.0 - pr) * 8.0; // unusable sliver penalty
        }
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Reward leaving a gap that the lookahead item can exactly fill (k=2 chaining).
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 45.0;
        } else if gap > 0 && gap < 10 {
            score += 12.0; // creates a new sliver for the next item
        } else if gap < 0 {
            score += 6.0; // next item won't fit here afterwards
        }
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * tightness;

    // Deviation from mean residual: prefer bins whose residual is close to item
    // size (best-fit flavor) to preserve large residuals elsewhere.
    let dev = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * dev;

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // opening a new bin is cheap so slightly favor filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + 12.0 * (1.0 - progress));
    score += 3.0 * pressure;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well; make the empty-bin baseline moderately high but
    // beatable by any decent fit, and lower it when open bins are scarce.
    if bin_residual == bin_capacity {
        score = 55.0 + 4.0 * pressure - 20.0 * (1.0 - (open_bins_count as f64 / 10.0).min(1.0));
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // stacking large items together in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score += diff as f64 * 1.5;
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Penalize post_residuals too small to fit the next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Penalize small unusable post_residuals relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Deviation from mean residual: prefer bins that reduce spread
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are poor
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if no good fit exists (large dead space would be created elsewhere), allow it
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 30.0;
        }
    }

    // Early in stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / (bin_capacity as f64));
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty scaled by how much it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.15 * miss;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // When many bins fit, prefer the one that preserves global flexibility.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Global state: penalize placements that push bin residual far below mean residual
    // (creating outlier bins), reward keeping residuals balanced.
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev.abs();

    // Time horizon: early in stream, be pickier (penalize mediocre fits);
    // late in stream, just close bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.3 * progress;

    // New-bin candidate handling: an empty bin is only attractive when no good
    // fit exists or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count == 0 {
            1.0
        } else {
            1.0 - mean_residual / (bin_capacity as f64)
        };
        // Good fits in existing bins should beat opening a new bin.
        score = (bin_capacity as f64) - 5.0
            - 30.0 * open_pressure
            - 20.0 * (fitting_bins_count == 0) as i32 as f64;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize quantities
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let pr_norm = pr / cap;                 // post-residual as fraction of capacity
    let item_frac = item_size as f64 / cap;
    let next_frac = next_item_size as f64 / cap;

    // Non-linear polynomial coupling: reward tight fits quadratically,
    // weighted by stream progress (tight packing matters more later).
    let tightness = 1.0 - pr_norm;          // 1 = perfect fill
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space: cubic in post_residual, scaled by mean residual context
    score += 0.9 * pr_norm * pr_norm * pr_norm * (1.0 + mean_residual / cap);

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward leaving residual that can host the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if next_item_size as f64 <= pr {
            score -= 8.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        } else {
            score += 5.0 * (next_frac - pr_norm);
        }
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.35 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: penalize proportionally to how full the item leaves it
    if bin_residual == bin_capacity {
        score += 18.0 + 20.0 * item_frac * (1.0 - progress);
        // Allow opening a new bin late in the stream when item is large
        score -= 15.0 * progress * item_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "reusable" classes (likely matchable by future items), penalize
    // tiny unusable slivers.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: best possible outcome
    } else if pr < 10 {
        // dead space sliver: unlikely any item (>=1..100 unknown, but small
        // residuals waste capacity) — strongly penalize
        score += 45.0;
    } else {
        // class by integer division into decile buckets; lower buckets
        // (small leftover) are progressively better
        let class = pr / 10; // 1..=10 harmonic class
        score -= (11 - class as i32) as f64 * 2.0;
        // reward residuals that are exact multiples of common item sizes
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 50 == 0 { score -= 5.0; }
    }

    // Lookahead coupling: if the next item exactly fills post_residual,
    // this is a chain fit — big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size <= pr {
            let npr = pr - next_item_size;
            if npr < 10 { score += 12.0; } // chains into dead space
            else { score -= (npr as f64).min(30.0) * 0.4; }
        }
        // if next item cannot use this residual, mild penalty for hoarding space
        if next_item_size > pr {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current fits are bad. Make the empty bin moderately unattractive by
    // default; it wins only if all real bins score high (bad fits).
    if bin_residual == bin_capacity {
        score += 20.0;
        // but if many bins are open and mean residual is large, new bin is fine
        score -= (open_bins_count as f64).min(10.0) * 1.5;
        // lookahead: if next item is large, a fresh bin is more valuable
        if next_item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Prefer filling bins below mean residual (tighter packing than average)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight preference to keep number of open bins small as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5 * (1.0 - progress);

    // Small tie-break: prefer bins with less residual before placement
    score -= bin_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are unusable.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit: no dead space at all
    } else if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0; // small unusable gap penalty
    } else if post_residual < 20 {
        score += 15.0; // moderately wasteful
    } else if post_residual == bin_capacity {
        // New-bin candidate: mild baseline so it only wins when fits are bad.
        score += 25.0;
    }

    // Reward tight fits relative to bin capacity.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * tightness;

    // Reward bins whose residual is close to item_size (near-exact fill).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.5 * gap;

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_tight = (post_residual - next_item_size) as f64;
        if next_tight < 10.0 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 20.0; // dead space blocks the next item too
    }

    // Open-bin pressure: prefer consolidating into fewer bins when many are open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Mean residual coupling: bins far below mean residual are already fragmented.
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    } else {
        score -= 3.0;
    }

    // Progress pressure: later in the stream, discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit for the next item: strongly reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits in the residual left behind: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space relative to the lookahead item: penalize.
        let wasted = (next_item_size - post_residual) as f64;
        score += 0.5 * wasted;
    }

    // Reward small residuals (tight packing) non-linearly.
    score -= 10.0 * (-post_residual as f64 / 20.0).exp();

    // Compare against mean residual across open bins.
    if mean_residual > 0.0 {
        let ratio = post_residual as f64 / mean_residual;
        score += 8.0 * (ratio - 1.0);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or too many bins are already open.
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size > 0 && post_residual >= next_item_size;
        let _ = good_fit_exists;
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = bin_capacity as f64 - 20.0 * pressure + 5.0 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score += 40.0; // never open a new bin when a last-chance bin exists
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host the pair
        }
    }

    // Mild stream-progression bias toward consolidating early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}
